        const Index* index_;
        Phase phase_;
        WarmAssets work_;
        std::vector<uint8_t> blueprint_, input_;
        std::vector<uint32_t> texture_ids_;
        ResourceRecord record_;
        Sha256 hash_;
        uint32_t image_, fixed_, reloc_, fixed_reloc_, texture_count_, texture_scan_, texture_at_, animation_at_;
        uint32_t current_blob_, reloc_at_, reloc_count_, reloc_previous_;
        uint32_t channel_, run_left_;uint8_t run_value_;
