            for (uint32_t i = 0;i < 12;++i) { const uint8_t* p = blueprint_.data() + 64 + size_t(texture_count_) * 16 + size_t(i) * 24;expected += uint64_t(u32(p + 4)) * u32(p + 8); }
            if (expected > MemoryLimit)return fail(why, "Images/animations and retained actor exceed 32 MiB budget");
            work_.images.reserve(2);work_.animations.reserve(12);work_.textures.reserve(texture_count_);texture_ids_.reserve(texture_count_);
