#ifndef RAYMAN2_NATIVE_ARENA_HPP
#define RAYMAN2_NATIVE_ARENA_HPP
// Private aligned SNA payloads. Binding requests stay null until a typed constructor handles them.
#include <memory>
namespace r2bank {
    inline void put32(uint8_t* p, uint32_t v) { for (unsigned i = 0;i < 4;++i)p[i] = uint8_t(v >> (8 * i)); }
    struct NativeRegion { uint32_t blob, offset, bytes, at, residue; };
    struct NativeMetadataRelocation { uint32_t blob, field, target, offset, binding; };
    class NativeArena {
    public:
        using Allocate = uint8_t * (*)(void*, size_t);
        using Release = void(*)(void*, uint8_t*, size_t);
    private:
        uint8_t* memory_;size_t bytes_;void* context_;Release release_;
        std::vector<NativeRegion> regions_;
        std::vector<NativeMetadataRelocation> metadata_;
    public:
        static const size_t MaxMetadata = 4096;
        uint64_t patched, skipped, scratch, engine;
        NativeArena() :memory_(nullptr), bytes_(0), context_(nullptr), release_(nullptr), patched(0), skipped(0), scratch(0), engine(0) {}
        ~NativeArena() { clear(); }
        NativeArena(const NativeArena&) = delete;NativeArena& operator=(const NativeArena&) = delete;
        NativeArena(NativeArena&& other) noexcept :NativeArena() { swap(other); }
        NativeArena& operator=(NativeArena&& other) noexcept { if (this != &other) { clear();swap(other); }return *this; }
        void swap(NativeArena& o) noexcept {
            std::swap(memory_, o.memory_);std::swap(bytes_, o.bytes_);std::swap(context_, o.context_);std::swap(release_, o.release_);regions_.swap(o.regions_);metadata_.swap(o.metadata_);
            std::swap(patched, o.patched);std::swap(skipped, o.skipped);std::swap(scratch, o.scratch);std::swap(engine, o.engine);
        }
        void clear() { if (memory_ && release_)release_(context_, memory_, bytes_);memory_ = nullptr;bytes_ = 0;regions_.clear();std::vector<NativeMetadataRelocation>().swap(metadata_);patched = skipped = scratch = engine = 0; }
        size_t bytes()const { return bytes_; }
        size_t metadata_bytes()const { return metadata_.capacity() * sizeof(NativeMetadataRelocation); }
        size_t metadata_count()const { return metadata_.size(); }
        bool remember_metadata(uint32_t blob, uint32_t field, uint32_t target, uint32_t offset, uint32_t binding) {
            if (metadata_.size() == MaxMetadata)return false;
            metadata_.push_back(NativeMetadataRelocation{ blob,field,target,offset,binding });return true;
        }
        const NativeMetadataRelocation* metadata(uint32_t blob, uint32_t field)const {
            for (const auto& r : metadata_)if (r.blob == blob && r.field == field)return &r;return nullptr;
        }
        const std::vector<NativeRegion>& regions()const { return regions_; }
        uint8_t* pointer(uint32_t blob, uint32_t offset, size_t n = 1)const {
            for (const auto& r : regions_)if (r.blob == blob && offset >= r.offset && range(offset - r.offset, n, r.bytes))return memory_ + r.at + offset - r.offset;
            return nullptr;
        }
        uint8_t* pointer(uint64_t ref, size_t n = 1)const { return ref == NoRef ? nullptr : pointer(uint32_t(ref >> 32), uint32_t(ref), n); }
        bool contains(const void* p, size_t n = 1)const {
            const uintptr_t address = reinterpret_cast<uintptr_t>(p), base = reinterpret_cast<uintptr_t>(memory_);
            if (!memory_ || address < base || !range(address - base, n, bytes_))return false;
            for (const auto& r : regions_)if (address >= base + r.at && range(address - base - r.at, n, r.bytes))return true;return false;
        }
        uint8_t* linked(const uint8_t* owner, size_t field, size_t n = 1)const {
            if (!contains(owner, field + 4))return nullptr;auto* p = reinterpret_cast<uint8_t*>(uintptr_t(u32(owner + field)));return contains(p, n) ? p : nullptr;
        }
        bool aligned(const void* p, size_t n, size_t alignment = 4)const { return contains(p, n) && (reinterpret_cast<uintptr_t>(p) & (alignment - 1)) == 0; }
        bool allocate(const Index& index, const WarmAssets& warm, uint64_t retained, Allocate allocate, Release release, void* context, std::string& why) {
            clear();uint64_t total = 0;
            for (const auto& image : warm.images) {
                const auto* layout = native_layout(image.blob);ResourceRecord record;
                if (!layout || !index.resource(image.blob, record) || record.size != layout->bytes || image.bytes.size() != layout->bytes || std::memcmp(record.digest, layout->digest, 32)) {
                    why = "Native layout does not match this verified bank image";return false;
                }
                for (uint32_t i = 0;i < layout->count;++i) {
                    const auto& block = NativeBlocks[layout->first + i];
                    if (!range(block.offset, block.bytes, image.bytes.size()) || !block.bytes || block.residue > 15) { why = "Invalid native payload layout";return false; }
                    total = ((total + 15) & ~uint64_t(15)) + block.residue;
                    if (total + block.bytes > 32ull * 1024 * 1024 || retained + total + block.bytes + MaxMetadata * sizeof(NativeMetadataRelocation) + 4096 > 32ull * 1024 * 1024) { why = "Native arena exceeds the 32 MiB resource budget";return false; }
                    regions_.push_back(NativeRegion{ image.blob,block.offset,block.bytes,uint32_t(total),block.residue });total += block.bytes;
                }
            }
            if (!total || !allocate || !release) { why = "Native arena allocation is unavailable";return false; }
            metadata_.reserve(MaxMetadata);
            memory_ = allocate(context, size_t(total));bytes_ = size_t(total);context_ = context;release_ = release;
            const uintptr_t base = reinterpret_cast<uintptr_t>(memory_);
            if (!memory_) { bytes_ = 0;why = "Could not allocate private native payloads";return false; }
            if ((base & 15) || base > UINT32_MAX || total > UINT32_MAX - base) { clear();why = "Native resources require aligned 32-bit process addresses";return false; }
            return true;
        }
    };

    class NativeJob {
    public:
        enum Phase { Idle, Copy, RelocationRead, RelocationApply, Complete };
        static const size_t ChunkBytes = 64 * 1024, Entries = 2048;
    private:
        const Index* index_;const WarmAssets* warm_;NativeArena arena_;std::vector<uint8_t> table_;
        std::vector<uint32_t> image_ids_, reloc_ids_;
        Phase phase_;size_t region_, position_, image_, entry_;uint64_t retained_, io_bytes_;ResourceRecord record_;Sha256 hash_;
        const Image* image(uint32_t id)const { for (const auto& v : warm_->images)if (v.blob == id)return &v;return nullptr; }
        bool fail(std::string& why, const char* message) { why = message;return false; }
    public:
        NativeJob() :index_(nullptr), warm_(nullptr), phase_(Idle), region_(0), position_(0), image_(0), entry_(0), retained_(0), io_bytes_(0) {}
        void cancel() { arena_.clear();std::vector<uint8_t>().swap(table_);image_ids_.clear();reloc_ids_.clear();phase_ = Idle;index_ = nullptr;warm_ = nullptr;region_ = position_ = image_ = entry_ = 0;retained_ = io_bytes_ = 0; }
        bool loading()const { return phase_ != Idle && phase_ != Complete; }
        Phase phase()const { return phase_; }
    static const char* name(Phase p) { switch (p) { case Idle:return "IDLE";case Copy:return "ALIGNED_COPY";case RelocationRead:return "RELOCATION_READ";case RelocationApply:return "RELOCATION_APPLY";case Complete:return "COMPLETE"; }return "INVALID"; }
                                                             uint64_t io_bytes()const { return io_bytes_; }
                                                             size_t position()const { return position_; }
                                                             size_t bytes()const { return arena_.bytes(); }
                                                             uint64_t charged()const { return retained_ + arena_.bytes() + arena_.metadata_bytes() + table_.capacity() + 4096; }
                                                             const NativeArena& arena()const { return arena_; }
                                                             bool begin(const Index& index, const WarmAssets& warm, const std::vector<uint8_t>& bp, uint64_t retained, NativeArena::Allocate allocate, NativeArena::Release release, void* context, std::string& why) {
                                                                 cancel();if (warm.actor.id == None || !index.blueprint(warm.actor, bp.data(), bp.size(), why))return false;
                                                                 if (!arena_.allocate(index, warm, retained, allocate, release, context, why)) { cancel();return false; }
                                                                 index_ = &index;warm_ = &warm;retained_ = retained;
                                                                 image_ids_.push_back(u32(bp.data() + 24));reloc_ids_.push_back(u32(bp.data() + 28));
                                                                 if (u32(bp.data() + 16) != u32(bp.data() + 24)) { image_ids_.push_back(u32(bp.data() + 16));reloc_ids_.push_back(u32(bp.data() + 20)); }
                                                                 phase_ = Copy;return true;
                                                             }
                                                             bool step(WarmJob::Read read, void* context, std::string& why) {
                                                                 if (!loading())return phase_ == Complete;
                                                                 if (phase_ == Copy) {
                                                                     const auto& region = arena_.regions()[region_];const auto* src = image(region.blob);if (!src)return fail(why, "Native copy source is missing");
                                                                     const size_t n = (std::min)(size_t(ChunkBytes), size_t(region.bytes) - position_);
                                                                     std::memcpy(arena_.pointer(region.blob, region.offset + uint32_t(position_), n), src->bytes.data() + region.offset + position_, n);position_ += n;
                                                                     if (position_ == region.bytes) { position_ = 0;if (++region_ == arena_.regions().size())phase_ = RelocationRead; }
                                                                     return true;
                                                                 }
                                                                 if (phase_ == RelocationRead) {
                                                                     if (table_.empty()) {
                                                                         if (!index_->resource(reloc_ids_[image_], record_) || record_.kind != 2 || record_.size < 16 || record_.size>32 * 1024 * 1024 || charged() + record_.size > 32ull * 1024 * 1024)return fail(why, "Native relocation table exceeds resource budget");
                                                                         table_.reserve(size_t(record_.size));hash_ = Sha256();position_ = 0;
                                                                     }
                                                                     const size_t n = (std::min)(size_t(ChunkBytes), size_t(record_.size) - position_);table_.resize(position_ + n);
                                                                     if (!read || !read(context, record_.offset + position_, table_.data() + position_, n, why))return false;
                                                                     hash_.update(table_.data() + position_, n);position_ += n;io_bytes_ += n;
                                                                     if (position_ == record_.size) {
                                                                         uint8_t digest[32];hash_.finish(digest);
                                                                         if (std::memcmp(digest, record_.digest, 32) || std::memcmp(table_.data(), "R2RELOC1", 8) || u32(table_.data() + 12) || uint64_t(u32(table_.data() + 8)) * 16 + 16 != table_.size())return fail(why, "Native relocation SHA-256/header mismatch");
                                                                         entry_ = 0;phase_ = RelocationApply;
                                                                     }
                                                                     return true;
                                                                 }
                                                                 if (phase_ == RelocationApply) {
                                                                     const uint32_t id = image_ids_[image_];const auto* original = image(id);const size_t count = u32(table_.data() + 8), end = (std::min)(count, entry_ + size_t(Entries));
                                                                     for (;entry_ < end;++entry_) {
                                                                         const uint8_t* p = table_.data() + 16 + entry_ * 16;const uint32_t field = u32(p), target = u32(p + 4), offset = u32(p + 8), binding = u32(p + 12);
                                                                         if (!range(field, 4, original->bytes.size()) || u32(original->bytes.data() + field) || (entry_ && field <= u32(p - 16)))return fail(why, "Invalid native relocation source");
                                                                         uint8_t* src = arena_.pointer(id, field, 4);if (!src) { if (!arena_.remember_metadata(id, field, target, offset, binding))return fail(why, "Native typed metadata limit exceeded");++arena_.skipped;continue; }
                                                                         uint32_t value = 0;
                                                                         if (target == None) { if (offset || binding)return fail(why, "Invalid null native relocation"); }
                                                                         else if (target == ScratchBinding) { if ((binding >> 8) != 10)return fail(why, "Unsupported native scratch binding");++arena_.scratch; }
                                                                         else if (target == EngineBinding) { if ((binding >> 8) != 17)return fail(why, "Unsupported native engine binding");++arena_.engine; }
                                                                         else { uint8_t* dst = arena_.pointer(target, offset);if (!dst || binding || (target != id && target != image_ids_[0]))return fail(why, "Native relocation points outside private payloads");value = uint32_t(reinterpret_cast<uintptr_t>(dst)); }
                                                                         put32(src, value);++arena_.patched;
                                                                     }
                                                                     if (entry_ == count) { std::vector<uint8_t>().swap(table_);position_ = 0;if (++image_ == image_ids_.size())phase_ = Complete;else phase_ = RelocationRead; }
                                                                     return true;
                                                                 }
                                                                 return fail(why, "Unsupported native preparation phase");
                                                             }
                                                             bool publish(NativeArena& out) { if (phase_ != Complete)return false;out = std::move(arena_);cancel();return true; }
    };
} // namespace r2bank
#endif

#ifndef RAYMAN2_NATIVE_SOURCE_HPP
#define RAYMAN2_NATIVE_SOURCE_HPP
namespace r2bank {
    struct NativeSource {
        uint8_t* actor, * data, * standard, * family, * state, * animation, * objects, * brain, * mind, * model, * intel, * reflex, * dsg, * vars, * infos, * default_buffer, * initial_buffer, * current_buffer, * dynamics;
        uint32_t channels, dsg_bytes, variables, intelligence_count, reflex_count;
        NativeSource() :actor(nullptr), data(nullptr), standard(nullptr), family(nullptr), state(nullptr), animation(nullptr), objects(nullptr), brain(nullptr), mind(nullptr), model(nullptr), intel(nullptr), reflex(nullptr), dsg(nullptr), vars(nullptr), infos(nullptr), default_buffer(nullptr), initial_buffer(nullptr), current_buffer(nullptr), dynamics(nullptr), channels(0), dsg_bytes(0), variables(0), intelligence_count(0), reflex_count(0) {}
        bool read(const NativeArena& a, const Actor& definition, std::string& why) {
            auto fail = [&](const char* s) {why = s;return false;};
            actor = a.pointer(definition.actor_ref, 56);if (!a.aligned(actor, 56))return fail("Actor root is not a private aligned native record");
            data = a.linked(actor, 0, 280);standard = a.linked(actor, 4, 52);brain = a.linked(actor, 12, 12);dynamics = a.linked(actor, 8, 12);
            if (!a.aligned(data, 280) || !a.aligned(standard, 52) || !a.aligned(brain, 12) || !a.aligned(dynamics, 12))return fail("A required actor module is unavailable");
            family = a.linked(data, 20, 56);state = a.linked(data, 0, 44);objects = a.linked(data, 12, 16);
            if (!a.aligned(family, 56) || !a.aligned(state, 44) || !a.aligned(objects, 16) || family != a.pointer(definition.family_ref, 56) || state != a.pointer(definition.state_ref, 44))return fail("Native family/state identity does not match the bank");
            animation = a.linked(state, 4, 28);channels = u32(family + 48);
            if (!a.aligned(animation, 28) || !channels || channels > 1024 || u32(data + 148) != channels)return fail("Native animation/channel dimensions are invalid");
            const uint32_t count = uint32_t(objects[12]) | (uint32_t(objects[13]) << 8);auto* elements = a.linked(objects, 4, uint64_t(count) * 20);
            if (!count || count > 16384 || !a.aligned(elements, size_t(count) * 20))return fail("Native objects table is unavailable");
            mind = a.linked(brain, 0, 20);if (!a.aligned(mind, 20))return fail("Native Mind is missing");
            model = a.linked(mind, 0, 20);intel = a.linked(mind, 4, 24);reflex = a.linked(mind, 8, 24);dsg = a.linked(mind, 12, 12);
            if (!a.aligned(model, 20) || !a.aligned(intel, 24) || !a.aligned(reflex, 24) || !a.aligned(dsg, 12))return fail("Native AI model, intelligence, reflex or DSG module is missing");
            auto* intelligence = a.linked(model, 0, 16);auto* reflexes = a.linked(model, 4, 16);vars = a.linked(model, 8, 16);
            if (!a.aligned(intelligence, 16) || !a.aligned(reflexes, 16) || !a.aligned(vars, 16))return fail("Native AI scripts or variable definitions are missing");
            intelligence_count = u32(intelligence + 4);reflex_count = u32(reflexes + 4);dsg_bytes = u32(vars + 8);variables = vars[12];
            if (!intelligence_count || intelligence_count > 4096 || reflex_count > 4096 || !dsg_bytes || dsg_bytes > 1024 * 1024 || !variables)return fail("Invalid native AI/DSG counts");
            infos = a.linked(vars, 4, size_t(variables) * 16);default_buffer = a.linked(vars, 0, dsg_bytes);initial_buffer = a.linked(dsg, 4, dsg_bytes);current_buffer = a.linked(dsg, 8, dsg_bytes);
            if (!a.aligned(infos, size_t(variables) * 16) || !default_buffer || !initial_buffer || !current_buffer)return fail("Native DSG descriptions or initial/current buffers are incomplete");
            for (uint32_t i = 0;i < variables;++i) { const uint32_t off = u32(infos + i * 16), type = u32(infos + i * 16 + 4);if (off >= dsg_bytes || type >= 25)return fail("Invalid native DSG variable descriptor"); }
            return true;
        }
        bool sanitize(std::vector<uint8_t>& out, const uint8_t* buffer, uint32_t& references, std::string& why)const {
            out.assign(buffer, buffer + dsg_bytes);references = 0;
            for (uint32_t i = 0;i < variables;++i) {
                const uint32_t off = u32(infos + i * 16), type = u32(infos + i * 16 + 4);
                if (type == 8 || type == 9 || type == 17 || type == 18 || type == 22 || type == 24) {
                    if (!range(off, 4, out.size())) { why = "Native scene reference exceeds DSG buffer";return false; }put32(out.data() + off, 0);++references;
                }
                else if (type == 10) {
                    if (!range(off, 4, out.size()) || out[off] > out[off + 1] || !range(off + 4, uint64_t(out[off + 1]) * 4, out.size())) { why = "Native DSG list exceeds its buffer";return false; }
                    out[off] = 0;std::memset(out.data() + off + 4, 0, size_t(out[off + 1]) * 4);++references;
                }
            }
            return true;
        }
    };
} // namespace r2bank
#endif

#ifndef RAYMAN2_NATIVE_EVENTS_HPP
#define RAYMAN2_NATIVE_EVENTS_HPP
namespace r2bank {
    // R2's Anim3d event array contains 12-byte runtime wrappers, not the
    // serialized 12-byte A3D event records. Their first word points to a record.
    // Source General/start-event indices and the bank's typed relocation supply
    // both links. The remaining wrapper words start at zero in this cold probe.
    struct NativeEvents {
        std::vector<uint8_t> records;
        uint8_t* wrappers;
        uint32_t general, start, count, parameters;
        NativeEvents() :wrappers(nullptr), general(0), start(0), count(0), parameters(0) {}
        static uint32_t word(const uint8_t* p) { return uint32_t(p[0]) | (uint32_t(p[1]) << 8); }
        bool bind(const NativeArena& arena, const NativeSource& source, const WarmAssets& warm, const std::vector<uint8_t>& bp, std::string& why) {
            auto fail = [&](const char* s) {why = s;return false;};
            if (wrappers || !records.empty())return fail("Native animation events were already initialized");
            if (!arena.aligned(source.animation, 28) || bp.size() < 64)return fail("Native event animation/blueprint is missing");
            const uint64_t descriptors = 64 + uint64_t(u32(bp.data() + 32)) * 16;
            if (u32(bp.data() + 36) != 12 || !range(descriptors, 12 * 24, bp.size()))return fail("Native event descriptors are invalid");
            const Animation* generals = nullptr, * events = nullptr;const uint8_t* eventDescriptor = nullptr;
            for (const auto& a : warm.animations) {
                if (a.slot == 1) { if (generals)return fail("Duplicate native General bank");generals = &a; }
                if (a.slot == 9) { if (events)return fail("Duplicate native event bank");events = &a; }
            }
            for (unsigned i = 0;i < 12;++i) {
                const auto* d = bp.data() + size_t(descriptors) + i * 24;
                if (u32(d) == 9) { if (eventDescriptor)return fail("Duplicate native event descriptor");eventDescriptor = d; }
            }
            general = word(source.animation + 24);count = source.animation[26];
            if (!generals || generals->stride != 56 || generals->bytes.size() != uint64_t(generals->count) * 56 || general >= generals->count ||
                !events || events->stride != 12 || events->bytes.size() != uint64_t(events->count) * 12 || !eventDescriptor ||
                u32(eventDescriptor + 4) != 12 || u32(eventDescriptor + 8) != events->count)return fail("Native General/event bank dimensions are invalid");
            const auto* g = generals->bytes.data() + size_t(general) * 56;start = word(g + 50);
            if (word(g + 20) != count || word(g + 14) != word(source.animation) || word(g) != source.animation[2] || word(g + 12) != source.animation[3] ||
                !range(start, count, events->count))return fail("Native animation event count/range does not match General");
            if (!count) { if (u32(source.animation + 4))return fail("An event-free animation has a runtime event array");return true; }
            wrappers = arena.linked(source.animation, 4, size_t(count) * 12);
            if (!arena.aligned(wrappers, size_t(count) * 12))return fail("Native animation event wrappers are unavailable");
            // Never reuse warm CPU pointers or overwrite a live runtime wrapper.
            for (size_t i = 0;i < size_t(count) * 12;++i)if (wrappers[i]) { wrappers = nullptr;return fail("Native animation event wrappers are not cold"); }
            const uint32_t prefix = u32(eventDescriptor + 12), sourceBlob = u32(bp.data() + 16), fixedBlob = u32(bp.data() + 24);
            if (prefix > events->count) { wrappers = nullptr;return fail("Invalid native event prefix"); }
            std::vector<uint8_t> prepared(events->bytes.begin() + size_t(start) * 12, events->bytes.begin() + size_t(start + count) * 12);
            const uintptr_t base = reinterpret_cast<uintptr_t>(prepared.data());
            if ((base & 3) || base > UINT32_MAX || prepared.size() > UINT32_MAX - base) { wrappers = nullptr;return fail("Native event records require aligned 32-bit addresses"); }
            unsigned linked = 0;
            for (uint32_t i = 0;i < count;++i) {
                const uint32_t index = start + i, blob = index < prefix ? fixedBlob : sourceBlob;
                const uint64_t field = uint64_t(u32(eventDescriptor + (index < prefix ? 16 : 20))) + uint64_t(index < prefix ? index : index - prefix) * 12;
                if (field > UINT32_MAX || u32(prepared.data() + size_t(i) * 12)) { wrappers = nullptr;return fail("Native event parameter is not a clean bank reference"); }
                const NativeMetadataRelocation* relocation = arena.metadata(blob, uint32_t(field));
                if (!relocation) { wrappers = nullptr;return fail("Native event parameter relocation is missing"); }
                uint32_t value = 0;
                if (relocation->target == None) { if (relocation->offset || relocation->binding) { wrappers = nullptr;return fail("Invalid null native event parameter"); } }
                else {
                    if (relocation->binding || (relocation->target != sourceBlob && relocation->target != fixedBlob)) {
                        wrappers = nullptr;return fail("Native event parameter needs an unsupported external binding");
                    }
                    auto* parameter = arena.pointer(relocation->target, relocation->offset, 4);
                    if (!arena.aligned(parameter, 4)) { wrappers = nullptr;return fail("Native event parameter is outside the private payloads"); }
                    value = uint32_t(reinterpret_cast<uintptr_t>(parameter));++linked;
                }
                put32(prepared.data() + size_t(i) * 12, value);
            }
            records.swap(prepared);parameters = linked;
            for (uint32_t i = 0;i < count;++i)put32(wrappers + size_t(i) * 12, uint32_t(reinterpret_cast<uintptr_t>(records.data() + size_t(i) * 12)));
            return true;
        }
        bool valid(const NativeArena& arena)const {
            if (!count)return !wrappers && records.empty();
            if (!arena.aligned(wrappers, size_t(count) * 12) || records.size() != size_t(count) * 12)return false;
            for (uint32_t i = 0;i < count;++i) {
                if (u32(wrappers + size_t(i) * 12) != reinterpret_cast<uintptr_t>(records.data() + size_t(i) * 12))return false;
                const auto parameter = reinterpret_cast<const void*>(uintptr_t(u32(records.data() + size_t(i) * 12)));
                if (parameter && !arena.aligned(parameter, 4))return false;
            }
            return true;
        }
    };
} // namespace r2bank
#endif


