// ============================================================
// RANDOMIZER CORE FOUNDATION (v0.0.14b.0)
//
// This is intentionally independent from the older Aglagl research code.
// The core provides:
//   - a persistent INI configuration next to Rayman2.exe
//   - a persistent seed
//   - deterministic, order-independent random rolls
//   - module toggles for future randomizers
//
// IMPORTANT DESIGN RULE:
// A roll is addressed by (seed, module, level, slot). Enabling/disabling one
// module therefore cannot shift the random results of another module.
// ============================================================

struct R2R_RandomizerConfig
{
    uint32_t seed;
    bool enabled;
    bool enemies;
    bool enemiesMenuTest; // Developer-only, not exposed by public configurator.
    bool enemiesWorldRemixTest; // Test 25 opt-in Jail_20 cinematic positional test.
    bool items;
    bool music;
    bool musicAllAPM;
    bool sounds;
    bool textures;
    bool texts;
    bool stats;
    bool randomMovementSpeeds;
    bool testingPowers;
};

static R2R_RandomizerConfig g_R2RConfig = {};
// Experimental menu shuffle must emit a report at DLL load (even if no Menu actor is found).
static void R2R_MenuEnemyStartupDiagnostic(const char* reason);
static void R2R_WorldRemixStartupDiagnostic(const char* reason);
static char g_R2RConfigPath[MAX_PATH] = {};
static const char* R2R_CORE_REPORT = "Rayman2Randomizer_Core.txt";
static unsigned int g_R2RConfigReloadCount = 0;
static const bool g_R2RResearchHotkeysEnabled = false;

static uint64_t R2R_SplitMix64(uint64_t x)
{
    x += 0x9E3779B97F4A7C15ULL;
    x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9ULL;
    x = (x ^ (x >> 27)) * 0x94D049BB133111EBULL;
    return x ^ (x >> 31);
}

static uint64_t R2R_HashText64(const char* text)
{
    // FNV-1a 64-bit. Stable across runs and compilers.
    uint64_t h = 1469598103934665603ULL;

    if (text == nullptr)
        return h;

    while (*text != '\0')
    {
        h ^= (uint8_t)(*text);
        h *= 1099511628211ULL;
        ++text;
    }

    return h;
}

static uint32_t R2R_RollU32(
    const char* module,
    const char* level,
    uint32_t slot
)
{
    uint64_t x = ((uint64_t)g_R2RConfig.seed << 32) | g_R2RConfig.seed;
    x ^= R2R_HashText64(module);
    x = R2R_SplitMix64(x);
    x ^= R2R_HashText64(level);
    x = R2R_SplitMix64(x);
    x ^= ((uint64_t)slot * 0x9E3779B97F4A7C15ULL);
    x = R2R_SplitMix64(x);
    return (uint32_t)(x ^ (x >> 32));
}

static int R2R_RollRange(
    const char* module,
    const char* level,
    uint32_t slot,
    int minInclusive,
    int maxInclusive
)
{
    if (maxInclusive <= minInclusive)
        return minInclusive;

    const uint32_t span =
        (uint32_t)(maxInclusive - minInclusive + 1);

    return minInclusive +
        (int)(R2R_RollU32(module, level, slot) % span);
}

static void R2R_BuildConfigPath()
{
    char exePath[MAX_PATH] = {};
    const DWORD len = GetModuleFileNameA(nullptr, exePath, MAX_PATH);

    if (len == 0 || len >= MAX_PATH)
    {
        strcpy_s(g_R2RConfigPath, ".\\Rayman2Randomizer.ini");
        return;
    }

    char* slash = strrchr(exePath, '\\');
    if (slash == nullptr)
        slash = strrchr(exePath, '/');

    if (slash != nullptr)
        *(slash + 1) = '\0';
    else
        exePath[0] = '\0';

    sprintf_s(
        g_R2RConfigPath,
        "%sRayman2Randomizer.ini",
        exePath
    );
}

static uint32_t R2R_GeneratePersistentSeed()
{
    LARGE_INTEGER qpc = {};
    QueryPerformanceCounter(&qpc);

    FILETIME ft = {};
    GetSystemTimeAsFileTime(&ft);

    uint64_t x = (uint64_t)qpc.QuadPart;
    x ^= ((uint64_t)ft.dwHighDateTime << 32) | ft.dwLowDateTime;
    x ^= ((uint64_t)GetTickCount() << 17);
    x ^= ((uint64_t)GetCurrentProcessId() << 41);
    x = R2R_SplitMix64(x);

    uint32_t result = (uint32_t)(x ^ (x >> 32));
    result &= 0x7FFFFFFFu; // Keep INI parsing simple and portable.
    if (result == 0)
        result = 1;

    return result;
}

static void R2R_WriteIniValue(const char* key, const char* value)
{
    WritePrivateProfileStringA(
        "Randomizer",
        key,
        value,
        g_R2RConfigPath
    );
}

static void R2R_CreateDefaultConfigIfMissing()
{
    if (g_R2RConfigPath[0] == '\0')
        R2R_BuildConfigPath();

    const DWORD attrs = GetFileAttributesA(g_R2RConfigPath);
    if (attrs != INVALID_FILE_ATTRIBUTES)
        return;

    const uint32_t seed = R2R_GeneratePersistentSeed();
    char seedText[32] = {};
    sprintf_s(seedText, "%u", seed);

    R2R_WriteIniValue("Seed", seedText);
    R2R_WriteIniValue("Enabled", "1");
    R2R_WriteIniValue("Enemies", "0");
    R2R_WriteIniValue("EnemiesMenuTest", "0");
    R2R_WriteIniValue("EnemiesWorldRemixTest", "0");
    R2R_WriteIniValue("Items", "0");
    R2R_WriteIniValue("Music", "0");
    R2R_WriteIniValue("MusicAllAPM", "1");
    R2R_WriteIniValue("Sounds", "0");
    R2R_WriteIniValue("Textures", "0");
    R2R_WriteIniValue("Texts", "0");
    R2R_WriteIniValue("Stats", "0");
    R2R_WriteIniValue("RandomMovementSpeeds", "0");
    // Testing convenience: direct level switching otherwise starts from a
    // fresh-save progression state and can make some test areas unreachable.
    R2R_WriteIniValue("TestingPowers", "0");
}

static bool R2R_ReadIniBool(const char* key, bool defaultValue)
{
    return GetPrivateProfileIntA(
        "Randomizer",
        key,
        defaultValue ? 1 : 0,
        g_R2RConfigPath
    ) != 0;
}

