{
    FILE* f = nullptr;
    fopen_s(&f, R2R_CORE_REPORT, "w");
    if (f == nullptr)
        return;

    fprintf(
        f,
        "RAYMAN 2 RANDOMIZER\n"
        "%s - CORE FOUNDATION\n"
        "============================================================\n\n"
        "Reason       : %s\n"
        "Config path  : %s\n"
        "Seed         : %u\n"
        "Reload count : %u\n\n"
        "OPTIONS\n"
        "------------------------------------------------------------\n"
        "Enabled  : %s\n"
        "Enemies  : %s\n"
        "EnemiesMenuTest: %s (developer-only)\n"
        "Items    : %s\n"
        "Music    : %s\n"
        "MusicAllAPM: %s\n"
        "Sounds   : %s\n"
        "Textures : %s\n"
        "Texts    : %s\n"
        "Stats    : %s\n"
        "RandomMovementSpeeds : %s (default OFF)\n"
        "TestingPowers : %s\n\n"
        "DETERMINISM SELF-CHECK\n"
        "------------------------------------------------------------\n"
        "The values below MUST stay identical for the same seed.\n"
        "They are independent streams, so module order does not matter.\n\n"
        "Bast_20 / Enemy slot 0 : %u\n"
        "Bast_20 / Item slot 0  : %u\n"
        "Bast_20 / Music slot 0 : %u\n"
        "Bast_20 / Sound slot 0 : %u\n"
        "Bast_20 / Texture 0    : %u\n"
        "Bast_20 / Stat slot 0  : %u\n\n"
        "GAMEPLAY MODULE\n"
        "------------------------------------------------------------\n"
        "Stats=ON enables the conservative HP randomizer.\n"
        "Movement stays native unless RandomMovementSpeeds=1 is explicitly set.\n"
        "Items=ON enables the current grouped Lum / special-pickup tests.\n"
        "Sounds=ON remaps loaded short one-shot SFX; loops and streaming music stay native.\n"
        "Music=ON and MusicAllAPM=1 try coherent APM sequence replacement first;\n"
        "a validated loaded-Theme swap is used as fallback.\n"
        "TestingPowers=ON grants the tester maximum health plus permanent\n"
        "purple-Lum swing, charged-shot and maximum golden-fist progression.\n"
        "Story/cutscene completion flags are not changed.\n",
        VERSION,
        reason != nullptr ? reason : "unknown",
        g_R2RConfigPath,
        g_R2RConfig.seed,
        g_R2RConfigReloadCount,
        g_R2RConfig.enabled ? "ON" : "OFF",
        g_R2RConfig.enemies ? "ON" : "OFF",
        g_R2RConfig.enemiesMenuTest ? "ON" : "OFF",
        g_R2RConfig.items ? "ON" : "OFF",
        g_R2RConfig.music ? "ON" : "OFF",
        g_R2RConfig.musicAllAPM ? "ON" : "OFF",
        g_R2RConfig.sounds ? "ON" : "OFF",
        g_R2RConfig.textures ? "ON" : "OFF",
        g_R2RConfig.texts ? "ON" : "OFF",
        g_R2RConfig.stats ? "ON" : "OFF",
        g_R2RConfig.randomMovementSpeeds ? "ON" : "OFF",
        g_R2RConfig.testingPowers ? "ON" : "OFF",
        R2R_RollU32("Enemies", "Bast_20", 0),
        R2R_RollU32("Items", "Bast_20", 0),
        R2R_RollU32("Music", "Bast_20", 0),
        R2R_RollU32("Sounds", "Bast_20", 0),
        R2R_RollU32("Textures", "Bast_20", 0),
        R2R_RollU32("Stats", "Bast_20", 0)
    );

    fflush(f);
    fclose(f);
}

static void R2R_LoadRandomizerConfig(const char* reason)
{
    if (g_R2RConfigPath[0] == '\0')
        R2R_BuildConfigPath();

    R2R_CreateDefaultConfigIfMissing();

    uint32_t seed = (uint32_t)GetPrivateProfileIntA(
        "Randomizer",
        "Seed",
        0,
        g_R2RConfigPath
    );

    if (seed == 0)
    {
        seed = R2R_GeneratePersistentSeed();
        char seedText[32] = {};
        sprintf_s(seedText, "%u", seed);
        R2R_WriteIniValue("Seed", seedText);
    }

    g_R2RConfig.seed = seed;
    g_R2RConfig.enabled = R2R_ReadIniBool("Enabled", true);
    // BETA 0.1.5: enemies are unavailable; item shuffle is EXPERIMENTAL opt-in.
    g_R2RConfig.enemies = false;
    // Public release: development-only enemy paths MUST remain unreachable,
    // even if an old experimental INI enables them.
    g_R2RConfig.enemiesMenuTest = false;
    g_R2RConfig.enemiesWorldRemixTest = false;
    // Items are explicitly opt-in and labelled EXPERIMENTAL by the launcher.
    g_R2RConfig.items = R2R_ReadIniBool("Items", false);
    g_R2RConfig.music = R2R_ReadIniBool("Music", false);
    g_R2RConfig.musicAllAPM = R2R_ReadIniBool("MusicAllAPM", true);
    g_R2RConfig.sounds = R2R_ReadIniBool("Sounds", false);
    g_R2RConfig.textures = R2R_ReadIniBool("Textures", false);
    g_R2RConfig.texts = R2R_ReadIniBool("Texts", false);
    g_R2RConfig.stats = R2R_ReadIniBool("Stats", false);
    // Existing INIs with Stats=1 also keep native movement unless explicitly opted in.
    g_R2RConfig.randomMovementSpeeds = R2R_ReadIniBool("RandomMovementSpeeds", false);
    // Developer convenience: respect the explicit INI toggle. The Test50
    // ZIP ships a matching INI with TestingPowers=1; missing keys default ON.
    // The public beta never gives developer test powers, regardless of INI.
    g_R2RConfig.testingPowers = false;

    ++g_R2RConfigReloadCount;
    R2R_WriteCoreReport(reason);
    R2R_MenuEnemyStartupDiagnostic(reason);
    R2R_WorldRemixStartupDiagnostic(reason);
}

