// ============================================================
// TESTER PROGRESSION PRESET (v0.0.14k.0)
//
// F1/F2 deliberately allows loading levels independently of normal story
// progression. On a fresh save that means some areas are unreachable because
// Rayman has not yet received his permanent upgrades. This tester-only helper
// grants the permanent progression needed for randomizer development while
// leaving story/cutscene completion flags alone.
//
// Known global collected-object bits used here (global DSG array #42):
//   1095 = purple-Lum swing/grab (blue Silver Lum)
//   1143 = charged shots (gold Silver Lum)
//   962 + 963 = maximum golden-fist progression
//
// Rayman's StandardGame max/maxmax is raised to the observed PC maximum 110.
// Current health is refilled only during the first second of a newly-loaded
// level; after that this is NOT an invincibility cheat.
// ============================================================

static const char* R2R_TESTER_PROGRESS_REPORT =
"Rayman2Randomizer_TesterProgress.txt";

static const unsigned char R2R_TESTER_MAX_HP = 110;
static const unsigned int R2R_TESTER_REFILL_FRAMES = 60;

static HIE_tdstSuperObject* g_R2RTesterWorldMarker = nullptr;
static char g_R2RTesterLevel[64] = {};
static unsigned int g_R2RTesterFrames = 0;
static bool g_R2RTesterReportWritten = false;

// Readability guard is implemented later in this translation unit.
bool R2R_AddressReadable(uintptr_t address, size_t size);

static bool R2R_SetBooleanInGlobalArray(
    HIE_tdstSuperObject* globalObject,
    unsigned int oneBasedIndex,
    bool value
)
{
    if (globalObject == nullptr || oneBasedIndex == 0)
        return false;

    AI_tdstArray* array = nullptr;

    if (
        !AI_fn_bGetDsgVar(
            globalObject,
            42,
            nullptr,
            reinterpret_cast<void**>(&array)
        ) ||
        array == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(array), sizeof(AI_tdstArray_1))
        )
    {
        return false;
    }

    const unsigned int zeroBased = oneBasedIndex - 1;
    const unsigned long wordIndex = (unsigned long)(zeroBased >> 5);
    const unsigned long bitIndex = (unsigned long)(zeroBased & 31u);

    // Boolean arrays are packed 32 flags per long in the ACP engine.
    // ucMaxSize is the number of stored array elements/words.
    if (wordIndex >= (unsigned long)array->ucMaxSize)
        return false;

    long* word = &AI_M_pArrayElement(array, wordIndex)->lValue;
    if (!R2R_AddressReadable(reinterpret_cast<uintptr_t>(word), sizeof(*word)))
        return false;
    MEMORY_BASIC_INFORMATION memory = {};
    if (!VirtualQuery(word, &memory, sizeof(memory)) || memory.State != MEM_COMMIT)
        return false;
    const DWORD protect = memory.Protect & 0xffu;
    if (protect != PAGE_READWRITE && protect != PAGE_WRITECOPY &&
        protect != PAGE_EXECUTE_READWRITE && protect != PAGE_EXECUTE_WRITECOPY)
        return false;
    const unsigned long mask = (1UL << bitIndex);
    unsigned long current = (unsigned long)(*word);

    if (value)
        current |= mask;
    else
        current &= ~mask;

    *word = (long)current;
    return true;
}

static void R2R_WriteTesterProgressReport(
    const char* levelName,
    bool globalFound,
    bool purpleSet,
    bool chargeSet,
    bool fist962Set,
    bool fist963Set,
    GAM_tdstStandardGame* rayStd
)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_TESTER_PROGRESS_REPORT, "w");
    if (f == nullptr)
        return;

    fprintf(
        f,
        "RAYMAN 2 RANDOMIZER\n"
        "%s - TESTER MAX PROGRESSION\n"
        "============================================================\n\n"
        "Level          : %s\n"
        "TestingPowers  : %s\n\n"
        "GLOBAL PROGRESSION FLAGS (DSG array #42)\n"
        "------------------------------------------------------------\n"
        "global object found : %s\n"
        "1095 purple-Lum grab: %s\n"
        "1143 charged shots  : %s\n"
        " 962 golden fist A  : %s\n"
        " 963 golden fist B  : %s\n\n"
        "RAYMAN HEALTH\n"
        "------------------------------------------------------------\n",
        VERSION,
        levelName != nullptr ? levelName : "(unknown)",
        g_R2RConfig.testingPowers ? "ON" : "OFF",
        globalFound ? "YES" : "NO",
        purpleSet ? "SET" : "FAILED",
        chargeSet ? "SET" : "FAILED",
        fist962Set ? "SET" : "FAILED",
        fist963Set ? "SET" : "FAILED"
    );

    if (rayStd != nullptr)
    {
        fprintf(
            f,
            "HP / Max / MaxMax : %u / %u / %u\n"
            "Save HP / Save Max: %u / %u\n"
            "Target max health : %u\n",
            (unsigned int)rayStd->ucHitPoints,
            (unsigned int)rayStd->ucHitPointsMax,
            (unsigned int)rayStd->ucHitPointsMaxMax,
            (unsigned int)rayStd->ucSaveHitPoints,
            (unsigned int)rayStd->ucSaveHitPointsMax,
            (unsigned int)R2R_TESTER_MAX_HP
        );
    }
    else
    {
        fprintf(f, "Rayman StandardGame not available.\n");
    }

    fprintf(
        f,
        "\nNOTE\n"
        "------------------------------------------------------------\n"
        "This helper intentionally does NOT set story/cutscene completion flags.\n"
        "It exists only so direct F1/F2 level testing is not blocked by a fresh save.\n"
    );

    fclose(f);
}

static void R2R_TesterProgressTick()
{
    if (
        !g_R2RConfig.enabled ||
        !g_R2RConfig.testingPowers ||
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr
        )
    {
        return;
    }

    HIE_tdstSuperObject* activeRoot = *GAM_g_p_stDynamicWorld;
    const char* levelName = GAM_g_stEngineStructure->szLevelName;

    const bool newLevel =
        g_R2RTesterWorldMarker != activeRoot ||
        g_R2RTesterLevel[0] == '\0' ||
        levelName == nullptr ||
        _stricmp(g_R2RTesterLevel, levelName) != 0;

    if (newLevel)
    {
        g_R2RTesterWorldMarker = activeRoot;
        g_R2RTesterFrames = 0;
        g_R2RTesterReportWritten = false;

        if (levelName != nullptr)
            strncpy_s(g_R2RTesterLevel, levelName, _TRUNCATE);
        else
            strcpy_s(g_R2RTesterLevel, "(unknown)");
    }

    ++g_R2RTesterFrames;

    // Reassert the permanent progression flags every playing frame because
    // direct level transitions can rebuild the global DSG state from the save.
    HIE_tdstSuperObject* globalObject =
        HIE_fn_p_stFindObjectByName("global");

    const bool globalFound = globalObject != nullptr;
    bool purpleSet = false;
    bool chargeSet = false;
    bool fist962Set = false;
    bool fist963Set = false;

    if (globalFound)
    {
        purpleSet = R2R_SetBooleanInGlobalArray(globalObject, 1095, true);
        chargeSet = R2R_SetBooleanInGlobalArray(globalObject, 1143, true);
        fist962Set = R2R_SetBooleanInGlobalArray(globalObject, 962, true);
        fist963Set = R2R_SetBooleanInGlobalArray(globalObject, 963, true);
    }

    HIE_tdstSuperObject* raymanSO = HIE_M_hGetMainActor();
    HIE_tdstEngineObject* raymanActor =
        raymanSO != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(raymanSO), sizeof(*raymanSO))
        ? HIE_M_hSuperObjectGetActor(raymanSO)
        : nullptr;
    if (raymanActor != nullptr &&
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raymanActor), sizeof(*raymanActor)))
        raymanActor = nullptr;

    GAM_tdstStandardGame* rayStd =
        raymanActor != nullptr
        ? raymanActor->hStandardGame
        : nullptr;
    if (rayStd != nullptr &&
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(rayStd), sizeof(*rayStd)))
        rayStd = nullptr;

    if (rayStd != nullptr)
    {
        // Keep the maximum unlocked. Refill current HP only briefly after a
        // level load so normal damage testing still works afterward.
        rayStd->ucHitPointsMaxMax = R2R_TESTER_MAX_HP;
        rayStd->ucHitPointsMax = R2R_TESTER_MAX_HP;
        rayStd->ucSaveHitPointsMax = R2R_TESTER_MAX_HP;

        if (g_R2RTesterFrames <= R2R_TESTER_REFILL_FRAMES)
        {
            rayStd->ucHitPoints = R2R_TESTER_MAX_HP;
            rayStd->ucSaveHitPoints = R2R_TESTER_MAX_HP;
        }
    }

    // Wait long enough for both the global object and Rayman to be fully live,
    // then leave a compact verification report for the tester.
    if (!g_R2RTesterReportWritten && g_R2RTesterFrames >= 30 &&
        ((globalFound && rayStd != nullptr) || g_R2RTesterFrames >= 180))
    {
        R2R_WriteTesterProgressReport(
            g_R2RTesterLevel,
            globalFound,
            purpleSet,
            chargeSet,
            fist962Set,
            fist963Set,
            rayStd
        );
        g_R2RTesterReportWritten = true;
    }
}

