// v0.0.18x.0: common default for every listed/current/future motion target.
// Register only AFTER an exact/prefix identity or strict network is validated.
// Animation scans use ObserveTarget; pre-engine motion scans use
// ObserveMotionTarget so their current observation survives frame publication.
// Inertia removal is automatic,
// including when only animation is varied, Stats is off, or F8 is selected.
enum R2R_NoMomentumProof
{
    R2R_NO_MOMENTUM_NAMED,
    R2R_NO_MOMENTUM_CHASE10_NETWORK,
    R2R_NO_MOMENTUM_CHASE22_NETWORK
};
struct R2R_NoMomentumScope
{
    HIE_tdstSuperObject* owner;
    DNM_tdstDynamics* dynamics;
    unsigned int serial;
    unsigned long originalBit;
    bool changed;
};
static bool R2R_NoMomentumObserveTarget(HIE_tdstSuperObject*,
    R2R_NoMomentumProof = R2R_NO_MOMENTUM_NAMED);
static void R2R_NoMomentumObserveMotionTarget(HIE_tdstSuperObject*,
    R2R_NoMomentumProof = R2R_NO_MOMENTUM_NAMED);
static void R2R_NoMomentumObserveRemovedSpeedTarget(HIE_tdstSuperObject*);
static void R2R_NoMomentumObserveLegacyTarget(HIE_tdstSuperObject*);
static bool R2R_NoMomentumBeginMechanics(HIE_tdstSuperObject*, DNM_tdstDynamics*, R2R_NoMomentumScope&);
static void R2R_NoMomentumEndMechanics(const R2R_NoMomentumScope&);

static DNM_tdstDynamics* R2R_HookedDynamicsBaseMechanics(
    DNM_tdstDynamics* p_stDynamics,
    HIE_tdstSuperObject* p_stSuperObject,
    DNM_tdstParsingDatas* p_stParsingDatas,
    void* hMecIdCard,
    MTH_tdxReal xDT
)
{
    R2R_StatsSeenEntry* entry = nullptr;
    bool imposeApplied = false;
    MTH3D_tdstVector originalImpose = {};

    if (
        g_R2RConfig.enabled &&
        R2R_StatsEffectiveMode() != R2R_STATS_MODE_NATIVE &&
        R2R_StatsMovementPlaytestEnabled() &&
        p_stDynamics != nullptr &&
        p_stSuperObject != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(p_stDynamics), sizeof(DNM_tdstDynamicsBaseBlock))
        )
    {
        entry = R2R_StatsFindMovementEntry(p_stSuperObject, p_stDynamics);
    }

    if (entry != nullptr)
    {
        ++entry->movementHookHits;

        // Pirates are deliberately READ-ONLY in 16j.  Capture the mechanics
        // vectors before/after the engine call, but do not alter any of them.
        if (entry->pirateReadOnlyDiagnostic)
        {
            R2R_StatsDiagCapture(entry, p_stDynamics, p_stParsingDatas, false);
        }
        else
        {
            DNM_tdstDynamicsBaseBlock& base = p_stDynamics->stDynamicsBase;
            if (
                entry->imposeSpeedDiagnostic &&
                R2R_StatsVectorHasHorizontalMotion(base.stImposeSpeed) &&
                std::isfinite(entry->movementMultiplier) &&
                entry->movementMultiplier >= 0.25f &&
                entry->movementMultiplier <= 2.50f
                )
            {
                originalImpose = base.stImposeSpeed;
                base.stImposeSpeed.x *= entry->movementMultiplier;
                base.stImposeSpeed.y *= entry->movementMultiplier;

                if (!entry->firstImposeCaptured)
                {
                    entry->firstImposeBefore = originalImpose;
                    entry->firstImposeApplied = base.stImposeSpeed;
                    entry->firstImposeCaptured = true;
                }

                ++entry->imposeAppliedHits;
                imposeApplied = true;
            }
        }
    }

    float jail20SbireOriginalY = 0.0f, jail20SbireAppliedY = 0.0f;
    const bool jail20SbireApplied = R2R_Jail20SbireBeginMechanics(
        p_stSuperObject, p_stDynamics, jail20SbireOriginalY, jail20SbireAppliedY);

    MTH3D_tdstVector cineImposeOriginal = {}, cineImposeApplied = {};
    const bool cineApplied = R2R_Bast22CineBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, cineImposeOriginal, cineImposeApplied);

    MTH3D_tdstVector ptizetreImposeOriginal = {}, ptizetreImposeApplied = {};
    const bool ptizetreApplied = R2R_Learn60PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, ptizetreImposeOriginal, ptizetreImposeApplied);

    MTH3D_tdstVector ski10ImposeOriginal = {}, ski10ImposeApplied = {};
    const bool ski10Applied = R2R_Ski10PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, ski10ImposeOriginal, ski10ImposeApplied);

    MTH3D_tdstVector ski60ImposeOriginal = {}, ski60ImposeApplied = {};
    const bool ski60Applied = R2R_Ski60PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, ski60ImposeOriginal, ski60ImposeApplied);

    MTH3D_tdstVector batam10ImposeOriginal = {}, batam10ImposeApplied = {};
    const bool batam10Applied = R2R_Batam10PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, batam10ImposeOriginal, batam10ImposeApplied);

    MTH3D_tdstVector ly10ImposeOriginal = {}, ly10ImposeApplied = {};
    const bool ly10Applied = R2R_Ly10PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, ly10ImposeOriginal, ly10ImposeApplied);

    MTH3D_tdstVector vulca20ImposeOriginal = {}, vulca20ImposeApplied = {};
    const bool vulca20Applied = R2R_Vulca20PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, vulca20ImposeOriginal, vulca20ImposeApplied);

    MTH3D_tdstVector vulca10ImposeOriginal = {}, vulca10ImposeApplied = {};
    const bool vulca10Applied = R2R_Vulca10PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, vulca10ImposeOriginal, vulca10ImposeApplied);

    MTH3D_tdstVector rodeo60ImposeOriginal = {}, rodeo60ImposeApplied = {};
    const bool rodeo60Applied = R2R_Rodeo60PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, rodeo60ImposeOriginal, rodeo60ImposeApplied);

    MTH3D_tdstVector rodeo40ImposeOriginal = {}, rodeo40ImposeApplied = {};
    const bool rodeo40Applied = R2R_Rodeo40PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, rodeo40ImposeOriginal, rodeo40ImposeApplied);

    MTH3D_tdstVector rodeo10ImposeOriginal = {}, rodeo10ImposeApplied = {};
    const bool rodeo10Applied = R2R_Rodeo10PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, rodeo10ImposeOriginal, rodeo10ImposeApplied);

    MTH3D_tdstVector poloc10ImposeOriginal = {}, poloc10ImposeApplied = {};
    const bool poloc10Applied = R2R_Poloc10PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, poloc10ImposeOriginal, poloc10ImposeApplied);

    MTH3D_tdstVector water20AglaglOriginal = {}, water20AglaglApplied = {};
    const bool water20AglaglAppliedFlag = R2R_Water20AglaglBeginMechanics(
        p_stSuperObject, p_stDynamics, xDT, water20AglaglOriginal, water20AglaglApplied);

    MTH3D_tdstVector water20ImposeOriginal = {}, water20ImposeApplied = {};
    const bool water20Applied = R2R_Water20PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, water20ImposeOriginal, water20ImposeApplied);

    MTH3D_tdstVector water10ImposeOriginal = {}, water10ImposeApplied = {};
    const bool water10Applied = R2R_Water10PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, water10ImposeOriginal, water10ImposeApplied);

    MTH3D_tdstVector nego10ImposeOriginal = {}, nego10ImposeApplied = {};
    const bool nego10Applied = R2R_Nego10PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, nego10ImposeOriginal, nego10ImposeApplied);

    MTH3D_tdstVector chase10ImposeOriginal = {}, chase10ImposeApplied = {};
    const bool chase10Applied = R2R_Chase10PathBeginMechanics(p_stSuperObject, p_stDynamics,
        xDT, chase10ImposeOriginal, chase10ImposeApplied);
    unsigned long chase10InertiaBit = 0;
    const bool chase10InertiaApplied = R2R_Chase10BarrelBeginMechanics(p_stSuperObject, p_stDynamics, chase10InertiaBit);

    unsigned long barrelInertiaBit = 0;
    const bool barrelInertiaApplied = R2R_Learn30BarrelBeginMechanics(
        p_stSuperObject, p_stDynamics, barrelInertiaBit);
    R2R_NoMomentumScope noMomentum = {};
    R2R_NoMomentumBeginMechanics(p_stSuperObject, p_stDynamics, noMomentum);
    DNM_tdstDynamics* result = MEC_p_stDynamicsBaseMechanics(
        p_stDynamics, p_stSuperObject, p_stParsingDatas, hMecIdCard,
        R2R_Bast20ExpandedMechanicsDT(p_stSuperObject, p_stDynamics,
            R2R_Learn31ExpandedMechanicsDT(p_stSuperObject, p_stDynamics,
                R2R_Learn30ExpandedMechanicsDT(p_stSuperObject, p_stDynamics,
                    R2R_MapMondeMechanicsDT(p_stSuperObject, p_stDynamics,
                        R2R_Learn10MechanicsDT(p_stSuperObject, p_stDynamics,
                            R2R_Rodeo60RayEndMechanicsDT(p_stSuperObject, p_stDynamics,
                                R2R_Rodeo40RayEndMechanicsDT(p_stSuperObject, p_stDynamics,
                                    R2R_Rodeo10RayEndMechanicsDT(p_stSuperObject, p_stDynamics,
                                        R2R_Chase22PathMechanicsDT(p_stSuperObject, p_stDynamics,
                                            R2R_Chase10ExpandedMechanicsDT(p_stSuperObject, p_stDynamics,
                                                R2R_Chase10RayEndMechanicsDT(p_stSuperObject, p_stDynamics,
                                                    R2R_Ski10ExpandedMechanicsDT(p_stSuperObject, p_stDynamics,
                                                        R2R_Learn60ExpandedMechanicsDT(p_stSuperObject, p_stDynamics,
                                                            R2R_Bast22ExpandedMechanicsDT(p_stSuperObject, p_stDynamics,
                                                                R2R_Bast22BombMechanicsDT(p_stSuperObject, p_stDynamics,
                                                                    R2R_Bast20PiranhaMechanicsDT(p_stSuperObject, p_stDynamics,
                                                                        R2R_Learn31PiranhaMechanicsDT(p_stSuperObject, p_stDynamics,
                                                                            R2R_Learn30PiranhaMechanicsDT(p_stSuperObject, p_stDynamics, xDT))))))))))))))))))
    );

    R2R_NoMomentumEndMechanics(noMomentum);

    if (jail20SbireApplied)
        R2R_Jail20SbireEndMechanics(p_stDynamics, jail20SbireOriginalY);

    if (chase10InertiaApplied)
        R2R_Chase10BarrelEndMechanics(p_stSuperObject, p_stDynamics, chase10InertiaBit);
    if (chase10Applied)
        R2R_Chase10PathEndMechanics(p_stSuperObject, p_stDynamics, chase10ImposeOriginal, chase10ImposeApplied);

    if (barrelInertiaApplied)
        R2R_Learn30BarrelEndMechanics(p_stSuperObject, p_stDynamics, barrelInertiaBit);

    if (vulca20Applied)
        R2R_Vulca20PathEndMechanics(p_stSuperObject, p_stDynamics, vulca20ImposeOriginal, vulca20ImposeApplied);

    if (vulca10Applied)
        R2R_Vulca10PathEndMechanics(p_stSuperObject, p_stDynamics, vulca10ImposeOriginal, vulca10ImposeApplied);

    if (rodeo60Applied)
        R2R_Rodeo60PathEndMechanics(p_stSuperObject, p_stDynamics, rodeo60ImposeOriginal, rodeo60ImposeApplied);

    if (rodeo40Applied)
        R2R_Rodeo40PathEndMechanics(p_stSuperObject, p_stDynamics, rodeo40ImposeOriginal, rodeo40ImposeApplied);

    if (rodeo10Applied)
        R2R_Rodeo10PathEndMechanics(p_stSuperObject, p_stDynamics, rodeo10ImposeOriginal, rodeo10ImposeApplied);

    if (poloc10Applied)
        R2R_Poloc10PathEndMechanics(p_stSuperObject, p_stDynamics, poloc10ImposeOriginal, poloc10ImposeApplied);

    if (water20Applied)
        R2R_Water20PathEndMechanics(p_stSuperObject, p_stDynamics, water20ImposeOriginal, water20ImposeApplied);

    if (water20AglaglAppliedFlag)
        R2R_Water20AglaglEndMechanics(
            p_stSuperObject, p_stDynamics, water20AglaglOriginal, water20AglaglApplied);

    if (water10Applied)
        R2R_Water10PathEndMechanics(p_stSuperObject, p_stDynamics, water10ImposeOriginal, water10ImposeApplied);

    if (nego10Applied)
        R2R_Nego10PathEndMechanics(p_stSuperObject, p_stDynamics, nego10ImposeOriginal, nego10ImposeApplied);

    if (ly10Applied)
        R2R_Ly10PathEndMechanics(p_stSuperObject, p_stDynamics, ly10ImposeOriginal, ly10ImposeApplied);

    if (batam10Applied)
        R2R_Batam10PathEndMechanics(p_stSuperObject, p_stDynamics, batam10ImposeOriginal, batam10ImposeApplied);

    if (ski60Applied)
        R2R_Ski60PathEndMechanics(p_stSuperObject, p_stDynamics, ski60ImposeOriginal, ski60ImposeApplied);

    if (ski10Applied)
        R2R_Ski10PathEndMechanics(p_stSuperObject, p_stDynamics, ski10ImposeOriginal, ski10ImposeApplied);

    if (ptizetreApplied)
        R2R_Learn60PathEndMechanics(p_stSuperObject, p_stDynamics, ptizetreImposeOriginal, ptizetreImposeApplied);

    if (cineApplied)
        R2R_Bast22CineEndMechanics(p_stSuperObject, p_stDynamics, cineImposeOriginal, cineImposeApplied);

    if (entry != nullptr && p_stDynamics != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(p_stDynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
    {
        if (entry->pirateReadOnlyDiagnostic)
        {
            R2R_StatsDiagCapture(entry, p_stDynamics, p_stParsingDatas, true);
        }
        else if (imposeApplied)
        {
            p_stDynamics->stDynamicsBase.stImposeSpeed = originalImpose;
        }
    }

    return result;
}

// v0.0.16l.0
// Lower-level translation hook kept READ-ONLY. Earlier builds experimented with
// scaling this input, but the Astro pirate showed that the vector can represent
// an absolute/world-space translation target rather than a velocity. Scaling it
// generically is therefore unsafe. The hook remains useful for route diagnostics.
static void R2R_HookedInitTranslation(
    DNM_tdstDynamics* p_stDynamics,
    HIE_tdstSuperObject* p_stSuperObject,
    MTH3D_tdstVector* p_stVector
)
{
    R2R_StatsSeenEntry* entry = nullptr;
    bool translationApplied = false;
    MTH3D_tdstVector originalVector = {};

    if (
        g_R2RConfig.enabled &&
        R2R_StatsEffectiveMode() != R2R_STATS_MODE_NATIVE &&
        R2R_StatsMovementPlaytestEnabled() &&
        p_stDynamics != nullptr &&
        p_stSuperObject != nullptr &&
        p_stVector != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(p_stVector), sizeof(MTH3D_tdstVector))
        )
    {
        entry = R2R_StatsFindMovementEntry(p_stSuperObject, p_stDynamics);
    }

    if (entry != nullptr)
    {
        ++entry->translationHookHits;

        if (entry->pirateReadOnlyDiagnostic)
        {
            // Capture the first real translation request without touching it.
            if (
                !entry->firstTranslationCaptured &&
                R2R_StatsVectorHasHorizontalMotion(*p_stVector)
                )
            {
                entry->firstTranslationBefore = *p_stVector;
                entry->firstTranslationApplied = *p_stVector;
                entry->firstTranslationCaptured = true;
            }
        }
        else
        {
            // v0.0.16l.0: generic InitTranslation scaling is disabled.
            // The Astro pirate diagnostic showed that this input can look like
            // an absolute/world-space translation target rather than a velocity.
            // We keep the hook read-only so future reports can still tell us
            // which actors use this path without risking another crash.
            if (
                !entry->firstTranslationCaptured &&
                R2R_StatsVectorHasHorizontalMotion(*p_stVector)
                )
            {
                entry->firstTranslationBefore = *p_stVector;
                entry->firstTranslationApplied = *p_stVector;
                entry->firstTranslationCaptured = true;
            }
        }
    }

    MEC_vInitTranslation(p_stDynamics, p_stSuperObject, p_stVector);

    // The vector belongs to the caller.  The engine call above has already
    // consumed it, so restore the caller-visible value immediately.
    if (translationApplied && p_stVector != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(p_stVector), sizeof(MTH3D_tdstVector)))
    {
        *p_stVector = originalVector;
    }
}

static void R2R_StatsLogActor(
    HIE_tdstSuperObject* superObject,
    GAM_tdstStandardGame* standardGame,
    const char* familyName,
    const char* modelName,
    const char* personalName,
    uint32_t slotKey,
    unsigned int oldHP,
    unsigned int newHP,
    const R2R_StatsSeenEntry* entry
)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_STATS_REPORT, "a");
    if (f == nullptr)
        return;

    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;

    if (
        superObject != nullptr &&
        superObject->p_stGlobalMatrix != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(superObject->p_stGlobalMatrix),
            sizeof(POS_tdstCompletePosition)
        )
        )
    {
        x = superObject->p_stGlobalMatrix->stPos.x;
        y = superObject->p_stGlobalMatrix->stPos.y;
        z = superObject->p_stGlobalMatrix->stPos.z;
    }

    fprintf(
        f,
        "[%04u] %s / %s / %s\n"
        "       IDs=%ld/%ld/%ld  pos=%.3f %.3f %.3f  key=%u\n"
        "       HP %u/%u/%u -> %u/%u/%u\n",
        g_R2RStatsRandomizedCount,
        familyName != nullptr ? familyName : "(null)",
        modelName != nullptr ? modelName : "(null)",
        personalName != nullptr ? personalName : "(null)",
        standardGame != nullptr ? standardGame->lObjectFamilyType : -1,
        standardGame != nullptr ? standardGame->lObjectModelType : -1,
        standardGame != nullptr ? standardGame->lObjectPersonalType : -1,
        x,
        y,
        z,
        slotKey,
        oldHP,
        oldHP,
        oldHP,
        newHP,
        newHP,
        newHP
    );

    if (entry != nullptr && entry->movementProfileAssigned)
    {
        fprintf(
            f,
            "       MOVE multiplier=%.3fx (stImposeSpeed XY via BaseMechanics)\n",
            entry->movementMultiplier
        );
    }
    else
    {
        fprintf(
            f,
            "       MOVE no runtime profile (Dynamics unavailable)\n"
        );
    }

    fclose(f);
}

