static void R2R_StatsAppendMovementActivations()
{
    FILE* f = nullptr;

    for (unsigned int i = 0; i < g_R2RStatsSeenCount; ++i)
    {
        R2R_StatsSeenEntry& entry = g_R2RStatsSeen[i];
        if (
            !entry.movementProfileAssigned ||
            entry.movementActivationLogged ||
            entry.imposeAppliedHits == 0 ||
            entry.superObject == nullptr
            )
        {
            continue;
        }

        if (f == nullptr)
        {
            fopen_s(&f, R2R_STATS_REPORT, "a");
            if (f == nullptr)
                return;

            fprintf(
                f,
                "\nMOVEMENT ACTIVATIONS\n"
                "------------------------------------------------------------\n"
            );
        }

        const char* familyName = HIE_fn_szGetObjectFamilyName(entry.superObject);
        const char* modelName = HIE_fn_szGetObjectModelName(entry.superObject);
        const char* personalName = HIE_fn_szGetObjectPersonalName(entry.superObject);

        fprintf(
            f,
            "[MOVE-ACTIVE] %s / %s / %s multiplier=%.3fx hookHits=%u imposeApplied=%u",
            familyName != nullptr ? familyName : "(null)",
            modelName != nullptr ? modelName : "(null)",
            personalName != nullptr ? personalName : "(null)",
            entry.movementMultiplier,
            entry.movementHookHits,
            entry.imposeAppliedHits
        );

        if (entry.firstImposeCaptured)
        {
            fprintf(
                f,
                " firstXY=(%.4f,%.4f)->(%.4f,%.4f)",
                entry.firstImposeBefore.x,
                entry.firstImposeBefore.y,
                entry.firstImposeApplied.x,
                entry.firstImposeApplied.y
            );
        }

        fprintf(f, "\n");

        entry.movementActivationLogged = true;
        if (!entry.movementObserved)
        {
            entry.movementObserved = true;
            ++g_R2RStatsMovementObservedCount;
        }
    }

    if (f != nullptr)
        fclose(f);
}

static void R2R_StatsAdvanceMovementAudit()
{
    FILE* f = nullptr;

    for (unsigned int i = 0; i < g_R2RStatsSeenCount; ++i)
    {
        R2R_StatsSeenEntry& entry = g_R2RStatsSeen[i];
        if (!entry.movementProfileAssigned || entry.movementAuditLogged)
            continue;

        if (entry.movementProfileFrames < 1000000u)
            ++entry.movementProfileFrames;

        if (entry.movementProfileFrames < 240u)
            continue;

        // 16h: both successful routes are now meaningful.  BaseMechanics remains
        // the primary route; InitTranslation is the fallback for actors that
        // never enter BaseMechanics.
        if (entry.imposeAppliedHits != 0 || entry.translationAppliedHits != 0)
        {
            if (f == nullptr)
            {
                fopen_s(&f, R2R_STATS_REPORT, "a");
                if (f == nullptr)
                    return;

                fprintf(
                    f,
                    "\nMOVEMENT ROUTE AUDIT (~240 frames)\n"
                    "------------------------------------------------------------\n"
                );
            }

            const char* familyName = entry.superObject != nullptr ? HIE_fn_szGetObjectFamilyName(entry.superObject) : nullptr;
            const char* modelName = entry.superObject != nullptr ? HIE_fn_szGetObjectModelName(entry.superObject) : nullptr;
            const char* personalName = entry.superObject != nullptr ? HIE_fn_szGetObjectPersonalName(entry.superObject) : nullptr;

            const char* route = entry.imposeAppliedHits != 0 ? "BASE-IMPOSE" : "INIT-TRANSLATION";
            fprintf(
                f,
                "[MOVE-ROUTE-%s] %s / %s / %s multiplier=%.3fx baseHits=%u imposeApplied=%u translationHits=%u translationApplied=%u\n",
                route,
                familyName != nullptr ? familyName : "(null)",
                modelName != nullptr ? modelName : "(null)",
                personalName != nullptr ? personalName : "(null)",
                entry.movementMultiplier,
                entry.movementHookHits,
                entry.imposeAppliedHits,
                entry.translationHookHits,
                entry.translationAppliedHits
            );

            if (entry.firstTranslationCaptured)
            {
                fprintf(
                    f,
                    "  TRANSLATION first: %.5f %.5f %.5f -> %.5f %.5f %.5f (%.2fx)\n",
                    entry.firstTranslationBefore.x, entry.firstTranslationBefore.y, entry.firstTranslationBefore.z,
                    entry.firstTranslationApplied.x, entry.firstTranslationApplied.y, entry.firstTranslationApplied.z,
                    entry.movementMultiplier
                );
            }

            entry.movementAuditLogged = true;
            continue;
        }

        if (f == nullptr)
        {
            fopen_s(&f, R2R_STATS_REPORT, "a");
            if (f == nullptr)
                return;

            fprintf(
                f,
                "\nMOVEMENT NON-ACTIVATIONS (~240 frames)\n"
                "------------------------------------------------------------\n"
            );
        }

        const char* familyName = entry.superObject != nullptr ? HIE_fn_szGetObjectFamilyName(entry.superObject) : nullptr;
        const char* modelName = entry.superObject != nullptr ? HIE_fn_szGetObjectModelName(entry.superObject) : nullptr;
        const char* personalName = entry.superObject != nullptr ? HIE_fn_szGetObjectPersonalName(entry.superObject) : nullptr;

        fprintf(
            f,
            "[%s] %s / %s / %s multiplier=%.3fx baseHits=%u imposeApplied=%u translationHits=%u translationApplied=%u\n",
            (entry.movementHookHits == 0 && entry.translationHookHits == 0) ? "MOVE-NO-ROUTE" :
            (entry.movementHookHits == 0 ? "MOVE-TRANSLATION-NO-VECTOR" : "MOVE-NO-IMPOSE"),
            familyName != nullptr ? familyName : "(null)",
            modelName != nullptr ? modelName : "(null)",
            personalName != nullptr ? personalName : "(null)",
            entry.movementMultiplier,
            entry.movementHookHits,
            entry.imposeAppliedHits,
            entry.translationHookHits,
            entry.translationAppliedHits
        );

        entry.movementAuditLogged = true;
    }

    if (f != nullptr)
        fclose(f);
}

static void R2R_StatsSampleWorldMovement()
{
    FILE* f = nullptr;

    for (unsigned int i = 0; i < g_R2RStatsSeenCount; ++i)
    {
        R2R_StatsSeenEntry& entry = g_R2RStatsSeen[i];
        if (
            !entry.movementProfileAssigned ||
            entry.positionMeasureLogged ||
            entry.superObject == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject),
                sizeof(HIE_tdstSuperObject)
            ) ||
            entry.superObject->p_stGlobalMatrix == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject->p_stGlobalMatrix),
                sizeof(POS_tdstCompletePosition)
            )
            )
        {
            continue;
        }

        const MTH3D_tdstVector current =
            entry.superObject->p_stGlobalMatrix->stPos;

        if (!R2R_StatsVectorSane(current))
            continue;

        if (!entry.positionSampleInitialized)
        {
            entry.lastWorldPosition = current;
            entry.positionSampleInitialized = true;
            continue;
        }

        const float dx = current.x - entry.lastWorldPosition.x;
        const float dy = current.y - entry.lastWorldPosition.y;
        const float step = std::sqrt(dx * dx + dy * dy);
        entry.lastWorldPosition = current;

        if (!std::isfinite(step) || step > 50.0f)
            continue;

        ++entry.positionSamples;
        if (step > 0.0001f)
        {
            ++entry.positionMovingSamples;
            entry.positionDistanceTotal += step;
            if (step > entry.positionMaxStep)
                entry.positionMaxStep = step;
        }

        if (entry.positionSamples < 240)
            continue;

        if (f == nullptr)
        {
            fopen_s(&f, R2R_STATS_REPORT, "a");
            if (f == nullptr)
                return;

            fprintf(
                f,
                "\nWORLD MOVEMENT MEASUREMENTS (~240 post-engine frames)\n"
                "------------------------------------------------------------\n"
            );
        }

        const char* familyName = HIE_fn_szGetObjectFamilyName(entry.superObject);
        const char* modelName = HIE_fn_szGetObjectModelName(entry.superObject);
        const char* personalName = HIE_fn_szGetObjectPersonalName(entry.superObject);
        const float averageAll =
            entry.positionSamples > 0 ?
            entry.positionDistanceTotal / (float)entry.positionSamples : 0.0f;
        const float averageMoving =
            entry.positionMovingSamples > 0 ?
            entry.positionDistanceTotal / (float)entry.positionMovingSamples : 0.0f;

        fprintf(
            f,
            "[MOVE-MEASURE] %s / %s / %s multiplier=%.3fx imposeApplied=%u samples=%u moving=%u "
            "distance=%.4f avgAll=%.5f avgMoving=%.5f maxStep=%.5f hookHits=%u\n",
            familyName != nullptr ? familyName : "(null)",
            modelName != nullptr ? modelName : "(null)",
            personalName != nullptr ? personalName : "(null)",
            entry.movementMultiplier,
            entry.imposeAppliedHits,
            entry.positionSamples,
            entry.positionMovingSamples,
            entry.positionDistanceTotal,
            averageAll,
            averageMoving,
            entry.positionMaxStep,
            entry.movementHookHits
        );

        if (entry.firstImposeCaptured)
        {
            fprintf(
                f,
                "  IMPOSE TEST first: %.5f %.5f %.5f -> %.5f %.5f %.5f (%.2fx)\n",
                entry.firstImposeBefore.x, entry.firstImposeBefore.y, entry.firstImposeBefore.z,
                entry.firstImposeApplied.x, entry.firstImposeApplied.y, entry.firstImposeApplied.z,
                entry.movementMultiplier
            );
        }

        fprintf(
            f,
            "  DYNAMICS PROFILE (horizontal magnitude; pre=original, post=inside mechanics before restore)\n"
        );

        bool anyDiag = false;
        for (int field = 0; field < R2R_DIAG_FIELD_COUNT; ++field)
        {
            if (
                entry.diagPreHits[field] == 0 &&
                entry.diagPostHits[field] == 0
                )
            {
                continue;
            }

            anyDiag = true;
            fprintf(
                f,
                "    %-25s pre[hits=%u min=%.5f max=%.5f] post[hits=%u min=%.5f max=%.5f]\n",
                g_R2RStatsDiagFieldNames[field],
                entry.diagPreHits[field],
                entry.diagPreHits[field] ? entry.diagPreMin[field] : 0.0f,
                entry.diagPreHits[field] ? entry.diagPreMax[field] : 0.0f,
                entry.diagPostHits[field],
                entry.diagPostHits[field] ? entry.diagPostMin[field] : 0.0f,
                entry.diagPostHits[field] ? entry.diagPostMax[field] : 0.0f
            );
        }

        if (!anyDiag)
        {
            fprintf(
                f,
                "    (no non-zero candidate dynamics vector observed)\n"
            );
        }

        entry.positionMeasureLogged = true;
    }

    if (f != nullptr)
        fclose(f);
}

// v0.0.18x.0: actor-local animation-rate experiment, Jail only.
// Independent from Stats. Exact cinematic doubles are intentionally included;
// the playable Rayman does not match any of these exact cinematic identities.
static const char* R2R_JAIL_RATE_REPORT = "Rayman2Randomizer_Jail20Speed.txt";
struct R2R_JailRateTarget
{
    const char* family;
    const char* model;
    const char* personal;
};
static const R2R_JailRateTarget g_R2RJailRateTargets[] =
{
    { "sbire_globox", "SUN_Sbire_Glob_Cine", "SUN_Sbire_Cine_Intro" },
    { "Globox_Cine", "SUN_Globox_Cinema", "SUN_Glob_Cine_Intro" },
    { "Globox_Cine", "SUN_Globox_Cinema", "SUN_Glob_Cine_Tuyo" },
    { "Lums_Cine", "SUN_Lums_Cinema", "SUN_Lums_Intro01" },
    { "Ray_Intro", "SUN_RayDummy_Intro", "SUN_RayDummy_Intro_Jail" },
    { "Ray_Intro", "SUN_RayDummy_Intro", "SUN_RayDummy_Intro_Tuyo" },
    { "helice", "OLD_Helice01", "SUN_Helice_Start" },
    { "helice", "OLD_Helice01", "SUN_Helice_Fin" }
};
static const unsigned int R2R_JAIL_RATE_TARGET_COUNT =
static_cast<unsigned int>(sizeof(g_R2RJailRateTargets) / sizeof(g_R2RJailRateTargets[0]));
static bool R2R_JailRateIsExactTarget(const char* family, const char* model,
    const char* personal)
{
    if (family == nullptr || model == nullptr || personal == nullptr) return false;
    for (unsigned int i = 0; i < R2R_JAIL_RATE_TARGET_COUNT; ++i)
    {
        const R2R_JailRateTarget& target = g_R2RJailRateTargets[i];
        if (_stricmp(family, target.family) == 0 &&
            _stricmp(model, target.model) == 0 &&
            _stricmp(personal, target.personal) == 0) return true;
    }
    return false;
}
struct R2R_JailRateEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    GAM_tdst3dData* data;
    HIE_tdstState* lastState;
    unsigned int original;
    int loggedMode;
    bool forced;
    unsigned int visit;
};
static R2R_JailRateEntry g_R2RJailRateEntries[R2R_JAIL_RATE_TARGET_COUNT] = {};
static HIE_tdstSuperObject* g_R2RJailRateWorld = nullptr;
static HIE_tdstSuperObject* g_R2RJailRateInactiveWorld = nullptr;
static int g_R2RJailRateMode = 0; // v18p: native animation and movement at startup.
static unsigned int g_R2RJailRateVisit = 0;
static unsigned int g_R2RJailRateFrame = 0;
static bool g_R2RJailRateReportStarted = false;

static bool R2R_JailRateByteWritable(unsigned char* value)
{
    MEMORY_BASIC_INFORMATION info = {};
    if (value == nullptr || VirtualQuery(value, &info, sizeof(info)) == 0)
        return false;
    if (info.State != MEM_COMMIT || (info.Protect & (PAGE_GUARD | PAGE_NOACCESS)))
        return false;
    const DWORD protection = info.Protect & 0xff;
    return protection == PAGE_READWRITE || protection == PAGE_WRITECOPY ||
        protection == PAGE_EXECUTE_READWRITE || protection == PAGE_EXECUTE_WRITECOPY;
}

static void R2R_JailRateLog(unsigned int index, const char* action,
    int mode, unsigned int before, unsigned int after)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_JAIL_RATE_REPORT, "a");
    if (f == nullptr) return;
    const R2R_JailRateTarget& target = g_R2RJailRateTargets[index];
    const R2R_JailRateEntry& entry = g_R2RJailRateEntries[index];
    HIE_tdstState* state = entry.data->h_CurrentState;
    const bool stateReadable = state != nullptr && R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(state), sizeof(HIE_tdstState));
    fprintf(f, "[JAIL-ANIMRATE] %s / %s / %s action=%s mode=%d "
        "original=%u before=%u applied=%u state=%p cSpeedAnim=%d owner=%p data=%p\n",
        target.family, target.model, target.personal, action, mode,
        entry.original, before, after, static_cast<void*>(state),
        stateReadable ? static_cast<int>(state->cSpeedAnim) : -1,
        static_cast<void*>(entry.owner), static_cast<void*>(entry.data));
    fclose(f);
}

static int R2R_JailRateDesiredMode(unsigned int targetIndex)
{
    const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 0;
    if (mode == R2R_STATS_MODE_MIN) return 5;
    if (mode == R2R_STATS_MODE_MAX) return 120;
    if (mode == R2R_STATS_MODE_RANDOM)
    {
        // Jail_20 now gets a different full-range animation roll per exact actor.
        const uint32_t slot =
            0x4A323000u ^
            (targetIndex * 0x9E3779B9u) ^
            (g_R2RStatsPlaytestGeneration * 0x85EBCA6Bu);
        return R2R_RollRange(
            "Stats.Jail20.AnimationRate",
            "Jail_20",
            slot,
            5,
            120
        );
    }
    return g_R2RJailRateMode;
}

static void R2R_JailRateProcess(HIE_tdstSuperObject* object)
{
    if (object == HIE_M_hGetMainActor()) return;
    R2R_NoMomentumObserveLegacyTarget(object);
    if (object == nullptr || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor)
        return;
    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) ||
        actor->h3dData == nullptr || !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actor->h3dData), sizeof(GAM_tdst3dData)))
        return;
    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    if (family == nullptr || model == nullptr || personal == nullptr) return;
    for (unsigned int i = 0; i < R2R_JAIL_RATE_TARGET_COUNT; ++i)
    {
        const R2R_JailRateTarget& target = g_R2RJailRateTargets[i];
        if (_stricmp(family, target.family) || _stricmp(model, target.model) ||
            _stricmp(personal, target.personal)) continue;
        R2R_NoMomentumObserveTarget(object);
        GAM_tdst3dData* data = actor->h3dData;
        if (!R2R_JailRateByteWritable(&data->ucFrameRate)) return;
        R2R_JailRateEntry& entry = g_R2RJailRateEntries[i];
        const unsigned int before = data->ucFrameRate;
        if (entry.owner != object || entry.actor != actor || entry.data != data)
        {
            entry = R2R_JailRateEntry();
            entry.owner = object;
            entry.actor = actor;
            entry.data = data;
            entry.original = before;
            entry.loggedMode = -1;
        }
        // Capture an engine-provided rate whenever it replaces our last write.
        if (!entry.forced || before != static_cast<unsigned int>(entry.loggedMode))
            entry.original = before;
        entry.visit = g_R2RJailRateVisit;
        const int desiredMode = R2R_JailRateDesiredMode(i);
        const bool log = entry.loggedMode != desiredMode ||
            entry.lastState != data->h_CurrentState;
        if (desiredMode == 0)
        {
            // Restore ONCE, then let the engine control the actor normally.
            if (entry.forced)
            {
                data->ucFrameRate = static_cast<unsigned char>(entry.original);
                R2R_JailRateLog(i, "RESTORE", desiredMode, before, data->ucFrameRate);
                entry.forced = false;
            }
            else if (log)
                R2R_JailRateLog(i, "VANILLA", desiredMode, before, before);
        }
        else
        {
            data->ucFrameRate = static_cast<unsigned char>(desiredMode);
            if (log) R2R_JailRateLog(i, "APPLY", desiredMode, before, data->ucFrameRate);
            entry.forced = true;
        }
        entry.loggedMode = desiredMode;
        entry.lastState = data->h_CurrentState;
        return;
    }
}

static void R2R_JailRateScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_JailRateProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr) R2R_JailRateScan(object, depth + 1);
    }
}

static void R2R_JailRateForgetWorld()
{
    // Never restore through cached pointers after a transition.
    std::memset(g_R2RJailRateEntries, 0, sizeof(g_R2RJailRateEntries));
    g_R2RJailRateWorld = nullptr;
    g_R2RJailRateInactiveWorld = nullptr;
    g_R2RJailRateFrame = 0;
}

static void R2R_JailRateTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Jail_20") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_JailRateForgetWorld();
        return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RJailRateWorld || inactive != g_R2RJailRateInactiveWorld)
    {
        R2R_JailRateForgetWorld();
        g_R2RJailRateWorld = active;
        g_R2RJailRateInactiveWorld = inactive;
        FILE* f = nullptr;
        fopen_s(&f, R2R_JAIL_RATE_REPORT, g_R2RJailRateReportStarted ? "a" : "w");
        if (f != nullptr)
        {
            fprintf(f, "\n%s JAIL_20 ANIMATION TEST: %u exact targets, "
                "global Stats controls: F6=MIN F7=MAX F8=RANDOM F12=NATIVE.\n",
                VERSION, R2R_JAIL_RATE_TARGET_COUNT);
            fclose(f);
            g_R2RJailRateReportStarted = true;
        }
    }
    // Jail keys are processed here, before the normal gameplay/research keys.
    ++g_R2RJailRateVisit;
    R2R_JailRateScan(active, 0);
    if (inactive != active) R2R_JailRateScan(inactive, 0);
    // Discard absent actors without dereferencing their cached pointers.
    for (unsigned int i = 0; i < R2R_JAIL_RATE_TARGET_COUNT; ++i)
        if (g_R2RJailRateEntries[i].visit != g_R2RJailRateVisit)
            g_R2RJailRateEntries[i] = R2R_JailRateEntry();
    if ((g_R2RJailRateFrame++ % 300) == 0)
    {
        FILE* f = nullptr;
        fopen_s(&f, R2R_JAIL_RATE_REPORT, "a");
        if (f != nullptr)
        {
            unsigned int found = 0;
            for (unsigned int i = 0; i < R2R_JAIL_RATE_TARGET_COUNT; ++i)
            {
                if (g_R2RJailRateEntries[i].owner != nullptr) ++found;
                else fprintf(f, "[JAIL-NOT-FOUND] %s / %s / %s\n",
                    g_R2RJailRateTargets[i].family, g_R2RJailRateTargets[i].model,
                    g_R2RJailRateTargets[i].personal);
            }
            fprintf(f, "[JAIL-SUMMARY] found=%u/%u globalMode=%d\n", found, R2R_JAIL_RATE_TARGET_COUNT, g_R2RJailRateMode);
            fclose(f);
        }
    }
}

// ============================================================
// v0.0.19b.2.1 - JAIL_20 SAFE MATRIX-SCALE HOOK TEST (COMPILE FIX)
//
// b.1 proved that forcing DNM_C_Flag_Scale on actors whose native scale
// mechanic is OFF can crash the engine. This build returns to the safe
// SuperObject matrix route, but applies it immediately BEFORE the engine's
// HIE relative-matrix computation so the engine can propagate it to rendering.
//
// Exact actors supplied from Raymap/script inspection:
//   - sbire_globox / SUN_Sbire_Glob_Cine / SUN_Sbire_Cine_Intro
//   - Globox_Cine / SUN_Globox_Cinema / SUN_Glob_Cine_Intro
//   - Globox_Cine / SUN_Globox_Cinema / SUN_Glob_Cine_Tuyo
//   - Lums_Cine / SUN_Lums_Cinema / SUN_Lums_Intro01
//   - Ray_Intro / SUN_RayDummy_Intro / SUN_RayDummy_Intro_Jail
//   - Ray_Intro / SUN_RayDummy_Intro / SUN_RayDummy_Intro_Tuyo
//
// Safe/intentional test fields:
//   * visual Scale X/Y/Z independently, absolute 0.5..2.0
//   * Ray_Intro Float_6 / Float_7, each independently x0.25..x4.0
//   * sbire_globox hard-coded imposed Y speed, independently x0.25..x4.0
//
// HP/MaxHP command channels and state-machine DSG vars are deliberately NOT
// randomized. Lums_Cine was added to the Jail exact-target exclusion so its
// HP-as-command channel cannot be mistaken for enemy health.
// ============================================================
static const char* R2R_JAIL20_EXTRA_REPORT = "Rayman2Randomizer_Jail20ExtraStats.txt";
static const unsigned int R2R_JAIL20_EXTRA_TARGET_COUNT = 6;

struct R2R_Jail20ExtraTarget
{
    const char* family;
    const char* model;
    const char* personal;
    bool rayJumpFloats;
    bool sbireImposeY;
};

static const R2R_Jail20ExtraTarget g_R2RJail20ExtraTargets[R2R_JAIL20_EXTRA_TARGET_COUNT] =
{
    { "sbire_globox", "SUN_Sbire_Glob_Cine", "SUN_Sbire_Cine_Intro", false, true },
    { "Globox_Cine", "SUN_Globox_Cinema", "SUN_Glob_Cine_Intro", false, false },
    { "Globox_Cine", "SUN_Globox_Cinema", "SUN_Glob_Cine_Tuyo", false, false },
    { "Lums_Cine", "SUN_Lums_Cinema", "SUN_Lums_Intro01", false, false },
    { "Ray_Intro", "SUN_RayDummy_Intro", "SUN_RayDummy_Intro_Jail", true, false },
    { "Ray_Intro", "SUN_RayDummy_Intro", "SUN_RayDummy_Intro_Tuyo", true, false }
};

struct R2R_Jail20ExtraEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    MTH3D_tdstVector originalScale;
    bool scaleCaptured;
    float originalFloat6;
    float originalFloat7;
    bool float6Captured;
    bool float7Captured;
    R2R_StatsPlaytestMode loggedMode;
    uint32_t loggedGeneration;
    unsigned int visit;
    unsigned int scaleHookHits;
};

static R2R_Jail20ExtraEntry g_R2RJail20ExtraEntries[R2R_JAIL20_EXTRA_TARGET_COUNT] = {};
static HIE_tdstSuperObject* g_R2RJail20ExtraWorld = nullptr;
static HIE_tdstSuperObject* g_R2RJail20ExtraInactiveWorld = nullptr;
static unsigned int g_R2RJail20ExtraVisit = 0;
static bool g_R2RJail20ExtraReportStarted = false;
static bool g_R2RJail20ScaleMatrixHookInstalled = false;

static int R2R_Jail20ExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr || personal == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_JAIL20_EXTRA_TARGET_COUNT; ++i)
    {
        const R2R_Jail20ExtraTarget& t = g_R2RJail20ExtraTargets[i];
        if (_stricmp(family, t.family) == 0 &&
            _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0)
            return static_cast<int>(i);
    }
    return -1;
}

static bool R2R_Jail20ExtraWritable(void* address, size_t bytes)
{
    if (address == nullptr || bytes == 0) return false;
    MEMORY_BASIC_INFORMATION info = {};
    if (VirtualQuery(address, &info, sizeof(info)) == 0) return false;
    if (info.State != MEM_COMMIT || (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const uintptr_t begin = reinterpret_cast<uintptr_t>(address);
    const uintptr_t regionEnd = reinterpret_cast<uintptr_t>(info.BaseAddress) + info.RegionSize;
    if (begin > regionEnd || bytes > regionEnd - begin) return false;
    const DWORD protection = info.Protect & 0xff;
    return protection == PAGE_READWRITE || protection == PAGE_WRITECOPY ||
        protection == PAGE_EXECUTE_READWRITE || protection == PAGE_EXECUTE_WRITECOPY;
}

static float R2R_Jail20VectorLength(const MTH3D_tdstVector& v)
{
    if (!std::isfinite(v.x) || !std::isfinite(v.y) || !std::isfinite(v.z)) return 0.0f;
    const float length = std::sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
    return std::isfinite(length) ? length : 0.0f;
}

static MTH3D_tdstVector R2R_Jail20MatrixScale(const POS_tdstCompletePosition* matrix)
{
    MTH3D_tdstVector result = { 1.0f, 1.0f, 1.0f };
    if (matrix == nullptr || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(matrix), sizeof(POS_tdstCompletePosition)))
        return result;
    const float x = R2R_Jail20VectorLength(matrix->stTransformMatrix.stCol_0);
    const float y = R2R_Jail20VectorLength(matrix->stTransformMatrix.stCol_1);
    const float z = R2R_Jail20VectorLength(matrix->stTransformMatrix.stCol_2);
    if (x > 0.0001f && x < 1000.0f) result.x = x;
    if (y > 0.0001f && y < 1000.0f) result.y = y;
    if (z > 0.0001f && z < 1000.0f) result.z = z;
    return result;
}

static bool R2R_Jail20ScaleColumn(MTH3D_tdstVector& column, float target)
{
    const float length = R2R_Jail20VectorLength(column);
    if (!(length > 0.0001f) || !(length < 1000.0f) || !std::isfinite(target) || target <= 0.0f)
        return false;
    const float factor = target / length;
    column.x *= factor;
    column.y *= factor;
    column.z *= factor;
    return true;
}

static bool R2R_Jail20ApplyMatrixScale(POS_tdstCompletePosition* matrix, const MTH3D_tdstVector& scale)
{
    if (matrix == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(matrix), sizeof(POS_tdstCompletePosition)) ||
        !R2R_Jail20ExtraWritable(matrix, sizeof(POS_tdstCompletePosition)))
        return false;
    bool ok = true;
    ok = R2R_Jail20ScaleColumn(matrix->stTransformMatrix.stCol_0, scale.x) && ok;
    ok = R2R_Jail20ScaleColumn(matrix->stTransformMatrix.stCol_1, scale.y) && ok;
    ok = R2R_Jail20ScaleColumn(matrix->stTransformMatrix.stCol_2, scale.z) && ok;
    return ok;
}

static float R2R_Jail20RandomMilli(const char* stream, unsigned int target, unsigned int field,
    float minValue, float maxValue)
{
    const int minMilli = static_cast<int>(minValue * 1000.0f + 0.5f);
    const int maxMilli = static_cast<int>(maxValue * 1000.0f + 0.5f);
    const uint32_t slot =
        0x4A323000u ^
        (target * 0x9E3779B9u) ^
        (field * 0x85EBCA6Bu) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange(stream, "Jail_20", slot, minMilli, maxMilli) / 1000.0f;
}

static MTH3D_tdstVector R2R_Jail20DesiredScale(unsigned int target,
    const MTH3D_tdstVector& original)
{
    const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return original;
    if (mode == R2R_STATS_MODE_MIN) return MTH3D_tdstVector{ 0.5f, 0.5f, 0.5f };
    if (mode == R2R_STATS_MODE_MAX) return MTH3D_tdstVector{ 2.0f, 2.0f, 2.0f };
    if (mode == R2R_STATS_MODE_RANDOM)
    {
        return MTH3D_tdstVector{
            R2R_Jail20RandomMilli("Stats.Jail20.ScaleX", target, 0, 0.5f, 2.0f),
            R2R_Jail20RandomMilli("Stats.Jail20.ScaleY", target, 1, 0.5f, 2.0f),
            R2R_Jail20RandomMilli("Stats.Jail20.ScaleZ", target, 2, 0.5f, 2.0f)
        };
    }
    return original;
}

static float R2R_Jail20DesiredFactor(unsigned int target, unsigned int field)
{
    const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return 0.25f;
    if (mode == R2R_STATS_MODE_MAX) return 4.0f;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Jail20RandomMilli("Stats.Jail20.PhysicsFactor", target, field, 0.25f, 4.0f);
    return 1.0f;
}

static bool R2R_Jail20GetFloatDsg(HIE_tdstSuperObject* object, unsigned char id, float*& value)
{
    value = nullptr;
    AI_tdeDsgVarType type = AI_E_Nb_dvt;
    void* raw = nullptr;
    if (!AI_fn_bGetDsgVar(object, id, &type, &raw) || raw == nullptr || type != AI_E_dvt_Float ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), sizeof(float)) ||
        !R2R_Jail20ExtraWritable(raw, sizeof(float)))
        return false;
    value = reinterpret_cast<float*>(raw);
    return true;
}

static void R2R_Jail20ExtraLog(unsigned int target, const R2R_Jail20ExtraEntry& entry,
    const MTH3D_tdstVector& scale, const float* float6, const float* float7)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_JAIL20_EXTRA_REPORT, g_R2RJail20ExtraReportStarted ? "a" : "w");
    if (f == nullptr) return;
    if (!g_R2RJail20ExtraReportStarted)
    {
        fprintf(f,
            "RAYMAN 2 RANDOMIZER\n%s - JAIL_20 SAFE MATRIX-SCALE HOOK TEST\n"
            "============================================================\n"
            "Scale X/Y/Z: independent 0.500..2.000 via HIE relative-matrix pre-hook\n"
            "Ray Float_6/Float_7: independent x0.250..x4.000 of captured native value\n"
            "sbire imposed Y speed: independent x0.250..x4.000 in BaseMechanics\n"
            "HP-as-command DSG/state-machine values are excluded.\n\n", VERSION);
        g_R2RJail20ExtraReportStarted = true;
    }
    const R2R_Jail20ExtraTarget& t = g_R2RJail20ExtraTargets[target];
    fprintf(f,
        "[JAIL20-EXTRA] %s / %s / %s mode=%s generation=%u "
        "scale=(%.3f %.3f %.3f)",
        t.family, t.model, t.personal, R2R_StatsModeName(R2R_StatsEffectiveMode()),
        g_R2RStatsPlaytestGeneration, scale.x, scale.y, scale.z);
    fprintf(f, " scaleHook=%s scaleHookHits=%u",
        g_R2RJail20ScaleMatrixHookInstalled ? "YES" : "NO", entry.scaleHookHits);
    if (float6 != nullptr) fprintf(f, " Float_6=%.6g(native %.6g)", *float6, entry.originalFloat6);
    if (float7 != nullptr) fprintf(f, " Float_7=%.6g(native %.6g)", *float7, entry.originalFloat7);
    if (t.sbireImposeY)
        fprintf(f, " sbireYFactor=%.3f", R2R_Jail20DesiredFactor(target, 20));
    fprintf(f, "\n");
    fclose(f);
}

static void R2R_Jail20ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr || object == HIE_M_hGetMainActor() ||
        object->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)))
        return;
    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)))
        return;
    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int targetIndex = R2R_Jail20ExtraFindTarget(family, model, personal);
    if (targetIndex < 0) return;
    const unsigned int target = static_cast<unsigned int>(targetIndex);
    R2R_Jail20ExtraEntry& e = g_R2RJail20ExtraEntries[target];
    if (e.owner != object || e.actor != actor)
    {
        e = R2R_Jail20ExtraEntry();
        e.owner = object;
        e.actor = actor;
        e.loggedMode = R2R_STATS_MODE_AUTO;
        e.loggedGeneration = UINT32_MAX;
    }
    e.visit = g_R2RJail20ExtraVisit;

    POS_tdstCompletePosition* local = object->p_stLocalMatrix;
    POS_tdstCompletePosition* global = object->p_stGlobalMatrix;
    if (!e.scaleCaptured)
    {
        e.originalScale = R2R_Jail20MatrixScale(local != nullptr ? local : global);
        e.scaleCaptured = true;
    }
    const MTH3D_tdstVector desiredScale = R2R_Jail20DesiredScale(target, e.originalScale);
    // Do NOT write scale here. At this point in the frame Rayman 2 can rebuild
    // the relative/global matrices afterward. The HIE hook below applies the
    // requested local scale immediately before that computation instead.

    float* float6 = nullptr;
    float* float7 = nullptr;
    if (g_R2RJail20ExtraTargets[target].rayJumpFloats)
    {
        if (R2R_Jail20GetFloatDsg(object, 6, float6))
        {
            if (!e.float6Captured && std::isfinite(*float6))
            {
                e.originalFloat6 = *float6;
                e.float6Captured = true;
            }
            if (e.float6Captured)
                *float6 = e.originalFloat6 * R2R_Jail20DesiredFactor(target, 6);
        }
        if (R2R_Jail20GetFloatDsg(object, 7, float7))
        {
            if (!e.float7Captured && std::isfinite(*float7))
            {
                e.originalFloat7 = *float7;
                e.float7Captured = true;
            }
            if (e.float7Captured)
                *float7 = e.originalFloat7 * R2R_Jail20DesiredFactor(target, 7);
        }
    }

    const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
    if (e.loggedMode != mode || e.loggedGeneration != g_R2RStatsPlaytestGeneration)
    {
        R2R_Jail20ExtraLog(target, e, desiredScale,
            e.float6Captured ? float6 : nullptr, e.float7Captured ? float7 : nullptr);
        e.loggedMode = mode;
        e.loggedGeneration = g_R2RStatsPlaytestGeneration;
    }
}


static void R2R_HookedComputeNewRelativeMatrix(HIE_tdstSuperObject* object)
{
    // This hook is deliberately narrow: Jail_20 + the six exact Raymap actors.
    // We only edit the already-existing local scale matrix. No Dynamics flags,
    // mechanics modes, AI state, or pointers are enabled/changed here.
    if (object != nullptr &&
        g_R2RConfig.enabled &&
        GAM_g_stEngineStructure != nullptr &&
        GAM_g_stEngineStructure->eEngineMode == E_EM_ModePlaying &&
        GAM_g_stEngineStructure->szLevelName != nullptr &&
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Jail_20") == 0 &&
        object->ulType == HIE_C_Type_Actor &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)))
    {
        const char* family = HIE_fn_szGetObjectFamilyName(object);
        const char* model = HIE_fn_szGetObjectModelName(object);
        const char* personal = HIE_fn_szGetObjectPersonalName(object);
        const int targetIndex = R2R_Jail20ExtraFindTarget(family, model, personal);

        if (targetIndex >= 0)
        {
            const unsigned int target = static_cast<unsigned int>(targetIndex);
            R2R_Jail20ExtraEntry& e = g_R2RJail20ExtraEntries[target];
            HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);

            // The hook can run before the normal per-frame Jail_20 scanner.
            if (e.owner != object || e.actor != actor)
            {
                e = R2R_Jail20ExtraEntry();
                e.owner = object;
                e.actor = actor;
                e.loggedMode = R2R_STATS_MODE_AUTO;
                e.loggedGeneration = UINT32_MAX;
            }

            POS_tdstCompletePosition* local = object->p_stLocalMatrix;
            POS_tdstCompletePosition* global = object->p_stGlobalMatrix;

            if (!e.scaleCaptured)
            {
                e.originalScale = R2R_Jail20MatrixScale(local != nullptr ? local : global);
                e.scaleCaptured = true;
            }

            if (local != nullptr)
            {
                const MTH3D_tdstVector desired =
                    R2R_Jail20DesiredScale(target, e.originalScale);

                if (R2R_Jail20ApplyMatrixScale(local, desired))
                    ++e.scaleHookHits;
            }
        }
    }

    // FHK keeps this symbol pointing at the original/trampoline while inside
    // the detour, same pattern as the existing mechanics/sound hooks.
    HIE_fn_vComputeNewRelativeMatrix(object);
}

static void R2R_Jail20ExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject)))
        return;
    R2R_Jail20ExtraProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr) R2R_Jail20ExtraScan(object, depth + 1);
    }
}

static void R2R_Jail20ExtraForgetWorld()
{
    std::memset(g_R2RJail20ExtraEntries, 0, sizeof(g_R2RJail20ExtraEntries));
    g_R2RJail20ExtraWorld = nullptr;
    g_R2RJail20ExtraInactiveWorld = nullptr;
}

static void R2R_Jail20ExtraTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Jail_20") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Jail20ExtraForgetWorld();
        return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RJail20ExtraWorld || inactive != g_R2RJail20ExtraInactiveWorld)
    {
        R2R_Jail20ExtraForgetWorld();
        g_R2RJail20ExtraWorld = active;
        g_R2RJail20ExtraInactiveWorld = inactive;
    }
    ++g_R2RJail20ExtraVisit;
    R2R_Jail20ExtraScan(active, 0);
    if (inactive != active) R2R_Jail20ExtraScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_JAIL20_EXTRA_TARGET_COUNT; ++i)
        if (g_R2RJail20ExtraEntries[i].visit != g_R2RJail20ExtraVisit)
            g_R2RJail20ExtraEntries[i] = R2R_Jail20ExtraEntry();
}

static bool R2R_Jail20SbireBeginMechanics(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, float& originalY, float& appliedY)
{
    if (object == nullptr || dynamics == nullptr ||
        R2R_StatsEffectiveMode() == R2R_STATS_MODE_NATIVE ||
        GAM_g_stEngineStructure == nullptr ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Jail_20") != 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        return false;
    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int targetIndex = R2R_Jail20ExtraFindTarget(family, model, personal);
    if (targetIndex < 0 || !g_R2RJail20ExtraTargets[targetIndex].sbireImposeY) return false;
    DNM_tdstDynamicsBaseBlock& base = dynamics->stDynamicsBase;
    if (!std::isfinite(base.stImposeSpeed.y) || std::fabs(base.stImposeSpeed.y) < 0.0001f) return false;
    originalY = base.stImposeSpeed.y;
    const float factor = R2R_Jail20DesiredFactor(static_cast<unsigned int>(targetIndex), 20);
    appliedY = originalY * factor;
    if (!std::isfinite(appliedY)) return false;
    base.stImposeSpeed.y = appliedY;
    return true;
}

static void R2R_Jail20SbireEndMechanics(DNM_tdstDynamics* dynamics, float originalY)
{
    if (dynamics == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        return;
    dynamics->stDynamicsBase.stImposeSpeed.y = originalY;
}


