static int R2R_Learn10ExtraFindTarget(
    const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr || personal == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_LEARN10_EXTRA_TARGET_COUNT; ++i)
    {
        const R2R_Learn10ExtraTarget& t = g_R2RLearn10ExtraTargets[i];
        if (_stricmp(family, t.family) == 0 &&
            _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0)
            return static_cast<int>(i);
    }
    return -1;
}

static bool R2R_Learn10ExtraWritable(void* address, size_t bytes)
{
    if (address == nullptr || bytes == 0) return false;
    MEMORY_BASIC_INFORMATION info = {};
    if (VirtualQuery(address, &info, sizeof(info)) == 0) return false;
    if (info.State != MEM_COMMIT || (info.Protect & (PAGE_GUARD | PAGE_NOACCESS)))
        return false;
    const uintptr_t begin = reinterpret_cast<uintptr_t>(address);
    const uintptr_t regionEnd =
        reinterpret_cast<uintptr_t>(info.BaseAddress) + info.RegionSize;
    if (begin > regionEnd || bytes > regionEnd - begin) return false;
    const DWORD protection = info.Protect & 0xff;
    return protection == PAGE_READWRITE || protection == PAGE_WRITECOPY ||
        protection == PAGE_EXECUTE_READWRITE ||
        protection == PAGE_EXECUTE_WRITECOPY;
}

static bool R2R_Learn10ExtraGetFloat(
    HIE_tdstSuperObject* object, unsigned char dsgIndex, float*& value)
{
    value = nullptr;
    AI_tdeDsgVarType type = AI_E_Nb_dvt;
    void* raw = nullptr;
    if (!AI_fn_bGetDsgVar(object, dsgIndex, &type, &raw) ||
        raw == nullptr || type != AI_E_dvt_Float ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), sizeof(float)) ||
        !R2R_Learn10ExtraWritable(raw, sizeof(float)))
        return false;
    value = reinterpret_cast<float*>(raw);
    return true;
}

static float R2R_Learn10ExtraRandomFactor(
    unsigned int target, unsigned int field,
    float minFactor, float maxFactor)
{
    const int minMilli = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int maxMilli = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t slot =
        0x4C313000u ^
        (target * 0x9E3779B9u) ^
        (field * 0x85EBCA6Bu) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange(
        "Stats.Learn10.Factor",
        "Learn_10",
        slot,
        minMilli,
        maxMilli
    ) / 1000.0f;
}

static float R2R_Learn10ExtraDesiredFactor(
    unsigned int target, unsigned int fieldSlot)
{
    if (target >= R2R_LEARN10_EXTRA_TARGET_COUNT ||
        fieldSlot >= g_R2RLearn10ExtraTargets[target].fieldCount)
        return 1.0f;

    const R2R_Learn10ExtraField& field =
        g_R2RLearn10ExtraTargets[target].fields[fieldSlot];

    const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return field.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return field.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Learn10ExtraRandomFactor(
            target, fieldSlot, field.minFactor, field.maxFactor);
    return 1.0f;
}

static float R2R_Learn10ExtraDesiredMotionFactor(unsigned int target)
{
    if (target >= R2R_LEARN10_EXTRA_TARGET_COUNT ||
        !g_R2RLearn10ExtraTargets[target].mechanicsDt)
        return 1.0f;

    const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return 0.25f;
    if (mode == R2R_STATS_MODE_MAX) return 4.0f;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Learn10ExtraRandomFactor(target, 100, 0.25f, 4.0f);
    return 1.0f;
}

static void R2R_Learn10ExtraStartReport()
{
    if (g_R2RLearn10ExtraReportStarted) return;
    FILE* f = nullptr;
    fopen_s(&f, R2R_LEARN10_EXTRA_REPORT, "w");
    if (f == nullptr) return;
    fprintf(f,
        "RAYMAN 2 RANDOMIZER\n"
        "%s - LEARN_10 EXPANDED SELECTIVE STATS\n"
        "============================================================\n"
        "F6=MIN, F7=MAX, F8=RANDOM/REROLL, F12=NATIVE\n"
        "Movement-speed factors: x0.250..x4.000\n"
        "Activation/opening-distance factors: x0.500..x2.000\n"
        "DSG arrays, waypoints, graphs, camera fields, action selectors and "
        "HP-as-command channels are protected.\n\n",
        VERSION);
    fclose(f);
    g_R2RLearn10ExtraReportStarted = true;
}

static void R2R_Learn10ExtraLog(
    unsigned int target, const R2R_Learn10ExtraEntry& entry,
    const float current[2])
{
    if (target >= R2R_LEARN10_EXTRA_TARGET_COUNT) return;
    R2R_Learn10ExtraStartReport();

    FILE* f = nullptr;
    fopen_s(&f, R2R_LEARN10_EXTRA_REPORT, "a");
    if (f == nullptr) return;

    const R2R_Learn10ExtraTarget& t = g_R2RLearn10ExtraTargets[target];
    fprintf(f,
        "[LEARN10-EXTRA] %s / %s / %s mode=%s generation=%u",
        t.family, t.model, t.personal,
        R2R_StatsModeName(R2R_StatsEffectiveMode()),
        g_R2RStatsPlaytestGeneration);

    for (unsigned int i = 0; i < t.fieldCount; ++i)
    {
        if (!entry.captured[i]) continue;
        fprintf(f,
            " | %s native=%.6g current=%.6g factor=%.3f",
            t.fields[i].label != nullptr ? t.fields[i].label : "field",
            entry.original[i],
            current[i],
            R2R_Learn10ExtraDesiredFactor(target, i));
    }

    if (t.mechanicsDt)
        fprintf(f,
            " | mechanicsDTFactor=%.3f hits=%u",
            R2R_Learn10ExtraDesiredMotionFactor(target),
            entry.mechanicsDtHits);

    fprintf(f, "\n");
    fclose(f);
}

static void R2R_Learn10ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr || object == HIE_M_hGetMainActor() ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(object),
            sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor)
        return;

    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int targetIndex =
        R2R_Learn10ExtraFindTarget(family, model, personal);
    if (targetIndex < 0) return;

    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actor),
            sizeof(HIE_tdstEngineObject)))
        return;

    const unsigned int target = static_cast<unsigned int>(targetIndex);
    const R2R_Learn10ExtraTarget& spec =
        g_R2RLearn10ExtraTargets[target];
    R2R_Learn10ExtraEntry& entry =
        g_R2RLearn10ExtraEntries[target];

    if (entry.owner != object || entry.actor != actor)
    {
        entry = R2R_Learn10ExtraEntry();
        entry.owner = object;
        entry.actor = actor;
        entry.loggedMode = R2R_STATS_MODE_AUTO;
        entry.loggedGeneration = UINT32_MAX;
    }

    entry.visit = g_R2RLearn10ExtraVisit;

    float current[2] = { 0.0f, 0.0f };
    for (unsigned int i = 0; i < spec.fieldCount; ++i)
    {
        float* address = nullptr;
        if (!R2R_Learn10ExtraGetFloat(
            object, spec.fields[i].dsgIndex, address))
            continue;

        const float before = *address;
        if (!std::isfinite(before) ||
            std::fabs(before) > 100000.0f)
            continue;

        // If the native AI changed the value behind our back, that new value
        // becomes the baseline instead of forcing an obsolete capture.
        if (!entry.captured[i] ||
            !entry.forced[i] ||
            before != entry.lastApplied[i])
        {
            entry.original[i] = before;
            entry.captured[i] = true;
        }

        float applied = before;
        const R2R_StatsPlaytestMode mode =
            R2R_StatsEffectiveMode();

        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (entry.forced[i] &&
                before == entry.lastApplied[i] &&
                entry.captured[i])
            {
                applied = entry.original[i];
            }
            entry.forced[i] = false;
        }
        else if (entry.captured[i])
        {
            const float factor =
                R2R_Learn10ExtraDesiredFactor(target, i);
            const float desired = entry.original[i] * factor;
            if (std::isfinite(desired) &&
                desired > 0.0001f &&
                desired <= 100000.0f)
            {
                applied = desired;
                entry.forced[i] = true;
            }
        }

        if (applied != before)
            *address = applied;

        entry.lastApplied[i] = applied;
        current[i] = applied;
    }

    const R2R_StatsPlaytestMode mode =
        R2R_StatsEffectiveMode();
    if (entry.loggedMode != mode ||
        entry.loggedGeneration != g_R2RStatsPlaytestGeneration)
    {
        R2R_Learn10ExtraLog(target, entry, current);
        entry.loggedMode = mode;
        entry.loggedGeneration = g_R2RStatsPlaytestGeneration;
    }
}

static void R2R_Learn10ExtraScan(
    HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(root),
            sizeof(HIE_tdstSuperObject)))
        return;

    R2R_Learn10ExtraProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr)
            R2R_Learn10ExtraScan(object, depth + 1);
    }
}

static void R2R_Learn10ExtraForgetWorld()
{
    std::memset(
        g_R2RLearn10ExtraEntries,
        0,
        sizeof(g_R2RLearn10ExtraEntries));
    g_R2RLearn10ExtraWorld = nullptr;
    g_R2RLearn10ExtraInactiveWorld = nullptr;
    g_R2RLearn10ExtraFrame = 0;
}

static void R2R_Learn10ExtraTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(
            GAM_g_stEngineStructure->szLevelName,
            "Learn_10") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Learn10ExtraForgetWorld();
        return;
    }

    HIE_tdstSuperObject* active =
        *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive =
        GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld
        : nullptr;

    if (active != g_R2RLearn10ExtraWorld ||
        inactive != g_R2RLearn10ExtraInactiveWorld)
    {
        R2R_Learn10ExtraForgetWorld();
        g_R2RLearn10ExtraWorld = active;
        g_R2RLearn10ExtraInactiveWorld = inactive;
        R2R_Learn10ExtraStartReport();
    }

    ++g_R2RLearn10ExtraVisit;
    R2R_Learn10ExtraScan(active, 0);
    if (inactive != active)
        R2R_Learn10ExtraScan(inactive, 0);

    for (unsigned int i = 0;
        i < R2R_LEARN10_EXTRA_TARGET_COUNT;
        ++i)
    {
        if (g_R2RLearn10ExtraEntries[i].visit !=
            g_R2RLearn10ExtraVisit)
        {
            g_R2RLearn10ExtraEntries[i] =
                R2R_Learn10ExtraEntry();
        }
    }

    ++g_R2RLearn10ExtraFrame; // retained for diagnostics; periodic summary spam disabled.

}

// Scale only the actor's mechanics time for motion routes that are hard-coded
// in Learn_10 scripts. This avoids patching script constants such as 3, 4,
// -4, jump vectors, mosquito pursuit coefficients, or shared mechanics data.
static MTH_tdxReal R2R_Learn10MechanicsDT(
    HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics,
    MTH_tdxReal dt)
{
    if (object == nullptr || dynamics == nullptr ||
        object == HIE_M_hGetMainActor() ||
        R2R_StatsEffectiveMode() == R2R_STATS_MODE_NATIVE ||
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(
            GAM_g_stEngineStructure->szLevelName,
            "Learn_10") != 0 ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(object),
            sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(dynamics),
            sizeof(DNM_tdstDynamicsBaseBlock)))
        return dt;

    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int targetIndex =
        R2R_Learn10ExtraFindTarget(family, model, personal);
    if (targetIndex < 0) return dt;

    const unsigned int target =
        static_cast<unsigned int>(targetIndex);
    if (!g_R2RLearn10ExtraTargets[target].mechanicsDt)
        return dt;

    if (!std::isfinite(dt) ||
        dt <= 0 ||
        dt > 0.25f)
        return dt;

    const float factor =
        R2R_Learn10ExtraDesiredMotionFactor(target);
    MTH_tdxReal applied =
        static_cast<MTH_tdxReal>(dt * factor);

    // Match the already validated ARG_Rayseau mechanics-DT safety envelope
    // used by other level modules.
    if (!std::isfinite(applied) ||
        applied <= 0 ||
        applied > 1.0f)
        return dt;

    R2R_Learn10ExtraEntry& entry =
        g_R2RLearn10ExtraEntries[target];
    if (entry.owner == object)
    {
        // Force one post-engine report line after the first actual mechanics hit
        // so the log proves that this actor's hard-coded motion path was reached.
        if (entry.mechanicsDtHits == 0)
            entry.loggedGeneration = UINT32_MAX;
        ++entry.mechanicsDtHits;
    }

    return applied;
}


