static const unsigned int R2R_MAPMONDE_EXTRA_TARGET_COUNT =
static_cast<unsigned int>(sizeof(g_R2RMapMondeExtraTargets) / sizeof(g_R2RMapMondeExtraTargets[0]));

struct R2R_MapMondeExtraEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    float original[3];
    float lastApplied[3];
    bool captured[3];
    bool forced[3];
    unsigned int visit;
    unsigned int mechanicsDtHits;
    R2R_StatsPlaytestMode loggedMode;
    uint32_t loggedGeneration;
};

static R2R_MapMondeExtraEntry g_R2RMapMondeExtraEntries[R2R_MAPMONDE_EXTRA_TARGET_COUNT] = {};
static HIE_tdstSuperObject* g_R2RMapMondeExtraWorld = nullptr;
static HIE_tdstSuperObject* g_R2RMapMondeExtraInactiveWorld = nullptr;
static unsigned int g_R2RMapMondeExtraVisit = 0;
static bool g_R2RMapMondeExtraReportStarted = false;

static int R2R_MapMondeExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr || personal == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_MAPMONDE_EXTRA_TARGET_COUNT; ++i)
    {
        const R2R_MapMondeExtraTarget& t = g_R2RMapMondeExtraTargets[i];
        if (_stricmp(family, t.family) == 0 &&
            _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0)
            return static_cast<int>(i);
    }
    return -1;
}

static bool R2R_MapMondeExtraGetField(HIE_tdstSuperObject* object,
    const R2R_MapMondeExtraField& field, void*& raw, float& current)
{
    raw = nullptr;
    current = 0.0f;
    AI_tdeDsgVarType type = AI_E_Nb_dvt;
    if (!AI_fn_bGetDsgVar(object, field.dsgIndex, &type, &raw) || raw == nullptr)
        return false;

    if (field.kind == R2R_MAPFIELD_FLOAT)
    {
        if (type != AI_E_dvt_Float ||
            !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), sizeof(float)) ||
            !R2R_Learn10ExtraWritable(raw, sizeof(float)))
            return false;
        current = *reinterpret_cast<float*>(raw);
        return std::isfinite(current);
    }

    if (field.kind == R2R_MAPFIELD_INT)
    {
        if (type != AI_E_dvt_Integer ||
            !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), sizeof(int)) ||
            !R2R_Learn10ExtraWritable(raw, sizeof(int)))
            return false;
        current = static_cast<float>(*reinterpret_cast<int*>(raw));
        return std::isfinite(current);
    }

    return false;
}

static void R2R_MapMondeExtraWriteField(const R2R_MapMondeExtraField& field,
    void* raw, float value)
{
    if (raw == nullptr || !std::isfinite(value)) return;
    if (field.kind == R2R_MAPFIELD_FLOAT)
    {
        *reinterpret_cast<float*>(raw) = value;
    }
    else
    {
        int v = static_cast<int>(value + 0.5f);
        if (v < 1) v = 1;
        *reinterpret_cast<int*>(raw) = v;
    }
}

static float R2R_MapMondeExtraRandomFactor(unsigned int target, unsigned int field,
    float minFactor, float maxFactor)
{
    const int minMilli = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int maxMilli = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t slot = 0x4D4D3000u ^
        (target * 0x9E3779B9u) ^
        (field * 0x85EBCA6Bu) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange("Stats.Mapmonde.Factor", "Mapmonde", slot,
        minMilli, maxMilli) / 1000.0f;
}

static float R2R_MapMondeExtraDesiredFieldFactor(unsigned int target, unsigned int fieldSlot)
{
    if (target >= R2R_MAPMONDE_EXTRA_TARGET_COUNT ||
        fieldSlot >= g_R2RMapMondeExtraTargets[target].fieldCount)
        return 1.0f;
    const R2R_MapMondeExtraField& field = g_R2RMapMondeExtraTargets[target].fields[fieldSlot];
    const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return field.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return field.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_MapMondeExtraRandomFactor(target, fieldSlot, field.minFactor, field.maxFactor);
    return 1.0f;
}

static float R2R_MapMondeExtraDesiredMotionFactor(unsigned int target)
{
    if (target >= R2R_MAPMONDE_EXTRA_TARGET_COUNT ||
        !g_R2RMapMondeExtraTargets[target].mechanicsDt)
        return 1.0f;
    const R2R_MapMondeExtraTarget& t = g_R2RMapMondeExtraTargets[target];
    const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return t.motionMin;
    if (mode == R2R_STATS_MODE_MAX) return t.motionMax;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_MapMondeExtraRandomFactor(target, 100, t.motionMin, t.motionMax);
    return 1.0f;
}

static void R2R_MapMondeExtraStartReport()
{
    if (g_R2RMapMondeExtraReportStarted) return;
    FILE* f = nullptr;
    fopen_s(&f, R2R_MAPMONDE_EXTRA_REPORT, "w");
    if (f == nullptr) return;
    fprintf(f,
        "RAYMAN 2 RANDOMIZER\n"
        "%s - MAPMONDE EXPANDED SELECTIVE STATS\n"
        "============================================================\n"
        "F6=MIN, F7=MAX, F8=RANDOM/REROLL, F12=NATIVE\n"
        "Normal motion factors: x0.250..x4.000\n"
        "YAM_RayMonde conservative motion: x0.500..x2.000\n"
        "Activation/trigger distances: x0.500..x2.000\n"
        "Global Fix Rayman, graphs, waypoints, arrays and action/state selectors are protected.\n\n",
        VERSION);
    fclose(f);
    g_R2RMapMondeExtraReportStarted = true;
}

static void R2R_MapMondeExtraLog(unsigned int target,
    const R2R_MapMondeExtraEntry& entry, const float current[3])
{
    if (target >= R2R_MAPMONDE_EXTRA_TARGET_COUNT) return;
    R2R_MapMondeExtraStartReport();
    FILE* f = nullptr;
    fopen_s(&f, R2R_MAPMONDE_EXTRA_REPORT, "a");
    if (f == nullptr) return;
    const R2R_MapMondeExtraTarget& t = g_R2RMapMondeExtraTargets[target];
    fprintf(f, "[MAPMONDE-EXTRA] %s / %s / %s mode=%s generation=%u",
        t.family, t.model, t.personal,
        R2R_StatsModeName(R2R_StatsEffectiveMode()),
        g_R2RStatsPlaytestGeneration);
    for (unsigned int i = 0; i < t.fieldCount; ++i)
    {
        if (!entry.captured[i]) continue;
        fprintf(f, " | %s native=%.6g current=%.6g factor=%.3f",
            t.fields[i].label != nullptr ? t.fields[i].label : "field",
            entry.original[i], current[i],
            R2R_MapMondeExtraDesiredFieldFactor(target, i));
    }
    if (t.mechanicsDt)
        fprintf(f, " | mechanicsDTFactor=%.3f hits=%u",
            R2R_MapMondeExtraDesiredMotionFactor(target), entry.mechanicsDtHits);
    fprintf(f, "\n");
    fclose(f);
}

static void R2R_MapMondeExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor)
        return;

    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int targetIndex = R2R_MapMondeExtraFindTarget(family, model, personal);
    if (targetIndex < 0) return;

    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)))
        return;

    const unsigned int target = static_cast<unsigned int>(targetIndex);
    const R2R_MapMondeExtraTarget& spec = g_R2RMapMondeExtraTargets[target];
    R2R_MapMondeExtraEntry& entry = g_R2RMapMondeExtraEntries[target];
    if (entry.owner != object || entry.actor != actor)
    {
        entry = R2R_MapMondeExtraEntry();
        entry.owner = object;
        entry.actor = actor;
        entry.loggedMode = R2R_STATS_MODE_AUTO;
        entry.loggedGeneration = UINT32_MAX;
    }
    entry.visit = g_R2RMapMondeExtraVisit;

    float current[3] = { 0.0f, 0.0f, 0.0f };
    for (unsigned int i = 0; i < spec.fieldCount; ++i)
    {
        const R2R_MapMondeExtraField& field = spec.fields[i];
        void* raw = nullptr;
        float before = 0.0f;
        if (!R2R_MapMondeExtraGetField(object, field, raw, before)) continue;
        if (!std::isfinite(before) || std::fabs(before) > 100000.0f) continue;

        if (!entry.captured[i] || !entry.forced[i] || before != entry.lastApplied[i])
        {
            entry.original[i] = before;
            entry.captured[i] = true;
        }

        float applied = before;
        const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (entry.forced[i] && before == entry.lastApplied[i] && entry.captured[i])
                applied = entry.original[i];
            entry.forced[i] = false;
        }
        else if (entry.captured[i])
        {
            const float factor = R2R_MapMondeExtraDesiredFieldFactor(target, i);
            float desired = entry.original[i] * factor;
            if (field.kind == R2R_MAPFIELD_INT)
            {
                desired = static_cast<float>(static_cast<int>(desired + 0.5f));
                if (desired < 1.0f) desired = 1.0f;
            }
            if (std::isfinite(desired) && desired > 0.0001f && desired <= 100000.0f)
            {
                applied = desired;
                entry.forced[i] = true;
            }
        }

        if (applied != before)
            R2R_MapMondeExtraWriteField(field, raw, applied);
        entry.lastApplied[i] = applied;
        current[i] = applied;
    }

    const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();
    if (entry.loggedMode != mode || entry.loggedGeneration != g_R2RStatsPlaytestGeneration)
    {
        R2R_MapMondeExtraLog(target, entry, current);
        entry.loggedMode = mode;
        entry.loggedGeneration = g_R2RStatsPlaytestGeneration;
    }
}

static void R2R_MapMondeExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject)))
        return;
    R2R_MapMondeExtraProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr) R2R_MapMondeExtraScan(object, depth + 1);
    }
}

static void R2R_MapMondeExtraForgetWorld()
{
    std::memset(g_R2RMapMondeExtraEntries, 0, sizeof(g_R2RMapMondeExtraEntries));
    g_R2RMapMondeExtraWorld = nullptr;
    g_R2RMapMondeExtraInactiveWorld = nullptr;
}

static void R2R_MapMondeExtraTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Mapmonde") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_MapMondeExtraForgetWorld();
        return;
    }

    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RMapMondeExtraWorld || inactive != g_R2RMapMondeExtraInactiveWorld)
    {
        R2R_MapMondeExtraForgetWorld();
        g_R2RMapMondeExtraWorld = active;
        g_R2RMapMondeExtraInactiveWorld = inactive;
        R2R_MapMondeExtraStartReport();
    }

    ++g_R2RMapMondeExtraVisit;
    R2R_MapMondeExtraScan(active, 0);
    if (inactive != active) R2R_MapMondeExtraScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_MAPMONDE_EXTRA_TARGET_COUNT; ++i)
    {
        if (g_R2RMapMondeExtraEntries[i].visit != g_R2RMapMondeExtraVisit)
            g_R2RMapMondeExtraEntries[i] = R2R_MapMondeExtraEntry();
    }
}

static MTH_tdxReal R2R_MapMondeMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    if (object == nullptr || dynamics == nullptr ||
        R2R_StatsEffectiveMode() == R2R_STATS_MODE_NATIVE ||
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Mapmonde") != 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        return dt;

    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int targetIndex = R2R_MapMondeExtraFindTarget(family, model, personal);
    if (targetIndex < 0) return dt;
    const unsigned int target = static_cast<unsigned int>(targetIndex);
    if (!g_R2RMapMondeExtraTargets[target].mechanicsDt) return dt;
    if (!std::isfinite(dt) || dt <= 0 || dt > 0.25f) return dt;

    const float factor = R2R_MapMondeExtraDesiredMotionFactor(target);
    const MTH_tdxReal applied = static_cast<MTH_tdxReal>(dt * factor);
    if (!std::isfinite(applied) || applied <= 0 || applied > 1.0f) return dt;

    R2R_MapMondeExtraEntry& entry = g_R2RMapMondeExtraEntries[target];
    if (entry.owner == object)
    {
        if (entry.mechanicsDtHits == 0) entry.loggedGeneration = UINT32_MAX;
        ++entry.mechanicsDtHits;
    }
    return applied;
}


// ============================================================
// v0.0.19e.2: Learn_30 expanded selective Stats randomizer.
//
// Validated from the selective Raymap export. Only actor-local, gameplay-like
// scalar fields and exact hard-coded movement routes are changed here.
// Graphs, waypoints, Caps, arrays, action/state selectors and shared scripts
// remain native.
//
// Direct DSG fields:
//   JCP_PHL_Actor_Model2_I1: Float_0 mushroom bounce impulse
//   JCP_OLD_francesco_I1: Float_1 travel speed, Float_2 activation distance
//   JCP_SUN_Grille_Cage_I1: Float_2 opening speed, Float_3 opening distance
//
// Hard-coded motion routes (actor-local mechanics DT):
//   ALW_Rayseau1 / ARG_Rayseau
//   JCP_SUN_Papillon_I3 / SUN_Papillon
//   JCP_SUN_Poisson_Rigol_M_I5 / SUN_Poisson_Rigol_M
//
// Existing validated modules remain authoritative for:
//   JCP_OLD_tonneau_reseau_I2 Float_3 travel speed
//   JCP_MIC_PiranhaSauteurVisible_I2 Int_1/Int_2/Float_3/Float_4,
//   piranha flight tempo and animation rate.
// ============================================================
