static_cast<unsigned int>(sizeof(g_R2RLearn30ExtraTargets) / sizeof(g_R2RLearn30ExtraTargets[0]));

struct R2R_Learn30ExtraEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    float original[2];
    float lastApplied[2];
    bool captured[2];
    bool forced[2];
    unsigned int visit;
    unsigned int mechanicsDtHits;
    R2R_StatsPlaytestMode loggedMode;
    uint32_t loggedGeneration;
};

static R2R_Learn30ExtraEntry g_R2RLearn30ExtraEntries[R2R_LEARN30_EXTRA_TARGET_COUNT] = {};
static HIE_tdstSuperObject* g_R2RLearn30ExtraWorld = nullptr;
static HIE_tdstSuperObject* g_R2RLearn30ExtraInactiveWorld = nullptr;
static unsigned int g_R2RLearn30ExtraVisit = 0;
static bool g_R2RLearn30ExtraReportStarted = false;

static int R2R_Learn30ExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr || personal == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_LEARN30_EXTRA_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RLearn30ExtraTargets[i];
        if (_stricmp(family, t.family) == 0 &&
            _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0)
            return static_cast<int>(i);
    }
    return -1;
}

static bool R2R_Learn30ExtraGetFloat(HIE_tdstSuperObject* object,
    unsigned char dsgIndex, float*& value)
{
    value = nullptr;
    AI_tdeDsgVarType type = AI_E_Nb_dvt;
    void* raw = nullptr;
    if (!AI_fn_bGetDsgVar(object, dsgIndex, &type, &raw) ||
        raw == nullptr || type != AI_E_dvt_Float ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), sizeof(float)) ||
        !R2R_Learn10ExtraWritable(raw, sizeof(float)))
        return false;
    value = reinterpret_cast<float*>(raw);
    return true;
}

static float R2R_Learn30ExtraRandomFactor(unsigned int target,
    unsigned int slot, float minFactor, float maxFactor)
{
    const int minMilli = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int maxMilli = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = 0x4C333000u ^
        (target * 0x9E3779B9u) ^
        (slot * 0x85EBCA6Bu) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange("Stats.Learn30Extra.Factor", "Learn_30", salt,
        minMilli, maxMilli) / 1000.0f;
}

static float R2R_Learn30ExtraDesiredFieldFactor(unsigned int target, unsigned int slot)
{
    if (target >= R2R_LEARN30_EXTRA_TARGET_COUNT ||
        slot >= g_R2RLearn30ExtraTargets[target].fieldCount)
        return 1.0f;
    const auto& field = g_R2RLearn30ExtraTargets[target].fields[slot];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return field.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return field.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Learn30ExtraRandomFactor(target, slot, field.minFactor, field.maxFactor);
    return 1.0f;
}

static float R2R_Learn30ExtraDesiredMotionFactor(unsigned int target)
{
    if (target >= R2R_LEARN30_EXTRA_TARGET_COUNT ||
        !g_R2RLearn30ExtraTargets[target].mechanicsDt)
        return 1.0f;
    const auto& t = g_R2RLearn30ExtraTargets[target];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return t.motionMin;
    if (mode == R2R_STATS_MODE_MAX) return t.motionMax;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Learn30ExtraRandomFactor(target, 100, t.motionMin, t.motionMax);
    return 1.0f;
}

