static void R2R_Learn30ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor)
        return;
    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int found = R2R_Learn30ExtraFindTarget(family, model, personal);
    if (found < 0) return;
    const unsigned int target = static_cast<unsigned int>(found);
    const auto& spec = g_R2RLearn30ExtraTargets[target];
    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)))
        return;

    auto& entry = g_R2RLearn30ExtraEntries[target];
    if (entry.owner != object || entry.actor != actor)
    {
        entry = R2R_Learn30ExtraEntry();
        entry.owner = object;
        entry.actor = actor;
        entry.loggedMode = R2R_STATS_MODE_AUTO;
        entry.loggedGeneration = UINT32_MAX;
    }
    entry.visit = g_R2RLearn30ExtraVisit;

    float current[2] = { 0.0f, 0.0f };
    for (unsigned int i = 0; i < spec.fieldCount; ++i)
    {
        float* value = nullptr;
        if (!R2R_Learn30ExtraGetFloat(object, spec.fields[i].dsgIndex, value)) continue;
        const float before = *value;
        if (!std::isfinite(before) || std::fabs(before) > 100000.0f) continue;

        if (!entry.captured[i] || !entry.forced[i] || before != entry.lastApplied[i])
        {
            entry.original[i] = before;
            entry.captured[i] = true;
        }

        float applied = before;
        const auto mode = R2R_StatsEffectiveMode();
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (entry.forced[i] && before == entry.lastApplied[i] && entry.captured[i])
                applied = entry.original[i];
            entry.forced[i] = false;
        }
        else if (entry.captured[i])
        {
            const float desired = entry.original[i] * R2R_Learn30ExtraDesiredFieldFactor(target, i);
            if (std::isfinite(desired) && std::fabs(desired) <= 100000.0f)
            {
                applied = desired;
                entry.forced[i] = true;
            }
        }

        if (applied != before) *value = applied;
        entry.lastApplied[i] = applied;
        current[i] = applied;
    }

    const auto mode = R2R_StatsEffectiveMode();
    if (entry.loggedMode != mode || entry.loggedGeneration != g_R2RStatsPlaytestGeneration)
    {
        R2R_Learn30ExtraLog(target, entry, current);
        entry.loggedMode = mode;
        entry.loggedGeneration = g_R2RStatsPlaytestGeneration;
    }
}

static void R2R_Learn30ExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject)))
        return;
    R2R_Learn30ExtraProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr) R2R_Learn30ExtraScan(object, depth + 1);
    }
}

static void R2R_Learn30ExtraForgetWorld()
{
    std::memset(g_R2RLearn30ExtraEntries, 0, sizeof(g_R2RLearn30ExtraEntries));
    g_R2RLearn30ExtraWorld = nullptr;
    g_R2RLearn30ExtraInactiveWorld = nullptr;
}

static void R2R_Learn30ExpandedTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Learn_30") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Learn30ExtraForgetWorld();
        return;
    }

    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RLearn30ExtraWorld || inactive != g_R2RLearn30ExtraInactiveWorld)
    {
        R2R_Learn30ExtraForgetWorld();
        g_R2RLearn30ExtraWorld = active;
        g_R2RLearn30ExtraInactiveWorld = inactive;
        R2R_Learn30ExtraStartReport();
    }

    ++g_R2RLearn30ExtraVisit;
    R2R_Learn30ExtraScan(active, 0);
    if (inactive != active) R2R_Learn30ExtraScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_LEARN30_EXTRA_TARGET_COUNT; ++i)
        if (g_R2RLearn30ExtraEntries[i].visit != g_R2RLearn30ExtraVisit)
            g_R2RLearn30ExtraEntries[i] = R2R_Learn30ExtraEntry();
}

static MTH_tdxReal R2R_Learn30ExpandedMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    if (object == nullptr || dynamics == nullptr || object == HIE_M_hGetMainActor() ||
        R2R_StatsEffectiveMode() == R2R_STATS_MODE_NATIVE ||
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Learn_30") != 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        return dt;

    const int found = R2R_Learn30ExtraFindTarget(
        HIE_fn_szGetObjectFamilyName(object),
        HIE_fn_szGetObjectModelName(object),
        HIE_fn_szGetObjectPersonalName(object));
    if (found < 0) return dt;
    const unsigned int target = static_cast<unsigned int>(found);
    if (!g_R2RLearn30ExtraTargets[target].mechanicsDt) return dt;
    if (!std::isfinite(dt) || dt <= 0 || dt > 0.25f) return dt;

    const float factor = R2R_Learn30ExtraDesiredMotionFactor(target);
    const MTH_tdxReal applied = static_cast<MTH_tdxReal>(dt * factor);
    if (!std::isfinite(applied) || applied <= 0 || applied > 1.0f) return dt;

    auto& entry = g_R2RLearn30ExtraEntries[target];
    if (entry.owner == object)
    {
        if (entry.mechanicsDtHits == 0) entry.loggedGeneration = UINT32_MAX;
        ++entry.mechanicsDtHits;
    }
    return applied;
}


// ============================================================
// v0.0.19f.0: Learn_31 expanded selective Stats randomizer.
//
// Selective Raymap export validation:
//   ALW_Prune / BNT_ThePrune:
//      Float_4 and Float_5 = native movement/bounce magnitudes,
//      Float_6 = collision response multiplier, Float_17 = mechanic slide.
//   ALW_Rayseau1 / ARG_Rayseau:
//      actor-local mechanics time only, conservative x0.5..x2.0.
//   OLD_alw_tonneau / OLD_alw_tonneau_model:
//      actor-local mechanics time for the launched explosive barrel.
//   ALW_kapoueh / STN_kapoueh:
//      Float_0 = detection distance; actor-local mechanics time for charge motion.
//   JCP_VCT_GenPrune_I1 / VCT_GenPrune:
//      Float_6 = slide value copied into newly generated prunes.
//   JCP_MIC_PiranhaSauteur_I15 / MIC_PiranhaSauteur:
//      Int_1 initial wait, Int_2 repeat wait, Float_6 attack radius,
//      FloatArray_8[0..2] jump impulses. Existing validated Learn_31 piranha
//      mechanics-DT control remains authoritative for flight tempo.
//
// Existing validated Learn_31 movement control remains authoritative for the
// chenille Float_2 travel speed. The two pirate_sbire actors remain read-only.
// Graphs, waypoints, arrays of references, action/state selectors and timers not
// listed above remain native.
// ============================================================
