static const unsigned int R2R_LEARN31_EXTRA_TARGET_COUNT =
static_cast<unsigned int>(sizeof(g_R2RLearn31ExtraTargets) / sizeof(g_R2RLearn31ExtraTargets[0]));
static const unsigned int R2R_LEARN31_EXTRA_PIRANHA_TARGET = 5;

struct R2R_Learn31ExtraEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    float original[4];
    float lastApplied[4];
    bool captured[4];
    bool forced[4];
    float jumpOriginal[3];
    float jumpLastApplied[3];
    bool jumpCaptured[3];
    bool jumpForced[3];
    unsigned int visit;
    unsigned int mechanicsDtHits;
    R2R_StatsPlaytestMode loggedMode;
    uint32_t loggedGeneration;
};

static R2R_Learn31ExtraEntry g_R2RLearn31ExtraEntries[R2R_LEARN31_EXTRA_TARGET_COUNT] = {};
static HIE_tdstSuperObject* g_R2RLearn31ExtraWorld = nullptr;
static HIE_tdstSuperObject* g_R2RLearn31ExtraInactiveWorld = nullptr;
static unsigned int g_R2RLearn31ExtraVisit = 0;
static bool g_R2RLearn31ExtraReportStarted = false;

static int R2R_Learn31ExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr || personal == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_LEARN31_EXTRA_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RLearn31ExtraTargets[i];
        if (_stricmp(family, t.family) == 0 &&
            _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0)
            return static_cast<int>(i);
    }
    return -1;
}

static bool R2R_Learn31ExtraGetField(HIE_tdstSuperObject* object,
    const R2R_Learn31ExtraField& field, void*& raw, float& current)
{
    raw = nullptr;
    current = 0.0f;
    AI_tdeDsgVarType type = AI_E_Nb_dvt;
    if (!AI_fn_bGetDsgVar(object, field.dsgIndex, &type, &raw) || raw == nullptr)
        return false;

    if (field.kind == R2R_LEARN31_FIELD_FLOAT)
    {
        if (type != AI_E_dvt_Float ||
            !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), sizeof(float)) ||
            !R2R_Learn10ExtraWritable(raw, sizeof(float)))
            return false;
        current = *reinterpret_cast<float*>(raw);
        return std::isfinite(current) && std::fabs(current) <= 100000.0f;
    }

    if (type != AI_E_dvt_Integer ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), sizeof(int)) ||
        !R2R_Learn10ExtraWritable(raw, sizeof(int)))
        return false;
    current = static_cast<float>(*reinterpret_cast<int*>(raw));
    return std::isfinite(current) && std::fabs(current) <= 1000000.0f;
}

static void R2R_Learn31ExtraWriteField(const R2R_Learn31ExtraField& field,
    void* raw, float value)
{
    if (raw == nullptr || !std::isfinite(value)) return;
    if (field.kind == R2R_LEARN31_FIELD_FLOAT)
    {
        *reinterpret_cast<float*>(raw) = value;
        return;
    }
    int v = static_cast<int>(value + 0.5f);
    if (v < 1) v = 1;
    *reinterpret_cast<int*>(raw) = v;
}

static float R2R_Learn31ExtraRandomFactor(unsigned int target, unsigned int slot,
    float minFactor, float maxFactor)
{
    const int minMilli = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int maxMilli = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = 0x4C333100u ^
        (target * 0x9E3779B9u) ^
        (slot * 0x85EBCA6Bu) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange("Stats.Learn31Extra.Factor", "Learn_31", salt,
        minMilli, maxMilli) / 1000.0f;
}

static float R2R_Learn31ExtraDesiredFieldFactor(unsigned int target, unsigned int slot)
{
    if (target >= R2R_LEARN31_EXTRA_TARGET_COUNT ||
        slot >= g_R2RLearn31ExtraTargets[target].fieldCount)
        return 1.0f;
    const auto& field = g_R2RLearn31ExtraTargets[target].fields[slot];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return field.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return field.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Learn31ExtraRandomFactor(target, slot, field.minFactor, field.maxFactor);
    return 1.0f;
}

static float R2R_Learn31ExtraDesiredMotionFactor(unsigned int target)
{
    if (target >= R2R_LEARN31_EXTRA_TARGET_COUNT ||
        !g_R2RLearn31ExtraTargets[target].mechanicsDt)
        return 1.0f;
    const auto& t = g_R2RLearn31ExtraTargets[target];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return t.motionMin;
    if (mode == R2R_STATS_MODE_MAX) return t.motionMax;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Learn31ExtraRandomFactor(target, 100, t.motionMin, t.motionMax);
    return 1.0f;
}

static float R2R_Learn31ExtraDesiredJumpFactor(unsigned int element)
{
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return 0.25f;
    if (mode == R2R_STATS_MODE_MAX) return 4.00f;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Learn31ExtraRandomFactor(R2R_LEARN31_EXTRA_PIRANHA_TARGET,
            200 + element, 0.25f, 4.00f);
    return 1.0f;
}

static bool R2R_Learn31ExtraGetJumpArray(HIE_tdstSuperObject* object, AI_tdstArray*& array)
{
    array = nullptr;
    AI_tdeDsgVarType type = AI_E_Nb_dvt;
    void* raw = nullptr;
    if (!AI_fn_bGetDsgVar(object, 8, &type, &raw) || raw == nullptr ||
        type != AI_E_dvt_FloatArray)
        return false;
    array = reinterpret_cast<AI_tdstArray*>(raw);
    if (!R2R_AddressReadable(reinterpret_cast<uintptr_t>(array), sizeof(AI_tdstArray_1)) ||
        array->eType != AI_E_dvt_Float || array->ucMaxSize < 3)
        return false;
    for (unsigned int i = 0; i < 3; ++i)
    {
        float* value = &AI_M_pArrayElement(array, i)->xValue;
        if (!R2R_AddressReadable(reinterpret_cast<uintptr_t>(value), sizeof(float)) ||
            !R2R_Learn10ExtraWritable(value, sizeof(float)) ||
            !std::isfinite(*value) || std::fabs(*value) > 100000.0f)
            return false;
    }
    return true;
}

static void R2R_Learn31ExtraStartReport()
{
    if (g_R2RLearn31ExtraReportStarted) return;
    FILE* f = nullptr;
    fopen_s(&f, R2R_LEARN31_EXTRA_REPORT, "w");
    if (f == nullptr) return;
    fprintf(f,
        "RAYMAN 2 RANDOMIZER\n"
        "%s - LEARN_31 EXPANDED SELECTIVE STATS\n"
        "============================================================\n"
        "F6=MIN, F7=MAX, F8=RANDOM/REROLL, F12=NATIVE\n"
        "Prune movement magnitudes x0.75..x4; collision/slide x0.5..x2.\n"
        "Rayseau mechanics x0.5..x2 (progression-safe conservative range).\n"
        "Explosive barrel and Kapoueh mechanics x0.25..x4.\n"
        "Kapoueh detection and GenPrune slide x0.5..x2.\n"
        "Piranha waits x0.25..x4, attack radius x0.5..x2, each jump-array element x0.25..x4.\n"
        "Chenille Float_2 and piranha flight tempo remain in Rayman2Randomizer_Learn31Movement.txt.\n"
        "Both pirate_sbire actors are protected/read-only in this Learn_31 pass.\n"
        "Graphs, waypoints, reference arrays and action/state selectors remain native.\n\n",
        VERSION);
    fclose(f);
    g_R2RLearn31ExtraReportStarted = true;
}

static void R2R_Learn31ExtraLog(unsigned int target,
    const R2R_Learn31ExtraEntry& entry, const float current[4], const float jumps[3])
{
    if (target >= R2R_LEARN31_EXTRA_TARGET_COUNT) return;
    R2R_Learn31ExtraStartReport();
    FILE* f = nullptr;
    fopen_s(&f, R2R_LEARN31_EXTRA_REPORT, "a");
    if (f == nullptr) return;
    const auto& t = g_R2RLearn31ExtraTargets[target];
    fprintf(f, "[LEARN31-EXTRA] %s / %s / %s mode=%s generation=%u",
        t.family, t.model, t.personal,
        R2R_StatsModeName(R2R_StatsEffectiveMode()),
        g_R2RStatsPlaytestGeneration);
    for (unsigned int i = 0; i < t.fieldCount; ++i)
    {
        if (!entry.captured[i]) continue;
        fprintf(f, " | %s native=%.6g current=%.6g factor=%.3f",
            t.fields[i].label != nullptr ? t.fields[i].label : "field",
            entry.original[i], current[i],
            R2R_Learn31ExtraDesiredFieldFactor(target, i));
    }
    if (target == R2R_LEARN31_EXTRA_PIRANHA_TARGET)
    {
        for (unsigned int i = 0; i < 3; ++i)
            if (entry.jumpCaptured[i])
                fprintf(f, " | FloatArray_8[%u] native=%.6g current=%.6g factor=%.3f",
                    i, entry.jumpOriginal[i], jumps[i], R2R_Learn31ExtraDesiredJumpFactor(i));
    }
    if (t.mechanicsDt)
        fprintf(f, " | mechanicsDTFactor=%.3f hits=%u",
            R2R_Learn31ExtraDesiredMotionFactor(target), entry.mechanicsDtHits);
    fprintf(f, "\n");
    fclose(f);
}

static void R2R_Learn31ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr || object == HIE_M_hGetMainActor() ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor)
        return;

    const int found = R2R_Learn31ExtraFindTarget(
        HIE_fn_szGetObjectFamilyName(object),
        HIE_fn_szGetObjectModelName(object),
        HIE_fn_szGetObjectPersonalName(object));
    if (found < 0) return;
    const unsigned int target = static_cast<unsigned int>(found);
    const auto& spec = g_R2RLearn31ExtraTargets[target];
    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)))
        return;

    auto& entry = g_R2RLearn31ExtraEntries[target];
    if (entry.owner != object || entry.actor != actor)
    {
        entry = R2R_Learn31ExtraEntry();
        entry.owner = object;
        entry.actor = actor;
        entry.loggedMode = R2R_STATS_MODE_AUTO;
        entry.loggedGeneration = UINT32_MAX;
    }
    entry.visit = g_R2RLearn31ExtraVisit;

    float current[4] = { 0,0,0,0 };
    for (unsigned int i = 0; i < spec.fieldCount; ++i)
    {
        void* raw = nullptr;
        float before = 0.0f;
        if (!R2R_Learn31ExtraGetField(object, spec.fields[i], raw, before)) continue;

        if (!entry.captured[i] || !entry.forced[i] || before != entry.lastApplied[i])
        {
            entry.original[i] = before;
            entry.captured[i] = true;
        }

        float applied = before;
        const auto mode = R2R_StatsEffectiveMode();
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (entry.forced[i] && before == entry.lastApplied[i] && entry.captured[i])
                applied = entry.original[i];
            entry.forced[i] = false;
        }
        else if (entry.captured[i])
        {
            applied = entry.original[i] * R2R_Learn31ExtraDesiredFieldFactor(target, i);
            if (spec.fields[i].kind == R2R_LEARN31_FIELD_INT && applied < 1.0f) applied = 1.0f;
            entry.forced[i] = true;
        }
        if (std::isfinite(applied) && applied != before)
            R2R_Learn31ExtraWriteField(spec.fields[i], raw, applied);

        if (spec.fields[i].kind == R2R_LEARN31_FIELD_INT)
        {
            void* checkRaw = nullptr; float check = applied;
            if (R2R_Learn31ExtraGetField(object, spec.fields[i], checkRaw, check)) applied = check;
        }
        entry.lastApplied[i] = applied;
        current[i] = applied;
    }

    float jumps[3] = { 0,0,0 };
    if (target == R2R_LEARN31_EXTRA_PIRANHA_TARGET)
    {
        AI_tdstArray* array = nullptr;
        if (R2R_Learn31ExtraGetJumpArray(object, array))
        {
            for (unsigned int i = 0; i < 3; ++i)
            {
                float* value = &AI_M_pArrayElement(array, i)->xValue;
                const float before = *value;
                if (!entry.jumpCaptured[i] || !entry.jumpForced[i] || before != entry.jumpLastApplied[i])
                {
                    entry.jumpOriginal[i] = before;
                    entry.jumpCaptured[i] = true;
                }
                float applied = before;
                const auto mode = R2R_StatsEffectiveMode();
                if (mode == R2R_STATS_MODE_NATIVE)
                {
                    if (entry.jumpForced[i] && before == entry.jumpLastApplied[i] && entry.jumpCaptured[i])
                        applied = entry.jumpOriginal[i];
                    entry.jumpForced[i] = false;
                }
                else if (entry.jumpCaptured[i])
                {
                    applied = entry.jumpOriginal[i] * R2R_Learn31ExtraDesiredJumpFactor(i);
                    entry.jumpForced[i] = true;
                }
                if (std::isfinite(applied) && applied > 0.0f && applied <= 100000.0f && applied != before)
                    *value = applied;
                entry.jumpLastApplied[i] = applied;
                jumps[i] = applied;
            }
        }
    }

    const auto mode = R2R_StatsEffectiveMode();
    if (entry.loggedMode != mode || entry.loggedGeneration != g_R2RStatsPlaytestGeneration)
    {
        R2R_Learn31ExtraLog(target, entry, current, jumps);
        entry.loggedMode = mode;
        entry.loggedGeneration = g_R2RStatsPlaytestGeneration;
    }
}

static void R2R_Learn31ExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject)))
        return;
    R2R_Learn31ExtraProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr) R2R_Learn31ExtraScan(object, depth + 1);
    }
}

static void R2R_Learn31ExtraForgetWorld()
{
    std::memset(g_R2RLearn31ExtraEntries, 0, sizeof(g_R2RLearn31ExtraEntries));
    g_R2RLearn31ExtraWorld = nullptr;
    g_R2RLearn31ExtraInactiveWorld = nullptr;
}

static void R2R_Learn31ExpandedTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Learn_31") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Learn31ExtraForgetWorld();
        return;
    }

    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RLearn31ExtraWorld || inactive != g_R2RLearn31ExtraInactiveWorld)
    {
        R2R_Learn31ExtraForgetWorld();
        g_R2RLearn31ExtraWorld = active;
        g_R2RLearn31ExtraInactiveWorld = inactive;
        R2R_Learn31ExtraStartReport();
    }

    ++g_R2RLearn31ExtraVisit;
    R2R_Learn31ExtraScan(active, 0);
    if (inactive != active) R2R_Learn31ExtraScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_LEARN31_EXTRA_TARGET_COUNT; ++i)
        if (g_R2RLearn31ExtraEntries[i].visit != g_R2RLearn31ExtraVisit)
            g_R2RLearn31ExtraEntries[i] = R2R_Learn31ExtraEntry();
}

static MTH_tdxReal R2R_Learn31ExpandedMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    if (object == nullptr || dynamics == nullptr || object == HIE_M_hGetMainActor() ||
        R2R_StatsEffectiveMode() == R2R_STATS_MODE_NATIVE ||
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Learn_31") != 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynamics), sizeof(DNM_tdstDynamicsBaseBlock)) ||
        !std::isfinite(dt) || dt <= 0 || dt > 0.25f)
        return dt;

    const int found = R2R_Learn31ExtraFindTarget(
        HIE_fn_szGetObjectFamilyName(object),
        HIE_fn_szGetObjectModelName(object),
        HIE_fn_szGetObjectPersonalName(object));
    if (found < 0) return dt;
    const unsigned int target = static_cast<unsigned int>(found);
    if (!g_R2RLearn31ExtraTargets[target].mechanicsDt) return dt;

    const float factor = R2R_Learn31ExtraDesiredMotionFactor(target);
    const MTH_tdxReal applied = static_cast<MTH_tdxReal>(dt * factor);
    if (!std::isfinite(applied) || applied <= 0 || applied > 1.0f) return dt;

    auto& entry = g_R2RLearn31ExtraEntries[target];
    if (entry.owner == object)
    {
        if (entry.mechanicsDtHits == 0) entry.loggedGeneration = UINT32_MAX;
        ++entry.mechanicsDtHits;
    }
    return applied;
}


