static const unsigned int R2R_BAST20_EXTRA_TARGET_COUNT =
static_cast<unsigned int>(sizeof(g_R2RBast20ExtraTargets) / sizeof(g_R2RBast20ExtraTargets[0]));
static const unsigned int R2R_BAST20_EXTRA_MAX_ACTORS = 128;

struct R2R_Bast20ExtraEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    unsigned int targetIndex;
    uint32_t rngKey;
    unsigned int visit;

    bool captured[16];
    bool forced[16];
    float originalScalar[16];
    float lastAppliedScalar[16];
    MTH3D_tdstVector originalVector[16];
    MTH3D_tdstVector lastAppliedVector[16];

    // Pirate HP is actor StandardGame state rather than a DSG variable.
    bool hpCaptured;
    bool hpForced;
    unsigned char originalHP;
    unsigned char originalHPMax;
    unsigned char originalHPMaxMax;
    unsigned char lastAppliedHP;
    unsigned char lastAppliedHPMax;
    R2R_StatsPlaytestMode hpAppliedMode;
    unsigned int hpAppliedGeneration;

    unsigned int mechanicsDtHits;
    R2R_StatsPlaytestMode loggedMode;
    unsigned int loggedGeneration;
};

static R2R_Bast20ExtraEntry g_R2RBast20ExtraEntries[R2R_BAST20_EXTRA_MAX_ACTORS] = {};
static HIE_tdstSuperObject* g_R2RBast20ExtraWorld = nullptr;
static HIE_tdstSuperObject* g_R2RBast20ExtraInactiveWorld = nullptr;
static unsigned int g_R2RBast20ExtraVisit = 0;
static bool g_R2RBast20ExtraReportStarted = false;

static bool R2R_Bast20ExtraVectorFinite(const MTH3D_tdstVector& v)
{
    return std::isfinite(v.x) && std::isfinite(v.y) && std::isfinite(v.z) &&
        std::fabs(v.x) <= 100000.0f && std::fabs(v.y) <= 100000.0f &&
        std::fabs(v.z) <= 100000.0f;
}

static bool R2R_Bast20ExtraVectorEqual(const MTH3D_tdstVector& a, const MTH3D_tdstVector& b)
{
    return a.x == b.x && a.y == b.y && a.z == b.z;
}

static float R2R_Bast20ExtraVectorNorm(const MTH3D_tdstVector& v)
{
    const double n = std::sqrt(static_cast<double>(v.x) * v.x +
        static_cast<double>(v.y) * v.y +
        static_cast<double>(v.z) * v.z);
    return std::isfinite(n) ? static_cast<float>(n) : 0.0f;
}

static int R2R_Bast20ExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr || personal == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_BAST20_EXTRA_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RBast20ExtraTargets[i];
        if (_stricmp(family, t.family) == 0 &&
            _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0)
            return static_cast<int>(i);
    }
    return -1;
}

static float R2R_Bast20ExtraRandomFactor(unsigned int target, unsigned int randomSlot,
    uint32_t rngKey, float minFactor, float maxFactor)
{
    const int minMilli = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int maxMilli = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = 0x42323000u ^
        (target * 0x9E3779B9u) ^
        (randomSlot * 0x85EBCA6Bu) ^
        (rngKey * 0x27D4EB2Du) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange("Stats.Bast20Extra.Factor", "Bast_20", salt,
        minMilli, maxMilli) / 1000.0f;
}

static float R2R_Bast20ExtraDesiredFactor(unsigned int target, unsigned int slot, uint32_t rngKey)
{
    if (target >= R2R_BAST20_EXTRA_TARGET_COUNT ||
        slot >= g_R2RBast20ExtraTargets[target].fieldCount)
        return 1.0f;
    const auto& field = g_R2RBast20ExtraTargets[target].fields[slot];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return field.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return field.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Bast20ExtraRandomFactor(target, field.randomSlot, rngKey,
            field.minFactor, field.maxFactor);
    return 1.0f;
}

static float R2R_Bast20ExtraDesiredMotionFactor(unsigned int target, uint32_t rngKey)
{
    if (target >= R2R_BAST20_EXTRA_TARGET_COUNT ||
        !g_R2RBast20ExtraTargets[target].mechanicsDt)
        return 1.0f;
    const auto& t = g_R2RBast20ExtraTargets[target];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return t.motionMin;
    if (mode == R2R_STATS_MODE_MAX) return t.motionMax;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Bast20ExtraRandomFactor(target, 100, rngKey, t.motionMin, t.motionMax);
    return 1.0f;
}

static bool R2R_Bast20ExtraGetRaw(HIE_tdstSuperObject* object,
    const R2R_Bast20ExtraField& field, void*& raw)
{
    raw = nullptr;
    AI_tdeDsgVarType type = AI_E_Nb_dvt;
    if (!AI_fn_bGetDsgVar(object, field.dsgIndex, &type, &raw) || raw == nullptr)
        return false;

    size_t size = 0;
    AI_tdeDsgVarType wanted = AI_E_Nb_dvt;
    if (field.kind == R2R_BAST20_FIELD_FLOAT)
    {
        wanted = AI_E_dvt_Float;
        size = sizeof(float);
    }
    else if (field.kind == R2R_BAST20_FIELD_INT)
    {
        wanted = AI_E_dvt_Integer;
        size = sizeof(int);
    }
    else
    {
        wanted = AI_E_dvt_Vector;
        size = sizeof(MTH3D_tdstVector);
    }

    return type == wanted &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), size) &&
        R2R_Learn10ExtraWritable(raw, size);
}

static bool R2R_Bast20ExtraIsGameplayPirate(const char* family)
{
    return family != nullptr && _stricmp(family, "pirate_sbire") == 0;
}

static unsigned int R2R_Bast20ExtraDesiredPirateHP(const R2R_Bast20ExtraEntry& e)
{
    if (!e.hpCaptured) return 0;
    int upper = static_cast<int>(e.originalHPMax) * 3;
    if (upper < 2) upper = 2;
    if (upper > 12) upper = 12;
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return e.originalHPMax;
    if (mode == R2R_STATS_MODE_MIN) return 1u;
    if (mode == R2R_STATS_MODE_MAX) return static_cast<unsigned int>(upper);
    if (mode == R2R_STATS_MODE_RANDOM)
    {
        const uint32_t salt = 0x42504850u ^ e.rngKey ^
            (g_R2RStatsPlaytestGeneration * 0x9E3779B9u);
        return static_cast<unsigned int>(R2R_RollRange(
            "Stats.Bast20Pirate.HP", "Bast_20", salt, 1, upper));
    }
    return e.originalHPMax;
}

static void R2R_Bast20ExtraApplyPirateHP(R2R_Bast20ExtraEntry& e,
    HIE_tdstEngineObject* actor, const char* family)
{
    if (!R2R_Bast20ExtraIsGameplayPirate(family) || actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)) ||
        !R2R_Learn10ExtraWritable(actor->hStandardGame, sizeof(GAM_tdstStandardGame)))
        return;

    GAM_tdstStandardGame* sg = actor->hStandardGame;
    unsigned int hp = sg->ucHitPoints;
    unsigned int hpMax = sg->ucHitPointsMax;
    unsigned int hpMaxMax = sg->ucHitPointsMaxMax;

    // Combat pirates initialize HP in script with Proc_SetHitPoints/Proc_SetHitPointsMax.
    // ucHitPointsMaxMax does NOT reliably mirror ucHitPointsMax at that moment, so
    // requiring all three bytes to match caused some pirates to keep native HP.
    const bool combatPlausible = hp > 0 && hp == hpMax && hpMax <= 20;
    if (!e.hpCaptured)
    {
        if (!combatPlausible) return;
        e.originalHP = static_cast<unsigned char>(hp);
        e.originalHPMax = static_cast<unsigned char>(hpMax);
        e.originalHPMaxMax = static_cast<unsigned char>((hpMaxMax > 0 && hpMaxMax <= 20) ? hpMaxMax : hpMax);
        e.hpCaptured = true;
        e.hpAppliedMode = R2R_STATS_MODE_AUTO;
        e.hpAppliedGeneration = UINT32_MAX;
    }

    const auto mode = R2R_StatsEffectiveMode();

    // The pirate init script may set native HP after our first pre-engine scan.
    // If it returns to a full plausible native value, recapture and reapply once.
    bool scriptReinitialized = false;
    if (e.hpForced && mode != R2R_STATS_MODE_NATIVE && combatPlausible &&
        hpMax != static_cast<unsigned int>(e.lastAppliedHPMax))
    {
        e.originalHP = static_cast<unsigned char>(hp);
        e.originalHPMax = static_cast<unsigned char>(hpMax);
        e.originalHPMaxMax = static_cast<unsigned char>((hpMaxMax > 0 && hpMaxMax <= 20) ? hpMaxMax : hpMax);
        scriptReinitialized = true;
        // Force a second report line after the actor's own init script so the log
        // shows the real native HP (3/6 or 6/9) rather than a pre-init placeholder.
        e.loggedGeneration = UINT32_MAX;
    }

    if (!scriptReinitialized && e.hpAppliedMode == mode &&
        e.hpAppliedGeneration == g_R2RStatsPlaytestGeneration)
        return;

    const unsigned int desiredMax = R2R_Bast20ExtraDesiredPirateHP(e);
    if (desiredMax == 0 || desiredMax > 255) return;

    // Preserve damage ratio when F6/F7/F8/F12 is changed mid-fight.
    unsigned int desiredHP = desiredMax;
    if (hpMax > 0 && hp < hpMax)
    {
        if (hp == 0) desiredHP = 0;
        else
        {
            desiredHP = static_cast<unsigned int>(
                (static_cast<unsigned long long>(hp) * desiredMax + hpMax / 2) / hpMax);
            if (desiredHP == 0) desiredHP = 1;
            if (desiredHP > desiredMax) desiredHP = desiredMax;
        }
    }

    sg->ucHitPoints = static_cast<unsigned char>(desiredHP);
    sg->ucHitPointsMax = static_cast<unsigned char>(desiredMax);
    sg->ucHitPointsMaxMax = static_cast<unsigned char>(desiredMax);
    e.lastAppliedHP = static_cast<unsigned char>(desiredHP);
    e.lastAppliedHPMax = static_cast<unsigned char>(desiredMax);
    e.hpForced = mode != R2R_STATS_MODE_NATIVE;
    e.hpAppliedMode = mode;
    e.hpAppliedGeneration = g_R2RStatsPlaytestGeneration;
}

static void R2R_Bast20ExtraStartReport()
{
    if (g_R2RBast20ExtraReportStarted) return;
    FILE* f = nullptr;
    fopen_s(&f, R2R_BAST20_EXTRA_REPORT, "w");
    if (f == nullptr) return;
    fprintf(f,
        "%s BAST_20 EXPANDED STATS\n"
        "Controls: F6=MIN F7=MAX F8=RANDOM/reroll F12=NATIVE.\n"
        "Selected exact identities only; live gameplay actors get independent deterministic factors.\n"
        "ALW beam prototype is randomized once so recursive beam clones inherit without factor compounding.\n"
        "Generated missiles randomize ballistic vector, homing step, hit radius and straight speed.\n"
        "Gameplay pirates randomize HP, combat ranges, burst counts, cooldowns, aiming coefficients, animation and actor-local mechanics x0.25..x4.\n"
        "Gnak barrel-throw minimum distance randomizes only downward (x0.25..x1) so a roll cannot trap FRH_gn_to_lance forever.\n"
        "Gnak thrown OLD_alw_tonneau instances randomize actor-local mechanics x0.25..x4 and animation.\n"
        "BNT_TonneauFusee randomizes rocket countdown, live spin and actor-local mechanics x0.25..x4.\n"
        "SUN_Tono_Generator randomizes animation plus brain polling frequency x0.25..x4; brain counter is reset only on actual rerolls/changes so generators keep running.\n"
        "SDZ_Sbire_Cine animation is randomized; its HP-Max command mailbox remains untouched. CHR_Porte and OLP_PorteLaser_Switch remain protected.\n"
        "Graphs, WayPoints, behavior/music selectors and cinematic pirate command channels remain untouched.\n"
        "Murfy Int_3 and Int_6 intentionally share one factor so their distance relationship is preserved.\n\n",
        VERSION);
    fclose(f);
    g_R2RBast20ExtraReportStarted = true;
}

static void R2R_Bast20ExtraLog(const R2R_Bast20ExtraEntry& e)
{
    if (e.targetIndex >= R2R_BAST20_EXTRA_TARGET_COUNT) return;
    R2R_Bast20ExtraStartReport();
    FILE* f = nullptr;
    fopen_s(&f, R2R_BAST20_EXTRA_REPORT, "a");
    if (f == nullptr) return;

    const auto& t = g_R2RBast20ExtraTargets[e.targetIndex];
    fprintf(f, "[BAST20-EXTRA] %s / %s / %s owner=%p key=%08X mode=%s generation=%u",
        t.family, t.model, t.personal, static_cast<void*>(e.owner), e.rngKey,
        R2R_StatsModeName(R2R_StatsEffectiveMode()), g_R2RStatsPlaytestGeneration);

    for (unsigned int i = 0; i < t.fieldCount; ++i)
    {
        const auto& field = t.fields[i];
        const float factor = R2R_Bast20ExtraDesiredFactor(e.targetIndex, i, e.rngKey);
        if (field.kind == R2R_BAST20_FIELD_VECTOR)
        {
            fprintf(f, " | %s norm %.3f->%.3f x%.3f",
                field.label,
                R2R_Bast20ExtraVectorNorm(e.originalVector[i]),
                R2R_Bast20ExtraVectorNorm(e.lastAppliedVector[i]),
                factor);
        }
        else
        {
            fprintf(f, " | %s %.3f->%.3f x%.3f",
                field.label, e.originalScalar[i], e.lastAppliedScalar[i], factor);
        }
    }

    if (e.hpCaptured)
        fprintf(f, " | HP native=%u applied=%u/%u",
            static_cast<unsigned int>(e.originalHPMax),
            static_cast<unsigned int>(e.lastAppliedHP),
            static_cast<unsigned int>(e.lastAppliedHPMax));

    if (t.mechanicsDt)
        fprintf(f, " | mechanicsDT x%.3f hits=%u",
            R2R_Bast20ExtraDesiredMotionFactor(e.targetIndex, e.rngKey),
            e.mechanicsDtHits);
    fprintf(f, "\n");
    fclose(f);
}

static uint32_t R2R_Bast20ExtraActorKey(HIE_tdstSuperObject* object,
    HIE_tdstEngineObject* actor, const char* family, const char* model, const char* personal)
{
    GAM_tdstStandardGame* standardGame = nullptr;
    if (actor != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) &&
        actor->hStandardGame != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)))
        standardGame = actor->hStandardGame;
    return R2R_StatsActorSlotKey(object, standardGame, family, model, personal);
}

static bool R2R_Bast20ExtraIsStoragePrototype(HIE_tdstSuperObject* object)
{
    return object != nullptr && object->p_stGlobalMatrix != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(object->p_stGlobalMatrix),
            sizeof(POS_tdstCompletePosition)) &&
        object->p_stGlobalMatrix->stPos.y < -900.0f;
}

static void R2R_Bast20ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr || object == HIE_M_hGetMainActor() ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor)
        return;

    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int found = R2R_Bast20ExtraFindTarget(family, model, personal);
    if (found < 0) return;
    const unsigned int target = static_cast<unsigned int>(found);
    const auto& spec = g_R2RBast20ExtraTargets[target];

    // Four ALW actors in this export live at y=-1000 as storage/prototype actors.
    // The beam recursively clones itself, so randomize ONLY its prototype once;
    // descendants inherit the same values and cannot compound the factor.
    // Projectile/OLD barrel/Rayseau prototypes stay native; their live generated
    // instances are handled after they appear in the playable map.
    const bool storagePrototype = R2R_Bast20ExtraIsStoragePrototype(object);
    if ((target == 0 || target == 1 || target == 3) && storagePrototype) return;
    if (target == 2 && !storagePrototype) return;

    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)))
        return;

    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_BAST20_EXTRA_MAX_ACTORS; ++i)
    {
        const auto& e = g_R2RBast20ExtraEntries[i];
        if (e.owner == object && e.actor == actor && e.targetIndex == target)
        {
            slot = static_cast<int>(i);
            break;
        }
        if (e.owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0) return;

    auto& e = g_R2RBast20ExtraEntries[slot];
    if (fresh)
    {
        e = R2R_Bast20ExtraEntry();
        e.owner = object;
        e.actor = actor;
        e.targetIndex = target;
        e.rngKey = R2R_Bast20ExtraActorKey(object, actor, family, model, personal);
        e.loggedMode = R2R_STATS_MODE_AUTO;
        e.loggedGeneration = UINT32_MAX;
        e.hpAppliedMode = R2R_STATS_MODE_AUTO;
        e.hpAppliedGeneration = UINT32_MAX;
    }
    e.visit = g_R2RBast20ExtraVisit;

    const auto mode = R2R_StatsEffectiveMode();
    R2R_Bast20ExtraApplyPirateHP(e, actor, family);

    for (unsigned int i = 0; i < spec.fieldCount; ++i)
    {
        const auto& field = spec.fields[i];
        void* raw = nullptr;
        if (!R2R_Bast20ExtraGetRaw(object, field, raw)) continue;

        if (field.kind == R2R_BAST20_FIELD_VECTOR)
        {
            const MTH3D_tdstVector before = *reinterpret_cast<MTH3D_tdstVector*>(raw);
            if (!R2R_Bast20ExtraVectorFinite(before)) continue;

            if (!e.captured[i] || !e.forced[i] ||
                !R2R_Bast20ExtraVectorEqual(before, e.lastAppliedVector[i]))
            {
                e.originalVector[i] = before;
                e.captured[i] = true;
            }

            MTH3D_tdstVector applied = before;
            if (mode == R2R_STATS_MODE_NATIVE)
            {
                if (e.forced[i] &&
                    R2R_Bast20ExtraVectorEqual(before, e.lastAppliedVector[i]) &&
                    e.captured[i])
                    applied = e.originalVector[i];
                e.forced[i] = false;
            }
            else if (e.captured[i])
            {
                const float factor = R2R_Bast20ExtraDesiredFactor(target, i, e.rngKey);
                applied.x = e.originalVector[i].x * factor;
                applied.y = e.originalVector[i].y * factor;
                applied.z = e.originalVector[i].z * factor;
                e.forced[i] = true;
            }

            if (R2R_Bast20ExtraVectorFinite(applied) &&
                !R2R_Bast20ExtraVectorEqual(applied, before))
                *reinterpret_cast<MTH3D_tdstVector*>(raw) = applied;
            e.lastAppliedVector[i] = applied;
            continue;
        }

        float before = 0.0f;
        if (field.kind == R2R_BAST20_FIELD_FLOAT)
        {
            before = *reinterpret_cast<float*>(raw);
            if (!std::isfinite(before) || std::fabs(before) > 100000.0f) continue;
        }
        else
        {
            before = static_cast<float>(*reinterpret_cast<int*>(raw));
            if (!std::isfinite(before) || std::fabs(before) > 1000000.0f) continue;
        }

        if (!e.captured[i] || !e.forced[i] || before != e.lastAppliedScalar[i])
        {
            e.originalScalar[i] = before;
            e.captured[i] = true;
        }

        float applied = before;
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (e.forced[i] && before == e.lastAppliedScalar[i] && e.captured[i])
                applied = e.originalScalar[i];
            e.forced[i] = false;
        }
        else if (e.captured[i])
        {
            applied = e.originalScalar[i] * R2R_Bast20ExtraDesiredFactor(target, i, e.rngKey);
            if (field.kind == R2R_BAST20_FIELD_INT && applied < 1.0f) applied = 1.0f;
            e.forced[i] = true;
        }

        if (std::isfinite(applied) && applied != before)
        {
            if (field.kind == R2R_BAST20_FIELD_FLOAT)
                *reinterpret_cast<float*>(raw) = applied;
            else
            {
                int v = static_cast<int>(applied + 0.5f);
                if (v < 1) v = 1;
                *reinterpret_cast<int*>(raw) = v;
                applied = static_cast<float>(v);
            }
        }
        else if (field.kind == R2R_BAST20_FIELD_INT)
        {
            applied = static_cast<float>(*reinterpret_cast<int*>(raw));
        }
        e.lastAppliedScalar[i] = applied;
    }

    if (e.loggedMode != mode || e.loggedGeneration != g_R2RStatsPlaytestGeneration)
    {
        R2R_Bast20ExtraLog(e);
        e.loggedMode = mode;
        e.loggedGeneration = g_R2RStatsPlaytestGeneration;
    }
}

static void R2R_Bast20ExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject)))
        return;
    R2R_Bast20ExtraProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr) R2R_Bast20ExtraScan(object, depth + 1);
    }
}

static void R2R_Bast20ExtraForgetWorld()
{
    std::memset(g_R2RBast20ExtraEntries, 0, sizeof(g_R2RBast20ExtraEntries));
    g_R2RBast20ExtraWorld = nullptr;
    g_R2RBast20ExtraInactiveWorld = nullptr;
}

static void R2R_Bast20ExpandedTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Bast_20") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Bast20ExtraForgetWorld();
        return;
    }

    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;

    if (active != g_R2RBast20ExtraWorld || inactive != g_R2RBast20ExtraInactiveWorld)
    {
        R2R_Bast20ExtraForgetWorld();
        g_R2RBast20ExtraWorld = active;
        g_R2RBast20ExtraInactiveWorld = inactive;
        R2R_Bast20ExtraStartReport();
    }

    ++g_R2RBast20ExtraVisit;
    R2R_Bast20ExtraScan(active, 0);
    if (inactive != active) R2R_Bast20ExtraScan(inactive, 0);

    for (unsigned int i = 0; i < R2R_BAST20_EXTRA_MAX_ACTORS; ++i)
        if (g_R2RBast20ExtraEntries[i].visit != g_R2RBast20ExtraVisit)
            g_R2RBast20ExtraEntries[i] = R2R_Bast20ExtraEntry();
}

static MTH_tdxReal R2R_Bast20ExpandedMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    if (object == nullptr || dynamics == nullptr || object == HIE_M_hGetMainActor() ||
        R2R_StatsEffectiveMode() == R2R_STATS_MODE_NATIVE ||
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_stEngineStructure->szLevelName == nullptr ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Bast_20") != 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynamics), sizeof(DNM_tdstDynamicsBaseBlock)) ||
        !std::isfinite(dt) || dt <= 0 || dt > 0.25f)
        return dt;

    const int found = R2R_Bast20ExtraFindTarget(
        HIE_fn_szGetObjectFamilyName(object),
        HIE_fn_szGetObjectModelName(object),
        HIE_fn_szGetObjectPersonalName(object));
    if (found < 0) return dt;
    const unsigned int target = static_cast<unsigned int>(found);
    if (!g_R2RBast20ExtraTargets[target].mechanicsDt) return dt;

    for (unsigned int i = 0; i < R2R_BAST20_EXTRA_MAX_ACTORS; ++i)
    {
        auto& e = g_R2RBast20ExtraEntries[i];
        if (e.owner != object || e.targetIndex != target ||
            e.visit != g_R2RBast20ExtraVisit)
            continue;

        const float factor = R2R_Bast20ExtraDesiredMotionFactor(target, e.rngKey);
        const MTH_tdxReal applied = static_cast<MTH_tdxReal>(dt * factor);
        if (!std::isfinite(applied) || applied <= 0 || applied > 1.0f)
            return dt;

        if (e.mechanicsDtHits == 0) e.loggedGeneration = UINT32_MAX;
        ++e.mechanicsDtHits;
        return applied;
    }

    return dt;
}


// ============================================================
// v0.0.19h.1: Bast_22 ALL-IN selective Stats randomizer.
// Direct fields are limited to values whose roles are explicit in the Raymap
// scripts. Runtime command/state variables (cinematic MaxHP mailboxes, laser-door
// Float_0, graphs/waypoints/selectors) remain untouched.
// ============================================================
static const char* R2R_BAST22_EXTRA_REPORT = "Rayman2Randomizer_Bast22ExtraStats.txt";

enum R2R_Bast22ExtraFieldKind
{
    R2R_BAST22_FIELD_FLOAT,
    R2R_BAST22_FIELD_INT
};
struct R2R_Bast22ExtraField
{
    unsigned int dsgIndex;
    R2R_Bast22ExtraFieldKind kind;
    float minFactor;
    float maxFactor;
    unsigned int randomSlot;
    const char* label;
};
struct R2R_Bast22ExtraTarget
{
    const char* family;
    const char* model;
    const char* personal;
    bool familyModelOnly;
    unsigned int fieldCount;
    R2R_Bast22ExtraField fields[8];
    bool mechanicsDt;
    float motionMin;
    float motionMax;
};
static const R2R_Bast22ExtraTarget g_R2RBast22ExtraTargets[] =
{
    // Storage/prototype bomb. Generated bombs inherit these DSG defaults, while
    // the already validated actor-local Bomb mechanics hook controls live travel.
    {
        "Bombe", "Alw_Bombe_Model", "Alw_Bombe", false, 5,
        {
            { 1, R2R_BAST22_FIELD_FLOAT, 0.25f, 4.00f, 0,  "Float_1 armed/vibration timeout" },
            { 2, R2R_BAST22_FIELD_FLOAT, 0.25f, 4.00f, 1,  "Float_2 pursuit timeout" },
            { 5, R2R_BAST22_FIELD_FLOAT, 0.25f, 4.00f, 2,  "Float_5 proximity threshold" },
            { 6, R2R_BAST22_FIELD_FLOAT, 0.25f, 4.00f, 50, "Float_6 random flight-speed lower bound" },
            { 7, R2R_BAST22_FIELD_FLOAT, 0.25f, 4.00f, 50, "Float_7 random flight-speed upper bound (linked)" }
        },
        false, 1.0f, 1.0f
    },
    // Progression helper: keep a wider feel while avoiding x0.25/x4 waypoint skips.
    {
        "rayman", "ARG_Rayseau", "ALW_Rayseau1", false, 0, {},
        true, 0.50f, 2.00f
    },
    // Rocket barrel: countdown is a true parameter; hard-coded movement is
    // randomized through actor-local mechanics time as in the validated Bast_20 barrel work.
    {
        "tonneau_boum", "BNT_TonneauFusee", "OLP_Tonneau_Machine", false, 1,
        {
            { 1, R2R_BAST22_FIELD_INT, 0.25f, 4.00f, 0, "Int_1 rocket countdown" }
        },
    // Generated by SUN_Tono_Generator right beside geometry. Slowing the
    // initial -6 fall below vanilla can leave it overlapping the machine/wall
    // long enough to collide/explode immediately. Keep MIN at vanilla speed.
    true, 1.00f, 4.00f
}
};
static const unsigned int R2R_BAST22_EXTRA_TARGET_COUNT =
static_cast<unsigned int>(sizeof(g_R2RBast22ExtraTargets) / sizeof(g_R2RBast22ExtraTargets[0]));
static const unsigned int R2R_BAST22_EXTRA_MAX_ACTORS = 64;
struct R2R_Bast22ExtraEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    unsigned int targetIndex;
    uint32_t rngKey;
    unsigned int visit;
    bool captured[8];
    bool forced[8];
    float original[8];
    float lastApplied[8];
    unsigned int mechanicsDtHits;
    R2R_StatsPlaytestMode loggedMode;
    unsigned int loggedGeneration;
};
static R2R_Bast22ExtraEntry g_R2RBast22ExtraEntries[R2R_BAST22_EXTRA_MAX_ACTORS] = {};
static HIE_tdstSuperObject* g_R2RBast22ExtraWorld = nullptr;
static HIE_tdstSuperObject* g_R2RBast22ExtraInactiveWorld = nullptr;
static unsigned int g_R2RBast22ExtraVisit = 0;
static bool g_R2RBast22ExtraReportStarted = false;

static int R2R_Bast22ExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_BAST22_EXTRA_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RBast22ExtraTargets[i];
        if (_stricmp(family, t.family) != 0 || _stricmp(model, t.model) != 0) continue;
        if (t.familyModelOnly) return static_cast<int>(i);
        if (personal != nullptr && _stricmp(personal, t.personal) == 0) return static_cast<int>(i);
    }
    return -1;
}
static float R2R_Bast22ExtraRandomFactor(unsigned int target, unsigned int randomSlot,
    uint32_t rngKey, float minFactor, float maxFactor)
{
    const int lo = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int hi = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = 0x42323200u ^ (target * 0x9E3779B9u) ^
        (randomSlot * 0x85EBCA6Bu) ^ (rngKey * 0x27D4EB2Du) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange("Stats.Bast22Extra.Factor", "Bast_22", salt, lo, hi) / 1000.0f;
}
static float R2R_Bast22ExtraDesiredFieldFactor(unsigned int target, unsigned int slot, uint32_t rngKey)
{
    if (target >= R2R_BAST22_EXTRA_TARGET_COUNT || slot >= g_R2RBast22ExtraTargets[target].fieldCount)
        return 1.0f;
    const auto& f = g_R2RBast22ExtraTargets[target].fields[slot];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return f.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return f.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Bast22ExtraRandomFactor(target, f.randomSlot, rngKey, f.minFactor, f.maxFactor);
    return 1.0f;
}
static float R2R_Bast22ExtraDesiredMotionFactor(unsigned int target, uint32_t rngKey)
{
    if (target >= R2R_BAST22_EXTRA_TARGET_COUNT || !g_R2RBast22ExtraTargets[target].mechanicsDt)
        return 1.0f;
    const auto& t = g_R2RBast22ExtraTargets[target];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return t.motionMin;
    if (mode == R2R_STATS_MODE_MAX) return t.motionMax;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Bast22ExtraRandomFactor(target, 100, rngKey, t.motionMin, t.motionMax);
    return 1.0f;
}
static bool R2R_Bast22ExtraGetRaw(HIE_tdstSuperObject* object,
    const R2R_Bast22ExtraField& field, void*& raw)
{
    raw = nullptr; AI_tdeDsgVarType type = AI_E_Nb_dvt;
    if (!AI_fn_bGetDsgVar(object, field.dsgIndex, &type, &raw) || raw == nullptr) return false;
    const AI_tdeDsgVarType wanted = field.kind == R2R_BAST22_FIELD_FLOAT ? AI_E_dvt_Float : AI_E_dvt_Integer;
    const size_t bytes = field.kind == R2R_BAST22_FIELD_FLOAT ? sizeof(float) : sizeof(int);
    return type == wanted && R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), bytes) &&
        R2R_Learn10ExtraWritable(raw, bytes);
}
static uint32_t R2R_Bast22ExtraActorKey(HIE_tdstSuperObject* object, HIE_tdstEngineObject* actor,
    const char* family, const char* model, const char* personal)
{
    GAM_tdstStandardGame* sg = nullptr;
    if (actor != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) &&
        actor->hStandardGame != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)))
        sg = actor->hStandardGame;
    return R2R_StatsActorSlotKey(object, sg, family, model, personal);
}
static void R2R_Bast22ExtraStartReport()
{
    if (g_R2RBast22ExtraReportStarted) return;
    FILE* f = nullptr; fopen_s(&f, R2R_BAST22_EXTRA_REPORT, "w");
    if (f == nullptr) return;
    fprintf(f,
        "%s BAST_22 ALL-IN EXPANDED STATS\n"
        "Controls: F6=MIN F7=MAX F8=RANDOM/reroll F12=NATIVE.\n"
        "Alw_Bombe: Float_1/2/5 x0.25..x4; linked Float_6/7 x0.25..x4; existing live Bomb mechanics hook retained.\n"
        "ALW_Rayseau1: actor-local mechanics time x0.5..x2 progression-safe.\n"
        "OLP_Tonneau_Machine: Int_1 countdown x0.25..x4 + actor-local mechanics time x1.00..x4 (generated-barrel wall-safe MIN).\n"
        "Generator brain frequency + animation are handled by Bast22Speed; cinematic MaxHP mailboxes and laser-door Float_0 remain untouched.\n\n",
        VERSION);
    fclose(f); g_R2RBast22ExtraReportStarted = true;
}
static void R2R_Bast22ExtraLog(R2R_Bast22ExtraEntry& e)
{
    if (e.loggedMode == R2R_StatsEffectiveMode() && e.loggedGeneration == g_R2RStatsPlaytestGeneration) return;
    R2R_Bast22ExtraStartReport(); FILE* f = nullptr; fopen_s(&f, R2R_BAST22_EXTRA_REPORT, "a");
    if (f == nullptr) return;
    const auto& t = g_R2RBast22ExtraTargets[e.targetIndex];
    fprintf(f, "[BAST22-EXTRA] %s / %s / %s owner=%p key=%08X mode=%s generation=%u",
        t.family, t.model, t.personal, static_cast<void*>(e.owner), e.rngKey,
        R2R_StatsModeName(R2R_StatsEffectiveMode()), g_R2RStatsPlaytestGeneration);
    for (unsigned int i = 0;i < t.fieldCount;++i)
        fprintf(f, " | %s native=%.6g applied=%.6g x%.3f", t.fields[i].label,
            e.original[i], e.lastApplied[i], R2R_Bast22ExtraDesiredFieldFactor(e.targetIndex, i, e.rngKey));
    if (t.mechanicsDt)
        fprintf(f, " | mechanics x%.3f hits=%u", R2R_Bast22ExtraDesiredMotionFactor(e.targetIndex, e.rngKey), e.mechanicsDtHits);
    fprintf(f, "\n"); fclose(f);
    e.loggedMode = R2R_StatsEffectiveMode(); e.loggedGeneration = g_R2RStatsPlaytestGeneration;
}
static void R2R_Bast22ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr || object == HIE_M_hGetMainActor() ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor) return;
    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int found = R2R_Bast22ExtraFindTarget(family, model, personal);
    if (found < 0) return;
    const unsigned int target = static_cast<unsigned int>(found);
    const auto& spec = g_R2RBast22ExtraTargets[target];
    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject))) return;
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0;i < R2R_BAST22_EXTRA_MAX_ACTORS;++i)
    {
        const auto& e = g_R2RBast22ExtraEntries[i];
        if (e.owner == object && e.actor == actor && e.targetIndex == target) { slot = static_cast<int>(i); break; }
        if (e.owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0; if (fresh) slot = freeSlot; if (slot < 0) return;
    auto& e = g_R2RBast22ExtraEntries[slot];
    if (fresh)
    {
        e = R2R_Bast22ExtraEntry(); e.owner = object; e.actor = actor; e.targetIndex = target;
        e.rngKey = R2R_Bast22ExtraActorKey(object, actor, family, model, personal);
        e.loggedMode = R2R_STATS_MODE_AUTO; e.loggedGeneration = UINT32_MAX;
    }
    e.visit = g_R2RBast22ExtraVisit;
    const auto mode = R2R_StatsEffectiveMode();
    for (unsigned int i = 0;i < spec.fieldCount;++i)
    {
        const auto& field = spec.fields[i]; void* raw = nullptr;
        if (!R2R_Bast22ExtraGetRaw(object, field, raw)) continue;
        float before = field.kind == R2R_BAST22_FIELD_FLOAT ? *reinterpret_cast<float*>(raw) :
            static_cast<float>(*reinterpret_cast<int*>(raw));
        if (!std::isfinite(before) || std::fabs(before) > 1000000.0f) continue;
        if (!e.captured[i] || !e.forced[i] || before != e.lastApplied[i])
        {
            e.original[i] = before; e.captured[i] = true;
        }
        float applied = before;
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (e.forced[i] && before == e.lastApplied[i] && e.captured[i]) applied = e.original[i];
            e.forced[i] = false;
        }
        else if (e.captured[i])
        {
            applied = e.original[i] * R2R_Bast22ExtraDesiredFieldFactor(target, i, e.rngKey);
            if (field.kind == R2R_BAST22_FIELD_INT && applied < 1.0f) applied = 1.0f;
            e.forced[i] = true;
        }
        if (field.kind == R2R_BAST22_FIELD_FLOAT)
        {
            if (std::isfinite(applied) && applied != before) *reinterpret_cast<float*>(raw) = applied;
        }
        else
        {
            int value = static_cast<int>(applied >= 0 ? applied + 0.5f : applied - 0.5f);
            if (value < 1) value = 1;
            if (static_cast<float>(value) != before) *reinterpret_cast<int*>(raw) = value;
            applied = static_cast<float>(value);
        }
        e.lastApplied[i] = applied;
    }
    R2R_Bast22ExtraLog(e);
}
static void R2R_Bast22ExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_Bast22ExtraProcess(root); HIE_tdstSuperObject* child = nullptr;
    LST_M_DynamicForEach(root, child) { if (child != nullptr) R2R_Bast22ExtraScan(child, depth + 1); }
}
static void R2R_Bast22ExtraForgetWorld()
{
    std::memset(g_R2RBast22ExtraEntries, 0, sizeof(g_R2RBast22ExtraEntries));
    g_R2RBast22ExtraWorld = nullptr; g_R2RBast22ExtraInactiveWorld = nullptr;
}
static void R2R_Bast22ExpandedTick()
{
    if (GAM_g_stEngineStructure == nullptr || GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Bast_22") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Bast22ExtraForgetWorld(); return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RBast22ExtraWorld || inactive != g_R2RBast22ExtraInactiveWorld)
    {
        R2R_Bast22ExtraForgetWorld(); g_R2RBast22ExtraWorld = active; g_R2RBast22ExtraInactiveWorld = inactive; R2R_Bast22ExtraStartReport();
    }
    ++g_R2RBast22ExtraVisit; R2R_Bast22ExtraScan(active, 0); if (inactive != active) R2R_Bast22ExtraScan(inactive, 0);
    for (unsigned int i = 0;i < R2R_BAST22_EXTRA_MAX_ACTORS;++i)
        if (g_R2RBast22ExtraEntries[i].visit != g_R2RBast22ExtraVisit) g_R2RBast22ExtraEntries[i] = R2R_Bast22ExtraEntry();
}
static MTH_tdxReal R2R_Bast22ExpandedMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    if (object == nullptr || dynamics == nullptr || object == HIE_M_hGetMainActor() ||
        R2R_StatsEffectiveMode() == R2R_STATS_MODE_NATIVE || GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Bast_22") != 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynamics), sizeof(DNM_tdstDynamicsBaseBlock)) ||
        !std::isfinite(dt) || dt <= 0 || dt > .25f) return dt;
    const int found = R2R_Bast22ExtraFindTarget(HIE_fn_szGetObjectFamilyName(object),
        HIE_fn_szGetObjectModelName(object), HIE_fn_szGetObjectPersonalName(object));
    if (found < 0) return dt; const unsigned int target = static_cast<unsigned int>(found);
    if (!g_R2RBast22ExtraTargets[target].mechanicsDt) return dt;
    for (auto& e : g_R2RBast22ExtraEntries)
    {
        if (e.owner != object || e.targetIndex != target || e.visit != g_R2RBast22ExtraVisit) continue;
        const float factor = R2R_Bast22ExtraDesiredMotionFactor(target, e.rngKey);
        const MTH_tdxReal applied = static_cast<MTH_tdxReal>(dt * factor);
        if (!std::isfinite(applied) || applied <= 0 || applied > 1.0f) return dt;
        ++e.mechanicsDtHits; return applied;
    }
    return dt;
}

