static const unsigned int R2R_BAST20_RATE_TARGET_COUNT =
static_cast<unsigned int>(sizeof(g_R2RBast20RateTargets) / sizeof(g_R2RBast20RateTargets[0]));
static const unsigned int R2R_BAST20_RATE_MAX_ACTORS = 128;

static bool R2R_Bast20RateNameMatches(const char* value, const char* wanted, bool prefix)
{
    if (value == nullptr || wanted == nullptr) return false;
    return prefix ? _strnicmp(value, wanted, std::strlen(wanted)) == 0 :
        _stricmp(value, wanted) == 0;
}
static int R2R_Bast20RateFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr || personal == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_BAST20_RATE_TARGET_COUNT; ++i)
    {
        const R2R_Bast20RateTarget& t = g_R2RBast20RateTargets[i];
        if (!R2R_Bast20RateNameMatches(family, t.family, (t.prefixFields & 1) != 0) ||
            !R2R_Bast20RateNameMatches(model, t.model, (t.prefixFields & 2) != 0) ||
            !R2R_Bast20RateNameMatches(personal, t.personal, (t.prefixFields & 4) != 0)) continue;
        if (t.personalSuffix != nullptr)
        {
            const size_t length = std::strlen(personal), suffixLength = std::strlen(t.personalSuffix);
            if (length < suffixLength || _stricmp(personal + length - suffixLength, t.personalSuffix)) continue;
        }
        return static_cast<int>(i);
    }
    return -1;
}
struct R2R_Bast20RateEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    GAM_tdst3dData* data;
    HIE_tdstState* lastState;
    unsigned int targetIndex;
    unsigned int original;
    int loggedMode;
    bool forced;

    // SUN_Tono_Generator also exposes the AI polling frequency in GAM_tdst3dData.
    bool brainFreqCaptured;
    bool brainFreqForced;
    unsigned int originalBrainFreq;
    unsigned int lastAppliedBrainFreq;
    R2R_StatsPlaytestMode brainFreqMode;
    unsigned int brainFreqGeneration;

    unsigned int visit;
};
static R2R_Bast20RateEntry g_R2RBast20RateEntries[R2R_BAST20_RATE_MAX_ACTORS] = {};
static bool g_R2RBast20RateDetected[R2R_BAST20_RATE_TARGET_COUNT] = {};
static bool g_R2RBast20RateUsable[R2R_BAST20_RATE_TARGET_COUNT] = {};
static bool g_R2RBast20RateErrorLogged[R2R_BAST20_RATE_TARGET_COUNT] = {};
static HIE_tdstSuperObject* g_R2RBast20RateWorld = nullptr;
static HIE_tdstSuperObject* g_R2RBast20RateInactiveWorld = nullptr;
static int g_R2RBast20RateMode = 0; // v18p: native animation and movement at startup.
static unsigned int g_R2RBast20RateVisit = 0;
static unsigned int g_R2RBast20RateFrame = 0;
static bool g_R2RBast20RateReportStarted = false;

static bool R2R_Bast20RateByteWritable(unsigned char* value)
{
    MEMORY_BASIC_INFORMATION info = {};
    if (value == nullptr || VirtualQuery(value, &info, sizeof(info)) == 0) return false;
    if (info.State != MEM_COMMIT || (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const DWORD protection = info.Protect & 0xff;
    return protection == PAGE_READWRITE || protection == PAGE_WRITECOPY ||
        protection == PAGE_EXECUTE_READWRITE || protection == PAGE_EXECUTE_WRITECOPY;
}
static void R2R_Bast20RateError(unsigned int target, const char* family,
    const char* model, const char* personal, const char* reason)
{
    if (g_R2RBast20RateErrorLogged[target]) return;
    FILE* f = nullptr;
    fopen_s(&f, R2R_BAST20_RATE_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[BAST20-SKIP] %s / %s / %s reason=%s\n", family, model, personal, reason);
    fclose(f);
    g_R2RBast20RateErrorLogged[target] = true;
}
static void R2R_Bast20RateLog(unsigned int index, const char* action,
    unsigned int before, unsigned int after)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_BAST20_RATE_REPORT, "a");
    if (f == nullptr) return;
    const R2R_Bast20RateEntry& e = g_R2RBast20RateEntries[index];
    HIE_tdstState* state = e.data->h_CurrentState;
    const bool readable = state != nullptr && R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(state), sizeof(HIE_tdstState));
    fprintf(f, "[BAST20-ANIMRATE] %s / %s / %s target=%u action=%s mode=%d "
        "original=%u before=%u applied=%u state=%p cSpeedAnim=%d owner=%p data=%p\n",
        HIE_fn_szGetObjectFamilyName(e.owner), HIE_fn_szGetObjectModelName(e.owner),
        HIE_fn_szGetObjectPersonalName(e.owner), e.targetIndex + 1, action,
        g_R2RBast20RateMode, e.original, before, after, static_cast<void*>(state),
        readable ? static_cast<int>(state->cSpeedAnim) : -1,
        static_cast<void*>(e.owner), static_cast<void*>(e.data));
    fclose(f);
}
static float R2R_Bast20GeneratorBrainFactor(unsigned int target)
{
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return 1.0f;
    if (mode == R2R_STATS_MODE_MIN) return 0.25f;
    if (mode == R2R_STATS_MODE_MAX) return 4.0f;
    if (mode == R2R_STATS_MODE_RANDOM)
    {
        const uint32_t salt = 0x47454E46u ^ (target * 0x9E3779B9u) ^
            (g_R2RStatsPlaytestGeneration * 0x85EBCA6Bu);
        return R2R_RollRange("Stats.Bast20Generator.BrainFrequency", "Bast_20",
            salt, 250, 4000) / 1000.0f;
    }
    return 1.0f;
}

static void R2R_Bast20GeneratorBrainFrequency(R2R_Bast20RateEntry& e,
    GAM_tdst3dData* data, unsigned int target, const char* personal)
{
    if (data == nullptr || !R2R_Bast20RateByteWritable(&data->ucBrainComputationFrequency)) return;
    unsigned int before = data->ucBrainComputationFrequency;
    if (before == 0) return;

    if (!e.brainFreqCaptured || !e.brainFreqForced || before != e.lastAppliedBrainFreq)
    {
        e.originalBrainFreq = before;
        e.brainFreqCaptured = true;
    }
    if (!e.brainFreqCaptured) return;

    const auto mode = R2R_StatsEffectiveMode();
    const bool reroll = e.brainFreqMode != mode ||
        e.brainFreqGeneration != g_R2RStatsPlaytestGeneration;
    const float factor = R2R_Bast20GeneratorBrainFactor(target);
    unsigned int desired = e.originalBrainFreq;
    if (mode != R2R_STATS_MODE_NATIVE)
    {
        desired = static_cast<unsigned int>(e.originalBrainFreq * factor + 0.5f);
        if (desired < 1) desired = 1;
        if (desired > 255) desired = 255;
    }

    bool brainFrequencyChanged = false;
    if (mode == R2R_STATS_MODE_NATIVE)
    {
        if (e.brainFreqForced && before == e.lastAppliedBrainFreq &&
            before != desired)
        {
            data->ucBrainComputationFrequency = static_cast<unsigned char>(desired);
            brainFrequencyChanged = true;
        }
        e.brainFreqForced = false;
    }
    else
    {
        if (before != desired)
        {
            data->ucBrainComputationFrequency = static_cast<unsigned char>(desired);
            brainFrequencyChanged = true;
        }
        e.brainFreqForced = true;
    }

    // IMPORTANT: cBrainCounter must be allowed to advance. g1 reset it to zero
    // every scan, which could prevent SUN_Tono_Generator from ever executing its
    // polling script and therefore from re-activating OLP_Tonneau_DK / DK_2.
    // Reset only when the requested frequency actually changes (or on reroll).
    if ((brainFrequencyChanged || reroll) &&
        R2R_Bast20RateByteWritable(reinterpret_cast<unsigned char*>(&data->cBrainCounter)))
        data->cBrainCounter = 0;
    e.lastAppliedBrainFreq = data->ucBrainComputationFrequency;

    if (reroll)
    {
        FILE* f = nullptr;
        fopen_s(&f, R2R_BAST20_RATE_REPORT, "a");
        if (f != nullptr)
        {
            fprintf(f, "[BAST20-GENERATOR] %s brainFreq native=%u applied=%u x%.3f mode=%s generation=%u\n",
                personal != nullptr ? personal : "(null)", e.originalBrainFreq,
                e.lastAppliedBrainFreq, factor, R2R_StatsModeName(mode),
                g_R2RStatsPlaytestGeneration);
            fclose(f);
        }
    }
    e.brainFreqMode = mode;
    e.brainFreqGeneration = g_R2RStatsPlaytestGeneration;
}

static void R2R_Bast20RateProcess(HIE_tdstSuperObject* object)
{
    if (object == HIE_M_hGetMainActor()) return;
    if (object == nullptr || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor) return;
    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int target = R2R_Bast20RateFindTarget(family, model, personal);
    if (target < 0) return;
    R2R_NoMomentumObserveTarget(object);
    g_R2RBast20RateDetected[target] = true;

    // v0.0.19g.2 ALL-IN: gameplay pirates, the cinematic pirate's ANIMATION,
    // missiles, thrown barrels and barrel generators participate in animation-rate randomization.
    // SDZ_Sbire_Cine's HP-Max is a command mailbox (1,2,3...99), so only its
    // visible animation rate is randomized; the command channel itself is never touched.
    const bool protectedController =
        (model != nullptr && (_stricmp(model, "CHR_Porte") == 0 ||
            _stricmp(model, "OLP_PorteLaser_Switch") == 0));
    const bool allInExpandedAnimation =
        (family != nullptr && _stricmp(family, "pirate_sbire") == 0) ||
        (model != nullptr && (_stricmp(model, "OLD_alw_tonneau_model") == 0 ||
            _stricmp(model, "SUN_basic") == 0 ||
            _stricmp(model, "SUN_Tono_Generator") == 0));
    const bool expandedStatsOwnsActor = target >= 15 && !allInExpandedAnimation;
    if (protectedController || expandedStatsOwnsActor)
    {
        R2R_Bast20RateError(target, family, model, personal,
            protectedController
            ? "progression door/controller: animation kept native"
            : "expanded Bast_20 Stats actor: animation kept native");
        return;
    }

    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)))
    {
        R2R_Bast20RateError(target, family, model, personal, "actor unavailable");
        return;
    }
    GAM_tdst3dData* data = actor->h3dData;
    if (data == nullptr || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(data), sizeof(GAM_tdst3dData)))
    {
        R2R_Bast20RateError(target, family, model, personal, "no readable actor-local animation data");
        return;
    }
    if (!R2R_Bast20RateByteWritable(&data->ucFrameRate))
    {
        R2R_Bast20RateError(target, family, model, personal, "animation-rate byte is not writable");
        return;
    }
    // Separate entries preserve each live actor's original rate, including
    // multiple instances with the same exact names.
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_BAST20_RATE_MAX_ACTORS; ++i)
    {
        const R2R_Bast20RateEntry& e = g_R2RBast20RateEntries[i];
        if (e.owner == object && e.actor == actor && e.data == data &&
            e.targetIndex == static_cast<unsigned int>(target)) {
            slot = static_cast<int>(i); break;
        }
        if (e.owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0)
    {
        R2R_Bast20RateError(target, family, model, personal, "actor tracking table full");
        return;
    }
    R2R_Bast20RateEntry& e = g_R2RBast20RateEntries[slot];
    const unsigned int before = data->ucFrameRate;
    if (fresh)
    {
        e = R2R_Bast20RateEntry();
        e.owner = object; e.actor = actor; e.data = data;
        e.targetIndex = static_cast<unsigned int>(target);
        e.original = before; e.loggedMode = -1;
        e.brainFreqMode = R2R_STATS_MODE_AUTO;
        e.brainFreqGeneration = UINT32_MAX;
    }
    if (!e.forced || before != static_cast<unsigned int>(e.loggedMode)) e.original = before;
    e.visit = g_R2RBast20RateVisit;
    g_R2RBast20RateUsable[target] = true;
    const bool log = e.loggedMode != g_R2RBast20RateMode || e.lastState != data->h_CurrentState;
    if (g_R2RBast20RateMode == 0)
    {
        if (e.forced)
        {
            data->ucFrameRate = static_cast<unsigned char>(e.original);
            R2R_Bast20RateLog(slot, "RESTORE", before, data->ucFrameRate);
            e.forced = false;
        }
        else if (log) R2R_Bast20RateLog(slot, "VANILLA", before, before);
    }
    else
    {
        data->ucFrameRate = static_cast<unsigned char>(g_R2RBast20RateMode);
        if (log) R2R_Bast20RateLog(slot, "APPLY", before, data->ucFrameRate);
        e.forced = true;
    }
    if (model != nullptr && _stricmp(model, "SUN_Tono_Generator") == 0)
        R2R_Bast20GeneratorBrainFrequency(e, data, static_cast<unsigned int>(target), personal);

    e.loggedMode = g_R2RBast20RateMode;
    e.lastState = data->h_CurrentState;
}
static void R2R_Bast20RateScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_Bast20RateProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr) R2R_Bast20RateScan(object, depth + 1);
    }
}
static void R2R_Bast20RateForgetWorld()
{
    std::memset(g_R2RBast20RateEntries, 0, sizeof(g_R2RBast20RateEntries));
    std::memset(g_R2RBast20RateErrorLogged, 0, sizeof(g_R2RBast20RateErrorLogged));
    g_R2RBast20RateWorld = nullptr; g_R2RBast20RateInactiveWorld = nullptr;
    g_R2RBast20RateFrame = 0;
}
static void R2R_Bast20RateTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Bast_20") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Bast20RateForgetWorld();
        return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RBast20RateWorld || inactive != g_R2RBast20RateInactiveWorld)
    {
        // Keep matching live actors across an in-level root change so F8
        // restores the baseline rather than recapturing the forced rate.
        // The scan validates owner/actor/data and prunes missing entries.
        g_R2RBast20RateWorld = active; g_R2RBast20RateInactiveWorld = inactive;
        FILE* f = nullptr;
        fopen_s(&f, R2R_BAST20_RATE_REPORT, g_R2RBast20RateReportStarted ? "a" : "w");
        if (f != nullptr)
        {
            fprintf(f, "\n%s BAST20 ANIMATION TEST: %u target rules, "
                "global Stats controls: F6=MIN F7=MAX F8=RANDOM F12=NATIVE. "
                "Full runtime identities are logged; Bast_20 uses exact identities only.\n",
                VERSION, R2R_BAST20_RATE_TARGET_COUNT);
            fclose(f); g_R2RBast20RateReportStarted = true;
        }
    }
    std::memset(g_R2RBast20RateDetected, 0, sizeof(g_R2RBast20RateDetected));
    std::memset(g_R2RBast20RateUsable, 0, sizeof(g_R2RBast20RateUsable));
    ++g_R2RBast20RateVisit;
    R2R_Bast20RateScan(active, 0);
    if (inactive != active) R2R_Bast20RateScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_BAST20_RATE_MAX_ACTORS; ++i)
        if (g_R2RBast20RateEntries[i].visit != g_R2RBast20RateVisit)
            g_R2RBast20RateEntries[i] = R2R_Bast20RateEntry();
    if ((g_R2RBast20RateFrame++ % 300) == 0)
    {
        FILE* f = nullptr;
        fopen_s(&f, R2R_BAST20_RATE_REPORT, "a");
        if (f == nullptr) return;
        unsigned int detected = 0, usable = 0, actors = 0;
        for (unsigned int i = 0; i < R2R_BAST20_RATE_TARGET_COUNT; ++i)
        {
            if (g_R2RBast20RateDetected[i]) ++detected;
            if (g_R2RBast20RateUsable[i]) ++usable;
            if (!g_R2RBast20RateDetected[i])
            {
                const R2R_Bast20RateTarget& t = g_R2RBast20RateTargets[i];
                fprintf(f, "[BAST20-NOT-FOUND] target=%u %s / %s / %s "
                    "prefixFields=%u suffix=%s\n", i + 1, t.family, t.model, t.personal,
                    t.prefixFields, t.personalSuffix != nullptr ? t.personalSuffix : "(none)");
            }
        }
        for (unsigned int i = 0; i < R2R_BAST20_RATE_MAX_ACTORS; ++i)
            if (g_R2RBast20RateEntries[i].owner != nullptr) ++actors;
        fprintf(f, "[BAST20-SUMMARY] detected=%u/%u animationData=%u/%u "
            "trackedActors=%u mode=%d\n", detected, R2R_BAST20_RATE_TARGET_COUNT,
            usable, R2R_BAST20_RATE_TARGET_COUNT, actors, g_R2RBast20RateMode);
        fclose(f);
    }
}

