static const unsigned int R2R_SKI10_EXTRA_TARGET_COUNT =
static_cast<unsigned int>(sizeof(g_R2RSki10ExtraTargets) / sizeof(g_R2RSki10ExtraTargets[0]));
static const unsigned int R2R_SKI10_EXTRA_MAX_ACTORS = 128;

struct R2R_Ski10ExtraEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    unsigned int targetIndex;
    uint32_t rngKey;
    unsigned int visit;
    bool captured[4];
    bool forced[4];
    float originalScalar[4];
    float lastAppliedScalar[4];
    MTH3D_tdstVector originalVector[4];
    MTH3D_tdstVector lastAppliedVector[4];
    unsigned int mechanicsDtHits;
    R2R_StatsPlaytestMode loggedMode;
    unsigned int loggedGeneration;
};
static R2R_Ski10ExtraEntry g_R2RSki10ExtraEntries[R2R_SKI10_EXTRA_MAX_ACTORS] = {};
static HIE_tdstSuperObject* g_R2RSki10ExtraWorld = nullptr;
static HIE_tdstSuperObject* g_R2RSki10ExtraInactiveWorld = nullptr;
static unsigned int g_R2RSki10ExtraVisit = 0;
static bool g_R2RSki10ExtraReportStarted = false;

static bool R2R_Ski10ExtraVectorFinite(const MTH3D_tdstVector& v)
{
    return std::isfinite(v.x) && std::isfinite(v.y) && std::isfinite(v.z) &&
        std::fabs(v.x) <= 100000.0f && std::fabs(v.y) <= 100000.0f && std::fabs(v.z) <= 100000.0f;
}
static bool R2R_Ski10ExtraVectorEqual(const MTH3D_tdstVector& a, const MTH3D_tdstVector& b)
{
    return a.x == b.x && a.y == b.y && a.z == b.z;
}
static int R2R_Ski10ExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr || personal == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_SKI10_EXTRA_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RSki10ExtraTargets[i];
        if (_stricmp(family, t.family) == 0 &&
            _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0) return static_cast<int>(i);
    }
    return -1;
}
static float R2R_Ski10ExtraRandomFactor(unsigned int target, unsigned int randomSlot,
    uint32_t rngKey, float minFactor, float maxFactor)
{
    const int lo = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int hi = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = 0x534B3130u ^ (target * 0x9E3779B9u) ^
        (randomSlot * 0x85EBCA6Bu) ^ (rngKey * 0x27D4EB2Du) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange("Stats.Ski10Extra.Factor", "Ski_10", salt, lo, hi) / 1000.0f;
}
static float R2R_Ski10ExtraDesiredFieldFactor(unsigned int target, unsigned int slot, uint32_t rngKey)
{
    if (target >= R2R_SKI10_EXTRA_TARGET_COUNT ||
        slot >= g_R2RSki10ExtraTargets[target].fieldCount) return 1.0f;
    const auto& field = g_R2RSki10ExtraTargets[target].fields[slot];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return field.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return field.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Ski10ExtraRandomFactor(target, field.randomSlot, rngKey,
            field.minFactor, field.maxFactor);
    return 1.0f;
}
static float R2R_Ski10ExtraDesiredMotionFactor(unsigned int target, uint32_t rngKey)
{
    if (target >= R2R_SKI10_EXTRA_TARGET_COUNT || !g_R2RSki10ExtraTargets[target].mechanicsDt)
        return 1.0f;
    const auto& t = g_R2RSki10ExtraTargets[target];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return t.motionMin;
    if (mode == R2R_STATS_MODE_MAX) return t.motionMax;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Ski10ExtraRandomFactor(target, 100, rngKey, t.motionMin, t.motionMax);
    return 1.0f;
}
static bool R2R_Ski10ExtraGetRaw(HIE_tdstSuperObject* object,
    const R2R_Ski10ExtraField& field, void*& raw)
{
    raw = nullptr; AI_tdeDsgVarType type = AI_E_Nb_dvt;
    if (!AI_fn_bGetDsgVar(object, field.dsgIndex, &type, &raw) || raw == nullptr) return false;
    AI_tdeDsgVarType wanted = AI_E_Nb_dvt; size_t bytes = 0;
    if (field.kind == R2R_SKI10_FIELD_FLOAT) { wanted = AI_E_dvt_Float; bytes = sizeof(float); }
    else if (field.kind == R2R_SKI10_FIELD_INT) { wanted = AI_E_dvt_Integer; bytes = sizeof(int); }
    else { wanted = AI_E_dvt_Vector; bytes = sizeof(MTH3D_tdstVector); }
    return type == wanted && R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), bytes) &&
        R2R_Learn10ExtraWritable(raw, bytes);
}
static uint32_t R2R_Ski10ExtraActorKey(HIE_tdstSuperObject* object, HIE_tdstEngineObject* actor,
    const char* family, const char* model, const char* personal)
{
    GAM_tdstStandardGame* sg = nullptr;
    if (actor != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) &&
        actor->hStandardGame != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)))
        sg = actor->hStandardGame;
    return R2R_StatsActorSlotKey(object, sg, family, model, personal);
}
static void R2R_Ski10ExtraStartReport()
{
    if (g_R2RSki10ExtraReportStarted) return;
    FILE* f = nullptr; fopen_s(&f, R2R_SKI10_EXTRA_REPORT, "w"); if (f == nullptr) return;
    fprintf(f,
        "%s SKI_10 ALL-IN EXPANDED STATS\n"
        "Controls: F6=MIN F7=MAX F8=RANDOM/reroll F12=NATIVE.\n"
        "MIC_Ski_Serpent: existing waypoint command randomizer retained; PERMANENT MAX x1.5, never stacked with this module.\n"
        "Two MIC_PiranhaHaineux: Int_0 jump wait + Float_3 attack radius x0.25..x4; movement stays owned by validated Ski10Path x0.25..x4.\n"
        "Five MIC_PouletFantome actors: Vector_1 initial movement + actor-local ongoing mechanics x0.25..x4.\n"
        "Three MIC_OctusDiabolus: hard-coded bounce movement through actor-local mechanics x0.25..x4; Float_0 baseline Z protected.\n"
        "MIC_Ski_Rayman, graph/waypoints/selectors and all cinematic command-mailbox MaxHP fields remain native.\n"
        "Six MIC_PtiPiranhaSolo animation identities corrected to the exact Raymap spelling.\n\n", VERSION);
    fclose(f); g_R2RSki10ExtraReportStarted = true;
}
static void R2R_Ski10ExtraLog(R2R_Ski10ExtraEntry& e)
{
    if (e.loggedMode == R2R_StatsEffectiveMode() &&
        e.loggedGeneration == g_R2RStatsPlaytestGeneration) return;
    R2R_Ski10ExtraStartReport();
    FILE* f = nullptr; fopen_s(&f, R2R_SKI10_EXTRA_REPORT, "a"); if (f == nullptr) return;
    const auto& t = g_R2RSki10ExtraTargets[e.targetIndex];
    fprintf(f, "[SKI10-EXTRA] %s / %s / %s owner=%p key=%08X mode=%s generation=%u",
        t.family, t.model, t.personal, static_cast<void*>(e.owner), e.rngKey,
        R2R_StatsModeName(R2R_StatsEffectiveMode()), g_R2RStatsPlaytestGeneration);
    for (unsigned int i = 0; i < t.fieldCount; ++i)
    {
        if (t.fields[i].kind == R2R_SKI10_FIELD_VECTOR)
            fprintf(f, " | %s x%.3f", t.fields[i].label,
                R2R_Ski10ExtraDesiredFieldFactor(e.targetIndex, i, e.rngKey));
        else
            fprintf(f, " | %s native=%.6g applied=%.6g x%.3f", t.fields[i].label,
                e.originalScalar[i], e.lastAppliedScalar[i],
                R2R_Ski10ExtraDesiredFieldFactor(e.targetIndex, i, e.rngKey));
    }
    if (t.mechanicsDt)
        fprintf(f, " | mechanics x%.3f hits=%u",
            R2R_Ski10ExtraDesiredMotionFactor(e.targetIndex, e.rngKey), e.mechanicsDtHits);
    fprintf(f, "\n"); fclose(f);
    e.loggedMode = R2R_StatsEffectiveMode();
    e.loggedGeneration = g_R2RStatsPlaytestGeneration;
}
static void R2R_Ski10ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr || object == HIE_M_hGetMainActor() ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor) return;

    R2R_Ski10Identity identity = {};
    if (!R2R_Ski10ReadIdentity(object, identity)) return;
    const int found = R2R_Ski10ExtraFindTarget(identity.family, identity.model, identity.personal);
    if (found < 0) return;
    const unsigned int target = static_cast<unsigned int>(found);
    const auto& spec = g_R2RSki10ExtraTargets[target];
    HIE_tdstEngineObject* actor = identity.actor;
    if (actor == nullptr || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject))) return;

    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_SKI10_EXTRA_MAX_ACTORS; ++i)
    {
        const auto& e = g_R2RSki10ExtraEntries[i];
        if (e.owner == object && e.actor == actor && e.targetIndex == target)
        {
            slot = static_cast<int>(i); break;
        }
        if (e.owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0; if (fresh) slot = freeSlot; if (slot < 0) return;
    auto& e = g_R2RSki10ExtraEntries[slot];
    if (fresh)
    {
        e = R2R_Ski10ExtraEntry(); e.owner = object; e.actor = actor; e.targetIndex = target;
        e.rngKey = R2R_Ski10ExtraActorKey(object, actor, identity.family, identity.model, identity.personal);
        e.loggedMode = R2R_STATS_MODE_AUTO; e.loggedGeneration = UINT32_MAX;
    }
    e.visit = g_R2RSki10ExtraVisit;
    const auto mode = R2R_StatsEffectiveMode();

    for (unsigned int i = 0; i < spec.fieldCount; ++i)
    {
        const auto& field = spec.fields[i]; void* raw = nullptr;
        if (!R2R_Ski10ExtraGetRaw(object, field, raw)) continue;

        if (field.kind == R2R_SKI10_FIELD_VECTOR)
        {
            const auto before = *reinterpret_cast<MTH3D_tdstVector*>(raw);
            if (!R2R_Ski10ExtraVectorFinite(before)) continue;
            if (!e.captured[i] || !e.forced[i] || !R2R_Ski10ExtraVectorEqual(before, e.lastAppliedVector[i]))
            {
                e.originalVector[i] = before; e.captured[i] = true;
            }
            auto applied = before;
            if (mode == R2R_STATS_MODE_NATIVE)
            {
                if (e.forced[i] && e.captured[i] &&
                    R2R_Ski10ExtraVectorEqual(before, e.lastAppliedVector[i])) applied = e.originalVector[i];
                e.forced[i] = false;
            }
            else if (e.captured[i])
            {
                const float factor = R2R_Ski10ExtraDesiredFieldFactor(target, i, e.rngKey);
                applied = { e.originalVector[i].x * factor,
                            e.originalVector[i].y * factor,
                            e.originalVector[i].z * factor };
                e.forced[i] = true;
            }
            if (R2R_Ski10ExtraVectorFinite(applied) &&
                !R2R_Ski10ExtraVectorEqual(applied, before))
                *reinterpret_cast<MTH3D_tdstVector*>(raw) = applied;
            e.lastAppliedVector[i] = applied;
            continue;
        }

        float before = field.kind == R2R_SKI10_FIELD_FLOAT ?
            *reinterpret_cast<float*>(raw) : static_cast<float>(*reinterpret_cast<int*>(raw));
        if (!std::isfinite(before) || std::fabs(before) > 1000000.0f) continue;
        if (!e.captured[i] || !e.forced[i] || before != e.lastAppliedScalar[i])
        {
            e.originalScalar[i] = before; e.captured[i] = true;
        }
        float applied = before;
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (e.forced[i] && e.captured[i] && before == e.lastAppliedScalar[i]) applied = e.originalScalar[i];
            e.forced[i] = false;
        }
        else if (e.captured[i])
        {
            applied = e.originalScalar[i] * R2R_Ski10ExtraDesiredFieldFactor(target, i, e.rngKey);
            e.forced[i] = true;
        }

        if (field.kind == R2R_SKI10_FIELD_FLOAT)
        {
            if (std::isfinite(applied) && applied != before) *reinterpret_cast<float*>(raw) = applied;
        }
        else
        {
            int value = static_cast<int>(applied >= 0 ? applied + 0.5f : applied - 0.5f);
            if (value < 1) value = 1;
            if (static_cast<float>(value) != before) *reinterpret_cast<int*>(raw) = value;
            applied = static_cast<float>(value);
        }
        e.lastAppliedScalar[i] = applied;
    }
    R2R_Ski10ExtraLog(e);
}
static void R2R_Ski10ExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_Ski10ExtraProcess(root);
    HIE_tdstSuperObject* child = nullptr;
    LST_M_DynamicForEach(root, child)
    {
        if (child != nullptr) R2R_Ski10ExtraScan(child, depth + 1);
    }
}
static void R2R_Ski10ExtraForgetWorld()
{
    std::memset(g_R2RSki10ExtraEntries, 0, sizeof(g_R2RSki10ExtraEntries));
    g_R2RSki10ExtraWorld = nullptr; g_R2RSki10ExtraInactiveWorld = nullptr;
}
static void R2R_Ski10ExpandedTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Ski_10") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Ski10ExtraForgetWorld(); return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ?
        *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RSki10ExtraWorld || inactive != g_R2RSki10ExtraInactiveWorld)
    {
        R2R_Ski10ExtraForgetWorld();
        g_R2RSki10ExtraWorld = active; g_R2RSki10ExtraInactiveWorld = inactive;
        R2R_Ski10ExtraStartReport();
    }
    ++g_R2RSki10ExtraVisit;
    R2R_Ski10ExtraScan(active, 0);
    if (inactive != active) R2R_Ski10ExtraScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_SKI10_EXTRA_MAX_ACTORS; ++i)
        if (g_R2RSki10ExtraEntries[i].visit != g_R2RSki10ExtraVisit)
            g_R2RSki10ExtraEntries[i] = R2R_Ski10ExtraEntry();
}
static MTH_tdxReal R2R_Ski10ExpandedMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    if (object == nullptr || dynamics == nullptr || object == HIE_M_hGetMainActor() ||
        R2R_StatsEffectiveMode() == R2R_STATS_MODE_NATIVE ||
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Ski_10") != 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynamics), sizeof(DNM_tdstDynamicsBaseBlock)) ||
        !std::isfinite(dt) || dt <= 0 || dt > .25f) return dt;

    R2R_Ski10Identity identity = {};
    if (!R2R_Ski10ReadIdentity(object, identity)) return dt;
    const int found = R2R_Ski10ExtraFindTarget(identity.family, identity.model, identity.personal);
    if (found < 0) return dt;
    const unsigned int target = static_cast<unsigned int>(found);
    if (!g_R2RSki10ExtraTargets[target].mechanicsDt) return dt;

    for (auto& e : g_R2RSki10ExtraEntries)
    {
        if (e.owner != object || e.targetIndex != target || e.visit != g_R2RSki10ExtraVisit) continue;
        const float factor = R2R_Ski10ExtraDesiredMotionFactor(target, e.rngKey);
        const MTH_tdxReal applied = static_cast<MTH_tdxReal>(dt * factor);
        if (!std::isfinite(applied) || applied <= 0 || applied > 1.0f) return dt;
        ++e.mechanicsDtHits;
        return applied;
    }
    return dt;
}

// v0.0.18x.0: 14 Ski_60 animation rules: 13 exact identities and one visible personal-name prefix.
