struct R2R_Chase10ExtraEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    unsigned int targetIndex;
    uint32_t rngKey;
    unsigned int visit;
    bool captured[16];
    bool forced[16];
    float originalScalar[16];
    float lastAppliedScalar[16];
    MTH3D_tdstVector originalVector[16];
    MTH3D_tdstVector lastAppliedVector[16];
    bool hpCaptured;
    bool hpForced;
    unsigned char originalHP;
    unsigned char originalHPMax;
    unsigned char originalHPMaxMax;
    unsigned char lastAppliedHP;
    unsigned char lastAppliedHPMax;
    R2R_StatsPlaytestMode hpAppliedMode;
    unsigned int hpAppliedGeneration;
    unsigned int mechanicsDtHits;
    R2R_StatsPlaytestMode loggedMode;
    unsigned int loggedGeneration;
};
static R2R_Chase10ExtraEntry g_R2RChase10ExtraEntries[R2R_CHASE10_EXTRA_MAX_ACTORS] = {};
static HIE_tdstSuperObject* g_R2RChase10ExtraWorld = nullptr;
static HIE_tdstSuperObject* g_R2RChase10ExtraInactiveWorld = nullptr;
static unsigned int g_R2RChase10ExtraVisit = 0;
static bool g_R2RChase10ExtraReportStarted = false;

static bool R2R_Chase10ExtraVectorFinite(const MTH3D_tdstVector& v)
{
    return std::isfinite(v.x) && std::isfinite(v.y) && std::isfinite(v.z) &&
        std::fabs(v.x) <= 100000.0f && std::fabs(v.y) <= 100000.0f && std::fabs(v.z) <= 100000.0f;
}
static bool R2R_Chase10ExtraVectorEqual(const MTH3D_tdstVector& a, const MTH3D_tdstVector& b)
{
    return a.x == b.x && a.y == b.y && a.z == b.z;
}
static int R2R_Chase10ExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_CHASE10_EXTRA_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RChase10ExtraTargets[i];
        if (_stricmp(family, t.family) != 0 || _stricmp(model, t.model) != 0) continue;
        if (t.familyModelOnly) return static_cast<int>(i);
        if (personal != nullptr && _stricmp(personal, t.personal) == 0) return static_cast<int>(i);
    }
    return -1;
}
static float R2R_Chase10ExtraRandomFactor(unsigned int target, unsigned int randomSlot,
    uint32_t rngKey, float minFactor, float maxFactor)
{
    const int lo = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int hi = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = 0x43483130u ^ (target * 0x9E3779B9u) ^
        (randomSlot * 0x85EBCA6Bu) ^ (rngKey * 0x27D4EB2Du) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange("Stats.Chase10Extra.Factor", "Chase_10", salt, lo, hi) / 1000.0f;
}
static float R2R_Chase10ExtraDesiredFactor(unsigned int target, unsigned int slot, uint32_t rngKey)
{
    if (target >= R2R_CHASE10_EXTRA_TARGET_COUNT || slot >= g_R2RChase10ExtraTargets[target].fieldCount)
        return 1.0f;
    const auto& f = g_R2RChase10ExtraTargets[target].fields[slot];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return f.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return f.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Chase10ExtraRandomFactor(target, f.randomSlot, rngKey, f.minFactor, f.maxFactor);
    return 1.0f;
}
static float R2R_Chase10ExtraDesiredMotionFactor(unsigned int target, uint32_t rngKey)
{
    if (target >= R2R_CHASE10_EXTRA_TARGET_COUNT || !g_R2RChase10ExtraTargets[target].mechanicsDt)
        return 1.0f;
    const auto& t = g_R2RChase10ExtraTargets[target];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return t.motionMin;
    if (mode == R2R_STATS_MODE_MAX) return t.motionMax;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Chase10ExtraRandomFactor(target, 100, rngKey, t.motionMin, t.motionMax);
    return 1.0f;
}
static bool R2R_Chase10ExtraGetRaw(HIE_tdstSuperObject* object,
    const R2R_Chase10ExtraField& field, void*& raw)
{
    raw = nullptr; AI_tdeDsgVarType type = AI_E_Nb_dvt;
    if (!AI_fn_bGetDsgVar(object, field.dsgIndex, &type, &raw) || raw == nullptr) return false;
    AI_tdeDsgVarType wanted = AI_E_Nb_dvt; size_t bytes = 0;
    if (field.kind == R2R_CHASE10_FIELD_FLOAT) { wanted = AI_E_dvt_Float; bytes = sizeof(float); }
    else if (field.kind == R2R_CHASE10_FIELD_INT) { wanted = AI_E_dvt_Integer; bytes = sizeof(int); }
    else { wanted = AI_E_dvt_Vector; bytes = sizeof(MTH3D_tdstVector); }
    return type == wanted && R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), bytes) &&
        R2R_Learn10ExtraWritable(raw, bytes);
}
static uint32_t R2R_Chase10ExtraActorKey(HIE_tdstSuperObject* object, HIE_tdstEngineObject* actor,
    const char* family, const char* model, const char* personal)
{
    GAM_tdstStandardGame* sg = nullptr;
    if (actor != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) &&
        actor->hStandardGame != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)))
        sg = actor->hStandardGame;
    return R2R_StatsActorSlotKey(object, sg, family, model, personal != nullptr ? personal : "");
}
static unsigned int R2R_Chase10ExtraDesiredPirateHP(const R2R_Chase10ExtraEntry& e)
{
    if (!e.hpCaptured) return 0;
    int upper = static_cast<int>(e.originalHPMax) * 3;
    if (upper < 2) upper = 2;
    if (upper > 12) upper = 12;
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return e.originalHPMax;
    if (mode == R2R_STATS_MODE_MIN) return 1u;
    if (mode == R2R_STATS_MODE_MAX) return static_cast<unsigned int>(upper);
    if (mode == R2R_STATS_MODE_RANDOM)
    {
        const uint32_t salt = 0x43485050u ^ e.rngKey ^
            (g_R2RStatsPlaytestGeneration * 0x9E3779B9u);
        return static_cast<unsigned int>(R2R_RollRange("Stats.Chase10Pirate.HP", "Chase_10", salt, 1, upper));
    }
    return e.originalHPMax;
}
static void R2R_Chase10ExtraApplyPirateHP(R2R_Chase10ExtraEntry& e,
    HIE_tdstEngineObject* actor, bool enabled)
{
    if (!enabled || actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)) ||
        !R2R_Learn10ExtraWritable(actor->hStandardGame, sizeof(GAM_tdstStandardGame))) return;
    GAM_tdstStandardGame* sg = actor->hStandardGame;
    unsigned int hp = sg->ucHitPoints, hpMax = sg->ucHitPointsMax, hpMaxMax = sg->ucHitPointsMaxMax;
    const bool plausible = hp > 0 && hp == hpMax && hpMax <= 20;
    if (!e.hpCaptured)
    {
        if (!plausible) return;
        e.originalHP = static_cast<unsigned char>(hp);
        e.originalHPMax = static_cast<unsigned char>(hpMax);
        e.originalHPMaxMax = static_cast<unsigned char>((hpMaxMax > 0 && hpMaxMax <= 20) ? hpMaxMax : hpMax);
        e.hpCaptured = true; e.hpAppliedMode = R2R_STATS_MODE_AUTO; e.hpAppliedGeneration = UINT32_MAX;
    }
    const auto mode = R2R_StatsEffectiveMode();
    bool scriptReinitialized = false;
    if (e.hpForced && mode != R2R_STATS_MODE_NATIVE && plausible && hpMax != e.lastAppliedHPMax)
    {
        e.originalHP = static_cast<unsigned char>(hp);
        e.originalHPMax = static_cast<unsigned char>(hpMax);
        e.originalHPMaxMax = static_cast<unsigned char>((hpMaxMax > 0 && hpMaxMax <= 20) ? hpMaxMax : hpMax);
        scriptReinitialized = true; e.loggedGeneration = UINT32_MAX;
    }
    if (!scriptReinitialized && e.hpAppliedMode == mode && e.hpAppliedGeneration == g_R2RStatsPlaytestGeneration) return;
    const unsigned int desiredMax = R2R_Chase10ExtraDesiredPirateHP(e);
    if (desiredMax == 0 || desiredMax > 255) return;
    unsigned int desiredHP = desiredMax;
    if (hpMax > 0 && hp < hpMax)
    {
        desiredHP = static_cast<unsigned int>((static_cast<unsigned long long>(hp) * desiredMax + hpMax / 2) / hpMax);
        if (desiredHP == 0 && hp > 0) desiredHP = 1;
        if (desiredHP > desiredMax) desiredHP = desiredMax;
    }
    sg->ucHitPoints = static_cast<unsigned char>(desiredHP);
    sg->ucHitPointsMax = static_cast<unsigned char>(desiredMax);
    sg->ucHitPointsMaxMax = static_cast<unsigned char>(desiredMax);
    e.lastAppliedHP = static_cast<unsigned char>(desiredHP);
    e.lastAppliedHPMax = static_cast<unsigned char>(desiredMax);
    e.hpForced = mode != R2R_STATS_MODE_NATIVE;
    e.hpAppliedMode = mode; e.hpAppliedGeneration = g_R2RStatsPlaytestGeneration;
}
static void R2R_Chase10ExtraStartReport()
{
    if (g_R2RChase10ExtraReportStarted) return;
    FILE* f = nullptr; fopen_s(&f, R2R_CHASE10_EXTRA_REPORT, "w"); if (f == nullptr) return;
    fprintf(f,
        "%s CHASE_10 ALL-IN EXPANDED STATS\n"
        "Controls: F6=MIN F7=MAX F8=RANDOM/reroll F12=NATIVE.\n"
        "Bomb timers/ranges/speed bounds, projectile lifetimes/motion, barrel waits, bridge delay, boat weapon cadence, chicken movement/ranges, pirate HP/combat/motion, SUN_basic projectile stats and Ly oscillation are randomized.\n"
        "Existing barrel Float_3, boat live path command and ALW_Rayseau1/FRG_Fin waypoint controller remain authoritative.\n"
        "ALW_PROJECTILE Float_7 stays native because value 31 is a script state/type sentinel. Graphs/waypoints/refs/selectors remain native.\n\n",
        VERSION);
    fclose(f); g_R2RChase10ExtraReportStarted = true;
}
static void R2R_Chase10ExtraLog(R2R_Chase10ExtraEntry& e)
{
    if (e.loggedMode == R2R_StatsEffectiveMode() && e.loggedGeneration == g_R2RStatsPlaytestGeneration) return;
    R2R_Chase10ExtraStartReport(); FILE* f = nullptr; fopen_s(&f, R2R_CHASE10_EXTRA_REPORT, "a"); if (f == nullptr) return;
    const auto& t = g_R2RChase10ExtraTargets[e.targetIndex];
    fprintf(f, "[CHASE10-EXTRA] %s / %s / %s owner=%p key=%08X mode=%s generation=%u",
        t.family, t.model, t.personal, static_cast<void*>(e.owner), e.rngKey,
        R2R_StatsModeName(R2R_StatsEffectiveMode()), g_R2RStatsPlaytestGeneration);
    for (unsigned int i = 0; i < t.fieldCount; ++i)
    {
        if (t.fields[i].kind == R2R_CHASE10_FIELD_VECTOR)
            fprintf(f, " | %s x%.3f", t.fields[i].label, R2R_Chase10ExtraDesiredFactor(e.targetIndex, i, e.rngKey));
        else
            fprintf(f, " | %s native=%.6g applied=%.6g x%.3f", t.fields[i].label,
                e.originalScalar[i], e.lastAppliedScalar[i], R2R_Chase10ExtraDesiredFactor(e.targetIndex, i, e.rngKey));
    }
    if (t.pirateHP && e.hpCaptured)
        fprintf(f, " | HP native=%u applied=%u/%u", static_cast<unsigned int>(e.originalHPMax),
            static_cast<unsigned int>(e.lastAppliedHP), static_cast<unsigned int>(e.lastAppliedHPMax));
    if (t.mechanicsDt)
        fprintf(f, " | mechanics x%.3f hits=%u", R2R_Chase10ExtraDesiredMotionFactor(e.targetIndex, e.rngKey), e.mechanicsDtHits);
    fprintf(f, "\n"); fclose(f);
    e.loggedMode = R2R_StatsEffectiveMode(); e.loggedGeneration = g_R2RStatsPlaytestGeneration;
}
static void R2R_Chase10ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr || object == HIE_M_hGetMainActor() ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor) return;
    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int found = R2R_Chase10ExtraFindTarget(family, model, personal); if (found < 0) return;
    const unsigned int target = static_cast<unsigned int>(found); const auto& spec = g_R2RChase10ExtraTargets[target];
    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject))) return;
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_CHASE10_EXTRA_MAX_ACTORS; ++i)
    {
        const auto& e = g_R2RChase10ExtraEntries[i];
        if (e.owner == object && e.actor == actor && e.targetIndex == target) { slot = static_cast<int>(i); break; }
        if (e.owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0; if (fresh) slot = freeSlot; if (slot < 0) return;
    auto& e = g_R2RChase10ExtraEntries[slot];
    if (fresh)
    {
        e = R2R_Chase10ExtraEntry(); e.owner = object; e.actor = actor; e.targetIndex = target;
        e.rngKey = R2R_Chase10ExtraActorKey(object, actor, family, model, personal);
        e.loggedMode = R2R_STATS_MODE_AUTO; e.loggedGeneration = UINT32_MAX;
    }
    e.visit = g_R2RChase10ExtraVisit; const auto mode = R2R_StatsEffectiveMode();
    for (unsigned int i = 0; i < spec.fieldCount; ++i)
    {
        const auto& field = spec.fields[i]; void* raw = nullptr; if (!R2R_Chase10ExtraGetRaw(object, field, raw)) continue;
        if (field.kind == R2R_CHASE10_FIELD_VECTOR)
        {
            const auto before = *reinterpret_cast<MTH3D_tdstVector*>(raw); if (!R2R_Chase10ExtraVectorFinite(before)) continue;
            if (!e.captured[i] || !e.forced[i] || !R2R_Chase10ExtraVectorEqual(before, e.lastAppliedVector[i]))
            {
                e.originalVector[i] = before; e.captured[i] = true;
            }
            auto applied = before;
            if (mode == R2R_STATS_MODE_NATIVE)
            {
                if (e.forced[i] && e.captured[i] && R2R_Chase10ExtraVectorEqual(before, e.lastAppliedVector[i])) applied = e.originalVector[i];
                e.forced[i] = false;
            }
            else if (e.captured[i])
            {
                const float factor = R2R_Chase10ExtraDesiredFactor(target, i, e.rngKey);
                applied = { e.originalVector[i].x * factor, e.originalVector[i].y * factor, e.originalVector[i].z * factor };
                e.forced[i] = true;
            }
            if (R2R_Chase10ExtraVectorFinite(applied) && !R2R_Chase10ExtraVectorEqual(applied, before))
                *reinterpret_cast<MTH3D_tdstVector*>(raw) = applied;
            e.lastAppliedVector[i] = applied; continue;
        }
        float before = field.kind == R2R_CHASE10_FIELD_FLOAT ? *reinterpret_cast<float*>(raw) : static_cast<float>(*reinterpret_cast<int*>(raw));
        if (!std::isfinite(before) || std::fabs(before) > 1000000.0f) continue;

        // FRG_Ly flips Float_0's sign in its own script every 750 ms. Treat a
        // pure sign flip as phase, not as a new native magnitude, otherwise x4
        // would compound (.01 -> .04 -> .16 -> ...). F12 restores native
        // magnitude while preserving the current oscillation direction.
        const bool lyOscillation = field.kind == R2R_CHASE10_FIELD_FLOAT && field.dsgIndex == 0 &&
            _stricmp(spec.family, "ly_cine") == 0 && _stricmp(spec.model, "DS1_Ly_Potiche") == 0;
        if (lyOscillation)
        {
            if (!e.captured[i]) { e.originalScalar[i] = before; e.captured[i] = true; }
            else if (!e.forced[i]) e.originalScalar[i] = before;
            else
            {
                const float beforeMag = std::fabs(before), appliedMag = std::fabs(e.lastAppliedScalar[i]);
                if (std::fabs(beforeMag - appliedMag) > 0.000001f)
                    e.originalScalar[i] = before;
            }
        }
        else if (!e.captured[i] || !e.forced[i] || before != e.lastAppliedScalar[i])
        {
            e.originalScalar[i] = before; e.captured[i] = true;
        }

        float applied = before;
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (e.forced[i] && e.captured[i])
            {
                if (lyOscillation)
                    applied = std::copysign(std::fabs(e.originalScalar[i]), before);
                else if (before == e.lastAppliedScalar[i])
                    applied = e.originalScalar[i];
            }
            e.forced[i] = false;
        }
        else if (e.captured[i])
        {
            const float factor = R2R_Chase10ExtraDesiredFactor(target, i, e.rngKey);
            applied = lyOscillation ? std::copysign(std::fabs(e.originalScalar[i]) * factor, before) :
                e.originalScalar[i] * factor;
            e.forced[i] = true;
        }
        if (field.kind == R2R_CHASE10_FIELD_FLOAT)
        {
            if (std::isfinite(applied) && applied != before) *reinterpret_cast<float*>(raw) = applied;
        }
        else
        {
            int value = static_cast<int>(applied >= 0 ? applied + 0.5f : applied - 0.5f);
            if (value < 1) value = 1;
            if (static_cast<float>(value) != before) *reinterpret_cast<int*>(raw) = value;
            applied = static_cast<float>(value);
        }
        e.lastAppliedScalar[i] = applied;
    }
    R2R_Chase10ExtraApplyPirateHP(e, actor, spec.pirateHP);
    R2R_Chase10ExtraLog(e);
}
static void R2R_Chase10ExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_Chase10ExtraProcess(root); HIE_tdstSuperObject* child = nullptr;
    LST_M_DynamicForEach(root, child) { if (child != nullptr) R2R_Chase10ExtraScan(child, depth + 1); }
}
static void R2R_Chase10ExtraForgetWorld()
{
    std::memset(g_R2RChase10ExtraEntries, 0, sizeof(g_R2RChase10ExtraEntries));
    g_R2RChase10ExtraWorld = nullptr; g_R2RChase10ExtraInactiveWorld = nullptr;
}
static void R2R_Chase10ExpandedTick()
{
    if (GAM_g_stEngineStructure == nullptr || GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Chase_10") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Chase10ExtraForgetWorld(); return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RChase10ExtraWorld || inactive != g_R2RChase10ExtraInactiveWorld)
    {
        R2R_Chase10ExtraForgetWorld(); g_R2RChase10ExtraWorld = active; g_R2RChase10ExtraInactiveWorld = inactive; R2R_Chase10ExtraStartReport();
    }
    ++g_R2RChase10ExtraVisit; R2R_Chase10ExtraScan(active, 0); if (inactive != active) R2R_Chase10ExtraScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_CHASE10_EXTRA_MAX_ACTORS; ++i)
        if (g_R2RChase10ExtraEntries[i].visit != g_R2RChase10ExtraVisit) g_R2RChase10ExtraEntries[i] = R2R_Chase10ExtraEntry();
}
static MTH_tdxReal R2R_Chase10ExpandedMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    if (object == nullptr || dynamics == nullptr || object == HIE_M_hGetMainActor() ||
        R2R_StatsEffectiveMode() == R2R_STATS_MODE_NATIVE || GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Chase_10") != 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynamics), sizeof(DNM_tdstDynamicsBaseBlock)) ||
        !std::isfinite(dt) || dt <= 0 || dt > .25f) return dt;
    const int found = R2R_Chase10ExtraFindTarget(HIE_fn_szGetObjectFamilyName(object),
        HIE_fn_szGetObjectModelName(object), HIE_fn_szGetObjectPersonalName(object));
    if (found < 0) return dt; const unsigned int target = static_cast<unsigned int>(found);
    if (!g_R2RChase10ExtraTargets[target].mechanicsDt) return dt;
    for (auto& e : g_R2RChase10ExtraEntries)
    {
        if (e.owner != object || e.targetIndex != target || e.visit != g_R2RChase10ExtraVisit) continue;
        const float factor = R2R_Chase10ExtraDesiredMotionFactor(target, e.rngKey);
        const MTH_tdxReal applied = static_cast<MTH_tdxReal>(dt * factor);
        if (!std::isfinite(applied) || applied <= 0 || applied > 1.0f) return dt;
        ++e.mechanicsDtHits; return applied;
    }
    return dt;
}

