static bool R2R_Chase22ExtraVectorFinite(const MTH3D_tdstVector& v)
{
    return std::isfinite(v.x) && std::isfinite(v.y) && std::isfinite(v.z) &&
        std::fabs(v.x) <= 100000.0f && std::fabs(v.y) <= 100000.0f && std::fabs(v.z) <= 100000.0f;
}
static bool R2R_Chase22ExtraVectorEqual(const MTH3D_tdstVector& a, const MTH3D_tdstVector& b)
{
    return a.x == b.x && a.y == b.y && a.z == b.z;
}
static int R2R_Chase22ExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_CHASE22_EXTRA_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RChase22ExtraTargets[i];
        if (_stricmp(family, t.family) != 0 || _stricmp(model, t.model) != 0) continue;
        if (t.familyModelOnly) return static_cast<int>(i);
        if (personal != nullptr && _stricmp(personal, t.personal) == 0) return static_cast<int>(i);
    }
    return -1;
}
static float R2R_Chase22ExtraRandomFactor(unsigned int target, unsigned int randomSlot,
    uint32_t rngKey, float minFactor, float maxFactor)
{
    const int lo = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int hi = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = 0x43483130u ^ (target * 0x9E3779B9u) ^
        (randomSlot * 0x85EBCA6Bu) ^ (rngKey * 0x27D4EB2Du) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange("Stats.Chase22Extra.Factor", "Chase_22", salt, lo, hi) / 1000.0f;
}
static float R2R_Chase22ExtraDesiredFactor(unsigned int target, unsigned int slot, uint32_t rngKey)
{
    if (target >= R2R_CHASE22_EXTRA_TARGET_COUNT || slot >= g_R2RChase22ExtraTargets[target].fieldCount)
        return 1.0f;
    const auto& f = g_R2RChase22ExtraTargets[target].fields[slot];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return f.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return f.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Chase22ExtraRandomFactor(target, f.randomSlot, rngKey, f.minFactor, f.maxFactor);
    return 1.0f;
}
static float R2R_Chase22ExtraDesiredMotionFactor(unsigned int target, uint32_t rngKey)
{
    if (target >= R2R_CHASE22_EXTRA_TARGET_COUNT || !g_R2RChase22ExtraTargets[target].mechanicsDt)
        return 1.0f;
    const auto& t = g_R2RChase22ExtraTargets[target];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return t.motionMin;
    if (mode == R2R_STATS_MODE_MAX) return t.motionMax;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Chase22ExtraRandomFactor(target, 100, rngKey, t.motionMin, t.motionMax);
    return 1.0f;
}
static bool R2R_Chase22ExtraGetRaw(HIE_tdstSuperObject* object,
    const R2R_Chase22ExtraField& field, void*& raw)
{
    raw = nullptr; AI_tdeDsgVarType type = AI_E_Nb_dvt;
    if (!AI_fn_bGetDsgVar(object, field.dsgIndex, &type, &raw) || raw == nullptr) return false;
    AI_tdeDsgVarType wanted = AI_E_Nb_dvt; size_t bytes = 0;
    if (field.kind == R2R_CHASE22_EXTRA_FIELD_FLOAT) { wanted = AI_E_dvt_Float; bytes = sizeof(float); }
    else if (field.kind == R2R_CHASE22_EXTRA_FIELD_INT) { wanted = AI_E_dvt_Integer; bytes = sizeof(int); }
    else { wanted = AI_E_dvt_Vector; bytes = sizeof(MTH3D_tdstVector); }
    return type == wanted && R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), bytes) &&
        R2R_Learn10ExtraWritable(raw, bytes);
}
static uint32_t R2R_Chase22ExtraActorKey(HIE_tdstSuperObject* object, HIE_tdstEngineObject* actor,
    const char* family, const char* model, const char* personal)
{
    GAM_tdstStandardGame* sg = nullptr;
    if (actor != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) &&
        actor->hStandardGame != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)))
        sg = actor->hStandardGame;
    return R2R_StatsActorSlotKey(object, sg, family, model, personal != nullptr ? personal : "");
}
static unsigned int R2R_Chase22ExtraDesiredPirateHP(const R2R_Chase22ExtraEntry& e)
{
    if (!e.hpCaptured) return 0;
    int upper = static_cast<int>(e.originalHPMax) * 3;
    if (e.targetIndex < R2R_CHASE22_EXTRA_TARGET_COUNT &&
        _stricmp(g_R2RChase22ExtraTargets[e.targetIndex].family, "Cage") == 0 &&
        _stricmp(g_R2RChase22ExtraTargets[e.targetIndex].model, "ARG_CageLums") == 0)
        upper = 12;
    if (upper < 2) upper = 2;
    if (upper > 12) upper = 12;
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return e.originalHPMax;
    if (mode == R2R_STATS_MODE_MIN) return 1u;
    if (mode == R2R_STATS_MODE_MAX) return static_cast<unsigned int>(upper);
    if (mode == R2R_STATS_MODE_RANDOM)
    {
        const uint32_t salt = 0x43485050u ^ e.rngKey ^
            (g_R2RStatsPlaytestGeneration * 0x9E3779B9u);
        return static_cast<unsigned int>(R2R_RollRange("Stats.Chase22Extra.HP", "Chase_22", salt, 1, upper));
    }
    return e.originalHPMax;
}
static void R2R_Chase22ExtraApplyPirateHP(R2R_Chase22ExtraEntry& e,
    HIE_tdstEngineObject* actor, bool enabled)
{
    if (!enabled || actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)) ||
        !R2R_Learn10ExtraWritable(actor->hStandardGame, sizeof(GAM_tdstStandardGame))) return;
    GAM_tdstStandardGame* sg = actor->hStandardGame;
    unsigned int hp = sg->ucHitPoints, hpMax = sg->ucHitPointsMax, hpMaxMax = sg->ucHitPointsMaxMax;
    const bool cageHP = e.targetIndex < R2R_CHASE22_EXTRA_TARGET_COUNT &&
        _stricmp(g_R2RChase22ExtraTargets[e.targetIndex].family, "Cage") == 0 &&
        _stricmp(g_R2RChase22ExtraTargets[e.targetIndex].model, "ARG_CageLums") == 0;
    const bool plausible = hp > 0 && hp <= 20 && (cageHP || (hp == hpMax && hpMax <= 20));
    if (!e.hpCaptured)
    {
        if (!plausible) return;
        const unsigned int nativeMax = cageHP ? hp : hpMax;
        e.originalHP = static_cast<unsigned char>(hp);
        e.originalHPMax = static_cast<unsigned char>(nativeMax);
        e.originalHPMaxMax = static_cast<unsigned char>((hpMaxMax > 0 && hpMaxMax <= 20) ? hpMaxMax : nativeMax);
        e.hpCaptured = true; e.hpAppliedMode = R2R_STATS_MODE_AUTO; e.hpAppliedGeneration = UINT32_MAX;
    }
    const auto mode = R2R_StatsEffectiveMode();
    bool scriptReinitialized = false;
    if (e.hpForced && mode != R2R_STATS_MODE_NATIVE && plausible && (cageHP ? hp : hpMax) != e.lastAppliedHPMax)
    {
        const unsigned int nativeMax = cageHP ? hp : hpMax;
        e.originalHP = static_cast<unsigned char>(hp);
        e.originalHPMax = static_cast<unsigned char>(nativeMax);
        e.originalHPMaxMax = static_cast<unsigned char>((hpMaxMax > 0 && hpMaxMax <= 20) ? hpMaxMax : nativeMax);
        scriptReinitialized = true; e.loggedGeneration = UINT32_MAX;
    }
    if (!scriptReinitialized && e.hpAppliedMode == mode && e.hpAppliedGeneration == g_R2RStatsPlaytestGeneration) return;
    const unsigned int desiredMax = R2R_Chase22ExtraDesiredPirateHP(e);
    if (desiredMax == 0 || desiredMax > 255) return;
    unsigned int desiredHP = desiredMax;
    if (hpMax > 0 && hp < hpMax)
    {
        desiredHP = static_cast<unsigned int>((static_cast<unsigned long long>(hp) * desiredMax + hpMax / 2) / hpMax);
        if (desiredHP == 0 && hp > 0) desiredHP = 1;
        if (desiredHP > desiredMax) desiredHP = desiredMax;
    }
    sg->ucHitPoints = static_cast<unsigned char>(desiredHP);
    sg->ucHitPointsMax = static_cast<unsigned char>(desiredMax);
    sg->ucHitPointsMaxMax = static_cast<unsigned char>(desiredMax);
    e.lastAppliedHP = static_cast<unsigned char>(desiredHP);
    e.lastAppliedHPMax = static_cast<unsigned char>(desiredMax);
    e.hpForced = mode != R2R_STATS_MODE_NATIVE;
    e.hpAppliedMode = mode; e.hpAppliedGeneration = g_R2RStatsPlaytestGeneration;
}
static void R2R_Chase22ExtraStartReport()
{
    if (g_R2RChase22ExtraReportStarted) return;
    FILE* f = nullptr; fopen_s(&f, R2R_CHASE22_EXTRA_REPORT, "w"); if (f == nullptr) return;
    fprintf(f,
        "%s CHASE_22 ALL-IN EXPANDED STATS\n"
        "Controls: F6=MIN F7=MAX F8=RANDOM/reroll F12=NATIVE.\n"
        "SimpleSbire HP/activation, eight barrel-generator spawn intervals, gorilla runtime charge values, piranha timing/radius, CageLums durability and SUN_basic projectile stats are randomized.\n"
        "Chase_22 intro Rayseau and exit Ptizetre are progression-locked fully native (animation, movement and DSG modifiers disabled). Piranha jump travel and Donkey barrel travel remain owned by Chase22Path.\n"
        "Cage lum IDs/count/value, graphs, waypoints, refs, selectors and command/state variables remain native.\n\n",
        VERSION);
    fclose(f); g_R2RChase22ExtraReportStarted = true;
}
static void R2R_Chase22ExtraLog(R2R_Chase22ExtraEntry& e)
{
    if (e.loggedMode == R2R_StatsEffectiveMode() && e.loggedGeneration == g_R2RStatsPlaytestGeneration) return;
    R2R_Chase22ExtraStartReport(); FILE* f = nullptr; fopen_s(&f, R2R_CHASE22_EXTRA_REPORT, "a"); if (f == nullptr) return;
    const auto& t = g_R2RChase22ExtraTargets[e.targetIndex];
    fprintf(f, "[CHASE22-EXTRA] %s / %s / %s owner=%p key=%08X mode=%s generation=%u",
        t.family, t.model, t.personal, static_cast<void*>(e.owner), e.rngKey,
        R2R_StatsModeName(R2R_StatsEffectiveMode()), g_R2RStatsPlaytestGeneration);
    for (unsigned int i = 0; i < t.fieldCount; ++i)
    {
        if (t.fields[i].kind == R2R_CHASE22_EXTRA_FIELD_VECTOR)
            fprintf(f, " | %s x%.3f", t.fields[i].label, R2R_Chase22ExtraDesiredFactor(e.targetIndex, i, e.rngKey));
        else
            fprintf(f, " | %s native=%.6g applied=%.6g x%.3f", t.fields[i].label,
                e.originalScalar[i], e.lastAppliedScalar[i], R2R_Chase22ExtraDesiredFactor(e.targetIndex, i, e.rngKey));
    }
    if (t.pirateHP && e.hpCaptured)
        fprintf(f, " | HP native=%u applied=%u/%u", static_cast<unsigned int>(e.originalHPMax),
            static_cast<unsigned int>(e.lastAppliedHP), static_cast<unsigned int>(e.lastAppliedHPMax));
    if (t.mechanicsDt)
        fprintf(f, " | mechanics x%.3f hits=%u", R2R_Chase22ExtraDesiredMotionFactor(e.targetIndex, e.rngKey), e.mechanicsDtHits);
    fprintf(f, "\n"); fclose(f);
    e.loggedMode = R2R_StatsEffectiveMode(); e.loggedGeneration = g_R2RStatsPlaytestGeneration;
}
static void R2R_Chase22ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr || object == HIE_M_hGetMainActor() ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor) return;
    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int found = R2R_Chase22ExtraFindTarget(family, model, personal); if (found < 0) return;
    const unsigned int target = static_cast<unsigned int>(found); const auto& spec = g_R2RChase22ExtraTargets[target];
    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject))) return;
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_CHASE22_EXTRA_MAX_ACTORS; ++i)
    {
        const auto& e = g_R2RChase22ExtraEntries[i];
        if (e.owner == object && e.actor == actor && e.targetIndex == target) { slot = static_cast<int>(i); break; }
        if (e.owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0; if (fresh) slot = freeSlot; if (slot < 0) return;
    auto& e = g_R2RChase22ExtraEntries[slot];
    if (fresh)
    {
        e = R2R_Chase22ExtraEntry(); e.owner = object; e.actor = actor; e.targetIndex = target;
        e.rngKey = R2R_Chase22ExtraActorKey(object, actor, family, model, personal);
        e.loggedMode = R2R_STATS_MODE_AUTO; e.loggedGeneration = UINT32_MAX;
    }
    e.visit = g_R2RChase22ExtraVisit; const auto mode = R2R_StatsEffectiveMode();
    for (unsigned int i = 0; i < spec.fieldCount; ++i)
    {
        const auto& field = spec.fields[i]; void* raw = nullptr; if (!R2R_Chase22ExtraGetRaw(object, field, raw)) continue;
        if (field.kind == R2R_CHASE22_EXTRA_FIELD_VECTOR)
        {
            const auto before = *reinterpret_cast<MTH3D_tdstVector*>(raw); if (!R2R_Chase22ExtraVectorFinite(before)) continue;
            if (!e.captured[i] || !e.forced[i] || !R2R_Chase22ExtraVectorEqual(before, e.lastAppliedVector[i]))
            {
                e.originalVector[i] = before; e.captured[i] = true;
            }
            auto applied = before;
            if (mode == R2R_STATS_MODE_NATIVE)
            {
                if (e.forced[i] && e.captured[i] && R2R_Chase22ExtraVectorEqual(before, e.lastAppliedVector[i])) applied = e.originalVector[i];
                e.forced[i] = false;
            }
            else if (e.captured[i])
            {
                const float factor = R2R_Chase22ExtraDesiredFactor(target, i, e.rngKey);
                applied = { e.originalVector[i].x * factor, e.originalVector[i].y * factor, e.originalVector[i].z * factor };
                e.forced[i] = true;
            }
            if (R2R_Chase22ExtraVectorFinite(applied) && !R2R_Chase22ExtraVectorEqual(applied, before))
                *reinterpret_cast<MTH3D_tdstVector*>(raw) = applied;
            e.lastAppliedVector[i] = applied; continue;
        }
        float before = field.kind == R2R_CHASE22_EXTRA_FIELD_FLOAT ? *reinterpret_cast<float*>(raw) : static_cast<float>(*reinterpret_cast<int*>(raw));
        if (!std::isfinite(before) || std::fabs(before) > 1000000.0f) continue;

        // FRG_Ly flips Float_0's sign in its own script every 750 ms. Treat a
        // pure sign flip as phase, not as a new native magnitude, otherwise x4
        // would compound (.01 -> .04 -> .16 -> ...). F12 restores native
        // magnitude while preserving the current oscillation direction.
        // Gorilla init converts Float_2 by x11.5 and Float_4 by x0.003.
        // Wait for those runtime-native conversions so our factor is applied once, not twice.
        const bool gorillaRuntimeField = _stricmp(spec.family, "pirate_gorille") == 0 &&
            _stricmp(spec.model, "MIC_GorilleGardien") == 0 &&
            field.kind == R2R_CHASE22_EXTRA_FIELD_FLOAT && (field.dsgIndex == 2 || field.dsgIndex == 4);
        if (gorillaRuntimeField)
        {
            if ((field.dsgIndex == 2 && std::fabs(before) < 5.0f) ||
                (field.dsgIndex == 4 && std::fabs(before) > 0.1f)) continue;
        }

        const bool lyOscillation = field.kind == R2R_CHASE22_EXTRA_FIELD_FLOAT && field.dsgIndex == 0 &&
            _stricmp(spec.family, "ly_cine") == 0 && _stricmp(spec.model, "DS1_Ly_Potiche") == 0;
        if (lyOscillation)
        {
            if (!e.captured[i]) { e.originalScalar[i] = before; e.captured[i] = true; }
            else if (!e.forced[i]) e.originalScalar[i] = before;
            else
            {
                const float beforeMag = std::fabs(before), appliedMag = std::fabs(e.lastAppliedScalar[i]);
                if (std::fabs(beforeMag - appliedMag) > 0.000001f)
                    e.originalScalar[i] = before;
            }
        }
        else if (!e.captured[i] || !e.forced[i] || before != e.lastAppliedScalar[i])
        {
            e.originalScalar[i] = before; e.captured[i] = true;
        }

        float applied = before;
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (e.forced[i] && e.captured[i])
            {
                if (lyOscillation)
                    applied = std::copysign(std::fabs(e.originalScalar[i]), before);
                else if (before == e.lastAppliedScalar[i])
                    applied = e.originalScalar[i];
            }
            e.forced[i] = false;
        }
        else if (e.captured[i])
        {
            const float factor = R2R_Chase22ExtraDesiredFactor(target, i, e.rngKey);
            applied = lyOscillation ? std::copysign(std::fabs(e.originalScalar[i]) * factor, before) :
                e.originalScalar[i] * factor;
            e.forced[i] = true;
        }
        if (field.kind == R2R_CHASE22_EXTRA_FIELD_FLOAT)
        {
            if (std::isfinite(applied) && applied != before) *reinterpret_cast<float*>(raw) = applied;
        }
        else
        {
            int value = static_cast<int>(applied >= 0 ? applied + 0.5f : applied - 0.5f);
            if (value < 1) value = 1;
            if (static_cast<float>(value) != before) *reinterpret_cast<int*>(raw) = value;
            applied = static_cast<float>(value);
        }
        e.lastAppliedScalar[i] = applied;
    }
    R2R_Chase22ExtraApplyPirateHP(e, actor, spec.pirateHP);
    R2R_Chase22ExtraLog(e);
}
static void R2R_Chase22ExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_Chase22ExtraProcess(root); HIE_tdstSuperObject* child = nullptr;
    LST_M_DynamicForEach(root, child) { if (child != nullptr) R2R_Chase22ExtraScan(child, depth + 1); }
}
static void R2R_Chase22ExtraForgetWorld()
{
    std::memset(g_R2RChase22ExtraEntries, 0, sizeof(g_R2RChase22ExtraEntries));
    g_R2RChase22ExtraWorld = nullptr; g_R2RChase22ExtraInactiveWorld = nullptr;
}
static void R2R_Chase22ExpandedTick()
{
    if (GAM_g_stEngineStructure == nullptr || GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Chase_22") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Chase22ExtraForgetWorld(); return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RChase22ExtraWorld || inactive != g_R2RChase22ExtraInactiveWorld)
    {
        R2R_Chase22ExtraForgetWorld(); g_R2RChase22ExtraWorld = active; g_R2RChase22ExtraInactiveWorld = inactive; R2R_Chase22ExtraStartReport();
    }
    ++g_R2RChase22ExtraVisit; R2R_Chase22ExtraScan(active, 0); if (inactive != active) R2R_Chase22ExtraScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_CHASE22_EXTRA_MAX_ACTORS; ++i)
        if (g_R2RChase22ExtraEntries[i].visit != g_R2RChase22ExtraVisit) g_R2RChase22ExtraEntries[i] = R2R_Chase22ExtraEntry();
}

