static void R2R_Rodeo40RateLog(unsigned int index, const char* action,
    unsigned int before, unsigned int after)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_RODEO40_RATE_REPORT, "a");
    if (f == nullptr) return;
    const R2R_Rodeo40RateEntry& e = g_R2RRodeo40RateEntries[index];
    HIE_tdstState* state = e.data->h_CurrentState;
    HIE_tdstState stateCopy = {};
    const bool readable = state != nullptr && R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(state), sizeof(HIE_tdstState)) &&
        SafeReadMemory(state, &stateCopy, sizeof(stateCopy));
    const R2R_Rodeo40RateTarget& t = g_R2RRodeo40RateTargets[e.targetIndex];
    fprintf(f, "[RODEO40-ANIMRATE] %s / %s / %s target=%u action=%s mode=%d "
        "original=%u before=%u applied=%u state=%p cSpeedAnim=%d owner=%p data=%p\n",
        t.family, t.model, t.personal, e.targetIndex + 1, action,
        g_R2RRodeo40RateMode, e.original, before, after, static_cast<void*>(state),
        readable ? static_cast<int>(stateCopy.cSpeedAnim) : -1,
        static_cast<void*>(e.owner), static_cast<void*>(e.data));
    fclose(f);
}
static void R2R_Rodeo40RateProcess(HIE_tdstSuperObject* object)
{
    if (object == HIE_M_hGetMainActor()) return;
    R2R_Rodeo40Identity identity = {};
    if (!R2R_Rodeo40ReadIdentity(object, identity) || identity.target < 0) return;
    const int target = identity.target;
    const R2R_Rodeo40RateTarget& t = g_R2RRodeo40RateTargets[target];
    const char* family = t.family; const char* model = t.model; const char* personal = t.personal;
    g_R2RRodeo40RateDetected[target] = true;

    // u.0 progression lock: ALW_Rayseau1 owns graph/network handoff.
    if (target == 0) return;

    HIE_tdstEngineObject* actor = identity.actor;
    GAM_tdst3dData* data = actor->h3dData;
    if (data == nullptr || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(data), sizeof(GAM_tdst3dData)))
    {
        R2R_Rodeo40RateError(target, family, model, personal, "no readable actor-local animation data");
        return;
    }
    if (!R2R_Rodeo40RateByteWritable(&data->ucFrameRate))
    {
        R2R_Rodeo40RateError(target, family, model, personal, "animation-rate byte is not writable");
        return;
    }
    // Separate entries preserve each live actor's original rate, including
    // multiple instances with the same exact names.
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_RODEO40_RATE_MAX_ACTORS; ++i)
    {
        const R2R_Rodeo40RateEntry& e = g_R2RRodeo40RateEntries[i];
        if (e.owner == object && e.actor == actor && e.data == data &&
            e.targetIndex == static_cast<unsigned int>(target)) {
            slot = static_cast<int>(i); break;
        }
        if (e.owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0)
    {
        R2R_Rodeo40RateError(target, family, model, personal, "actor tracking table full");
        return;
    }
    R2R_Rodeo40RateEntry& e = g_R2RRodeo40RateEntries[slot];
    const unsigned int before = data->ucFrameRate;
    if (fresh)
    {
        e = R2R_Rodeo40RateEntry();
        e.owner = object; e.actor = actor; e.data = data;
        e.targetIndex = static_cast<unsigned int>(target);
        e.original = before; e.loggedMode = -1;
    }
    if (!e.forced || before != static_cast<unsigned int>(e.loggedMode)) e.original = before;
    e.visit = g_R2RRodeo40RateVisit;
    g_R2RRodeo40RateUsable[target] = true;
    const bool log = e.loggedMode != g_R2RRodeo40RateMode || e.lastState != data->h_CurrentState;
    if (g_R2RRodeo40RateMode == 0)
    {
        if (e.forced)
        {
            data->ucFrameRate = static_cast<unsigned char>(e.original);
            R2R_Rodeo40RateLog(slot, "RESTORE", before, data->ucFrameRate);
            e.forced = false;
        }
        else if (log) R2R_Rodeo40RateLog(slot, "VANILLA", before, before);
    }
    else
    {
        data->ucFrameRate = static_cast<unsigned char>(g_R2RRodeo40RateMode);
        if (log) R2R_Rodeo40RateLog(slot, "APPLY", before, data->ucFrameRate);
        e.forced = true;
    }
    e.loggedMode = g_R2RRodeo40RateMode;
    e.lastState = data->h_CurrentState;
}
static unsigned int g_R2RRodeo40RateScanBudget = 0;
static void R2R_Rodeo40RateScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || g_R2RRodeo40RateScanBudget == 0 || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    --g_R2RRodeo40RateScanBudget;
    R2R_Rodeo40RateProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (g_R2RRodeo40RateScanBudget == 0) break;
        if (object != nullptr) R2R_Rodeo40RateScan(object, depth + 1);
    }
}
static void R2R_Rodeo40RateForgetWorld()
{
    std::memset(g_R2RRodeo40RateEntries, 0, sizeof(g_R2RRodeo40RateEntries));
    std::memset(g_R2RRodeo40RateErrorLogged, 0, sizeof(g_R2RRodeo40RateErrorLogged));
    g_R2RRodeo40RateWorld = nullptr; g_R2RRodeo40RateInactiveWorld = nullptr;
    g_R2RRodeo40RateFrame = 0;
}
static void R2R_Rodeo40RateTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Rodeo_40") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Rodeo40RateForgetWorld();
        return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RRodeo40RateWorld || inactive != g_R2RRodeo40RateInactiveWorld)
    {
        // Keep matching live actors across an in-level root change so F8
        // restores the baseline rather than recapturing the forced rate.
        // The scan validates owner/actor/data and prunes missing entries.
        g_R2RRodeo40RateWorld = active; g_R2RRodeo40RateInactiveWorld = inactive;
        FILE* f = nullptr;
        fopen_s(&f, R2R_RODEO40_RATE_REPORT, g_R2RRodeo40RateReportStarted ? "a" : "w");
        if (f != nullptr)
        {
            fprintf(f, "\n%s RODEO40 ANIMATION TEST: %u randomized animation targets, "
                "global Stats controls: F6=MIN F7=MAX F8=RANDOM F12=NATIVE. "
                "All 26 supplied non-Rayseau identities are covered; generated SUN_basic family/model clones are covered too. "
                "ALW_Rayseau1 is detected/protected but fully native.\n",
                VERSION, R2R_RODEO40_ANIMATION_TEST_COUNT);
            fclose(f); g_R2RRodeo40RateReportStarted = true;
        }
    }
    std::memset(g_R2RRodeo40RateDetected, 0, sizeof(g_R2RRodeo40RateDetected));
    std::memset(g_R2RRodeo40RateUsable, 0, sizeof(g_R2RRodeo40RateUsable));
    ++g_R2RRodeo40RateVisit;
    g_R2RRodeo40RateScanBudget = 4096;
    R2R_Rodeo40RateScan(active, 0);
    if (inactive != active) R2R_Rodeo40RateScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_RODEO40_RATE_MAX_ACTORS; ++i)
        if (g_R2RRodeo40RateEntries[i].visit != g_R2RRodeo40RateVisit)
            g_R2RRodeo40RateEntries[i] = R2R_Rodeo40RateEntry();
    if ((g_R2RRodeo40RateFrame++ % 300) == 0)
    {
        FILE* f = nullptr;
        fopen_s(&f, R2R_RODEO40_RATE_REPORT, "a");
        if (f == nullptr) return;
        unsigned int detected = 0, usable = 0, actors = 0;
        for (unsigned int i = 0; i < R2R_RODEO40_RATE_TARGET_COUNT; ++i)
        {
            if (g_R2RRodeo40RateDetected[i])
            {
                ++detected;
            }
            if (g_R2RRodeo40RateUsable[i]) ++usable;
            if (!g_R2RRodeo40RateDetected[i])
            {
                const R2R_Rodeo40RateTarget& t = g_R2RRodeo40RateTargets[i];
                fprintf(f, "[RODEO40-NOT-FOUND] target=%u %s / %s / %s "
                    "prefixFields=%u suffix=%s\n", i + 1, t.family, t.model, t.personal,
                    t.prefixFields, t.personalSuffix != nullptr ? t.personalSuffix : "(none)");
            }
        }
        for (unsigned int i = 0; i < R2R_RODEO40_RATE_MAX_ACTORS; ++i)
            if (g_R2RRodeo40RateEntries[i].owner != nullptr) ++actors;
        fprintf(f, "[RODEO40-SUMMARY] detected=%u/%u animationData=%u/%u "
            "trackedActors=%u mode=%d\n", detected, R2R_RODEO40_RATE_TARGET_COUNT,
            usable, R2R_RODEO40_ANIMATION_TEST_COUNT, actors, g_R2RRodeo40RateMode);
        fclose(f);
    }
}

