static const unsigned int R2R_RODEO40_EXTRA_MAX_ACTORS = 192;

struct R2R_Rodeo40ExtraEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    unsigned int targetIndex;
    uint32_t rngKey;
    unsigned int visit;

    bool captured[12];
    bool forced[12];
    float originalScalar[12];
    float lastAppliedScalar[12];
    MTH3D_tdstVector originalVector[12];
    MTH3D_tdstVector lastAppliedVector[12];

    bool hpCaptured;
    bool hpForced;
    unsigned char originalHP;
    unsigned char originalHPMax;
    unsigned char originalHPMaxMax;
    unsigned char lastAppliedHP;
    unsigned char lastAppliedHPMax;
    R2R_StatsPlaytestMode hpAppliedMode;
    unsigned int hpAppliedGeneration;

    R2R_StatsPlaytestMode loggedMode;
    unsigned int loggedGeneration;
};

static R2R_Rodeo40ExtraEntry g_R2RRodeo40ExtraEntries[R2R_RODEO40_EXTRA_MAX_ACTORS] = {};
static HIE_tdstSuperObject* g_R2RRodeo40ExtraWorld = nullptr;
static HIE_tdstSuperObject* g_R2RRodeo40ExtraInactiveWorld = nullptr;
static unsigned int g_R2RRodeo40ExtraVisit = 0;
static bool g_R2RRodeo40ExtraReportStarted = false;

static bool R2R_Rodeo40ExtraVectorFinite(const MTH3D_tdstVector& v)
{
    return std::isfinite(v.x) && std::isfinite(v.y) && std::isfinite(v.z) &&
        std::fabs(v.x) <= 100000.0f && std::fabs(v.y) <= 100000.0f && std::fabs(v.z) <= 100000.0f;
}
static bool R2R_Rodeo40ExtraVectorEqual(const MTH3D_tdstVector& a, const MTH3D_tdstVector& b)
{
    return a.x == b.x && a.y == b.y && a.z == b.z;
}
static int R2R_Rodeo40ExtraFindTarget(const char* family, const char* model, const char* personal)
{
    if (family == nullptr || model == nullptr) return -1;
    for (unsigned int i = 0; i < R2R_RODEO40_EXTRA_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RRodeo40ExtraTargets[i];
        if (_stricmp(family, t.family) != 0 || _stricmp(model, t.model) != 0) continue;
        if (t.familyModelOnly) return static_cast<int>(i);
        if (personal != nullptr && _stricmp(personal, t.personal) == 0) return static_cast<int>(i);
    }
    return -1;
}
static float R2R_Rodeo40ExtraRandomFactor(unsigned int target, unsigned int randomSlot,
    uint32_t rngKey, float minFactor, float maxFactor)
{
    const int lo = static_cast<int>(minFactor * 1000.0f + 0.5f);
    const int hi = static_cast<int>(maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = 0x52343045u ^ (target * 0x9E3779B9u) ^
        (randomSlot * 0x85EBCA6Bu) ^ (rngKey * 0x27D4EB2Du) ^
        (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u);
    return R2R_RollRange("Stats.Rodeo40Extra.Factor", "Rodeo_40", salt, lo, hi) / 1000.0f;
}
static float R2R_Rodeo40ExtraDesiredFactor(unsigned int target, unsigned int slot, uint32_t rngKey)
{
    if (target >= R2R_RODEO40_EXTRA_TARGET_COUNT ||
        slot >= g_R2RRodeo40ExtraTargets[target].fieldCount) return 1.0f;
    const auto& f = g_R2RRodeo40ExtraTargets[target].fields[slot];
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return f.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return f.maxFactor;
    if (mode == R2R_STATS_MODE_RANDOM)
        return R2R_Rodeo40ExtraRandomFactor(target, f.randomSlot, rngKey, f.minFactor, f.maxFactor);
    return 1.0f;
}
static bool R2R_Rodeo40ExtraGetRaw(HIE_tdstSuperObject* object,
    const R2R_Rodeo40ExtraField& field, void*& raw)
{
    raw = nullptr; AI_tdeDsgVarType type = AI_E_Nb_dvt;
    if (!AI_fn_bGetDsgVar(object, field.dsgIndex, &type, &raw) || raw == nullptr) return false;
    AI_tdeDsgVarType wanted = AI_E_Nb_dvt; size_t bytes = 0;
    if (field.kind == R2R_RODEO40_EXTRA_FIELD_FLOAT) { wanted = AI_E_dvt_Float; bytes = sizeof(float); }
    else if (field.kind == R2R_RODEO40_EXTRA_FIELD_INT) { wanted = AI_E_dvt_Integer; bytes = sizeof(int); }
    else { wanted = AI_E_dvt_Vector; bytes = sizeof(MTH3D_tdstVector); }
    return type == wanted && R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), bytes) &&
        R2R_Learn10ExtraWritable(raw, bytes);
}
static uint32_t R2R_Rodeo40ExtraActorKey(HIE_tdstSuperObject* object, HIE_tdstEngineObject* actor,
    const char* family, const char* model, const char* personal)
{
    GAM_tdstStandardGame* sg = nullptr;
    if (actor != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) &&
        actor->hStandardGame != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)))
        sg = actor->hStandardGame;
    return R2R_StatsActorSlotKey(object, sg, family, model, personal != nullptr ? personal : "");
}
static unsigned int R2R_Rodeo40ExtraDesiredHP(const R2R_Rodeo40ExtraEntry& e)
{
    if (!e.hpCaptured) return 0;
    const int upper = 12;
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_NATIVE) return e.originalHPMax;
    if (mode == R2R_STATS_MODE_MIN) return 1u;
    if (mode == R2R_STATS_MODE_MAX) return static_cast<unsigned int>(upper);
    if (mode == R2R_STATS_MODE_RANDOM)
    {
        const uint32_t salt = 0x52344850u ^ e.rngKey ^
            (g_R2RStatsPlaytestGeneration * 0x9E3779B9u);
        return static_cast<unsigned int>(
            R2R_RollRange("Stats.Rodeo40Pirate.HP", "Rodeo_40", salt, 1, upper));
    }
    return e.originalHPMax;
}
static void R2R_Rodeo40ExtraApplyHP(R2R_Rodeo40ExtraEntry& e,
    HIE_tdstEngineObject* actor, bool enabled)
{
    if (!enabled || actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)) ||
        !R2R_Learn10ExtraWritable(actor->hStandardGame, sizeof(GAM_tdstStandardGame))) return;

    GAM_tdstStandardGame* sg = actor->hStandardGame;
    unsigned int hp = sg->ucHitPoints, hpMax = sg->ucHitPointsMax, hpMaxMax = sg->ucHitPointsMaxMax;
    const bool plausible = hp > 0 && hp == hpMax && hpMax <= 20;
    if (!e.hpCaptured)
    {
        if (!plausible) return;
        e.originalHP = static_cast<unsigned char>(hp);
        e.originalHPMax = static_cast<unsigned char>(hpMax);
        e.originalHPMaxMax = static_cast<unsigned char>(
            (hpMaxMax > 0 && hpMaxMax <= 20) ? hpMaxMax : hpMax);
        e.hpCaptured = true;
        e.hpAppliedMode = R2R_STATS_MODE_AUTO;
        e.hpAppliedGeneration = UINT32_MAX;
    }

    const auto mode = R2R_StatsEffectiveMode();
    bool scriptReinitialized = false;
    if (e.hpForced && mode != R2R_STATS_MODE_NATIVE && plausible && hpMax != e.lastAppliedHPMax)
    {
        e.originalHP = static_cast<unsigned char>(hp);
        e.originalHPMax = static_cast<unsigned char>(hpMax);
        e.originalHPMaxMax = static_cast<unsigned char>(
            (hpMaxMax > 0 && hpMaxMax <= 20) ? hpMaxMax : hpMax);
        scriptReinitialized = true;
        e.loggedGeneration = UINT32_MAX;
    }
    if (!scriptReinitialized &&
        e.hpAppliedMode == mode && e.hpAppliedGeneration == g_R2RStatsPlaytestGeneration) return;

    const unsigned int desiredMax = R2R_Rodeo40ExtraDesiredHP(e);
    if (desiredMax == 0 || desiredMax > 255) return;

    unsigned int desiredHP = desiredMax;
    if (hpMax > 0 && hp < hpMax)
    {
        desiredHP = static_cast<unsigned int>(
            (static_cast<unsigned long long>(hp) * desiredMax + hpMax / 2) / hpMax);
        if (desiredHP == 0 && hp > 0) desiredHP = 1;
        if (desiredHP > desiredMax) desiredHP = desiredMax;
    }

    sg->ucHitPoints = static_cast<unsigned char>(desiredHP);
    sg->ucHitPointsMax = static_cast<unsigned char>(desiredMax);
    sg->ucHitPointsMaxMax = static_cast<unsigned char>(desiredMax);
    e.lastAppliedHP = static_cast<unsigned char>(desiredHP);
    e.lastAppliedHPMax = static_cast<unsigned char>(desiredMax);
    e.hpForced = mode != R2R_STATS_MODE_NATIVE;
    e.hpAppliedMode = mode;
    e.hpAppliedGeneration = g_R2RStatsPlaytestGeneration;
}
static void R2R_Rodeo40ExtraStartReport()
{
    if (g_R2RRodeo40ExtraReportStarted) return;
    FILE* f = nullptr; fopen_s(&f, R2R_RODEO40_EXTRA_REPORT, "w");
    if (f == nullptr) return;
    fprintf(f,
        "%s RODEO_40 FULL EXPANDED STATS\n"
        "Controls: F6=MIN F7=MAX F8=RANDOM/reroll F12=NATIVE.\n"
        "OLP_Obus_1: detection x1..x4; attack/ride target speeds x0.5..x2; timers x0.25..x4. HP native because the Obus mirrors Rayman while ridden.\n"
        "OLP_Sbire_Bastion_1: HP 1..12 plus fall/range/aim/burst/cooldown/lead/wake stats; generated SUN_basic x0.25..x4.\n"
        "Mushroom bounce and Clark-wall trigger distances never go below native; thorns randomize trigger range plus nonzero cooldowns.\n"
        "Francesco/Papillons randomize activation ranges only; route movement stays native.\n"
        "ALW_Rayseau1 and all old Rodeo_40 path/cinematic mechanics writes are native in u.0.\n"
        "Graphs, waypoints, refs, selectors, command mailboxes, progression flags and barrel flight logic remain native.\n\n",
        VERSION);
    fclose(f);
    g_R2RRodeo40ExtraReportStarted = true;
}
static void R2R_Rodeo40ExtraLog(R2R_Rodeo40ExtraEntry& e)
{
    if (e.loggedMode == R2R_StatsEffectiveMode() &&
        e.loggedGeneration == g_R2RStatsPlaytestGeneration) return;
    R2R_Rodeo40ExtraStartReport();
    FILE* f = nullptr; fopen_s(&f, R2R_RODEO40_EXTRA_REPORT, "a");
    if (f == nullptr) return;

    const auto& t = g_R2RRodeo40ExtraTargets[e.targetIndex];
    fprintf(f, "[RODEO40-EXTRA] %s / %s / %s owner=%p key=%08X mode=%s generation=%u",
        t.family, t.model, t.personal, static_cast<void*>(e.owner), e.rngKey,
        R2R_StatsModeName(R2R_StatsEffectiveMode()), g_R2RStatsPlaytestGeneration);

    for (unsigned int i = 0; i < t.fieldCount; ++i)
    {
        if (t.fields[i].kind == R2R_RODEO40_EXTRA_FIELD_VECTOR)
            fprintf(f, " | %s x%.3f", t.fields[i].label,
                R2R_Rodeo40ExtraDesiredFactor(e.targetIndex, i, e.rngKey));
        else
            fprintf(f, " | %s native=%.6g applied=%.6g x%.3f", t.fields[i].label,
                e.originalScalar[i], e.lastAppliedScalar[i],
                R2R_Rodeo40ExtraDesiredFactor(e.targetIndex, i, e.rngKey));
    }
    if (t.gameplayHP && e.hpCaptured)
        fprintf(f, " | HP native=%u applied=%u/%u",
            static_cast<unsigned int>(e.originalHPMax),
            static_cast<unsigned int>(e.lastAppliedHP),
            static_cast<unsigned int>(e.lastAppliedHPMax));
    fprintf(f, "\n");
    fclose(f);
    e.loggedMode = R2R_StatsEffectiveMode();
    e.loggedGeneration = g_R2RStatsPlaytestGeneration;
}
static void R2R_Rodeo40ExtraProcess(HIE_tdstSuperObject* object)
{
    if (object == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object), sizeof(HIE_tdstSuperObject)) ||
        object->ulType != HIE_C_Type_Actor) return;

    const char* family = HIE_fn_szGetObjectFamilyName(object);
    const char* model = HIE_fn_szGetObjectModelName(object);
    const char* personal = HIE_fn_szGetObjectPersonalName(object);
    const int found = R2R_Rodeo40ExtraFindTarget(family, model, personal);
    if (found < 0) return;

    const unsigned int target = static_cast<unsigned int>(found);
    // OLP_Obus_1 becomes MainActor while ridden; its exact script-owned fields
    // remain safe. Every other MainActor identity stays excluded.
    if (object == HIE_M_hGetMainActor() && target != 0) return;
    const auto& spec = g_R2RRodeo40ExtraTargets[target];
    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(object);
    if (actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject))) return;

    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_RODEO40_EXTRA_MAX_ACTORS; ++i)
    {
        const auto& e = g_R2RRodeo40ExtraEntries[i];
        if (e.owner == object && e.actor == actor && e.targetIndex == target)
        {
            slot = static_cast<int>(i); break;
        }
        if (e.owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0) return;

    auto& e = g_R2RRodeo40ExtraEntries[slot];
    if (fresh)
    {
        e = R2R_Rodeo40ExtraEntry();
        e.owner = object; e.actor = actor; e.targetIndex = target;
        e.rngKey = R2R_Rodeo40ExtraActorKey(object, actor, family, model, personal);
        e.loggedMode = R2R_STATS_MODE_AUTO;
        e.loggedGeneration = UINT32_MAX;
    }
    e.visit = g_R2RRodeo40ExtraVisit;
    const auto mode = R2R_StatsEffectiveMode();

    for (unsigned int i = 0; i < spec.fieldCount; ++i)
    {
        const auto& field = spec.fields[i];
        void* raw = nullptr;
        if (!R2R_Rodeo40ExtraGetRaw(object, field, raw)) continue;

        if (field.kind == R2R_RODEO40_EXTRA_FIELD_VECTOR)
        {
            const auto before = *reinterpret_cast<MTH3D_tdstVector*>(raw);
            if (!R2R_Rodeo40ExtraVectorFinite(before)) continue;
            if (!e.captured[i] || !e.forced[i] ||
                !R2R_Rodeo40ExtraVectorEqual(before, e.lastAppliedVector[i]))
            {
                e.originalVector[i] = before;
                e.captured[i] = true;
            }

            auto applied = before;
            if (mode == R2R_STATS_MODE_NATIVE)
            {
                if (e.forced[i] && e.captured[i] &&
                    R2R_Rodeo40ExtraVectorEqual(before, e.lastAppliedVector[i]))
                    applied = e.originalVector[i];
                e.forced[i] = false;
            }
            else if (e.captured[i])
            {
                const float factor = R2R_Rodeo40ExtraDesiredFactor(target, i, e.rngKey);
                applied = {
                    e.originalVector[i].x * factor,
                    e.originalVector[i].y * factor,
                    e.originalVector[i].z * factor
                };
                e.forced[i] = true;
            }

            if (R2R_Rodeo40ExtraVectorFinite(applied) &&
                !R2R_Rodeo40ExtraVectorEqual(applied, before))
                *reinterpret_cast<MTH3D_tdstVector*>(raw) = applied;
            e.lastAppliedVector[i] = applied;
            continue;
        }

        float before = field.kind == R2R_RODEO40_EXTRA_FIELD_FLOAT
            ? *reinterpret_cast<float*>(raw)
            : static_cast<float>(*reinterpret_cast<int*>(raw));
        if (!std::isfinite(before) || std::fabs(before) > 1000000.0f) continue;

        if (!e.captured[i] || !e.forced[i] || before != e.lastAppliedScalar[i])
        {
            e.originalScalar[i] = before;
            e.captured[i] = true;
        }

        float applied = before;
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (e.forced[i] && e.captured[i] && before == e.lastAppliedScalar[i])
                applied = e.originalScalar[i];
            e.forced[i] = false;
        }
        else if (e.captured[i])
        {
            applied = e.originalScalar[i] *
                R2R_Rodeo40ExtraDesiredFactor(target, i, e.rngKey);
            e.forced[i] = true;
        }

        if (field.kind == R2R_RODEO40_EXTRA_FIELD_FLOAT)
        {
            if (std::isfinite(applied) && applied != before)
                *reinterpret_cast<float*>(raw) = applied;
        }
        else
        {
            int value = static_cast<int>(applied >= 0 ? applied + 0.5f : applied - 0.5f);
            if (value < 1) value = 1;
            if (static_cast<float>(value) != before)
                *reinterpret_cast<int*>(raw) = value;
            applied = static_cast<float>(value);
        }
        e.lastAppliedScalar[i] = applied;
    }

    R2R_Rodeo40ExtraApplyHP(e, actor, spec.gameplayHP);
    R2R_Rodeo40ExtraLog(e);
}
static void R2R_Rodeo40ExtraScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_Rodeo40ExtraProcess(root);
    HIE_tdstSuperObject* child = nullptr;
    LST_M_DynamicForEach(root, child)
    {
        if (child != nullptr) R2R_Rodeo40ExtraScan(child, depth + 1);
    }
}
static void R2R_Rodeo40ExtraForgetWorld()
{
    std::memset(g_R2RRodeo40ExtraEntries, 0, sizeof(g_R2RRodeo40ExtraEntries));
    g_R2RRodeo40ExtraWorld = nullptr;
    g_R2RRodeo40ExtraInactiveWorld = nullptr;
}
static void R2R_Rodeo40ExpandedTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Rodeo_40") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Rodeo40ExtraForgetWorld();
        return;
    }

    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;

    if (active != g_R2RRodeo40ExtraWorld || inactive != g_R2RRodeo40ExtraInactiveWorld)
    {
        R2R_Rodeo40ExtraForgetWorld();
        g_R2RRodeo40ExtraWorld = active;
        g_R2RRodeo40ExtraInactiveWorld = inactive;
        R2R_Rodeo40ExtraStartReport();
    }

    ++g_R2RRodeo40ExtraVisit;
    R2R_Rodeo40ExtraScan(active, 0);
    if (inactive != active) R2R_Rodeo40ExtraScan(inactive, 0);

    for (unsigned int i = 0; i < R2R_RODEO40_EXTRA_MAX_ACTORS; ++i)
        if (g_R2RRodeo40ExtraEntries[i].visit != g_R2RRodeo40ExtraVisit)
            g_R2RRodeo40ExtraEntries[i] = R2R_Rodeo40ExtraEntry();
}



