static bool R2R_Rodeo60RateByteWritable(unsigned char* value)
{
    MEMORY_BASIC_INFORMATION info = {};
    if (value == nullptr || VirtualQuery(value, &info, sizeof(info)) == 0) return false;
    if (info.State != MEM_COMMIT || (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const DWORD protection = info.Protect & 0xff;
    return protection == PAGE_READWRITE || protection == PAGE_WRITECOPY ||
        protection == PAGE_EXECUTE_READWRITE || protection == PAGE_EXECUTE_WRITECOPY;
}
static void R2R_Rodeo60RateError(unsigned int target, const char* family,
    const char* model, const char* personal, const char* reason)
{
    if (g_R2RRodeo60RateErrorLogged[target]) return;
    FILE* f = nullptr;
    fopen_s(&f, R2R_RODEO60_RATE_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[RODEO60-SKIP] %s / %s / %s reason=%s\n", family, model, personal, reason);
    fclose(f);
    g_R2RRodeo60RateErrorLogged[target] = true;
}
static void R2R_Rodeo60RateLog(unsigned int index, const char* action,
    unsigned int before, unsigned int after)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_RODEO60_RATE_REPORT, "a");
    if (f == nullptr) return;
    const R2R_Rodeo60RateEntry& e = g_R2RRodeo60RateEntries[index];
    HIE_tdstState* state = e.data->h_CurrentState;
    HIE_tdstState stateCopy = {};
    const bool readable = state != nullptr && R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(state), sizeof(HIE_tdstState)) &&
        SafeReadMemory(state, &stateCopy, sizeof(stateCopy));
    const R2R_Rodeo60RateTarget& t = g_R2RRodeo60RateTargets[e.targetIndex];
    fprintf(f, "[RODEO60-ANIMRATE] %s / %s / %s target=%u action=%s mode=%d "
        "original=%u before=%u applied=%u state=%p cSpeedAnim=%d owner=%p data=%p\n",
        t.family, t.model, t.personal, e.targetIndex + 1, action,
        g_R2RRodeo60RateMode, e.original, before, after, static_cast<void*>(state),
        readable ? static_cast<int>(stateCopy.cSpeedAnim) : -1,
        static_cast<void*>(e.owner), static_cast<void*>(e.data));
    fclose(f);
}
static void R2R_Rodeo60RateProcess(HIE_tdstSuperObject* object)
{
    if (object == HIE_M_hGetMainActor()) return;
    R2R_Rodeo60Identity identity = {};
    if (!R2R_Rodeo60ReadIdentity(object, identity) || identity.target < 0) return;
    const int target = identity.target;
    const R2R_Rodeo60RateTarget& t = g_R2RRodeo60RateTargets[target];
    const char* family = t.family; const char* model = t.model; const char* personal = t.personal;
    g_R2RRodeo60RateDetected[target] = true;

    // v.0 progression lock: ALW_Rayseau1 owns the intro network and stays fully native.
    if (target == 0) return;

    HIE_tdstEngineObject* actor = identity.actor;
    GAM_tdst3dData* data = actor->h3dData;
    if (data == nullptr || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(data), sizeof(GAM_tdst3dData)))
    {
        R2R_Rodeo60RateError(target, family, model, personal, "no readable actor-local animation data");
        return;
    }
    if (!R2R_Rodeo60RateByteWritable(&data->ucFrameRate))
    {
        R2R_Rodeo60RateError(target, family, model, personal, "animation-rate byte is not writable");
        return;
    }
    // Separate entries preserve each live actor's original rate, including
    // multiple instances with the same exact names.
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_RODEO60_RATE_MAX_ACTORS; ++i)
    {
        const R2R_Rodeo60RateEntry& e = g_R2RRodeo60RateEntries[i];
        if (e.owner == object && e.actor == actor && e.data == data &&
            e.targetIndex == static_cast<unsigned int>(target)) {
            slot = static_cast<int>(i); break;
        }
        if (e.owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0)
    {
        R2R_Rodeo60RateError(target, family, model, personal, "actor tracking table full");
        return;
    }
    R2R_Rodeo60RateEntry& e = g_R2RRodeo60RateEntries[slot];
    const unsigned int before = data->ucFrameRate;
    if (fresh)
    {
        e = R2R_Rodeo60RateEntry();
        e.owner = object; e.actor = actor; e.data = data;
        e.targetIndex = static_cast<unsigned int>(target);
        e.original = before; e.loggedMode = -1;
    }
    if (!e.forced || before != static_cast<unsigned int>(e.loggedMode)) e.original = before;
    e.visit = g_R2RRodeo60RateVisit;
    g_R2RRodeo60RateUsable[target] = true;
    const bool log = e.loggedMode != g_R2RRodeo60RateMode || e.lastState != data->h_CurrentState;
    if (g_R2RRodeo60RateMode == 0)
    {
        if (e.forced)
        {
            data->ucFrameRate = static_cast<unsigned char>(e.original);
            R2R_Rodeo60RateLog(slot, "RESTORE", before, data->ucFrameRate);
            e.forced = false;
        }
        else if (log) R2R_Rodeo60RateLog(slot, "VANILLA", before, before);
    }
    else
    {
        data->ucFrameRate = static_cast<unsigned char>(g_R2RRodeo60RateMode);
        if (log) R2R_Rodeo60RateLog(slot, "APPLY", before, data->ucFrameRate);
        e.forced = true;
    }
    e.loggedMode = g_R2RRodeo60RateMode;
    e.lastState = data->h_CurrentState;
}
static unsigned int g_R2RRodeo60RateScanBudget = 0;
static void R2R_Rodeo60RateScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || g_R2RRodeo60RateScanBudget == 0 || !R2R_AddressReadable(
        reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    --g_R2RRodeo60RateScanBudget;
    R2R_Rodeo60RateProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (g_R2RRodeo60RateScanBudget == 0) break;
        if (object != nullptr) R2R_Rodeo60RateScan(object, depth + 1);
    }
}
static void R2R_Rodeo60RateForgetWorld()
{
    std::memset(g_R2RRodeo60RateEntries, 0, sizeof(g_R2RRodeo60RateEntries));
    std::memset(g_R2RRodeo60RateErrorLogged, 0, sizeof(g_R2RRodeo60RateErrorLogged));
    g_R2RRodeo60RateWorld = nullptr; g_R2RRodeo60RateInactiveWorld = nullptr;
    g_R2RRodeo60RateFrame = 0;
}
static void R2R_Rodeo60RateTick()
{
    if (GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Rodeo_60") != 0 ||
        GAM_g_p_stDynamicWorld == nullptr || *GAM_g_p_stDynamicWorld == nullptr)
    {
        R2R_Rodeo60RateForgetWorld();
        return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr
        ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RRodeo60RateWorld || inactive != g_R2RRodeo60RateInactiveWorld)
    {
        // Keep matching live actors across an in-level root change so F8
        // restores the baseline rather than recapturing the forced rate.
        // The scan validates owner/actor/data and prunes missing entries.
        g_R2RRodeo60RateWorld = active; g_R2RRodeo60RateInactiveWorld = inactive;
        FILE* f = nullptr;
        fopen_s(&f, R2R_RODEO60_RATE_REPORT, g_R2RRodeo60RateReportStarted ? "a" : "w");
        if (f != nullptr)
        {
            fprintf(f, "\n%s RODEO60 ANIMATION TEST: %u randomized animation targets, "
                "global Stats controls: F6=MIN F7=MAX F8=RANDOM F12=NATIVE. "
                "All 28 selected identities are detected/protected; ALW_Rayseau1 is fully native, the other 27 keep exact animation randomization.\n",
                VERSION, R2R_RODEO60_ANIMATION_TEST_COUNT);
            fclose(f); g_R2RRodeo60RateReportStarted = true;
        }
    }
    std::memset(g_R2RRodeo60RateDetected, 0, sizeof(g_R2RRodeo60RateDetected));
    std::memset(g_R2RRodeo60RateUsable, 0, sizeof(g_R2RRodeo60RateUsable));
    ++g_R2RRodeo60RateVisit;
    g_R2RRodeo60RateScanBudget = 4096;
    R2R_Rodeo60RateScan(active, 0);
    if (inactive != active) R2R_Rodeo60RateScan(inactive, 0);
    for (unsigned int i = 0; i < R2R_RODEO60_RATE_MAX_ACTORS; ++i)
        if (g_R2RRodeo60RateEntries[i].visit != g_R2RRodeo60RateVisit)
            g_R2RRodeo60RateEntries[i] = R2R_Rodeo60RateEntry();
    if ((g_R2RRodeo60RateFrame++ % 300) == 0)
    {
        FILE* f = nullptr;
        fopen_s(&f, R2R_RODEO60_RATE_REPORT, "a");
        if (f == nullptr) return;
        unsigned int detected = 0, usable = 0, actors = 0;
        for (unsigned int i = 0; i < R2R_RODEO60_RATE_TARGET_COUNT; ++i)
        {
            if (g_R2RRodeo60RateDetected[i])
            {
                ++detected;
            }
            if (g_R2RRodeo60RateUsable[i]) ++usable;
            if (!g_R2RRodeo60RateDetected[i])
            {
                const R2R_Rodeo60RateTarget& t = g_R2RRodeo60RateTargets[i];
                fprintf(f, "[RODEO60-NOT-FOUND] target=%u %s / %s / %s "
                    "prefixFields=%u suffix=%s\n", i + 1, t.family, t.model, t.personal,
                    t.prefixFields, t.personalSuffix != nullptr ? t.personalSuffix : "(none)");
            }
        }
        for (unsigned int i = 0; i < R2R_RODEO60_RATE_MAX_ACTORS; ++i)
            if (g_R2RRodeo60RateEntries[i].owner != nullptr) ++actors;
        fprintf(f, "[RODEO60-SUMMARY] detected=%u/%u animationData=%u/%u "
            "trackedActors=%u mode=%d\n", detected, R2R_RODEO60_RATE_TARGET_COUNT,
            usable, R2R_RODEO60_ANIMATION_TEST_COUNT, actors, g_R2RRodeo60RateMode);
        fclose(f);
    }
}

