static const unsigned int R2R_GLOB20_TARGET_COUNT =
    static_cast<unsigned int>(sizeof(g_R2RGlob20Targets) / sizeof(g_R2RGlob20Targets[0]));
static const unsigned int R2R_GLOB20_MAX_ENTRIES = 48;
struct R2R_Glob20Entry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    GAM_tdst3dData* data;
    GAM_tdstStandardGame* standard;
    HIE_tdstState* state;
    unsigned int target, visit;
    uint32_t key;
    unsigned char originalRate, forcedRate;
    bool rateForced;
    R2R_StatsPlaytestMode rateMode;
    uint32_t rateGeneration;
    bool capturedFloat[2], forcedFloat[2];
    float originalFloat[2], lastFloat[2];
    bool hpCaptured, hpForced;
    unsigned char originalHPMax, forcedHPMax;
    R2R_StatsPlaytestMode hpMode, fieldMode;
    uint32_t hpGeneration, fieldGeneration;
    bool doorProgressTracked;
    float lastDoorProgress;
};
static R2R_Glob20Entry g_R2RGlob20Entries[R2R_GLOB20_MAX_ENTRIES] = {};
static HIE_tdstSuperObject* g_R2RGlob20World = nullptr;
static HIE_tdstSuperObject* g_R2RGlob20InactiveWorld = nullptr;
static unsigned int g_R2RGlob20Visit = 0, g_R2RGlob20Frame = 0;
static bool g_R2RGlob20Started = false;

static int R2R_Glob20Identity(HIE_tdstSuperObject* object, HIE_tdstEngineObject*& actor)
{
    actor = nullptr;
    if (!R2R_Vulca20IdentityActor(object, actor)) return -1;
    char family[96] = {}, model[96] = {}, personal[96] = {};
    if (!R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 0), family, sizeof(family))) return -1;
    bool familyRelevant = false;
    for (const auto& t : g_R2RGlob20Targets)
        if (_stricmp(t.family, family) == 0) { familyRelevant = true; break; }
    if (!familyRelevant ||
        !R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 1), model, sizeof(model)) ||
        !R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 2), personal, sizeof(personal))) return -1;
    for (unsigned int i = 0; i < R2R_GLOB20_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RGlob20Targets[i];
        if (_stricmp(family, t.family) == 0 && _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0) return static_cast<int>(i);
    }
    return -1;
}
static void R2R_Glob20Log(const char* action, const R2R_Glob20Entry& e,
    const char* what, float before, float after)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_GLOB20_REPORT, "a");
    if (!f) return;
    fprintf(f, "[GLOB20] %s actor=%s owner=%p %s: %.3f -> %.3f mode=%s gen=%u\n",
        action, g_R2RGlob20Targets[e.target].personal, static_cast<void*>(e.owner),
        what ? what : "", before, after, R2R_StatsModeName(R2R_StatsEffectiveMode()),
        g_R2RStatsPlaytestGeneration);
    fclose(f);
}
static float R2R_Glob20Factor(const R2R_Glob20Entry& e, unsigned int slot,
    const R2R_Glob20FloatRule& rule)
{
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return rule.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return rule.maxFactor;
    if (mode != R2R_STATS_MODE_RANDOM) return 1.0f;
    const int minMilli = static_cast<int>(rule.minFactor * 1000.0f + 0.5f);
    const int maxMilli = static_cast<int>(rule.maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = e.key ^ (slot * 0x85EBCA6Bu) ^
        (g_R2RStatsPlaytestGeneration * 0x9E3779B9u);
    return R2R_RollRange("Stats.Glob20.DSG", "GLob_20", salt, minMilli, maxMilli) / 1000.0f;
}
// Exact static DSG defaults from the supplied Raymap export. If a script or
// a reload resets an actor after an earlier MIN/MAX roll, anchor multipliers
// to the actual native values instead of compounding old forced values.
static float R2R_Glob20NativeFloat(unsigned int target, unsigned int dsgIndex)
{
    if (target == 2u && dsgIndex == 6u) return 3.000f;
    if (target == 2u && dsgIndex == 7u) return 6.000f;
    if (target == 5u && dsgIndex == 0u) return 15.000f;
    if (target == 8u && dsgIndex == 2u) return 12.000f;
    if (target == 11u && dsgIndex == 2u) return 2.000f;
    return 0.0f;
}
static void R2R_Glob20Process(HIE_tdstSuperObject* object)
{
    HIE_tdstEngineObject* actor = nullptr;
    const int targetIndex = R2R_Glob20Identity(object, actor);
    if (targetIndex < 0 || actor == nullptr || actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame))) return;
    const auto& target = g_R2RGlob20Targets[targetIndex];
    GAM_tdstStandardGame* sg = actor->hStandardGame;
    GAM_tdst3dData* data = actor->h3dData;
    const bool dataValid = data && R2R_AddressReadable(reinterpret_cast<uintptr_t>(data), sizeof(GAM_tdst3dData)) &&
        R2R_Vulca20RateByteWritable(&data->ucFrameRate);

    int slot = -1, vacant = -1;
    for (unsigned int i = 0; i < R2R_GLOB20_MAX_ENTRIES; ++i)
    {
        const auto& old = g_R2RGlob20Entries[i];
        if (old.owner == object && old.actor == actor && old.standard == sg &&
            old.target == static_cast<unsigned int>(targetIndex)) { slot = static_cast<int>(i); break; }
        if (!old.owner && vacant < 0) vacant = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = vacant;
    if (slot < 0) return;
    auto& e = g_R2RGlob20Entries[slot];
    if (fresh)
    {
        e = R2R_Glob20Entry();
        e.owner = object; e.actor = actor; e.standard = sg; e.data = data;
        e.target = static_cast<unsigned int>(targetIndex);
        e.key = R2R_StatsActorSlotKey(object, sg, target.family, target.model, target.personal);
        e.rateMode = R2R_STATS_MODE_AUTO;
        e.hpMode = e.fieldMode = R2R_STATS_MODE_AUTO;
        e.hpGeneration = e.rateGeneration = e.fieldGeneration = UINT32_MAX;
        if (dataValid) e.originalRate = data->ucFrameRate;
        R2R_Glob20Log("TRACK", e, "identity", 0.0f, 0.0f);
    }
    e.visit = g_R2RGlob20Visit;
    const auto mode = R2R_StatsEffectiveMode();

    // Actor-local animation control includes cinematic and story actors;
    // no state, navigation, dialogue or MaxHP command mailbox edits.
    if (target.animate && dataValid)
    {
        const unsigned int before = data->ucFrameRate;
        if (!e.rateForced || before != e.forcedRate)
            e.originalRate = static_cast<unsigned char>(before);
        unsigned int desired = e.originalRate;
        const bool gnak = _stricmp(target.model, "FRH_sbire_gnak") == 0;
        const bool scripted = _stricmp(target.family, "globox") == 0 ||
            _stricmp(target.family, "rayman") == 0 ||
            _stricmp(target.family, "Globox_Cine") == 0 ||
            _stricmp(target.family, "nef_pirate_cine") == 0 ||
            _stricmp(target.family, "Ray_Glob20") == 0 ||
            _stricmp(target.family, "nef_pirate") == 0 ||
            _stricmp(target.family, "ptizetre") == 0 ||
            _stricmp(target.family, "porte") == 0 ||
            _stricmp(target.family, "porte_laser") == 0 ||
            _stricmp(target.family, "buisson") == 0;
        const int minRate = gnak ? 10 : (scripted ? 12 : 5);
        const int maxRate = gnak ? 70 : (scripted ? 75 : 120);
        if (mode == R2R_STATS_MODE_MIN) desired = minRate;
        else if (mode == R2R_STATS_MODE_MAX) desired = maxRate;
        else if (mode == R2R_STATS_MODE_RANDOM)
            desired = static_cast<unsigned int>(R2R_RollRange("Stats.Glob20.Animation",
                "GLob_20", e.key ^ (g_R2RStatsPlaytestGeneration * 0xA1B2C3D5u), minRate, maxRate));
        const bool changed = e.rateMode != mode || e.rateGeneration != g_R2RStatsPlaytestGeneration ||
            e.state != data->h_CurrentState;
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (e.rateForced && before == e.forcedRate) data->ucFrameRate = e.originalRate;
            if (changed) R2R_Glob20Log("ANIM_NATIVE", e, "rate", static_cast<float>(before),
                static_cast<float>(data->ucFrameRate));
            e.rateForced = false;
        }
        else
        {
            if (before != desired) data->ucFrameRate = static_cast<unsigned char>(desired);
            if (changed) R2R_Glob20Log("ANIM_SET", e, "rate", static_cast<float>(before), static_cast<float>(desired));
            e.rateForced = true; e.forcedRate = static_cast<unsigned char>(desired);
        }
        e.state = data->h_CurrentState;
        e.rateMode = mode;
        e.rateGeneration = g_R2RStatsPlaytestGeneration;
    }

    // JEZ_PorteLaser: script changes Float_3 by +/-0.4 per frame while
    // closing/opening. Scale ONLY that small observed step, not the 0.01
    // or 6.5 endpoint assignments. This keeps the Globbox event functional.
    if (_stricmp(target.model, "JEZ_PorteLaser") == 0)
    {
        float* progress = nullptr;
        if (R2R_Learn10ExtraGetFloat(object, 3, progress) && progress &&
            std::isfinite(*progress) && *progress >= 0.01f && *progress <= 6.51f)
        {
            const float value = *progress;
            if (e.doorProgressTracked && mode != R2R_STATS_MODE_NATIVE)
            {
                const float delta = value - e.lastDoorProgress;
                if (std::fabs(delta) > 0.08f && std::fabs(delta) < 0.55f)
                {
                    const float factor = mode == R2R_STATS_MODE_MIN ? 0.55f :
                        mode == R2R_STATS_MODE_MAX ? 1.75f :
                        R2R_RollRange("Stats.GlobDoor.Progress", "GLob_20",
                            e.key ^ (g_R2RStatsPlaytestGeneration * 0xB3E19A0Du),
                            550, 1750) / 1000.0f;
                    const float changed = (std::max)(0.01f, (std::min)(6.5f,
                        e.lastDoorProgress + delta * factor));
                    *progress = changed;
                    if (std::fabs(changed - value) > 0.02f &&
                        (g_R2RStatsPlaytestGeneration != e.fieldGeneration ||
                            (g_R2RGlob20Frame % 240) == 0))
                        R2R_Glob20Log("DOOR_MOTION", e, "Float_3 step", value, changed);
                }
            }
            e.lastDoorProgress = *progress;
            e.doorProgressTracked = true;
        }
    }

    // Only DSG fields proven to represent speed or detection ranges.
    // No waypoint, Graph, Boolean, timers, positional vectors, or flags.
    for (unsigned int k = 0; k < target.floatCount; ++k)
    {
        const auto& rule = target.floats[k];
        float* p = nullptr;
        if (!R2R_Learn10ExtraGetFloat(object, rule.dsgIndex, p)) continue;
        const float before = *p;
        if (!std::isfinite(before) || before <= 0.0f || before > 1000.0f) continue;
        if (!e.capturedFloat[k] || !e.forcedFloat[k] || std::fabs(before - e.lastFloat[k]) > 0.001f)
        {
            const float native = R2R_Glob20NativeFloat(e.target, rule.dsgIndex);
            e.originalFloat[k] = native > 0.0f ? native : before;
            e.capturedFloat[k] = true;
        }
        const float factor = R2R_Glob20Factor(e, k, rule);
        const float desired = e.originalFloat[k] * factor;
        if (!std::isfinite(desired) || desired < 0.1f || desired > 1000.0f) continue;
        // When game scripts unexpectedly change a DSG field on NATIVE, do not
        // overwrite their new value; restore only the byte pattern we own.
        if (mode == R2R_STATS_MODE_NATIVE && e.forcedFloat[k] &&
            std::fabs(before - e.lastFloat[k]) > 0.001f)
        {
            e.forcedFloat[k] = false;
            continue;
        }
        const bool valueChanged = std::fabs(before - desired) > 0.001f;
        if (valueChanged) *p = desired;
        if (valueChanged || e.fieldMode != mode ||
            e.fieldGeneration != g_R2RStatsPlaytestGeneration)
            R2R_Glob20Log(mode == R2R_STATS_MODE_NATIVE ? "DSG_NATIVE" : "DSG_SET",
                e, rule.name, before, desired);
        e.lastFloat[k] = desired;
        e.forcedFloat[k] = mode != R2R_STATS_MODE_NATIVE;
    }
    e.fieldMode = mode;
    e.fieldGeneration = g_R2RStatsPlaytestGeneration;

    // Only named pirates: wait for ARG_Init (simple 6, gnak 6 or 9).
    // No forced healing on rerolls or resurrecting defeated enemies.
    if (!target.pirateHP || !R2R_Learn10ExtraWritable(sg, sizeof(*sg))) return;
    const unsigned int hp = sg->ucHitPoints, maxHP = sg->ucHitPointsMax;
    if (!hp || !maxHP) return;
    const bool gnakHP = _stricmp(target.model, "FRH_sbire_gnak") == 0;
    if (!e.hpCaptured)
    {
        if (maxHP != 6 && !(gnakHP && maxHP == 9)) return;
        e.hpCaptured = true; e.originalHPMax = static_cast<unsigned char>(maxHP);
    }
    const unsigned int nativeHP = e.originalHPMax;
    const bool reinitialized = e.hpForced && maxHP == nativeHP && hp == nativeHP &&
        e.forcedHPMax != nativeHP;
    if (!reinitialized && e.hpMode == mode && e.hpGeneration == g_R2RStatsPlaytestGeneration) return;
    if (maxHP != nativeHP && (!e.hpForced || maxHP != e.forcedHPMax)) return;
    unsigned int wanted = nativeHP;
    if (mode == R2R_STATS_MODE_MIN) wanted = 1;
    else if (mode == R2R_STATS_MODE_MAX) wanted = nativeHP * 2u;
    else if (mode == R2R_STATS_MODE_RANDOM)
        wanted = static_cast<unsigned int>(R2R_RollRange("Stats.Glob20.PirateHP", "GLob_20",
            e.key ^ (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u), 1, static_cast<int>(nativeHP * 2u)));
    unsigned int health = (hp * wanted + maxHP / 2u) / maxHP;
    if (health == 0) health = 1;
    if (health > wanted) health = wanted;
    sg->ucHitPoints = static_cast<unsigned char>(health);
    sg->ucHitPointsMax = sg->ucHitPointsMaxMax = static_cast<unsigned char>(wanted);
    e.hpForced = mode != R2R_STATS_MODE_NATIVE;
    e.forcedHPMax = static_cast<unsigned char>(wanted);
    e.hpMode = mode; e.hpGeneration = g_R2RStatsPlaytestGeneration;
    R2R_Glob20Log("HP_SET", e, "max HP", static_cast<float>(maxHP), static_cast<float>(wanted));
}
static unsigned int g_R2RGlob20Budget = 0;
static void R2R_Glob20Scan(HIE_tdstSuperObject* root, int depth)
{
    if (!root || depth > 64 || !g_R2RGlob20Budget ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    --g_R2RGlob20Budget;
    R2R_Glob20Process(root);
    HIE_tdstSuperObject* child = nullptr;
    LST_M_DynamicForEach(root, child)
    {
        if (!g_R2RGlob20Budget) break;
        if (child) R2R_Glob20Scan(child, depth + 1);
    }
}
static void R2R_Glob20ForgetWorld()
{
    std::memset(g_R2RGlob20Entries, 0, sizeof(g_R2RGlob20Entries));
    g_R2RGlob20World = g_R2RGlob20InactiveWorld = nullptr;
    g_R2RGlob20Frame = 0;
}
static void R2R_Glob20Tick()
{
    if (!GAM_g_stEngineStructure ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "GLob_20") != 0 ||
        !GAM_g_p_stDynamicWorld || !*GAM_g_p_stDynamicWorld)
    {
        R2R_Glob20ForgetWorld(); return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld ?
        *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RGlob20World || inactive != g_R2RGlob20InactiveWorld)
    {
        g_R2RGlob20World = active; g_R2RGlob20InactiveWorld = inactive;
        FILE* f = nullptr;
        fopen_s(&f, R2R_GLOB20_REPORT, g_R2RGlob20Started ? "a" : "w");
        if (f)
        {
            fprintf(f, "\n%s GLob_20: selective export 16 named actors. "
                "F6 MIN / F7 MAX / F8 RANDOM / F12 NATIVE. "
                "Simple pirate HP 1..12, Float_0 detection x0.5..2; "
                "gnak pirate HP 1..12/18 (native 6 or 9), animation 10..70; "
                "bomb Float_6/7 flight speeds x0.75..1.25; "
                "cage Float_2 lift x0.5..1.5. "
                "Globox/Rayseau/Ptizetre/scene/bush/door/ship animations included; "
                "boat Float_2 speed x0.65..1.35; laser door progress scaled; "
                "quest commands/waypoints/ship event spawns native.\n", VERSION);
            for (unsigned int i = 0; i < R2R_GLOB20_TARGET_COUNT; ++i)
                fprintf(f, "[GLOB20-TARGET] %u %s / %s / %s | anim=%s hp=%s floats=%u | %s\n",
                    i, g_R2RGlob20Targets[i].family, g_R2RGlob20Targets[i].model,
                    g_R2RGlob20Targets[i].personal,
                    g_R2RGlob20Targets[i].animate ? "YES" : "NATIVE",
                    g_R2RGlob20Targets[i].pirateHP ? "YES" : "NATIVE",
                    g_R2RGlob20Targets[i].floatCount, g_R2RGlob20Targets[i].policy);
            fclose(f); g_R2RGlob20Started = true;
        }
    }
    ++g_R2RGlob20Visit;
    g_R2RGlob20Budget = 4096;
    R2R_Glob20Scan(active, 0);
    if (inactive != active) R2R_Glob20Scan(inactive, 0);
    for (auto& e : g_R2RGlob20Entries)
        if (e.owner && e.visit != g_R2RGlob20Visit) e = R2R_Glob20Entry();
    if ((g_R2RGlob20Frame++ % 300) == 0)
    {
        unsigned int found = 0;
        bool used[R2R_GLOB20_TARGET_COUNT] = {};
        for (const auto& e : g_R2RGlob20Entries)
            if (e.owner && !used[e.target]) { used[e.target] = true; ++found; }
        FILE* f = nullptr;
        fopen_s(&f, R2R_GLOB20_REPORT, "a");
        if (f)
        {
            fprintf(f, "[GLOB20-SUMMARY] found=%u/%u mode=%s generation=%u\n",
                found, R2R_GLOB20_TARGET_COUNT, R2R_StatsModeName(R2R_StatsEffectiveMode()),
                g_R2RStatsPlaytestGeneration);
            for (unsigned int i = 0; i < R2R_GLOB20_TARGET_COUNT; ++i)
                if (!used[i]) fprintf(f, "[GLOB20-MISSING] %s\n", g_R2RGlob20Targets[i].personal);
            fclose(f);
        }
    }
}

