static const unsigned int R2R_WHALE10_TARGET_COUNT =
    static_cast<unsigned int>(sizeof(g_R2RWhale10Targets) / sizeof(g_R2RWhale10Targets[0]));
// Int_7 controls the baleine bubble emission interval in Whale_10.
// Do not modify time stamps, pointers, graph routes, or Ptizetre flags.
struct R2R_Whale10IntRule
{
    unsigned char target, dsgIndex;
    int native;
    float minFactor, maxFactor;
    const char* name;
};
static const R2R_Whale10IntRule g_R2RWhale10IntRules[] =
{
    {1, 7, 3000, 1.80f, 0.45f, "Int_7 piranha/bubble release interval (ms)"}
};
static const unsigned int R2R_WHALE10_INT_RULE_COUNT =
    static_cast<unsigned int>(sizeof(g_R2RWhale10IntRules) / sizeof(g_R2RWhale10IntRules[0]));
static const unsigned int R2R_WHALE10_MAX_ENTRIES = 192;
struct R2R_Whale10Entry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    GAM_tdst3dData* data;
    GAM_tdstStandardGame* standard;
    HIE_tdstState* state;
    unsigned int target, visit;
    uint32_t key;
    unsigned char originalRate, forcedRate;
    bool rateForced;
    R2R_StatsPlaytestMode rateMode;
    uint32_t rateGeneration;
    bool capturedFloat[4], forcedFloat[4];
    float originalFloat[4], lastFloat[4];
    bool capturedInt[16], forcedInt[16];
    int lastInt[16];
    R2R_StatsPlaytestMode intMode;
    uint32_t intGeneration;
    bool hpCaptured, hpForced;
    unsigned char originalHPMax, forcedHPMax;
    R2R_StatsPlaytestMode hpMode, fieldMode;
    uint32_t hpGeneration, fieldGeneration;
    };
static R2R_Whale10Entry g_R2RWhale10Entries[R2R_WHALE10_MAX_ENTRIES] = {};
static HIE_tdstSuperObject* g_R2RWhale10World = nullptr;
static HIE_tdstSuperObject* g_R2RWhale10InactiveWorld = nullptr;
static unsigned int g_R2RWhale10Visit = 0, g_R2RWhale10Frame = 0;
static bool g_R2RWhale10Started = false;

static int R2R_Whale10Identity(HIE_tdstSuperObject* object, HIE_tdstEngineObject*& actor)
{
    actor = nullptr;
    if (!R2R_Vulca20IdentityActor(object, actor)) return -1;
    char family[96] = {}, model[96] = {}, personal[96] = {};
    if (!R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 0), family, sizeof(family))) return -1;
    bool familyRelevant = false;
    for (const auto& t : g_R2RWhale10Targets)
        if (_stricmp(t.family, family) == 0) { familyRelevant = true; break; }
    if (!familyRelevant ||
        !R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 1), model, sizeof(model)) ||
        !R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 2), personal, sizeof(personal))) return -1;
    for (unsigned int i = 0; i < R2R_WHALE10_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RWhale10Targets[i];
        if (_stricmp(family, t.family) == 0 && _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0) return static_cast<int>(i);
    }
    return -1;
}
static void R2R_Whale10Log(const char* action, const R2R_Whale10Entry& e,
    const char* what, float before, float after)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_WHALE10_REPORT, "a");
    if (!f) return;
    fprintf(f, "[WHALE10] %s actor=%s owner=%p %s: %.3f -> %.3f mode=%s gen=%u\n",
        action, g_R2RWhale10Targets[e.target].personal, static_cast<void*>(e.owner),
        what ? what : "", before, after, R2R_StatsModeName(R2R_StatsEffectiveMode()),
        g_R2RStatsPlaytestGeneration);
    fclose(f);
}
static float R2R_Whale10Factor(const R2R_Whale10Entry& e, unsigned int slot,
    const R2R_Whale10FloatRule& rule)
{
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return rule.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return rule.maxFactor;
    if (mode != R2R_STATS_MODE_RANDOM) return 1.0f;
    const int minMilli = static_cast<int>(rule.minFactor * 1000.0f + 0.5f);
    const int maxMilli = static_cast<int>(rule.maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = e.key ^ (slot * 0x85EBCA6Bu) ^
        (g_R2RStatsPlaytestGeneration * 0x9E3779B9u);
    return R2R_RollRange("Stats.Whale10.DSG", "Whale_10", salt, minMilli, maxMilli) / 1000.0f;
}
// Exact static DSG defaults from the supplied Raymap export. If a script or
// a reload resets an actor after an earlier MIN/MAX roll, anchor multipliers
// to the actual native values instead of compounding old forced values.
static float R2R_Whale10NativeFloat(unsigned int target, unsigned int dsgIndex)
{
    if (target == 1u) {
        if (dsgIndex == 0u) return 100.0f;
        if (dsgIndex == 1u) return 35.0f;
        if (dsgIndex == 4u) return 30.0f;
        if (dsgIndex == 5u) return 45.0f;
    }
    if (target == 2u || target == 3u) {
        if (dsgIndex == 1u) return target == 2u ? 35.0f : 30.0f;
        if (dsgIndex == 2u) return 35.0f;
    }
    if (target == 4u) {
        if (dsgIndex == 1u) return 15.0f;
        // MIC_Gege_INIT multiplies native Float_2 (0.5) by 11.5.
        // Never write this field before it has been initialized to 5.75.
        if (dsgIndex == 2u) return 5.75f;
        if (dsgIndex == 3u) return 8.0f;
    }
    if (target == 5u) {
        if (dsgIndex == 3u) return 50.0f;
        if (dsgIndex == 4u) return 10.0f;
    }
    return 0.0f;
}
static bool R2R_Whale10GetInt(HIE_tdstSuperObject* object, unsigned char index, int*& value)
{
    value = nullptr;
    AI_tdeDsgVarType type = AI_E_Nb_dvt;
    void* raw = nullptr;
    if (!AI_fn_bGetDsgVar(object, index, &type, &raw) || !raw ||
        type != AI_E_dvt_Integer ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), sizeof(int)) ||
        !R2R_Learn10ExtraWritable(raw, sizeof(int))) return false;
    value = reinterpret_cast<int*>(raw);
    return true;
}
static void R2R_Whale10Process(HIE_tdstSuperObject* object)
{
    HIE_tdstEngineObject* actor = nullptr;
    const int targetIndex = R2R_Whale10Identity(object, actor);
    if (targetIndex < 0 || actor == nullptr || actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame))) return;
    const auto& target = g_R2RWhale10Targets[targetIndex];
    GAM_tdstStandardGame* sg = actor->hStandardGame;
    GAM_tdst3dData* data = actor->h3dData;
    const bool dataValid = data && R2R_AddressReadable(reinterpret_cast<uintptr_t>(data), sizeof(GAM_tdst3dData)) &&
        R2R_Vulca20RateByteWritable(&data->ucFrameRate);

    int slot = -1, vacant = -1;
    for (unsigned int i = 0; i < R2R_WHALE10_MAX_ENTRIES; ++i)
    {
        const auto& old = g_R2RWhale10Entries[i];
        if (old.owner == object && old.actor == actor && old.standard == sg &&
            old.target == static_cast<unsigned int>(targetIndex)) { slot = static_cast<int>(i); break; }
        if (!old.owner && vacant < 0) vacant = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = vacant;
    if (slot < 0) return;
    auto& e = g_R2RWhale10Entries[slot];
    if (fresh)
    {
        e = R2R_Whale10Entry();
        e.owner = object; e.actor = actor; e.standard = sg; e.data = data;
        e.target = static_cast<unsigned int>(targetIndex);
        e.key = R2R_StatsActorSlotKey(object, sg, target.family, target.model, target.personal);
        e.rateMode = R2R_STATS_MODE_AUTO;
        e.hpMode = e.fieldMode = e.intMode = R2R_STATS_MODE_AUTO;
        e.hpGeneration = e.rateGeneration = e.fieldGeneration = e.intGeneration = UINT32_MAX;
        if (dataValid) e.originalRate = data->ucFrameRate;
        R2R_Whale10Log("TRACK", e, "identity", 0.0f, 0.0f);
    }
    e.visit = g_R2RWhale10Visit;
    const auto mode = R2R_StatsEffectiveMode();

    // Actor-local animation control includes cinematic and story actors;
    // no state, navigation, dialogue or MaxHP command mailbox edits.
    if (target.animate && dataValid)
    {
        const unsigned int before = data->ucFrameRate;
        if (!e.rateForced || before != e.forcedRate)
            e.originalRate = static_cast<unsigned char>(before);
        unsigned int desired = e.originalRate;
        const bool gnak = _stricmp(target.model, "FRH_sbire_gnak") == 0 ||
            _stricmp(target.model, "OLD_SBIRE_alarme") == 0;
        const bool scripted = _stricmp(target.family, "rayman") == 0 ||
            _stricmp(target.family, "faisceau") == 0 ||
            _stricmp(target.family, "Cage") == 0 ||
            _stricmp(target.family, "poisson_rigol") == 0 ||
            _stricmp(target.model, "BNT_TonneauFusee") == 0 ||
            _stricmp(target.model, "XAP_TonoGear_light") == 0;
        const int minRate = gnak ? 10 : (scripted ? 12 : 5);
        const int maxRate = gnak ? 70 : (scripted ? 75 : 120);
        if (mode == R2R_STATS_MODE_MIN) desired = minRate;
        else if (mode == R2R_STATS_MODE_MAX) desired = maxRate;
        else if (mode == R2R_STATS_MODE_RANDOM)
            desired = static_cast<unsigned int>(R2R_RollRange("Stats.Whale10.Animation",
                "Whale_10", e.key ^ (g_R2RStatsPlaytestGeneration * 0xA1B2C3D5u), minRate, maxRate));
        const bool changed = e.rateMode != mode || e.rateGeneration != g_R2RStatsPlaytestGeneration ||
            e.state != data->h_CurrentState;
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (e.rateForced && before == e.forcedRate) data->ucFrameRate = e.originalRate;
            if (changed) R2R_Whale10Log("ANIM_NATIVE", e, "rate", static_cast<float>(before),
                static_cast<float>(data->ucFrameRate));
            e.rateForced = false;
        }
        else
        {
            if (before != desired) data->ucFrameRate = static_cast<unsigned char>(desired);
            if (changed) R2R_Whale10Log("ANIM_SET", e, "rate", static_cast<float>(before), static_cast<float>(desired));
            e.rateForced = true; e.forcedRate = static_cast<unsigned char>(desired);
        }
        e.state = data->h_CurrentState;
        e.rateMode = mode;
        e.rateGeneration = g_R2RStatsPlaytestGeneration;
    }

    // Float DSG fields proven to represent speed and ranges. No Graph,
    // WayPoint, Boolean, positional vector, or event/mailbox writes.
    for (unsigned int k = 0; k < target.floatCount; ++k)
    {
        const auto& rule = target.floats[k];
        float* p = nullptr;
        if (!R2R_Learn10ExtraGetFloat(object, rule.dsgIndex, p)) continue;
        const float before = *p;
        if (!std::isfinite(before) || before <= 0.0f || before > 1000.0f) continue;
        // Gorilla Float_2 is multiplied by 11.5 in its init script.
        if (e.target == 4u && rule.dsgIndex == 2u && before < 1.50f) continue;
        if (!e.capturedFloat[k] || !e.forcedFloat[k] || std::fabs(before - e.lastFloat[k]) > 0.001f)
        {
            const float native = R2R_Whale10NativeFloat(e.target, rule.dsgIndex);
            e.originalFloat[k] = native > 0.0f ? native : before;
            e.capturedFloat[k] = true;
        }
        const float factor = R2R_Whale10Factor(e, k, rule);
        const float desired = e.originalFloat[k] * factor;
        if (!std::isfinite(desired) || desired < 0.1f || desired > 1000.0f) continue;
        // When game scripts unexpectedly change a DSG field on NATIVE, do not
        // overwrite their new value; restore only the byte pattern we own.
        if (mode == R2R_STATS_MODE_NATIVE && e.forcedFloat[k] &&
            std::fabs(before - e.lastFloat[k]) > 0.001f)
        {
            e.forcedFloat[k] = false;
            continue;
        }
        const bool valueChanged = std::fabs(before - desired) > 0.001f;
        if (valueChanged) *p = desired;
        if (valueChanged || e.fieldMode != mode ||
            e.fieldGeneration != g_R2RStatsPlaytestGeneration)
            R2R_Whale10Log(mode == R2R_STATS_MODE_NATIVE ? "DSG_NATIVE" : "DSG_SET",
                e, rule.name, before, desired);
        e.lastFloat[k] = desired;
        e.forcedFloat[k] = mode != R2R_STATS_MODE_NATIVE;
    }
    e.fieldMode = mode;
    e.fieldGeneration = g_R2RStatsPlaytestGeneration;

    // Independent script timer values, always anchored to Raymap originals.
    // Never scale a value already written by this randomizer.
    for (unsigned int k = 0; k < R2R_WHALE10_INT_RULE_COUNT; ++k)
    {
        const auto& rule = g_R2RWhale10IntRules[k];
        if (rule.target != e.target) continue;
        int* p = nullptr;
        if (!R2R_Whale10GetInt(object, rule.dsgIndex, p)) continue;
        const int before = *p;
        if (before <= 0 || before > 120000) continue;
        // This timer may have been initialized late or rewritten by the AI.
        // Only intervene when it is an original or our own previous value.
        if (before != rule.native && (!e.forcedInt[k] || before != e.lastInt[k])) continue;
        float factor = 1.0f;
        if (mode == R2R_STATS_MODE_MIN) factor = rule.minFactor;
        else if (mode == R2R_STATS_MODE_MAX) factor = rule.maxFactor;
        else if (mode == R2R_STATS_MODE_RANDOM)
        {
            const float low = (std::min)(rule.minFactor, rule.maxFactor);
            const float high = (std::max)(rule.minFactor, rule.maxFactor);
            const int lo = static_cast<int>(low * 1000.0f + 0.5f);
            const int hi = static_cast<int>(high * 1000.0f + 0.5f);
            factor = R2R_RollRange("Stats.Whale10.Timer", "Whale_10",
                e.key ^ (k * 0x9E3779B9u) ^
                (g_R2RStatsPlaytestGeneration * 0xB52E53A1u), lo, hi) / 1000.0f;
        }
        int desired = static_cast<int>(rule.native * factor + 0.5f);
        if (desired < 250) desired = 250;
        if (desired > 120000) desired = 120000;
        if (before != desired) *p = desired;
        if (before != desired || e.intMode != mode ||
            e.intGeneration != g_R2RStatsPlaytestGeneration)
            R2R_Whale10Log(mode == R2R_STATS_MODE_NATIVE ? "TIMER_NATIVE" : "TIMER_SET",
                e, rule.name, static_cast<float>(before), static_cast<float>(desired));
        e.capturedInt[k] = true;
        e.forcedInt[k] = mode != R2R_STATS_MODE_NATIVE;
        e.lastInt[k] = desired;
    }
    e.intMode = mode;
    e.intGeneration = g_R2RStatsPlaytestGeneration;

    // This export has no verified combat HP field for any of these six
    // actors. Keep scripted reward/encounter commands untouched.

}
static unsigned int g_R2RWhale10Budget = 0;
static void R2R_Whale10Scan(HIE_tdstSuperObject* root, int depth)
{
    if (!root || depth > 64 || !g_R2RWhale10Budget ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    --g_R2RWhale10Budget;
    R2R_Whale10Process(root);
    HIE_tdstSuperObject* child = nullptr;
    LST_M_DynamicForEach(root, child)
    {
        if (!g_R2RWhale10Budget) break;
        if (child) R2R_Whale10Scan(child, depth + 1);
    }
}
static void R2R_Whale10ForgetWorld()
{
    std::memset(g_R2RWhale10Entries, 0, sizeof(g_R2RWhale10Entries));
    g_R2RWhale10World = g_R2RWhale10InactiveWorld = nullptr;
    g_R2RWhale10Frame = 0;
}
static void R2R_Whale10Tick()
{
    if (!GAM_g_stEngineStructure ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Whale_10") != 0 ||
        !GAM_g_p_stDynamicWorld || !*GAM_g_p_stDynamicWorld)
    {
        R2R_Whale10ForgetWorld(); return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld ?
        *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RWhale10World || inactive != g_R2RWhale10InactiveWorld)
    {
        g_R2RWhale10World = active; g_R2RWhale10InactiveWorld = inactive;
        FILE* f = nullptr;
        fopen_s(&f, R2R_WHALE10_REPORT, g_R2RWhale10Started ? "a" : "w");
        if (f)
        {
            fprintf(f, "\n%s Whale_10: 6 exact actors from Raymap; "
                "F6 MIN / F7 MAX / F8 RANDOM / F12 NATIVE. "
                "Whale speed/steering/bubble cycle; 2 piranhas pursuit, "
                "gorilla charge speed/range; Ptizetre reaction/animations. "
                "Navigation, cage rewards and story signals native.\n", VERSION);
            for (unsigned int i = 0; i < R2R_WHALE10_TARGET_COUNT; ++i)
                fprintf(f, "[WHALE10-TARGET] %u %s / %s / %s | anim=%s hp=%s floats=%u | %s\n",
                    i, g_R2RWhale10Targets[i].family, g_R2RWhale10Targets[i].model,
                    g_R2RWhale10Targets[i].personal,
                    g_R2RWhale10Targets[i].animate ? "YES" : "NATIVE",
                    g_R2RWhale10Targets[i].pirateHP ? "YES" : "NATIVE",
                    g_R2RWhale10Targets[i].floatCount, g_R2RWhale10Targets[i].policy);
            fclose(f); g_R2RWhale10Started = true;
        }
    }
    ++g_R2RWhale10Visit;
    g_R2RWhale10Budget = 4096;
    R2R_Whale10Scan(active, 0);
    if (inactive != active) R2R_Whale10Scan(inactive, 0);
    for (auto& e : g_R2RWhale10Entries)
        if (e.owner && e.visit != g_R2RWhale10Visit) e = R2R_Whale10Entry();
    if ((g_R2RWhale10Frame++ % 300) == 0)
    {
        unsigned int found = 0;
        bool used[R2R_WHALE10_TARGET_COUNT] = {};
        for (const auto& e : g_R2RWhale10Entries)
            if (e.owner && !used[e.target]) { used[e.target] = true; ++found; }
        FILE* f = nullptr;
        fopen_s(&f, R2R_WHALE10_REPORT, "a");
        if (f)
        {
            fprintf(f, "[WHALE10-SUMMARY] found=%u/%u mode=%s generation=%u\n",
                found, R2R_WHALE10_TARGET_COUNT, R2R_StatsModeName(R2R_StatsEffectiveMode()),
                g_R2RStatsPlaytestGeneration);
            for (unsigned int i = 0; i < R2R_WHALE10_TARGET_COUNT; ++i)
                if (!used[i]) fprintf(f, "[WHALE10-MISSING] %s\n", g_R2RWhale10Targets[i].personal);
            fclose(f);
        }
    }
}




