static int R2R_Plum00Identity(HIE_tdstSuperObject* object, HIE_tdstEngineObject*& actor)
{
    actor = nullptr;
    if (!R2R_Vulca20IdentityActor(object, actor)) return -1;
    char family[96] = {}, model[96] = {}, personal[96] = {};
    if (!R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 0), family, sizeof(family))) return -1;
    bool familyRelevant = false;
    for (const auto& t : g_R2RPlum00Targets)
        if (_stricmp(t.family, family) == 0) { familyRelevant = true; break; }
    if (!familyRelevant ||
        !R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 1), model, sizeof(model)) ||
        !R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 2), personal, sizeof(personal))) return -1;
    for (unsigned int i = 0; i < R2R_PLUM00_TARGET_COUNT; ++i)
    {
        const auto& t = g_R2RPlum00Targets[i];
        if (_stricmp(family, t.family) == 0 && _stricmp(model, t.model) == 0 &&
            _stricmp(personal, t.personal) == 0) return static_cast<int>(i);
    }
    return -1;
}
static void R2R_Plum00Log(const char* action, const R2R_Plum00Entry& e,
    const char* what, float before, float after)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_PLUM00_REPORT, "a");
    if (!f) return;
    fprintf(f, "[PLUM00] %s actor=%s owner=%p %s: %.3f -> %.3f mode=%s gen=%u\n",
        action, g_R2RPlum00Targets[e.target].personal, static_cast<void*>(e.owner),
        what ? what : "", before, after, R2R_StatsModeName(R2R_StatsEffectiveMode()),
        g_R2RStatsPlaytestGeneration);
    fclose(f);
}
static float R2R_Plum00Factor(const R2R_Plum00Entry& e, unsigned int slot,
    const R2R_Plum00FloatRule& rule)
{
    const auto mode = R2R_StatsEffectiveMode();
    if (mode == R2R_STATS_MODE_MIN) return rule.minFactor;
    if (mode == R2R_STATS_MODE_MAX) return rule.maxFactor;
    if (mode != R2R_STATS_MODE_RANDOM) return 1.0f;
    const int minMilli = static_cast<int>(rule.minFactor * 1000.0f + 0.5f);
    const int maxMilli = static_cast<int>(rule.maxFactor * 1000.0f + 0.5f);
    const uint32_t salt = e.key ^ (slot * 0x85EBCA6Bu) ^
        (g_R2RStatsPlaytestGeneration * 0x9E3779B9u);
    return R2R_RollRange("Stats.Plum00.DSG", "Plum_00", salt, minMilli, maxMilli) / 1000.0f;
}
// Exact static DSG defaults from the supplied Raymap export. If a script or
// a reload resets an actor after an earlier MIN/MAX roll, anchor multipliers
// to the actual native values instead of compounding old forced values.
static float R2R_Plum00NativeFloat(unsigned int target, unsigned int dsgIndex)
{
    if (target == 0u && dsgIndex == 4u) return 8.000000f;
    if (target == 0u && dsgIndex == 5u) return 6.000000f;
    if (target == 0u && dsgIndex == 6u) return 3.000000f;
    if (target == 0u && dsgIndex == 8u) return 38.000000f;
    if (target == 1u && dsgIndex == 0u) return 25.000000f;
    if (target == 1u && dsgIndex == 1u) return 1.000000f;
    if (target == 4u && dsgIndex == 1u) return 23.800000f;
    if (target == 4u && dsgIndex == 2u) return 9.200000f;
    if (target == 4u && dsgIndex == 3u) return 20.000000f;
    if (target == 5u && dsgIndex == 2u) return 19.000000f;
    if (target == 5u && dsgIndex == 6u) return 35.000000f;
    if (target == 6u && dsgIndex == 2u) return 16.000000f;
    if (target == 6u && dsgIndex == 6u) return 30.000000f;
    if (target == 7u && dsgIndex == 2u) return 22.000000f;
    if (target == 7u && dsgIndex == 6u) return 26.000000f;
    if (target == 9u && dsgIndex == 2u) return 30.000000f;
    if (target == 9u && dsgIndex == 6u) return 30.000000f;
    if (target == 10u && dsgIndex == 17u) return 0.600000f;
    if (target == 11u && dsgIndex == 17u) return 0.500000f;
    if (target == 13u && dsgIndex == 2u) return 18.000000f;
    if (target == 13u && dsgIndex == 6u) return 29.000000f;
    if (target == 14u && dsgIndex == 2u) return 25.000000f;
    if (target == 14u && dsgIndex == 6u) return 22.000000f;
    if (target == 15u && dsgIndex == 2u) return 18.000000f;
    if (target == 15u && dsgIndex == 6u) return 26.000000f;
    if (target == 16u && dsgIndex == 0u) return 19.000000f;
    if (target == 16u && dsgIndex == 1u) return 0.750000f;
    if (target == 17u && dsgIndex == 0u) return 30.000000f;
    if (target == 17u && dsgIndex == 1u) return 0.600000f;
    if (target == 19u && dsgIndex == 1u) return 2.300000f;
    if (target == 20u && dsgIndex == 10u) return 5.000000f;
    if (target == 21u && dsgIndex == 4u) return 8.000000f;
    if (target == 21u && dsgIndex == 5u) return 6.000000f;
    if (target == 21u && dsgIndex == 6u) return 3.000000f;
    if (target == 21u && dsgIndex == 8u) return 38.000000f;
    return 0.0f;
}
static bool R2R_Plum00GetInt(HIE_tdstSuperObject* object, unsigned char index, int*& value)
{
    value = nullptr;
    AI_tdeDsgVarType type = AI_E_Nb_dvt;
    void* raw = nullptr;
    if (!AI_fn_bGetDsgVar(object, index, &type, &raw) || !raw ||
        type != AI_E_dvt_Integer ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(raw), sizeof(int)) ||
        !R2R_Learn10ExtraWritable(raw, sizeof(int))) return false;
    value = reinterpret_cast<int*>(raw);
    return true;
}
static void R2R_Plum00Process(HIE_tdstSuperObject* object)
{
    HIE_tdstEngineObject* actor = nullptr;
    const int targetIndex = R2R_Plum00Identity(object, actor);
    if (targetIndex < 0 || actor == nullptr || actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame))) return;
    const auto& target = g_R2RPlum00Targets[targetIndex];
    GAM_tdstStandardGame* sg = actor->hStandardGame;
    GAM_tdst3dData* data = actor->h3dData;
    const bool dataValid = data && R2R_AddressReadable(reinterpret_cast<uintptr_t>(data), sizeof(GAM_tdst3dData)) &&
        R2R_Vulca20RateByteWritable(&data->ucFrameRate);

    int slot = -1, vacant = -1;
    for (unsigned int i = 0; i < R2R_PLUM00_MAX_ENTRIES; ++i)
    {
        const auto& old = g_R2RPlum00Entries[i];
        if (old.owner == object && old.actor == actor && old.standard == sg &&
            old.target == static_cast<unsigned int>(targetIndex)) { slot = static_cast<int>(i); break; }
        if (!old.owner && vacant < 0) vacant = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = vacant;
    if (slot < 0) return;
    auto& e = g_R2RPlum00Entries[slot];
    if (fresh)
    {
        e = R2R_Plum00Entry();
        e.owner = object; e.actor = actor; e.standard = sg; e.data = data;
        e.target = static_cast<unsigned int>(targetIndex);
        e.key = R2R_StatsActorSlotKey(object, sg, target.family, target.model, target.personal);
        e.rateMode = R2R_STATS_MODE_AUTO;
        e.hpMode = e.fieldMode = e.intMode = R2R_STATS_MODE_AUTO;
        e.hpGeneration = e.rateGeneration = e.fieldGeneration = e.intGeneration = UINT32_MAX;
        if (dataValid) e.originalRate = data->ucFrameRate;
        R2R_Plum00Log("TRACK", e, "identity", 0.0f, 0.0f);
    }
    e.visit = g_R2RPlum00Visit;
    const auto mode = R2R_StatsEffectiveMode();

    // Actor-local animation control includes cinematic and story actors;
    // no state, navigation, dialogue or MaxHP command mailbox edits.
    if (target.animate && dataValid)
    {
        const unsigned int before = data->ucFrameRate;
        if (!e.rateForced || before != e.forcedRate)
            e.originalRate = static_cast<unsigned char>(before);
        unsigned int desired = e.originalRate;
        const bool gnak = _stricmp(target.model, "FRH_sbire_gnak") == 0;
        const bool scripted = _stricmp(target.family, "murfy") == 0 ||
            _stricmp(target.family, "megashoot") == 0 ||
            _stricmp(target.family, "dalle") == 0 ||
            _stricmp(target.family, "prune") == 0;
        const int minRate = gnak ? 10 : (scripted ? 12 : 5);
        const int maxRate = gnak ? 70 : (scripted ? 75 : 120);
        if (mode == R2R_STATS_MODE_MIN) desired = minRate;
        else if (mode == R2R_STATS_MODE_MAX) desired = maxRate;
        else if (mode == R2R_STATS_MODE_RANDOM)
            desired = static_cast<unsigned int>(R2R_RollRange("Stats.Plum00.Animation",
                "Plum_00", e.key ^ (g_R2RStatsPlaytestGeneration * 0xA1B2C3D5u), minRate, maxRate));
        const bool changed = e.rateMode != mode || e.rateGeneration != g_R2RStatsPlaytestGeneration ||
            e.state != data->h_CurrentState;
        if (mode == R2R_STATS_MODE_NATIVE)
        {
            if (e.rateForced && before == e.forcedRate) data->ucFrameRate = e.originalRate;
            if (changed) R2R_Plum00Log("ANIM_NATIVE", e, "rate", static_cast<float>(before),
                static_cast<float>(data->ucFrameRate));
            e.rateForced = false;
        }
        else
        {
            if (before != desired) data->ucFrameRate = static_cast<unsigned char>(desired);
            if (changed) R2R_Plum00Log("ANIM_SET", e, "rate", static_cast<float>(before), static_cast<float>(desired));
            e.rateForced = true; e.forcedRate = static_cast<unsigned char>(desired);
        }
        e.state = data->h_CurrentState;
        e.rateMode = mode;
        e.rateGeneration = g_R2RStatsPlaytestGeneration;
    }

    // Float DSG fields proven to represent speed and ranges. No Graph,
    // WayPoint, Boolean, positional vector, or event/mailbox writes.
    for (unsigned int k = 0; k < target.floatCount; ++k)
    {
        const auto& rule = target.floats[k];
        float* p = nullptr;
        if (!R2R_Learn10ExtraGetFloat(object, rule.dsgIndex, p)) continue;
        const float before = *p;
        if (!std::isfinite(before) || before <= 0.0f || before > 1000.0f) continue;
        // Every gorilla Float_2 is multiplied by 11.5 in MIC_Gege_INIT.
        // Wait until the native post-init value (e.g., 0.8*11.5 == 9.2).
        if (_stricmp(target.model, "MIC_GorilleGardien") == 0 &&
            rule.dsgIndex == 2u && before < 1.50f) continue;
        if (!e.capturedFloat[k] || !e.forcedFloat[k] || std::fabs(before - e.lastFloat[k]) > 0.001f)
        {
            const float native = R2R_Plum00NativeFloat(e.target, rule.dsgIndex);
            e.originalFloat[k] = native > 0.0f ? native : before;
            e.capturedFloat[k] = true;
        }
        const float factor = R2R_Plum00Factor(e, k, rule);
        const float desired = e.originalFloat[k] * factor;
        if (!std::isfinite(desired) || desired < 0.1f || desired > 1000.0f) continue;
        // When game scripts unexpectedly change a DSG field on NATIVE, do not
        // overwrite their new value; restore only the byte pattern we own.
        if (mode == R2R_STATS_MODE_NATIVE && e.forcedFloat[k] &&
            std::fabs(before - e.lastFloat[k]) > 0.001f)
        {
            e.forcedFloat[k] = false;
            continue;
        }
        const bool valueChanged = std::fabs(before - desired) > 0.001f;
        if (valueChanged) *p = desired;
        if (valueChanged || e.fieldMode != mode ||
            e.fieldGeneration != g_R2RStatsPlaytestGeneration)
            R2R_Plum00Log(mode == R2R_STATS_MODE_NATIVE ? "DSG_NATIVE" : "DSG_SET",
                e, rule.name, before, desired);
        e.lastFloat[k] = desired;
        e.forcedFloat[k] = mode != R2R_STATS_MODE_NATIVE;
    }
    e.fieldMode = mode;
    e.fieldGeneration = g_R2RStatsPlaytestGeneration;

    // Independent script timer values, always anchored to Raymap originals.
    // Never scale a value already written by this randomizer.
    for (unsigned int k = 0; k < R2R_PLUM00_INT_RULE_COUNT; ++k)
    {
        const auto& rule = g_R2RPlum00IntRules[k];
        if (rule.target != e.target) continue;
        int* p = nullptr;
        if (!R2R_Plum00GetInt(object, rule.dsgIndex, p)) continue;
        const int before = *p;
        if (before <= 0 || before > 120000) continue;
        // This timer may have been initialized late or rewritten by the AI.
        // Only intervene when it is an original or our own previous value.
        if (before != rule.native && (!e.forcedInt[k] || before != e.lastInt[k])) continue;
        float factor = 1.0f;
        if (mode == R2R_STATS_MODE_MIN) factor = rule.minFactor;
        else if (mode == R2R_STATS_MODE_MAX) factor = rule.maxFactor;
        else if (mode == R2R_STATS_MODE_RANDOM)
        {
            const float low = (std::min)(rule.minFactor, rule.maxFactor);
            const float high = (std::max)(rule.minFactor, rule.maxFactor);
            const int lo = static_cast<int>(low * 1000.0f + 0.5f);
            const int hi = static_cast<int>(high * 1000.0f + 0.5f);
            // Int_3 and Int_4 on a Gnak are the LOW and HIGH bounds of
            // Func_RandomInt. Couple their roll so LOW can never exceed HIGH.
            const unsigned int paired = target.pirateHP && rule.dsgIndex == 4u ?
                k - 1u : k;
            factor = R2R_RollRange("Stats.Plum00.Timer", "Plum_00",
                e.key ^ (paired * 0x9E3779B9u) ^
                (g_R2RStatsPlaytestGeneration * 0xB52E53A1u), lo, hi) / 1000.0f;
        }
        int desired = static_cast<int>(rule.native * factor + 0.5f);
        if (desired < 250) desired = 250;
        if (desired > 120000) desired = 120000;
        if (before != desired) *p = desired;
        if (before != desired || e.intMode != mode ||
            e.intGeneration != g_R2RStatsPlaytestGeneration)
            R2R_Plum00Log(mode == R2R_STATS_MODE_NATIVE ? "TIMER_NATIVE" : "TIMER_SET",
                e, rule.name, static_cast<float>(before), static_cast<float>(desired));
        e.capturedInt[k] = true;
        e.forcedInt[k] = mode != R2R_STATS_MODE_NATIVE;
        e.lastInt[k] = desired;
    }
    e.intMode = mode;
    e.intGeneration = g_R2RStatsPlaytestGeneration;

    // MIC_DalleCassee: Float_0 is a LIVE negative falling displacement.
    // Speed up/slow down only a real script-generated descending step.
    // The -10 threshold and exit event are still executed by native scripts.
    if (_stricmp(target.model, "MIC_DalleCassee") == 0)
    {
        float* fall = nullptr;
        if (R2R_Learn10ExtraGetFloat(object, 0u, fall) && fall &&
            std::isfinite(*fall) && *fall <= 0.01f && *fall >= -12.0f)
        {
            const float before = *fall;
            if (e.tileProgressTracked && mode != R2R_STATS_MODE_NATIVE)
            {
                const float step = before - e.tilePrevious;
                if (step < -0.0001f && step > -3.0f)
                {
                    float factor = 1.0f;
                    if (mode == R2R_STATS_MODE_MIN) factor = 0.50f;
                    else if (mode == R2R_STATS_MODE_MAX) factor = 2.0f;
                    else if (mode == R2R_STATS_MODE_RANDOM)
                        factor = R2R_RollRange("Stats.Plum00.DalleFall", "Plum_00",
                            e.key ^ (g_R2RStatsPlaytestGeneration * 0x6E624EB7u),
                            500, 2000) / 1000.0f;
                    const float desired = (std::max)(-12.0f, e.tilePrevious + step * factor);
                    if (std::fabs(desired - before) > 0.0001f) *fall = desired;
                }
            }
            e.tilePrevious = *fall;
            e.tileProgressTracked = true;
        }
    }

    // Gnak pirate HP from FRH_gn_init: 6 for mode Int_2==0, otherwise 9.
    // Never touch Jano/Murfy/Prune HP, some are event messages or mirrored DSG.
    if (target.pirateHP && R2R_Learn10ExtraWritable(sg, sizeof(*sg)))
    {
        const unsigned int hp = sg->ucHitPoints;
        const unsigned int maxHP = sg->ucHitPointsMax;
        if (hp && maxHP)
        {
            if (!e.hpCaptured && (maxHP == 6u || maxHP == 9u))
            {
                e.hpCaptured = true;
                e.originalHPMax = static_cast<unsigned char>(maxHP);
            }
            if (e.hpCaptured)
            {
                const unsigned int nativeHP = e.originalHPMax;
                const bool reinit = e.hpForced && maxHP == nativeHP && hp == nativeHP &&
                    e.forcedHPMax != nativeHP;
                const bool due = reinit || e.hpMode != mode ||
                    e.hpGeneration != g_R2RStatsPlaytestGeneration;
                const bool ours = maxHP == nativeHP ||
                    (e.hpForced && maxHP == e.forcedHPMax);
                if (due && ours)
                {
                    unsigned int desired = nativeHP;
                    if (mode == R2R_STATS_MODE_MIN) desired = 1u;
                    else if (mode == R2R_STATS_MODE_MAX) desired = nativeHP * 2u;
                    else if (mode == R2R_STATS_MODE_RANDOM)
                        desired = static_cast<unsigned int>(R2R_RollRange("Stats.Plum00.GnakHP",
                            "Plum_00", e.key ^ (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u),
                            1, static_cast<int>(nativeHP * 2u)));
                    unsigned int newHP = (hp * desired + maxHP / 2u) / maxHP;
                    if (newHP < 1u) newHP = 1u;
                    if (newHP > desired) newHP = desired;
                    sg->ucHitPoints = static_cast<unsigned char>(newHP);
                    sg->ucHitPointsMax = sg->ucHitPointsMaxMax = static_cast<unsigned char>(desired);
                    e.hpForced = mode != R2R_STATS_MODE_NATIVE;
                    e.forcedHPMax = static_cast<unsigned char>(desired);
                    e.hpMode = mode;
                    e.hpGeneration = g_R2RStatsPlaytestGeneration;
                    R2R_Plum00Log("HP_SET", e, "Gnak MaxHP", static_cast<float>(maxHP),
                        static_cast<float>(desired));
                }
            }
        }
    }
}
static unsigned int g_R2RPlum00Budget = 0;
static void R2R_Plum00Scan(HIE_tdstSuperObject* root, int depth)
{
    if (!root || depth > 64 || !g_R2RPlum00Budget ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    --g_R2RPlum00Budget;
    R2R_Plum00Process(root);
    HIE_tdstSuperObject* child = nullptr;
    LST_M_DynamicForEach(root, child)
    {
        if (!g_R2RPlum00Budget) break;
        if (child) R2R_Plum00Scan(child, depth + 1);
    }
}
static void R2R_Plum00ForgetWorld()
{
    std::memset(g_R2RPlum00Entries, 0, sizeof(g_R2RPlum00Entries));
    g_R2RPlum00World = g_R2RPlum00InactiveWorld = nullptr;
    g_R2RPlum00Frame = 0;
}
static void R2R_Plum00Tick()
{
    if (!GAM_g_stEngineStructure ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Plum_00") != 0 ||
        !GAM_g_p_stDynamicWorld || !*GAM_g_p_stDynamicWorld)
    {
        R2R_Plum00ForgetWorld(); return;
    }
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld ?
        *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RPlum00World || inactive != g_R2RPlum00InactiveWorld)
    {
        g_R2RPlum00World = active; g_R2RPlum00InactiveWorld = inactive;
        FILE* f = nullptr;
        fopen_s(&f, R2R_PLUM00_REPORT, g_R2RPlum00Started ? "a" : "w");
        if (f)
        {
            fprintf(f, "\n%s Plum_00: 22 exact Raymap actors. "
                "Animation on all, plum bounce/spawn/lifetime, Kapoueh chase, "
                "gorilla charge, Gnak HP/attack/timing, Murfy fly speed, "
                "MegaShoot pickup, radar and cinematic visuals. "
                "F6 MIN / F7 MAX / F8 RANDOM / F12 NATIVE.\n", VERSION);
            for (unsigned int i = 0; i < R2R_PLUM00_TARGET_COUNT; ++i)
                fprintf(f, "[PLUM00-TARGET] %u %s / %s / %s | anim=%s hp=%s floats=%u | %s\n",
                    i, g_R2RPlum00Targets[i].family, g_R2RPlum00Targets[i].model,
                    g_R2RPlum00Targets[i].personal,
                    g_R2RPlum00Targets[i].animate ? "YES" : "NATIVE",
                    g_R2RPlum00Targets[i].pirateHP ? "YES" : "NATIVE",
                    g_R2RPlum00Targets[i].floatCount, g_R2RPlum00Targets[i].policy);
            fclose(f); g_R2RPlum00Started = true;
        }
    }
    ++g_R2RPlum00Visit;
    g_R2RPlum00Budget = 4096;
    R2R_Plum00Scan(active, 0);
    if (inactive != active) R2R_Plum00Scan(inactive, 0);
    for (auto& e : g_R2RPlum00Entries)
        if (e.owner && e.visit != g_R2RPlum00Visit) e = R2R_Plum00Entry();
    if ((g_R2RPlum00Frame++ % 300) == 0)
    {
        unsigned int found = 0;
        bool used[R2R_PLUM00_TARGET_COUNT] = {};
        for (const auto& e : g_R2RPlum00Entries)
            if (e.owner && !used[e.target]) { used[e.target] = true; ++found; }
        FILE* f = nullptr;
        fopen_s(&f, R2R_PLUM00_REPORT, "a");
        if (f)
        {
            fprintf(f, "[PLUM00-SUMMARY] found=%u/%u mode=%s generation=%u\n",
                found, R2R_PLUM00_TARGET_COUNT, R2R_StatsModeName(R2R_StatsEffectiveMode()),
                g_R2RStatsPlaytestGeneration);
            for (unsigned int i = 0; i < R2R_PLUM00_TARGET_COUNT; ++i)
                if (!used[i]) fprintf(f, "[PLUM00-MISSING] %s\n", g_R2RPlum00Targets[i].personal);
            fclose(f);
        }
    }
}





// ============================================================
// v0.0.19y.7: General cinematic animation fallback for maps that do not
// have an exact rate module. Maps with existing cinematic controllers keep
// their own tested rules; GLob_10 and GLob_20 now include their previously
// protected cine actors directly. Only actor animation rate is changed.
// ============================================================
static const char* R2R_CINE_GLOBAL_REPORT = "Rayman2Randomizer_CinematicGlobal.txt";
static const unsigned int R2R_CINE_GLOBAL_MAX = 96;
struct R2R_CineGlobalEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    GAM_tdst3dData* data;
    HIE_tdstState* state;
    unsigned int visit;
    uint32_t key;
    unsigned char nativeRate, forcedRate;
    bool forced;
    R2R_StatsPlaytestMode mode;
    uint32_t generation;
};
static R2R_CineGlobalEntry g_R2RCineGlobalEntries[R2R_CINE_GLOBAL_MAX] = {};
static HIE_tdstSuperObject* g_R2RCineGlobalWorld = nullptr;
static HIE_tdstSuperObject* g_R2RCineGlobalInactive = nullptr;
static char g_R2RCineGlobalLevel[64] = {};
static unsigned int g_R2RCineGlobalVisit = 0;
static unsigned int g_R2RCineGlobalBudget = 0;
static bool g_R2RCineGlobalWasActive = false;

static bool R2R_CineGlobalAlreadyOwned(const char* level)
{
    if (!level) return true;
    // These levels already use exact actor animation lists, so stacking an
    // additional writer on the same ucFrameRate would be unsafe.
    static const char* owned[] = {
        "Jail_20", "Learn_10", "Mapmonde", "Learn_30", "Learn_31",
        "Bast_20", "Bast_22", "Learn_60", "Ski_10", "Ski_60",
        "Batam_10", "Chase_10", "Chase_22", "Ly_10", "nego_10",
        "Water_10", "Water_20", "poloc_10", "Rodeo_10",
        "Rodeo_40", "Rodeo_60", "Vulca_10", "Vulca_20",
        "GLob_10", "GLob_20", "Whale_00", "Whale_05", "Whale_10", "Plum_00"
    };
    for (const auto* s : owned) if (_stricmp(level, s) == 0) return true;
    return false;
}
static bool R2R_CineGlobalHasCinemaToken(const char* in)
{
    if (!in || !*in) return false;
    char lower[112] = {};
    unsigned int j = 0;
    while (in[j] && j < sizeof(lower) - 1)
    {
        const char c = in[j];
        lower[j] = (c >= 'A' && c <= 'Z') ? static_cast<char>(c + 32) : c;
        ++j;
    }
    return std::strstr(lower, "_cine") != nullptr ||
        std::strstr(lower, "cinema") != nullptr ||
        std::strstr(lower, "_thx") != nullptr ||
        std::strstr(lower, "gen_cinematique") != nullptr;
}
static void R2R_CineGlobalProcess(HIE_tdstSuperObject* object, const char* level)
{
    if (object == nullptr || object == HIE_M_hGetMainActor()) return;
    HIE_tdstEngineObject* actor = nullptr;
    if (!R2R_Vulca20IdentityActor(object, actor) || !actor || !actor->h3dData) return;
    char family[96] = {}, model[96] = {};
    if (!R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 0), family, sizeof(family)) ||
        !R2R_Vulca20CopyName(R2R_Vulca20NativeName(object, 1), model, sizeof(model))) return;
    if (!R2R_CineGlobalHasCinemaToken(family) &&
        !R2R_CineGlobalHasCinemaToken(model)) return;
    auto* data = actor->h3dData;
    if (!R2R_AddressReadable(reinterpret_cast<uintptr_t>(data), sizeof(*data)) ||
        !R2R_Vulca20RateByteWritable(&data->ucFrameRate)) return;
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_CINE_GLOBAL_MAX; ++i)
    {
        const auto& t = g_R2RCineGlobalEntries[i];
        if (t.owner == object && t.actor == actor && t.data == data)
        { slot = static_cast<int>(i); break; }
        if (!t.owner && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    if (slot < 0) slot = freeSlot;
    if (slot < 0) return;
    auto& e = g_R2RCineGlobalEntries[slot];
    if (e.owner != object || e.actor != actor || e.data != data)
    {
        e = R2R_CineGlobalEntry();
        e.owner = object; e.actor = actor; e.data = data;
        e.nativeRate = data->ucFrameRate;
        e.key = R2R_StatsActorSlotKey(object, actor->hStandardGame, family, model, nullptr);
        e.mode = R2R_STATS_MODE_AUTO;
        e.generation = UINT32_MAX;
    }
    e.visit = g_R2RCineGlobalVisit;
    const auto mode = R2R_StatsEffectiveMode();
    const unsigned int before = data->ucFrameRate;
    if (!e.forced || before != e.forcedRate) e.nativeRate = static_cast<unsigned char>(before);
    unsigned int wanted = e.nativeRate;
    if (mode == R2R_STATS_MODE_MIN) wanted = 12;
    else if (mode == R2R_STATS_MODE_MAX) wanted = 75;
    else if (mode == R2R_STATS_MODE_RANDOM)
        wanted = static_cast<unsigned int>(R2R_RollRange("Stats.CinematicGlobal.Animation",
            level, e.key ^ (g_R2RStatsPlaytestGeneration * 0xDEADBEEFu), 12, 75));
    const bool changed = e.mode != mode || e.generation != g_R2RStatsPlaytestGeneration ||
        e.state != data->h_CurrentState;
    if (mode == R2R_STATS_MODE_NATIVE)
    {
        if (e.forced && before == e.forcedRate) data->ucFrameRate = e.nativeRate;
        e.forced = false;
    }
    else
    {
        if (before != wanted) data->ucFrameRate = static_cast<unsigned char>(wanted);
        e.forced = true; e.forcedRate = static_cast<unsigned char>(wanted);
    }
    if (changed)
    {
        FILE* f = nullptr; fopen_s(&f, R2R_CINE_GLOBAL_REPORT, "a");
        if (f)
        {
            fprintf(f, "[CINE-GLOBAL] level=%s %s/%s actor=%p anim=%u->%u mode=%s\n",
                level, family, model, static_cast<void*>(object), before,
                static_cast<unsigned int>(data->ucFrameRate), R2R_StatsModeName(mode));
            fclose(f);
        }
    }
    e.mode = mode; e.state = data->h_CurrentState;
    e.generation = g_R2RStatsPlaytestGeneration;
}
static void R2R_CineGlobalScan(HIE_tdstSuperObject* root, const char* level, int depth)
{
    if (!root || depth > 64 || !g_R2RCineGlobalBudget ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(*root))) return;
    --g_R2RCineGlobalBudget;
    R2R_CineGlobalProcess(root, level);
    HIE_tdstSuperObject* child = nullptr;
    LST_M_DynamicForEach(root, child)
    {
        if (!g_R2RCineGlobalBudget) break;
        if (child) R2R_CineGlobalScan(child, level, depth + 1);
    }
}
static void R2R_CineGlobalTick()
{
    if (!GAM_g_stEngineStructure || GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        !GAM_g_p_stDynamicWorld || !*GAM_g_p_stDynamicWorld ||
        R2R_CineGlobalAlreadyOwned(GAM_g_stEngineStructure->szLevelName))
    {
        std::memset(g_R2RCineGlobalEntries, 0, sizeof(g_R2RCineGlobalEntries));
        g_R2RCineGlobalWorld = g_R2RCineGlobalInactive = nullptr;
        g_R2RCineGlobalLevel[0] = '\0';
        g_R2RCineGlobalWasActive = false;
        return;
    }
    // Do not run another full actor scan during ordinary unmodified play.
    // A single NATIVE pass restores only the frame-rate bytes we own.
    const bool activeMode = R2R_StatsEffectiveMode() != R2R_STATS_MODE_NATIVE;
    if (!activeMode && !g_R2RCineGlobalWasActive) return;
    const char* level = GAM_g_stEngineStructure->szLevelName;
    auto* active = *GAM_g_p_stDynamicWorld;
    auto* inactive = GAM_g_p_stInactiveDynamicWorld ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    if (active != g_R2RCineGlobalWorld || inactive != g_R2RCineGlobalInactive ||
        _stricmp(g_R2RCineGlobalLevel, level) != 0)
    {
        std::memset(g_R2RCineGlobalEntries, 0, sizeof(g_R2RCineGlobalEntries));
        g_R2RCineGlobalWorld = active; g_R2RCineGlobalInactive = inactive;
        strncpy_s(g_R2RCineGlobalLevel, sizeof(g_R2RCineGlobalLevel), level, _TRUNCATE);
    }
    ++g_R2RCineGlobalVisit;
    g_R2RCineGlobalBudget = 4096;
    R2R_CineGlobalScan(active, level, 0);
    if (inactive != active) R2R_CineGlobalScan(inactive, level, 0);
    for (auto& e : g_R2RCineGlobalEntries)
        if (e.owner && e.visit != g_R2RCineGlobalVisit) e = R2R_CineGlobalEntry();
    g_R2RCineGlobalWasActive = activeMode;
}

