static const unsigned int R2R_MULTI_LEVELS = sizeof(g_R2RMultiLevels)/sizeof(g_R2RMultiLevels[0]);
static int R2R_MultiLevelIndex(const char* level)
{
    if (!level) return -1;
    for (unsigned int k=0;k<R2R_MULTI_LEVELS;++k)
        if (_stricmp(g_R2RMultiLevels[k],level)==0) return (int)k;
    return -1;
}
struct R2R_MultiEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    GAM_tdstStandardGame* standard;
    GAM_tdst3dData* data;
    HIE_tdstState* state;
    unsigned int target, visit, seenFrames;
    uint32_t key;
    unsigned char nativeRate, lastRate;
    bool rateForced;
    R2R_StatsPlaytestMode rateMode;
    uint32_t rateGen;
    float lastField[12];
    bool forcedField[12];
    bool hpSaved, hpForced;
    unsigned char hpNative, hpLast;
    R2R_StatsPlaytestMode hpMode;
    uint32_t hpGen;
};
static const unsigned int R2R_MULTI_MAX_ENTRIES=512u;
static R2R_MultiEntry g_R2RMultiEntries[R2R_MULTI_MAX_ENTRIES] = {};
static unsigned int g_R2RMultiVisit = 0, g_R2RMultiBudget = 0, g_R2RMultiFrames = 0;
static HIE_tdstSuperObject* g_R2RMultiWorld = nullptr;
static HIE_tdstSuperObject* g_R2RMultiInactive = nullptr;
static int g_R2RMultiCurrentLevel = -1;
static bool g_R2RMultiReportStarted[R2R_MULTI_LEVELS] = {};
static void R2R_MultiLog(const char* tag, unsigned int target, const char* field, float from, float to)
{
    if (g_R2RMultiCurrentLevel<0 || g_R2RMultiCurrentLevel >= (int)R2R_MULTI_LEVELS) return;
    char fn[128]={};
    sprintf_s(fn,sizeof(fn),"Rayman2Randomizer_%sStats.txt",g_R2RMultiLevels[g_R2RMultiCurrentLevel]);
    FILE* fp = nullptr; fopen_s(&fp,fn,"a"); if (!fp) return;
    fprintf(fp,"[MULTI] %s %s %s/%s/%s %s %.4f -> %.4f mode=%s gen=%u\n",
        tag,g_R2RMultiTargets[target].level,g_R2RMultiTargets[target].family,
        g_R2RMultiTargets[target].model,g_R2RMultiTargets[target].personal,field,
        from,to,R2R_StatsModeName(R2R_StatsEffectiveMode()),g_R2RStatsPlaytestGeneration);
    fclose(fp);
}
static int R2R_MultiIdentity(HIE_tdstSuperObject* object, HIE_tdstEngineObject*& actor)
{
    actor=nullptr;
    if (g_R2RMultiCurrentLevel < 0 || !R2R_Vulca20IdentityActor(object,actor)) return -1;
    char family[96]={},model[96]={},personal[128]={};
    if (!R2R_Vulca20CopyName(R2R_Vulca20NativeName(object,0),family,sizeof(family))) return -1;
    bool candidate=false;
    for (unsigned int k=0;k<R2R_MULTI_ACTORS;++k)
        if (_stricmp(g_R2RMultiTargets[k].level,g_R2RMultiLevels[g_R2RMultiCurrentLevel])==0 &&
            _stricmp(g_R2RMultiTargets[k].family,family)==0) {candidate=true;break;}
    if (!candidate ||
        !R2R_Vulca20CopyName(R2R_Vulca20NativeName(object,1),model,sizeof(model)) ||
        !R2R_Vulca20CopyName(R2R_Vulca20NativeName(object,2),personal,sizeof(personal))) return -1;
    for (unsigned int k=0;k<R2R_MULTI_ACTORS;++k)
    {
        const auto& t=g_R2RMultiTargets[k];
        if (_stricmp(t.level,g_R2RMultiLevels[g_R2RMultiCurrentLevel])==0 &&
            _stricmp(t.family,family)==0 && _stricmp(t.model,model)==0 &&
            _stricmp(t.personal,personal)==0) return (int)k;
    }
    return -1;
}
static void R2R_MultiProcess(HIE_tdstSuperObject* object)
{
    HIE_tdstEngineObject* actor=nullptr;
    const int index=R2R_MultiIdentity(object,actor);
    // User exclusion: Cask_30/porte/OLD_porte/PorteDebut is NEVER randomized.
    // Keep its target slot in the table to preserve every other rule index.
    if (index == 135) return;
    if (index<0 || !actor || !actor->hStandardGame ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame),sizeof(GAM_tdstStandardGame)))return;
    auto* sg=actor->hStandardGame;
    auto* data=actor->h3dData;
    const bool dataValid=data && R2R_AddressReadable(reinterpret_cast<uintptr_t>(data),sizeof(GAM_tdst3dData)) &&
        R2R_Vulca20RateByteWritable(&data->ucFrameRate);
    int found=-1,empty=-1;
    for (unsigned int i=0;i<R2R_MULTI_MAX_ENTRIES;++i)
    {
        const auto& o=g_R2RMultiEntries[i];
        if (o.owner==object && o.actor==actor && o.standard==sg && o.target==(unsigned int)index){found=(int)i;break;}
        if (!o.owner && empty<0)empty=(int)i;
    }
    if (found<0)found=empty;
    if (found<0)return;
    auto& e=g_R2RMultiEntries[found];
    if (e.owner!=object)
    {
        e=R2R_MultiEntry();
        e.owner=object;e.actor=actor;e.standard=sg;e.data=data;e.target=(unsigned int)index;
        const auto& t=g_R2RMultiTargets[index];
        e.key=R2R_StatsActorSlotKey(object,sg,t.family,t.model,t.personal);
        e.rateMode=e.hpMode=R2R_STATS_MODE_AUTO;
        e.rateGen=e.hpGen=UINT32_MAX;
        if(dataValid)e.nativeRate=data->ucFrameRate;
        R2R_MultiLog("TRACK",index,"actor",0.0f,0.0f);
    }
    e.visit=g_R2RMultiVisit;
    if (e.seenFrames<10000u)++e.seenFrames;
    const auto mode=R2R_StatsEffectiveMode();
    const auto& t=g_R2RMultiTargets[index];
    // Animation on every selected actor: gates, cinematic characters, projectiles,
    // platform generators, friendly NPCs. Never rewrite a state or action ID.
    if(dataValid)
    {
        const unsigned int before=data->ucFrameRate;
        const bool stateChanged=e.state!=data->h_CurrentState;
        if(!e.rateForced || before!=e.lastRate)
            if(before>0u)e.nativeRate=(unsigned char)before;
        unsigned int desired=e.nativeRate;
        if(mode==R2R_STATS_MODE_MIN)desired=6u;
        else if(mode==R2R_STATS_MODE_MAX)desired=115u;
        else if(mode==R2R_STATS_MODE_RANDOM)
            desired=(unsigned int)R2R_RollRange("Stats.Multi.Anim",t.level,
                e.key ^ (g_R2RStatsPlaytestGeneration*0x9E3779B9u),6,115);
        if(desired>255u)desired=255u;
        if(before!=desired && desired>0u)data->ucFrameRate=(unsigned char)desired;
        if((before!=desired && (e.rateMode!=mode || stateChanged || e.rateGen!=g_R2RStatsPlaytestGeneration)) ||
            (!e.rateForced && e.rateMode!=mode))
            R2R_MultiLog("ANIM",index,"rate",(float)before,(float)desired);
        e.lastRate=(unsigned char)desired;e.rateForced=mode!=R2R_STATS_MODE_NATIVE;
        e.rateMode=mode;e.rateGen=g_R2RStatsPlaytestGeneration;
        e.state=data->h_CurrentState;
    }
    // Only apply fields whose value still matches native Raymap or our previous
    // write. This prevents overwriting a script-owned timestamp or accumulator.
    for(unsigned int j=0;j<t.ruleCount;++j)
    {
        const unsigned int ruleIndex=(unsigned int)t.firstRule+j;
        const auto& r=g_R2RMultiRules[ruleIndex];
        if(j>=12)break;
        const bool integer=r.kind=='I';
        float* f=nullptr;int* ip=nullptr;
        if(integer){if(!R2R_Plum00GetInt(object,r.index,ip))continue;}
        else {if(!R2R_Learn10ExtraGetFloat(object,r.index,f))continue;}
        const float before=integer?(float)*ip:*f;
        if(!std::isfinite(before) || before<=0.0f)continue;
        const float tol=integer?0.51f:(std::max)(0.002f,r.native*.015f);
        const bool nativeValue=std::fabs(before-r.native)<=tol;
        const bool ownValue=e.forcedField[j] && std::fabs(before-e.lastField[j])<=tol;
        if(!nativeValue && !ownValue)continue;
        float factor=1.0f;
        if(mode==R2R_STATS_MODE_MIN)factor=r.minFactor;
        else if(mode==R2R_STATS_MODE_MAX)factor=r.maxFactor;
        else if(mode==R2R_STATS_MODE_RANDOM)
        {
            const int lo=(int)((std::min)(r.minFactor,r.maxFactor)*1000.0f+0.5f);
            const int hi=(int)((std::max)(r.minFactor,r.maxFactor)*1000.0f+0.5f);
            factor=R2R_RollRange("Stats.Multi.DSG",t.level,
                e.key ^ ((unsigned int)r.rollGroup*0x85EBCA6Bu) ^
                (g_R2RStatsPlaytestGeneration*0xC2B2AE35u),lo,hi)/1000.0f;
        }
        float desired=r.native*factor;
        if(integer)
        {
            desired=std::floor(desired+0.5f);
            if(desired<1.0f)desired=1.0f;
            if(desired>120000.0f)desired=120000.0f;
            if((int)desired!=*ip)*ip=(int)desired;
        }
        else
        {
            if(desired<0.00001f || desired>10000.0f)continue;
            if(std::fabs(before-desired)>0.0001f)*f=desired;
        }
        if(std::fabs(before-desired)>tol && (!e.forcedField[j] || !ownValue))
            R2R_MultiLog(integer?"TIMER":"DSG",index,r.label,before,desired);
        e.lastField[j]=desired;e.forcedField[j]=mode!=R2R_STATS_MODE_NATIVE;
    }
    // Only actual pirates / gorilla enemies. Cinematics often use maxHP as
    // a command mailbox, so the model/family allowlist below is mandatory.
    if(t.combatHP && e.seenFrames>1u && R2R_Learn10ExtraWritable(sg,sizeof(*sg)))
    {
        const unsigned int hp=sg->ucHitPoints, maxHP=sg->ucHitPointsMax;
        if(hp>0u && maxHP>=2u && maxHP<=30u && hp<=maxHP)
        {
            if(!e.hpSaved && (!e.hpForced || maxHP!=e.hpLast))
            {e.hpSaved=true;e.hpNative=(unsigned char)maxHP;}
            if(e.hpSaved)
            {
                const unsigned int original=e.hpNative;
                const bool ours=e.hpForced && maxHP==e.hpLast;
                if(!ours && maxHP!=original) {e.hpSaved=false;e.hpForced=false;}
                else if(!ours || e.hpMode!=mode || e.hpGen!=g_R2RStatsPlaytestGeneration)
                {
                    unsigned int desired=original;
                    if(mode==R2R_STATS_MODE_MIN)desired=1u;
                    else if(mode==R2R_STATS_MODE_MAX)desired=(std::min)(original*2u,40u);
                    else if(mode==R2R_STATS_MODE_RANDOM)
                        desired=(unsigned int)R2R_RollRange("Stats.Multi.HP",t.level,
                            e.key ^ (g_R2RStatsPlaytestGeneration*0x27D4EB2Du),1,(int)(std::min)(original*2u,40u));
                    unsigned int scaled=(hp*desired+maxHP/2u)/maxHP;
                    if(scaled<1u)scaled=1u;
                    if(scaled>desired)scaled=desired;
                    sg->ucHitPoints=(unsigned char)scaled;
                    sg->ucHitPointsMax=sg->ucHitPointsMaxMax=(unsigned char)desired;
                    e.hpLast=(unsigned char)desired;e.hpForced=mode!=R2R_STATS_MODE_NATIVE;
                    e.hpMode=mode;e.hpGen=g_R2RStatsPlaytestGeneration;
                    R2R_MultiLog("HP",index,"combat hp",(float)maxHP,(float)desired);
                }
            }
        }
    }
}
static void R2R_MultiScan(HIE_tdstSuperObject* root,int depth)
{
    if(!root || depth>64 || !g_R2RMultiBudget ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root),sizeof(HIE_tdstSuperObject)))return;
    --g_R2RMultiBudget;
    R2R_MultiProcess(root);
    HIE_tdstSuperObject* child=nullptr;
    LST_M_DynamicForEach(root,child)
    {
        if(!g_R2RMultiBudget)break;
        if(child)R2R_MultiScan(child,depth+1);
    }
}
static void R2R_MultiForget()
{
    std::memset(g_R2RMultiEntries,0,sizeof(g_R2RMultiEntries));
    g_R2RMultiWorld=g_R2RMultiInactive=nullptr;g_R2RMultiFrames=0;
}
static void R2R_MultiTick()
{
    const int level=(GAM_g_stEngineStructure && GAM_g_stEngineStructure->eEngineMode==E_EM_ModePlaying) ?
        R2R_MultiLevelIndex(GAM_g_stEngineStructure->szLevelName):-1;
    if(level<0 || !GAM_g_p_stDynamicWorld || !*GAM_g_p_stDynamicWorld)
    {
        if(g_R2RMultiCurrentLevel>=0) R2R_MultiForget();
        g_R2RMultiCurrentLevel=-1; return;
    }
    HIE_tdstSuperObject* active=*GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive=GAM_g_p_stInactiveDynamicWorld?*GAM_g_p_stInactiveDynamicWorld:nullptr;
    if(level!=g_R2RMultiCurrentLevel || active!=g_R2RMultiWorld || inactive!=g_R2RMultiInactive)
    {
        R2R_MultiForget();
        g_R2RMultiCurrentLevel=level;
        g_R2RMultiWorld=active;g_R2RMultiInactive=inactive;
        char fn[128]={};
        sprintf_s(fn,sizeof(fn),"Rayman2Randomizer_%sStats.txt",g_R2RMultiLevels[level]);
        FILE* fp=nullptr;
        fopen_s(&fp,fn,g_R2RMultiReportStarted[level]?"a":"w");
        if(fp)
        {
            unsigned int total=0,fields=0;
            for(unsigned int k=0;k<R2R_MULTI_ACTORS;++k)
                if(k != 135u && _stricmp(g_R2RMultiTargets[k].level,g_R2RMultiLevels[level])==0)
                {++total; fields+=g_R2RMultiTargets[k].ruleCount;}
            fprintf(fp,"\n%s [MULTI] %s exact actors=%u scripted-fields=%u F3 cycles 35 levels. "
                "F6 MIN F7 MAX F8 RANDOM F12 NATIVE.\n",VERSION,g_R2RMultiLevels[level],total,fields);
            fclose(fp);
            g_R2RMultiReportStarted[level]=true;
        }
    }
    ++g_R2RMultiVisit;
    g_R2RMultiBudget=4096u;
    R2R_MultiScan(active,0);
    if(inactive!=active)R2R_MultiScan(inactive,0);
    for(auto& e:g_R2RMultiEntries)
        if(e.owner && e.visit!=g_R2RMultiVisit)e=R2R_MultiEntry();
    if((g_R2RMultiFrames++%300u)==0u)
    {
        unsigned int found=0,total=0;
        for(const auto& e:g_R2RMultiEntries)if(e.owner)++found;
        for(unsigned int k=0;k<R2R_MULTI_ACTORS;++k)
            if(k != 135u && _stricmp(g_R2RMultiTargets[k].level,g_R2RMultiLevels[level])==0)++total;
        char fn[128]={};
        sprintf_s(fn,sizeof(fn),"Rayman2Randomizer_%sStats.txt",g_R2RMultiLevels[level]);
        FILE* fp=nullptr;fopen_s(&fp,fn,"a");
        if(fp){fprintf(fp,"[MULTI-SUMMARY] active=%u exported=%u mode=%s gen=%u\n",
            found,total,R2R_StatsModeName(R2R_StatsEffectiveMode()),g_R2RStatsPlaytestGeneration);
            fclose(fp);}
    }
}

static void R2R_StatsProcessActor(
    HIE_tdstSuperObject* superObject,
    HIE_tdstSuperObject* mainActorSO,
    const char* levelName
)
{
    if (
        superObject == nullptr ||
        superObject->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(superObject),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return;
    }

    HIE_tdstEngineObject* actor =
        HIE_M_hSuperObjectGetActor(superObject);

    if (
        actor == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actor),
            sizeof(HIE_tdstEngineObject)
        ) ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actor->hStandardGame),
            sizeof(GAM_tdstStandardGame)
        )
        )
    {
        return;
    }

    if (R2R_StatsWasSeen(superObject, actor))
        return;

    GAM_tdstStandardGame* standardGame = actor->hStandardGame;
    R2R_StatsSeenEntry* entry =
        R2R_StatsRemember(superObject, actor, standardGame);

    if (entry == nullptr)
        return;

    if (superObject == mainActorSO)
    {
        ++g_R2RStatsSkippedRayman;
        return;
    }

    // y.13: exact actor triples in the twenty exported levels use the
    // unified per-level randomizer. No competing generic HP/animation writer.
    if (levelName != nullptr && R2R_MultiLevelIndex(levelName) >= 0)
    {
        HIE_tdstEngineObject* multiActor = nullptr;
        if (R2R_MultiIdentity(superObject, multiActor) >= 0)
        {
            ++g_R2RStatsSkippedRule;
            return;
        }
    }

    // Plum_00 all 22 exact Raymap actors are owned by their new module.
    if (levelName != nullptr && _stricmp(levelName, "Plum_00") == 0)
    {
        HIE_tdstEngineObject* plumActor = nullptr;
        if (R2R_Plum00Identity(superObject, plumActor) >= 0)
        {
            ++g_R2RStatsSkippedRule;
            return;
        }
    }

    // Whale_10 has exact actor-specific animation / movement rules; don't
    // re-randomize these actors through the generic stats pass.
    if (levelName != nullptr && _stricmp(levelName, "Whale_10") == 0)
    {
        HIE_tdstEngineObject* whale10Actor = nullptr;
        if (R2R_Whale10Identity(superObject, whale10Actor) >= 0)
        {
            ++g_R2RStatsSkippedRule;
            return;
        }
    }

    // Whale_05 scripted actors have their own animation, movement and timer
    // randomizer. Never overlay generic stat/animation writes on these actors.
    if (levelName != nullptr && _stricmp(levelName, "Whale_05") == 0)
    {
        HIE_tdstEngineObject* whale05Actor = nullptr;
        if (R2R_Whale05Identity(superObject, whale05Actor) >= 0)
        {
            ++g_R2RStatsSkippedRule;
            return;
        }
    }

    // Whale_00 exact exported enemies, traps and dynamic barrel templates
    // already have HP/animation/selected DSG managed by R2R_Whale00Tick().
    // Do not layer the generic stats or animation writer on these actors.
    if (levelName != nullptr && _stricmp(levelName, "Whale_00") == 0)
    {
        HIE_tdstEngineObject* whaleActor = nullptr;
        if (R2R_Whale00Identity(superObject, whaleActor) >= 0)
        {
            ++g_R2RStatsSkippedRule;
            return;
        }
    }

    // GLob_20 owns only approved per-actor stats; exact NPC/story actors
    // are explicitly protected from generic speed, HP and animation edits.
    if (levelName != nullptr && _stricmp(levelName, "GLob_20") == 0)
    {
        HIE_tdstEngineObject* glob20Actor = nullptr;
        if (R2R_Glob20Identity(superObject, glob20Actor) >= 0)
        {
            ++g_R2RStatsSkippedRule;
            return;
        }
    }

    // GLob_10 exact Raymap export owns HP, selected DSG fields and safe visuals.
    // Skip generic HP/movement for all 13, including story and navigation actors.
    if (levelName != nullptr && _stricmp(levelName, "GLob_10") == 0)
    {
        HIE_tdstEngineObject* glob10Actor = nullptr;
        if (R2R_Glob10Identity(superObject, glob10Actor) >= 0)
        {
            ++g_R2RStatsSkippedRule;
            return;
        }
    }

    // GLob_30 Tronc spider is owned by the exact HP/animation module.
    // Never stack generic HP or mechanics movement changes on its graph AI.
    if (levelName != nullptr && _stricmp(levelName, "GLob_30") == 0)
    {
        HIE_tdstEngineObject* globSpider = nullptr;
        if (R2R_Glob30Identity(superObject, globSpider))
        {
            ++g_R2RStatsSkippedRule;
            return;
        }
    }

    // Vulca_20 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Vulca_20") == 0 && R2R_Vulca20ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule;return;
    }

    // Vulca_10 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Vulca_10") == 0 && R2R_Vulca10ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule;return;
    }

    // Rodeo_60 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Rodeo_60") == 0 &&
        R2R_Rodeo60ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule; return;
    }

    // Rodeo_40 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Rodeo_40") == 0 &&
        R2R_Rodeo40ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule; return;
    }

    // Rodeo_10 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Rodeo_10") == 0 &&
        R2R_Rodeo10ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule; return;
    }

    // poloc_10 exact test stays independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "poloc_10") == 0 &&
        R2R_Poloc10ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule; return;
    }

    // Water_20 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Water_20") == 0 &&
        R2R_Water20ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule; return;
    }

    // Water_10 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Water_10") == 0 &&
        R2R_Water10ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule; return;
    }

    // nego_10 cinematic tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "nego_10") == 0 &&
        R2R_Nego10ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule; return;
    }

    // Ly_10 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Ly_10") == 0 &&
        R2R_Ly10ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule; return;
    }

    // Chase_22 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Chase_22") == 0 &&
        R2R_Chase22ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Chase_10 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Chase_10") == 0 &&
        R2R_Chase10ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Batam_10 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Batam_10") == 0 &&
        R2R_Batam10ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Ski_60 tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Ski_60") == 0 &&
        R2R_Ski60ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Ski_10 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Ski_10") == 0 &&
        R2R_Ski10ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Learn_60 exact tests stay independent of generic Stats and movement.
    if (levelName != nullptr && _stricmp(levelName, "Learn_60") == 0 &&
        R2R_Learn60ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Check Bast_22 protected identities before generic native name queries.
    // Temporary Rayman helpers also retain native Stats during the handoff.
    if (levelName != nullptr && _stricmp(levelName, "Bast_22") == 0 &&
        R2R_Bast22ProtectFromStats(superObject))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    const char* familyName = HIE_fn_szGetObjectFamilyName(superObject);
    const char* modelName = HIE_fn_szGetObjectModelName(superObject);
    const char* personalName = HIE_fn_szGetObjectPersonalName(superObject);

    // Cinematic HP/MaxHP may encode event commands (not health). Never let
    // the generic combat randomizer touch unlisted cinematic controllers.
    // Their animation alone is controlled by the global cinematic fallback.
    if (R2R_CineGlobalHasCinemaToken(familyName) ||
        R2R_CineGlobalHasCinemaToken(modelName))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Keep the seven Jail_20 test actors free of HP/mechanics randomization.
    if (levelName != nullptr && _stricmp(levelName, "Jail_20") == 0 &&
        R2R_JailRateIsExactTarget(familyName, modelName, personalName))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Learn_10 exact actors are handled only by the validated animation /
    // selective-extra modules. This also protects cinematic HP-as-command
    // channels and prevents generic movement from stacking with exact DT scaling.
    if (levelName != nullptr && _stricmp(levelName, "Learn_10") == 0 &&
        (R2R_LearnRateFindTarget(familyName, modelName, personalName) >= 0 ||
            R2R_Learn10ExtraFindTarget(familyName, modelName, personalName) >= 0))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Mapmonde targets are modified only by the isolated animation-rate probe.
    if (levelName != nullptr && _stricmp(levelName, "Mapmonde") == 0 &&
        R2R_MapMondeRateFindTarget(familyName, modelName, personalName) >= 0)
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Isolate Learn_30 animation testing from HP and mechanics randomization.
    if (levelName != nullptr && _stricmp(levelName, "Learn_30") == 0 &&
        R2R_Learn30RateFindTarget(familyName, modelName, personalName) >= 0)
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Isolate all validated Learn_31 actors from generic HP/mechanics changes.
    // Exact selective modules own the chosen fields; both pirates remain read-only.
    if (levelName != nullptr && _stricmp(levelName, "Learn_31") == 0 &&
        (R2R_Learn31RateFindTarget(familyName, modelName, personalName) >= 0 ||
            R2R_Learn31ExtraFindTarget(familyName, modelName, personalName) >= 0))
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    // Isolate all exact Bast_20 test actors from generic HP and mechanics changes.
    if (levelName != nullptr && _stricmp(levelName, "Bast_20") == 0 &&
        R2R_Bast20RateFindTarget(familyName, modelName, personalName) >= 0)
    {
        ++g_R2RStatsSkippedRule;
        return;
    }

    const uint32_t slotKey =
        R2R_StatsActorSlotKey(
            superObject,
            standardGame,
            familyName,
            modelName,
            personalName
        );

    const unsigned int hp = standardGame->ucHitPoints;
    const unsigned int hpMax = standardGame->ucHitPointsMax;
    const unsigned int hpMaxMax = standardGame->ucHitPointsMaxMax;

    const bool hpEligible =
        hp != 0 &&
        hp == hpMax &&
        hpMax == hpMaxMax &&
        hpMax <= 20;

    const bool isPirateSbire = R2R_StatsIsPirateSbire(familyName);

    // 16j safety rollback:
    // - normal movement randomization is again restricted to persistent,
    //   HP-shaped actors (the conservative gate that was stable before 16i);
    // - pirate_sbire is admitted only as a READ-ONLY diagnostic exception;
    // - short-lived generated actors (personal IDs 65536+) are excluded.
    const bool movementCandidate =
        actor->hBrain != nullptr &&
        actor->hDynam != nullptr &&
        R2R_StatsIsPersistentPersonal(standardGame, personalName) &&
        (hpEligible || isPirateSbire);

    if (movementCandidate)
    {
        if (
            R2R_StatsAssignMovementProfile(
                entry,
                actor,
                levelName,
                slotKey
            )
            )
        {
            if (isPirateSbire)
            {
                entry->pirateReadOnlyDiagnostic = true;
                entry->imposeSpeedDiagnostic = false;
            }
        }
    }

    // Pirates remain untouched by HP and generic movement mechanics.
    // Menu animation tests are separate from normal gameplay Stats.
    if (isPirateSbire)
    {
        if (entry->movementProfileAssigned)
        {
            R2R_StatsLogMovementOnly(
                superObject,
                standardGame,
                familyName,
                modelName,
                personalName,
                slotKey,
                "PIRATE READ-ONLY: HP untouched after Astro_00 crash",
                entry
            );
        }
        else
        {
            ++g_R2RStatsSkippedRule;
        }
        return;
    }

    if (hpEligible)
    {
        int upper = (int)hpMax * 3;
        if (upper < 2)
            upper = 2;
        if (upper > 12)
            upper = 12;

        unsigned int newHP = hp;
        const R2R_StatsPlaytestMode mode = R2R_StatsEffectiveMode();

        if (mode == R2R_STATS_MODE_MIN)
        {
            newHP = 1u;
        }
        else if (mode == R2R_STATS_MODE_MAX)
        {
            newHP = (unsigned int)upper;
        }
        else if (mode == R2R_STATS_MODE_RANDOM)
        {
            newHP =
                (unsigned int)R2R_RollRange(
                    "Stats.HP",
                    levelName != nullptr ? levelName : "(unknown)",
                    slotKey ^
                    (g_R2RStatsPlaytestGeneration * 0xC2B2AE35u),
                    1,
                    upper
                );
        }
        else
        {
            ++g_R2RStatsSkippedRule;
            return;
        }

        standardGame->ucHitPoints = (unsigned char)newHP;
        standardGame->ucHitPointsMax = (unsigned char)newHP;
        standardGame->ucHitPointsMaxMax = (unsigned char)newHP;
        entry->randomized = true;

        ++g_R2RStatsRandomizedCount;

        R2R_StatsLogActor(
            superObject,
            standardGame,
            familyName,
            modelName,
            personalName,
            slotKey,
            hp,
            newHP,
            entry
        );
        return;
    }

    if (entry->movementProfileAssigned)
    {
        const char* hpReason = "HP-filter";
        if (hp == 0)
            hpReason = "HP=0";
        else if (hp != hpMax || hpMax != hpMaxMax)
            hpReason = "HP/Max/MaxMax mismatch";
        else if (hpMax > 20)
            hpReason = "MaxHP>20";

        R2R_StatsLogMovementOnly(
            superObject,
            standardGame,
            familyName,
            modelName,
            personalName,
            slotKey,
            hpReason,
            entry
        );
        return;
    }

    ++g_R2RStatsSkippedRule;
}

static void R2R_StatsScanTreeRecursive(
    HIE_tdstSuperObject* root,
    HIE_tdstSuperObject* mainActorSO,
    const char* levelName,
    int depth
)
{
    if (
        root == nullptr ||
        depth > 64 ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(root),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return;
    }

    HIE_tdstSuperObject* object = nullptr;

    LST_M_DynamicForEach(root, object)
    {
        if (object == nullptr)
            continue;

        R2R_StatsProcessActor(
            object,
            mainActorSO,
            levelName
        );

        R2R_StatsScanTreeRecursive(
            object,
            mainActorSO,
            levelName,
            depth + 1
        );
    }
}

static void R2R_StatsAppendScanSummary()
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_STATS_REPORT, "a");
    if (f == nullptr)
        return;

    fprintf(
        f,
        "\nSCAN SUMMARY: seen=%u hpRandomized=%u movementProfiles=%u movementActivated=%u movementOnly=%u skippedRayman=%u fullySkippedRule=%u\n",
        g_R2RStatsSeenCount,
        g_R2RStatsRandomizedCount,
        g_R2RStatsMovementProfileCount,
        g_R2RStatsMovementObservedCount,
        g_R2RStatsMovementOnlyCount,
        g_R2RStatsSkippedRayman,
        g_R2RStatsSkippedRule
    );

    fclose(f);
}


static void R2R_StatsAppendPirateReadOnlyDiagnostics()
{
    FILE* f = nullptr;
    bool wroteHeader = false;

    for (unsigned int i = 0; i < g_R2RStatsSeenCount; ++i)
    {
        R2R_StatsSeenEntry& entry = g_R2RStatsSeen[i];

        if (
            !entry.pirateReadOnlyDiagnostic ||
            entry.superObject == nullptr ||
            entry.actor == nullptr
            )
        {
            continue;
        }

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject),
                sizeof(HIE_tdstSuperObject)
            ) ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.actor),
                sizeof(HIE_tdstEngineObject)
            )
            )
        {
            continue;
        }

        const char* familyName = HIE_fn_szGetObjectFamilyName(entry.superObject);
        const char* modelName = HIE_fn_szGetObjectModelName(entry.superObject);
        const char* personalName = HIE_fn_szGetObjectPersonalName(entry.superObject);

        auto ensureFile = [&]() -> bool
            {
                if (f != nullptr)
                    return true;

                fopen_s(&f, R2R_STATS_REPORT, "a");
                if (f == nullptr)
                    return false;

                if (!wroteHeader)
                {
                    fprintf(
                        f,
                        "\nPIRATE READ-ONLY DIAGNOSTIC\n"
                        "------------------------------------------------------------\n"
                    );
                    wroteHeader = true;
                }

                return true;
            };

        // Log the first BaseMechanics route observation.  No movement value has
        // been modified: diagPre/diagPost are read-only snapshots.
        if (
            entry.movementHookHits != 0 &&
            !entry.pirateBaseSnapshotLogged
            )
        {
            if (!ensureFile())
                return;

            fprintf(
                f,
                "[PIRATE-BASE] %s / %s / %s baseHits=%u translationHits=%u\n",
                familyName != nullptr ? familyName : "(null)",
                modelName != nullptr ? modelName : "(null)",
                personalName != nullptr ? personalName : "(null)",
                entry.movementHookHits,
                entry.translationHookHits
            );

            for (int field = 0; field < R2R_DIAG_FIELD_COUNT; ++field)
            {
                if (
                    entry.diagPreHits[field] == 0 &&
                    entry.diagPostHits[field] == 0
                    )
                {
                    continue;
                }

                fprintf(
                    f,
                    "    %-25s pre[hits=%u min=%.5f max=%.5f] post[hits=%u min=%.5f max=%.5f]\n",
                    g_R2RStatsDiagFieldNames[field],
                    entry.diagPreHits[field],
                    entry.diagPreHits[field] ? entry.diagPreMin[field] : 0.0f,
                    entry.diagPreHits[field] ? entry.diagPreMax[field] : 0.0f,
                    entry.diagPostHits[field],
                    entry.diagPostHits[field] ? entry.diagPostMin[field] : 0.0f,
                    entry.diagPostHits[field] ? entry.diagPostMax[field] : 0.0f
                );
            }

            entry.pirateBaseSnapshotLogged = true;
        }

        if (
            entry.translationHookHits != 0 &&
            entry.firstTranslationCaptured &&
            !entry.pirateTranslationSnapshotLogged
            )
        {
            if (!ensureFile())
                return;

            fprintf(
                f,
                "[PIRATE-INIT-TRANSLATION] %s / %s / %s hits=%u first=(%.5f %.5f %.5f) READ-ONLY\n",
                familyName != nullptr ? familyName : "(null)",
                modelName != nullptr ? modelName : "(null)",
                personalName != nullptr ? personalName : "(null)",
                entry.translationHookHits,
                entry.firstTranslationBefore.x,
                entry.firstTranslationBefore.y,
                entry.firstTranslationBefore.z
            );

            entry.pirateTranslationSnapshotLogged = true;
        }

        // Watch the actual HIE animation state.  This is intentionally separate
        // from DNM::stSpeedAnim: state->cSpeedAnim is a different engine value
        // and is a strong candidate for root-motion-style pirate locomotion.
        HIE_tdstState* currentState = nullptr;
        int currentSpeedAnim = 0;
        unsigned int repeatAnim = 0;
        void* animPtr = nullptr;

        if (
            entry.actor->h3dData != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.actor->h3dData),
                sizeof(GAM_tdst3dData)
            )
            )
        {
            currentState = entry.actor->h3dData->h_CurrentState;

            if (
                currentState != nullptr &&
                R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(currentState),
                    sizeof(HIE_tdstState)
                )
                )
            {
                currentSpeedAnim = (int)currentState->cSpeedAnim;
                repeatAnim = (unsigned int)currentState->ucRepeatAnimation;
                animPtr = currentState->p_stAnim;

                if (
                    !entry.pirateStateInitialized ||
                    entry.pirateLastState != currentState ||
                    entry.pirateLastStateSpeedAnim != currentSpeedAnim
                    )
                {
                    if (!ensureFile())
                        return;

                    fprintf(
                        f,
                        "[PIRATE-STATE] %s / %s / %s state=%p anim=%p cSpeedAnim=%d repeat=%u\n",
                        familyName != nullptr ? familyName : "(null)",
                        modelName != nullptr ? modelName : "(null)",
                        personalName != nullptr ? personalName : "(null)",
                        currentState,
                        animPtr,
                        currentSpeedAnim,
                        repeatAnim
                    );

                    entry.pirateStateInitialized = true;
                    entry.pirateLastState = currentState;
                    entry.pirateLastStateSpeedAnim = currentSpeedAnim;
                }
            }
        }

        // Record the first observed real world-space movement and the animation
        // state active at that moment.  This works even if no mechanics hook fires.
        if (
            entry.superObject->p_stGlobalMatrix != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject->p_stGlobalMatrix),
                sizeof(POS_tdstCompletePosition)
            )
            )
        {
            const MTH3D_tdstVector currentPos =
                entry.superObject->p_stGlobalMatrix->stPos;

            if (R2R_StatsVectorSane(currentPos))
            {
                if (!entry.piratePositionInitialized)
                {
                    entry.pirateLastWorldPosition = currentPos;
                    entry.piratePositionInitialized = true;
                }
                else
                {
                    const float dx = currentPos.x - entry.pirateLastWorldPosition.x;
                    const float dy = currentPos.y - entry.pirateLastWorldPosition.y;
                    const float dz = currentPos.z - entry.pirateLastWorldPosition.z;
                    const float step = std::sqrt(dx * dx + dy * dy + dz * dz);

                    if (
                        !entry.pirateFirstWorldMoveLogged &&
                        std::isfinite(step) &&
                        step > 0.0001f &&
                        step < 1000.0f
                        )
                    {
                        if (!ensureFile())
                            return;

                        fprintf(
                            f,
                            "[PIRATE-FIRST-WORLD-MOVE] %s / %s / %s step=%.6f d=(%.6f %.6f %.6f) "
                            "baseHits=%u translationHits=%u state=%p cSpeedAnim=%d\n",
                            familyName != nullptr ? familyName : "(null)",
                            modelName != nullptr ? modelName : "(null)",
                            personalName != nullptr ? personalName : "(null)",
                            step,
                            dx, dy, dz,
                            entry.movementHookHits,
                            entry.translationHookHits,
                            currentState,
                            currentSpeedAnim
                        );

                        entry.pirateFirstWorldMoveLogged = true;
                    }

                    // v0.0.16l.0: for the first handful of real movement frames,
                    // correlate world-space movement with the actor-specific
                    // animation player and Frame3d linear-speed pointer. This is
                    // read-only and targets the suspected root-motion path used
                    // by pirates such as Earth_10 ZOR_SbireFilet.
                    if (
                        step > 0.0001f &&
                        step < 1000.0f &&
                        entry.pirateMotionSamplesLogged < 16u
                        )
                    {
                        if (!ensureFile())
                            return;

                        GAM_tdst3dData* d3 = entry.actor->h3dData;
                        unsigned int runtimeRate = 0;
                        unsigned int currentFrame = 0;
                        unsigned int frame3dFrame = 0;
                        unsigned int animRate = 0;
                        unsigned int animFrames = 0;
                        MTH3D_tdstVector linear = {};
                        bool haveLinear = false;

                        if (
                            d3 != nullptr &&
                            R2R_AddressReadable(
                                reinterpret_cast<uintptr_t>(d3),
                                sizeof(GAM_tdst3dData)
                            )
                            )
                        {
                            runtimeRate = (unsigned int)d3->ucFrameRate;
                            currentFrame = (unsigned int)d3->uwCurrentFrame;
                            frame3dFrame = (unsigned int)d3->stFrame3d.uwFrameNumber;

                            if (
                                d3->h_CurrentState != nullptr &&
                                R2R_AddressReadable(
                                    reinterpret_cast<uintptr_t>(d3->h_CurrentState),
                                    sizeof(HIE_tdstState)
                                ) &&
                                d3->h_CurrentState->p_stAnim != nullptr &&
                                R2R_AddressReadable(
                                    reinterpret_cast<uintptr_t>(d3->h_CurrentState->p_stAnim),
                                    sizeof(GAM_tdstAnim3d)
                                )
                                )
                            {
                                animRate = (unsigned int)d3->h_CurrentState->p_stAnim->ucFrameRate;
                                animFrames = (unsigned int)d3->h_CurrentState->p_stAnim->uwNumberOfFrames;
                            }

                            if (
                                d3->stFrame3d.p_stLinearSpeedVector != nullptr &&
                                R2R_AddressReadable(
                                    reinterpret_cast<uintptr_t>(d3->stFrame3d.p_stLinearSpeedVector),
                                    sizeof(MTH3D_tdstVector)
                                )
                                )
                            {
                                linear = *d3->stFrame3d.p_stLinearSpeedVector;
                                haveLinear = R2R_StatsVectorSane(linear);
                            }
                        }

                        fprintf(
                            f,
                            "[PIRATE-MOTION-SAMPLE %02u] %s / %s / %s step=%.6f d=(%.6f %.6f %.6f) "
                            "state=%p cSpeedAnim=%d runtimeRate=%u animRate=%u animFrames=%u curFrame=%u frame3d=%u "
                            "linear=%s(%.6f %.6f %.6f)\n",
                            entry.pirateMotionSamplesLogged + 1u,
                            familyName != nullptr ? familyName : "(null)",
                            modelName != nullptr ? modelName : "(null)",
                            personalName != nullptr ? personalName : "(null)",
                            step, dx, dy, dz,
                            currentState, currentSpeedAnim,
                            runtimeRate, animRate, animFrames, currentFrame, frame3dFrame,
                            haveLinear ? "YES " : "NO  ",
                            haveLinear ? linear.x : 0.0f,
                            haveLinear ? linear.y : 0.0f,
                            haveLinear ? linear.z : 0.0f
                        );

                        ++entry.pirateMotionSamplesLogged;
                    }

                    entry.pirateLastWorldPosition = currentPos;
                }
            }
        }
    }

    if (f != nullptr)
        fclose(f);
}

static void R2R_StatsTick()
{
    const R2R_StatsPlaytestMode effectiveMode = R2R_StatsEffectiveMode();
    const bool moduleEnabled =
        g_R2RConfig.enabled &&
        effectiveMode != R2R_STATS_MODE_NATIVE;
    const bool movementEnabled = R2R_StatsMovementPlaytestEnabled();

    if (!g_R2RStatsConfigObserved)
    {
        g_R2RStatsConfigObserved = true;
        g_R2RStatsObservedSeed = g_R2RConfig.seed;
        g_R2RStatsObservedEnabled = moduleEnabled;
        g_R2RStatsObservedMovementEnabled = movementEnabled;
        g_R2RStatsObservedMode = effectiveMode;
        g_R2RStatsObservedGeneration = g_R2RStatsPlaytestGeneration;
    }
    else if (
        g_R2RStatsObservedSeed != g_R2RConfig.seed ||
        g_R2RStatsObservedEnabled != moduleEnabled ||
        g_R2RStatsObservedMovementEnabled != movementEnabled ||
        g_R2RStatsObservedMode != effectiveMode ||
        g_R2RStatsObservedGeneration != g_R2RStatsPlaytestGeneration
        )
    {
        if (g_R2RStatsObservedEnabled)
            R2R_StatsRestoreLiveOriginals();

        R2R_StatsClearSeen();
        g_R2RStatsWorldMarker = nullptr;
        g_R2RStatsLevel[0] = '\0';
        g_R2RStatsObservedSeed = g_R2RConfig.seed;
        g_R2RStatsObservedEnabled = moduleEnabled;
        g_R2RStatsObservedMovementEnabled = movementEnabled;
        g_R2RStatsObservedMode = effectiveMode;
        g_R2RStatsObservedGeneration = g_R2RStatsPlaytestGeneration;
    }

    if (!moduleEnabled)
        return;

    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr
        )
    {
        return;
    }

    const char* levelName = GAM_g_stEngineStructure->szLevelName;

    if (
        levelName == nullptr ||
        levelName[0] == '\0' ||
        _stricmp(levelName, "Menu") == 0
        )
    {
        return;
    }

    HIE_tdstSuperObject* activeRoot = *GAM_g_p_stDynamicWorld;

    const bool newLevel =
        g_R2RStatsWorldMarker != activeRoot ||
        g_R2RStatsLevel[0] == '\0' ||
        levelName == nullptr ||
        _stricmp(g_R2RStatsLevel, levelName) != 0;

    if (newLevel)
    {
        R2R_StatsClearSeen();
        g_R2RStatsWorldMarker = activeRoot;

        if (levelName != nullptr)
            strncpy_s(g_R2RStatsLevel, levelName, _TRUNCATE);
        else
            strcpy_s(g_R2RStatsLevel, "(unknown)");

        R2R_StatsStartLevelReport(g_R2RStatsLevel);
    }
    else
    {
        // Hook activity happens during GAM_fn_vEngine(), before this tick.
        // 16e visually validated stImposeSpeed; the old post-engine world-position
        // sampler did not reflect that visible effect reliably, so stable builds
        // only log confirmed BaseMechanics activations here.
        R2R_StatsAppendMovementActivations();
        R2R_StatsAdvanceMovementAudit();
        R2R_StatsAppendPirateReadOnlyDiagnostics();

        ++g_R2RStatsScanFrame;
        if (
            (g_R2RStatsScanFrame % R2R_STATS_SCAN_INTERVAL_FRAMES) != 0
            )
        {
            return;
        }
    }

    HIE_tdstSuperObject* mainActorSO = HIE_M_hGetMainActor();
    const unsigned int before = g_R2RStatsRandomizedCount;

    R2R_StatsScanTreeRecursive(
        activeRoot,
        mainActorSO,
        g_R2RStatsLevel,
        0
    );

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr
        )
    {
        R2R_StatsScanTreeRecursive(
            *GAM_g_p_stInactiveDynamicWorld,
            mainActorSO,
            g_R2RStatsLevel,
            0
        );
    }

    R2R_StatsAppendMovementActivations();
    R2R_StatsAdvanceMovementAudit();
    R2R_StatsAppendPirateReadOnlyDiagnostics();

    if (g_R2RStatsRandomizedCount != before || newLevel)
        R2R_StatsAppendScanSummary();
}


// ============================================================
// RANDOMIZER MODULE 2 PREP - LIVE ACTOR CATALOG (v0.0.14c.0)
//
// This is intentionally READ-ONLY.  When Items=1, the module catalogs every
// live Actor SuperObject in the active + inactive dynamic worlds.  The goal is
// to identify Rayman 2's real collectible/item actor families before we start
// swapping or replacing them.  No gameplay data is modified here.
// ============================================================

static const char* R2R_ITEM_CATALOG_REPORT =
"Rayman2Randomizer_ItemCatalog.txt";
static const unsigned int R2R_ITEM_CATALOG_MAX_SEEN = 8192;
static const unsigned int R2R_ITEM_CATALOG_SCAN_INTERVAL_FRAMES = 60;

struct R2R_ItemCatalogSeenEntry
{
    HIE_tdstSuperObject* superObject;
    HIE_tdstEngineObject* actor;
};

static R2R_ItemCatalogSeenEntry
g_R2RItemCatalogSeen[R2R_ITEM_CATALOG_MAX_SEEN] = {};
static unsigned int g_R2RItemCatalogSeenCount = 0;
static unsigned int g_R2RItemCatalogLoggedCount = 0;
static unsigned int g_R2RItemCatalogScanFrame = 0;
static HIE_tdstSuperObject* g_R2RItemCatalogWorldMarker = nullptr;
static char g_R2RItemCatalogLevel[64] = {};
static bool g_R2RItemCatalogConfigObserved = false;
static bool g_R2RItemCatalogObservedEnabled = false;
static uint32_t g_R2RItemCatalogObservedSeed = 0;
static bool g_R2RItemCatalogReportStarted = false;

static void R2R_ItemCatalogReset()
{
    std::memset(
        g_R2RItemCatalogSeen,
        0,
        sizeof(g_R2RItemCatalogSeen)
    );
    g_R2RItemCatalogSeenCount = 0;
    g_R2RItemCatalogLoggedCount = 0;
    g_R2RItemCatalogScanFrame = 0;
}

static bool R2R_ItemCatalogWasSeen(
    HIE_tdstSuperObject* superObject,
    HIE_tdstEngineObject* actor
)
{
    for (unsigned int i = 0; i < g_R2RItemCatalogSeenCount; ++i)
    {
        if (
            g_R2RItemCatalogSeen[i].superObject == superObject &&
            g_R2RItemCatalogSeen[i].actor == actor
            )
        {
            return true;
        }
    }

    return false;
}

static void R2R_ItemCatalogRemember(
    HIE_tdstSuperObject* superObject,
    HIE_tdstEngineObject* actor
)
{
    if (g_R2RItemCatalogSeenCount >= R2R_ITEM_CATALOG_MAX_SEEN)
        return;

    R2R_ItemCatalogSeenEntry& entry =
        g_R2RItemCatalogSeen[g_R2RItemCatalogSeenCount++];
    entry.superObject = superObject;
    entry.actor = actor;
}

static void R2R_ItemCatalogStartReport(const char* levelName)
{
    FILE* f = nullptr;
    fopen_s(
        &f,
        R2R_ITEM_CATALOG_REPORT,
        g_R2RItemCatalogReportStarted ? "a" : "w"
    );
    if (f == nullptr)
        return;

    if (!g_R2RItemCatalogReportStarted)
    {
        fprintf(
            f,
            "RAYMAN 2 RANDOMIZER\n"
            "%s - MULTI-LEVEL LIVE ACTOR / ITEM DISCOVERY CATALOG\n"
            "============================================================\n\n"
            "Seed  : %u\n"
            "Items : %s (DISCOVERY MODE - READ ONLY)\n\n"
            "PURPOSE\n"
            "------------------------------------------------------------\n"
            "Catalog live Actors across multiple gameplay levels without\n"
            "modifying gameplay. Menu is ignored and does not overwrite this file.\n"
            "We will use this to identify autonomous Lums/pickups before shuffling.\n\n"
            "FIELDS\n"
            "------------------------------------------------------------\n"
            "B=Brain D=Dynamics C=CollSet  3D=3DData\n"
            "HP is current/max/maxmax.\n\n",
            VERSION,
            g_R2RConfig.seed,
            g_R2RConfig.items ? "ON" : "OFF"
        );
        g_R2RItemCatalogReportStarted = true;
    }

    fprintf(
        f,
        "\n============================================================\n"
        "LEVEL: %s\n"
        "============================================================\n"
        "ACTORS\n"
        "------------------------------------------------------------\n",
        levelName != nullptr ? levelName : "(unknown)"
    );

    fclose(f);
}

static void R2R_ItemCatalogLogActor(
    HIE_tdstSuperObject* superObject,
    HIE_tdstEngineObject* actor
)
{
    if (
        superObject == nullptr ||
        actor == nullptr ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actor->hStandardGame),
            sizeof(GAM_tdstStandardGame)
        )
        )
    {
        return;
    }

    GAM_tdstStandardGame* sg = actor->hStandardGame;

    const char* familyName = HIE_fn_szGetObjectFamilyName(superObject);
    const char* modelName = HIE_fn_szGetObjectModelName(superObject);
    const char* personalName = HIE_fn_szGetObjectPersonalName(superObject);

    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;
    bool positionReadable = false;

    if (
        superObject->p_stGlobalMatrix != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(superObject->p_stGlobalMatrix),
            sizeof(POS_tdstCompletePosition)
        )
        )
    {
        x = superObject->p_stGlobalMatrix->stPos.x;
        y = superObject->p_stGlobalMatrix->stPos.y;
        z = superObject->p_stGlobalMatrix->stPos.z;
        positionReadable = true;
    }

    ++g_R2RItemCatalogLoggedCount;

    FILE* f = nullptr;
    fopen_s(&f, R2R_ITEM_CATALOG_REPORT, "a");
    if (f == nullptr)
        return;

    fprintf(
        f,
        "[%04u] %s / %s / %s\n"
        "       IDs=%ld/%ld/%ld  SO=%p Actor=%p\n"
        "       pos=%s %.3f %.3f %.3f\n"
        "       B=%s D=%s C=%s 3D=%s  HP=%u/%u/%u\n"
        "       custom=0x%08lX misc=0x%02X\n",
        g_R2RItemCatalogLoggedCount,
        familyName != nullptr ? familyName : "(null)",
        modelName != nullptr ? modelName : "(null)",
        personalName != nullptr ? personalName : "(null)",
        sg->lObjectFamilyType,
        sg->lObjectModelType,
        sg->lObjectPersonalType,
        superObject,
        actor,
        positionReadable ? "YES" : "NO ",
        x,
        y,
        z,
        actor->hBrain != nullptr ? "Y" : "N",
        actor->hDynam != nullptr ? "Y" : "N",
        actor->hCollSet != nullptr ? "Y" : "N",
        actor->h3dData != nullptr ? "Y" : "N",
        (unsigned int)sg->ucHitPoints,
        (unsigned int)sg->ucHitPointsMax,
        (unsigned int)sg->ucHitPointsMaxMax,
        (unsigned long)sg->ulCustomBits,
        (unsigned int)sg->ucMiscFlags
    );

    fclose(f);
}

static void R2R_ItemCatalogProcessActor(
    HIE_tdstSuperObject* superObject
)
{
    if (
        superObject == nullptr ||
        superObject->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(superObject),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return;
    }

    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(superObject);
    if (
        actor == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actor),
            sizeof(HIE_tdstEngineObject)
        )
        )
    {
        return;
    }

    if (R2R_ItemCatalogWasSeen(superObject, actor))
        return;

    R2R_ItemCatalogRemember(superObject, actor);
    R2R_ItemCatalogLogActor(superObject, actor);
}

static void R2R_ItemCatalogScanTreeRecursive(
    HIE_tdstSuperObject* root,
    int depth
)
{
    if (
        root == nullptr ||
        depth > 64 ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(root),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return;
    }

    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object == nullptr)
            continue;

        R2R_ItemCatalogProcessActor(object);
        R2R_ItemCatalogScanTreeRecursive(object, depth + 1);
    }
}

static void R2R_ItemCatalogAppendSummary()
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_ITEM_CATALOG_REPORT, "a");
    if (f == nullptr)
        return;

    fprintf(
        f,
        "\nCATALOG SUMMARY: seen=%u logged=%u\n",
        g_R2RItemCatalogSeenCount,
        g_R2RItemCatalogLoggedCount
    );
    fclose(f);
}

static void R2R_ItemCatalogTick()
{
    const bool moduleEnabled =
        g_R2RConfig.enabled &&
        g_R2RConfig.items;

    if (!g_R2RItemCatalogConfigObserved)
    {
        g_R2RItemCatalogConfigObserved = true;
        g_R2RItemCatalogObservedEnabled = moduleEnabled;
        g_R2RItemCatalogObservedSeed = g_R2RConfig.seed;
    }
    else if (
        g_R2RItemCatalogObservedEnabled != moduleEnabled ||
        g_R2RItemCatalogObservedSeed != g_R2RConfig.seed
        )
    {
        R2R_ItemCatalogReset();
        g_R2RItemCatalogWorldMarker = nullptr;
        g_R2RItemCatalogLevel[0] = '\0';
        g_R2RItemCatalogObservedEnabled = moduleEnabled;
        g_R2RItemCatalogObservedSeed = g_R2RConfig.seed;
        g_R2RItemCatalogReportStarted = false;
    }

    if (!moduleEnabled)
        return;

    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr
        )
    {
        return;
    }

    const char* levelName = GAM_g_stEngineStructure->szLevelName;
    HIE_tdstSuperObject* activeRoot = *GAM_g_p_stDynamicWorld;

    const bool newLevel =
        g_R2RItemCatalogWorldMarker != activeRoot ||
        g_R2RItemCatalogLevel[0] == '\0' ||
        levelName == nullptr ||
        _stricmp(g_R2RItemCatalogLevel, levelName) != 0;

    if (newLevel)
    {
        R2R_ItemCatalogReset();
        g_R2RItemCatalogWorldMarker = activeRoot;

        if (levelName != nullptr)
            strncpy_s(g_R2RItemCatalogLevel, levelName, _TRUNCATE);
        else
            strcpy_s(g_R2RItemCatalogLevel, "(unknown)");

        R2R_ItemCatalogStartReport(g_R2RItemCatalogLevel);
    }

    if (!newLevel)
    {
        ++g_R2RItemCatalogScanFrame;
        if (
            (g_R2RItemCatalogScanFrame %
                R2R_ITEM_CATALOG_SCAN_INTERVAL_FRAMES) != 0
            )
        {
            return;
        }
    }

    const unsigned int before = g_R2RItemCatalogLoggedCount;

    R2R_ItemCatalogScanTreeRecursive(activeRoot, 0);

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr
        )
    {
        R2R_ItemCatalogScanTreeRecursive(
            *GAM_g_p_stInactiveDynamicWorld,
            0
        );
    }

    if (newLevel || g_R2RItemCatalogLoggedCount != before)
        R2R_ItemCatalogAppendSummary();
}



// ============================================================
// RANDOMIZER MODULE 2 - SAFE STATIC LUM POSITION SHUFFLER (v0.0.14i.0)
//
// Full-game cataloging showed several very different actors in the Lums family.
// This first real collectible pass touches ONLY:
//
//     Lums / CHR_lums_basic
//
// and only actors that are static (Brain=YES, Dynamics=NO, CollSet=NO,
// 3DData=YES). All eligible CHR_lums_basic actors in one level share the same
// model compatibility class, so their actor identities may trade positions.
//
// This deliberately excludes:
//   - Alw_Lums_Model  (runtime/generated Lums)
//   - ARG_SerieRouge  (dedicated red-Lum series)
//   - BNT_grappinable (grappling Lums)
//   - YAM_Lums        (map/menu object)
//   - every Cage actor
//
// We move no scripts, models, Brains, collisions or actor identities.
// ============================================================

static const char* R2R_STATIC_LUM_REPORT =
"Rayman2Randomizer_Items.txt";
static const unsigned int R2R_STATIC_LUM_MAX = 128;
static const unsigned int R2R_STATIC_LUM_DELAY_FRAMES = 60;

struct R2R_StaticLumEntry
{
    HIE_tdstSuperObject* superObject;
    HIE_tdstEngineObject* actor;
    MTH3D_tdstVector originalGlobal;
    long personalType;
    unsigned long customBits;
    unsigned char miscFlags;
    char personal[128];
};

static R2R_StaticLumEntry g_R2RStaticLums[R2R_STATIC_LUM_MAX] = {};
static unsigned int g_R2RStaticLumCount = 0;
static unsigned int g_R2RStaticLumFrames = 0;
static bool g_R2RStaticLumApplied = false;
static HIE_tdstSuperObject* g_R2RStaticLumWorldMarker = nullptr;
static char g_R2RStaticLumLevel[64] = {};
static bool g_R2RStaticLumConfigObserved = false;
static bool g_R2RStaticLumObservedEnabled = false;
static uint32_t g_R2RStaticLumObservedSeed = 0;

static void R2R_StaticLumResetForLevel()
{
    std::memset(g_R2RStaticLums, 0, sizeof(g_R2RStaticLums));
    g_R2RStaticLumCount = 0;
    g_R2RStaticLumFrames = 0;
    g_R2RStaticLumApplied = false;
}

static bool R2R_StaticLumAlreadyCollected(HIE_tdstSuperObject* superObject)
{
    for (unsigned int i = 0; i < g_R2RStaticLumCount; ++i)
    {
        if (g_R2RStaticLums[i].superObject == superObject)
            return true;
    }
    return false;
}

static void R2R_StaticLumTryCollect(HIE_tdstSuperObject* superObject)
{
    if (
        superObject == nullptr ||
        superObject->ulType != HIE_C_Type_Actor ||
        g_R2RStaticLumCount >= R2R_STATIC_LUM_MAX ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(superObject), sizeof(HIE_tdstSuperObject)) ||
        R2R_StaticLumAlreadyCollected(superObject)
        )
        return;

    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(superObject);

    if (
        actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)) ||
        superObject->p_stGlobalMatrix == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(superObject->p_stGlobalMatrix), sizeof(POS_tdstCompletePosition))
        )
        return;

    const char* familyName = HIE_fn_szGetObjectFamilyName(superObject);
    const char* modelName = HIE_fn_szGetObjectModelName(superObject);

    if (
        familyName == nullptr ||
        modelName == nullptr ||
        _stricmp(familyName, "Lums") != 0 ||
        _stricmp(modelName, "CHR_lums_basic") != 0
        )
        return;

    if (
        actor->hBrain == nullptr ||
        actor->hDynam != nullptr ||
        actor->hCollSet != nullptr ||
        actor->h3dData == nullptr
        )
        return;

    GAM_tdstStandardGame* sg = actor->hStandardGame;
    R2R_StaticLumEntry& entry = g_R2RStaticLums[g_R2RStaticLumCount++];

    entry.superObject = superObject;
    entry.actor = actor;
    entry.originalGlobal = superObject->p_stGlobalMatrix->stPos;
    entry.personalType = sg->lObjectPersonalType;
    entry.customBits = sg->ulCustomBits;
    entry.miscFlags = sg->ucMiscFlags;

    const char* personalName = HIE_fn_szGetObjectPersonalName(superObject);
    if (personalName != nullptr)
        strncpy_s(entry.personal, personalName, _TRUNCATE);
    else
        strcpy_s(entry.personal, "(null)");
}

static void R2R_StaticLumCollectTreeRecursive(HIE_tdstSuperObject* root, int depth)
{
    if (
        root == nullptr ||
        depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))
        )
        return;

    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object == nullptr)
            continue;
        R2R_StaticLumTryCollect(object);
        R2R_StaticLumCollectTreeRecursive(object, depth + 1);
    }
}

static bool R2R_StaticLumSameGroup(const R2R_StaticLumEntry& a, const R2R_StaticLumEntry& b)
{
    return a.customBits == b.customBits && a.miscFlags == b.miscFlags;
}

static void R2R_StaticLumSortIndices(unsigned int* indices, unsigned int count)
{
    for (unsigned int i = 0; i < count; ++i)
    {
        for (unsigned int j = i + 1; j < count; ++j)
        {
            const R2R_StaticLumEntry& a = g_R2RStaticLums[indices[i]];
            const R2R_StaticLumEntry& b = g_R2RStaticLums[indices[j]];
            bool swapNeeded = false;

            if (b.personalType < a.personalType)
                swapNeeded = true;
            else if (b.personalType == a.personalType)
            {
                if (b.originalGlobal.x < a.originalGlobal.x)
                    swapNeeded = true;
                else if (b.originalGlobal.x == a.originalGlobal.x &&
                    b.originalGlobal.y < a.originalGlobal.y)
                    swapNeeded = true;
                else if (b.originalGlobal.x == a.originalGlobal.x &&
                    b.originalGlobal.y == a.originalGlobal.y &&
                    b.originalGlobal.z < a.originalGlobal.z)
                    swapNeeded = true;
            }

            if (swapNeeded)
            {
                const unsigned int temp = indices[i];
                indices[i] = indices[j];
                indices[j] = temp;
            }
        }
    }
}

static void R2R_StaticLumApply(const char* levelName)
{
    if (g_R2RStaticLumApplied)
        return;

    g_R2RStaticLumApplied = true;

    FILE* f = nullptr;
    fopen_s(&f, R2R_STATIC_LUM_REPORT, "w");

    if (f != nullptr)
    {
        fprintf(
            f,
            "RAYMAN 2 RANDOMIZER\n"
            "%s - SAFE STATIC BASIC-LUM SHUFFLER\n"
            "============================================================\n\n"
            "Level : %s\n"
            "Seed  : %u\n"
            "Items : ON\n\n"
            "ELIGIBILITY\n"
            "------------------------------------------------------------\n"
            "Family / Model : Lums / CHR_lums_basic\n"
            "Brain          : required\n"
            "Dynamics       : must be NULL\n"
            "CollSet        : must be NULL\n"
            "3DData         : required\n"
            "Collected      : %u\n\n"
            "Operation: CHR_lums_basic actors trade positions ONLY inside\n"
            "the exact same CustomBits + MiscFlags compatibility class.\n"
            "This avoids mixing special/conditional Lum behaviors.\n\n"
            "Explicitly untouched: Alw_Lums_Model, ARG_SerieRouge,\n"
            "BNT_grappinable, YAM_Lums, all Cage actors.\n\n",
            VERSION,
            levelName != nullptr ? levelName : "(unknown)",
            g_R2RConfig.seed,
            g_R2RStaticLumCount
        );
    }

    if (g_R2RStaticLumCount < 2)
    {
        if (f != nullptr)
        {
            fprintf(
                f,
                "RESULT: fewer than two compatible static basic Lums; nothing changed.\n"
            );
            fclose(f);
        }
        return;
    }

    unsigned int indices[R2R_STATIC_LUM_MAX] = {};
    unsigned int permutation[R2R_STATIC_LUM_MAX] = {};

    for (unsigned int i = 0; i < g_R2RStaticLumCount; ++i)
    {
        indices[i] = i;
        permutation[i] = i;
    }

    // Stable source order first, then a deterministic Fisher-Yates permutation.
    R2R_StaticLumSortIndices(indices, g_R2RStaticLumCount);

    // v0.0.14i.0: shuffle ONLY inside exact CustomBits + MiscFlags
    // compatibility classes.  The previous build had this compatibility
    // predicate but did not actually use it when building the permutation.
    for (unsigned int i = g_R2RStaticLumCount - 1; i > 0; --i)
    {
        unsigned int candidates[R2R_STATIC_LUM_MAX] = {};
        unsigned int candidateCount = 0;

        for (unsigned int k = 0; k <= i; ++k)
        {
            if (
                R2R_StaticLumSameGroup(
                    g_R2RStaticLums[indices[i]],
                    g_R2RStaticLums[indices[k]]
                )
                )
            {
                candidates[candidateCount++] = k;
            }
        }

        if (candidateCount < 2)
            continue;

        const uint32_t r = R2R_RollU32(
            "Items.StaticBasicLum.Grouped",
            levelName,
            0x14A00000u + i
        );
        const unsigned int j = candidates[r % candidateCount];

        const unsigned int temp = permutation[i];
        permutation[i] = permutation[j];
        permutation[j] = temp;
    }

    bool anyMoved = false;
    for (unsigned int i = 0; i < g_R2RStaticLumCount; ++i)
    {
        if (permutation[i] != i)
        {
            anyMoved = true;
            break;
        }
    }

    // If RNG happened to leave every actor in place, force one swap only
    // when a truly compatible pair exists. Never cross compatibility classes.
    if (!anyMoved)
    {
        bool forced = false;
        for (unsigned int i = 0; i < g_R2RStaticLumCount && !forced; ++i)
        {
            for (unsigned int j = i + 1; j < g_R2RStaticLumCount; ++j)
            {
                if (
                    R2R_StaticLumSameGroup(
                        g_R2RStaticLums[indices[i]],
                        g_R2RStaticLums[indices[j]]
                    )
                    )
                {
                    const unsigned int temp = permutation[i];
                    permutation[i] = permutation[j];
                    permutation[j] = temp;
                    forced = true;
                    break;
                }
            }
        }
    }

    unsigned int movedActors = 0;

    if (f != nullptr)
    {
        fprintf(
            f,
            "SHUFFLE\n"
            "------------------------------------------------------------\n"
        );
    }

    for (unsigned int i = 0; i < g_R2RStaticLumCount; ++i)
    {
        R2R_StaticLumEntry& entry = g_R2RStaticLums[indices[i]];
        const R2R_StaticLumEntry& target =
            g_R2RStaticLums[indices[permutation[i]]];

        if (
            entry.superObject == nullptr ||
            entry.superObject->p_stGlobalMatrix == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject->p_stGlobalMatrix),
                sizeof(POS_tdstCompletePosition)
            )
            )
            continue;

        const MTH3D_tdstVector oldGlobal =
            entry.superObject->p_stGlobalMatrix->stPos;
        const MTH3D_tdstVector newGlobal =
            target.originalGlobal;

        const float dx = newGlobal.x - oldGlobal.x;
        const float dy = newGlobal.y - oldGlobal.y;
        const float dz = newGlobal.z - oldGlobal.z;

        entry.superObject->p_stGlobalMatrix->stPos = newGlobal;

        if (
            entry.superObject->p_stLocalMatrix != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject->p_stLocalMatrix),
                sizeof(POS_tdstCompletePosition)
            )
            )
        {
            entry.superObject->p_stLocalMatrix->stPos.x += dx;
            entry.superObject->p_stLocalMatrix->stPos.y += dy;
            entry.superObject->p_stLocalMatrix->stPos.z += dz;
        }

        if (permutation[i] != i)
            ++movedActors;

        if (f != nullptr)
        {
            fprintf(
                f,
                "[%03u] %s  custom=0x%08lX misc=0x%02X\n"
                "      from %.3f %.3f %.3f\n"
                "        to %.3f %.3f %.3f  <- %s\n",
                i,
                entry.personal,
                entry.customBits,
                (unsigned int)entry.miscFlags,
                oldGlobal.x, oldGlobal.y, oldGlobal.z,
                newGlobal.x, newGlobal.y, newGlobal.z,
                target.personal
            );
        }
    }

    if (f != nullptr)
    {
        fprintf(
            f,
            "\n============================================================\n"
            "RESULT\n"
            "------------------------------------------------------------\n"
            "Compatible static basic Lums : %u\n"
            "Actors moved                 : %u\n"
            "No actors created/deleted; no model/Brain/script pointers replaced.\n",
            g_R2RStaticLumCount,
            movedActors
        );
        fclose(f);
    }
}

static void R2R_StaticLumShuffleTick()
{
    const bool moduleEnabled = g_R2RConfig.enabled && g_R2RConfig.items;

    if (!g_R2RStaticLumConfigObserved)
    {
        g_R2RStaticLumConfigObserved = true;
        g_R2RStaticLumObservedEnabled = moduleEnabled;
        g_R2RStaticLumObservedSeed = g_R2RConfig.seed;
    }
    else if (
        g_R2RStaticLumObservedEnabled != moduleEnabled ||
        g_R2RStaticLumObservedSeed != g_R2RConfig.seed
        )
    {
        R2R_StaticLumResetForLevel();
        g_R2RStaticLumWorldMarker = nullptr;
        g_R2RStaticLumLevel[0] = '\0';
        g_R2RStaticLumObservedEnabled = moduleEnabled;
        g_R2RStaticLumObservedSeed = g_R2RConfig.seed;
    }

    if (!moduleEnabled)
        return;

    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr
        )
        return;

    const char* levelName = GAM_g_stEngineStructure->szLevelName;

    if (levelName != nullptr && _stricmp(levelName, "Menu") == 0)
        return;

    HIE_tdstSuperObject* activeRoot = *GAM_g_p_stDynamicWorld;

    const bool newLevel =
        g_R2RStaticLumWorldMarker != activeRoot ||
        g_R2RStaticLumLevel[0] == '\0' ||
        levelName == nullptr ||
        _stricmp(g_R2RStaticLumLevel, levelName) != 0;

    if (newLevel)
    {
        R2R_StaticLumResetForLevel();
        g_R2RStaticLumWorldMarker = activeRoot;

        if (levelName != nullptr)
            strncpy_s(g_R2RStaticLumLevel, levelName, _TRUNCATE);
        else
            strcpy_s(g_R2RStaticLumLevel, "(unknown)");
    }

    if (g_R2RStaticLumApplied)
        return;

    ++g_R2RStaticLumFrames;
    if (g_R2RStaticLumFrames < R2R_STATIC_LUM_DELAY_FRAMES)
        return;

    g_R2RStaticLumCount = 0;
    R2R_StaticLumCollectTreeRecursive(activeRoot, 0);

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr
        )
    {
        R2R_StaticLumCollectTreeRecursive(*GAM_g_p_stInactiveDynamicWorld, 0);
    }

    R2R_StaticLumApply(g_R2RStaticLumLevel);
}


// ============================================================
// RANDOMIZER MODULE 3 - SAFE STATIC RED-LUM SERIES SHUFFLER (v0.0.14i.0)
//
// Second conservative collectible pool:
//
//     Lums / ARG_SerieRouge
//
// The full-game catalog shows these actors with the same safe static profile:
// Brain=YES, Dynamics=NO, CollSet=NO, 3DData=YES.
// They are shuffled ONLY among other ARG_SerieRouge positions in the same level.
// Basic Lums and red-series Lums never cross pools.
//
// We move no scripts, models, Brains, collisions or actor identities.
// ============================================================

static const char* R2R_STATIC_RED_LUM_REPORT =
"Rayman2Randomizer_RedLums.txt";
static const unsigned int R2R_STATIC_RED_LUM_MAX = 256;
static const unsigned int R2R_STATIC_RED_LUM_DELAY_FRAMES = 60;

struct R2R_StaticRedLumEntry
{
    HIE_tdstSuperObject* superObject;
    HIE_tdstEngineObject* actor;
    MTH3D_tdstVector originalGlobal;
    long personalType;
    unsigned long customBits;
    unsigned char miscFlags;
    char personal[128];
};

static R2R_StaticRedLumEntry g_R2RStaticRedLums[R2R_STATIC_RED_LUM_MAX] = {};
static unsigned int g_R2RStaticRedLumCount = 0;
static unsigned int g_R2RStaticRedLumFrames = 0;
static bool g_R2RStaticRedLumApplied = false;
static HIE_tdstSuperObject* g_R2RStaticRedLumWorldMarker = nullptr;
static char g_R2RStaticRedLumLevel[64] = {};
static bool g_R2RStaticRedLumConfigObserved = false;
static bool g_R2RStaticRedLumObservedEnabled = false;
static uint32_t g_R2RStaticRedLumObservedSeed = 0;

static void R2R_StaticRedLumResetForLevel()
{
    std::memset(g_R2RStaticRedLums, 0, sizeof(g_R2RStaticRedLums));
    g_R2RStaticRedLumCount = 0;
    g_R2RStaticRedLumFrames = 0;
    g_R2RStaticRedLumApplied = false;
}

static bool R2R_StaticRedLumAlreadyCollected(HIE_tdstSuperObject* superObject)
{
    for (unsigned int i = 0; i < g_R2RStaticRedLumCount; ++i)
    {
        if (g_R2RStaticRedLums[i].superObject == superObject)
            return true;
    }
    return false;
}

static void R2R_StaticRedLumTryCollect(HIE_tdstSuperObject* superObject)
{
    if (
        superObject == nullptr ||
        superObject->ulType != HIE_C_Type_Actor ||
        g_R2RStaticRedLumCount >= R2R_STATIC_RED_LUM_MAX ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(superObject), sizeof(HIE_tdstSuperObject)) ||
        R2R_StaticRedLumAlreadyCollected(superObject)
        )
        return;

    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(superObject);

    if (
        actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)) ||
        superObject->p_stGlobalMatrix == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(superObject->p_stGlobalMatrix), sizeof(POS_tdstCompletePosition))
        )
        return;

    const char* familyName = HIE_fn_szGetObjectFamilyName(superObject);
    const char* modelName = HIE_fn_szGetObjectModelName(superObject);

    if (
        familyName == nullptr ||
        modelName == nullptr ||
        _stricmp(familyName, "Lums") != 0 ||
        _stricmp(modelName, "ARG_SerieRouge") != 0
        )
        return;

    if (
        actor->hBrain == nullptr ||
        actor->hDynam != nullptr ||
        actor->hCollSet != nullptr ||
        actor->h3dData == nullptr
        )
        return;

    GAM_tdstStandardGame* sg = actor->hStandardGame;
    R2R_StaticRedLumEntry& entry = g_R2RStaticRedLums[g_R2RStaticRedLumCount++];

    entry.superObject = superObject;
    entry.actor = actor;
    entry.originalGlobal = superObject->p_stGlobalMatrix->stPos;
    entry.personalType = sg->lObjectPersonalType;
    entry.customBits = sg->ulCustomBits;
    entry.miscFlags = sg->ucMiscFlags;

    const char* personalName = HIE_fn_szGetObjectPersonalName(superObject);
    if (personalName != nullptr)
        strncpy_s(entry.personal, personalName, _TRUNCATE);
    else
        strcpy_s(entry.personal, "(null)");
}

static void R2R_StaticRedLumCollectTreeRecursive(HIE_tdstSuperObject* root, int depth)
{
    if (
        root == nullptr ||
        depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))
        )
        return;

    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object == nullptr)
            continue;
        R2R_StaticRedLumTryCollect(object);
        R2R_StaticRedLumCollectTreeRecursive(object, depth + 1);
    }
}

static bool R2R_StaticRedLumSameGroup(const R2R_StaticRedLumEntry& a, const R2R_StaticRedLumEntry& b)
{
    return a.customBits == b.customBits && a.miscFlags == b.miscFlags;
}

static void R2R_StaticRedLumSortIndices(unsigned int* indices, unsigned int count)
{
    for (unsigned int i = 0; i < count; ++i)
    {
        for (unsigned int j = i + 1; j < count; ++j)
        {
            const R2R_StaticRedLumEntry& a = g_R2RStaticRedLums[indices[i]];
            const R2R_StaticRedLumEntry& b = g_R2RStaticRedLums[indices[j]];
            bool swapNeeded = false;

            if (b.personalType < a.personalType)
                swapNeeded = true;
            else if (b.personalType == a.personalType)
            {
                if (b.originalGlobal.x < a.originalGlobal.x)
                    swapNeeded = true;
                else if (b.originalGlobal.x == a.originalGlobal.x &&
                    b.originalGlobal.y < a.originalGlobal.y)
                    swapNeeded = true;
                else if (b.originalGlobal.x == a.originalGlobal.x &&
                    b.originalGlobal.y == a.originalGlobal.y &&
                    b.originalGlobal.z < a.originalGlobal.z)
                    swapNeeded = true;
            }

            if (swapNeeded)
            {
                const unsigned int temp = indices[i];
                indices[i] = indices[j];
                indices[j] = temp;
            }
        }
    }
}

static void R2R_StaticRedLumApply(const char* levelName)
{
    if (g_R2RStaticRedLumApplied)
        return;

    g_R2RStaticRedLumApplied = true;

    FILE* f = nullptr;
    fopen_s(&f, R2R_STATIC_RED_LUM_REPORT, "w");

    if (f != nullptr)
    {
        fprintf(
            f,
            "RAYMAN 2 RANDOMIZER\n"
            "%s - SAFE STATIC RED-LUM SERIES SHUFFLER\n"
            "============================================================\n\n"
            "Level : %s\n"
            "Seed  : %u\n"
            "Items : ON\n\n"
            "ELIGIBILITY\n"
            "------------------------------------------------------------\n"
            "Family / Model : Lums / ARG_SerieRouge\n"
            "Brain          : required\n"
            "Dynamics       : must be NULL\n"
            "CollSet        : must be NULL\n"
            "3DData         : required\n"
            "Collected      : %u\n\n"
            "Operation: ARG_SerieRouge actors trade positions ONLY inside\n"
            "the exact same CustomBits + MiscFlags compatibility class.\n"
            "Different scripted red-Lum series are no longer mixed.\n\n"
            "Separate pool: CHR_lums_basic (never mixed with red series).\n"
            "Explicitly untouched: Alw_Lums_Model, BNT_grappinable,\n"
            "YAM_Lums, all Cage actors.\n\n",
            VERSION,
            levelName != nullptr ? levelName : "(unknown)",
            g_R2RConfig.seed,
            g_R2RStaticRedLumCount
        );
    }

    if (g_R2RStaticRedLumCount < 2)
    {
        if (f != nullptr)
        {
            fprintf(
                f,
                "RESULT: fewer than two compatible static red-series Lums; nothing changed.\n"
            );
            fclose(f);
        }
        return;
    }

    unsigned int indices[R2R_STATIC_RED_LUM_MAX] = {};
    unsigned int permutation[R2R_STATIC_RED_LUM_MAX] = {};

    for (unsigned int i = 0; i < g_R2RStaticRedLumCount; ++i)
    {
        indices[i] = i;
        permutation[i] = i;
    }

    // Stable source order first, then a deterministic Fisher-Yates permutation.
    R2R_StaticRedLumSortIndices(indices, g_R2RStaticRedLumCount);

    // v0.0.14i.0: red-series actors are shuffled only inside exact
    // CustomBits + MiscFlags compatibility classes. This keeps independent
    // scripted red-Lum series from being mixed together.
    for (unsigned int i = g_R2RStaticRedLumCount - 1; i > 0; --i)
    {
        unsigned int candidates[R2R_STATIC_RED_LUM_MAX] = {};
        unsigned int candidateCount = 0;

        for (unsigned int k = 0; k <= i; ++k)
        {
            if (
                R2R_StaticRedLumSameGroup(
                    g_R2RStaticRedLums[indices[i]],
                    g_R2RStaticRedLums[indices[k]]
                )
                )
            {
                candidates[candidateCount++] = k;
            }
        }

        if (candidateCount < 2)
            continue;

        const uint32_t r = R2R_RollU32(
            "Items.StaticRedLum.Grouped",
            levelName,
            0x14B00000u + i
        );
        const unsigned int j = candidates[r % candidateCount];

        const unsigned int temp = permutation[i];
        permutation[i] = permutation[j];
        permutation[j] = temp;
    }

    bool anyMoved = false;
    for (unsigned int i = 0; i < g_R2RStaticRedLumCount; ++i)
    {
        if (permutation[i] != i)
        {
            anyMoved = true;
            break;
        }
    }

    if (!anyMoved)
    {
        bool forced = false;
        for (unsigned int i = 0; i < g_R2RStaticRedLumCount && !forced; ++i)
        {
            for (unsigned int j = i + 1; j < g_R2RStaticRedLumCount; ++j)
            {
                if (
                    R2R_StaticRedLumSameGroup(
                        g_R2RStaticRedLums[indices[i]],
                        g_R2RStaticRedLums[indices[j]]
                    )
                    )
                {
                    const unsigned int temp = permutation[i];
                    permutation[i] = permutation[j];
                    permutation[j] = temp;
                    forced = true;
                    break;
                }
            }
        }
    }

    unsigned int movedActors = 0;

    if (f != nullptr)
    {
        fprintf(
            f,
            "SHUFFLE\n"
            "------------------------------------------------------------\n"
        );
    }

    for (unsigned int i = 0; i < g_R2RStaticRedLumCount; ++i)
    {
        R2R_StaticRedLumEntry& entry = g_R2RStaticRedLums[indices[i]];
        const R2R_StaticRedLumEntry& target =
            g_R2RStaticRedLums[indices[permutation[i]]];

        if (
            entry.superObject == nullptr ||
            entry.superObject->p_stGlobalMatrix == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject->p_stGlobalMatrix),
                sizeof(POS_tdstCompletePosition)
            )
            )
            continue;

        const MTH3D_tdstVector oldGlobal =
            entry.superObject->p_stGlobalMatrix->stPos;
        const MTH3D_tdstVector newGlobal =
            target.originalGlobal;

        const float dx = newGlobal.x - oldGlobal.x;
        const float dy = newGlobal.y - oldGlobal.y;
        const float dz = newGlobal.z - oldGlobal.z;

        entry.superObject->p_stGlobalMatrix->stPos = newGlobal;

        if (
            entry.superObject->p_stLocalMatrix != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject->p_stLocalMatrix),
                sizeof(POS_tdstCompletePosition)
            )
            )
        {
            entry.superObject->p_stLocalMatrix->stPos.x += dx;
            entry.superObject->p_stLocalMatrix->stPos.y += dy;
            entry.superObject->p_stLocalMatrix->stPos.z += dz;
        }

        if (permutation[i] != i)
            ++movedActors;

        if (f != nullptr)
        {
            fprintf(
                f,
                "[%03u] %s  custom=0x%08lX misc=0x%02X\n"
                "      from %.3f %.3f %.3f\n"
                "        to %.3f %.3f %.3f  <- %s\n",
                i,
                entry.personal,
                entry.customBits,
                (unsigned int)entry.miscFlags,
                oldGlobal.x, oldGlobal.y, oldGlobal.z,
                newGlobal.x, newGlobal.y, newGlobal.z,
                target.personal
            );
        }
    }

    if (f != nullptr)
    {
        fprintf(
            f,
            "\n============================================================\n"
            "RESULT\n"
            "------------------------------------------------------------\n"
            "Compatible static red-series Lums : %u\n"
            "Actors moved                 : %u\n"
            "No actors created/deleted; no model/Brain/script pointers replaced.\n",
            g_R2RStaticRedLumCount,
            movedActors
        );
        fclose(f);
    }
}

static void R2R_StaticRedLumShuffleTick()
{
    const bool moduleEnabled = g_R2RConfig.enabled && g_R2RConfig.items;

    if (!g_R2RStaticRedLumConfigObserved)
    {
        g_R2RStaticRedLumConfigObserved = true;
        g_R2RStaticRedLumObservedEnabled = moduleEnabled;
        g_R2RStaticRedLumObservedSeed = g_R2RConfig.seed;
    }
    else if (
        g_R2RStaticRedLumObservedEnabled != moduleEnabled ||
        g_R2RStaticRedLumObservedSeed != g_R2RConfig.seed
        )
    {
        R2R_StaticRedLumResetForLevel();
        g_R2RStaticRedLumWorldMarker = nullptr;
        g_R2RStaticRedLumLevel[0] = '\0';
        g_R2RStaticRedLumObservedEnabled = moduleEnabled;
        g_R2RStaticRedLumObservedSeed = g_R2RConfig.seed;
    }

    if (!moduleEnabled)
        return;

    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr
        )
        return;

    const char* levelName = GAM_g_stEngineStructure->szLevelName;

    if (levelName != nullptr && _stricmp(levelName, "Menu") == 0)
        return;

    HIE_tdstSuperObject* activeRoot = *GAM_g_p_stDynamicWorld;

    const bool newLevel =
        g_R2RStaticRedLumWorldMarker != activeRoot ||
        g_R2RStaticRedLumLevel[0] == '\0' ||
        levelName == nullptr ||
        _stricmp(g_R2RStaticRedLumLevel, levelName) != 0;

    if (newLevel)
    {
        R2R_StaticRedLumResetForLevel();
        g_R2RStaticRedLumWorldMarker = activeRoot;

        if (levelName != nullptr)
            strncpy_s(g_R2RStaticRedLumLevel, levelName, _TRUNCATE);
        else
            strcpy_s(g_R2RStaticRedLumLevel, "(unknown)");
    }

    if (g_R2RStaticRedLumApplied)
        return;

    ++g_R2RStaticRedLumFrames;
    if (g_R2RStaticRedLumFrames < R2R_STATIC_RED_LUM_DELAY_FRAMES)
        return;

    g_R2RStaticRedLumCount = 0;
    R2R_StaticRedLumCollectTreeRecursive(activeRoot, 0);

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr
        )
    {
        R2R_StaticRedLumCollectTreeRecursive(*GAM_g_p_stInactiveDynamicWorld, 0);
    }

    R2R_StaticRedLumApply(g_R2RStaticRedLumLevel);
}




// ============================================================
// RANDOMIZER MODULE 4 - CONSERVATIVE NEARBY MEGASHOOT RELOCATION (v0.0.14j.0)
//
// Full-game cataloging found only a handful of megashoot / ARG_MegaShoot
// pickups, usually one per level. A same-model position permutation would
// therefore do nothing. For this first special-item test we allow a MegaShoot
// to trade places with ONE nearby static Lums / CHR_lums_basic actor.
//
// Safety rules are intentionally strict:
//   - MegaShoot profile: Brain=YES, Dynamics=NO, CollSet=NO, 3DData=YES
//   - anchor profile:    static CHR_lums_basic with the same safe profile
//   - exact MiscFlags match
//   - exact low CustomBits tag match: (CustomBits & 0x00000FFF)
//   - maximum original/current separation: 20 world units
//
// This tick runs AFTER the proven basic/red Lum shufflers, so the proximity
// test sees the final Lum positions for this frame. No actor/model/script is
// created, deleted, replaced or copied; only the two existing positions trade.
// ============================================================

static const char* R2R_SPECIAL_PICKUP_REPORT =
"Rayman2Randomizer_SpecialPickups.txt";
static const unsigned int R2R_MEGASHOOT_MAX = 16;
static const unsigned int R2R_MEGASHOOT_ANCHOR_MAX = 256;
static const unsigned int R2R_MEGASHOOT_DELAY_FRAMES = 60;
static const float R2R_MEGASHOOT_MAX_DISTANCE = 20.0f;
static const unsigned long R2R_MEGASHOOT_CUSTOM_TAG_MASK = 0x00000FFFul;

struct R2R_MegaShootEntry
{
    HIE_tdstSuperObject* superObject;
    HIE_tdstEngineObject* actor;
    MTH3D_tdstVector position;
    long personalType;
    unsigned long customBits;
    unsigned char miscFlags;
    char personal[128];
};

static R2R_MegaShootEntry g_R2RMegaShoots[R2R_MEGASHOOT_MAX] = {};
static R2R_MegaShootEntry g_R2RMegaShootAnchors[R2R_MEGASHOOT_ANCHOR_MAX] = {};
static unsigned int g_R2RMegaShootCount = 0;
static unsigned int g_R2RMegaShootAnchorCount = 0;
static unsigned int g_R2RMegaShootFrames = 0;
static bool g_R2RMegaShootApplied = false;
static HIE_tdstSuperObject* g_R2RMegaShootWorldMarker = nullptr;
static char g_R2RMegaShootLevel[64] = {};
static bool g_R2RMegaShootConfigObserved = false;
static bool g_R2RMegaShootObservedEnabled = false;
static uint32_t g_R2RMegaShootObservedSeed = 0;

static void R2R_MegaShootResetForLevel()
{
    std::memset(g_R2RMegaShoots, 0, sizeof(g_R2RMegaShoots));
    std::memset(g_R2RMegaShootAnchors, 0, sizeof(g_R2RMegaShootAnchors));
    g_R2RMegaShootCount = 0;
    g_R2RMegaShootAnchorCount = 0;
    g_R2RMegaShootFrames = 0;
    g_R2RMegaShootApplied = false;
}

static bool R2R_MegaShootEntryAlreadyPresent(
    const R2R_MegaShootEntry* entries,
    unsigned int count,
    HIE_tdstSuperObject* superObject
)
{
    for (unsigned int i = 0; i < count; ++i)
    {
        if (entries[i].superObject == superObject)
            return true;
    }
    return false;
}

static void R2R_MegaShootFillEntry(
    R2R_MegaShootEntry& entry,
    HIE_tdstSuperObject* superObject,
    HIE_tdstEngineObject* actor
)
{
    GAM_tdstStandardGame* sg = actor->hStandardGame;

    entry.superObject = superObject;
    entry.actor = actor;
    entry.position = superObject->p_stGlobalMatrix->stPos;
    entry.personalType = sg->lObjectPersonalType;
    entry.customBits = sg->ulCustomBits;
    entry.miscFlags = sg->ucMiscFlags;

    const char* personalName = HIE_fn_szGetObjectPersonalName(superObject);
    if (personalName != nullptr)
        strncpy_s(entry.personal, personalName, _TRUNCATE);
    else
        strcpy_s(entry.personal, "(null)");
}

static void R2R_MegaShootTryCollect(HIE_tdstSuperObject* superObject)
{
    if (
        superObject == nullptr ||
        superObject->ulType != HIE_C_Type_Actor ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(superObject), sizeof(HIE_tdstSuperObject))
        )
        return;

    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(superObject);

    if (
        actor == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor), sizeof(HIE_tdstEngineObject)) ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->hStandardGame), sizeof(GAM_tdstStandardGame)) ||
        superObject->p_stGlobalMatrix == nullptr ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(superObject->p_stGlobalMatrix), sizeof(POS_tdstCompletePosition)) ||
        actor->hBrain == nullptr ||
        actor->hDynam != nullptr ||
        actor->hCollSet != nullptr ||
        actor->h3dData == nullptr
        )
        return;

    const char* familyName = HIE_fn_szGetObjectFamilyName(superObject);
    const char* modelName = HIE_fn_szGetObjectModelName(superObject);

    if (familyName == nullptr || modelName == nullptr)
        return;

    if (
        _stricmp(familyName, "megashoot") == 0 &&
        _stricmp(modelName, "ARG_MegaShoot") == 0
        )
    {
        if (
            g_R2RMegaShootCount < R2R_MEGASHOOT_MAX &&
            !R2R_MegaShootEntryAlreadyPresent(
                g_R2RMegaShoots,
                g_R2RMegaShootCount,
                superObject
            )
            )
        {
            R2R_MegaShootFillEntry(
                g_R2RMegaShoots[g_R2RMegaShootCount++],
                superObject,
                actor
            );
        }
        return;
    }

    if (
        _stricmp(familyName, "Lums") == 0 &&
        _stricmp(modelName, "CHR_lums_basic") == 0
        )
    {
        if (
            g_R2RMegaShootAnchorCount < R2R_MEGASHOOT_ANCHOR_MAX &&
            !R2R_MegaShootEntryAlreadyPresent(
                g_R2RMegaShootAnchors,
                g_R2RMegaShootAnchorCount,
                superObject
            )
            )
        {
            R2R_MegaShootFillEntry(
                g_R2RMegaShootAnchors[g_R2RMegaShootAnchorCount++],
                superObject,
                actor
            );
        }
    }
}

static void R2R_MegaShootCollectTreeRecursive(HIE_tdstSuperObject* root, int depth)
{
    if (
        root == nullptr ||
        depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))
        )
        return;

    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object == nullptr)
            continue;
        R2R_MegaShootTryCollect(object);
        R2R_MegaShootCollectTreeRecursive(object, depth + 1);
    }
}

static float R2R_MegaShootDistanceSquared(
    const MTH3D_tdstVector& a,
    const MTH3D_tdstVector& b
)
{
    const float dx = a.x - b.x;
    const float dy = a.y - b.y;
    const float dz = a.z - b.z;
    return dx * dx + dy * dy + dz * dz;
}

static bool R2R_MegaShootAnchorCompatible(
    const R2R_MegaShootEntry& pickup,
    const R2R_MegaShootEntry& anchor
)
{
    if (pickup.miscFlags != anchor.miscFlags)
        return false;

    if (
        (pickup.customBits & R2R_MEGASHOOT_CUSTOM_TAG_MASK) !=
        (anchor.customBits & R2R_MEGASHOOT_CUSTOM_TAG_MASK)
        )
        return false;

    const float distanceSquared =
        R2R_MegaShootDistanceSquared(pickup.position, anchor.position);

    const float maxDistanceSquared =
        R2R_MEGASHOOT_MAX_DISTANCE * R2R_MEGASHOOT_MAX_DISTANCE;

    return distanceSquared > 0.0001f && distanceSquared <= maxDistanceSquared;
}

static void R2R_MegaShootSortEntries(R2R_MegaShootEntry* entries, unsigned int count)
{
    for (unsigned int i = 0; i < count; ++i)
    {
        for (unsigned int j = i + 1; j < count; ++j)
        {
            const R2R_MegaShootEntry& a = entries[i];
            const R2R_MegaShootEntry& b = entries[j];
            bool swapNeeded = false;

            if (b.personalType < a.personalType)
                swapNeeded = true;
            else if (b.personalType == a.personalType)
            {
                if (b.position.x < a.position.x)
                    swapNeeded = true;
                else if (
                    b.position.x == a.position.x &&
                    b.position.y < a.position.y
                    )
                    swapNeeded = true;
                else if (
                    b.position.x == a.position.x &&
                    b.position.y == a.position.y &&
                    b.position.z < a.position.z
                    )
                    swapNeeded = true;
            }

            if (swapNeeded)
            {
                R2R_MegaShootEntry temp = entries[i];
                entries[i] = entries[j];
                entries[j] = temp;
            }
        }
    }
}

static bool R2R_MoveExistingActorTo(
    HIE_tdstSuperObject* superObject,
    const MTH3D_tdstVector& newGlobal
)
{
    if (
        superObject == nullptr ||
        superObject->p_stGlobalMatrix == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(superObject->p_stGlobalMatrix),
            sizeof(POS_tdstCompletePosition)
        )
        )
        return false;

    const MTH3D_tdstVector oldGlobal =
        superObject->p_stGlobalMatrix->stPos;

    const float dx = newGlobal.x - oldGlobal.x;
    const float dy = newGlobal.y - oldGlobal.y;
    const float dz = newGlobal.z - oldGlobal.z;

    superObject->p_stGlobalMatrix->stPos = newGlobal;

    if (
        superObject->p_stLocalMatrix != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(superObject->p_stLocalMatrix),
            sizeof(POS_tdstCompletePosition)
        )
        )
    {
        superObject->p_stLocalMatrix->stPos.x += dx;
        superObject->p_stLocalMatrix->stPos.y += dy;
        superObject->p_stLocalMatrix->stPos.z += dz;
    }

    return true;
}

static void R2R_MegaShootApply(const char* levelName)
{
    if (g_R2RMegaShootApplied)
        return;

    g_R2RMegaShootApplied = true;

    R2R_MegaShootSortEntries(g_R2RMegaShoots, g_R2RMegaShootCount);
    R2R_MegaShootSortEntries(g_R2RMegaShootAnchors, g_R2RMegaShootAnchorCount);

    FILE* f = nullptr;
    fopen_s(&f, R2R_SPECIAL_PICKUP_REPORT, "w");

    if (f != nullptr)
    {
        fprintf(
            f,
            "RAYMAN 2 RANDOMIZER\n"
            "%s - CONSERVATIVE NEARBY MEGASHOOT RELOCATION\n"
            "============================================================\n\n"
            "Level : %s\n"
            "Seed  : %u\n"
            "Items : ON\n\n"
            "PICKUP CLASS\n"
            "------------------------------------------------------------\n"
            "Pickup       : megashoot / ARG_MegaShoot\n"
            "Anchor       : Lums / CHR_lums_basic\n"
            "MegaShoots   : %u\n"
            "Lum anchors  : %u\n"
            "Max distance : %.1f world units\n"
            "Compatibility: same MiscFlags + same (CustomBits & 0x%08lX)\n\n"
            "This is a local safety test. No actor/model/Brain/script is replaced.\n"
            "Only a MegaShoot and one nearby compatible Lum trade positions.\n\n",
            VERSION,
            levelName != nullptr ? levelName : "(unknown)",
            g_R2RConfig.seed,
            g_R2RMegaShootCount,
            g_R2RMegaShootAnchorCount,
            R2R_MEGASHOOT_MAX_DISTANCE,
            R2R_MEGASHOOT_CUSTOM_TAG_MASK
        );
    }

    bool usedAnchor[R2R_MEGASHOOT_ANCHOR_MAX] = {};
    unsigned int relocated = 0;

    for (unsigned int m = 0; m < g_R2RMegaShootCount; ++m)
    {
        R2R_MegaShootEntry& pickup = g_R2RMegaShoots[m];
        unsigned int candidates[R2R_MEGASHOOT_ANCHOR_MAX] = {};
        unsigned int candidateCount = 0;

        for (unsigned int a = 0; a < g_R2RMegaShootAnchorCount; ++a)
        {
            if (usedAnchor[a])
                continue;

            if (R2R_MegaShootAnchorCompatible(pickup, g_R2RMegaShootAnchors[a]))
                candidates[candidateCount++] = a;
        }

        if (candidateCount == 0)
        {
            if (f != nullptr)
            {
                fprintf(
                    f,
                    "[%02u] %s custom=0x%08lX misc=0x%02X\n"
                    "     NO SAFE NEARBY LUM ANCHOR - unchanged\n\n",
                    m,
                    pickup.personal,
                    pickup.customBits,
                    (unsigned int)pickup.miscFlags
                );
            }
            continue;
        }

        const uint32_t roll = R2R_RollU32(
            "Items.MegaShoot.Nearby",
            levelName,
            0x14C00000u + m
        );
        const unsigned int chosen = candidates[roll % candidateCount];
        R2R_MegaShootEntry& anchor = g_R2RMegaShootAnchors[chosen];

        const MTH3D_tdstVector pickupOld =
            pickup.superObject->p_stGlobalMatrix->stPos;
        const MTH3D_tdstVector anchorOld =
            anchor.superObject->p_stGlobalMatrix->stPos;
        const float distance = std::sqrt(
            R2R_MegaShootDistanceSquared(pickupOld, anchorOld)
        );

        const bool pickupMoved =
            R2R_MoveExistingActorTo(pickup.superObject, anchorOld);
        const bool anchorMoved =
            pickupMoved && R2R_MoveExistingActorTo(anchor.superObject, pickupOld);

        if (!anchorMoved)
        {
            // Best-effort rollback if the second move could not be performed.
            if (pickupMoved)
                R2R_MoveExistingActorTo(pickup.superObject, pickupOld);

            if (f != nullptr)
            {
                fprintf(
                    f,
                    "[%02u] %s -> %s\n"
                    "     MOVE FAILED - rollback attempted\n\n",
                    m,
                    pickup.personal,
                    anchor.personal
                );
            }
            continue;
        }

        usedAnchor[chosen] = true;
        ++relocated;

        if (f != nullptr)
        {
            fprintf(
                f,
                "[%02u] MEGASHOOT %s custom=0x%08lX misc=0x%02X\n"
                "     candidates : %u\n"
                "     chosen Lum : %s custom=0x%08lX misc=0x%02X\n"
                "     distance   : %.3f\n"
                "     MegaShoot  : %.3f %.3f %.3f -> %.3f %.3f %.3f\n"
                "     Lum anchor : %.3f %.3f %.3f -> %.3f %.3f %.3f\n\n",
                m,
                pickup.personal,
                pickup.customBits,
                (unsigned int)pickup.miscFlags,
                candidateCount,
                anchor.personal,
                anchor.customBits,
                (unsigned int)anchor.miscFlags,
                distance,
                pickupOld.x, pickupOld.y, pickupOld.z,
                anchorOld.x, anchorOld.y, anchorOld.z,
                anchorOld.x, anchorOld.y, anchorOld.z,
                pickupOld.x, pickupOld.y, pickupOld.z
            );
        }
    }

    if (f != nullptr)
    {
        fprintf(
            f,
            "============================================================\n"
            "RESULT\n"
            "------------------------------------------------------------\n"
            "MegaShoots found     : %u\n"
            "MegaShoots relocated : %u\n"
            "No actors created/deleted.\n",
            g_R2RMegaShootCount,
            relocated
        );
        fclose(f);
    }
}

static void R2R_MegaShootRelocationTick()
{
    const bool moduleEnabled = g_R2RConfig.enabled && g_R2RConfig.items;

    if (!g_R2RMegaShootConfigObserved)
    {
        g_R2RMegaShootConfigObserved = true;
        g_R2RMegaShootObservedEnabled = moduleEnabled;
        g_R2RMegaShootObservedSeed = g_R2RConfig.seed;
    }
    else if (
        g_R2RMegaShootObservedEnabled != moduleEnabled ||
        g_R2RMegaShootObservedSeed != g_R2RConfig.seed
        )
    {
        R2R_MegaShootResetForLevel();
        g_R2RMegaShootWorldMarker = nullptr;
        g_R2RMegaShootLevel[0] = '\0';
        g_R2RMegaShootObservedEnabled = moduleEnabled;
        g_R2RMegaShootObservedSeed = g_R2RConfig.seed;
    }

    if (!moduleEnabled)
        return;

    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr
        )
        return;

    const char* levelName = GAM_g_stEngineStructure->szLevelName;

    if (levelName != nullptr && _stricmp(levelName, "Menu") == 0)
        return;

    HIE_tdstSuperObject* activeRoot = *GAM_g_p_stDynamicWorld;

    const bool newLevel =
        g_R2RMegaShootWorldMarker != activeRoot ||
        g_R2RMegaShootLevel[0] == '\0' ||
        levelName == nullptr ||
        _stricmp(g_R2RMegaShootLevel, levelName) != 0;

    if (newLevel)
    {
        R2R_MegaShootResetForLevel();
        g_R2RMegaShootWorldMarker = activeRoot;

        if (levelName != nullptr)
            strncpy_s(g_R2RMegaShootLevel, levelName, _TRUNCATE);
        else
            strcpy_s(g_R2RMegaShootLevel, "(unknown)");
    }

    if (g_R2RMegaShootApplied)
        return;

    ++g_R2RMegaShootFrames;
    if (g_R2RMegaShootFrames < R2R_MEGASHOOT_DELAY_FRAMES)
        return;

    g_R2RMegaShootCount = 0;
    g_R2RMegaShootAnchorCount = 0;

    R2R_MegaShootCollectTreeRecursive(activeRoot, 0);

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr
        )
    {
        R2R_MegaShootCollectTreeRecursive(
            *GAM_g_p_stInactiveDynamicWorld,
            0
        );
    }

    R2R_MegaShootApply(g_R2RMegaShootLevel);
}



// ============================================================
// PARKED EXPERIMENT - CAGE POSITION SHUFFLER (v0.0.14d.0, NOT CALLED)
//
// For the first real Items implementation we deliberately use a very narrow
// compatibility class discovered in Rodeo_10: Cage / ARG_CageLums.
// We DO NOT replace models or scripts.  We only permute the world positions
// of existing ARG_CageLums actors among other positions that already held an
// ARG_CageLums actor in the same level.  Count, model, Personal type, Brain,
// collisions and scripts remain attached to their original Actor.
// ============================================================

static const char* R2R_ITEMS_REPORT =
"Rayman2Randomizer_Items.txt";
static const unsigned int R2R_ITEM_SHUFFLE_MAX = 128;
static const unsigned int R2R_ITEM_SHUFFLE_DELAY_FRAMES = 60;

struct R2R_ItemShuffleEntry
{
    HIE_tdstSuperObject* superObject;
    HIE_tdstEngineObject* actor;
    MTH3D_tdstVector originalGlobal;
    MTH3D_tdstVector originalLocal;
    bool hasLocal;
    char personal[128];
};

static R2R_ItemShuffleEntry
g_R2RItemShuffleEntries[R2R_ITEM_SHUFFLE_MAX] = {};
static unsigned int g_R2RItemShuffleCount = 0;
static unsigned int g_R2RItemShuffleFrames = 0;
static bool g_R2RItemShuffleApplied = false;
static HIE_tdstSuperObject* g_R2RItemShuffleWorldMarker = nullptr;
static char g_R2RItemShuffleLevel[64] = {};
static bool g_R2RItemShuffleConfigObserved = false;
static bool g_R2RItemShuffleObservedEnabled = false;
static uint32_t g_R2RItemShuffleObservedSeed = 0;

static void R2R_ItemShuffleResetForLevel()
{
    std::memset(
        g_R2RItemShuffleEntries,
        0,
        sizeof(g_R2RItemShuffleEntries)
    );
    g_R2RItemShuffleCount = 0;
    g_R2RItemShuffleFrames = 0;
    g_R2RItemShuffleApplied = false;
}

static bool R2R_ItemShuffleAlreadyCollected(
    HIE_tdstSuperObject* superObject
)
{
    for (unsigned int i = 0; i < g_R2RItemShuffleCount; ++i)
    {
        if (g_R2RItemShuffleEntries[i].superObject == superObject)
            return true;
    }
    return false;
}

static void R2R_ItemShuffleTryCollect(
    HIE_tdstSuperObject* superObject
)
{
    if (
        superObject == nullptr ||
        superObject->ulType != HIE_C_Type_Actor ||
        g_R2RItemShuffleCount >= R2R_ITEM_SHUFFLE_MAX ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(superObject),
            sizeof(HIE_tdstSuperObject)
        ) ||
        R2R_ItemShuffleAlreadyCollected(superObject)
        )
    {
        return;
    }

    HIE_tdstEngineObject* actor = HIE_M_hSuperObjectGetActor(superObject);
    if (
        actor == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actor),
            sizeof(HIE_tdstEngineObject)
        ) ||
        superObject->p_stGlobalMatrix == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(superObject->p_stGlobalMatrix),
            sizeof(POS_tdstCompletePosition)
        )
        )
    {
        return;
    }

    const char* familyName = HIE_fn_szGetObjectFamilyName(superObject);
    const char* modelName = HIE_fn_szGetObjectModelName(superObject);

    // Strict compatibility class.  In particular, Cage / OLP_Grille is NOT
    // included even though it shares the Cage family.
    if (
        familyName == nullptr ||
        modelName == nullptr ||
        _stricmp(familyName, "Cage") != 0 ||
        _stricmp(modelName, "ARG_CageLums") != 0
        )
    {
        return;
    }

    R2R_ItemShuffleEntry& entry =
        g_R2RItemShuffleEntries[g_R2RItemShuffleCount++];

    entry.superObject = superObject;
    entry.actor = actor;
    entry.originalGlobal = superObject->p_stGlobalMatrix->stPos;
    entry.hasLocal = false;

    if (
        superObject->p_stLocalMatrix != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(superObject->p_stLocalMatrix),
            sizeof(POS_tdstCompletePosition)
        )
        )
    {
        entry.originalLocal = superObject->p_stLocalMatrix->stPos;
        entry.hasLocal = true;
    }

    const char* personalName = HIE_fn_szGetObjectPersonalName(superObject);
    if (personalName != nullptr)
        strncpy_s(entry.personal, personalName, _TRUNCATE);
    else
        strcpy_s(entry.personal, "(null)");
}

static void R2R_ItemShuffleCollectTreeRecursive(
    HIE_tdstSuperObject* root,
    int depth
)
{
    if (
        root == nullptr ||
        depth > 64 ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(root),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return;
    }

    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object == nullptr)
            continue;

        R2R_ItemShuffleTryCollect(object);
        R2R_ItemShuffleCollectTreeRecursive(object, depth + 1);
    }
}

static void R2R_ItemShuffleWriteNoopReport(
    const char* levelName,
    const char* reason
)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_ITEMS_REPORT, "w");
    if (f == nullptr)
        return;

    fprintf(
        f,
        "RAYMAN 2 RANDOMIZER\n"
        "%s - FIRST ITEM SHUFFLER\n"
        "============================================================\n\n"
        "Level : %s\n"
        "Seed  : %u\n"
        "Items : ON\n\n"
        "COMPATIBILITY CLASS\n"
        "------------------------------------------------------------\n"
        "Family / Model : Cage / ARG_CageLums\n"
        "Found          : %u\n"
        "Result         : %s\n\n"
        "No actors were created or deleted.\n",
        VERSION,
        levelName != nullptr ? levelName : "(unknown)",
        g_R2RConfig.seed,
        g_R2RItemShuffleCount,
        reason != nullptr ? reason : "No shuffle"
    );

    fclose(f);
}

static void R2R_ItemShuffleApply(const char* levelName)
{
    if (g_R2RItemShuffleApplied)
        return;

    g_R2RItemShuffleApplied = true;

    if (g_R2RItemShuffleCount < 2)
    {
        R2R_ItemShuffleWriteNoopReport(
            levelName,
            "Need at least two compatible cages; nothing changed."
        );
        return;
    }

    unsigned int permutation[R2R_ITEM_SHUFFLE_MAX] = {};
    for (unsigned int i = 0; i < g_R2RItemShuffleCount; ++i)
        permutation[i] = i;

    // Deterministic Fisher-Yates shuffle.  This stream is independent from
    // Stats and from future item categories.
    for (unsigned int i = g_R2RItemShuffleCount - 1; i > 0; --i)
    {
        const uint32_t r = R2R_RollU32(
            "Items.CageShuffle",
            levelName,
            0xCA600000u + i
        );
        const unsigned int j = r % (i + 1);
        const unsigned int temp = permutation[i];
        permutation[i] = permutation[j];
        permutation[j] = temp;
    }

    // Avoid a complete no-op when a level has multiple eligible cages.  This
    // still stays deterministic: every seed that lands on the identity
    // permutation gets the same fixed first-two swap.
    bool anyMoved = false;
    for (unsigned int i = 0; i < g_R2RItemShuffleCount; ++i)
    {
        if (permutation[i] != i)
        {
            anyMoved = true;
            break;
        }
    }
    if (!anyMoved)
    {
        const unsigned int temp = permutation[0];
        permutation[0] = permutation[1];
        permutation[1] = temp;
    }

    FILE* f = nullptr;
    fopen_s(&f, R2R_ITEMS_REPORT, "w");
    if (f != nullptr)
    {
        fprintf(
            f,
            "RAYMAN 2 RANDOMIZER\n"
            "%s - FIRST ITEM SHUFFLER\n"
            "============================================================\n\n"
            "Level : %s\n"
            "Seed  : %u\n"
            "Items : ON\n\n"
            "MODE\n"
            "------------------------------------------------------------\n"
            "Compatibility class : Cage / ARG_CageLums\n"
            "Compatible actors   : %u\n"
            "Operation           : POSITION PERMUTATION ONLY\n"
            "Safety              : no spawn, no delete, no model/script swap\n\n"
            "SHUFFLE\n"
            "------------------------------------------------------------\n",
            VERSION,
            levelName != nullptr ? levelName : "(unknown)",
            g_R2RConfig.seed,
            g_R2RItemShuffleCount
        );
    }

    for (unsigned int i = 0; i < g_R2RItemShuffleCount; ++i)
    {
        R2R_ItemShuffleEntry& entry = g_R2RItemShuffleEntries[i];
        const R2R_ItemShuffleEntry& target =
            g_R2RItemShuffleEntries[permutation[i]];

        if (
            entry.superObject == nullptr ||
            entry.superObject->p_stGlobalMatrix == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject->p_stGlobalMatrix),
                sizeof(POS_tdstCompletePosition)
            )
            )
        {
            if (f != nullptr)
            {
                fprintf(
                    f,
                    "[%02u] %s : SKIPPED (matrix unavailable)\n",
                    i,
                    entry.personal
                );
            }
            continue;
        }

        const MTH3D_tdstVector oldGlobal =
            entry.superObject->p_stGlobalMatrix->stPos;
        const MTH3D_tdstVector newGlobal = target.originalGlobal;

        const float dx = newGlobal.x - oldGlobal.x;
        const float dy = newGlobal.y - oldGlobal.y;
        const float dz = newGlobal.z - oldGlobal.z;

        entry.superObject->p_stGlobalMatrix->stPos = newGlobal;

        if (
            entry.superObject->p_stLocalMatrix != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(entry.superObject->p_stLocalMatrix),
                sizeof(POS_tdstCompletePosition)
            )
            )
        {
            entry.superObject->p_stLocalMatrix->stPos.x += dx;
            entry.superObject->p_stLocalMatrix->stPos.y += dy;
            entry.superObject->p_stLocalMatrix->stPos.z += dz;
        }

        if (f != nullptr)
        {
            fprintf(
                f,
                "[%02u] %s\n"
                "     from %.3f %.3f %.3f\n"
                "       to %.3f %.3f %.3f\n"
                "     target slot=%u (%s)\n",
                i,
                entry.personal,
                oldGlobal.x,
                oldGlobal.y,
                oldGlobal.z,
                newGlobal.x,
                newGlobal.y,
                newGlobal.z,
                permutation[i],
                target.personal
            );
        }
    }

    if (f != nullptr)
    {
        fprintf(
            f,
            "\nRESULT: cage position shuffle applied successfully.\n"
            "Same seed + same level => same permutation.\n"
        );
        fclose(f);
    }
}

static void R2R_ItemShuffleTick()
{
    const bool moduleEnabled =
        g_R2RConfig.enabled &&
        g_R2RConfig.items;

    if (!g_R2RItemShuffleConfigObserved)
    {
        g_R2RItemShuffleConfigObserved = true;
        g_R2RItemShuffleObservedEnabled = moduleEnabled;
        g_R2RItemShuffleObservedSeed = g_R2RConfig.seed;
    }
    else if (
        g_R2RItemShuffleObservedEnabled != moduleEnabled ||
        g_R2RItemShuffleObservedSeed != g_R2RConfig.seed
        )
    {
        R2R_ItemShuffleResetForLevel();
        g_R2RItemShuffleWorldMarker = nullptr;
        g_R2RItemShuffleLevel[0] = '\0';
        g_R2RItemShuffleObservedEnabled = moduleEnabled;
        g_R2RItemShuffleObservedSeed = g_R2RConfig.seed;
    }

    if (!moduleEnabled)
        return;

    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr
        )
    {
        return;
    }

    const char* levelName = GAM_g_stEngineStructure->szLevelName;
    HIE_tdstSuperObject* activeRoot = *GAM_g_p_stDynamicWorld;

    const bool newLevel =
        g_R2RItemShuffleWorldMarker != activeRoot ||
        g_R2RItemShuffleLevel[0] == '\0' ||
        levelName == nullptr ||
        _stricmp(g_R2RItemShuffleLevel, levelName) != 0;

    if (newLevel)
    {
        R2R_ItemShuffleResetForLevel();
        g_R2RItemShuffleWorldMarker = activeRoot;

        if (levelName != nullptr)
            strncpy_s(g_R2RItemShuffleLevel, levelName, _TRUNCATE);
        else
            strcpy_s(g_R2RItemShuffleLevel, "(unknown)");
    }

    if (g_R2RItemShuffleApplied)
        return;

    ++g_R2RItemShuffleFrames;
    if (g_R2RItemShuffleFrames < R2R_ITEM_SHUFFLE_DELAY_FRAMES)
        return;

    g_R2RItemShuffleCount = 0;
    R2R_ItemShuffleCollectTreeRecursive(activeRoot, 0);

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr
        )
    {
        R2R_ItemShuffleCollectTreeRecursive(
            *GAM_g_p_stInactiveDynamicWorld,
            0
        );
    }

    R2R_ItemShuffleApply(g_R2RItemShuffleLevel);
}

