// ============================================================
// LITTLE ENDIAN
// ============================================================

uint32_t ReadLE32(const uint8_t* p)
{
    return
        static_cast<uint32_t>(p[0]) |
        (static_cast<uint32_t>(p[1]) << 8) |
        (static_cast<uint32_t>(p[2]) << 16) |
        (static_cast<uint32_t>(p[3]) << 24);
}

void WriteLE32(uint8_t* p, uint32_t value)
{
    p[0] = static_cast<uint8_t>(value & 0xFF);
    p[1] = static_cast<uint8_t>((value >> 8) & 0xFF);
    p[2] = static_cast<uint8_t>((value >> 16) & 0xFF);
    p[3] = static_cast<uint8_t>((value >> 24) & 0xFF);
}


// ============================================================
// FILE HELPERS
// ============================================================

uint64_t GetOpenFileSize(FILE* file)
{
    if (file == nullptr)
    {
        return 0;
    }

    const __int64 oldPosition = _ftelli64(file);

    _fseeki64(file, 0, SEEK_END);

    const __int64 size = _ftelli64(file);

    _fseeki64(file, oldPosition, SEEK_SET);

    return
        size > 0
        ? static_cast<uint64_t>(size)
        : 0;
}

bool ReadWholeFile(const char* path, std::vector<uint8_t>& output)
{
    output.clear();

    FILE* file = nullptr;

    fopen_s(&file, path, "rb");

    if (file == nullptr)
    {
        return false;
    }

    const uint64_t size = GetOpenFileSize(file);

    if (
        size == 0 ||
        size > 256ULL * 1024ULL * 1024ULL
        )
    {
        fclose(file);
        return false;
    }

    output.resize(static_cast<size_t>(size));

    const size_t bytesRead =
        fread(
            output.data(),
            1,
            output.size(),
            file
        );

    fclose(file);

    return
        bytesRead == output.size();
}


// ============================================================
// SNA DECODE / PARSE
// ============================================================

uint32_t RaymanNextMask(uint32_t currentMask)
{
    const uint32_t value =
        currentMask ^
        0x075BD924u;

    return
        (16807u * value) -
        (
            0x7FFFFFFFu *
            (value / 0x0001F31Du)
            );
}

bool DecodeSna(
    const std::vector<uint8_t>& raw,
    std::vector<uint8_t>& decoded
)
{
    decoded.clear();

    if (raw.size() < 5)
    {
        return false;
    }

    uint32_t mask =
        ReadLE32(
            raw.data()
        );

    decoded.resize(
        raw.size() - 4
    );

    for (
        size_t i = 4;
        i < raw.size();
        i++
        )
    {
        decoded[i - 4] =
            raw[i] ^
            static_cast<uint8_t>(
                (mask >> 8) &
                0xFF
                );

        mask =
            RaymanNextMask(mask);
    }

    return true;
}

bool ParseSna(
    const std::vector<uint8_t>& data,
    std::vector<SnaBlock>& blocks
)
{
    blocks.clear();

    size_t position = 0;

    while (position < data.size())
    {
        if (
            data.size() -
            position <
            7
            )
        {
            return false;
        }

        SnaBlock block = {};

        block.moduleId =
            data[position++];

        block.blockId =
            data[position++];

        block.unk1 =
            data[position++];

        const uint32_t baseRaw =
            ReadLE32(
                &data[position]
            );

        position += 4;

        std::memcpy(
            &block.baseInMemory,
            &baseRaw,
            sizeof(block.baseInMemory)
        );

        if (block.baseInMemory != -1)
        {
            if (
                data.size() -
                position <
                16
                )
            {
                return false;
            }

            block.unk2 =
                ReadLE32(
                    &data[position]
                );

            position += 4;

            block.unk3 =
                ReadLE32(
                    &data[position]
                );

            position += 4;

            block.maxPosMinus9 =
                ReadLE32(
                    &data[position]
                );

            position += 4;

            block.size =
                ReadLE32(
                    &data[position]
                );

            position += 4;

            block.dataOffset =
                position;

            if (
                block.size >
                data.size() -
                position
                )
            {
                return false;
            }

            position +=
                block.size;
        }
        else
        {
            block.dataOffset =
                position;
        }

        blocks.push_back(block);

        if (blocks.size() > 4096)
        {
            return false;
        }
    }

    return
        !blocks.empty();
}

bool LoadWaterSna(LoadedSna& output)
{
    output = {};

    std::vector<uint8_t> raw;

    if (
        !ReadWholeFile(
            WATER_SNA,
            raw
        )
        )
    {
        return false;
    }

    if (
        !DecodeSna(
            raw,
            output.data
        )
        )
    {
        return false;
    }

    if (
        !ParseSna(
            output.data,
            output.blocks
        )
        )
    {
        return false;
    }

    output.loaded =
        true;

    return true;
}

const SnaBlock* FindDataBlock(
    const LoadedSna& sna,
    uint8_t moduleId,
    uint8_t blockId
)
{
    for (
        const SnaBlock& block :
        sna.blocks
        )
    {
        if (
            block.moduleId == moduleId &&
            block.blockId == blockId &&
            block.size > 0
            )
        {
            return
                &block;
        }
    }

    return nullptr;
}

const SnaBlock* FindAnyBlock(
    const LoadedSna& sna,
    uint8_t moduleId,
    uint8_t blockId
)
{
    const SnaBlock* descriptor =
        nullptr;

    for (
        const SnaBlock& block :
        sna.blocks
        )
    {
        if (
            block.moduleId != moduleId ||
            block.blockId != blockId
            )
        {
            continue;
        }

        if (block.size > 0)
        {
            return
                &block;
        }

        descriptor =
            &block;
    }

    return descriptor;
}


// ============================================================
// LEVELS0.DAT RELOCATION READER
// ============================================================

bool ReadRawU32(
    FILE* file,
    uint32_t& output
)
{
    uint8_t bytes[4];

    if (
        fread(
            bytes,
            1,
            4,
            file
        ) != 4
        )
    {
        return false;
    }

    output =
        ReadLE32(bytes);

    return true;
}

bool ComputeDatRelocationOffset(
    FILE* file,
    uint8_t requestedLevelId,
    uint8_t relocationType,
    uint32_t& outputOffset
)
{
    if (file == nullptr)
    {
        return false;
    }

    _fseeki64(
        file,
        0,
        SEEK_SET
    );

    uint32_t field0;
    uint32_t field4;
    uint32_t field8;
    uint32_t fieldC;

    if (
        !ReadRawU32(file, field0) ||
        !ReadRawU32(file, field4) ||
        !ReadRawU32(file, field8) ||
        !ReadRawU32(file, fieldC)
        )
    {
        return false;
    }

    uint32_t number;

    if (!ReadRawU32(file, number))
    {
        return false;
    }

    field0 += field8;
    field4 += fieldC;

    if (!ReadRawU32(file, number))
    {
        return false;
    }

    const uint32_t value0 =
        field4 ^
        (number - field0);

    field0 += field8;
    field4 += fieldC;

    if (!ReadRawU32(file, number))
    {
        return false;
    }

    const uint32_t levelCount =
        (
            field4 ^
            (number - field0)
            ) >>
        2;

    field0 += field8;
    field4 += fieldC;

    if (!ReadRawU32(file, number))
    {
        return false;
    }

    field0 += field8;
    field4 += fieldC;

    if (!ReadRawU32(file, number))
    {
        return false;
    }

    const uint32_t value2 =
        field4 ^
        (number - field0);

    (void)value2;

    field0 += field8;
    field4 += fieldC;

    if (!ReadRawU32(file, number))
    {
        return false;
    }

    const uint32_t value3 =
        field4 ^
        (number - field0);

    (void)value3;

    field0 += field8;
    field4 += fieldC;

    if (!ReadRawU32(file, number))
    {
        return false;
    }

    const uint32_t value4 =
        field4 ^
        (number - field0);

    field0 += field8;
    field4 += fieldC;

    if (!ReadRawU32(file, number))
    {
        return false;
    }

    const uint32_t value5 =
        field4 ^
        (number - field0);

    if (levelCount == 0)
    {
        return false;
    }

    const uint8_t levelId =
        static_cast<uint8_t>(
            requestedLevelId %
            levelCount
            );

    relocationType &=
        3;

    const uint32_t tableIndex =
        (4u * levelId) +
        relocationType;

    const double fraction =
        std::floor(
            std::fmod(
                1.06913,
                1.0
            ) *
            1000000.0
        ) /
        1000000.0;

    const uint64_t value14 =
        static_cast<uint64_t>(
            std::floor(
                static_cast<double>(
                    value0
                    ) *
                fraction
            )
            );

    const uint64_t secondaryHeader =
        static_cast<uint64_t>(
            value4
            ) +
        (
            static_cast<uint64_t>(
                value5
                ) *
            value14
            );

    const uint64_t fileSize =
        GetOpenFileSize(file);

    if (
        secondaryHeader +
        16 >
        fileSize
        )
    {
        return false;
    }

    _fseeki64(
        file,
        static_cast<__int64>(
            secondaryHeader
            ),
        SEEK_SET
    );

    uint32_t sub0;
    uint32_t sub4;
    uint32_t sub8;
    uint32_t subC;

    if (
        !ReadRawU32(file, sub0) ||
        !ReadRawU32(file, sub4) ||
        !ReadRawU32(file, sub8) ||
        !ReadRawU32(file, subC)
        )
    {
        return false;
    }

    sub0 +=
        tableIndex *
        sub8;

    sub4 +=
        tableIndex *
        subC;

    const uint64_t entryOffset =
        secondaryHeader +
        16ULL +
        (
            4ULL *
            tableIndex
            );

    if (
        entryOffset +
        4 >
        fileSize
        )
    {
        return false;
    }

    _fseeki64(
        file,
        static_cast<__int64>(
            entryOffset
            ),
        SEEK_SET
    );

    uint32_t encoded;

    if (!ReadRawU32(file, encoded))
    {
        return false;
    }

    outputOffset =
        sub4 ^
        (encoded - sub0);

    return
        outputOffset <
        fileSize;
}

class MaskedReader
{
public:

    FILE* file;
    uint32_t mask;

    MaskedReader(
        FILE* input,
        uint32_t initialMask
    )
        :
        file(input),
        mask(initialMask)
    {
    }

    bool ReadByte(uint8_t& output)
    {
        uint8_t raw;

        if (
            fread(
                &raw,
                1,
                1,
                file
            ) != 1
            )
        {
            return false;
        }

        output =
            raw ^
            static_cast<uint8_t>(
                (mask >> 8) &
                0xFF
                );

        mask =
            RaymanNextMask(mask);

        return true;
    }

    bool ReadU32(uint32_t& output)
    {
        uint8_t bytes[4];

        for (
            int i = 0;
            i < 4;
            i++
            )
        {
            if (!ReadByte(bytes[i]))
            {
                return false;
            }
        }

        output =
            ReadLE32(bytes);

        return true;
    }
};

uint32_t BuildRelocationMask(
    uint8_t levelId,
    uint8_t relocationType
)
{
    const uint8_t byte2 =
        0;

    const uint8_t byte3 =
        static_cast<uint8_t>(
            ~byte2
            );

    const uint32_t initial =
        static_cast<uint32_t>(
            levelId
            ) |
        (
            static_cast<uint32_t>(
                relocationType
                ) <<
            8
            ) |
        (
            static_cast<uint32_t>(
                byte2
                ) <<
            16
            ) |
        (
            static_cast<uint32_t>(
                byte3
                ) <<
            24
            );

    return
        RaymanNextMask(initial);
}

bool LoadRelocationTable(
    uint8_t type,
    RelocationTable& output
)
{
    output = {};
    output.type = type;

    FILE* file = nullptr;

    fopen_s(
        &file,
        LEVELS_DAT,
        "rb"
    );

    if (file == nullptr)
    {
        return false;
    }

    uint32_t offset = 0;

    if (
        !ComputeDatRelocationOffset(
            file,
            WATER_DAT_ID,
            type,
            offset
        )
        )
    {
        fclose(file);
        return false;
    }

    output.datOffset =
        offset;

    _fseeki64(
        file,
        offset,
        SEEK_SET
    );

    MaskedReader reader(
        file,
        BuildRelocationMask(
            WATER_DAT_ID,
            type
        )
    );

    uint32_t prefix;

    if (!reader.ReadU32(prefix))
    {
        fclose(file);
        return false;
    }

    uint8_t blockCount;

    if (!reader.ReadByte(blockCount))
    {
        fclose(file);
        return false;
    }

    uint32_t secondary;

    if (!reader.ReadU32(secondary))
    {
        fclose(file);
        return false;
    }

    if (
        blockCount == 0 ||
        blockCount > 200
        )
    {
        fclose(file);
        return false;
    }

    for (
        uint32_t b = 0;
        b < blockCount;
        b++
        )
    {
        RelocationBlock block = {};
        uint32_t pointerCount;

        if (
            !reader.ReadByte(
                block.moduleId
            ) ||
            !reader.ReadByte(
                block.blockId
            ) ||
            !reader.ReadU32(
                pointerCount
            )
            )
        {
            fclose(file);
            return false;
        }

        if (pointerCount > 5000000)
        {
            fclose(file);
            return false;
        }

        block.pointers.reserve(
            pointerCount
        );

        for (
            uint32_t i = 0;
            i < pointerCount;
            i++
            )
        {
            RelocationPointer pointer = {};

            if (
                !reader.ReadU32(
                    pointer.offsetInMemory
                ) ||
                !reader.ReadByte(
                    pointer.targetModuleId
                ) ||
                !reader.ReadByte(
                    pointer.targetBlockId
                ) ||
                !reader.ReadByte(
                    pointer.byte6
                ) ||
                !reader.ReadByte(
                    pointer.byte7
                )
                )
            {
                fclose(file);
                return false;
            }

            block.pointers.push_back(
                pointer
            );
        }

        output.blocks.push_back(
            block
        );
    }

    fclose(file);

    output.loaded =
        true;

    return true;
}


// ============================================================
// SAFE PROCESS MEMORY / MMG
// ============================================================

bool SafeReadMemory(
    const void* address,
    void* destination,
    size_t size
)
{
    if (
        address == nullptr ||
        destination == nullptr ||
        size == 0
        )
    {
        return false;
    }

    SIZE_T bytesRead = 0;

    const BOOL result =
        ReadProcessMemory(
            GetCurrentProcess(),
            address,
            destination,
            size,
            &bytesRead
        );

    return
        result != FALSE &&
        bytesRead == size;
}

bool ReadMmgBlock(
    uint8_t moduleId,
    uint8_t blockId,
    tdstBlockInfoPriv& output
)
{
    std::memset(
        &output,
        0,
        sizeof(output)
    );

    if (
        g_a_p_stMmgModuleBlocksInfo ==
        nullptr
        )
    {
        return false;
    }

    tdstBlockInfoPriv* moduleBlocks =
        nullptr;

    const uintptr_t moduleSlot =
        reinterpret_cast<uintptr_t>(
            g_a_p_stMmgModuleBlocksInfo
            ) +
        (
            static_cast<uintptr_t>(
                moduleId
                ) *
            sizeof(
                tdstBlockInfoPriv*
                )
            );

    if (
        !SafeReadMemory(
            reinterpret_cast<const void*>(
                moduleSlot
                ),
            &moduleBlocks,
            sizeof(moduleBlocks)
        )
        )
    {
        return false;
    }

    if (moduleBlocks == nullptr)
    {
        return false;
    }

    const uintptr_t blockAddress =
        reinterpret_cast<uintptr_t>(
            moduleBlocks
            ) +
        (
            static_cast<uintptr_t>(
                blockId
                ) *
            sizeof(
                tdstBlockInfoPriv
                )
            );

    return
        SafeReadMemory(
            reinterpret_cast<const void*>(
                blockAddress
                ),
            &output,
            sizeof(output)
        );
}

bool AddressInsideRuntimeBlock(
    uintptr_t address,
    const tdstBlockInfoPriv& block
)
{
    const uintptr_t begin =
        reinterpret_cast<uintptr_t>(
            block.p_cBeginBlock
            );

    const uintptr_t end =
        reinterpret_cast<uintptr_t>(
            block.p_cEndBlock
            );

    const uintptr_t maxMem =
        reinterpret_cast<uintptr_t>(
            block.p_cMaxMem
            );

    const uintptr_t upper =
        end > maxMem
        ? end
        : maxMem;

    if (
        begin == 0 ||
        upper <= begin
        )
    {
        return false;
    }

    return
        address >= begin &&
        address < upper;
}


// ============================================================
// PRIVATE ARENA RELOCATION
// ============================================================

ResolveResult ResolveArenaTarget(
    const LoadedSna& donor,
    uint8_t* arena,
    size_t arenaSize,
    uint8_t targetModuleId,
    uint8_t targetBlockId,
    uint32_t oldValue
)
{
    ResolveResult result = {};
    result.kind = TARGET_FAILED;

    const SnaBlock* target =
        FindAnyBlock(
            donor,
            targetModuleId,
            targetBlockId
        );

    if (target == nullptr)
    {
        return result;
    }

    const uint32_t donorBase =
        static_cast<uint32_t>(
            target->baseInMemory
            );

    if (oldValue < donorBase)
    {
        return result;
    }

    const uint32_t relative =
        oldValue -
        donorBase;

    // Module 10 uses the unified virtual SNA/GPT/PTX image.
    if (targetModuleId == 10)
    {
        if (
            static_cast<uint64_t>(
                relative
                ) +
            4ULL >
            arenaSize
            )
        {
            return result;
        }

        const uintptr_t address =
            reinterpret_cast<uintptr_t>(
                arena
                ) +
            relative;

        result.newValue =
            static_cast<uint32_t>(
                address
                );

        result.kind =
            TARGET_MODULE10_ARENA;

        result.success =
            true;

        return result;
    }

    // Normal Water_20 serialized level block.
    if (target->size > 0)
    {
        if (relative >= target->size)
        {
            return result;
        }

        const size_t arenaOffset =
            target->dataOffset +
            relative;

        if (arenaOffset >= arenaSize)
        {
            return result;
        }

        const uintptr_t address =
            reinterpret_cast<uintptr_t>(
                arena
                ) +
            arenaOffset;

        result.newValue =
            static_cast<uint32_t>(
                address
                );

        result.kind =
            TARGET_LOCAL_SNA;

        result.success =
            true;

        return result;
    }

    // Zero-size descriptor / Fix / shared resource:
    // resolve against the CURRENT Bast_20 runtime MMG.
    tdstBlockInfoPriv runtimeBlock = {};

    if (
        !ReadMmgBlock(
            targetModuleId,
            targetBlockId,
            runtimeBlock
        )
        )
    {
        return result;
    }

    if (
        runtimeBlock.p_cBeginBlock ==
        nullptr
        )
    {
        return result;
    }

    const uintptr_t address =
        reinterpret_cast<uintptr_t>(
            runtimeBlock.p_cBeginBlock
            ) +
        relative;

    if (
        !AddressInsideRuntimeBlock(
            address,
            runtimeBlock
        )
        )
    {
        return result;
    }

    result.newValue =
        static_cast<uint32_t>(
            address
            );

    result.kind =
        TARGET_RUNTIME_MMG;

    result.success =
        true;

    return result;
}

RelocationStats ApplyRtb(
    const LoadedSna& donor,
    const RelocationTable& rtb,
    uint8_t* arena,
    size_t arenaSize
)
{
    RelocationStats stats = {};

    for (
        const RelocationBlock& sourceList :
        rtb.blocks
        )
    {
        const SnaBlock* source =
            FindDataBlock(
                donor,
                sourceList.moduleId,
                sourceList.blockId
            );

        for (
            const RelocationPointer& pointer :
            sourceList.pointers
            )
        {
            stats.expected++;

            if (
                source == nullptr ||
                source->size < 4
                )
            {
                stats.sourceFailures++;
                continue;
            }

            const uint32_t sourceBase =
                static_cast<uint32_t>(
                    source->baseInMemory
                    );

            if (
                pointer.offsetInMemory <
                sourceBase
                )
            {
                stats.sourceFailures++;
                continue;
            }

            const uint32_t sourceRelative =
                pointer.offsetInMemory -
                sourceBase;

            if (
                sourceRelative >
                source->size -
                4
                )
            {
                stats.sourceFailures++;
                continue;
            }

            const size_t fieldOffset =
                source->dataOffset +
                sourceRelative;

            if (
                fieldOffset +
                4 >
                arenaSize
                )
            {
                stats.sourceFailures++;
                continue;
            }

            uint8_t* field =
                arena +
                fieldOffset;

            const uint32_t oldValue =
                ReadLE32(field);

            const ResolveResult resolved =
                ResolveArenaTarget(
                    donor,
                    arena,
                    arenaSize,
                    pointer.targetModuleId,
                    pointer.targetBlockId,
                    oldValue
                );

            if (!resolved.success)
            {
                stats.targetFailures++;
                continue;
            }

            WriteLE32(
                field,
                resolved.newValue
            );

            stats.patched++;

            if (
                resolved.kind ==
                TARGET_LOCAL_SNA
                )
            {
                stats.localSna++;
            }
            else if (
                resolved.kind ==
                TARGET_MODULE10_ARENA
                )
            {
                stats.module10++;
            }
            else if (
                resolved.kind ==
                TARGET_RUNTIME_MMG
                )
            {
                stats.runtimeMmg++;
            }
        }
    }

    return stats;
}

uint64_t CountRelocations(
    const RelocationTable& table
)
{
    uint64_t result = 0;

    for (
        const RelocationBlock& block :
        table.blocks
        )
    {
        result +=
            block.pointers.size();
    }

    return result;
}

std::vector<PointerFileMatch> CollectPointerFileMatches(
    const std::vector<uint8_t>& rawFile,
    const RelocationTable& table
)
{
    std::vector<PointerFileMatch> result;

    for (
        const RelocationBlock& list :
        table.blocks
        )
    {
        if (list.pointers.empty())
        {
            continue;
        }

        size_t listIndex = 0;

        for (
            size_t fileOffset = 0;

            fileOffset + 4 <= rawFile.size() &&
            listIndex < list.pointers.size();

            fileOffset += 4
            )
        {
            const uint32_t value =
                ReadLE32(
                    &rawFile[fileOffset]
                );

            const RelocationPointer& pointer =
                list.pointers[listIndex];

            if (
                value !=
                pointer.offsetInMemory
                )
            {
                continue;
            }

            PointerFileMatch match = {};

            match.fileOffset =
                static_cast<uint32_t>(
                    fileOffset
                    );

            match.relocation =
                pointer;

            result.push_back(match);

            listIndex++;
        }
    }

    return result;
}

PointerFileStats ApplyPointerFile(
    const LoadedSna& donor,
    const std::vector<uint8_t>& rawFile,
    const RelocationTable& table,
    uint8_t* arena,
    size_t arenaSize,
    size_t fileArenaOffset
)
{
    PointerFileStats stats = {};

    stats.expected =
        CountRelocations(table);

    const std::vector<PointerFileMatch> matches =
        CollectPointerFileMatches(
            rawFile,
            table
        );

    stats.matched =
        matches.size();

    if (
        stats.expected >
        stats.matched
        )
    {
        stats.missing =
            stats.expected -
            stats.matched;
    }

    for (
        const PointerFileMatch& match :
        matches
        )
    {
        if (
            match.fileOffset +
            4 >
            rawFile.size()
            )
        {
            stats.targetFailures++;
            continue;
        }

        const uint32_t oldValue =
            ReadLE32(
                &rawFile[
                    match.fileOffset
                ]
            );

        const ResolveResult resolved =
            ResolveArenaTarget(
                donor,
                arena,
                arenaSize,
                match.relocation.targetModuleId,
                match.relocation.targetBlockId,
                oldValue
            );

        if (!resolved.success)
        {
            stats.targetFailures++;
            continue;
        }

        const size_t arenaField =
            fileArenaOffset +
            match.fileOffset;

        if (
            arenaField +
            4 >
            arenaSize
            )
        {
            stats.targetFailures++;
            continue;
        }

        WriteLE32(
            arena +
            arenaField,
            resolved.newValue
        );

        stats.patched++;
    }

    return stats;
}


// ============================================================
// ARENA POINTER HELPERS
// ============================================================

void* ArenaBlockPointer(
    const LoadedSna& donor,
    uint8_t* arena,
    size_t arenaSize,
    uint8_t moduleId,
    uint8_t blockId,
    uint32_t relativeOffset
)
{
    const SnaBlock* block =
        FindDataBlock(
            donor,
            moduleId,
            blockId
        );

    if (block == nullptr)
    {
        return nullptr;
    }

    if (
        relativeOffset >=
        block->size
        )
    {
        return nullptr;
    }

    const size_t arenaOffset =
        block->dataOffset +
        relativeOffset;

    if (
        arenaOffset >=
        arenaSize
        )
    {
        return nullptr;
    }

    return
        arena +
        arenaOffset;
}

bool PointerInsideArena(
    const void* pointer,
    const uint8_t* arena,
    size_t arenaSize
)
{
    if (
        pointer == nullptr ||
        arena == nullptr ||
        arenaSize == 0
        )
    {
        return false;
    }

    const uintptr_t value =
        reinterpret_cast<uintptr_t>(
            pointer
            );

    const uintptr_t begin =
        reinterpret_cast<uintptr_t>(
            arena
            );

    const uintptr_t end =
        begin +
        arenaSize;

    return
        value >= begin &&
        value < end;
}

template <typename T>
bool ReadArenaStruct(
    const T* pointer,
    T& output,
    const uint8_t* arena,
    size_t arenaSize
)
{
    if (
        pointer == nullptr ||
        !PointerInsideArena(
            pointer,
            arena,
            arenaSize
        )
        )
    {
        return false;
    }

    const uintptr_t begin =
        reinterpret_cast<uintptr_t>(
            arena
            );

    const uintptr_t address =
        reinterpret_cast<uintptr_t>(
            pointer
            );

    const size_t offset =
        static_cast<size_t>(
            address -
            begin
            );

    if (
        offset +
        sizeof(T) >
        arenaSize
        )
    {
        return false;
    }

    std::memcpy(
        &output,
        pointer,
        sizeof(T)
    );

    return true;
}


// ============================================================
// AUDIT HELPERS
// ============================================================

void AuditExactPointer(
    FILE* report,
    GraphAudit& audit,
    const char* name,
    const void* actual,
    const void* expected
)
{
    const bool pass =
        actual ==
        expected;

    fprintf(
        report,
        "%-34s actual=%p expected=%p  %s\n",
        name,
        actual,
        expected,
        pass ? "PASS" : "FAIL"
    );

    if (pass)
    {
        audit.passed++;
    }
    else
    {
        audit.failed++;
    }
}

void AuditNullPointer(
    FILE* report,
    GraphAudit& audit,
    const char* name,
    const void* actual
)
{
    const bool pass =
        actual ==
        nullptr;

    fprintf(
        report,
        "%-34s actual=%p expected=NULL      %s\n",
        name,
        actual,
        pass ? "PASS" : "FAIL"
    );

    if (pass)
    {
        audit.passed++;
    }
    else
    {
        audit.failed++;
    }
}

void AuditInsideArena(
    FILE* report,
    GraphAudit& audit,
    const char* name,
    const void* actual,
    const uint8_t* arena,
    size_t arenaSize
)
{
    const bool pass =
        PointerInsideArena(
            actual,
            arena,
            arenaSize
        );

    fprintf(
        report,
        "%-34s actual=%p inside-arena=%s  %s\n",
        name,
        actual,
        pass ? "YES" : "NO",
        pass ? "PASS" : "FAIL"
    );

    if (pass)
    {
        audit.passed++;
    }
    else
    {
        audit.failed++;
    }
}

void AuditLongValue(
    FILE* report,
    GraphAudit& audit,
    const char* name,
    long actual,
    long expected
)
{
    const bool pass =
        actual ==
        expected;

    fprintf(
        report,
        "%-34s actual=%ld expected=%ld  %s\n",
        name,
        actual,
        expected,
        pass ? "PASS" : "FAIL"
    );

    if (pass)
    {
        audit.passed++;
    }
    else
    {
        audit.failed++;
    }
}

void AuditUnsignedValue(
    FILE* report,
    GraphAudit& audit,
    const char* name,
    unsigned long actual,
    unsigned long expected
)
{
    const bool pass =
        actual ==
        expected;

    fprintf(
        report,
        "%-34s actual=%lu expected=%lu  %s\n",
        name,
        actual,
        expected,
        pass ? "PASS" : "FAIL"
    );

    if (pass)
    {
        audit.passed++;
    }
    else
    {
        audit.failed++;
    }
}


