// ============================================================
// SAFE OBJECT TYPE ELEMENT CREATION
//
// ACP_Ray2 HIE_fn_lNewObjectType() allocates a fresh element and
// immediately feeds it to LST_M_DynamicAddTail().  Our i.0c probe
// proved that explicitly initializing the dynamic-list links first
// avoids the crash path.
//
// This helper performs ONLY allocation + initialization + insertion.
// The caller performs the category-specific lookup afterwards.
// ============================================================

template <typename TAnchor>
GAM_tdstObjectTypeElement* SafeInsertObjectTypeElement(
    const char* name,
    TAnchor* anchor
)
{
    if (
        name == nullptr ||
        anchor == nullptr ||
        fn_p_vDynAlloc == nullptr
        )
    {
        return nullptr;
    }

    const size_t nameSize =
        std::strlen(name) + 1;

    char* nameMemory =
        reinterpret_cast<char*>(
            fn_p_vDynAlloc(
                static_cast<unsigned long>(
                    nameSize
                    )
            )
            );

    if (nameMemory == nullptr)
    {
        return nullptr;
    }

    std::memcpy(
        nameMemory,
        name,
        nameSize
    );

    GAM_tdstObjectTypeElement* element =
        reinterpret_cast<GAM_tdstObjectTypeElement*>(
            fn_p_vDynAlloc(
                static_cast<unsigned long>(
                    sizeof(GAM_tdstObjectTypeElement)
                    )
            )
            );

    if (element == nullptr)
    {
        return nullptr;
    }

    std::memset(
        element,
        0,
        sizeof(GAM_tdstObjectTypeElement)
    );

    LST_M_DynamicInitElement(
        element
    );

    element->szName =
        nameMemory;

    element->ucElementPriority =
        0;

    LST_M_DynamicAddTail(
        anchor,
        element
    );

    // h.7.99: these lists are global across the running process.  Leaving our
    // cross-level names linked while the main menu loads can make the next
    // level resolve serialized type indices against the wrong list layout.
    // Remember ONLY nodes that this DLL actually inserted.
    if (g_R2RInsertedObjectTypeCount < 64)
    {
        g_R2RInsertedObjectTypes[g_R2RInsertedObjectTypeCount++] =
            element;
    }

    return element;
}


// ============================================================
// OBJECT TYPE REGISTRATION
// ============================================================

long EnsureFamilyType(const char* name)
{
    if (
        name == nullptr ||
        GAM_g_stObjectTypes == nullptr
        )
    {
        return GAM_C_InvalidObjectType;
    }

    long value =
        HIE_fn_lFindFamilyTypeByName(
            name
        );

    if (value != GAM_C_InvalidObjectType)
    {
        return value;
    }

    GAM_tdstObjectTypeElement* element =
        SafeInsertObjectTypeElement(
            name,
            &GAM_g_stObjectTypes->stFamilyType
        );

    if (element == nullptr)
    {
        return GAM_C_InvalidObjectType;
    }

    return
        HIE_fn_lFindFamilyTypeByName(
            name
        );
}

