// ============================================================
// h.7.87 - NATIVE-vs-RUNTIME STALAC_SHOOT ALLOCATION DIFF
// ============================================================
//
// h.7.85 proved the imported template can be allocated and killed safely.
// h.7.87 compares that Bast_20 allocation against a native Water_20 allocation
// captured at F3, before allowing any actor to survive to a later frame.
// ============================================================
static bool R2R_RunStalacShootManualAllocationProbe()
{
    R2R_F6CrashPoint("ENTER R2R_RunStalacShootManualAllocationProbe");
    FILE* report = nullptr;
    fopen_s(
        &report,
        R2R_AI_EVAL_TRACE_FILE,
        "w"
    );

    if (report == nullptr)
    {
        R2R_F6CrashPoint("Manual projectile report OPEN FAILED");
        return false;
    }

    R2R_F6CrashPoint("Manual projectile report OPENED");
    setvbuf(report, nullptr, _IONBF, 0);

    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - STALAC SHOOT FULL PRIVATE TABLE PROBE\n"
        "============================================================\n\n"
        "PURPOSE:\n"
        "Allocate STN_Stalac_shoot directly from the imported Always template.\n"
        "Aglagl AI/attack is NOT allowed to run in this probe.\n"
        "The projectile keeps its PRIVATE Stalac State/ObjectTable and its own visual target,\n"
        "and still borrows the proven-safe Bast_20 frame/morph/matrix helpers.\n"
        "This probe additionally makes BOTH current + init ObjectTable entry arrays private.\n"
        "AI/mechanics/animation remain disabled. The projectile's OWN 3D pointer is restored before kill.\n\n"
    );

    if (
        g_SpawnedHybridActor == nullptr ||
        g_AglaglTemplate == nullptr ||
        g_AglaglTemplate->hBrain == nullptr
        )
    {
        fprintf(report, "FAIL: Aglagl/template prerequisites unavailable.\n");
        fclose(report);
        return false;
    }

    // We only need a cloned Brain long enough to recover the imported script
    // and locate the original GenerateObject PersoRef for template setup.
    AI_fn_vBrainCopyClone(
        g_SpawnedHybridActor,
        g_AglaglTemplate
    );

    if (
        g_SpawnedHybridActor->hBrain == nullptr ||
        g_SpawnedHybridActor->hBrain->p_stMind == nullptr
        )
    {
        fprintf(report, "FAIL: cloned Aglagl Brain unavailable.\n");
        fclose(report);
        return false;
    }

    AI_tdstMind* cloneMind =
        g_SpawnedHybridActor->hBrain->p_stMind;

    AI_tdstIntelligence* active =
        R2R_GetActiveIntelligence(cloneMind);

    AI_tdstScriptAI* script =
        R2R_GetScriptAIFromIntelligence(active);

    if (
        active == nullptr ||
        script == nullptr ||
        script->a_stComport == nullptr
        )
    {
        fprintf(report, "FAIL: cloned Aglagl script unavailable.\n");
        fclose(report);
        return false;
    }

    fprintf(
        report,
        "Water target identity : %s / %s / %s\n"
        "Old Water IDs         : %ld / %ld / %ld\n\n",
        g_R2RGenerateObjectTemplateCapture.familyName[0] != '\0'
        ? g_R2RGenerateObjectTemplateCapture.familyName
        : "(uncaptured family)",
        g_R2RGenerateObjectTemplateCapture.modelName[0] != '\0'
        ? g_R2RGenerateObjectTemplateCapture.modelName
        : "(uncaptured model)",
        g_R2RGenerateObjectTemplateCapture.personalName[0] != '\0'
        ? g_R2RGenerateObjectTemplateCapture.personalName
        : "(uncaptured personal)",
        R2R_GENOBJ_WATER_FAMILY_TYPE,
        R2R_GENOBJ_WATER_MODEL_TYPE,
        R2R_GENOBJ_WATER_PERSONAL_TYPE
    );

    const bool importReady =
        R2R_PrepareStalacShootRuntimeImport(
            script,
            report
        );

    if (!importReady)
    {
        fprintf(
            report,
            "\nRESULT: runtime STN_Stalac_shoot import could not be prepared.\n"
        );
        fflush(report);
        fclose(report);
        return false;
    }

    // This probe will NOT run Aglagl's AI. Restore the cloned script now so
    // there is no chance of the normal attack reaching Function 0x42 later.
    const unsigned int patchedBeforeRestore =
        g_R2RStalacShootPatchedNodeCount;
    R2R_RestoreGenerateObjectPersoRefs();

    fprintf(
        report,
        "\nRUNTIME BAST ALLOCATION PREFLIGHT\n"
        "------------------------------------------------------------\n"
        "Runtime Bast IDs       : %ld / %ld / %ld\n"
        "Runtime template       : %p\n"
        "Runtime Family         : %p\n"
        "Temporary Always node  : %p\n"
        "Patched refs restored  : %u\n"
        "ALW allocator          : %p\n"
        "Dynamic world          : %p\n",
        g_R2RStalacShootFamilyType,
        g_R2RStalacShootModelType,
        g_R2RStalacShootPersonalType,
        g_R2RStalacShootRuntimeTemplate,
        g_R2RStalacShootRuntimeFamily,
        g_R2RStalacShootAlwaysNode,
        patchedBeforeRestore,
        ALW_fn_p_stAllocateAlways,
        (GAM_g_p_stDynamicWorld != nullptr)
        ? *GAM_g_p_stDynamicWorld
        : nullptr
    );

    if (
        g_R2RStalacShootRuntimeTemplate == nullptr ||
        g_R2RStalacShootAlwaysNode == nullptr ||
        g_R2RStalacShootModelType == GAM_C_InvalidObjectType ||
        ALW_fn_p_stAllocateAlways == nullptr ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr ||
        g_SpawnedHybrid == nullptr ||
        g_SpawnedHybrid->p_stGlobalMatrix == nullptr
        )
    {
        fprintf(report, "RESULT: manual allocation preflight FAILED.\n");
        fflush(report);
        fclose(report);
        return false;
    }

    POS_tdstCompletePosition position =
        *g_SpawnedHybrid->p_stGlobalMatrix;

    fprintf(
        report,
        "\nCALLING ALW_fn_p_stAllocateAlways NOW\n"
        "------------------------------------------------------------\n"
        "modelType : %ld\n"
        "parent SO : %p\n"
        "position  : %.6f %.6f %.6f\n"
        "If the game crashes before ALLOCATOR RETURNED is written,\n"
        "the imported template itself is not safe to instantiate.\n",
        g_R2RStalacShootModelType,
        g_SpawnedHybrid,
        position.stPos.x,
        position.stPos.y,
        position.stPos.z
    );
    fflush(report);

    HIE_tdstSuperObject* spawnedSO =
        ALW_fn_p_stAllocateAlways(
            g_R2RStalacShootModelType,
            *GAM_g_p_stDynamicWorld,
            g_SpawnedHybrid,
            0,
            &position
        );

    fprintf(
        report,
        "\nALLOCATOR RETURNED SAFELY\n"
        "------------------------------------------------------------\n"
        "Returned SuperObject : %p\n",
        spawnedSO
    );
    fflush(report);

    if (
        spawnedSO == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(spawnedSO),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        fprintf(
            report,
            "RESULT: allocator returned NULL/unreadable SuperObject.\n"
            "Temporary Always entry intentionally kept installed for process lifetime.\n"
        );
        fflush(report);
        fclose(report);
        return true;
    }

    fprintf(
        report,
        "Returned SO type      : 0x%08lX\n",
        spawnedSO->ulType
    );

    if (spawnedSO->ulType != HIE_C_Type_Actor)
    {
        fprintf(
            report,
            "RESULT: allocator returned a non-Actor SuperObject.\n"
            "Temporary Always entry intentionally kept installed for process lifetime.\n"
        );
        fflush(report);
        fclose(report);
        return true;
    }

    HIE_tdstEngineObject* spawnedActor =
        HIE_M_hSuperObjectGetActor(spawnedSO);

    fprintf(
        report,
        "Returned Actor        : %p\n",
        spawnedActor
    );

    if (spawnedActor == nullptr)
    {
        fprintf(report, "RESULT: Actor pointer is NULL.\n");
        fflush(report);
        fclose(report);
        return true;
    }

    HIE_tdstEngineObject actorCopy = {};
    GAM_tdstStandardGame stdCopy = {};
    const bool actorReadable =
        R2R_ReadActorAndStd(
            spawnedActor,
            actorCopy,
            stdCopy
        );

    if (spawnedActor->hStandardGame != nullptr)
    {
        spawnedActor->hStandardGame->ulCustomBits |=
            (
                Std_C_CustBit_NoAI |
                Std_C_CustBit_NoMechanic |
                Std_C_CustBit_NoAnimPlayer |
                Std_C_CustBit_OutOfVisibility
                );
    }

    fprintf(
        report,
        "\nALLOCATED ACTOR SNAPSHOT\n"
        "------------------------------------------------------------\n"
        "Actor readable        : %s\n"
        "Type IDs              : %ld / %ld / %ld\n"
        "Custom / misc         : 0x%08lX / 0x%02X\n"
        "3DData                : %p\n"
        "Family                : %p\n"
        "Initial state         : %p\n"
        "Current state         : %p\n"
        "Initial objects table : %p\n"
        "Current objects table : %p\n"
        "Brain                 : %p\n"
        "Dynamics              : %p\n"
        "CollSet               : %p\n",
        actorReadable ? "YES" : "NO",
        actorReadable ? stdCopy.lObjectFamilyType : -1,
        actorReadable ? stdCopy.lObjectModelType : -1,
        actorReadable ? stdCopy.lObjectPersonalType : -1,
        actorReadable ? static_cast<unsigned long>(stdCopy.ulCustomBits) : 0ul,
        actorReadable ? static_cast<unsigned int>(stdCopy.ucMiscFlags) : 0u,
        actorReadable ? actorCopy.h3dData : nullptr,
        (actorReadable && actorCopy.h3dData != nullptr)
        ? actorCopy.h3dData->h_Family
        : nullptr,
        (actorReadable && actorCopy.h3dData != nullptr)
        ? actorCopy.h3dData->h_InitialState
        : nullptr,
        (actorReadable && actorCopy.h3dData != nullptr)
        ? actorCopy.h3dData->h_CurrentState
        : nullptr,
        (actorReadable && actorCopy.h3dData != nullptr)
        ? actorCopy.h3dData->h_InitialObjectsTable
        : nullptr,
        (actorReadable && actorCopy.h3dData != nullptr)
        ? actorCopy.h3dData->h_CurrentObjectsTable
        : nullptr,
        actorReadable ? actorCopy.hBrain : nullptr,
        actorReadable ? actorCopy.hDynam : nullptr,
        actorReadable ? actorCopy.hCollSet : nullptr
    );
    fflush(report);

    GAM_tdst3dData runtimeDataCopy = {};
    if (
        actorReadable &&
        actorCopy.h3dData != nullptr &&
        SafeReadMemory(actorCopy.h3dData, &runtimeDataCopy, sizeof(runtimeDataCopy))
        )
    {
        R2R_ReportStalacShootAllocationDiff(
            report,
            actorCopy,
            stdCopy,
            runtimeDataCopy
        );
    }
    else
    {
        fprintf(report, "\nRUNTIME 3D DATA COPY FAILED; comparison unavailable.\n");
    }
    fflush(report);

    // h.8.01: h.8.00 proved that private State/ObjectTable descriptors alone
    // are NOT enough: the visible projectile still crashed on the next engine
    // frame.  h.7.94 proved that replacing the ENTIRE 3D block with Bast data
    // survives.  Narrow the difference by keeping Stalac's own Family,
    // private State/ObjectTable and visual target, while borrowing ONLY the
    // low-level frame/morph/matrix runtime group from a known-safe Bast actor.
    //
    // IMPORTANT OWNERSHIP RULE:
    // We never overwrite the projectile's engine-owned 3D allocation.  We make
    // a private hybrid copy, point the Actor at it for one frame, then the
    // existing h.7.98 ownership guard restores the original h3dData pointer
    // BEFORE the Actor is killed.
    g_R2RStalacShootOriginal3DBeforeBorrow = nullptr;
    g_R2RStalacShootBorrowedSafe3D = nullptr;

    const bool privateDescriptorsReady =
        g_R2RStalacShootRuntimeState != nullptr &&
        g_R2RStalacShootRuntimeTable != nullptr &&
        g_R2RStalacShootRuntimeTableElements != nullptr &&
        spawnedActor->h3dData != nullptr &&
        spawnedActor->h3dData->h_CurrentState == g_R2RStalacShootRuntimeState &&
        spawnedActor->h3dData->h_CurrentObjectsTable == g_R2RStalacShootRuntimeTable;

    HIE_tdstSuperObject* safeFrameSO = nullptr;
    HIE_tdstEngineObject* safeFrameActor = nullptr;
    const char* safeFrameModel = nullptr;

    const bool safeFrameSourceFound =
        FindBast20ControlSource(
            safeFrameSO,
            safeFrameActor,
            safeFrameModel
        );

    GAM_tdst3dData projectileOwn3DCopy = {};
    GAM_tdst3dData safeFrame3DCopy = {};
    GAM_tdst3dData* runtimeHybrid3D = nullptr;

    const bool projectile3DReadable =
        spawnedActor->h3dData != nullptr &&
        SafeReadMemory(
            spawnedActor->h3dData,
            &projectileOwn3DCopy,
            sizeof(projectileOwn3DCopy)
        );

    const bool safeFrame3DReadable =
        safeFrameSourceFound &&
        safeFrameActor != nullptr &&
        safeFrameActor->h3dData != nullptr &&
        SafeReadMemory(
            safeFrameActor->h3dData,
            &safeFrame3DCopy,
            sizeof(safeFrame3DCopy)
        );

    if (
        privateDescriptorsReady &&
        projectile3DReadable &&
        safeFrame3DReadable &&
        R2_GameMallocInHLM != nullptr
        )
    {
        runtimeHybrid3D =
            reinterpret_cast<GAM_tdst3dData*>(
                R2_GameMallocInHLM(
                    static_cast<unsigned int>(sizeof(GAM_tdst3dData))
                )
                );

        if (runtimeHybrid3D != nullptr)
        {
            // Start with the projectile's OWN current 3D state.  That means
            // Family + private Stalac State/ObjectTable + draw state stay Stalac.
            std::memcpy(
                runtimeHybrid3D,
                &projectileOwn3DCopy,
                sizeof(GAM_tdst3dData)
            );

            // Swap ONLY the low-level runtime frame group.  These fields are
            // touched by the renderer even with NoAnimPlayer set, so this is the
            // smallest useful group between h.8.00 (crash) and h.7.94 (stable).
            runtimeHybrid3D->p_stGLIObjectAbsoluteMatrix =
                safeFrame3DCopy.p_stGLIObjectAbsoluteMatrix;
            runtimeHybrid3D->d_ucEventActivation =
                safeFrame3DCopy.d_ucEventActivation;
            runtimeHybrid3D->p_stCurrentHieCouples =
                safeFrame3DCopy.p_stCurrentHieCouples;
            runtimeHybrid3D->stFrame3d =
                safeFrame3DCopy.stFrame3d;
            runtimeHybrid3D->hMorphChannelList =
                safeFrame3DCopy.hMorphChannelList;
            runtimeHybrid3D->p_stShadowMaterial =
                safeFrame3DCopy.p_stShadowMaterial;
            runtimeHybrid3D->p_stShadowTexture =
                safeFrame3DCopy.p_stShadowTexture;

            // h.8.02: complete the State pointer set explicitly.  Earlier
            // Stalac probes only replaced Initial/Current/FirstStateOfAction.
            // Rayman 2 also keeps WantedState and StateInLastFrame inside the
            // same 3D block; the stable Aglagl isolation path explicitly
            // normalizes these fields, so do the same here before the first
            // visible projectile frame.
            runtimeHybrid3D->h_InitialState =
                g_R2RStalacShootRuntimeState;
            runtimeHybrid3D->h_CurrentState =
                g_R2RStalacShootRuntimeState;
            runtimeHybrid3D->h_FirstStateOfAction =
                g_R2RStalacShootRuntimeState;
            runtimeHybrid3D->h_WantedState =
                g_R2RStalacShootRuntimeState;
            runtimeHybrid3D->h_StateInLastFrame = nullptr;
            runtimeHybrid3D->h_InitialObjectsTable =
                g_R2RStalacShootRuntimeTable;
            runtimeHybrid3D->h_CurrentObjectsTable =
                g_R2RStalacShootRuntimeTable;

            g_R2RStalacShootOriginal3DBeforeBorrow =
                spawnedActor->h3dData;
            g_R2RStalacShootBorrowedSafe3D =
                runtimeHybrid3D;
            spawnedActor->h3dData =
                runtimeHybrid3D;
        }
    }

    const bool frameCoreSwapReady =
        runtimeHybrid3D != nullptr &&
        spawnedActor->h3dData == runtimeHybrid3D;

    fprintf(
        report,
        "\nH.8.03 STALAC FULL PRIVATE TABLE ISOLATION\n"
        "------------------------------------------------------------\n"
        "Experimental Water_20 TP removed       : YES\n"
        "Private Stalac State/Table ready       : %s\n"
        "Safe Bast frame-core source found      : %s\n"
        "Safe Bast source model                 : %s\n"
        "Projectile owned 3D                    : %p\n"
        "Hybrid one-frame 3D                    : %p\n"
        "Stalac Family preserved                : %s\n"
        "Stalac private State preserved         : %s\n"
        "Stalac private ObjectTable preserved   : %s\n"
        "Borrowed: absolute GLI matrix          : %p -> %p\n"
        "Borrowed: Frame3d elements             : %p -> %p\n"
        "Borrowed: Morph list                   : %p -> %p\n"
        "Borrowed: current Hie couples          : %p -> %p\n"
        "WantedState before fix                 : %p\n"
        "WantedState after fix                  : %p\n"
        "StateInLastFrame before fix            : %p\n"
        "StateInLastFrame after fix             : %p\n"
        "All active State pointers private      : %s\n"
        "AI / mechanics / animation disabled   : YES\n"
        "Purpose: test whether the still-donor d_stInitObjectsTable entry array caused the visible-frame crash.\n",
        privateDescriptorsReady ? "YES" : "NO",
        safeFrameSourceFound ? "YES" : "NO",
        safeFrameModel != nullptr ? safeFrameModel : "(none)",
        g_R2RStalacShootOriginal3DBeforeBorrow,
        runtimeHybrid3D,
        (runtimeHybrid3D != nullptr && runtimeHybrid3D->h_Family == projectileOwn3DCopy.h_Family) ? "YES" : "NO",
        (runtimeHybrid3D != nullptr && runtimeHybrid3D->h_CurrentState == g_R2RStalacShootRuntimeState) ? "YES" : "NO",
        (runtimeHybrid3D != nullptr && runtimeHybrid3D->h_CurrentObjectsTable == g_R2RStalacShootRuntimeTable) ? "YES" : "NO",
        projectileOwn3DCopy.p_stGLIObjectAbsoluteMatrix,
        safeFrame3DCopy.p_stGLIObjectAbsoluteMatrix,
        projectileOwn3DCopy.stFrame3d.p_stArrayOfElts3d,
        safeFrame3DCopy.stFrame3d.p_stArrayOfElts3d,
        projectileOwn3DCopy.hMorphChannelList,
        safeFrame3DCopy.hMorphChannelList,
        projectileOwn3DCopy.p_stCurrentHieCouples,
        safeFrame3DCopy.p_stCurrentHieCouples,
        projectileOwn3DCopy.h_WantedState,
        runtimeHybrid3D != nullptr ? runtimeHybrid3D->h_WantedState : nullptr,
        projectileOwn3DCopy.h_StateInLastFrame,
        runtimeHybrid3D != nullptr ? runtimeHybrid3D->h_StateInLastFrame : nullptr,
        (
            runtimeHybrid3D != nullptr &&
            runtimeHybrid3D->h_InitialState == g_R2RStalacShootRuntimeState &&
            runtimeHybrid3D->h_CurrentState == g_R2RStalacShootRuntimeState &&
            runtimeHybrid3D->h_FirstStateOfAction == g_R2RStalacShootRuntimeState &&
            runtimeHybrid3D->h_WantedState == g_R2RStalacShootRuntimeState &&
            runtimeHybrid3D->h_StateInLastFrame == nullptr
            ) ? "YES" : "NO"
    );
    fflush(report);

    if (!frameCoreSwapReady)
    {
        fprintf(
            report,
            "RESULT: frame-core hybrid preparation FAILED; projectile will be killed without a visible frame.\n"
        );
        fflush(report);

        // If a hybrid pointer was installed partially, put the Actor back on
        // its owned 3D block before destruction.
        if (
            g_R2RStalacShootOriginal3DBeforeBorrow != nullptr &&
            spawnedActor != nullptr
            )
        {
            spawnedActor->h3dData =
                g_R2RStalacShootOriginal3DBeforeBorrow;
        }

        if (R2_KillEngineObjectOrAlwaysByPointer != nullptr)
        {
            R2_KillEngineObjectOrAlwaysByPointer(spawnedActor);
        }

        g_R2RStalacShootOriginal3DBeforeBorrow = nullptr;
        g_R2RStalacShootBorrowedSafe3D = nullptr;
        R2R_FinalizeStalacShootImport(report);
        fclose(report);
        return false;
    }

    if (spawnedActor->hStandardGame != nullptr)
    {
        spawnedActor->hStandardGame->ulCustomBits &=
            ~Std_C_CustBit_OutOfVisibility;
    }

    g_R2RStalacShootBornSO = spawnedSO;
    g_R2RStalacShootBornActor = spawnedActor;
    g_R2RStalacShootGenerateReturnedThisFrame = false;
    g_R2RStalacShootBirthProbeCompleted = true;
    g_R2RStalacShootOneFrameSurvivalPending = true;
    g_R2RStalacShootBirthFrame = 0;

    g_R2RAIMultiFramesCompleted = 0;
    g_R2ROneAIFrameReturned = false;
    g_R2ROneAIFrameArmed = true;
    g_R2RAITraceActive = false;

    fprintf(
        report,
        "Projectile visibility                  : ENABLED\n"
        "Projectile visual target                : STALAC (unchanged)\n"
        "Low-level frame core                    : BAST_20 SAFE\n"
        "State pointer set                       : PRIVATE STALAC + NORMALIZED\n"
        "ObjectTable current entry array          : PRIVATE\n"
        "ObjectTable init entry array             : PRIVATE/NULL\n"
        "Next engine frame will be attempted    : YES\n"
        "============================================================\n"
        "\n================ FULL-PRIVATE-TABLE ONE-FRAME TEST BEGIN ================\n"
    );
    fflush(report);

    g_R2RAITraceFile = report;
    return true;

    // Legacy h.7.94 Piranha shell code retained below but intentionally
    // unreachable in h.8.00 for comparison/reference only.
    // h.7.95: h.7.93 still crashed after replacing only State/ObjectTable.
    // Therefore the risky part may be elsewhere inside GAM_tdst3dData
    // (Frame3d, morph data, absolute GLI matrix, etc.).  For ONE frame only,
    // replace the projectile's ENTIRE 3D data block with a copy of a known-safe
    // native Bast_20 actor.  StandardGame identity remains STN_Stalac_shoot.
    HIE_tdstSuperObject* safeVisualSO = nullptr;
    HIE_tdstEngineObject* safeVisualActor = nullptr;
    const char* safeVisualModel = nullptr;

    const bool safeVisualSourceFound =
        FindBast20ControlSource(
            safeVisualSO,
            safeVisualActor,
            safeVisualModel
        );

    GAM_tdst3dData* originalProjectile3D =
        spawnedActor->h3dData;

    // h.7.98 ownership guard: remember the projectile's own 3D block before
    // temporarily pointing the Actor at a shallow copy of native Bast_20 data.
    g_R2RStalacShootOriginal3DBeforeBorrow = originalProjectile3D;
    g_R2RStalacShootBorrowedSafe3D = nullptr;

    GAM_tdst3dData* runtimeSafe3D = nullptr;

    if (
        safeVisualSourceFound &&
        safeVisualActor != nullptr &&
        safeVisualActor->h3dData != nullptr &&
        R2_GameMallocInHLM != nullptr
        )
    {
        GAM_tdst3dData safe3DCopy = {};

        if (
            SafeReadMemory(
                safeVisualActor->h3dData,
                &safe3DCopy,
                sizeof(safe3DCopy)
            )
            )
        {
            runtimeSafe3D =
                reinterpret_cast<GAM_tdst3dData*>(
                    R2_GameMallocInHLM(
                        static_cast<unsigned int>(
                            sizeof(GAM_tdst3dData)
                            )
                    )
                    );

            if (runtimeSafe3D != nullptr)
            {
                memcpy(
                    runtimeSafe3D,
                    &safe3DCopy,
                    sizeof(GAM_tdst3dData)
                );

                spawnedActor->h3dData =
                    runtimeSafe3D;
                g_R2RStalacShootBorrowedSafe3D = runtimeSafe3D;

                if (spawnedActor->hStandardGame != nullptr)
                {
                    spawnedActor->hStandardGame->ulCustomBits &=
                        ~Std_C_CustBit_OutOfVisibility;
                }
            }
        }
    }

    const bool safeVisualReady =
        runtimeSafe3D != nullptr;

    fprintf(
        report,
        "\nH.7.94 FULL SAFE 3D ISOLATION\n"
        "------------------------------------------------------------\n"
        "Safe Bast 3D source found          : %s\n"
        "Safe Bast source model             : %s\n"
        "Original projectile 3D             : %p\n"
        "Full Bast 3D clone                  : %p\n"
        "Projectile uses FULL safe 3D block : %s\n"
        "Projectile visible for next frame  : %s\n"
        "AI / mechanics / animation disabled: YES\n"
        "Purpose: test whether ANY remaining Water_20 3D field caused the visible-frame crash.\n",
        safeVisualSourceFound ? "YES" : "NO",
        safeVisualModel != nullptr ? safeVisualModel : "(none)",
        originalProjectile3D,
        runtimeSafe3D,
        safeVisualReady ? "YES" : "NO",
        safeVisualReady ? "YES" : "NO"
    );
    fflush(report);

    if (!safeVisualReady)
    {
        g_R2RStalacShootBorrowedSafe3D = nullptr;
        // Actor never adopted a usable borrowed shell, so its own 3D pointer is
        // already the correct ownership pointer for destruction.
        fprintf(report, "RESULT: full safe 3D shell could not be prepared; projectile will be killed without running another frame.\n");
        fflush(report);

        if (R2_KillEngineObjectOrAlwaysByPointer != nullptr)
        {
            R2_KillEngineObjectOrAlwaysByPointer(spawnedActor);
        }

        R2R_FinalizeStalacShootImport(report);
        fclose(report);
        return false;
    }

    // h.7.95: do NOT kill the manually allocated projectile yet.
    // Keep it visible with the FULL safe Bast 3D shell for exactly one frame.
    g_R2RStalacShootBornSO = spawnedSO;
    g_R2RStalacShootBornActor = spawnedActor;
    g_R2RStalacShootGenerateReturnedThisFrame = false;
    g_R2RStalacShootBirthProbeCompleted = true;
    g_R2RStalacShootOneFrameSurvivalPending = true;
    g_R2RStalacShootBirthFrame = 0;

    g_R2RAIMultiFramesCompleted = 0;
    g_R2ROneAIFrameReturned = false;
    g_R2ROneAIFrameArmed = true;
    g_R2RAITraceActive = false;

    fprintf(
        report,
        "\n============================================================\n"
        "H.7.94 FULL-SAFE-3D PROJECTILE CREATED - ONE ENGINE FRAME WILL RUN\n"
        "Aglagl attack executed              : NO\n"
        "Projectile Actor                    : %p\n"
        "Projectile AI/mechanics/anim        : DISABLED\n"
        "Projectile visibility               : ENABLED\n"
        "3D resources                        : FULL BAST_20 SAFE SHELL\n"
        "Projectile will remain allocated    : YES\n"
        "Next engine frame will be attempted : YES\n"
        "============================================================\n"
        "\n================ FULL-SAFE-3D ONE-FRAME SURVIVAL TEST BEGIN ================\n",
        spawnedActor
    );
    fflush(report);

    // The normal post-engine callback owns this file from now on.
    g_R2RAITraceFile = report;
    return true;
}


static bool R2R_AllocateNativeCHGPairFromAlways(
    long modelType,
    R2R_ModelActorMatch& first,
    R2R_ModelActorMatch& second
)
{
    first = {};
    second = {};

    if (
        modelType == GAM_C_InvalidObjectType ||
        ALW_fn_p_stAllocateAlways == nullptr ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr
        )
    {
        return false;
    }

    HIE_tdstSuperObject* mainActor =
        HIE_M_hGetMainActor();

    if (
        mainActor == nullptr ||
        mainActor->p_stGlobalMatrix == nullptr
        )
    {
        return false;
    }

    POS_tdstCompletePosition position =
        *mainActor->p_stGlobalMatrix;

    HIE_tdstSuperObject* so0 =
        ALW_fn_p_stAllocateAlways(
            modelType,
            *GAM_g_p_stDynamicWorld,
            mainActor,
            0,
            &position
        );

    HIE_tdstSuperObject* so1 =
        ALW_fn_p_stAllocateAlways(
            modelType,
            *GAM_g_p_stDynamicWorld,
            mainActor,
            0,
            &position
        );

    if (
        so0 == nullptr ||
        so1 == nullptr ||
        so0->ulType != HIE_C_Type_Actor ||
        so1->ulType != HIE_C_Type_Actor
        )
    {
        if (
            so0 != nullptr &&
            R2_KillEngineObjectOrAlwaysByPointer != nullptr &&
            so0->ulType == HIE_C_Type_Actor
            )
        {
            HIE_tdstEngineObject* actor0 =
                HIE_M_hSuperObjectGetActor(
                    so0
                );

            if (actor0 != nullptr)
            {
                R2_KillEngineObjectOrAlwaysByPointer(
                    actor0
                );
            }
        }

        if (
            so1 != nullptr &&
            R2_KillEngineObjectOrAlwaysByPointer != nullptr &&
            so1->ulType == HIE_C_Type_Actor
            )
        {
            HIE_tdstEngineObject* actor1 =
                HIE_M_hSuperObjectGetActor(
                    so1
                );

            if (actor1 != nullptr)
            {
                R2_KillEngineObjectOrAlwaysByPointer(
                    actor1
                );
            }
        }

        return false;
    }

    HIE_tdstEngineObject* actor0 =
        HIE_M_hSuperObjectGetActor(
            so0
        );

    HIE_tdstEngineObject* actor1 =
        HIE_M_hSuperObjectGetActor(
            so1
        );

    if (
        actor0 == nullptr ||
        actor1 == nullptr ||
        actor0->hStandardGame == nullptr ||
        actor1->hStandardGame == nullptr
        )
    {
        return false;
    }

    // They only exist as dependency targets for this diagnostic.
    // Do not let their own engine update run independently.
    actor0->hStandardGame->ulCustomBits |=
        (
            Std_C_CustBit_NoAI |
            Std_C_CustBit_NoMechanic
            );

    actor1->hStandardGame->ulCustomBits |=
        (
            Std_C_CustBit_NoAI |
            Std_C_CustBit_NoMechanic
            );

    first.superObject = so0;
    first.actor = actor0;

    second.superObject = so1;
    second.actor = actor1;

    g_R2RNativeCHG0 = so0;
    g_R2RNativeCHG1 = so1;

    return true;
}



static bool R2R_BindDonorActionStatesToMergedAnimations(
    AI_tdstScriptAI* script,
    GAM_tdstAnim3d* safeIdleAnimation,
    FILE* report
)
{
    if (
        script == nullptr ||
        script->a_stComport == nullptr ||
        script->ulNbComport == 0 ||
        script->ulNbComport > 64 ||
        safeIdleAnimation == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                safeIdleAnimation
                ),
            sizeof(GAM_tdstAnim3d)
        ) ||
        !g_A3dMergedBankInstalled
        )
    {
        return false;
    }

    GAM_tdstAnim3d* runtimeAnimation[4] =
    {
        nullptr, nullptr, nullptr, nullptr
    };

    // General 301 is the exact already-proven safe idle descriptor created
    // for the spawned Aglagl.
    runtimeAnimation[0] =
        safeIdleAnimation;

    HIE_tdstState* patchedStates[64] = {};
    unsigned int patchedStateCount = 0;
    unsigned int actionRefCount = 0;

    auto alreadyPatched =
        [&](HIE_tdstState* state) -> bool
        {
            for (
                unsigned int i = 0;
                i < patchedStateCount;
                i++
                )
            {
                if (
                    patchedStates[i] ==
                    state
                    )
                {
                    return true;
                }
            }

            return false;
        };

    auto getRuntimeAnimation =
        [&](int sourceIndex, const GAM_tdstAnim3d& source)
        -> GAM_tdstAnim3d*
        {
            if (
                sourceIndex < 0 ||
                sourceIndex >= 4
                )
            {
                return nullptr;
            }

            if (
                runtimeAnimation[
                    sourceIndex
                ] != nullptr
                )
            {
                return runtimeAnimation[
                    sourceIndex
                ];
            }

            if (
                R2_GameMallocInHLM ==
                nullptr
                )
            {
                return nullptr;
            }

            GAM_tdstAnim3d* clone =
                reinterpret_cast<GAM_tdstAnim3d*>(
                    R2_GameMallocInHLM(
                        static_cast<unsigned int>(
                            sizeof(
                                GAM_tdstAnim3d
                                )
                            )
                    )
                    );

            if (clone == nullptr)
            {
                return nullptr;
            }

            std::memcpy(
                clone,
                &source,
                sizeof(
                    GAM_tdstAnim3d
                    )
            );

            clone->uwNumOfA3dGENERAL =
                g_R2RActionSyntheticGeneralIds[
                    sourceIndex
                ];

            // h.7.68: the single General-302 event is intentionally
            // suppressed until its Water runtime payload is reconstructed.
            clone->ucNumberOfEvents = 0;
            clone->d_stAnimEvent = nullptr;

            // These animations have no morph payload.
            clone->d_stMorphDataArray = nullptr;

            runtimeAnimation[
                sourceIndex
            ] = clone;

            return clone;
        };

    auto patchStateChain =
        [&](HIE_tdstState* root) -> bool
        {
            if (
                root == nullptr ||
                !PointerInsideCrossLevelArena(
                    root
                )
                )
            {
                return true;
            }

            HIE_tdstState* visited[16] = {};
            unsigned int visitedCount = 0;

            HIE_tdstState* cursor =
                root;

            for (
                unsigned int chainIndex = 0;
                chainIndex < 12;
                chainIndex++
                )
            {
                if (
                    cursor == nullptr ||
                    !PointerInsideCrossLevelArena(
                        cursor
                    ) ||
                    !R2R_AddressReadable(
                        reinterpret_cast<uintptr_t>(
                            cursor
                            ),
                        sizeof(HIE_tdstState)
                    )
                    )
                {
                    break;
                }

                bool loop = false;

                for (
                    unsigned int v = 0;
                    v < visitedCount;
                    v++
                    )
                {
                    if (
                        visited[v] ==
                        cursor
                        )
                    {
                        loop = true;
                        break;
                    }
                }

                if (loop)
                {
                    break;
                }

                if (visitedCount < 16)
                {
                    visited[
                        visitedCount++
                    ] = cursor;
                }

                HIE_tdstState stateCopy = {};

                if (
                    !SafeReadMemory(
                        cursor,
                        &stateCopy,
                        sizeof(stateCopy)
                    )
                    )
                {
                    return false;
                }

                if (!alreadyPatched(cursor))
                {
                    GAM_tdstAnim3d sourceAnimation = {};

                    if (
                        stateCopy.p_stAnim ==
                        nullptr ||
                        !R2R_AddressReadable(
                            reinterpret_cast<uintptr_t>(
                                stateCopy.p_stAnim
                                ),
                            sizeof(
                                GAM_tdstAnim3d
                                )
                        ) ||
                        !SafeReadMemory(
                            stateCopy.p_stAnim,
                            &sourceAnimation,
                            sizeof(
                                sourceAnimation
                                )
                        )
                        )
                    {
                        return false;
                    }

                    const uint16_t sourceGeneral =
                        sourceAnimation.
                        uwNumOfA3dGENERAL;

                    const int sourceIndex =
                        R2R_ActionSourceGeneralIndex(
                            sourceGeneral
                        );

                    if (sourceIndex < 0)
                    {
                        if (report != nullptr)
                        {
                            fprintf(
                                report,
                                "FAIL: donor Action State %p references unimported Water General %u.\n",
                                cursor,
                                static_cast<unsigned int>(
                                    sourceGeneral
                                    )
                            );
                        }

                        return false;
                    }

                    GAM_tdstAnim3d* runtime =
                        getRuntimeAnimation(
                            sourceIndex,
                            sourceAnimation
                        );

                    if (runtime == nullptr)
                    {
                        return false;
                    }

                    cursor->p_stAnim =
                        runtime;

                    if (
                        patchedStateCount <
                        64
                        )
                    {
                        patchedStates[
                            patchedStateCount++
                        ] = cursor;
                    }

                    if (report != nullptr)
                    {
                        fprintf(
                            report,
                            "  donor State %p: Water General %u -> runtime animation %p -> synthetic General %u%s\n",
                            cursor,
                            static_cast<unsigned int>(
                                sourceGeneral
                                ),
                            runtime,
                            static_cast<unsigned int>(
                                runtime->
                                uwNumOfA3dGENERAL
                                ),
                            sourceGeneral == 302
                            ? "  [302 EVENT SUPPRESSED]"
                            : ""
                        );
                    }
                }

                if (
                    stateCopy.hNextState ==
                    nullptr
                    )
                {
                    break;
                }

                cursor =
                    stateCopy.hNextState;
            }

            return true;
        };

    const unsigned long comportCount =
        script->ulNbComport <= 64
        ? script->ulNbComport
        : 64;

    for (
        unsigned long c = 0;
        c < comportCount;
        c++
        )
    {
        AI_tdstComport* comport =
            script->a_stComport + c;

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    comport
                    ),
                sizeof(AI_tdstComport)
            )
            )
        {
            return false;
        }

        AI_tdstComport comportCopy = {};

        if (
            !SafeReadMemory(
                comport,
                &comportCopy,
                sizeof(comportCopy)
            )
            )
        {
            return false;
        }

        unsigned int ruleCount =
            static_cast<unsigned int>(
                comportCopy.ucNbRules
                );

        if (ruleCount > 32)
        {
            ruleCount = 32;
        }

        for (
            unsigned int r = 0;
            r < ruleCount;
            r++
            )
        {
            AI_tdstTreeInterpret* tree =
                comportCopy.a_stRules + r;

            if (
                tree == nullptr ||
                !R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(
                        tree
                        ),
                    sizeof(
                        AI_tdstTreeInterpret
                        )
                )
                )
            {
                continue;
            }

            AI_tdstTreeInterpret treeCopy = {};

            if (
                !SafeReadMemory(
                    tree,
                    &treeCopy,
                    sizeof(treeCopy)
                ) ||
                treeCopy.p_stNodeInterpret ==
                nullptr
                )
            {
                continue;
            }

            for (
                unsigned int i = 0;
                i < 256;
                i++
                )
            {
                AI_tdstNodeInterpret* nodePtr =
                    treeCopy.
                    p_stNodeInterpret +
                    i;

                if (
                    !R2R_AddressReadable(
                        reinterpret_cast<uintptr_t>(
                            nodePtr
                            ),
                        sizeof(
                            AI_tdstNodeInterpret
                            )
                    )
                    )
                {
                    break;
                }

                AI_tdstNodeInterpret node = {};

                if (
                    !SafeReadMemory(
                        nodePtr,
                        &node,
                        sizeof(node)
                    )
                    )
                {
                    break;
                }

                const unsigned int type =
                    static_cast<unsigned int>(
                        node.eType
                        );

                if (
                    type == 24 &&
                    node.uParam.pvValue !=
                    nullptr &&
                    PointerInsideCrossLevelArena(
                        node.uParam.pvValue
                    )
                    )
                {
                    actionRefCount++;

                    if (
                        !patchStateChain(
                            reinterpret_cast<
                            HIE_tdstState*
                            >(
                                node.uParam.
                                pvValue
                                )
                        )
                        )
                    {
                        return false;
                    }
                }

                if (type == 8)
                {
                    break;
                }
            }
        }
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nREAL ACTION-ANIMATION BINDING\n"
            "------------------------------------------------------------\n"
            "Donor ActionRef nodes seen : %u\n"
            "Unique donor States patched: %u\n"
            "Water 301 synthetic         : %u\n"
            "Water 302 synthetic         : %u\n"
            "Water 303 synthetic         : %u\n"
            "Water 305 synthetic         : %u\n"
            "General 302 event           : SUPPRESSED ONLY FOR h.7.68\n"
            "Purpose                     : execute the real donor motion through the merged Bast animation bank\n\n",
            actionRefCount,
            patchedStateCount,
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[
                    0
                ]
                ),
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[
                    1
                ]
                ),
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[
                    2
                ]
                ),
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[
                    3
                ]
                )
        );

        fflush(report);
    }

    return patchedStateCount >= 4;
}

static bool R2R_IsAllowedAglaglRealActionState(
    HIE_tdstState* state,
    HIE_tdstState* originalSafeState
)
{
    if (
        state ==
        originalSafeState
        )
    {
        return true;
    }

    if (
        state == nullptr ||
        !PointerInsideCrossLevelArena(
            state
        ) ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                state
                ),
            sizeof(HIE_tdstState)
        )
        )
    {
        return false;
    }

    HIE_tdstState stateCopy = {};

    if (
        !SafeReadMemory(
            state,
            &stateCopy,
            sizeof(stateCopy)
        ) ||
        stateCopy.p_stAnim ==
        nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                stateCopy.p_stAnim
                ),
            sizeof(GAM_tdstAnim3d)
        )
        )
    {
        return false;
    }

    GAM_tdstAnim3d animation = {};

    if (
        !SafeReadMemory(
            stateCopy.p_stAnim,
            &animation,
            sizeof(animation)
        )
        )
    {
        return false;
    }

    for (int i = 0; i < 4; i++)
    {
        if (
            g_R2RActionSyntheticGeneralIds[i] !=
            0xFFFF &&
            animation.uwNumOfA3dGENERAL ==
            g_R2RActionSyntheticGeneralIds[i]
            )
        {
            return true;
        }
    }

    return false;
}



static bool R2R_BindGeneral302And303Real(
    AI_tdstScriptAI* script,
    GAM_tdstAnim3d* safeIdleAnimation,
    FILE* report
)
{
    if (
        script == nullptr ||
        script->a_stComport == nullptr ||
        script->ulNbComport == 0 ||
        script->ulNbComport > 64 ||
        safeIdleAnimation == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                safeIdleAnimation
                ),
            sizeof(GAM_tdstAnim3d)
        ) ||
        !g_A3dMergedBankInstalled
        )
    {
        return false;
    }

    GAM_tdstAnim3d* runtimeAnimation[4] =
    {
        nullptr, nullptr, nullptr, nullptr
    };

    // General 301 is the exact already-proven safe idle descriptor created
    // for the spawned Aglagl.
    runtimeAnimation[0] =
        safeIdleAnimation;

    HIE_tdstState* patchedStates[64] = {};
    unsigned int patchedStateCount = 0;
    unsigned int actionRefCount = 0;

    auto alreadyPatched =
        [&](HIE_tdstState* state) -> bool
        {
            for (
                unsigned int i = 0;
                i < patchedStateCount;
                i++
                )
            {
                if (
                    patchedStates[i] ==
                    state
                    )
                {
                    return true;
                }
            }

            return false;
        };

    auto getRuntimeAnimation =
        [&](int sourceIndex, const GAM_tdstAnim3d& source)
        -> GAM_tdstAnim3d*
        {
            if (
                sourceIndex < 0 ||
                sourceIndex >= 4
                )
            {
                return nullptr;
            }

            // h.7.75 isolation:
            // Water Generals 302 AND 303 get their real imported synthetic
            // animations. 301 and 305 deliberately reuse the proven-safe idle.
            if (
                sourceIndex != 1 &&
                sourceIndex != 2
                )
            {
                return safeIdleAnimation;
            }

            if (
                runtimeAnimation[
                    sourceIndex
                ] != nullptr
                )
            {
                return runtimeAnimation[
                    sourceIndex
                ];
            }

            if (
                R2_GameMallocInHLM ==
                nullptr
                )
            {
                return nullptr;
            }

            GAM_tdstAnim3d* clone =
                reinterpret_cast<GAM_tdstAnim3d*>(
                    R2_GameMallocInHLM(
                        static_cast<unsigned int>(
                            sizeof(
                                GAM_tdstAnim3d
                                )
                            )
                    )
                    );

            if (clone == nullptr)
            {
                return nullptr;
            }

            std::memcpy(
                clone,
                &source,
                sizeof(
                    GAM_tdstAnim3d
                    )
            );

            clone->uwNumOfA3dGENERAL =
                g_R2RActionSyntheticGeneralIds[
                    sourceIndex
                ];

            // h.7.75: Generals 302 and 303 are real in this test.
            // The single General-302 event remains suppressed until its Water payload is reconstructed.
            clone->ucNumberOfEvents = 0;
            clone->d_stAnimEvent = nullptr;

            // These animations have no morph payload.
            clone->d_stMorphDataArray = nullptr;

            runtimeAnimation[
                sourceIndex
            ] = clone;

            return clone;
        };

    auto patchStateChain =
        [&](HIE_tdstState* root) -> bool
        {
            if (
                root == nullptr ||
                !PointerInsideCrossLevelArena(
                    root
                )
                )
            {
                return true;
            }

            HIE_tdstState* visited[16] = {};
            unsigned int visitedCount = 0;

            HIE_tdstState* cursor =
                root;

            for (
                unsigned int chainIndex = 0;
                chainIndex < 12;
                chainIndex++
                )
            {
                if (
                    cursor == nullptr ||
                    !PointerInsideCrossLevelArena(
                        cursor
                    ) ||
                    !R2R_AddressReadable(
                        reinterpret_cast<uintptr_t>(
                            cursor
                            ),
                        sizeof(HIE_tdstState)
                    )
                    )
                {
                    break;
                }

                bool loop = false;

                for (
                    unsigned int v = 0;
                    v < visitedCount;
                    v++
                    )
                {
                    if (
                        visited[v] ==
                        cursor
                        )
                    {
                        loop = true;
                        break;
                    }
                }

                if (loop)
                {
                    break;
                }

                if (visitedCount < 16)
                {
                    visited[
                        visitedCount++
                    ] = cursor;
                }

                HIE_tdstState stateCopy = {};

                if (
                    !SafeReadMemory(
                        cursor,
                        &stateCopy,
                        sizeof(stateCopy)
                    )
                    )
                {
                    return false;
                }

                if (!alreadyPatched(cursor))
                {
                    GAM_tdstAnim3d sourceAnimation = {};

                    if (
                        stateCopy.p_stAnim ==
                        nullptr ||
                        !R2R_AddressReadable(
                            reinterpret_cast<uintptr_t>(
                                stateCopy.p_stAnim
                                ),
                            sizeof(
                                GAM_tdstAnim3d
                                )
                        ) ||
                        !SafeReadMemory(
                            stateCopy.p_stAnim,
                            &sourceAnimation,
                            sizeof(
                                sourceAnimation
                                )
                        )
                        )
                    {
                        return false;
                    }

                    const uint16_t sourceGeneral =
                        sourceAnimation.
                        uwNumOfA3dGENERAL;

                    const int sourceIndex =
                        R2R_ActionSourceGeneralIndex(
                            sourceGeneral
                        );

                    if (sourceIndex < 0)
                    {
                        if (report != nullptr)
                        {
                            fprintf(
                                report,
                                "FAIL: donor Action State %p references unimported Water General %u.\n",
                                cursor,
                                static_cast<unsigned int>(
                                    sourceGeneral
                                    )
                            );
                        }

                        return false;
                    }

                    GAM_tdstAnim3d* runtime =
                        getRuntimeAnimation(
                            sourceIndex,
                            sourceAnimation
                        );

                    if (runtime == nullptr)
                    {
                        return false;
                    }

                    cursor->p_stAnim =
                        runtime;

                    if (
                        patchedStateCount <
                        64
                        )
                    {
                        patchedStates[
                            patchedStateCount++
                        ] = cursor;
                    }

                    if (report != nullptr)
                    {
                        fprintf(
                            report,
                            "  donor State %p: Water General %u -> %s animation %p -> General %u%s\n",
                            cursor,
                            static_cast<unsigned int>(
                                sourceGeneral
                                ),
                            sourceGeneral == 302
                            ? "REAL-302"
                            : (
                                sourceGeneral == 303
                                ? "REAL-303"
                                : "SAFE-IDLE"
                                ),
                            runtime,
                            static_cast<unsigned int>(
                                runtime->
                                uwNumOfA3dGENERAL
                                ),
                            sourceGeneral == 302
                            ? "  [302 EVENT SUPPRESSED]"
                            : ""
                        );
                    }
                }

                if (
                    stateCopy.hNextState ==
                    nullptr
                    )
                {
                    break;
                }

                cursor =
                    stateCopy.hNextState;
            }

            return true;
        };

    const unsigned long comportCount =
        script->ulNbComport <= 64
        ? script->ulNbComport
        : 64;

    for (
        unsigned long c = 0;
        c < comportCount;
        c++
        )
    {
        AI_tdstComport* comport =
            script->a_stComport + c;

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    comport
                    ),
                sizeof(AI_tdstComport)
            )
            )
        {
            return false;
        }

        AI_tdstComport comportCopy = {};

        if (
            !SafeReadMemory(
                comport,
                &comportCopy,
                sizeof(comportCopy)
            )
            )
        {
            return false;
        }

        unsigned int ruleCount =
            static_cast<unsigned int>(
                comportCopy.ucNbRules
                );

        if (ruleCount > 32)
        {
            ruleCount = 32;
        }

        for (
            unsigned int r = 0;
            r < ruleCount;
            r++
            )
        {
            AI_tdstTreeInterpret* tree =
                comportCopy.a_stRules + r;

            if (
                tree == nullptr ||
                !R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(
                        tree
                        ),
                    sizeof(
                        AI_tdstTreeInterpret
                        )
                )
                )
            {
                continue;
            }

            AI_tdstTreeInterpret treeCopy = {};

            if (
                !SafeReadMemory(
                    tree,
                    &treeCopy,
                    sizeof(treeCopy)
                ) ||
                treeCopy.p_stNodeInterpret ==
                nullptr
                )
            {
                continue;
            }

            for (
                unsigned int i = 0;
                i < 256;
                i++
                )
            {
                AI_tdstNodeInterpret* nodePtr =
                    treeCopy.
                    p_stNodeInterpret +
                    i;

                if (
                    !R2R_AddressReadable(
                        reinterpret_cast<uintptr_t>(
                            nodePtr
                            ),
                        sizeof(
                            AI_tdstNodeInterpret
                            )
                    )
                    )
                {
                    break;
                }

                AI_tdstNodeInterpret node = {};

                if (
                    !SafeReadMemory(
                        nodePtr,
                        &node,
                        sizeof(node)
                    )
                    )
                {
                    break;
                }

                const unsigned int type =
                    static_cast<unsigned int>(
                        node.eType
                        );

                if (
                    type == 24 &&
                    node.uParam.pvValue !=
                    nullptr &&
                    PointerInsideCrossLevelArena(
                        node.uParam.pvValue
                    )
                    )
                {
                    actionRefCount++;

                    if (
                        !patchStateChain(
                            reinterpret_cast<
                            HIE_tdstState*
                            >(
                                node.uParam.
                                pvValue
                                )
                        )
                        )
                    {
                        return false;
                    }
                }

                if (type == 8)
                {
                    break;
                }
            }
        }
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nh.7.75 SELECTIVE ACTION-ANIMATION BINDING\n"
            "------------------------------------------------------------\n"
            "Donor ActionRef nodes seen : %u\n"
            "Unique donor States patched: %u\n"
            "Water 301                  : SAFE IDLE SUBSTITUTE\n"
            "Water 302                  : REAL synthetic General %u\n"
            "Water 303                  : REAL synthetic General %u\n"
            "Water 305                  : SAFE IDLE SUBSTITUTE\n"
            "General 302 event          : SUPPRESSED\n"
            "Purpose                    : play the complete real 302 -> 303 action chain while keeping 301/305 safe\n\n",
            actionRefCount,
            patchedStateCount,
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[
                    1
                ]
                ),
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[
                    2
                ]
                )
        );

        fflush(report);
    }

    return patchedStateCount >= 4;
}




static bool R2R_SubstituteDonorActionAnimationsWithSafeRuntime(
    AI_tdstScriptAI* script,
    GAM_tdstAnim3d* safeAnimation,
    FILE* report
)
{
    if (
        script == nullptr ||
        script->a_stComport == nullptr ||
        script->ulNbComport == 0 ||
        script->ulNbComport > 64 ||
        safeAnimation == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(safeAnimation),
            sizeof(GAM_tdstAnim3d)
        )
        )
    {
        return false;
    }

    HIE_tdstState* patchedStates[64] = {};
    unsigned int patchedStateCount = 0;
    unsigned int actionRefCount = 0;

    auto alreadyPatched = [&](HIE_tdstState* state) -> bool
        {
            for (unsigned int i = 0; i < patchedStateCount; i++)
            {
                if (patchedStates[i] == state)
                {
                    return true;
                }
            }
            return false;
        };

    auto patchStateChain = [&](HIE_tdstState* root) -> bool
        {
            if (
                root == nullptr ||
                !PointerInsideCrossLevelArena(root)
                )
            {
                return true;
            }

            HIE_tdstState* visited[16] = {};
            unsigned int visitedCount = 0;
            HIE_tdstState* cursor = root;

            for (unsigned int chainIndex = 0; chainIndex < 12; chainIndex++)
            {
                if (
                    cursor == nullptr ||
                    !PointerInsideCrossLevelArena(cursor) ||
                    !R2R_AddressReadable(
                        reinterpret_cast<uintptr_t>(cursor),
                        sizeof(HIE_tdstState)
                    )
                    )
                {
                    break;
                }

                bool loop = false;
                for (unsigned int v = 0; v < visitedCount; v++)
                {
                    if (visited[v] == cursor)
                    {
                        loop = true;
                        break;
                    }
                }

                if (loop)
                {
                    break;
                }

                if (visitedCount < 16)
                {
                    visited[visitedCount++] = cursor;
                }

                HIE_tdstState stateCopy = {};
                if (
                    !SafeReadMemory(
                        cursor,
                        &stateCopy,
                        sizeof(stateCopy)
                    )
                    )
                {
                    return false;
                }

                if (!alreadyPatched(cursor))
                {
                    unsigned int oldGeneral = 0xFFFFu;
                    GAM_tdstAnim3d oldAnim = {};
                    bool oldAnimReadable = false;

                    if (
                        stateCopy.p_stAnim != nullptr &&
                        R2R_AddressReadable(
                            reinterpret_cast<uintptr_t>(
                                stateCopy.p_stAnim
                                ),
                            sizeof(GAM_tdstAnim3d)
                        ) &&
                        SafeReadMemory(
                            stateCopy.p_stAnim,
                            &oldAnim,
                            sizeof(oldAnim)
                        )
                        )
                    {
                        oldGeneral =
                            static_cast<unsigned int>(
                                oldAnim.uwNumOfA3dGENERAL
                                );

                        oldAnimReadable = true;
                    }

                    // Only touch the donor Aglagl action states found by h.7.65.
                    // 301 = idle loop, 302 -> 303 = the crashing ChangeAction chain,
                    // 305 -> 301 = the other donor ChangeAction chain.
                    const bool knownAglaglAction =
                        oldAnimReadable &&
                        (
                            oldGeneral == 301u ||
                            oldGeneral == 302u ||
                            oldGeneral == 303u ||
                            oldGeneral == 305u
                            );

                    if (knownAglaglAction)
                    {
                        cursor->p_stAnim =
                            safeAnimation;

                        if (patchedStateCount < 64)
                        {
                            patchedStates[patchedStateCount++] =
                                cursor;
                        }

                        if (report != nullptr)
                        {
                            fprintf(
                                report,
                                "  donor State %p: General %u animation %p -> SAFE runtime animation %p (General %u)\n",
                                cursor,
                                oldGeneral,
                                stateCopy.p_stAnim,
                                safeAnimation,
                                static_cast<unsigned int>(
                                    safeAnimation->uwNumOfA3dGENERAL
                                    )
                            );
                        }
                    }
                }

                if (stateCopy.hNextState == nullptr)
                {
                    break;
                }

                cursor =
                    stateCopy.hNextState;
            }

            return true;
        };

    const unsigned long comportCount =
        script->ulNbComport <= 64
        ? script->ulNbComport
        : 64;

    for (unsigned long c = 0; c < comportCount; c++)
    {
        AI_tdstComport* comport =
            script->a_stComport + c;

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(comport),
                sizeof(AI_tdstComport)
            )
            )
        {
            return false;
        }

        AI_tdstComport comportCopy = {};
        if (
            !SafeReadMemory(
                comport,
                &comportCopy,
                sizeof(comportCopy)
            )
            )
        {
            return false;
        }

        unsigned int ruleCount =
            static_cast<unsigned int>(
                comportCopy.ucNbRules
                );

        if (ruleCount > 32)
        {
            ruleCount = 32;
        }

        for (unsigned int r = 0; r < ruleCount; r++)
        {
            AI_tdstTreeInterpret* tree =
                comportCopy.a_stRules + r;

            if (
                tree == nullptr ||
                !R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(tree),
                    sizeof(AI_tdstTreeInterpret)
                )
                )
            {
                continue;
            }

            AI_tdstTreeInterpret treeCopy = {};
            if (
                !SafeReadMemory(
                    tree,
                    &treeCopy,
                    sizeof(treeCopy)
                ) ||
                treeCopy.p_stNodeInterpret == nullptr
                )
            {
                continue;
            }

            for (unsigned int i = 0; i < 256; i++)
            {
                AI_tdstNodeInterpret* nodePtr =
                    treeCopy.p_stNodeInterpret + i;

                if (
                    !R2R_AddressReadable(
                        reinterpret_cast<uintptr_t>(nodePtr),
                        sizeof(AI_tdstNodeInterpret)
                    )
                    )
                {
                    break;
                }

                AI_tdstNodeInterpret node = {};
                if (
                    !SafeReadMemory(
                        nodePtr,
                        &node,
                        sizeof(node)
                    )
                    )
                {
                    break;
                }

                const unsigned int type =
                    static_cast<unsigned int>(
                        node.eType
                        );

                if (
                    type == 24 &&
                    node.uParam.pvValue != nullptr &&
                    PointerInsideCrossLevelArena(
                        node.uParam.pvValue
                    )
                    )
                {
                    actionRefCount++;

                    if (
                        !patchStateChain(
                            reinterpret_cast<HIE_tdstState*>(
                                node.uParam.pvValue
                                )
                        )
                        )
                    {
                        return false;
                    }
                }

                if (type == 8)
                {
                    break;
                }
            }
        }
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nCHANGEACTION POINTER-VALIDITY CONTROL\n"
            "------------------------------------------------------------\n"
            "Donor ActionRef nodes seen : %u\n"
            "Unique donor States patched: %u\n"
            "Temporary animation         : %p (known-safe imported idle)\n"
            "Purpose                     : prove ChangeAction can accept the donor State graph when its animation pointer is valid\n"
            "IMPORTANT                   : this is NOT the final animation import; 302/303/305 are temporarily shown as idle\n\n",
            actionRefCount,
            patchedStateCount,
            safeAnimation
        );
        fflush(report);
    }

    return patchedStateCount >= 4;
}





static bool R2R_ProjectileAuditIsKnown(
    HIE_tdstSuperObject* object
)
{
    if (object == nullptr)
    {
        return true;
    }

    for (
        unsigned int i = 0;
        i < g_R2RProjectileAuditKnownCount;
        i++
        )
    {
        if (
            g_R2RProjectileAuditKnown[i] ==
            object
            )
        {
            return true;
        }
    }

    return false;
}

static bool R2R_ProjectileAuditRemember(
    HIE_tdstSuperObject* object
)
{
    if (
        object == nullptr ||
        R2R_ProjectileAuditIsKnown(object)
        )
    {
        return true;
    }

    if (
        g_R2RProjectileAuditKnownCount >=
        (
            sizeof(g_R2RProjectileAuditKnown) /
            sizeof(g_R2RProjectileAuditKnown[0])
            )
        )
    {
        return false;
    }

    g_R2RProjectileAuditKnown[
        g_R2RProjectileAuditKnownCount++
    ] = object;

    return true;
}

static const char* R2R_ProjectileAuditSOTypeName(
    unsigned long type
)
{
    switch (type)
    {
    case HIE_C_Type_Unknown:
        return "Unknown";
    case HIE_C_Type_SuperObject:
        return "SuperObject";
    case HIE_C_Type_Actor:
        return "Actor";
    case HIE_C_Type_Sector:
        return "Sector";
    case HIE_C_Type_PO:
        return "PO";
    case HIE_C_Type_PO_Mirror:
        return "PO_Mirror";
    case HIE_C_Type_IPO:
        return "IPO";
    case HIE_C_Type_IPO_Mirror:
        return "IPO_Mirror";
    case HIE_C_Type_SpecialEffect:
        return "SpecialEffect";
    case HIE_C_Type_NoAction:
        return "NoAction";
    case HIE_C_Type_Mirror:
        return "Mirror";
    default:
        return "Other/Editor";
    }
}

static bool R2R_ProjectileAuditReadPosition(
    HIE_tdstSuperObject* object,
    float& x,
    float& y,
    float& z
)
{
    x = 0.0f;
    y = 0.0f;
    z = 0.0f;

    if (
        object == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(object),
            sizeof(HIE_tdstSuperObject)
        ) ||
        object->p_stGlobalMatrix == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                object->p_stGlobalMatrix
                ),
            sizeof(POS_tdstCompletePosition)
        )
        )
    {
        return false;
    }

    x = object->p_stGlobalMatrix->stPos.x;
    y = object->p_stGlobalMatrix->stPos.y;
    z = object->p_stGlobalMatrix->stPos.z;

    return true;
}

static PO_tdstPhysicalObject* R2R_ProjectileAuditGetPhysicalObject(
    HIE_tdstSuperObject* object
)
{
    if (
        object == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(object),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return nullptr;
    }

    if (
        object->ulType == HIE_C_Type_PO ||
        object->ulType == HIE_C_Type_PO_Mirror
        )
    {
        return object->hLinkedObject.p_stPhysicalObject;
    }

    if (
        object->ulType == HIE_C_Type_IPO ||
        object->ulType == HIE_C_Type_IPO_Mirror
        )
    {
        PO_tdstInstantiatedPhysicalObject* ipo =
            object->hLinkedObject.p_stInstantiatedPhysicalObject;

        if (
            ipo != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(ipo),
                sizeof(PO_tdstInstantiatedPhysicalObject)
            )
            )
        {
            return ipo->hPhysicalObject;
        }
    }

    return nullptr;
}

static int R2R_ProjectileAuditFindTracked(
    HIE_tdstSuperObject* object
)
{
    if (object == nullptr)
    {
        return -1;
    }

    for (
        unsigned int i = 0;
        i < g_R2RProjectileTrackedCount;
        i++
        )
    {
        if (
            g_R2RProjectileTracked[i].object ==
            object
            )
        {
            return static_cast<int>(i);
        }
    }

    return -1;
}

static void R2R_ProjectileAuditCaptureVisualIdentity(
    R2R_ProjectileTrackedObject& tracked,
    HIE_tdstSuperObject* object
)
{
    PO_tdstPhysicalObject* po =
        R2R_ProjectileAuditGetPhysicalObject(
            object
        );

    tracked.physicalObjectAtBirth = po;

    if (
        po == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(po),
            sizeof(PO_tdstPhysicalObject)
        )
        )
    {
        return;
    }

    PO_tdstPhysicalObject poCopy = {};

    if (
        !SafeReadMemory(
            po,
            &poCopy,
            sizeof(poCopy)
        )
        )
    {
        return;
    }

    tracked.visualSetAtBirth =
        poCopy.hVisualSet;

    tracked.collideSetAtBirth =
        poCopy.hCollideSet;

    tracked.boundingAtBirth =
        poCopy.hBoundingVolume;

    if (
        poCopy.hVisualSet != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                poCopy.hVisualSet
                ),
            sizeof(GEO_tdstVisualSet)
        )
        )
    {
        GEO_tdstVisualSet visual = {};

        if (
            SafeReadMemory(
                poCopy.hVisualSet,
                &visual,
                sizeof(visual)
            )
            )
        {
            tracked.lodCountAtBirth =
                static_cast<unsigned int>(
                    visual.xNbLodDefinitions
                    );

            if (
                visual.xNbLodDefinitions > 0 &&
                visual.xNbLodDefinitions <= 32 &&
                visual.d_p_stLodDefinitions != nullptr &&
                R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(
                        visual.d_p_stLodDefinitions
                        ),
                    sizeof(GEO_tdstGeometricObject*)
                )
                )
            {
                GEO_tdstGeometricObject* firstGeo =
                    nullptr;

                if (
                    SafeReadMemory(
                        visual.d_p_stLodDefinitions,
                        &firstGeo,
                        sizeof(firstGeo)
                    )
                    )
                {
                    tracked.firstGeoAtBirth =
                        firstGeo;
                }
            }
        }
    }

    GLI_tdstTexture* texture =
        reinterpret_cast<GLI_tdstTexture*>(
            R2R_FindFirstTextureFromTarget(
                po
            )
            );

    tracked.firstTextureAtBirth =
        texture;

    if (
        texture != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(texture),
            sizeof(GLI_tdstTexture)
        )
        )
    {
        GLI_tdstTexture textureCopy = {};

        if (
            SafeReadMemory(
                texture,
                &textureCopy,
                sizeof(textureCopy)
            )
            )
        {
            tracked.textureGpuAtBirth =
                textureCopy.p_stSpecParam;

            tracked.textureSubstitutionAtBirth =
                textureCopy.p_TextureOfSubstitution;

            tracked.textureAvailableAtBirth =
                static_cast<int>(
                    textureCopy.bIsAvailable
                    );

            strncpy_s(
                tracked.textureName,
                sizeof(tracked.textureName),
                textureCopy.szFileName,
                _TRUNCATE
            );
        }
    }
}

static int R2R_ProjectileAuditTrackNew(
    HIE_tdstSuperObject* parent,
    HIE_tdstSuperObject* object
)
{
    if (
        object == nullptr ||
        g_R2RProjectileTrackedCount >=
        (
            sizeof(g_R2RProjectileTracked) /
            sizeof(g_R2RProjectileTracked[0])
            )
        )
    {
        return -1;
    }

    const int existing =
        R2R_ProjectileAuditFindTracked(
            object
        );

    if (existing >= 0)
    {
        return existing;
    }

    const unsigned int index =
        g_R2RProjectileTrackedCount++;

    R2R_ProjectileTrackedObject& tracked =
        g_R2RProjectileTracked[index];

    std::memset(
        &tracked,
        0,
        sizeof(tracked)
    );

    tracked.object = object;
    tracked.parentAtBirth = parent;
    tracked.firstFrame =
        g_R2RAIMultiFramesCompleted;
    tracked.lastSeenFrame =
        g_R2RAIMultiFramesCompleted;
    tracked.presentLastScan = true;
    tracked.lateAttackCandidate =
        tracked.firstFrame > 1;
    tracked.seenFrames = 1;

    if (
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(object),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        tracked.typeAtBirth =
            static_cast<unsigned long>(
                object->ulType
                );

        tracked.linkedObjectAtBirth =
            object->hLinkedObject.p_Void;

        tracked.flagsAtBirth =
            static_cast<unsigned long>(
                object->ulFlags
                );

        tracked.drawMaskAtBirth =
            static_cast<unsigned long>(
                object->lDrawModeMask
                );
    }

    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;

    if (
        R2R_ProjectileAuditReadPosition(
            object,
            x,
            y,
            z
        )
        )
    {
        tracked.firstPositionValid = true;
        tracked.lastPositionValid = true;

        tracked.firstX = x;
        tracked.firstY = y;
        tracked.firstZ = z;

        tracked.lastX = x;
        tracked.lastY = y;
        tracked.lastZ = z;
    }

    R2R_ProjectileAuditCaptureVisualIdentity(
        tracked,
        object
    );

    return static_cast<int>(index);
}

static void R2R_ProjectileAuditMarkTrackedSeen(
    FILE* report,
    HIE_tdstSuperObject* object
)
{
    const int trackedIndex =
        R2R_ProjectileAuditFindTracked(
            object
        );

    if (trackedIndex < 0)
    {
        return;
    }

    R2R_ProjectileTrackedObject& tracked =
        g_R2RProjectileTracked[
            trackedIndex
        ];

    if (
        tracked.lastSeenFrame ==
        g_R2RAIMultiFramesCompleted
        )
    {
        return;
    }

    const int previousSeenFrame =
        tracked.lastSeenFrame;

    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;

    const bool positionValid =
        R2R_ProjectileAuditReadPosition(
            object,
            x,
            y,
            z
        );

    float stepDistance = 0.0f;

    if (
        positionValid &&
        tracked.lastPositionValid
        )
    {
        const float dx =
            x - tracked.lastX;

        const float dy =
            y - tracked.lastY;

        const float dz =
            z - tracked.lastZ;

        stepDistance =
            static_cast<float>(
                std::sqrt(
                    static_cast<double>(
                        (dx * dx) +
                        (dy * dy) +
                        (dz * dz)
                        )
                )
                );

        tracked.totalTravel +=
            stepDistance;

        if (
            stepDistance >
            tracked.maxStepDistance
            )
        {
            tracked.maxStepDistance =
                stepDistance;
        }
    }

    tracked.lastSeenFrame =
        g_R2RAIMultiFramesCompleted;

    tracked.seenFrames++;

    if (positionValid)
    {
        tracked.lastPositionValid = true;
        tracked.lastX = x;
        tracked.lastY = y;
        tracked.lastZ = z;
    }

    if (
        tracked.lateAttackCandidate &&
        report != nullptr
        )
    {
        fprintf(
            report,
            "\n>>> LATE ATTACK OBJECT TRACK #%d - FRAME %d <<<\n"
            "SuperObject            : %p\n"
            "First seen frame       : %d\n"
            "Previous seen frame    : %d\n"
            "Position readable      : %s\n",
            trackedIndex + 1,
            g_R2RAIMultiFramesCompleted,
            tracked.object,
            tracked.firstFrame,
            previousSeenFrame,
            positionValid ? "YES" : "NO"
        );

        if (positionValid)
        {
            fprintf(
                report,
                "Position               : %.6f %.6f %.6f\n"
                "Step distance          : %.6f\n"
                "Total travel           : %.6f\n",
                x,
                y,
                z,
                stepDistance,
                tracked.totalTravel
            );
        }

        if (
            object != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(object),
                sizeof(HIE_tdstSuperObject)
            )
            )
        {
            fprintf(
                report,
                "Current flags          : 0x%08lX\n"
                "Current draw mask      : 0x%08lX\n"
                "Current linked object  : %p\n",
                static_cast<unsigned long>(
                    object->ulFlags
                    ),
                static_cast<unsigned long>(
                    object->lDrawModeMask
                    ),
                object->hLinkedObject.p_Void
            );
        }

        fprintf(
            report,
            ">>> END LATE ATTACK OBJECT TRACK <<<\n"
        );
    }
}

static void R2R_ProjectileAuditFinalizeFrame(
    FILE* report
)
{
    for (
        unsigned int i = 0;
        i < g_R2RProjectileTrackedCount;
        i++
        )
    {
        R2R_ProjectileTrackedObject& tracked =
            g_R2RProjectileTracked[i];

        const bool presentNow =
            tracked.lastSeenFrame ==
            g_R2RAIMultiFramesCompleted;

        if (
            tracked.presentLastScan &&
            !presentNow
            )
        {
            tracked.presentLastScan = false;

            if (report != nullptr)
            {
                fprintf(
                    report,
                    "\n>>> TRACKED SUPEROBJECT DISAPPEARED #%u <<<\n"
                    "SuperObject            : %p\n"
                    "First seen frame       : %d\n"
                    "Last seen frame        : %d\n"
                    "First absent frame     : %d\n"
                    "Candidate class        : %s\n"
                    ">>> END DISAPPEARANCE <<<\n",
                    i + 1,
                    tracked.object,
                    tracked.firstFrame,
                    tracked.lastSeenFrame,
                    g_R2RAIMultiFramesCompleted,
                    tracked.lateAttackCandidate
                    ? "LATE ATTACK"
                    : "FRAME-1 STARTUP"
                );
            }
        }
        else if (
            !tracked.presentLastScan &&
            presentNow
            )
        {
            tracked.presentLastScan = true;

            if (report != nullptr)
            {
                fprintf(
                    report,
                    "\n>>> TRACKED SUPEROBJECT REAPPEARED #%u <<<\n"
                    "SuperObject            : %p\n"
                    "Frame                  : %d\n"
                    ">>> END REAPPEARANCE <<<\n",
                    i + 1,
                    tracked.object,
                    g_R2RAIMultiFramesCompleted
                );
            }
        }
    }
}

static void R2R_ProjectileAuditWriteTrackingSummary(
    FILE* report
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n============================================================\n"
        "PROJECTILE / PHYSICAL-OBJECT TRACKING SUMMARY\n"
        "============================================================\n"
        "Tracked post-baseline SuperObjects: %u\n"
        "Frame-1 objects are labelled STARTUP candidates.\n"
        "Objects first appearing after frame 1 are labelled LATE ATTACK candidates.\n\n",
        g_R2RProjectileTrackedCount
    );

    for (
        unsigned int i = 0;
        i < g_R2RProjectileTrackedCount;
        i++
        )
    {
        const R2R_ProjectileTrackedObject& tracked =
            g_R2RProjectileTracked[i];

        float displacement = 0.0f;

        if (
            tracked.firstPositionValid &&
            tracked.lastPositionValid
            )
        {
            const float dx =
                tracked.lastX -
                tracked.firstX;

            const float dy =
                tracked.lastY -
                tracked.firstY;

            const float dz =
                tracked.lastZ -
                tracked.firstZ;

            displacement =
                static_cast<float>(
                    std::sqrt(
                        static_cast<double>(
                            (dx * dx) +
                            (dy * dy) +
                            (dz * dz)
                            )
                    )
                    );
        }

        fprintf(
            report,
            "[#%u] %s\n"
            "  SuperObject       : %p\n"
            "  Type              : 0x%08lX (%s)\n"
            "  Parent at birth   : %p%s\n"
            "  Linked at birth   : %p\n"
            "  Flags / draw mask : 0x%08lX / 0x%08lX\n"
            "  First / last frame: %d / %d\n"
            "  Seen frames       : %d\n"
            "  Present at end    : %s\n"
            "  Position valid    : first=%s last=%s\n"
            "  First position    : %.6f %.6f %.6f\n"
            "  Last position     : %.6f %.6f %.6f\n"
            "  Net displacement  : %.6f\n"
            "  Total travel      : %.6f\n"
            "  Max frame step    : %.6f\n"
            "  PhysicalObject    : %p\n"
            "  VisualSet         : %p\n"
            "  FirstGeo          : %p\n"
            "  LOD count         : %u\n"
            "  CollideSet        : %p\n"
            "  BoundingVolume    : %p\n"
            "  First texture     : %p\n"
            "  Texture name      : %s\n"
            "  Texture GPU       : %p\n"
            "  Texture available : %d\n"
            "  Texture substitute: %p\n\n",
            i + 1,
            tracked.lateAttackCandidate
            ? "LATE ATTACK CANDIDATE"
            : "FRAME-1 STARTUP CANDIDATE",
            tracked.object,
            tracked.typeAtBirth,
            R2R_ProjectileAuditSOTypeName(
                tracked.typeAtBirth
            ),
            tracked.parentAtBirth,
            tracked.parentAtBirth ==
            g_SpawnedHybrid
            ? "  [DIRECT CHILD OF IMPORTED AGLAGL]"
            : "",
            tracked.linkedObjectAtBirth,
            tracked.flagsAtBirth,
            tracked.drawMaskAtBirth,
            tracked.firstFrame,
            tracked.lastSeenFrame,
            tracked.seenFrames,
            tracked.presentLastScan
            ? "YES"
            : "NO",
            tracked.firstPositionValid
            ? "YES"
            : "NO",
            tracked.lastPositionValid
            ? "YES"
            : "NO",
            tracked.firstX,
            tracked.firstY,
            tracked.firstZ,
            tracked.lastX,
            tracked.lastY,
            tracked.lastZ,
            displacement,
            tracked.totalTravel,
            tracked.maxStepDistance,
            tracked.physicalObjectAtBirth,
            tracked.visualSetAtBirth,
            tracked.firstGeoAtBirth,
            tracked.lodCountAtBirth,
            tracked.collideSetAtBirth,
            tracked.boundingAtBirth,
            tracked.firstTextureAtBirth,
            tracked.textureName[0] != '\0'
            ? tracked.textureName
            : "(none/unreadable)",
            tracked.textureGpuAtBirth,
            tracked.textureAvailableAtBirth,
            tracked.textureSubstitutionAtBirth
        );
    }

    fflush(report);
}

static void R2R_ProjectileAuditReportSuperObject(
    FILE* report,
    const char* worldName,
    HIE_tdstSuperObject* parent,
    HIE_tdstSuperObject* object,
    int trackedIndex
)
{
    if (
        report == nullptr ||
        object == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                object
                ),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return;
    }

    bool positionReadable = false;
    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;

    positionReadable =
        R2R_ProjectileAuditReadPosition(
            object,
            x,
            y,
            z
        );

    const R2R_ProjectileTrackedObject* tracked =
        (
            trackedIndex >= 0 &&
            static_cast<unsigned int>(
                trackedIndex
                ) <
            g_R2RProjectileTrackedCount
            )
        ? &g_R2RProjectileTracked[
            trackedIndex
        ]
        : nullptr;

    fprintf(
        report,
        "\n>>> NEW WORLD SUPEROBJECT #%u <<<\n"
        "Detected after frame   : %d\n"
        "Candidate class        : %s\n"
        "World tree             : %s\n"
        "SuperObject            : %p\n"
        "Parent SuperObject     : %p\n"
        "Parent is Aglagl       : %s\n"
        "SO type                : 0x%08lX (%s)\n"
        "Linked object          : %p\n"
        "SO flags               : 0x%08lX\n"
        "Draw mask              : 0x%08lX\n"
        "Local matrix           : %p\n"
        "Global matrix          : %p\n"
        "Position readable      : %s\n",
        g_R2RProjectileAuditNewCount,
        g_R2RAIMultiFramesCompleted,
        g_R2RAIMultiFramesCompleted > 1
        ? "LATE ATTACK"
        : "FRAME-1 STARTUP",
        worldName != nullptr
        ? worldName
        : "(unknown)",
        object,
        parent,
        parent == g_SpawnedHybrid
        ? "YES"
        : "NO",
        static_cast<unsigned long>(
            object->ulType
            ),
        R2R_ProjectileAuditSOTypeName(
            static_cast<unsigned long>(
                object->ulType
                )
        ),
        object->hLinkedObject.p_Void,
        static_cast<unsigned long>(
            object->ulFlags
            ),
        static_cast<unsigned long>(
            object->lDrawModeMask
            ),
        object->p_stLocalMatrix,
        object->p_stGlobalMatrix,
        positionReadable ? "YES" : "NO"
    );

    if (positionReadable)
    {
        fprintf(
            report,
            "Position               : %.6f %.6f %.6f\n",
            x,
            y,
            z
        );
    }

    if (
        object->ulType ==
        HIE_C_Type_Actor
        )
    {
        HIE_tdstEngineObject* actor =
            HIE_M_hSuperObjectGetActor(
                object
            );

        fprintf(
            report,
            "\nACTOR DETAILS\n"
            "------------------------------------------------------------\n"
            "Actor                  : %p\n",
            actor
        );

        if (
            actor != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    actor
                    ),
                sizeof(HIE_tdstEngineObject)
            ) &&
            actor->hStandardGame != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    actor->hStandardGame
                    ),
                sizeof(GAM_tdstStandardGame)
            )
            )
        {
            GAM_tdstStandardGame* stdGame =
                actor->hStandardGame;

            const char* familyName =
                HIE_fn_szGetObjectFamilyName(
                    object
                );

            const char* modelName =
                HIE_fn_szGetObjectModelName(
                    object
                );

            const char* personalName =
                HIE_fn_szGetObjectPersonalName(
                    object
                );

            GAM_tdst3dData* data =
                actor->h3dData;

            HIE_tdstState* currentState =
                data != nullptr
                ? data->h_CurrentState
                : nullptr;

            GAM_tdstAnim3d* anim = nullptr;
            unsigned int generalId = 0xFFFFu;
            unsigned int animFrames = 0;

            if (
                currentState != nullptr &&
                R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(
                        currentState
                        ),
                    sizeof(HIE_tdstState)
                )
                )
            {
                anim =
                    currentState->p_stAnim;

                if (
                    anim != nullptr &&
                    R2R_AddressReadable(
                        reinterpret_cast<uintptr_t>(
                            anim
                            ),
                        sizeof(GAM_tdstAnim3d)
                    )
                    )
                {
                    generalId =
                        static_cast<unsigned int>(
                            anim->uwNumOfA3dGENERAL
                            );

                    animFrames =
                        static_cast<unsigned int>(
                            anim->uwNumberOfFrames
                            );
                }
            }

            fprintf(
                report,
                "Family                 : %s\n"
                "Model                  : %s\n"
                "Personal               : %s\n"
                "Type IDs               : family=%ld model=%ld personal=%ld\n"
                "Custom bits            : 0x%08lX\n"
                "Brain                  : %p\n"
                "Dynamics               : %p\n"
                "3D data                : %p\n"
                "Current State          : %p\n"
                "Current Animation      : %p\n"
                "Animation General      : %u\n"
                "Animation frames       : %u\n",
                familyName != nullptr
                ? familyName
                : "(unknown family)",
                modelName != nullptr
                ? modelName
                : "(unknown model)",
                personalName != nullptr
                ? personalName
                : "(unknown personal)",
                stdGame->lObjectFamilyType,
                stdGame->lObjectModelType,
                stdGame->lObjectPersonalType,
                stdGame->ulCustomBits,
                actor->hBrain,
                actor->hDynam,
                actor->h3dData,
                currentState,
                anim,
                generalId,
                animFrames
            );
        }
        else
        {
            fprintf(
                report,
                "Actor metadata          : unreadable\n"
            );
        }
    }
    else if (
        object->ulType ==
        HIE_C_Type_PO ||
        object->ulType ==
        HIE_C_Type_PO_Mirror
        )
    {
        PO_tdstPhysicalObject* po =
            object->hLinkedObject.p_stPhysicalObject;

        fprintf(
            report,
            "\nPHYSICAL OBJECT DETAILS\n"
            "------------------------------------------------------------\n"
            "PhysicalObject         : %p\n",
            po
        );

        if (
            po != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    po
                    ),
                sizeof(PO_tdstPhysicalObject)
            )
            )
        {
            fprintf(
                report,
                "VisualSet              : %p\n"
                "CollideSet             : %p\n"
                "BoundingVolume         : %p\n",
                po->hVisualSet,
                po->hCollideSet,
                po->hBoundingVolume
            );
        }
    }
    else if (
        object->ulType ==
        HIE_C_Type_IPO ||
        object->ulType ==
        HIE_C_Type_IPO_Mirror
        )
    {
        PO_tdstInstantiatedPhysicalObject* ipo =
            object->hLinkedObject.p_stInstantiatedPhysicalObject;

        fprintf(
            report,
            "\nINSTANTIATED PO DETAILS\n"
            "------------------------------------------------------------\n"
            "Instantiated PO        : %p\n",
            ipo
        );

        if (
            ipo != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    ipo
                    ),
                sizeof(PO_tdstInstantiatedPhysicalObject)
            )
            )
        {
            fprintf(
                report,
                "PhysicalObject         : %p\n"
                "Radiosity              : %p\n",
                ipo->hPhysicalObject,
                ipo->hRadiosity
            );

            if (
                ipo->hPhysicalObject != nullptr &&
                R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(
                        ipo->hPhysicalObject
                        ),
                    sizeof(PO_tdstPhysicalObject)
                )
                )
            {
                fprintf(
                    report,
                    "Physical.VisualSet     : %p\n"
                    "Physical.CollideSet    : %p\n"
                    "Physical.Bounding      : %p\n",
                    ipo->hPhysicalObject->hVisualSet,
                    ipo->hPhysicalObject->hCollideSet,
                    ipo->hPhysicalObject->hBoundingVolume
                );
            }
        }
    }

    if (tracked != nullptr)
    {
        fprintf(
            report,
            "\nVISUAL / TEXTURE IDENTITY AT BIRTH\n"
            "------------------------------------------------------------\n"
            "PhysicalObject         : %p\n"
            "VisualSet              : %p\n"
            "FirstGeo               : %p\n"
            "LOD count              : %u\n"
            "CollideSet             : %p\n"
            "BoundingVolume         : %p\n"
            "First texture          : %p\n"
            "Texture name           : %s\n"
            "Texture GPU/spec       : %p\n"
            "Texture available      : %d\n"
            "Texture substitution   : %p\n",
            tracked->physicalObjectAtBirth,
            tracked->visualSetAtBirth,
            tracked->firstGeoAtBirth,
            tracked->lodCountAtBirth,
            tracked->collideSetAtBirth,
            tracked->boundingAtBirth,
            tracked->firstTextureAtBirth,
            tracked->textureName[0] != '\0'
            ? tracked->textureName
            : "(none/unreadable)",
            tracked->textureGpuAtBirth,
            tracked->textureAvailableAtBirth,
            tracked->textureSubstitutionAtBirth
        );
    }

    fprintf(
        report,
        ">>> END NEW WORLD SUPEROBJECT <<<\n"
    );

    fflush(report);
}

static void R2R_ProjectileAuditScanTreeRecursive(
    HIE_tdstSuperObject* root,
    const char* worldName,
    FILE* report,
    bool reportNew,
    int depth
)
{
    if (
        root == nullptr ||
        depth > 64 ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                root
                ),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return;
    }

    HIE_tdstSuperObject* object = nullptr;

    LST_M_DynamicForEach(
        root,
        object
    )
    {
        if (
            object == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    object
                    ),
                sizeof(HIE_tdstSuperObject)
            )
            )
        {
            continue;
        }

        R2R_ProjectileAuditMarkTrackedSeen(
            report,
            object
        );

        const bool wasKnown =
            R2R_ProjectileAuditIsKnown(
                object
            );

        if (!wasKnown)
        {
            const bool remembered =
                R2R_ProjectileAuditRemember(
                    object
                );

            if (
                reportNew &&
                remembered
                )
            {
                g_R2RProjectileAuditNewCount++;

                const int trackedIndex =
                    R2R_ProjectileAuditTrackNew(
                        root,
                        object
                    );

                R2R_ProjectileAuditReportSuperObject(
                    report,
                    worldName,
                    root,
                    object,
                    trackedIndex
                );
            }
        }

        R2R_ProjectileAuditScanTreeRecursive(
            object,
            worldName,
            report,
            reportNew,
            depth + 1
        );
    }
}

static void R2R_ProjectileAuditTakeBaseline(
    FILE* report
)
{
    g_R2RProjectileAuditKnownCount = 0;
    g_R2RProjectileAuditNewCount = 0;
    g_R2RProjectileTrackedCount = 0;

    std::memset(
        g_R2RProjectileTracked,
        0,
        sizeof(g_R2RProjectileTracked)
    );

    if (
        GAM_g_p_stDynamicWorld != nullptr &&
        *GAM_g_p_stDynamicWorld != nullptr
        )
    {
        R2R_ProjectileAuditScanTreeRecursive(
            *GAM_g_p_stDynamicWorld,
            "ACTIVE",
            report,
            false,
            0
        );
    }

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr
        )
    {
        R2R_ProjectileAuditScanTreeRecursive(
            *GAM_g_p_stInactiveDynamicWorld,
            "INACTIVE",
            report,
            false,
            0
        );
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "PROJECTILE/DEPENDENCY SUPEROBJECT BASELINE\n"
            "------------------------------------------------------------\n"
            "Known SuperObjects before attack: %u\n"
            "Scanner: recursive ACTIVE + INACTIVE hierarchy\n"
            "Types: Actor / PO / IPO / SpecialEffect / all others\n"
            "The old visible Piranha control is NOT spawned in h.7.79.\n"
            "h.7.81 resolves constant PersoRef nodes as EngineObject/Actor references and searches ACTIVE + INACTIVE world trees.\n"
            "Any brand-new SuperObject first appearing after this point is logged.\n\n",
            g_R2RProjectileAuditKnownCount
        );

        fflush(report);
    }
}

static void R2R_ProjectileAuditScanForNewActors(
    FILE* report
)
{
    if (
        GAM_g_p_stDynamicWorld != nullptr &&
        *GAM_g_p_stDynamicWorld != nullptr
        )
    {
        R2R_ProjectileAuditScanTreeRecursive(
            *GAM_g_p_stDynamicWorld,
            "ACTIVE",
            report,
            true,
            0
        );
    }

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr
        )
    {
        R2R_ProjectileAuditScanTreeRecursive(
            *GAM_g_p_stInactiveDynamicWorld,
            "INACTIVE",
            report,
            true,
            0
        );
    }

    R2R_ProjectileAuditFinalizeFrame(
        report
    );
}


// ============================================================
// h.7.81 - AGLAGL PERSOREF ACTOR + DSG HELPER DEPENDENCY TRACE
// ============================================================
//
// h.7.78 proved that the two late Physical Objects (#9/#10) really MOVE,
// while the yellow/electric object seen by the player remains visually fixed.
// Therefore those late POs are almost certainly animated pieces of Aglagl's
// hierarchy, not the gameplay projectile itself.
//
// Earlier Water_20 capture already identified Aglagl's Perso DSG variables:
//   #2 = Lums / BNT_grappinable / STN_BNT_grappinable_I8
//   #3 = stalac_glace / STN_Aglagla / STN_Aglagla
//   #4 = GenCamera / SUN_PosCam_Smooth / STN_CamSmooth
//   #5 = fleche / STN_direction / STN_direction_I1
//   #6 = fleche / STN_direction / STN_direction_I2
//
// The current cross-level clone only remaps #14/#15 (CHG_TexteMenu).  This
// audit proves whether #2..#6 are live Bast_20 world actors or merely retained
// donor-arena SuperObjects that the engine never updates as independent actors.
// Read-only: no DSG helper is patched in this build.

struct R2R_DsgHelperSpec
{
    unsigned int varIndex;
    unsigned long offset;
    const char* capturedRole;
};

static const R2R_DsgHelperSpec g_R2RDsgHelperSpecs[] =
{
    { 2u, 0x08u, "Lums / BNT_grappinable / STN_BNT_grappinable_I8" },
    { 3u, 0x0Cu, "stalac_glace / STN_Aglagla / STN_Aglagla" },
    { 4u, 0x10u, "GenCamera / SUN_PosCam_Smooth / STN_CamSmooth" },
    { 5u, 0x14u, "fleche / STN_direction / STN_direction_I1" },
    { 6u, 0x18u, "fleche / STN_direction / STN_direction_I2" }
};

static int R2R_DsgVarOwnerForOffset(
    unsigned int offset
)
{
    // Captured Water_20 DSG layout (80 bytes / 16 variables).
    struct Range { unsigned int begin; unsigned int end; };
    static const Range ranges[16] =
    {
        {0x00u,0x04u}, {0x04u,0x08u}, {0x08u,0x0Cu}, {0x0Cu,0x10u},
        {0x10u,0x14u}, {0x14u,0x18u}, {0x18u,0x1Cu}, {0x1Cu,0x20u},
        {0x20u,0x24u}, {0x24u,0x30u}, {0x30u,0x3Cu}, {0x3Cu,0x40u},
        {0x40u,0x44u}, {0x44u,0x48u}, {0x48u,0x4Cu}, {0x4Cu,0x50u}
    };

    for (int i = 0; i < 16; i++)
    {
        if (offset >= ranges[i].begin && offset < ranges[i].end)
        {
            return i;
        }
    }

    return -1;
}

static const char* R2R_DsgCapturedRoleForVar(
    int varIndex
)
{
    for (
        size_t i = 0;
        i < sizeof(g_R2RDsgHelperSpecs) / sizeof(g_R2RDsgHelperSpecs[0]);
        i++
        )
    {
        if (static_cast<int>(g_R2RDsgHelperSpecs[i].varIndex) == varIndex)
        {
            return g_R2RDsgHelperSpecs[i].capturedRole;
        }
    }

    if (varIndex == 14)
    {
        return "alphabet / CHG_TexteMenu / helper #0";
    }

    if (varIndex == 15)
    {
        return "alphabet / CHG_TexteMenu / helper #1";
    }

    return "(non-Perso or other DSG variable)";
}

static bool R2R_DsgHelperWorldContainsRecursive(
    HIE_tdstSuperObject* root,
    HIE_tdstSuperObject* target,
    int depth
)
{
    if (
        root == nullptr ||
        target == nullptr ||
        depth > 64 ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(root),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return false;
    }

    HIE_tdstSuperObject* object = nullptr;

    LST_M_DynamicForEach(root, object)
    {
        if (
            object == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(object),
                sizeof(HIE_tdstSuperObject)
            )
            )
        {
            continue;
        }

        if (object == target)
        {
            return true;
        }

        if (R2R_DsgHelperWorldContainsRecursive(object, target, depth + 1))
        {
            return true;
        }
    }

    return false;
}

static const char* R2R_DsgHelperWorldLocation(
    HIE_tdstSuperObject* target
)
{
    if (target == nullptr)
    {
        return "NULL";
    }

    if (
        GAM_g_p_stDynamicWorld != nullptr &&
        *GAM_g_p_stDynamicWorld != nullptr &&
        R2R_DsgHelperWorldContainsRecursive(
            *GAM_g_p_stDynamicWorld,
            target,
            0
        )
        )
    {
        return "ACTIVE";
    }

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr &&
        R2R_DsgHelperWorldContainsRecursive(
            *GAM_g_p_stInactiveDynamicWorld,
            target,
            0
        )
        )
    {
        return "INACTIVE";
    }

    return "NOT_IN_WORLD";
}

// ============================================================
// h.7.81 - CONSTANT PERSOREF ACTOR RESOLUTION AUDIT
// ============================================================
//
// h.7.79 proved two separate facts:
//   * Aglagl really rotates during the attack while its position stays fixed;
//   * DSG vars #5/#6 (STN_direction_I1/I2) are never referenced by the
//     controlled 180-frame path, while DSG var #3 (STN_Aglagla) is.
//
// The attack script also contains constant PersoRef nodes (type 23), notably
// one that receives Procedure 0x43/0x44 Comport changes immediately before
// the attack.  Their raw value is NOT a DSG offset.  This read-only audit
// resolves the raw address through zero, one and two pointer indirections and
// reports any candidate that is a real Actor SuperObject in Bast_20.
//
// No PersoRef, DSG value, Actor or world list is modified here.

static void* g_R2RPersoRefAuditSeen[128] = {};
static unsigned int g_R2RPersoRefAuditSeenCount = 0;

static bool R2R_PersoRefAuditWasSeen(void* raw)
{
    for (unsigned int i = 0; i < g_R2RPersoRefAuditSeenCount; i++)
    {
        if (g_R2RPersoRefAuditSeen[i] == raw)
        {
            return true;
        }
    }

    if (g_R2RPersoRefAuditSeenCount < 128)
    {
        g_R2RPersoRefAuditSeen[g_R2RPersoRefAuditSeenCount++] = raw;
    }

    return false;
}

static bool R2R_PersoRefAuditReadPointer(
    void* address,
    void*& outValue
)
{
    outValue = nullptr;

    if (
        address == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(address),
            sizeof(uint32_t)
        )
        )
    {
        return false;
    }

    uint32_t value = 0;

    if (!SafeReadMemory(address, &value, sizeof(value)))
    {
        return false;
    }

    outValue = reinterpret_cast<void*>(
        static_cast<uintptr_t>(value)
        );

    return true;
}

static bool R2R_PersoRefAuditFindActorInTree(
    HIE_tdstSuperObject* root,
    HIE_tdstEngineObject* wantedActor,
    HIE_tdstSuperObject*& outSO,
    int depth
)
{
    if (
        root == nullptr ||
        wantedActor == nullptr ||
        depth > 96
        )
    {
        return false;
    }

    if (root->ulType == HIE_C_Type_Actor)
    {
        HIE_tdstEngineObject* actor =
            HIE_M_hSuperObjectGetActor(root);

        if (actor == wantedActor)
        {
            outSO = root;
            return true;
        }
    }

    HIE_tdstSuperObject* child = nullptr;

    LST_M_DynamicForEach(root, child)
    {
        if (
            R2R_PersoRefAuditFindActorInTree(
                child,
                wantedActor,
                outSO,
                depth + 1
            )
            )
        {
            return true;
        }
    }

    return false;
}

static const char* R2R_PersoRefAuditFindActorWorldLocation(
    HIE_tdstEngineObject* actor,
    HIE_tdstSuperObject*& outSO
)
{
    outSO = nullptr;

    if (actor == nullptr)
    {
        return "NULL";
    }

    if (
        GAM_g_p_stDynamicWorld != nullptr &&
        *GAM_g_p_stDynamicWorld != nullptr &&
        R2R_PersoRefAuditFindActorInTree(
            *GAM_g_p_stDynamicWorld,
            actor,
            outSO,
            0
        )
        )
    {
        return "ACTIVE";
    }

    if (
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr &&
        R2R_PersoRefAuditFindActorInTree(
            *GAM_g_p_stInactiveDynamicWorld,
            actor,
            outSO,
            0
        )
        )
    {
        return "INACTIVE";
    }

    outSO = nullptr;
    return "NOT_IN_WORLD";
}

static const char* R2R_PersoRefAuditCapturedRoleForIds(
    long familyType,
    long modelType,
    long personalType
)
{
    if (familyType == 9 && modelType == 17 && personalType == 28)
    {
        return "MATCH DSG #2: Lums / BNT_grappinable / STN_BNT_grappinable_I8";
    }

    if (familyType == 10 && modelType == 22 && personalType == 37)
    {
        return "MATCH DSG #3: stalac_glace / STN_Aglagla / STN_Aglagla";
    }

    if (familyType == 17 && modelType == 23 && personalType == 38)
    {
        return "MATCH DSG #4: GenCamera / SUN_PosCam_Smooth / STN_CamSmooth";
    }

    if (familyType == 20 && modelType == 26 && personalType == 54)
    {
        return "MATCH DSG #5: fleche / STN_direction / STN_direction_I1";
    }

    if (familyType == 20 && modelType == 26 && personalType == 53)
    {
        return "MATCH DSG #6: fleche / STN_direction / STN_direction_I2";
    }

    return "no captured DSG-helper ID match";
}

static void R2R_PersoRefAuditReportActorCandidate(
    FILE* report,
    const char* label,
    void* candidate
)
{
    if (report == nullptr)
    {
        return;
    }

    HIE_tdstEngineObject* actor =
        reinterpret_cast<HIE_tdstEngineObject*>(candidate);

    HIE_tdstSuperObject* worldSO = nullptr;
    const char* worldLocation =
        R2R_PersoRefAuditFindActorWorldLocation(
            actor,
            worldSO
        );

    const bool actorReadable =
        actor != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actor),
            sizeof(HIE_tdstEngineObject)
        );

    HIE_tdstSuperObject* mainSO =
        HIE_M_hGetMainActor();

    HIE_tdstEngineObject* mainActor = nullptr;

    if (
        mainSO != nullptr &&
        mainSO->ulType == HIE_C_Type_Actor
        )
    {
        mainActor = HIE_M_hSuperObjectGetActor(mainSO);
    }

    fprintf(
        report,
        "  %-14s : %p domain=%s actorReadable=%s world=%s worldSO=%p\n"
        "                   mainRayman=%s importedAglagl=%s aglaglTemplate=%s stalacShootTemplate=%s\n",
        label != nullptr ? label : "candidate",
        candidate,
        PointerDomainFor3dAudit(candidate),
        actorReadable ? "YES" : "NO",
        worldLocation,
        worldSO,
        actor != nullptr && actor == mainActor ? "YES" : "NO",
        actor != nullptr && actor == g_SpawnedHybridActor ? "YES" : "NO",
        actor != nullptr && actor == g_AglaglTemplate ? "YES" : "NO",
        actor != nullptr && actor == g_R2RStalacShootRuntimeTemplate ? "YES" : "NO"
    );

    if (!actorReadable)
    {
        return;
    }

    HIE_tdstEngineObject actorCopy = {};

    if (!SafeReadMemory(actor, &actorCopy, sizeof(actorCopy)))
    {
        fprintf(report, "                   Actor struct SafeRead: FAILED\n");
        return;
    }

    fprintf(
        report,
        "                   h3dData=%p stdGame=%p dynam=%p brain=%p cine=%p coll=%p\n",
        actorCopy.h3dData,
        actorCopy.hStandardGame,
        actorCopy.hDynam,
        actorCopy.hBrain,
        actorCopy.hCineInfo,
        actorCopy.hCollSet
    );

    GAM_tdstStandardGame stdCopy = {};
    const bool stdReadable =
        actorCopy.hStandardGame != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actorCopy.hStandardGame),
            sizeof(GAM_tdstStandardGame)
        ) &&
        SafeReadMemory(
            actorCopy.hStandardGame,
            &stdCopy,
            sizeof(stdCopy)
        );

    if (stdReadable)
    {
        fprintf(
            report,
            "                   typeIDs=%ld / %ld / %ld custom=0x%08lX misc=0x%02X\n"
            "                   captured-ID interpretation: %s\n",
            stdCopy.lObjectFamilyType,
            stdCopy.lObjectModelType,
            stdCopy.lObjectPersonalType,
            static_cast<unsigned long>(stdCopy.ulCustomBits),
            static_cast<unsigned int>(stdCopy.ucMiscFlags),
            R2R_PersoRefAuditCapturedRoleForIds(
                stdCopy.lObjectFamilyType,
                stdCopy.lObjectModelType,
                stdCopy.lObjectPersonalType
            )
        );

        if (
            stdCopy.lObjectFamilyType == R2R_GENOBJ_WATER_FAMILY_TYPE &&
            stdCopy.lObjectModelType == R2R_GENOBJ_WATER_MODEL_TYPE &&
            stdCopy.lObjectPersonalType == R2R_GENOBJ_WATER_PERSONAL_TYPE
            )
        {
            fprintf(
                report,
                "                   GENERATEOBJECT TARGET 10/11/11: YES\n"
                "                   Water_20 identity: %s / %s / %s\n"
                "                   Water Always exact template captured: %s (matches=%u)\n"
                "                   Water Always custom/misc: 0x%08lX / 0x%02X\n",
                g_R2RGenerateObjectTemplateCapture.familyName[0] != '\0'
                ? g_R2RGenerateObjectTemplateCapture.familyName
                : "(uncaptured family)",
                g_R2RGenerateObjectTemplateCapture.modelName[0] != '\0'
                ? g_R2RGenerateObjectTemplateCapture.modelName
                : "(uncaptured model)",
                g_R2RGenerateObjectTemplateCapture.personalName[0] != '\0'
                ? g_R2RGenerateObjectTemplateCapture.personalName
                : "(uncaptured personal)",
                g_R2RGenerateObjectTemplateCapture.exactAlwaysFound
                ? "YES"
                : "NO",
                g_R2RGenerateObjectTemplateCapture.exactAlwaysMatchCount,
                g_R2RGenerateObjectTemplateCapture.exactCustomBits,
                g_R2RGenerateObjectTemplateCapture.exactMiscFlags
            );
        }

        if (
            actor != nullptr &&
            actor == g_R2RStalacShootRuntimeTemplate
            )
        {
            fprintf(
                report,
                "                   RUNTIME STALAC SHOOT TEMPLATE: YES\n"
                "                   Bast runtime IDs: %ld / %ld / %ld\n"
                "                   GenerateObject PersoRef was redirected here by h.7.83.\n",
                g_R2RStalacShootFamilyType,
                g_R2RStalacShootModelType,
                g_R2RStalacShootPersonalType
            );
        }
    }
    else
    {
        fprintf(
            report,
            "                   StandardGame readable: NO\n"
        );
    }

    if (worldSO != nullptr)
    {
        const char* familyName =
            HIE_fn_szGetObjectFamilyName(worldSO);
        const char* modelName =
            HIE_fn_szGetObjectModelName(worldSO);
        const char* personalName =
            HIE_fn_szGetObjectPersonalName(worldSO);

        fprintf(
            report,
            "                   WORLD IDENTITY=%s / %s / %s\n",
            familyName != nullptr ? familyName : "(unknown)",
            modelName != nullptr ? modelName : "(unknown)",
            personalName != nullptr ? personalName : "(unknown)"
        );

        if (
            worldSO->p_stGlobalMatrix != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(worldSO->p_stGlobalMatrix),
                sizeof(POS_tdstCompletePosition)
            )
            )
        {
            fprintf(
                report,
                "                   WORLD POSITION=%.6f %.6f %.6f\n",
                worldSO->p_stGlobalMatrix->stPos.x,
                worldSO->p_stGlobalMatrix->stPos.y,
                worldSO->p_stGlobalMatrix->stPos.z
            );
        }
    }
}

static void R2R_PersoRefAuditReportFirstSeen(
    FILE* report,
    void* raw
)
{
    if (
        report == nullptr ||
        raw == nullptr ||
        R2R_PersoRefAuditWasSeen(raw)
        )
    {
        return;
    }

    void* indirect1 = nullptr;
    void* indirect2 = nullptr;

    const bool read1 =
        R2R_PersoRefAuditReadPointer(raw, indirect1);

    const bool read2 =
        read1 &&
        R2R_PersoRefAuditReadPointer(indirect1, indirect2);

    fprintf(
        report,
        "\n>>> CONSTANT PERSOREF ACTOR RESOLUTION <<<\n"
        "Current attack frame : %d\n"
        "Raw node value       : %p\n"
        "Raw domain           : %s\n"
        "*raw readable/value  : %s / %p\n"
        "**raw readable/value : %s / %p\n"
        "NOTE: AI_Scr.h exposes PersoRef-compatible node storage as hActor;\n"
        "      hActor is HIE_tdstEngineObject*, NOT HIE_tdstSuperObject*.\n",
        g_R2RAIMultiFramesCompleted + 1,
        raw,
        PointerDomainFor3dAudit(raw),
        read1 ? "YES" : "NO",
        indirect1,
        read2 ? "YES" : "NO",
        indirect2
    );

    R2R_PersoRefAuditReportActorCandidate(
        report,
        "raw-as-ACTOR",
        raw
    );

    R2R_PersoRefAuditReportActorCandidate(
        report,
        "*raw-as-ACTOR",
        indirect1
    );

    R2R_PersoRefAuditReportActorCandidate(
        report,
        "**raw-as-ACTOR",
        indirect2
    );

    fprintf(
        report,
        ">>> END CONSTANT PERSOREF ACTOR RESOLUTION <<<\n\n"
    );
}

static void R2R_ReportCurrentCloneDsgHelpers(
    FILE* report,
    const char* phase
)
{
    if (
        report == nullptr ||
        g_SpawnedHybridActor == nullptr ||
        g_SpawnedHybridActor->hBrain == nullptr ||
        g_SpawnedHybridActor->hBrain->p_stMind == nullptr
        )
    {
        return;
    }

    AI_tdstMind* mind =
        g_SpawnedHybridActor->hBrain->p_stMind;

    AI_tdstDsgMem* dsgMem =
        mind->p_stDsgMem;

    if (
        dsgMem == nullptr ||
        dsgMem->p_cDsgMemBuffer == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(dsgMem->p_cDsgMemBuffer),
            0x50
        )
        )
    {
        fprintf(
            report,
            "\n>>> DSG HELPER SNAPSHOT [%s] <<<\nDSG buffer unreadable.\n",
            phase != nullptr ? phase : "(unknown)"
        );
        return;
    }

    fprintf(
        report,
        "\n>>> DSG HELPER SNAPSHOT [%s] <<<\n"
        "frame=%d  cloneSO=%p  cloneActor=%p\n"
        "NOTE: expected identity comes from the live Water_20 F3 capture.\n"
        "      world=NOT_IN_WORLD means the pointer is readable but is NOT an actor\n"
        "      linked into Bast_20's ACTIVE/INACTIVE SuperObject hierarchy.\n",
        phase != nullptr ? phase : "(unknown)",
        g_R2RAIMultiFramesCompleted,
        g_SpawnedHybrid,
        g_SpawnedHybridActor
    );

    for (
        size_t i = 0;
        i < sizeof(g_R2RDsgHelperSpecs) / sizeof(g_R2RDsgHelperSpecs[0]);
        i++
        )
    {
        const R2R_DsgHelperSpec& spec =
            g_R2RDsgHelperSpecs[i];

        uint32_t raw = 0;
        std::memcpy(
            &raw,
            dsgMem->p_cDsgMemBuffer + spec.offset,
            sizeof(raw)
        );

        HIE_tdstSuperObject* so =
            reinterpret_cast<HIE_tdstSuperObject*>(
                static_cast<uintptr_t>(raw)
                );

        const bool soReadable =
            so != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(so),
                sizeof(HIE_tdstSuperObject)
            );

        unsigned long soType = 0xFFFFFFFFul;
        HIE_tdstEngineObject* actor = nullptr;
        GAM_tdstStandardGame* stdGame = nullptr;
        bool actorReadable = false;
        bool positionReadable = false;
        float x = 0.0f;
        float y = 0.0f;
        float z = 0.0f;

        if (soReadable)
        {
            soType = static_cast<unsigned long>(so->ulType);

            if (so->p_stGlobalMatrix != nullptr &&
                R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(so->p_stGlobalMatrix),
                    sizeof(POS_tdstCompletePosition)
                ))
            {
                positionReadable = true;
                x = so->p_stGlobalMatrix->stPos.x;
                y = so->p_stGlobalMatrix->stPos.y;
                z = so->p_stGlobalMatrix->stPos.z;
            }

            if (so->ulType == HIE_C_Type_Actor)
            {
                actor = HIE_M_hSuperObjectGetActor(so);
                actorReadable =
                    actor != nullptr &&
                    R2R_AddressReadable(
                        reinterpret_cast<uintptr_t>(actor),
                        sizeof(HIE_tdstEngineObject)
                    );

                if (
                    actorReadable &&
                    actor->hStandardGame != nullptr &&
                    R2R_AddressReadable(
                        reinterpret_cast<uintptr_t>(actor->hStandardGame),
                        sizeof(GAM_tdstStandardGame)
                    )
                    )
                {
                    stdGame = actor->hStandardGame;
                }
            }
        }

        const char* expectedFamily = "(capture unavailable)";
        const char* expectedModel = "(capture unavailable)";
        const char* expectedPersonal = "(capture unavailable)";

        if (spec.varIndex < g_R2RLiveDsgPersoIdentityCount)
        {
            const R2R_DsgPersoIdentity& captured =
                g_R2RLiveDsgPersoIdentity[spec.varIndex];

            if (captured.familyName[0] != '\0') expectedFamily = captured.familyName;
            if (captured.modelName[0] != '\0') expectedModel = captured.modelName;
            if (captured.personalName[0] != '\0') expectedPersonal = captured.personalName;
        }

        fprintf(
            report,
            "\nVAR #%u offset=0x%02lX\n"
            "  captured role     : %s\n"
            "  expected identity : %s / %s / %s\n"
            "  raw SuperObject   : 0x%08X\n"
            "  pointer domain    : %s\n"
            "  world location    : %s\n"
            "  SO readable/type  : %s / 0x%08lX\n"
            "  linked Actor      : %p  readable=%s\n"
            "  Brain / Dynam     : %p / %p\n",
            spec.varIndex,
            spec.offset,
            spec.capturedRole,
            expectedFamily,
            expectedModel,
            expectedPersonal,
            static_cast<unsigned int>(raw),
            PointerDomainFor3dAudit(so),
            R2R_DsgHelperWorldLocation(so),
            soReadable ? "YES" : "NO",
            soType,
            actor,
            actorReadable ? "YES" : "NO",
            actorReadable ? actor->hBrain : nullptr,
            actorReadable ? actor->hDynam : nullptr
        );

        if (stdGame != nullptr)
        {
            fprintf(
                report,
                "  runtime type IDs  : family=%ld model=%ld personal=%ld\n"
                "  custom/misc       : 0x%08lX / 0x%02X\n",
                stdGame->lObjectFamilyType,
                stdGame->lObjectModelType,
                stdGame->lObjectPersonalType,
                static_cast<unsigned long>(stdGame->ulCustomBits),
                static_cast<unsigned int>(stdGame->ucMiscFlags)
            );
        }

        if (positionReadable)
        {
            fprintf(
                report,
                "  SO position       : %.6f %.6f %.6f\n",
                x, y, z
            );
        }
        else
        {
            fprintf(report, "  SO position       : (unreadable)\n");
        }
    }

    fprintf(report, ">>> END DSG HELPER SNAPSHOT <<<\n");
    fflush(report);
}


static bool R2R_ArmOneRealAglaglAIFrame()
{
    if (
        g_SpawnedHybrid == nullptr ||
        g_SpawnedHybridActor == nullptr ||
        g_SpawnedHybridActor->hStandardGame == nullptr ||
        g_SpawnedHybridActor->h3dData == nullptr ||
        g_AglaglTemplate == nullptr ||
        g_AglaglTemplate->hBrain == nullptr ||
        !g_R2RLiveAIStateCaptured
        )
    {
        return false;
    }

    AI_fn_vBrainCopyClone(
        g_SpawnedHybridActor,
        g_AglaglTemplate
    );

    if (
        g_SpawnedHybridActor->hBrain == nullptr ||
        g_SpawnedHybridActor->hBrain->p_stMind == nullptr
        )
    {
        return false;
    }

    AI_tdstMind* cloneMind =
        g_SpawnedHybridActor->hBrain->p_stMind;

    AI_tdstIntelligence* active =
        R2R_GetActiveIntelligence(
            cloneMind
        );

    AI_tdstScriptAI* script =
        R2R_GetScriptAIFromIntelligence(
            active
        );

    if (
        active == nullptr ||
        script == nullptr ||
        script->a_stComport == nullptr ||
        g_R2RLiveAICurrentComportIndex < 0 ||
        static_cast<unsigned long>(
            g_R2RLiveAICurrentComportIndex
            ) >= script->ulNbComport
        )
    {
        return false;
    }

    active->p_stCurrentComport =
        script->a_stComport +
        g_R2RLiveAICurrentComportIndex;

    AI_tdstDsgMem* dsgMem =
        cloneMind->p_stDsgMem;

    if (
        dsgMem == nullptr ||
        dsgMem->p_cDsgMemBuffer == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                dsgMem->p_cDsgMemBuffer
                ),
            0x50
        )
        )
    {
        return false;
    }

    FILE* resolveReport = nullptr;

    fopen_s(
        &resolveReport,
        R2R_AI_FRAME_REPORT_FILE,
        "w"
    );

    R2R_ModelActorMatch chg0 = {};
    R2R_ModelActorMatch chg1 = {};
    unsigned int liveCount = 0;

    const bool livePairFound =
        R2R_FindLiveCHGTexteMenuPair(
            chg0,
            chg1,
            liveCount
        );

    const long directModelLookup =
        HIE_fn_lFindModelTypeByName(
            "CHG_TexteMenu"
        );

    long alwaysModelType =
        GAM_C_InvalidObjectType;

    ALW_tdstAlwaysModelList* alwaysTemplate =
        nullptr;

    bool allocatedFromAlways =
        false;

    if (!livePairFound)
    {
        alwaysTemplate =
            R2R_FindAlwaysTemplateByModelName(
                "CHG_TexteMenu",
                alwaysModelType
            );

        if (
            alwaysTemplate != nullptr &&
            alwaysModelType !=
            GAM_C_InvalidObjectType
            )
        {
            allocatedFromAlways =
                R2R_AllocateNativeCHGPairFromAlways(
                    alwaysModelType,
                    chg0,
                    chg1
                );
        }
    }

    const bool dependencyPairReady =
        livePairFound ||
        allocatedFromAlways;

    if (resolveReport != nullptr)
    {
        fprintf(
            resolveReport,
            "RAYMAN 2 RANDOMIZER\n"
            "v0.0.14b.0 - DSG HELPER DEPENDENCY AUDIT\n"
            "============================================================\n\n"
            "WHY 7.54 FAILED:\n"
            "The previous build required TWO already-live CHG_TexteMenu actors\n"
            "inside Bast_20's dynamic/inactive world lists.\n"
            "Bast_20 does not necessarily keep those helper actors live.\n\n"
            "h.7.54b first uses the exact old object-scanner list traversal.\n"
            "If no live pair exists, it searches Rayman 2's native Always\n"
            "template list and tries to allocate TWO native CHG_TexteMenu\n"
            "runtime instances instead.\n\n"
            "Live CHG matches found       : %u\n"
            "Live pair ready              : %s\n"
            "Direct model lookup          : %ld\n"
            "Always template node         : %p\n"
            "Always template model type   : %ld\n"
            "Allocated pair from Always   : %s\n"
            "FINAL dependency pair ready  : %s\n\n"
            "CHG #0 SuperObject           : %p\n"
            "CHG #0 Actor                 : %p\n"
            "CHG #1 SuperObject           : %p\n"
            "CHG #1 Actor                 : %p\n\n",
            liveCount,
            livePairFound ? "YES" : "NO",
            directModelLookup,
            alwaysTemplate,
            alwaysModelType,
            allocatedFromAlways
            ? "YES"
            : "NO",
            dependencyPairReady
            ? "YES"
            : "NO",
            chg0.superObject,
            chg0.actor,
            chg1.superObject,
            chg1.actor
        );

        fflush(resolveReport);
    }

    if (!dependencyPairReady)
    {
        if (resolveReport != nullptr)
        {
            fprintf(
                resolveReport,
                "RESULT: COULD NOT RESOLVE NATIVE CHG_TEXTE_MENU DEPENDENCIES\n"
                "No AI/mechanics frame was executed.\n"
            );

            fclose(resolveReport);
        }

        return false;
    }

    // h.7.83: prepare the missing Water_20 Always template that the real
    // Function 0x42 (GenerateObject) uses during the attack.
    const bool stalacShootImportReady =
        R2R_PrepareStalacShootRuntimeImport(
            script,
            resolveReport
        );

    if (!stalacShootImportReady)
    {
        if (resolveReport != nullptr)
        {
            fprintf(
                resolveReport,
                "\nRESULT: STALAC SHOOT RUNTIME IMPORT COULD NOT BE PREPARED.\n"
                "No guarded AI/mechanics frame was executed.\n"
            );

            fclose(resolveReport);
        }

        R2R_FinalizeStalacShootImport(nullptr);
        return false;
    }

    // h.7.72 isolation:
    // h.7.69 proved expanded bank + animation is safe.
    // h.7.70 proved expanded bank + REAL Brain + animation is safe.
    // h.7.71b proved expanded bank + REAL mechanics + animation is safe.
    //
    // Now enable ALL THREE at once, but keep donor ActionRef animations
    // temporarily redirected to the known-safe idle.  This isolates whether
    // the h.7.68 frame-29 crash requires the three-way interaction itself,
    // without allowing the real 302/303/305 action animations to participate.

    DNM_fn_vDynamCopyClone(
        g_SpawnedHybridActor,
        g_AglaglTemplate
    );

    if (
        g_SpawnedHybridActor->hDynam == nullptr ||
        g_SpawnedHybridActor->hDynam->p_stDynamics == nullptr
        )
    {
        if (resolveReport != nullptr)
        {
            fprintf(
                resolveReport,
                "FAIL: REAL Aglagl Dynamics clone unavailable.\n"
            );
            fclose(resolveReport);
        }

        R2R_FinalizeStalacShootImport(nullptr);
        return false;
    }

    const unsigned long VAR14_OFFSET = 0x48;
    const unsigned long VAR15_OFFSET = 0x4C;

    uint32_t var14Before = 0;
    uint32_t var15Before = 0;

    const uint32_t var14After =
        static_cast<uint32_t>(
            reinterpret_cast<uintptr_t>(
                chg0.superObject
                )
            );

    const uint32_t var15After =
        static_cast<uint32_t>(
            reinterpret_cast<uintptr_t>(
                chg1.superObject
                )
            );

    std::memcpy(
        &var14Before,
        dsgMem->p_cDsgMemBuffer +
        VAR14_OFFSET,
        sizeof(var14Before)
    );

    std::memcpy(
        &var15Before,
        dsgMem->p_cDsgMemBuffer +
        VAR15_OFFSET,
        sizeof(var15Before)
    );

    std::memcpy(
        dsgMem->p_cDsgMemBuffer +
        VAR14_OFFSET,
        &var14After,
        sizeof(var14After)
    );

    std::memcpy(
        dsgMem->p_cDsgMemBuffer +
        VAR15_OFFSET,
        &var15After,
        sizeof(var15After)
    );

    GAM_tdst3dData* data =
        g_SpawnedHybridActor->h3dData;

    g_R2RSafeInitialStateBeforeAI =
        data->h_InitialState;
    g_R2RSafeCurrentStateBeforeAI =
        data->h_CurrentState;
    g_R2RSafeFirstStateBeforeAI =
        data->h_FirstStateOfAction;
    g_R2RSafeWantedStateBeforeAI =
        data->h_WantedState;
    g_R2RSafeLastStateBeforeAI =
        data->h_StateInLastFrame;

    GAM_tdstAnim3d* safeActionAnimation =
        (
            g_R2RSafeCurrentStateBeforeAI != nullptr
            )
        ? g_R2RSafeCurrentStateBeforeAI->p_stAnim
        : nullptr;

    const bool actionSubstitutionReady =
        R2R_BindGeneral302And303Real(
            script,
            safeActionAnimation,
            resolveReport
        );

    if (!actionSubstitutionReady)
    {
        if (resolveReport != nullptr)
        {
            fprintf(
                resolveReport,
                "FAIL: donor ActionRef state animation substitution could not be prepared.\n"
            );
            fclose(resolveReport);
        }

        R2R_FinalizeStalacShootImport(nullptr);
        return false;
    }

    if (resolveReport != nullptr)
    {
        fprintf(
            resolveReport,
            "DSG REMAP\n"
            "------------------------------------------------------------\n"
            "Current Comport applied : %d\n"
            "Var #14 0x48            : 0x%08X -> 0x%08X\n"
            "Var #15 0x4C            : 0x%08X -> 0x%08X\n"
            "Dependency source       : %s\n"
            "Dynamics source         : REAL Water_20 Aglagl clone\n"
            "Animation player        : ENABLED; expanded 301/302/303/305 bank stays installed\n"
            "Mechanics               : ENABLED for all 60 frames\n"
            "AI                      : ENABLED for up to 60 traced frames\n\n",
            g_R2RLiveAICurrentComportIndex,
            static_cast<unsigned int>(
                var14Before
                ),
            static_cast<unsigned int>(
                var14After
                ),
            static_cast<unsigned int>(
                var15Before
                ),
            static_cast<unsigned int>(
                var15After
                ),
            livePairFound
            ? "already-live Bast_20 actors"
            : "native Bast_20 Always allocation"
        );

        fflush(resolveReport);
        fclose(resolveReport);
    }

    if (g_R2RAITraceFile != nullptr)
    {
        fclose(g_R2RAITraceFile);
        g_R2RAITraceFile = nullptr;
    }

    std::memset(
        g_R2RPersoRefAuditSeen,
        0,
        sizeof(g_R2RPersoRefAuditSeen)
    );
    g_R2RPersoRefAuditSeenCount = 0;

    fopen_s(
        &g_R2RAITraceFile,
        R2R_AI_EVAL_TRACE_FILE,
        "w"
    );

    if (g_R2RAITraceFile == nullptr)
    {
        R2R_FinalizeStalacShootImport(nullptr);
        return false;
    }

    setvbuf(
        g_R2RAITraceFile,
        nullptr,
        _IONBF,
        0
    );

    fprintf(
        g_R2RAITraceFile,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - STALAC SHOOT REAL GENERATEOBJECT BIRTH FIX\n"
        "============================================================\n\n"
        "var #14 -> CHG #0 runtime SO: %p\n"
        "var #15 -> CHG #1 runtime SO: %p\n"
        "source: %s\n"
        "captured live current: Comport %d\n"
        "AI+mechanics+animation frames requested: up to 180\n"
        "Brain: REAL Aglagl\n"
        "Dynamics/mechanics: ENABLED (REAL Aglagl)\n"
        "Mechanics: ENABLED\n"
        "Animation player: ENABLED\n"
        "Starting state: safe imported idle; Water Generals 302+303 are REAL. 301/305 remain safe-idle substitutes\n"
        "Guard: safe idle OR controlled donor Action states only\n"
        "The full real 302 -> 303 chain is ALLOWED to continue so both imported motions can play.\n\n"
        "Water_20 GenerateObject IDs : 10 / 11 / 11\n"
        "Captured Water identity     : %s / %s / %s\n"
        "Exact Water Always template : %s (matches=%u)\n"
        "Always custom/misc          : 0x%08lX / 0x%02X\n"
        "Stalac runtime import        : %s\n"
        "Stalac Bast runtime IDs      : %ld / %ld / %ld\n"
        "Stalac runtime template      : %p\n"
        "Patched GenerateObject refs  : %u\n\n",
        chg0.superObject,
        chg1.superObject,
        livePairFound
        ? "already-live Bast_20 actors"
        : "native Always allocations",
        g_R2RLiveAICurrentComportIndex,
        g_R2RGenerateObjectTemplateCapture.familyName[0] != '\0'
        ? g_R2RGenerateObjectTemplateCapture.familyName
        : "(uncaptured family)",
        g_R2RGenerateObjectTemplateCapture.modelName[0] != '\0'
        ? g_R2RGenerateObjectTemplateCapture.modelName
        : "(uncaptured model)",
        g_R2RGenerateObjectTemplateCapture.personalName[0] != '\0'
        ? g_R2RGenerateObjectTemplateCapture.personalName
        : "(uncaptured personal)",
        g_R2RGenerateObjectTemplateCapture.exactAlwaysFound ? "YES" : "NO",
        g_R2RGenerateObjectTemplateCapture.exactAlwaysMatchCount,
        g_R2RGenerateObjectTemplateCapture.exactCustomBits,
        g_R2RGenerateObjectTemplateCapture.exactMiscFlags,
        g_R2RStalacShootImportPrepared ? "READY" : "NOT READY",
        g_R2RStalacShootFamilyType,
        g_R2RStalacShootModelType,
        g_R2RStalacShootPersonalType,
        g_R2RStalacShootRuntimeTemplate,
        g_R2RStalacShootPatchedNodeCount
    );

    fflush(g_R2RAITraceFile);

    // h.7.76: establish the exact Bast_20 Actor population BEFORE the
    // attack is allowed to run. The two CHG helper actors are already present
    // at this point, so they will not be misreported as projectiles.
    R2R_ProjectileAuditTakeBaseline(
        g_R2RAITraceFile
    );

    R2R_ReportCurrentCloneDsgHelpers(
        g_R2RAITraceFile,
        "BASELINE BEFORE FRAME 1"
    );

    fflush(g_R2RAITraceFile);

    // Save the spawned SuperObject transform so the report can tell us
    // whether real mechanics moved/rotated Aglagl during the combined frame.
    g_R2RCombinedMatrixBeforeValid = false;

    if (
        g_SpawnedHybrid->p_stGlobalMatrix != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                g_SpawnedHybrid->p_stGlobalMatrix
                ),
            sizeof(POS_tdstCompletePosition)
        )
        )
    {
        g_R2RCombinedMatrixBefore =
            *g_SpawnedHybrid->p_stGlobalMatrix;

        g_R2RCombinedMatrixBeforeValid =
            true;
    }

    GAM_tdstStandardGame* stdGame =
        g_SpawnedHybridActor->hStandardGame;

    g_R2RAnimFrameBeforeValid = false;
    g_R2RAnimFrameBefore = 0;

    if (
        g_SpawnedHybridActor->h3dData != nullptr
        )
    {
        g_R2RAnimFrameBefore =
            g_SpawnedHybridActor->h3dData->uwCurrentFrame;

        g_R2RAnimFrameBeforeValid =
            true;
    }

    // h.7.72: ALL THREE systems ON.
    // Only Water General 302 uses its real imported animation descriptor.
    // Water 301/303/305 deliberately reuse the known-good idle descriptor.
    stdGame->ulCustomBits &=
        ~(
            Std_C_CustBit_NoAI |
            Std_C_CustBit_NoMechanic |
            Std_C_CustBit_NoAnimPlayer
            );

    g_R2RAITraceSequence = 0;
    g_R2RAITraceDepth = 0;
    g_R2RAITraceActive = true;

    g_R2RAIMultiFramesCompleted = 0;
    g_R2ROneAIFrameReturned = false;
    g_R2ROneAIFrameArmed = true;

    g_R2RStalacShootGenerateReturnedThisFrame = false;
    g_R2RStalacShootBirthProbeCompleted = false;
    g_R2RStalacShootBornSO = nullptr;
    g_R2RStalacShootBornActor = nullptr;
    g_R2RStalacShootOriginal3DBeforeBorrow = nullptr;
    g_R2RStalacShootBorrowedSafe3D = nullptr;
    g_R2RStalacShootOneFrameSurvivalPending = false;
    g_R2RStalacShootBirthFrame = -1;

    fprintf(
        g_R2RAITraceFile,
        "================ GENERAL-302 PLAYBACK FRAME 1 / 180 BEGIN ================\n"
        "Animation frame BEFORE: %u\n",
        static_cast<unsigned int>(
            g_R2RAnimFrameBefore
            )
    );
    fflush(g_R2RAITraceFile);

    return true;
}





static void R2R_CloseOneRealAglaglAIFrameAfterEngine()
{
    if (!g_R2ROneAIFrameArmed)
    {
        return;
    }

    g_R2RAIMultiFramesCompleted++;

    // h.7.89: capture the real projectile, quarantine it, and allow exactly
    // one complete engine frame before killing it.
    if (
        g_R2RStalacShootGenerateReturnedThisFrame &&
        !g_R2RStalacShootBirthProbeCompleted
        )
    {
        g_R2RStalacShootBirthProbeCompleted = true;

        const bool birthCaptured =
            R2R_CaptureAndQuarantineBornStalacShoot(
                g_R2RAITraceFile
            );

        if (
            g_SpawnedHybridActor != nullptr &&
            g_SpawnedHybridActor->hStandardGame != nullptr
            )
        {
            g_SpawnedHybridActor->hStandardGame->ulCustomBits |=
                (
                    Std_C_CustBit_NoAI |
                    Std_C_CustBit_NoMechanic
                    );
        }

        g_R2RStalacShootGenerateReturnedThisFrame = false;
        g_R2RStalacShootOneFrameSurvivalPending = birthCaptured;
        g_R2RStalacShootBirthFrame = g_R2RAIMultiFramesCompleted;

        if (g_R2RAITraceFile != nullptr)
        {
            fprintf(
                g_R2RAITraceFile,
                "\n============================================================\n"
                "H.7.89 PROJECTILE CAPTURED - ONE ENGINE FRAME WILL RUN\n"
                "Frame that contained GenerateObject : %d\n"
                "Generated Actor captured            : %s\n"
                "Projectile is fully quarantined     : YES\n"
                "Next engine frame will be attempted : %s\n"
                "============================================================\n",
                g_R2RAIMultiFramesCompleted,
                birthCaptured ? "YES" : "NO",
                birthCaptured ? "YES" : "NO"
            );
            if (birthCaptured)
            {
                fprintf(
                    g_R2RAITraceFile,
                    "\n================ ONE-FRAME PROJECTILE SURVIVAL TEST BEGIN ================\n"
                );
            }
            fflush(g_R2RAITraceFile);
        }

        if (!birthCaptured)
        {
            g_R2RAITraceActive = false;
            g_R2ROneAIFrameReturned = true;
            g_R2ROneAIFrameArmed = false;
            g_OneFrameIsolationPending = false;
            g_OneFrameIsolationMode = R2R_ISO_NONE;
            g_IsolationFramesRemaining = 0;

            if (g_R2RAITraceFile != nullptr)
            {
                R2R_FinalizeStalacShootImport(g_R2RAITraceFile);
                fclose(g_R2RAITraceFile);
                g_R2RAITraceFile = nullptr;
            }

            R2R_WriteOneAIFrameReport(
                "GENERATEOBJECT RETURNED BUT PROJECTILE BIRTH WAS NOT FOUND"
            );
        }

        return;
    }

    if (
        g_R2RStalacShootOneFrameSurvivalPending &&
        g_R2RStalacShootBirthProbeCompleted &&
        g_R2RAIMultiFramesCompleted > g_R2RStalacShootBirthFrame
        )
    {
        if (g_R2RAITraceFile != nullptr)
        {
            fprintf(
                g_R2RAITraceFile,
                "\n================ ONE-FRAME PROJECTILE SURVIVAL TEST RETURNED ================\n"
                "The engine frame AFTER projectile birth returned safely.\n"
            );
            fflush(g_R2RAITraceFile);
        }

        const bool killed =
            R2R_KillCapturedStalacShoot(g_R2RAITraceFile);

        g_R2RStalacShootOneFrameSurvivalPending = false;
        g_R2RAITraceActive = false;
        g_R2ROneAIFrameReturned = true;
        g_R2ROneAIFrameArmed = false;
        g_OneFrameIsolationPending = false;
        g_OneFrameIsolationMode = R2R_ISO_NONE;
        g_IsolationFramesRemaining = 0;

        if (g_R2RAITraceFile != nullptr)
        {
            fprintf(
                g_R2RAITraceFile,
                "\n============================================================\n"
                "H.8.03 FULL-PRIVATE-TABLE PROJECTILE PROBE COMPLETE\n"
                "Birth frame                         : %d\n"
                "Survival frame                      : %d\n"
                "Projectile survived next frame      : YES\n"
                "Projectile cleanup                  : %s\n"
                "============================================================\n",
                g_R2RStalacShootBirthFrame,
                g_R2RAIMultiFramesCompleted,
                killed ? "YES" : "NO"
            );

            R2R_FinalizeStalacShootImport(g_R2RAITraceFile);
            fflush(g_R2RAITraceFile);
            fclose(g_R2RAITraceFile);
            g_R2RAITraceFile = nullptr;
        }

        // h.7.97: h.7.96 cleaned everything immediately in this same post-
        // engine callback.  That was too early: Rayman 2 could still hold
        // transient references to the Aglagl/merged animation data and crash
        // right after the user saw Aglagl + the safe Piranha shell.
        // Leave the already-proven stable runtime alone for a short grace
        // period, then clean it from a later normal engine frame.
        g_R2RPostProbeCleanupPending = true;
        g_R2RPostProbeCleanupFrames = 0;

        FILE* cleanupDone = nullptr;
        fopen_s(&cleanupDone, TRANSITION_CLEANUP_REPORT, "w");
        if (cleanupDone != nullptr)
        {
            fprintf(
                cleanupDone,
                "RAYMAN 2 RANDOMIZER\n"
                "v0.0.14b.0 - DEFERRED POST-PROBE CLEANUP\n"
                "============================================================\n"
                "Projectile survived and was killed safely.\n"
                "Aglagl/helpers/merged bank cleanup deferred for %u normal engine frames.\n"
                "Merged bank memory will NOT be freed when globals are restored.\n",
                R2R_POST_PROBE_CLEANUP_DELAY_FRAMES
            );
            fclose(cleanupDone);
        }

        R2R_WriteOneAIFrameReport(
            "STALAC SHOOT FULL-PRIVATE-TABLE INSTANCE SURVIVED ONE FULL ENGINE FRAME; DEFERRED SAFE CLEANUP ARMED"
        );

        return;
    }

    // h.7.76 read-only dependency detector. If Aglagl's AI created a
    // projectile/helper Actor during the just-finished frame, this records
    // its exact Family / Model / Personal identity and runtime state.
    R2R_ProjectileAuditScanForNewActors(
        g_R2RAITraceFile
    );

    // h.7.79: keep the dependency trace readable while still covering the
    // complete attack window.  Snapshot every early frame, then every 5th
    // frame, plus the late attack region where h.7.78 saw activity.
    if (
        g_R2RAIMultiFramesCompleted <= 10 ||
        (g_R2RAIMultiFramesCompleted % 5) == 0 ||
        g_R2RAIMultiFramesCompleted >= 100
        )
    {
        char helperPhase[96] = {};
        sprintf_s(
            helperPhase,
            "AFTER FULL PIPELINE FRAME %d",
            g_R2RAIMultiFramesCompleted
        );

        R2R_ReportCurrentCloneDsgHelpers(
            g_R2RAITraceFile,
            helperPhase
        );
    }

    bool matrixReadable = false;
    bool matrixChanged = false;
    bool rotationChanged = false;
    POS_tdstCompletePosition matrixAfter = {};

    if (
        g_SpawnedHybrid != nullptr &&
        g_SpawnedHybrid->p_stGlobalMatrix != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                g_SpawnedHybrid->p_stGlobalMatrix
                ),
            sizeof(POS_tdstCompletePosition)
        )
        )
    {
        matrixAfter =
            *g_SpawnedHybrid->p_stGlobalMatrix;

        matrixReadable = true;

        if (g_R2RCombinedMatrixBeforeValid)
        {
            matrixChanged =
                std::memcmp(
                    &g_R2RCombinedMatrixBefore,
                    &matrixAfter,
                    sizeof(POS_tdstCompletePosition)
                ) != 0;

            rotationChanged =
                std::memcmp(
                    &g_R2RCombinedMatrixBefore.stRotationMatrix,
                    &matrixAfter.stRotationMatrix,
                    sizeof(MTH3D_tdstMatrix)
                ) != 0;
        }
    }

    int currentComportAfter = -1;
    int previousComportAfter = -1;

    if (
        g_SpawnedHybridActor != nullptr &&
        g_SpawnedHybridActor->hBrain != nullptr &&
        g_SpawnedHybridActor->hBrain->p_stMind != nullptr
        )
    {
        AI_tdstMind* mind =
            g_SpawnedHybridActor->hBrain->p_stMind;

        AI_tdstIntelligence* active =
            R2R_GetActiveIntelligence(
                mind
            );

        AI_tdstScriptAI* script =
            R2R_GetScriptAIFromIntelligence(
                active
            );

        if (
            active != nullptr &&
            script != nullptr
            )
        {
            currentComportAfter =
                R2R_GetComportIndex(
                    script,
                    active->p_stCurrentComport
                );

            previousComportAfter =
                R2R_GetComportIndex(
                    script,
                    active->p_stPrevComport
                );
        }
    }

    unsigned short animFrameAfter = 0;
    bool animFrameAfterValid = false;

    HIE_tdstState* initialAfter = nullptr;
    HIE_tdstState* currentAfter = nullptr;
    HIE_tdstState* firstAfter = nullptr;
    HIE_tdstState* wantedAfter = nullptr;
    HIE_tdstState* lastAfter = nullptr;

    unsigned long customBitsAfter = 0;

    if (
        g_SpawnedHybridActor != nullptr &&
        g_SpawnedHybridActor->h3dData != nullptr
        )
    {
        GAM_tdst3dData* data =
            g_SpawnedHybridActor->h3dData;

        animFrameAfter =
            data->uwCurrentFrame;

        animFrameAfterValid =
            true;

        initialAfter =
            data->h_InitialState;

        currentAfter =
            data->h_CurrentState;

        firstAfter =
            data->h_FirstStateOfAction;

        wantedAfter =
            data->h_WantedState;

        lastAfter =
            data->h_StateInLastFrame;
    }

    if (
        g_SpawnedHybridActor != nullptr &&
        g_SpawnedHybridActor->hStandardGame != nullptr
        )
    {
        customBitsAfter =
            g_SpawnedHybridActor->hStandardGame->ulCustomBits;
    }

    const bool guardedStatesStillSafe =
        R2R_IsAllowedAglaglRealActionState(
            initialAfter,
            g_R2RSafeInitialStateBeforeAI
        ) &&
        R2R_IsAllowedAglaglRealActionState(
            currentAfter,
            g_R2RSafeCurrentStateBeforeAI
        ) &&
        R2R_IsAllowedAglaglRealActionState(
            firstAfter,
            g_R2RSafeFirstStateBeforeAI
        ) &&
        R2R_IsAllowedAglaglRealActionState(
            wantedAfter,
            g_R2RSafeWantedStateBeforeAI
        );

    if (g_R2RAITraceFile != nullptr)
    {
        fprintf(
            g_R2RAITraceFile,
            "\n================ FULL PIPELINE FRAME %d / %d RETURNED ================\n"
            "Evaluator calls total    : %lu\n"
            "Current Comport          : %d\n"
            "Previous Comport         : %d\n"
            "Animation frame BEFORE   : %u\n"
            "Animation frame AFTER    : %u\n"
            "Animation frame changed  : %s\n"
            "Initial State            : %p  changed=%s\n"
            "Current State            : %p  changed=%s\n"
            "First State              : %p  changed=%s\n"
            "Wanted State             : %p  changed=%s\n"
            "Last State               : %p\n"
            "Guarded states allowed   : %s\n"
            "Custom bits after        : 0x%08lX\n"
            "NoAnimPlayer after       : %s\n"
            "Matrix readable          : %s\n"
            "Whole matrix changed     : %s\n"
            "Rotation changed         : %s\n",
            g_R2RAIMultiFramesCompleted,
            R2R_AI_MULTI_FRAME_TARGET,
            g_R2RAITraceSequence,
            currentComportAfter,
            previousComportAfter,
            static_cast<unsigned int>(
                g_R2RAnimFrameBefore
                ),
            static_cast<unsigned int>(
                animFrameAfter
                ),
            (
                g_R2RAnimFrameBeforeValid &&
                animFrameAfterValid &&
                g_R2RAnimFrameBefore !=
                animFrameAfter
                )
            ? "YES"
            : "NO",
            initialAfter,
            initialAfter !=
            g_R2RSafeInitialStateBeforeAI
            ? "YES"
            : "NO",
            currentAfter,
            currentAfter !=
            g_R2RSafeCurrentStateBeforeAI
            ? "YES"
            : "NO",
            firstAfter,
            firstAfter !=
            g_R2RSafeFirstStateBeforeAI
            ? "YES"
            : "NO",
            wantedAfter,
            wantedAfter !=
            g_R2RSafeWantedStateBeforeAI
            ? "YES"
            : "NO",
            lastAfter,
            guardedStatesStillSafe
            ? "YES"
            : "NO",
            customBitsAfter,
            (
                customBitsAfter &
                Std_C_CustBit_NoAnimPlayer
                )
            ? "YES"
            : "NO",
            matrixReadable ? "YES" : "NO",
            matrixChanged ? "YES" : "NO",
            rotationChanged ? "YES" : "NO"
        );

        if (
            matrixReadable &&
            g_R2RCombinedMatrixBeforeValid
            )
        {
            fprintf(
                g_R2RAITraceFile,
                "Position BEFORE        : %.6f %.6f %.6f\n"
                "Position AFTER         : %.6f %.6f %.6f\n",
                g_R2RCombinedMatrixBefore.stPos.x,
                g_R2RCombinedMatrixBefore.stPos.y,
                g_R2RCombinedMatrixBefore.stPos.z,
                matrixAfter.stPos.x,
                matrixAfter.stPos.y,
                matrixAfter.stPos.z
            );
        }

        if (
            currentAfter != nullptr &&
            currentAfter !=
            g_R2RLastRealActionStateLogged
            )
        {
            fprintf(
                g_R2RAITraceFile,
                "\n>>> GENERAL-302+303 PLAYBACK STATE TRANSITION <<<\n"
            );

            ReportStateDetails(
                g_R2RAITraceFile,
                "TRANSITION CURRENT STATE",
                currentAfter
            );

            fprintf(
                g_R2RAITraceFile,
                ">>> END GENERAL-302+303 PLAYBACK STATE TRANSITION <<<\n"
            );

            g_R2RLastRealActionStateLogged =
                currentAfter;
        }

        fflush(g_R2RAITraceFile);
    }

    // Known donor Action states are allowed to run. In h.7.74 ONLY General 302
    // is real; 301/303/305 point to the proven-safe idle descriptor.
    if (!guardedStatesStillSafe)
    {
        if (
            g_SpawnedHybridActor != nullptr &&
            g_SpawnedHybridActor->hStandardGame != nullptr
            )
        {
            g_SpawnedHybridActor->hStandardGame->ulCustomBits |=
                (
                    Std_C_CustBit_NoAI |
                    Std_C_CustBit_NoMechanic
                    );
        }

        if (
            g_SpawnedHybridActor != nullptr &&
            g_SpawnedHybridActor->h3dData != nullptr
            )
        {
            GAM_tdst3dData* data =
                g_SpawnedHybridActor->h3dData;

            data->h_InitialState =
                g_R2RSafeInitialStateBeforeAI;
            data->h_CurrentState =
                g_R2RSafeCurrentStateBeforeAI;
            data->h_FirstStateOfAction =
                g_R2RSafeFirstStateBeforeAI;
            data->h_WantedState =
                g_R2RSafeWantedStateBeforeAI;
            data->h_StateInLastFrame =
                g_R2RSafeLastStateBeforeAI;
        }

        g_R2RAITraceActive = false;
        g_R2ROneAIFrameReturned = true;
        g_R2ROneAIFrameArmed = false;

        if (g_R2RAITraceFile != nullptr)
        {
            fprintf(
                g_R2RAITraceFile,
                "\n============================================================\n"
                "UNKNOWN STATE OUTSIDE GENERAL-302+303 CONTROL SET\n"
                "============================================================\n"
                "The engine frame returned safely, but this state is outside the\n"
                "controlled 302 + safe-substitute action set. The guard is stopping NOW.\n\n"
            );

            ReportStateDetails(
                g_R2RAITraceFile,
                "NEW CURRENT STATE",
                currentAfter
            );

            ReportStateDetails(
                g_R2RAITraceFile,
                "NEW WANTED STATE",
                wantedAfter
            );

            fprintf(
                g_R2RAITraceFile,
                "\nGUARD STOPPED THE TEST SAFELY.\n"
                "Unknown state was not allowed to run another frame.\n"
                "Known-safe state pointers were restored.\n"
            );

            R2R_FinalizeStalacShootImport(
                g_R2RAITraceFile
            );

            fflush(g_R2RAITraceFile);
            fclose(g_R2RAITraceFile);
            g_R2RAITraceFile = nullptr;
        }

        R2R_WriteOneAIFrameReport(
            "GENERAL-302+303 PLAYBACK GUARD STOPPED ON AN UNKNOWN STATE"
        );

        return;
    }

    if (
        g_R2RAIMultiFramesCompleted <
        R2R_AI_MULTI_FRAME_TARGET
        )
    {
        // Preserve the real animation/player progression. Do NOT restore the
        // state or current animation frame while it remains inside the
        // known imported Aglagl action-state set.
        if (matrixReadable)
        {
            g_R2RCombinedMatrixBefore =
                matrixAfter;

            g_R2RCombinedMatrixBeforeValid =
                true;
        }

        if (animFrameAfterValid)
        {
            g_R2RAnimFrameBefore =
                animFrameAfter;

            g_R2RAnimFrameBeforeValid =
                true;
        }

        if (
            g_SpawnedHybridActor != nullptr &&
            g_SpawnedHybridActor->hStandardGame != nullptr
            )
        {
            GAM_tdstStandardGame* stdGame =
                g_SpawnedHybridActor->hStandardGame;

            // Make sure all three subsystems are enabled for the next guarded
            // full pipeline frame.
            stdGame->ulCustomBits &=
                ~(
                    Std_C_CustBit_NoAI |
                    Std_C_CustBit_NoMechanic |
                    Std_C_CustBit_NoAnimPlayer
                    );
        }

        if (g_R2RAITraceFile != nullptr)
        {
            fprintf(
                g_R2RAITraceFile,
                "\n================ FULL PIPELINE FRAME %d / %d BEGIN ================\n",
                g_R2RAIMultiFramesCompleted + 1,
                R2R_AI_MULTI_FRAME_TARGET
            );
            fflush(g_R2RAITraceFile);
        }

        g_R2RAITraceActive = true;
        return;
    }

    // All 180 guarded real-action frames returned without an unknown state.
    if (
        g_SpawnedHybridActor != nullptr &&
        g_SpawnedHybridActor->hStandardGame != nullptr
        )
    {
        GAM_tdstStandardGame* stdGame =
            g_SpawnedHybridActor->hStandardGame;

        // Quarantine gameplay systems after the test, but leave the normal
        // animation player enabled so the final safe state can keep rendering.
        stdGame->ulCustomBits |=
            (
                Std_C_CustBit_NoAI |
                Std_C_CustBit_NoMechanic
                );

        stdGame->ulCustomBits &=
            ~Std_C_CustBit_NoAnimPlayer;
    }

    g_R2RAITraceActive = false;
    g_R2ROneAIFrameReturned = true;
    g_R2ROneAIFrameArmed = false;

    if (g_R2RAITraceFile != nullptr)
    {
        R2R_ProjectileAuditWriteTrackingSummary(
            g_R2RAITraceFile
        );

        R2R_FinalizeStalacShootImport(
            g_R2RAITraceFile
        );

        fprintf(
            g_R2RAITraceFile,
            "\n============================================================\n"
            "ALL %d GUARDED GENERAL-302+303 PLAYBACK FRAMES RETURNED SAFELY\n"
            "Total evaluator calls: %lu\n"
            "New world SuperObjects detected: %u\n"
            "Only the safe idle and controlled donor Action states were selected.\n"
            "Animation-player progression was NOT reset between frames.\n"
            "============================================================\n",
            R2R_AI_MULTI_FRAME_TARGET,
            g_R2RAITraceSequence,
            g_R2RProjectileAuditNewCount
        );

        fflush(g_R2RAITraceFile);
        fclose(g_R2RAITraceFile);
        g_R2RAITraceFile = nullptr;
    }

    R2R_WriteOneAIFrameReport(
        "GENERAL-302+303 PLAYBACK TEST COMPLETED"
    );
}


bool EnableAnimationOnlyForAglaglTest()
{
    if (
        g_SpawnedHybridActor == nullptr ||
        g_SpawnedHybridActor->hStandardGame == nullptr
        )
    {
        return false;
    }

    GAM_tdstStandardGame* stdGame =
        g_SpawnedHybridActor->hStandardGame;

    // SpawnHybridShell starts in a very strong "do nothing" safety mode.
    // h.7.14 now turns ONLY the animation/display side back on.
    // AI and mechanics stay disabled, so the boss cannot start behaving
    // like the real Water_20 boss yet.
    stdGame->ulCustomBits &=
        ~(
            Std_C_CustBit_NoAnimPlayer |
            Std_C_CustBit_UnseenFrozenAnimPlayer |
            Std_C_CustBit_UnseenFrozen |
            Std_C_CustBit_OutOfVisibility
            );

    stdGame->ulCustomBits |=
        (
            Std_C_CustBit_NoAI |
            Std_C_CustBit_NoMechanic
            );

    stdGame->ucMiscFlags &=
        ~(
            Std_C_MiscFlag_DesactivateAtAll |
            Std_C_MiscFlag_TooFar
            );

    stdGame->ucMiscFlags |=
        (
            Std_C_MiscFlag_Active |
            Std_C_MiscFlag_Always |
            Std_C_MiscFlag_AlwaysActive
            );

    FILE* report = nullptr;
    fopen_s(&report, ISOLATION_REPORT_FILE, "a");

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nANIMATION-ONLY ACTIVATION\n"
            "------------------------------------------------------------\n"
            "AI disabled        : YES\n"
            "Mechanics disabled : YES\n"
            "Animation enabled  : YES\n"
            "Visible allowed    : YES\n"
            "Custom bits        : 0x%08X\n"
            "Misc flags         : 0x%02X\n\n",
            static_cast<unsigned int>(stdGame->ulCustomBits),
            static_cast<unsigned int>(stdGame->ucMiscFlags)
        );
        fflush(report);
        fclose(report);
    }

    return true;
}


void Run3DIsolationVariant(
    int mode,
    bool allowPreparation
)
{
    R2R_F6CrashPoint("ENTER Run3DIsolationVariant");

    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(
            GAM_g_stEngineStructure->szLevelName,
            "Bast_20"
        ) != 0
        )
    {
        return;
    }

    if (g_HybridProbeDone || g_OneFrameIsolationPending)
    {
        MessageBoxA(
            nullptr,
            "A 3D isolation test has already run in this process.\n\nRestart Rayman 2 before another diagnostic test.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    if (allowPreparation)
    {
        bool preparationStageCompleted = false;

        if (!EnsureForeign3DHybridPrepared(preparationStageCompleted))
        {
            if (preparationStageCompleted)
            {
                const char* stageMessage =
                    g_F6PreparationStage == 1
                    ? "F6 PREPARATION STAGE 1 COMPLETE!\n\nThe arena/ObjectType/remap stage is ready.\n\nClose this box, wait until Rayman is fully responsive again, then press F6 a SECOND time.\n\nThe second press will ONLY register the runtime garde_tfeu Family."
                    : "F6 PREPARATION STAGE 2 COMPLETE!\n\nPreparation is finished.\n\nMAIN TEST:\n\nF6 = E1: native Animation descriptor + ONLY Aglagl A3dGENERAL ID\n\nControls kept for reference:\nF7 = E2 inverse: foreign descriptor + native A3dGENERAL ID\nF8 = old D1 control (known freeze)\n\nRun only ONE test per game process.";

                MessageBoxA(
                    nullptr,
                    stageMessage,
                    "Rayman 2 Randomizer v0.0.14b.0",
                    MB_OK | MB_ICONINFORMATION
                );
            }
            else
            {
                MessageBoxA(
                    nullptr,
                    "3D isolation preparation failed.\n\nRestart Rayman 2, go directly to Bast_20, then use F6 from a fresh process.",
                    "Rayman 2 Randomizer v0.0.14b.0",
                    MB_OK | MB_ICONWARNING
                );
            }

            return;
        }
    }
    else
    {
        if (
            !g_AglaglPrepared ||
            !g_RuntimeAglaglFamilyRegistered ||
            g_RuntimeAglaglFamily == nullptr ||
            g_CrossLevelArena == nullptr
            )
        {
            MessageBoxA(
                nullptr,
                "Preparation is not finished yet.\n\nFrom a fresh process:\n1. F2 to Bast_20\n2. F6 once (Stage 1)\n3. F6 again (Stage 2)\n4. THEN press F6 for E1 (or F7 for E2 after preparation).",
                "Rayman 2 Randomizer v0.0.14b.0",
                MB_OK | MB_ICONWARNING
            );
            return;
        }
    }

    HIE_tdstSuperObject* nativeSuper = nullptr;
    HIE_tdstEngineObject* nativeActor = nullptr;
    const char* nativeModel = nullptr;

    R2R_F6CrashPoint("BEFORE FindBast20ControlSource");
    if (
        !FindBast20ControlSource(
            nativeSuper,
            nativeActor,
            nativeModel
        ) ||
        nativeActor == nullptr ||
        nativeActor->h3dData == nullptr
        )
    {
        MessageBoxA(
            nullptr,
            "Could not find the native Bast_20 control actor.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONERROR
        );
        return;
    }

    R2R_F6CrashPoint("AFTER FindBast20ControlSource = OK");
    g_HybridProbeDone = true;
    g_R2RChannelAuditWritten = false;

    R2R_F6CrashPoint("BEFORE opening 3D isolation report");
    FILE* report = nullptr;
    fopen_s(&report, ISOLATION_REPORT_FILE, "w");

    if (report == nullptr)
    {
        return;
    }

    R2R_F6CrashPoint("3D isolation report OPENED");
    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - BLUE AGLAGL AI EXECUTION-MODE SYNC\n"
        "============================================================\n\n"
        "Current Level      : Bast_20\n"
        "Test               : %s\n"
        "Foreign Family     : garde_tfeu / %p\n"
        "Native control     : %s / %p\n"
        "Alias ModelType    : %ld\n\n",
        IsolationModeName(mode),
        g_RuntimeAglaglFamily,
        nativeModel != nullptr ? nativeModel : "(unknown)",
        nativeActor,
        g_AglaglModelType
    );
    fflush(report);

    R2R_F6CrashPoint("BEFORE BuildRuntimeAglaglTemplate");
    g_HybridTemplate =
        BuildRuntimeAglaglTemplate();
    R2R_F6CrashPoint("AFTER BuildRuntimeAglaglTemplate");

    if (
        g_HybridTemplate == nullptr ||
        g_HybridTemplate->hStandardGame == nullptr ||
        g_HybridTemplate->h3dData == nullptr
        )
    {
        fprintf(report, "TEMPLATE BUILD FAILED.\n");
        fflush(report);
        fclose(report);
        return;
    }

    R2R_F6CrashPoint("BEFORE AI_fn_vBrainCopyClone for Aglagl shell");
    fprintf(report, "STEP 1: COPYING NATIVE BRAIN...\n");
    fflush(report);
    AI_fn_vBrainCopyClone(
        g_HybridTemplate,
        nativeActor
    );
    fprintf(report, "STEP 1 RETURNED.\n");
    fflush(report);
    R2R_F6CrashPoint("AFTER AI_fn_vBrainCopyClone for Aglagl shell");

    R2R_F6CrashPoint("BEFORE DNM_fn_vDynamCopyClone for Aglagl shell");
    fprintf(report, "STEP 2: COPYING NATIVE DYNAMICS...\n");
    fflush(report);
    DNM_fn_vDynamCopyClone(
        g_HybridTemplate,
        nativeActor
    );
    fprintf(report, "STEP 2 RETURNED.\n");
    fflush(report);
    R2R_F6CrashPoint("AFTER DNM_fn_vDynamCopyClone for Aglagl shell");

    R2R_F6CrashPoint("BEFORE Apply3DIsolationMode on template");
    const bool templatePatched =
        Apply3DIsolationMode(
            g_HybridTemplate,
            nativeActor,
            mode
        );
    R2R_F6CrashPoint(templatePatched ? "AFTER Apply3DIsolationMode template = OK" : "AFTER Apply3DIsolationMode template = FAILED");

    g_HybridTemplate->hStandardGame->lObjectFamilyType =
        g_AglaglFamilyType;
    g_HybridTemplate->hStandardGame->lObjectModelType =
        g_AglaglModelType;
    g_HybridTemplate->hStandardGame->lObjectPersonalType =
        g_AglaglPersonalType;

    fprintf(
        report,
        "\nTEMPLATE PATCH\n"
        "------------------------------------------------------------\n"
        "Applied       : %s\n"
        "Family        : %p\n"
        "InitialState  : %p\n"
        "CurrentState  : %p\n"
        "InitialTable  : %p\n"
        "CurrentTable  : %p\n\n",
        templatePatched ? "YES" : "NO",
        g_HybridTemplate->h3dData->h_Family,
        g_HybridTemplate->h3dData->h_InitialState,
        g_HybridTemplate->h3dData->h_CurrentState,
        g_HybridTemplate->h3dData->h_InitialObjectsTable,
        g_HybridTemplate->h3dData->h_CurrentObjectsTable
    );
    fflush(report);
    fclose(report);

    if (!templatePatched)
    {
        MessageBoxA(
            nullptr,
            "The isolation template could not be patched.\n\nSend Rayman2Randomizer_3DIsolation.txt.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    R2R_F6CrashPoint("BEFORE SpawnHybridShell");
    const bool spawned =
        SpawnHybridShell(
            g_HybridTemplate,
            ISOLATION_REPORT_FILE,
            IsolationModeName(mode)
        );
    R2R_F6CrashPoint(spawned ? "AFTER SpawnHybridShell = OK" : "AFTER SpawnHybridShell = FAILED");

    if (!spawned)
    {
        MessageBoxA(
            nullptr,
            "The isolation spawn did not complete.\n\nSend Rayman2Randomizer_3DIsolation.txt.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    // ALW is allowed to initialize/normalize its fresh 3D shell. Re-apply
    // the chosen D1/B2/C1 ownership immediately AFTER allocation so the
    // next normal engine frame receives exactly the combination we want.
    R2R_F6CrashPoint("BEFORE Apply3DIsolationMode on spawned Aglagl");
    const bool spawnedPatched =
        Apply3DIsolationMode(
            g_SpawnedHybridActor,
            nativeActor,
            mode
        );
    R2R_F6CrashPoint(spawnedPatched ? "AFTER Apply3DIsolationMode spawned = OK" : "AFTER Apply3DIsolationMode spawned = FAILED");

    AppendIsolation3DSnapshot(
        "AFTER SPAWN + FINAL ANIMATION SETUP",
        mode,
        nativeActor
    );

    FILE* armReport = nullptr;
    fopen_s(&armReport, ISOLATION_REPORT_FILE, "a");

    if (armReport != nullptr)
    {
        fprintf(
            armReport,
            "\n============================================================\n"
            "MULTI-FRAME PROBE ARMED\n"
            "============================================================\n\n"
            "Spawned patch applied : %s\n"
            "Target frames         : %d\n"
            "The object will stay alive while Rayman 2 runs these frames.\n"
            "If all frames return normally, the object will be removed.\n\n",
            spawnedPatched ? "YES" : "NO",
            R2R_LONG_VISUAL_TEST_FRAMES
        );
        fflush(armReport);
        fclose(armReport);
    }

    if (!spawnedPatched)
    {
        DestroyHybridSafely();
        return;
    }

    // h.7.26: h.7.25 changed only the spawned 3D object's current table.
    // Make the runtime Family's default table match it too, BEFORE the
    // animation player receives its first normal frame.
    if (
        mode == R2R_ISO_F1_MERGED_AGLAGL_ANIMATION &&
        !R2R_SwapRuntimeFamilyDefaultToNativeTable()
        )
    {
        DestroyHybridSafely();

        MessageBoxA(
            nullptr,
            "Could not make the runtime Family use the native Bast visual table.\n\nRestart Rayman 2 and try again.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    // h.7.14: previous tests kept the object fully quarantined.
    // Now enable only its animation/display while AI + mechanics remain off.
    R2R_F6CrashPoint("BEFORE EnableAnimationOnlyForAglaglTest");
    const bool animationEnabledForAglagl = EnableAnimationOnlyForAglaglTest();
    R2R_F6CrashPoint(animationEnabledForAglagl ? "AFTER EnableAnimationOnlyForAglaglTest = OK" : "AFTER EnableAnimationOnlyForAglaglTest = FAILED");
    if (!animationEnabledForAglagl)
    {
        DestroyHybridSafely();

        MessageBoxA(
            nullptr,
            "Could not enable the animation-only test.\n\nRestart Rayman 2 and try again.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    // h.7.91: isolate the projectile from Aglagl's attack entirely.
    // Allocate STN_Stalac_shoot manually, quarantine it, and let exactly one
    // normal engine frame run.  If this crashes, the projectile/runtime data
    // itself is the culprit.  If it survives, the crash depends on Aglagl's
    // attack-side state changes rather than the projectile alone.
    if (mode == R2R_ISO_G1_MERGED_ANIMATION_FOREIGN_TABLE)
    {
        R2R_F6CrashPoint("BEFORE R2R_RunStalacShootManualAllocationProbe");
    }

    const bool manualProbeStarted =
        mode != R2R_ISO_G1_MERGED_ANIMATION_FOREIGN_TABLE ||
        R2R_RunStalacShootManualAllocationProbe();

    if (mode == R2R_ISO_G1_MERGED_ANIMATION_FOREIGN_TABLE)
    {
        R2R_F6CrashPoint(manualProbeStarted ? "AFTER manual projectile probe = STARTED" : "AFTER manual projectile probe = FAILED");
    }

    if (
        mode == R2R_ISO_G1_MERGED_ANIMATION_FOREIGN_TABLE &&
        !manualProbeStarted
        )
    {
        DestroyHybridSafely();

        MessageBoxA(
            nullptr,
            "Could not start the manual STN_Stalac_shoot one-frame test.\n\nAglagl's attack was NOT executed.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    g_OneFrameIsolationMode = mode;
    g_OneFrameIsolationPending = true;
    g_IsolationFramesRemaining = R2R_LONG_VISUAL_TEST_FRAMES;
    g_IsolationFramesCompleted = 0;

    // h.7.78:
    // DO NOT auto-spawn the known-visible Piranha control for the projectile
    // dependency test. h.7.76 took its baseline before this control was
    // created, so the scanner incorrectly reported R2R_NATIVE_CONTROL_MODEL
    // as the "projectile".
    //
    // Other isolation modes can still use the control if needed.
    if (
        mode !=
        R2R_ISO_G1_MERGED_ANIMATION_FOREIGN_TABLE &&
        g_SpawnedControl == nullptr &&
        !g_ControlProbeDone
        )
    {
        RunSameMapNormalizedControl();
    }

    MessageBoxA(
        nullptr,
        "STALAC_SHOOT HIDDEN ONE-FRAME TEST ARMED!\n\n"
        "Aglagl will NOT attack in this test.\n\n"
        "The DLL created the projectile directly and will let Rayman 2 process it for exactly one normal engine frame.\n\n"
        "If that frame returns, the projectile will be deleted automatically.\n\n"
        "Then send me:\n"
        "Rayman2Randomizer_StalacShootFullSafe3D.txt",
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | MB_ICONINFORMATION
    );
}

// ============================================================
// h.7.9 - READ-ONLY A3D REGISTRY / CODE-REFERENCE DISCOVERY
// ============================================================

bool R2R_IsReadableProtection(DWORD protect)
{
    if (protect & PAGE_GUARD)
    {
        return false;
    }

    const DWORD baseProtect = protect & 0xFF;

    return
        baseProtect == PAGE_READONLY ||
        baseProtect == PAGE_READWRITE ||
        baseProtect == PAGE_WRITECOPY ||
        baseProtect == PAGE_EXECUTE_READ ||
        baseProtect == PAGE_EXECUTE_READWRITE ||
        baseProtect == PAGE_EXECUTE_WRITECOPY;
}

bool R2R_IsExecutableProtection(DWORD protect)
{
    if (protect & PAGE_GUARD)
    {
        return false;
    }

    const DWORD baseProtect = protect & 0xFF;

    return
        baseProtect == PAGE_EXECUTE ||
        baseProtect == PAGE_EXECUTE_READ ||
        baseProtect == PAGE_EXECUTE_READWRITE ||
        baseProtect == PAGE_EXECUTE_WRITECOPY;
}

bool R2R_AddressReadable(uintptr_t address, size_t size)
{
    if (address < 0x10000 || size == 0)
    {
        return false;
    }

    MEMORY_BASIC_INFORMATION mbi = {};

    if (
        VirtualQuery(
            reinterpret_cast<LPCVOID>(address),
            &mbi,
            sizeof(mbi)
        ) == 0
        )
    {
        return false;
    }

    if (
        mbi.State != MEM_COMMIT ||
        !R2R_IsReadableProtection(mbi.Protect)
        )
    {
        return false;
    }

    const uintptr_t regionStart =
        reinterpret_cast<uintptr_t>(mbi.BaseAddress);

    const uintptr_t regionEnd =
        regionStart + static_cast<uintptr_t>(mbi.RegionSize);

    if (address > regionEnd)
    {
        return false;
    }

    if (size > static_cast<size_t>(regionEnd - address))
    {
        return false;
    }

    return true;
}

bool R2R_AddressExecutable(uintptr_t address)
{
    if (address < 0x10000)
    {
        return false;
    }

    MEMORY_BASIC_INFORMATION mbi = {};

    if (
        VirtualQuery(
            reinterpret_cast<LPCVOID>(address),
            &mbi,
            sizeof(mbi)
        ) == 0
        )
    {
        return false;
    }

    return
        mbi.State == MEM_COMMIT &&
        R2R_IsExecutableProtection(mbi.Protect);
}

bool R2R_GetMainImageRange(
    uintptr_t& imageBase,
    size_t& imageSize
)
{
    imageBase = 0;
    imageSize = 0;

    HMODULE module = GetModuleHandleA(nullptr);

    if (module == nullptr)
    {
        return false;
    }

    const uintptr_t base =
        reinterpret_cast<uintptr_t>(module);

    IMAGE_DOS_HEADER dos = {};

    if (
        !SafeReadMemory(
            reinterpret_cast<const void*>(base),
            &dos,
            sizeof(dos)
        ) ||
        dos.e_magic != IMAGE_DOS_SIGNATURE
        )
    {
        return false;
    }

    IMAGE_NT_HEADERS32 nt = {};

    if (
        !SafeReadMemory(
            reinterpret_cast<const void*>(
                base + static_cast<uintptr_t>(dos.e_lfanew)
                ),
            &nt,
            sizeof(nt)
        ) ||
        nt.Signature != IMAGE_NT_SIGNATURE
        )
    {
        return false;
    }

    imageBase = base;
    imageSize = static_cast<size_t>(nt.OptionalHeader.SizeOfImage);

    return imageSize != 0;
}

bool R2R_IsInsideMainImage(
    uintptr_t address,
    uintptr_t imageBase,
    size_t imageSize
)
{
    if (imageBase == 0 || imageSize == 0)
    {
        return false;
    }

    const uintptr_t imageEnd =
        imageBase + static_cast<uintptr_t>(imageSize);

    return address >= imageBase && address < imageEnd;
}

void R2R_DumpHexWindow(
    FILE* report,
    const uint8_t* bytes,
    size_t size,
    size_t center
)
{
    if (report == nullptr || bytes == nullptr || size == 0)
    {
        return;
    }

    const size_t begin = center > 12 ? center - 12 : 0;
    size_t end = center + 20;

    if (end > size)
    {
        end = size;
    }

    fprintf(report, "    bytes:");

    for (size_t i = begin; i < end; i++)
    {
        if (i == center)
        {
            fprintf(report, " [");
        }
        else
        {
            fprintf(report, " ");
        }

        fprintf(report, "%02X", static_cast<unsigned int>(bytes[i]));

        if (i == center)
        {
            fprintf(report, "]");
        }
    }

    fprintf(report, "\n");
}

void R2R_ReportAbsoluteDataReference(
    FILE* report,
    const char* ownerLabel,
    uintptr_t instructionAddress,
    uintptr_t targetAddress,
    uintptr_t imageBase,
    size_t imageSize
)
{
    if (report == nullptr)
    {
        return;
    }

    if (
        !R2R_IsInsideMainImage(
            targetAddress,
            imageBase,
            imageSize
        ) ||
        !R2R_AddressReadable(targetAddress, 4)
        )
    {
        return;
    }

    uint32_t value32 = 0;
    uint16_t value16 = 0;

    SafeReadMemory(
        reinterpret_cast<const void*>(targetAddress),
        &value32,
        sizeof(value32)
    );

    SafeReadMemory(
        reinterpret_cast<const void*>(targetAddress),
        &value16,
        sizeof(value16)
    );

    const uintptr_t pointerValue =
        static_cast<uintptr_t>(value32);

    MEMORY_BASIC_INFORMATION targetMbi = {};
    VirtualQuery(
        reinterpret_cast<LPCVOID>(targetAddress),
        &targetMbi,
        sizeof(targetMbi)
    );

    fprintf(
        report,
        "  ABSREF owner=%s ins=%p target=%p value32=0x%08X value16=%u protect=0x%08lX",
        ownerLabel != nullptr ? ownerLabel : "(unknown)",
        reinterpret_cast<void*>(instructionAddress),
        reinterpret_cast<void*>(targetAddress),
        static_cast<unsigned int>(value32),
        static_cast<unsigned int>(value16),
        static_cast<unsigned long>(targetMbi.Protect)
    );

    if (R2R_AddressReadable(pointerValue, 4))
    {
        uint32_t deref32 = 0;
        uint16_t deref16 = 0;

        SafeReadMemory(
            reinterpret_cast<const void*>(pointerValue),
            &deref32,
            sizeof(deref32)
        );

        SafeReadMemory(
            reinterpret_cast<const void*>(pointerValue),
            &deref16,
            sizeof(deref16)
        );

        fprintf(
            report,
            "  -> ptr=%p deref32=0x%08X deref16=%u",
            reinterpret_cast<void*>(pointerValue),
            static_cast<unsigned int>(deref32),
            static_cast<unsigned int>(deref16)
        );
    }

    if (
        value16 >= 250 &&
        value16 <= 4096
        )
    {
        fprintf(report, "  [COUNT/INDEX-LIKE]");
    }

    fprintf(report, "\n");
}

bool R2R_VectorContainsAddress(
    const std::vector<uintptr_t>& values,
    uintptr_t value
)
{
    for (size_t i = 0; i < values.size(); i++)
    {
        if (values[i] == value)
        {
            return true;
        }
    }

    return false;
}

void R2R_ScanCodeRegionForA3dClues(
    FILE* report,
    const char* label,
    const void* functionAddress,
    size_t scanSize,
    uintptr_t imageBase,
    size_t imageSize,
    std::vector<uintptr_t>* outCalls
)
{
    if (
        report == nullptr ||
        label == nullptr ||
        functionAddress == nullptr ||
        scanSize == 0
        )
    {
        return;
    }

    const uintptr_t functionBase =
        reinterpret_cast<uintptr_t>(functionAddress);

    if (!R2R_AddressReadable(functionBase, scanSize))
    {
        fprintf(
            report,
            "\n[%s] code region is not readable: %p size=0x%zX\n",
            label,
            functionAddress,
            scanSize
        );
        return;
    }

    std::vector<uint8_t> code(scanSize);

    if (
        !SafeReadMemory(
            functionAddress,
            code.data(),
            scanSize
        )
        )
    {
        fprintf(report, "\n[%s] SafeReadMemory failed.\n", label);
        return;
    }

    fprintf(
        report,
        "\n============================================================\n"
        "CODE SCAN: %s\n"
        "============================================================\n\n"
        "Function : %p\n"
        "Scan size : 0x%zX\n\n",
        label,
        functionAddress,
        scanSize
    );

    std::vector<uintptr_t> seenDataTargets;
    unsigned int generalOffsetHits = 0;
    unsigned int absRefCount = 0;
    unsigned int directCallCount = 0;

    for (size_t i = 0; i < scanSize; i++)
    {
        // Direct x86 CALL rel32.
        if (code[i] == 0xE8 && i + 5 <= scanSize)
        {
            int32_t rel = 0;
            std::memcpy(&rel, &code[i + 1], sizeof(rel));

            const uintptr_t target =
                functionBase + i + 5 + static_cast<intptr_t>(rel);

            if (
                R2R_IsInsideMainImage(target, imageBase, imageSize) &&
                R2R_AddressExecutable(target)
                )
            {
                directCallCount++;

                if (
                    outCalls != nullptr &&
                    outCalls->size() < 64 &&
                    !R2R_VectorContainsAddress(*outCalls, target)
                    )
                {
                    outCalls->push_back(target);
                }
            }
        }

        // Common absolute-memory forms in 32-bit x86.
        uintptr_t absoluteTarget = 0;
        bool haveAbsoluteTarget = false;

        if (
            (code[i] >= 0xA0 && code[i] <= 0xA3) &&
            i + 5 <= scanSize
            )
        {
            uint32_t raw = 0;
            std::memcpy(&raw, &code[i + 1], sizeof(raw));
            absoluteTarget = static_cast<uintptr_t>(raw);
            haveAbsoluteTarget = true;
        }
        else
        {
            bool oneByteModRm = false;

            switch (code[i])
            {
            case 0x01: case 0x03:
            case 0x21: case 0x23:
            case 0x29: case 0x2B:
            case 0x31: case 0x33:
            case 0x39: case 0x3B:
            case 0x80: case 0x81: case 0x83:
            case 0x85:
            case 0x88: case 0x89: case 0x8A: case 0x8B:
            case 0xC6: case 0xC7:
            case 0xF6: case 0xF7:
            case 0xFF:
                oneByteModRm = true;
                break;
            default:
                break;
            }

            if (oneByteModRm && i + 6 <= scanSize)
            {
                const uint8_t modrm = code[i + 1];
                const uint8_t mod = (modrm >> 6) & 0x03;
                const uint8_t rm = modrm & 0x07;

                if (mod == 0 && rm == 5)
                {
                    uint32_t raw = 0;
                    std::memcpy(&raw, &code[i + 2], sizeof(raw));
                    absoluteTarget = static_cast<uintptr_t>(raw);
                    haveAbsoluteTarget = true;
                }
                else if (
                    mod == 0 &&
                    rm == 4 &&
                    i + 7 <= scanSize
                    )
                {
                    const uint8_t sib = code[i + 2];
                    const uint8_t base = sib & 0x07;

                    if (base == 5)
                    {
                        uint32_t raw = 0;
                        std::memcpy(&raw, &code[i + 3], sizeof(raw));
                        absoluteTarget = static_cast<uintptr_t>(raw);
                        haveAbsoluteTarget = true;
                    }
                }
            }

            if (
                !haveAbsoluteTarget &&
                code[i] == 0x0F &&
                i + 7 <= scanSize
                )
            {
                const uint8_t op2 = code[i + 1];
                const bool hasModRm =
                    op2 == 0xB6 ||
                    op2 == 0xB7 ||
                    op2 == 0xBE ||
                    op2 == 0xBF ||
                    op2 == 0xAF;

                if (hasModRm)
                {
                    const uint8_t modrm = code[i + 2];
                    const uint8_t mod = (modrm >> 6) & 0x03;
                    const uint8_t rm = modrm & 0x07;

                    if (mod == 0 && rm == 5)
                    {
                        uint32_t raw = 0;
                        std::memcpy(&raw, &code[i + 3], sizeof(raw));
                        absoluteTarget = static_cast<uintptr_t>(raw);
                        haveAbsoluteTarget = true;
                    }
                }
            }
        }

        if (
            haveAbsoluteTarget &&
            R2R_IsInsideMainImage(
                absoluteTarget,
                imageBase,
                imageSize
            ) &&
            !R2R_VectorContainsAddress(
                seenDataTargets,
                absoluteTarget
            )
            )
        {
            seenDataTargets.push_back(absoluteTarget);
            absRefCount++;

            R2R_ReportAbsoluteDataReference(
                report,
                label,
                functionBase + i,
                absoluteTarget,
                imageBase,
                imageSize
            );
        }

        // GAM_tdstAnim3d::uwNumOfA3dGENERAL is at +0x18 in the
        // public ACP_Ray2 32-bit structure.  Look for common x86 reads
        // of WORD PTR [reg+0x18].  This is only a locator, not a patch.
        if (
            i + 4 <= scanSize &&
            code[i] == 0x0F &&
            code[i + 1] == 0xB7
            )
        {
            const uint8_t modrm = code[i + 2];
            const uint8_t mod = (modrm >> 6) & 0x03;
            const uint8_t rm = modrm & 0x07;

            if (
                mod == 1 &&
                rm != 4 &&
                code[i + 3] == 0x18
                )
            {
                generalOffsetHits++;
                fprintf(
                    report,
                    "\n  POSSIBLE +0x18 WORD READ at %p (offset +0x%zX)\n",
                    reinterpret_cast<void*>(functionBase + i),
                    i
                );
                R2R_DumpHexWindow(report, code.data(), scanSize, i);
            }
        }

        if (
            i + 5 <= scanSize &&
            code[i] == 0x66 &&
            code[i + 1] == 0x8B
            )
        {
            const uint8_t modrm = code[i + 2];
            const uint8_t mod = (modrm >> 6) & 0x03;
            const uint8_t rm = modrm & 0x07;

            if (
                mod == 1 &&
                rm != 4 &&
                code[i + 3] == 0x18
                )
            {
                generalOffsetHits++;
                fprintf(
                    report,
                    "\n  POSSIBLE +0x18 WORD MOV at %p (offset +0x%zX)\n",
                    reinterpret_cast<void*>(functionBase + i),
                    i
                );
                R2R_DumpHexWindow(report, code.data(), scanSize, i);
            }
        }
    }

    fprintf(
        report,
        "\nSCAN SUMMARY\n"
        "------------------------------------------------------------\n"
        "Unique absolute in-image data refs : %u\n"
        "Direct in-image CALL instructions  : %u\n"
        "Possible Anim3d +0x18 reads        : %u\n",
        absRefCount,
        directCallCount,
        generalOffsetHits
    );
}

void R2R_ReportAnimationDescriptorFull(
    FILE* report,
    const char* label,
    GAM_tdstAnim3d* animation
)
{
    if (report == nullptr || label == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n%s\n"
        "------------------------------------------------------------\n"
        "Descriptor : %p\n",
        label,
        animation
    );

    if (animation == nullptr)
    {
        fprintf(report, "NULL\n");
        return;
    }

    GAM_tdstAnim3d copy = {};

    if (!SafeReadMemory(animation, &copy, sizeof(copy)))
    {
        fprintf(report, "READ FAILED\n");
        return;
    }

    fprintf(
        report,
        "sizeof(GAM_tdstAnim3d) : %zu\n"
        "Frames                 : %u\n"
        "FrameRate              : %u\n"
        "MaxElements            : %u\n"
        "AnimEvent ptr          : %p\n"
        "OffsetMatrix           : %.6f %.6f %.6f\n"
        "MorphData ptr          : %p\n"
        "uwNumOfA3dGENERAL      : %u\n"
        "NumberOfEvents         : %u\n"
        "Unused/alignment       : %u\n",
        sizeof(GAM_tdstAnim3d),
        static_cast<unsigned int>(copy.uwNumberOfFrames),
        static_cast<unsigned int>(copy.ucFrameRate),
        static_cast<unsigned int>(copy.ucMaxNumberOfElements),
        copy.d_stAnimEvent,
        copy.stOffsetMatrix.x,
        copy.stOffsetMatrix.y,
        copy.stOffsetMatrix.z,
        copy.d_stMorphDataArray,
        static_cast<unsigned int>(copy.uwNumOfA3dGENERAL),
        static_cast<unsigned int>(copy.ucNumberOfEvents),
        static_cast<unsigned int>(copy.ucUnused)
    );
}


void R2R_DumpRawBytes(
    FILE* report,
    const char* label,
    uintptr_t address,
    size_t count
)
{
    if (report == nullptr || label == nullptr || count == 0)
    {
        return;
    }

    fprintf(
        report,
        "\n%s @ %p (%zu bytes)\n"
        "------------------------------------------------------------\n",
        label,
        reinterpret_cast<void*>(address),
        count
    );

    if (!R2R_AddressReadable(address, count))
    {
        fprintf(report, "NOT READABLE AS ONE CONTIGUOUS BLOCK\n");
        return;
    }

    std::vector<uint8_t> bytes(count);

    if (!SafeReadMemory(
        reinterpret_cast<const void*>(address),
        bytes.data(),
        count
    ))
    {
        fprintf(report, "SafeReadMemory FAILED\n");
        return;
    }

    for (size_t i = 0; i < count; i += 16)
    {
        fprintf(
            report,
            "%p :",
            reinterpret_cast<void*>(address + i)
        );

        const size_t lineEnd = (i + 16 < count) ? i + 16 : count;

        for (size_t j = i; j < lineEnd; j++)
        {
            fprintf(report, " %02X", static_cast<unsigned int>(bytes[j]));
        }

        fprintf(report, "\n");
    }
}

void R2R_ReportIndexedCandidate(
    FILE* report,
    uintptr_t base,
    unsigned int id,
    size_t stride
)
{
    if (report == nullptr || base < 0x10000 || stride == 0)
    {
        return;
    }

    const uintptr_t address =
        base + static_cast<uintptr_t>(id) * static_cast<uintptr_t>(stride);

    fprintf(
        report,
        "    id=%3u stride=%2zu -> %p : ",
        id,
        stride,
        reinterpret_cast<void*>(address)
    );

    if (!R2R_AddressReadable(address, 16))
    {
        fprintf(report, "NOT READABLE\n");
        return;
    }

    uint8_t bytes[16] = {};

    if (!SafeReadMemory(
        reinterpret_cast<const void*>(address),
        bytes,
        sizeof(bytes)
    ))
    {
        fprintf(report, "READ FAILED\n");
        return;
    }

    for (size_t i = 0; i < sizeof(bytes); i++)
    {
        fprintf(report, "%02X%s", bytes[i], i + 1 == sizeof(bytes) ? "" : " ");
    }

    uint32_t first32 = 0;
    std::memcpy(&first32, bytes, sizeof(first32));

    if (R2R_AddressReadable(static_cast<uintptr_t>(first32), 4))
    {
        uint32_t deref = 0;
        SafeReadMemory(
            reinterpret_cast<const void*>(static_cast<uintptr_t>(first32)),
            &deref,
            sizeof(deref)
        );

        fprintf(
            report,
            "  first32->%p deref=0x%08X",
            reinterpret_cast<void*>(static_cast<uintptr_t>(first32)),
            static_cast<unsigned int>(deref)
        );
    }

    fprintf(report, "\n");
}

void R2R_RunFocusedA3dResolverProbe(
    FILE* report,
    uintptr_t imageBase,
    size_t imageSize
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n============================================================\n"
        "h.7.9 FOCUSED A3D GENERAL RESOLVER PROBE\n"
        "============================================================\n\n"
        "Why this function is interesting:\n"
        "  h.7.7 found a real WORD read at 0041A407 from Anim3d +0x18.\n"
        "  +0x18 is GAM_tdstAnim3d::uwNumOfA3dGENERAL.\n"
        "  The same function reads +0x18 again near 0041A64C and then\n"
        "  directly CALLs 004192E0 with that value on the stack.\n\n"
        "Known IDs in this process:\n"
        "  Bast_20 native  = 397\n"
        "  Water_20 Aglagl = 301\n"
        "\nThis section is READ-ONLY. No foreign animation is executed.\n"
    );

    const uintptr_t consumerAddress = 0x0041A400;
    const uintptr_t resolverAddress = 0x004192E0;

    std::vector<uintptr_t> consumerCalls;
    std::vector<uintptr_t> resolverCalls;

    R2R_ScanCodeRegionForA3dClues(
        report,
        "FOCUSED GENERAL CONSUMER @ 0041A400",
        reinterpret_cast<const void*>(consumerAddress),
        0x400,
        imageBase,
        imageSize,
        &consumerCalls
    );

    R2R_DumpRawBytes(
        report,
        "RAW CODE: 0041A400 GENERAL CONSUMER",
        consumerAddress,
        0x280
    );

    R2R_ScanCodeRegionForA3dClues(
        report,
        "FOCUSED GENERAL RESOLVER @ 004192E0",
        reinterpret_cast<const void*>(resolverAddress),
        0x500,
        imageBase,
        imageSize,
        &resolverCalls
    );

    R2R_DumpRawBytes(
        report,
        "RAW CODE: 004192E0 GENERAL RESOLVER",
        resolverAddress,
        0x300
    );

    fprintf(
        report,
        "\n============================================================\n"
        "004192E0 DIRECT CALLEES\n"
        "============================================================\n\n"
        "Unique executable direct calls found: %zu\n",
        resolverCalls.size()
    );

    const size_t resolverCallCount =
        resolverCalls.size() < 20 ? resolverCalls.size() : 20;

    for (size_t i = 0; i < resolverCallCount; i++)
    {
        char label[128] = {};

        sprintf_s(
            label,
            "004192E0 CALL #%zu @ %p",
            i,
            reinterpret_cast<void*>(resolverCalls[i])
        );

        R2R_ScanCodeRegionForA3dClues(
            report,
            label,
            reinterpret_cast<const void*>(resolverCalls[i]),
            0x240,
            imageBase,
            imageSize,
            nullptr
        );
    }

    fprintf(
        report,
        "\n============================================================\n"
        "GLOBAL CLUSTER 00500270..005002A8\n"
        "============================================================\n\n"
        "0041A400 references several globals in this tight range.\n"
        "For every pointer-looking slot below, the probe also tests\n"
        "common array strides at IDs 301 and 397.\n\n"
    );

    static const size_t strides[] =
    {
        2, 4, 8, 12, 16, 20, 24, 28, 32
    };

    for (uintptr_t slot = 0x00500270; slot <= 0x005002A8; slot += 4)
    {
        uint32_t value = 0;

        if (!R2R_AddressReadable(slot, sizeof(value)))
        {
            fprintf(
                report,
                "GLOBAL %p : NOT READABLE\n",
                reinterpret_cast<void*>(slot)
            );
            continue;
        }

        SafeReadMemory(
            reinterpret_cast<const void*>(slot),
            &value,
            sizeof(value)
        );

        const uintptr_t pointerValue = static_cast<uintptr_t>(value);

        fprintf(
            report,
            "\nGLOBAL %p = 0x%08X",
            reinterpret_cast<void*>(slot),
            static_cast<unsigned int>(value)
        );

        if (!R2R_AddressReadable(pointerValue, 16))
        {
            fprintf(report, "  [not a readable pointer]\n");
            continue;
        }

        fprintf(
            report,
            "  -> %p [READABLE]\n",
            reinterpret_cast<void*>(pointerValue)
        );

        uint8_t head[16] = {};
        SafeReadMemory(
            reinterpret_cast<const void*>(pointerValue),
            head,
            sizeof(head)
        );

        fprintf(report, "  base[0..15] : ");
        for (size_t i = 0; i < sizeof(head); i++)
        {
            fprintf(report, "%02X%s", head[i], i + 1 == sizeof(head) ? "" : " ");
        }
        fprintf(report, "\n");

        for (size_t s = 0; s < sizeof(strides) / sizeof(strides[0]); s++)
        {
            R2R_ReportIndexedCandidate(report, pointerValue, 301, strides[s]);
            R2R_ReportIndexedCandidate(report, pointerValue, 397, strides[s]);
        }
    }

    fprintf(
        report,
        "\n============================================================\n"
        "FOCUSED PROBE FINISHED\n"
        "============================================================\n"
    );
}


