bool R2R_ReadGlobal32(
    uintptr_t slot,
    uint32_t& value
)
{
    value = 0;

    if (!R2R_AddressReadable(slot, sizeof(value)))
    {
        return false;
    }

    return SafeReadMemory(
        reinterpret_cast<const void*>(slot),
        &value,
        sizeof(value)
    );
}

bool R2R_ReadA3dGeneralExact(
    uint16_t id,
    uint16_t outWords[28],
    uintptr_t& outAddress,
    uintptr_t& outBase
)
{
    outAddress = 0;
    outBase = 0;

    uint32_t base32 = 0;
    if (!R2R_ReadGlobal32(0x00500278, base32))
    {
        return false;
    }

    outBase = static_cast<uintptr_t>(base32);
    if (!R2R_AddressReadable(outBase, 0x38))
    {
        return false;
    }

    // Confirmed by Rayman 2 code at 004192E0:
    // return p_stA3dGENERAL + (id * 0x38).
    outAddress =
        outBase +
        static_cast<uintptr_t>(id) *
        static_cast<uintptr_t>(0x38);

    if (!R2R_AddressReadable(outAddress, 0x38))
    {
        return false;
    }

    return SafeReadMemory(
        reinterpret_cast<const void*>(outAddress),
        outWords,
        0x38
    );
}

void R2R_ReportA3dGeneralExact(
    FILE* report,
    uint16_t id,
    uint16_t saveWords[28],
    bool& saveValid
)
{
    if (report == nullptr)
    {
        return;
    }

    uint16_t words[28] = {};
    uintptr_t address = 0;
    uintptr_t base = 0;

    const bool ok =
        R2R_ReadA3dGeneralExact(
            id,
            words,
            address,
            base
        );

    fprintf(
        report,
        "\n------------------------------------------------------------\n"
        "A3D GENERAL ID %u\n"
        "------------------------------------------------------------\n"
        "p_stA3dGENERAL base : %p\n"
        "Exact stride         : 0x38 (56 bytes)\n"
        "Entry address        : %p\n"
        "Readable             : %s\n",
        static_cast<unsigned int>(id),
        reinterpret_cast<void*>(base),
        reinterpret_cast<void*>(address),
        ok ? "YES" : "NO"
    );

    if (!ok)
    {
        saveValid = false;
        return;
    }

    std::memcpy(saveWords, words, 0x38);
    saveValid = true;

    for (size_t i = 0; i < 28; i++)
    {
        fprintf(
            report,
            "  +0x%02X %-28s = %5u (0x%04X)\n",
            static_cast<unsigned int>(i * 2),
            R2R_A3D_WORD_NAMES[i],
            static_cast<unsigned int>(words[i]),
            static_cast<unsigned int>(words[i])
        );
    }

    fprintf(report, "  RAW 0x38 : ");
    const uint8_t* raw = reinterpret_cast<const uint8_t*>(words);
    for (size_t i = 0; i < 0x38; i++)
    {
        fprintf(
            report,
            "%02X%s",
            static_cast<unsigned int>(raw[i]),
            i + 1 == 0x38 ? "" : " "
        );
    }
    fprintf(report, "\n");
}

void R2R_ReportA3dWordDiff(
    FILE* report,
    const char* title,
    const uint16_t left[28],
    const uint16_t right[28]
)
{
    if (report == nullptr || title == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n============================================================\n"
        "%s\n"
        "============================================================\n",
        title
    );

    unsigned int differenceCount = 0;

    for (size_t i = 0; i < 28; i++)
    {
        if (left[i] == right[i])
        {
            continue;
        }

        differenceCount++;

        fprintf(
            report,
            "  +0x%02X %-28s : %5u -> %5u\n",
            static_cast<unsigned int>(i * 2),
            R2R_A3D_WORD_NAMES[i],
            static_cast<unsigned int>(left[i]),
            static_cast<unsigned int>(right[i])
        );
    }

    fprintf(
        report,
        "Different WORD fields: %u / 28\n",
        differenceCount
    );
}

void R2R_ReportA3dGlobalDiff(
    FILE* report,
    const uint32_t left[12],
    const uint32_t right[12]
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n============================================================\n"
        "WATER_20 vs BAST_20 GLOBAL ANIMATION BASE POINTERS\n"
        "============================================================\n"
    );

    unsigned int changed = 0;

    for (size_t i = 0; i < 12; i++)
    {
        const bool same = left[i] == right[i];
        if (!same)
        {
            changed++;
        }

        fprintf(
            report,
            "  %-20s Water=%08X  Bast=%08X  %s\n",
            R2R_A3D_GLOBAL_NAMES[i],
            static_cast<unsigned int>(left[i]),
            static_cast<unsigned int>(right[i]),
            same ? "SAME" : "DIFFERENT"
        );
    }

    fprintf(report, "Changed bases: %u / 12\n", changed);
}

void RunCurrentLevelA3dBankSnapshot()
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying
        )
    {
        return;
    }

    const char* levelName = GAM_g_stEngineStructure->szLevelName;
    if (levelName == nullptr)
    {
        levelName = "(unknown)";
    }

    const bool isWater = _stricmp(levelName, "Water_20") == 0;
    const bool isBast = _stricmp(levelName, "Bast_20") == 0;

    FILE* report = nullptr;
    fopen_s(
        &report,
        A3D_BANK_COMPARE_REPORT_FILE,
        g_A3dBankCompareStarted ? "a" : "w"
    );

    if (report == nullptr)
    {
        return;
    }

    if (!g_A3dBankCompareStarted)
    {
        fprintf(
            report,
            "RAYMAN 2 RANDOMIZER\n"
            "v0.0.14b.0 - EXACT R2 A3D BANK COMPARE\n"
            "============================================================\n\n"
            "READ-ONLY SNAPSHOT. No spawn. No foreign animation execution.\n"
            "Rayman 2 resolver 004192E0 uses 0x38-byte A3dGENERAL entries.\n"
        );
    }

    fprintf(
        report,
        "\n\n############################################################\n"
        "CURRENT LEVEL SNAPSHOT: %s\n"
        "############################################################\n",
        levelName
    );

    uint32_t globals[12] = {};

    fprintf(
        report,
        "\nGLOBAL ANIMATION TABLE BASES\n"
        "------------------------------------------------------------\n"
    );

    for (size_t i = 0; i < 12; i++)
    {
        const bool ok =
            R2R_ReadGlobal32(
                R2R_A3D_GLOBAL_SLOTS[i],
                globals[i]
            );

        fprintf(
            report,
            "  %p %-20s = %08X  %s\n",
            reinterpret_cast<void*>(R2R_A3D_GLOBAL_SLOTS[i]),
            R2R_A3D_GLOBAL_NAMES[i],
            static_cast<unsigned int>(globals[i]),
            ok ? "READ" : "FAILED"
        );
    }

    uint16_t scratch301[28] = {};
    uint16_t scratch397[28] = {};
    bool scratch301Valid = false;
    bool scratch397Valid = false;

    if (isWater)
    {
        R2R_ReportA3dGeneralExact(
            report,
            301,
            g_A3dWater301,
            g_A3dWater301Valid
        );

        // Also record 397 in Water_20 for context, but it is not stored
        // as one of the primary comparison snapshots.
        R2R_ReportA3dGeneralExact(
            report,
            397,
            scratch397,
            scratch397Valid
        );

        std::memcpy(g_A3dWaterGlobals, globals, sizeof(globals));
        g_A3dSawWater = true;
    }
    else if (isBast)
    {
        R2R_ReportA3dGeneralExact(
            report,
            301,
            g_A3dBast301,
            g_A3dBast301Valid
        );

        R2R_ReportA3dGeneralExact(
            report,
            397,
            g_A3dBast397,
            g_A3dBast397Valid
        );

        std::memcpy(g_A3dBastGlobals, globals, sizeof(globals));
        g_A3dSawBast = true;
    }
    else
    {
        // Unknown level: still dump the two IDs for inspection.
        R2R_ReportA3dGeneralExact(
            report,
            301,
            scratch301,
            scratch301Valid
        );

        R2R_ReportA3dGeneralExact(
            report,
            397,
            scratch397,
            scratch397Valid
        );
    }

    if (
        g_A3dSawWater &&
        g_A3dSawBast
        )
    {
        R2R_ReportA3dGlobalDiff(
            report,
            g_A3dWaterGlobals,
            g_A3dBastGlobals
        );

        if (g_A3dWater301Valid && g_A3dBast301Valid)
        {
            R2R_ReportA3dWordDiff(
                report,
                "WATER_20 GENERAL 301 vs BAST_20 GENERAL 301",
                g_A3dWater301,
                g_A3dBast301
            );
        }

        if (g_A3dWater301Valid && g_A3dBast397Valid)
        {
            R2R_ReportA3dWordDiff(
                report,
                "WATER_20 GENERAL 301 vs BAST_20 GENERAL 397",
                g_A3dWater301,
                g_A3dBast397
            );
        }

        fprintf(
            report,
            "\n============================================================\n"
            "COMPARE COMPLETE\n"
            "============================================================\n"
            "Both Water_20 and Bast_20 snapshots were captured in this process.\n"
        );
    }

    fflush(report);
    fclose(report);

    g_A3dBankCompareStarted = true;

    char message[1024] = {};

    if (g_A3dSawWater && g_A3dSawBast)
    {
        sprintf_s(
            message,
            "A3D BANK COMPARE COMPLETE!\n\nWater_20 and Bast_20 were both captured.\n\nSend me:\n%s\n\nNo object was spawned.",
            A3D_BANK_COMPARE_REPORT_FILE
        );
    }
    else if (isWater)
    {
        sprintf_s(
            message,
            "WATER_20 A3D SNAPSHOT SAVED!\n\nNow press F2 -> wait until Bast_20 is playable -> press F7 again.\n\nThe second snapshot will be appended to:\n%s",
            A3D_BANK_COMPARE_REPORT_FILE
        );
    }
    else if (isBast)
    {
        sprintf_s(
            message,
            "BAST_20 A3D SNAPSHOT SAVED!\n\nNow press F1 -> wait until Water_20 is playable -> press F7 again.\n\nThe second snapshot will be appended to:\n%s",
            A3D_BANK_COMPARE_REPORT_FILE
        );
    }
    else
    {
        sprintf_s(
            message,
            "A3D SNAPSHOT SAVED for %s.\n\nFor the comparison we need Water_20 and Bast_20.\n\nReport:\n%s",
            levelName,
            A3D_BANK_COMPARE_REPORT_FILE
        );
    }

    MessageBoxA(
        nullptr,
        message,
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | MB_ICONINFORMATION
    );
}

