uint32_t R2R_Fnv1a32(const void* data, size_t size)
{
    const uint8_t* bytes = reinterpret_cast<const uint8_t*>(data);
    uint32_t hash = 2166136261u;
    for (size_t i = 0; i < size; i++)
    {
        hash ^= bytes[i];
        hash *= 16777619u;
    }
    return hash;
}

bool R2R_ReadSliceToVector(
    uintptr_t base,
    uint32_t start,
    uint32_t count,
    size_t elementSize,
    std::vector<uint8_t>& out
)
{
    out.clear();

    if (count == 0)
    {
        return true;
    }

    if (base == 0 || elementSize == 0 || count > 1000000u)
    {
        return false;
    }

    const size_t byteCount = static_cast<size_t>(count) * elementSize;
    const uintptr_t address =
        base + static_cast<uintptr_t>(start) * elementSize;

    if (!R2R_AddressReadable(address, byteCount))
    {
        return false;
    }

    out.resize(byteCount);
    if (!SafeReadMemory(
        reinterpret_cast<const void*>(address),
        out.data(),
        byteCount
    ))
    {
        out.clear();
        return false;
    }

    return true;
}

uint16_t R2R_ReadVecU16(const std::vector<uint8_t>& data, size_t offset)
{
    uint16_t value = 0;
    if (offset + sizeof(value) <= data.size())
    {
        std::memcpy(&value, data.data() + offset, sizeof(value));
    }
    return value;
}

uint32_t R2R_ReadVecU32(const std::vector<uint8_t>& data, size_t offset)
{
    uint32_t value = 0;
    if (offset + sizeof(value) <= data.size())
    {
        std::memcpy(&value, data.data() + offset, sizeof(value));
    }
    return value;
}

static int R2R_ActionSourceGeneralIndex(uint16_t generalId)
{
    for (int i = 0; i < 4; i++)
    {
        if (R2R_ACTION_SOURCE_GENERAL_IDS[i] == generalId)
        {
            return i;
        }
    }

    return -1;
}

static bool R2R_CaptureWaterAglaglActionBank(FILE* report)
{
    uint32_t globals[12] = {};

    for (size_t i = 0; i < 12; i++)
    {
        if (!R2R_ReadGlobal32(R2R_A3D_GLOBAL_SLOTS[i], globals[i]))
        {
            if (report != nullptr)
            {
                fprintf(
                    report,
                    "ACTION BANK CAPTURE FAILED: global %s unreadable.\n",
                    R2R_A3D_GLOBAL_NAMES[i]
                );
            }
            return false;
        }
    }

    uint32_t minVector = 0xFFFFFFFFu;
    uint32_t maxVector = 0;
    uint32_t minQuat = 0xFFFFFFFFu;
    uint32_t maxQuat = 0;
    uint32_t minHier = 0xFFFFFFFFu;
    uint32_t maxHier = 0;
    uint32_t minNTTO = 0xFFFFFFFFu;
    uint32_t maxNTTO = 0;
    uint32_t minOnly = 0xFFFFFFFFu;
    uint32_t maxOnly = 0;
    uint32_t minChannel = 0xFFFFFFFFu;
    uint32_t maxChannel = 0;
    uint32_t minFrames = 0xFFFFFFFFu;
    uint32_t maxFrames = 0;
    uint32_t minFramesKF = 0xFFFFFFFFu;
    uint32_t maxFramesKF = 0;
    uint32_t minKeyFrame = 0xFFFFFFFFu;
    uint32_t maxKeyFrame = 0;

    bool ok = true;

    for (int g = 0; g < 4; g++)
    {
        uintptr_t address = 0;
        uintptr_t base = 0;

        ok &= R2R_ReadA3dGeneralExact(
            R2R_ACTION_SOURCE_GENERAL_IDS[g],
            g_R2RActionGeneralWords[g],
            address,
            base
        );

        if (!ok)
        {
            break;
        }

        const uint16_t* words =
            g_R2RActionGeneralWords[g];

        auto updateRange =
            [](
                uint32_t start,
                uint32_t count,
                uint32_t& minimum,
                uint32_t& maximum
                )
            {
                if (count == 0)
                {
                    return;
                }

                if (start < minimum)
                {
                    minimum = start;
                }

                if (start + count > maximum)
                {
                    maximum = start + count;
                }
            };

        updateRange(
            words[19], words[1],
            minVector, maxVector
        );

        updateRange(
            words[20], words[2],
            minQuat, maxQuat
        );

        updateRange(
            words[21], words[3],
            minHier, maxHier
        );

        updateRange(
            words[22], words[4],
            minNTTO, maxNTTO
        );

        updateRange(
            words[23], words[7],
            minOnly, maxOnly
        );

        updateRange(
            words[24], words[6],
            minChannel, maxChannel
        );

        const uint32_t channelStart =
            words[24];

        const uint32_t channelCount =
            words[6];

        const uint32_t numNumNTTO =
            words[5];

        const uint32_t onlyFrameCount =
            words[7];

        const uint32_t totalKeyFrames =
            words[8];

        for (uint32_t c = 0; c < channelCount; c++)
        {
            uint8_t raw[16] = {};

            const uintptr_t channelAddress =
                static_cast<uintptr_t>(
                    globals[2]
                    ) +
                static_cast<uintptr_t>(
                    channelStart + c
                    ) * 16u;

            if (
                !R2R_AddressReadable(
                    channelAddress,
                    sizeof(raw)
                ) ||
                !SafeReadMemory(
                    reinterpret_cast<const void*>(
                        channelAddress
                        ),
                    raw,
                    sizeof(raw)
                )
                )
            {
                ok = false;
                break;
            }

            uint16_t numStart = 0;
            uint32_t framesKFStart = 0;
            uint32_t keyFrameStart = 0;

            std::memcpy(
                &numStart,
                raw + 6,
                sizeof(numStart)
            );

            std::memcpy(
                &framesKFStart,
                raw + 8,
                sizeof(framesKFStart)
            );

            std::memcpy(
                &keyFrameStart,
                raw + 12,
                sizeof(keyFrameStart)
            );

            updateRange(
                static_cast<uint32_t>(
                    numStart
                    ),
                numNumNTTO,
                minFrames,
                maxFrames
            );

            updateRange(
                framesKFStart,
                onlyFrameCount,
                minFramesKF,
                maxFramesKF
            );

            // Same conservative bound already proven in the 301 importer.
            updateRange(
                keyFrameStart,
                totalKeyFrames,
                minKeyFrame,
                maxKeyFrame
            );
        }

        if (!ok)
        {
            break;
        }
    }

    if (!ok)
    {
        if (report != nullptr)
        {
            fprintf(
                report,
                "ACTION BANK CAPTURE FAILED while reading descriptors/channels.\n"
            );
        }
        return false;
    }

    auto normalize =
        [](
            uint32_t minimum,
            uint32_t maximum,
            uint32_t& start,
            uint32_t& count
            )
        {
            if (
                minimum == 0xFFFFFFFFu ||
                maximum < minimum
                )
            {
                start = 0;
                count = 0;
                return;
            }

            start = minimum;
            count = maximum - minimum;
        };

    normalize(
        minVector, maxVector,
        g_R2RActionVectorStart,
        g_R2RActionVectorCount
    );

    normalize(
        minQuat, maxQuat,
        g_R2RActionQuaternionStart,
        g_R2RActionQuaternionCount
    );

    normalize(
        minHier, maxHier,
        g_R2RActionHierarchyStart,
        g_R2RActionHierarchyCount
    );

    normalize(
        minNTTO, maxNTTO,
        g_R2RActionNTTOStart,
        g_R2RActionNTTOCount
    );

    normalize(
        minOnly, maxOnly,
        g_R2RActionOnlyFrameStart,
        g_R2RActionOnlyFrameCount
    );

    normalize(
        minChannel, maxChannel,
        g_R2RActionChannelStart,
        g_R2RActionChannelCount
    );

    normalize(
        minFrames, maxFrames,
        g_R2RActionFramesStart,
        g_R2RActionFramesCount
    );

    normalize(
        minFramesKF, maxFramesKF,
        g_R2RActionFramesKFStart,
        g_R2RActionFramesKFCount
    );

    normalize(
        minKeyFrame, maxKeyFrame,
        g_R2RActionKeyFrameStart,
        g_R2RActionKeyFrameCount
    );

    ok &= R2R_ReadSliceToVector(
        globals[8],
        g_R2RActionVectorStart,
        g_R2RActionVectorCount,
        12,
        g_R2RActionVectors
    );

    ok &= R2R_ReadSliceToVector(
        globals[11],
        g_R2RActionQuaternionStart,
        g_R2RActionQuaternionCount,
        8,
        g_R2RActionQuaternions
    );

    ok &= R2R_ReadSliceToVector(
        globals[4],
        g_R2RActionHierarchyStart,
        g_R2RActionHierarchyCount,
        4,
        g_R2RActionHierarchies
    );

    ok &= R2R_ReadSliceToVector(
        globals[10],
        g_R2RActionNTTOStart,
        g_R2RActionNTTOCount,
        6,
        g_R2RActionNTTO
    );

    ok &= R2R_ReadSliceToVector(
        globals[7],
        g_R2RActionOnlyFrameStart,
        g_R2RActionOnlyFrameCount,
        10,
        g_R2RActionOnlyFrames
    );

    ok &= R2R_ReadSliceToVector(
        globals[2],
        g_R2RActionChannelStart,
        g_R2RActionChannelCount,
        16,
        g_R2RActionChannels
    );

    ok &= R2R_ReadSliceToVector(
        globals[3],
        g_R2RActionFramesStart,
        g_R2RActionFramesCount,
        2,
        g_R2RActionFrames
    );

    ok &= R2R_ReadSliceToVector(
        globals[0],
        g_R2RActionFramesKFStart,
        g_R2RActionFramesKFCount,
        4,
        g_R2RActionFramesKF
    );

    ok &= R2R_ReadSliceToVector(
        globals[6],
        g_R2RActionKeyFrameStart,
        g_R2RActionKeyFrameCount,
        36,
        g_R2RActionKeyFrames
    );

    g_R2RActionBankCaptured = ok;

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nACTION ANIMATION BANK CAPTURE (301/302/303/305)\n"
            "------------------------------------------------------------\n"
            "Broad union deliberately includes gaps between required Generals.\n"
            "Events are NOT imported in h.7.68; General 302's single event is\n"
            "suppressed for this first real-motion test.\n"
            "  vectors       start=%u count=%u\n"
            "  quaternions   start=%u count=%u\n"
            "  hierarchies   start=%u count=%u\n"
            "  NTTO          start=%u count=%u\n"
            "  onlyFrames    start=%u count=%u\n"
            "  channels      start=%u count=%u\n"
            "  frames        start=%u count=%u\n"
            "  framesKF      start=%u count=%u\n"
            "  keyFrames     start=%u count=%u\n"
            "  result        %s\n",
            g_R2RActionVectorStart,
            g_R2RActionVectorCount,
            g_R2RActionQuaternionStart,
            g_R2RActionQuaternionCount,
            g_R2RActionHierarchyStart,
            g_R2RActionHierarchyCount,
            g_R2RActionNTTOStart,
            g_R2RActionNTTOCount,
            g_R2RActionOnlyFrameStart,
            g_R2RActionOnlyFrameCount,
            g_R2RActionChannelStart,
            g_R2RActionChannelCount,
            g_R2RActionFramesStart,
            g_R2RActionFramesCount,
            g_R2RActionFramesKFStart,
            g_R2RActionFramesKFCount,
            g_R2RActionKeyFrameStart,
            g_R2RActionKeyFrameCount,
            ok ? "SUCCESS" : "FAILED"
        );

        fflush(report);
    }

    return ok;
}



void R2R_ReportCapturedSlice(
    FILE* report,
    const char* name,
    uint32_t start,
    uint32_t count,
    size_t elementSize,
    const std::vector<uint8_t>& bytes
)
{
    if (report == nullptr || name == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "  %-18s start=%6u count=%6u elem=%2zu bytes=%7zu hash=%08X %s\n",
        name,
        static_cast<unsigned int>(start),
        static_cast<unsigned int>(count),
        elementSize,
        bytes.size(),
        bytes.empty() && count != 0
        ? 0u
        : static_cast<unsigned int>(R2R_Fnv1a32(bytes.data(), bytes.size())),
        (count == 0 || !bytes.empty()) ? "OK" : "FAILED"
    );
}

struct R2R_A3dUsageSummary
{
    uint32_t highestAnimationPlusOne;
    uint32_t validAnimations;
    uint32_t vectors;
    uint32_t quaternions;
    uint32_t hierarchies;
    uint32_t ntto;
    uint32_t onlyFrames;
    uint32_t channels;
    uint32_t frames;
    uint32_t framesKF;
    uint32_t keyFrames;
    uint32_t events;
    uint32_t morphData;
};

void R2R_UpdateMaxU32(uint32_t& destination, uint32_t value)
{
    if (value > destination)
    {
        destination = value;
    }
}

bool R2R_A3dWordsPlausible(const uint16_t words[28])
{
    if (words == nullptr)
    {
        return false;
    }

    bool any = false;
    for (size_t i = 0; i < 28; i++)
    {
        if (words[i] != 0)
        {
            any = true;
            break;
        }
    }

    if (!any)
    {
        return false;
    }

    // Conservative sanity filter.  We only use this to estimate the live
    // Bast_20 footprint, never to modify game memory.
    if (words[0] > 1000u) return false; // speed
    if (words[1] > 20000u) return false;
    if (words[2] > 20000u) return false;
    if (words[3] > 20000u) return false;
    if (words[4] > 20000u) return false;
    if (words[5] > 20000u) return false;
    if (words[6] > 2048u) return false;  // channels
    if (words[7] > 20000u) return false; // onlyFrames
    if (words[8] > 30000u) return false; // keyframes

    return true;
}

R2R_A3dUsageSummary R2R_ScanCurrentA3dUsage(FILE* report)
{
    R2R_A3dUsageSummary usage = {};

    uint32_t globals[12] = {};
    for (size_t i = 0; i < 12; i++)
    {
        R2R_ReadGlobal32(R2R_A3D_GLOBAL_SLOTS[i], globals[i]);
    }

    const uintptr_t channelBase = static_cast<uintptr_t>(globals[2]);

    // 1024 is intentionally a diagnostic ceiling, not an assumed game limit.
    // Fresh process + Water->Bast ordering keeps the unused tail zeroed in our
    // current experiment and makes this a useful footprint estimate.
    for (uint32_t id = 0; id < 1024u; id++)
    {
        uint16_t words[28] = {};
        uintptr_t address = 0;
        uintptr_t base = 0;

        if (!R2R_ReadA3dGeneralExact(
            static_cast<uint16_t>(id),
            words,
            address,
            base
        ))
        {
            break;
        }

        if (!R2R_A3dWordsPlausible(words))
        {
            continue;
        }

        usage.validAnimations++;
        usage.highestAnimationPlusOne = id + 1u;

        R2R_UpdateMaxU32(usage.vectors, static_cast<uint32_t>(words[19]) + words[1]);
        R2R_UpdateMaxU32(usage.quaternions, static_cast<uint32_t>(words[20]) + words[2]);
        R2R_UpdateMaxU32(usage.hierarchies, static_cast<uint32_t>(words[21]) + words[3]);
        R2R_UpdateMaxU32(usage.ntto, static_cast<uint32_t>(words[22]) + words[4]);
        R2R_UpdateMaxU32(usage.onlyFrames, static_cast<uint32_t>(words[23]) + words[7]);
        R2R_UpdateMaxU32(usage.channels, static_cast<uint32_t>(words[24]) + words[6]);
        R2R_UpdateMaxU32(usage.events, static_cast<uint32_t>(words[25]) + words[10]);
        R2R_UpdateMaxU32(usage.morphData, static_cast<uint32_t>(words[26]) + words[18]);

        const uint32_t channelStart = words[24];
        const uint32_t channelCount = words[6];
        const uint32_t numNumNTTO = words[5];
        const uint32_t onlyFrameCount = words[7];
        const uint32_t totalKeyFrames = words[8];

        if (
            channelBase != 0 &&
            channelCount > 0 &&
            channelCount <= 2048u
            )
        {
            for (uint32_t c = 0; c < channelCount; c++)
            {
                uint8_t raw[16] = {};
                const uintptr_t chAddress =
                    channelBase +
                    static_cast<uintptr_t>(channelStart + c) * 16u;

                if (!R2R_AddressReadable(chAddress, sizeof(raw)) ||
                    !SafeReadMemory(
                        reinterpret_cast<const void*>(chAddress),
                        raw,
                        sizeof(raw)
                    ))
                {
                    continue;
                }

                uint16_t numStart = 0;
                uint32_t framesKFStart = 0;
                uint32_t keyFrameStart = 0;
                std::memcpy(&numStart, raw + 6, sizeof(numStart));
                std::memcpy(&framesKFStart, raw + 8, sizeof(framesKFStart));
                std::memcpy(&keyFrameStart, raw + 12, sizeof(keyFrameStart));

                R2R_UpdateMaxU32(
                    usage.frames,
                    static_cast<uint32_t>(numStart) + numNumNTTO
                );
                R2R_UpdateMaxU32(
                    usage.framesKF,
                    framesKFStart + onlyFrameCount
                );

                // Conservative copy bound: a channel cannot require more than
                // the animation's complete keyframe count from its start.
                R2R_UpdateMaxU32(
                    usage.keyFrames,
                    keyFrameStart + totalKeyFrames
                );
            }
        }
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nBAST_20 ESTIMATED LIVE ANIMATION FOOTPRINT\n"
            "------------------------------------------------------------\n"
            "  plausible A3dGENERAL entries : %u\n"
            "  highest plausible ID + 1      : %u\n"
            "  vectors used through          : %u\n"
            "  quaternions used through      : %u\n"
            "  hierarchies used through      : %u\n"
            "  NTTO used through             : %u\n"
            "  onlyFrames used through       : %u\n"
            "  channels used through         : %u\n"
            "  frames/numNTTO used through   : %u\n"
            "  framesKF used through         : %u\n"
            "  keyFrames conservative through: %u\n"
            "  events used through           : %u\n"
            "  morphData used through        : %u\n",
            usage.validAnimations,
            usage.highestAnimationPlusOne,
            usage.vectors,
            usage.quaternions,
            usage.hierarchies,
            usage.ntto,
            usage.onlyFrames,
            usage.channels,
            usage.frames,
            usage.framesKF,
            usage.keyFrames,
            usage.events,
            usage.morphData
        );
    }

    return usage;
}

void R2R_ReportDonorOverwriteCheck(
    FILE* report,
    const char* name,
    uintptr_t base,
    uint32_t start,
    uint32_t count,
    size_t elementSize,
    const std::vector<uint8_t>& saved
)
{
    if (report == nullptr || name == nullptr)
    {
        return;
    }

    std::vector<uint8_t> current;
    const bool ok = R2R_ReadSliceToVector(
        base, start, count, elementSize, current
    );

    const uint32_t savedHash =
        saved.empty() ? 0u : R2R_Fnv1a32(saved.data(), saved.size());
    const uint32_t currentHash =
        current.empty() ? 0u : R2R_Fnv1a32(current.data(), current.size());

    const bool same =
        ok &&
        saved.size() == current.size() &&
        (saved.empty() || std::memcmp(saved.data(), current.data(), saved.size()) == 0);

    fprintf(
        report,
        "  %-18s WaterSaved=%08X BastAtSameIndex=%08X  %s\n",
        name,
        static_cast<unsigned int>(savedHash),
        static_cast<unsigned int>(currentHash),
        same ? "SAME" : "OVERWRITTEN/DIFFERENT"
    );
}

bool R2R_CaptureWaterAglagl301(FILE* report)
{
    uint16_t words[28] = {};
    uintptr_t address = 0;
    uintptr_t base = 0;

    if (!R2R_ReadA3dGeneralExact(301, words, address, base))
    {
        fprintf(report, "FAILED: could not read Water_20 A3dGENERAL #301.\n");
        return false;
    }

    std::memcpy(g_A3dDonor301Words, words, sizeof(words));

    uint32_t globals[12] = {};
    for (size_t i = 0; i < 12; i++)
    {
        if (!R2R_ReadGlobal32(R2R_A3D_GLOBAL_SLOTS[i], globals[i]))
        {
            fprintf(report, "FAILED: could not read global slot %s.\n", R2R_A3D_GLOBAL_NAMES[i]);
            return false;
        }
    }

    const uint32_t numVectors = words[1];
    const uint32_t numQuaternions = words[2];
    const uint32_t numHierarchies = words[3];
    const uint32_t numNTTO = words[4];
    const uint32_t numNumNTTO = words[5];
    const uint32_t numChannels = words[6];
    const uint32_t numOnlyFrames = words[7];
    const uint32_t numKeyFrames = words[8];

    const uint32_t startVectors = words[19];
    const uint32_t startQuaternions = words[20];
    const uint32_t startHierarchies = words[21];
    const uint32_t startNTTO = words[22];
    const uint32_t startOnlyFrames = words[23];
    const uint32_t startChannels = words[24];

    bool ok = true;
    ok &= R2R_ReadSliceToVector(globals[8], startVectors, numVectors, 12, g_A3dDonorVectors);
    ok &= R2R_ReadSliceToVector(globals[11], startQuaternions, numQuaternions, 8, g_A3dDonorQuaternions);
    ok &= R2R_ReadSliceToVector(globals[4], startHierarchies, numHierarchies, 4, g_A3dDonorHierarchies);
    ok &= R2R_ReadSliceToVector(globals[10], startNTTO, numNTTO, 6, g_A3dDonorNTTO);
    ok &= R2R_ReadSliceToVector(globals[7], startOnlyFrames, numOnlyFrames, 10, g_A3dDonorOnlyFrames);
    ok &= R2R_ReadSliceToVector(globals[2], startChannels, numChannels, 16, g_A3dDonorChannels);

    fprintf(
        report,
        "\nWATER_20 AGLAGL A3dGENERAL #301\n"
        "------------------------------------------------------------\n"
        "  entry address : %p\n"
        "  speed=%u vectors=%u quaternions=%u hierarchies=%u NTTO=%u\n"
        "  numNumNTTO=%u channels=%u onlyFrames=%u keyFrames=%u\n",
        reinterpret_cast<void*>(address),
        words[0], numVectors, numQuaternions, numHierarchies, numNTTO,
        numNumNTTO, numChannels, numOnlyFrames, numKeyFrames
    );

    R2R_ReportCapturedSlice(report, "vectors", startVectors, numVectors, 12, g_A3dDonorVectors);
    R2R_ReportCapturedSlice(report, "quaternions", startQuaternions, numQuaternions, 8, g_A3dDonorQuaternions);
    R2R_ReportCapturedSlice(report, "hierarchies", startHierarchies, numHierarchies, 4, g_A3dDonorHierarchies);
    R2R_ReportCapturedSlice(report, "NTTO", startNTTO, numNTTO, 6, g_A3dDonorNTTO);
    R2R_ReportCapturedSlice(report, "onlyFrames", startOnlyFrames, numOnlyFrames, 10, g_A3dDonorOnlyFrames);
    R2R_ReportCapturedSlice(report, "channels", startChannels, numChannels, 16, g_A3dDonorChannels);

    uint32_t minFrames = 0xFFFFFFFFu;
    uint32_t maxFrames = 0u;
    uint32_t minFramesKF = 0xFFFFFFFFu;
    uint32_t maxFramesKF = 0u;
    uint32_t minKeyFrames = 0xFFFFFFFFu;

    fprintf(report, "\nCHANNEL REFERENCES (16 bytes each)\n");

    for (uint32_t c = 0; c < numChannels; c++)
    {
        const size_t off = static_cast<size_t>(c) * 16u;
        const uint16_t unk0 = R2R_ReadVecU16(g_A3dDonorChannels, off + 0);
        const uint16_t id = R2R_ReadVecU16(g_A3dDonorChannels, off + 2);
        const uint16_t vectorIndex = R2R_ReadVecU16(g_A3dDonorChannels, off + 4);
        const uint16_t numStart = R2R_ReadVecU16(g_A3dDonorChannels, off + 6);
        const uint32_t framesKFStart = R2R_ReadVecU32(g_A3dDonorChannels, off + 8);
        const uint32_t keyFrameStart = R2R_ReadVecU32(g_A3dDonorChannels, off + 12);

        if (numStart < minFrames) minFrames = numStart;
        if (static_cast<uint32_t>(numStart) + numNumNTTO > maxFrames)
            maxFrames = static_cast<uint32_t>(numStart) + numNumNTTO;

        if (framesKFStart < minFramesKF) minFramesKF = framesKFStart;
        if (framesKFStart + numOnlyFrames > maxFramesKF)
            maxFramesKF = framesKFStart + numOnlyFrames;

        if (keyFrameStart < minKeyFrames) minKeyFrames = keyFrameStart;

        fprintf(
            report,
            "  ch[%u] unk0=%u id=%u vector=%u numNTTOStart=%u framesKFStart=%u keyFrameStart=%u\n",
            c, unk0, id, vectorIndex,
            static_cast<unsigned int>(numStart),
            static_cast<unsigned int>(framesKFStart),
            static_cast<unsigned int>(keyFrameStart)
        );
    }

    if (minFrames == 0xFFFFFFFFu) minFrames = 0;
    if (minFramesKF == 0xFFFFFFFFu) minFramesKF = 0;
    if (minKeyFrames == 0xFFFFFFFFu) minKeyFrames = 0;

    g_A3dDonorFramesStart = minFrames;
    g_A3dDonorFramesCount = maxFrames >= minFrames ? maxFrames - minFrames : 0;
    g_A3dDonorFramesKFStart = minFramesKF;
    g_A3dDonorFramesKFCount = maxFramesKF >= minFramesKF ? maxFramesKF - minFramesKF : 0;
    g_A3dDonorKeyFramesStart = minKeyFrames;
    g_A3dDonorKeyFramesCount = numKeyFrames;

    ok &= R2R_ReadSliceToVector(
        globals[3],
        g_A3dDonorFramesStart,
        g_A3dDonorFramesCount,
        2,
        g_A3dDonorFrames
    );
    ok &= R2R_ReadSliceToVector(
        globals[0],
        g_A3dDonorFramesKFStart,
        g_A3dDonorFramesKFCount,
        4,
        g_A3dDonorFramesKF
    );
    ok &= R2R_ReadSliceToVector(
        globals[6],
        g_A3dDonorKeyFramesStart,
        g_A3dDonorKeyFramesCount,
        36,
        g_A3dDonorKeyFrames
    );

    fprintf(report, "\nSECONDARY CHANNEL-REFERENCED SLICES\n");
    R2R_ReportCapturedSlice(report, "frames/numNTTO", g_A3dDonorFramesStart, g_A3dDonorFramesCount, 2, g_A3dDonorFrames);
    R2R_ReportCapturedSlice(report, "framesKF", g_A3dDonorFramesKFStart, g_A3dDonorFramesKFCount, 4, g_A3dDonorFramesKF);
    R2R_ReportCapturedSlice(report, "keyFrames", g_A3dDonorKeyFramesStart, g_A3dDonorKeyFramesCount, 36, g_A3dDonorKeyFrames);

    fprintf(
        report,
        "\nNOTE: Water_20 Aglagl #301 has num_events=%u and num_morphData=%u,\n"
        "so no event or morph payload needs to be captured for this animation.\n",
        words[10], words[18]
    );

    g_A3dDonor301Captured = ok;
    return ok;
}

void RunAglaglDependencyFootprintProbe()
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying
        )
    {
        return;
    }

    const char* levelName = GAM_g_stEngineStructure->szLevelName;
    if (levelName == nullptr)
    {
        levelName = "(unknown)";
    }

    const bool isWater = _stricmp(levelName, "Water_20") == 0;
    const bool isBast = _stricmp(levelName, "Bast_20") == 0;

    FILE* report = nullptr;
    fopen_s(
        &report,
        A3D_DEPENDENCY_REPORT_FILE,
        g_A3dDependencyReportStarted ? "a" : "w"
    );

    if (report == nullptr)
    {
        return;
    }

    if (!g_A3dDependencyReportStarted)
    {
        fprintf(
            report,
            "RAYMAN 2 RANDOMIZER\n"
            "v0.0.14b.0 - AGLAGL A3D DEPENDENCY FOOTPRINT\n"
            "============================================================\n\n"
            "READ-ONLY PROBE. No spawn and no game animation data is modified.\n"
            "Goal: capture every global animation slice used by Water_20 Aglagl\n"
            "A3dGENERAL #301, then measure the active Bast_20 footprint needed\n"
            "for a future merged cross-level animation bank.\n"
        );
    }

    fprintf(
        report,
        "\n\n############################################################\n"
        "CURRENT LEVEL: %s\n"
        "############################################################\n",
        levelName
    );

    if (isWater)
    {
        const bool ok = R2R_CaptureWaterAglagl301(report);
        fprintf(
            report,
            "\nWATER CAPTURE RESULT: %s\n",
            ok ? "SUCCESS" : "FAILED"
        );
    }
    else if (isBast)
    {
        if (!g_A3dDonor301Captured)
        {
            fprintf(
                report,
                "ERROR: Water_20 donor capture is not present in this process.\n"
                "Start fresh, go to Water_20, press F7, then go to Bast_20 and press F7.\n"
            );
        }
        else
        {
            uint32_t globals[12] = {};
            for (size_t i = 0; i < 12; i++)
            {
                R2R_ReadGlobal32(R2R_A3D_GLOBAL_SLOTS[i], globals[i]);
            }

            fprintf(
                report,
                "\nDONOR BYTES AT THEIR ORIGINAL WATER INDICES AFTER BAST LOAD\n"
                "------------------------------------------------------------\n"
            );

            R2R_ReportDonorOverwriteCheck(report, "vectors", globals[8], g_A3dDonor301Words[19], g_A3dDonor301Words[1], 12, g_A3dDonorVectors);
            R2R_ReportDonorOverwriteCheck(report, "quaternions", globals[11], g_A3dDonor301Words[20], g_A3dDonor301Words[2], 8, g_A3dDonorQuaternions);
            R2R_ReportDonorOverwriteCheck(report, "hierarchies", globals[4], g_A3dDonor301Words[21], g_A3dDonor301Words[3], 4, g_A3dDonorHierarchies);
            R2R_ReportDonorOverwriteCheck(report, "NTTO", globals[10], g_A3dDonor301Words[22], g_A3dDonor301Words[4], 6, g_A3dDonorNTTO);
            R2R_ReportDonorOverwriteCheck(report, "onlyFrames", globals[7], g_A3dDonor301Words[23], g_A3dDonor301Words[7], 10, g_A3dDonorOnlyFrames);
            R2R_ReportDonorOverwriteCheck(report, "channels", globals[2], g_A3dDonor301Words[24], g_A3dDonor301Words[6], 16, g_A3dDonorChannels);
            R2R_ReportDonorOverwriteCheck(report, "frames/numNTTO", globals[3], g_A3dDonorFramesStart, g_A3dDonorFramesCount, 2, g_A3dDonorFrames);
            R2R_ReportDonorOverwriteCheck(report, "framesKF", globals[0], g_A3dDonorFramesKFStart, g_A3dDonorFramesKFCount, 4, g_A3dDonorFramesKF);
            R2R_ReportDonorOverwriteCheck(report, "keyFrames", globals[6], g_A3dDonorKeyFramesStart, g_A3dDonorKeyFramesCount, 36, g_A3dDonorKeyFrames);

            const R2R_A3dUsageSummary usage = R2R_ScanCurrentA3dUsage(report);

            fprintf(
                report,
                "\nDONOR APPEND REQUIREMENTS FOR FUTURE MERGED BANK\n"
                "------------------------------------------------------------\n"
                "  A3dGENERAL entries : +1 (synthetic ID candidate %u)\n"
                "  vectors            : +%u\n"
                "  quaternions        : +%u\n"
                "  hierarchies        : +%u\n"
                "  NTTO               : +%u\n"
                "  onlyFrames         : +%u\n"
                "  channels           : +%u\n"
                "  frames/numNTTO     : +%u\n"
                "  framesKF           : +%u\n"
                "  keyFrames          : +%u\n"
                "  events             : +0\n"
                "  morphData          : +0\n",
                usage.highestAnimationPlusOne,
                g_A3dDonor301Words[1],
                g_A3dDonor301Words[2],
                g_A3dDonor301Words[3],
                g_A3dDonor301Words[4],
                g_A3dDonor301Words[7],
                g_A3dDonor301Words[6],
                g_A3dDonorFramesCount,
                g_A3dDonorFramesKFCount,
                g_A3dDonorKeyFramesCount
            );

            fprintf(
                report,
                "\nNEXT-BUILD PLAN\n"
                "------------------------------------------------------------\n"
                "Allocate private merged copies of the Bast_20 animation tables,\n"
                "append these saved Water_20 slices, remap the copied A3dGENERAL\n"
                "and its channel-local indices, then point the game globals to the\n"
                "merged tables.  Existing Bast indices stay unchanged.\n"
            );
        }
    }
    else
    {
        fprintf(
            report,
            "This probe expects Water_20 first and Bast_20 second.\n"
        );
    }

    fflush(report);
    fclose(report);
    g_A3dDependencyReportStarted = true;

    char message[1024] = {};
    if (isWater)
    {
        sprintf_s(
            message,
            "WATER_20 AGLAGL DEPENDENCIES CAPTURED!\n\nNow press F2, wait until Bast_20 is playable, then press F7 again.\n\nReport:\n%s",
            A3D_DEPENDENCY_REPORT_FILE
        );
    }
    else if (isBast && g_A3dDonor301Captured)
    {
        sprintf_s(
            message,
            "A3D DEPENDENCY FOOTPRINT COMPLETE!\n\nWater donor slices were preserved and Bast_20 usage was measured.\n\nSend me:\n%s\n\nNo object was spawned.",
            A3D_DEPENDENCY_REPORT_FILE
        );
    }
    else
    {
        sprintf_s(
            message,
            "A3D dependency probe logged %s.\n\nUse Water_20 first, then Bast_20.\n\nReport:\n%s",
            levelName,
            A3D_DEPENDENCY_REPORT_FILE
        );
    }

    MessageBoxA(
        nullptr,
        message,
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | MB_ICONINFORMATION
    );
}


void RunA3dRegistryReadOnlyProbe()
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(
            GAM_g_stEngineStructure->szLevelName,
            "Bast_20"
        ) != 0
        )
    {
        return;
    }

    if (
        !g_AglaglPrepared ||
        g_RuntimeAglaglFamily == nullptr ||
        !g_RuntimeAglaglFamilyRegistered
        )
    {
        MessageBoxA(
            nullptr,
            "Preparation is not complete yet.\n\nUse F6 Stage 1, then F6 Stage 2, then F6 a THIRD time.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    HIE_tdstSuperObject* nativeSuper = nullptr;
    HIE_tdstEngineObject* nativeActor = nullptr;
    const char* nativeModel = nullptr;

    if (
        !FindBast20ControlSource(
            nativeSuper,
            nativeActor,
            nativeModel
        ) ||
        nativeActor == nullptr ||
        nativeActor->h3dData == nullptr
        )
    {
        MessageBoxA(
            nullptr,
            "Could not find the native Bast_20 control actor.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONERROR
        );
        return;
    }

    HIE_tdstState* nativeState =
        nativeActor->h3dData->h_CurrentState != nullptr
        ? nativeActor->h3dData->h_CurrentState
        : nativeActor->h3dData->h_InitialState;

    HIE_tdstState* foreignState =
        g_RuntimeAglaglFamily->stForStateArray.hFirstElementSta;

    GAM_tdstAnim3d* nativeAnimation =
        nativeState != nullptr
        ? nativeState->p_stAnim
        : nullptr;

    GAM_tdstAnim3d* foreignAnimation =
        foreignState != nullptr
        ? foreignState->p_stAnim
        : nullptr;

    FILE* report = nullptr;
    fopen_s(&report, A3D_REGISTRY_REPORT_FILE, "w");

    if (report == nullptr)
    {
        return;
    }

    uintptr_t imageBase = 0;
    size_t imageSize = 0;
    const bool imageOK =
        R2R_GetMainImageRange(imageBase, imageSize);

    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - MATCHED AGLAGL ANIMATION + VISUAL ONE-FRAME TEST\n"
        "============================================================\n\n"
        "Current Level   : %s\n"
        "Native control  : %s / %p\n"
        "Native State    : %p\n"
        "Foreign Family  : garde_tfeu / %p\n"
        "Foreign State   : %p\n"
        "Donor Arena     : %p .. %p (%zu bytes)\n"
        "Main image OK   : %s\n"
        "Main image      : %p .. %p (%zu bytes)\n\n"
        "SAFETY\n"
        "------------------------------------------------------------\n"
        "This h.7.9 probe does NOT spawn an object.\n"
        "It does NOT run a foreign animation through a normal frame.\n"
        "It only reads descriptors, process memory metadata, and code bytes.\n",
        GAM_g_stEngineStructure->szLevelName,
        nativeModel != nullptr ? nativeModel : "(unknown)",
        nativeActor,
        nativeState,
        g_RuntimeAglaglFamily,
        foreignState,
        g_CrossLevelArena,
        g_CrossLevelArena != nullptr
        ? g_CrossLevelArena + g_CrossLevelArenaSize
        : nullptr,
        g_CrossLevelArenaSize,
        imageOK ? "YES" : "NO",
        reinterpret_cast<void*>(imageBase),
        reinterpret_cast<void*>(
            imageBase + static_cast<uintptr_t>(imageSize)
            ),
        imageSize
    );

    R2R_ReportAnimationDescriptorFull(
        report,
        "NATIVE BAST_20 ANIMATION",
        nativeAnimation
    );

    R2R_ReportAnimationDescriptorFull(
        report,
        "FOREIGN AGLAGL ANIMATION",
        foreignAnimation
    );

    fprintf(
        report,
        "\nKNOWN EXPERIMENTAL RESULT\n"
        "------------------------------------------------------------\n"
        "B1 (native animation)                       : PASS\n"
        "E1 (native descriptor + foreign General)   : FREEZE\n"
        "E2 (foreign descriptor + native General)   : FREEZE\n"
        "D1 (foreign descriptor copied to HLM)      : FREEZE\n\n"
        "Goal of this report: locate code/data references involved in\n"
        "Rayman 2's animation player without executing a dangerous test.\n"
    );

    if (imageOK)
    {
        std::vector<uintptr_t> callTargets;

        R2R_ScanCodeRegionForA3dClues(
            report,
            "PLA_fn_bDoAnimPlayerForCharacter",
            reinterpret_cast<const void*>(
                PLA_fn_bDoAnimPlayerForCharacter
                ),
            0x1000,
            imageBase,
            imageSize,
            &callTargets
        );

        R2R_ScanCodeRegionForA3dClues(
            report,
            "PLA_fn_bSetNewState",
            reinterpret_cast<const void*>(
                PLA_fn_bSetNewState
                ),
            0x600,
            imageBase,
            imageSize,
            nullptr
        );

        fprintf(
            report,
            "\n============================================================\n"
            "FIRST-LEVEL CALL TARGET SCANS\n"
            "============================================================\n\n"
            "Unique direct calls collected from AnimPlayer: %zu\n"
            "Up to the first 48 in-image executable targets are scanned.\n",
            callTargets.size()
        );

        const size_t callScanCount =
            callTargets.size() < 48
            ? callTargets.size()
            : 48;

        for (size_t i = 0; i < callScanCount; i++)
        {
            char label[96] = {};

            sprintf_s(
                label,
                "AnimPlayer CALL #%zu @ %p",
                i,
                reinterpret_cast<void*>(callTargets[i])
            );

            R2R_ScanCodeRegionForA3dClues(
                report,
                label,
                reinterpret_cast<const void*>(callTargets[i]),
                0x300,
                imageBase,
                imageSize,
                nullptr
            );
        }
    }

    if (imageOK)
    {
        R2R_RunFocusedA3dResolverProbe(
            report,
            imageBase,
            imageSize
        );
    }

    fprintf(
        report,
        "\n============================================================\n"
        "END OF READ-ONLY PROBE\n"
        "============================================================\n\n"
        "No spawn was performed.\n"
        "No normal engine frame was intentionally exposed to foreign animation data.\n"
    );

    fflush(report);
    fclose(report);

    MessageBoxA(
        nullptr,
        "A3D RESOLVER PROBE COMPLETE!\n\nNo enemy was spawned and no dangerous animation frame was run.\n\nSend me:\nRayman2Randomizer_A3dResolver.txt",
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | MB_ICONINFORMATION
    );
}


// ============================================================
// h.7.17 - READ-ONLY AGLAGL 3D APPEARANCE AUDIT
//
// The native Bast_20 Piranha was visibly rendered in h.7.16, proving that
// the generic spawn/display route works. This probe therefore inspects only
// the Water_20 visual objects referenced by Aglagl's animation.
//
// Nothing is spawned and no game pointer is modified here.
// ============================================================

static const char* R2R_VisualPtrClass(const void* pointer)
{
    if (pointer == nullptr)
    {
        return "NULL";
    }

    if (PointerInsideCrossLevelArena(pointer))
    {
        return "WATER_COPY";
    }

    const uintptr_t address =
        reinterpret_cast<uintptr_t>(pointer);

    if (R2R_AddressReadable(address, 4))
    {
        return "READABLE_OTHER";
    }

    return "UNREADABLE";
}


// ============================================================
// h.7.19 - MATERIAL / TEXTURE READ-ONLY AUDIT
//
// Simple goal:
// follow a visible mesh -> its drawing element -> its material -> its texture.
// Nothing is changed in game memory.
// ============================================================

static void R2R_ReportTextureSummary(
    FILE* report,
    const char* prefix,
    void* texture
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "%s texture       : %p [%s]\n",
        prefix,
        texture,
        R2R_VisualPtrClass(texture)
    );

    if (
        texture == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(texture),
            0x46
        )
        )
    {
        fprintf(
            report,
            "%s texture data  : NOT READABLE\n",
            prefix
        );
        return;
    }

    // GLI_tdstTexture layout used by Rayman 2 PC.
    uint8_t raw[0xC6] = {};

    const size_t readableSize =
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(texture),
            sizeof(raw)
        )
        ? sizeof(raw)
        : static_cast<size_t>(0x46);

    if (!SafeReadMemory(
        texture,
        raw,
        readableSize
    ))
    {
        fprintf(
            report,
            "%s texture data  : READ FAILED\n",
            prefix
        );
        return;
    }

    int32_t available = 0;
    int32_t quality = 0;
    uint32_t bitmapRaw = 0;
    uint32_t paletteRaw = 0;
    uint32_t specRaw = 0;
    uint32_t caps = 0;
    uint16_t height = 0;
    uint16_t width = 0;
    uint16_t realHeight = 0;
    uint16_t realWidth = 0;
    uint32_t substitutionRaw = 0;

    std::memcpy(&available, raw + 0x00, 4);
    std::memcpy(&quality, raw + 0x04, 4);
    std::memcpy(&bitmapRaw, raw + 0x08, 4);
    std::memcpy(&paletteRaw, raw + 0x0C, 4);
    std::memcpy(&specRaw, raw + 0x10, 4);
    std::memcpy(&caps, raw + 0x14, 4);
    std::memcpy(&height, raw + 0x18, 2);
    std::memcpy(&width, raw + 0x1A, 2);
    std::memcpy(&realHeight, raw + 0x1C, 2);
    std::memcpy(&realWidth, raw + 0x1E, 2);
    std::memcpy(&substitutionRaw, raw + 0x40, 4);

    void* bitmap =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(bitmapRaw)
            );

    void* palette =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(paletteRaw)
            );

    void* spec =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(specRaw)
            );

    void* substitution =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(substitutionRaw)
            );

    fprintf(
        report,
        "%s available     : %d\n"
        "%s quality       : %d\n"
        "%s bitmap        : %p [%s]\n"
        "%s palette       : %p [%s]\n"
        "%s graphics data : %p [%s]\n"
        "%s size          : %ux%u (real %ux%u)\n"
        "%s caps          : 0x%08X\n"
        "%s substitution  : %p [%s]\n",
        prefix,
        available,
        prefix,
        quality,
        prefix,
        bitmap,
        R2R_VisualPtrClass(bitmap),
        prefix,
        palette,
        R2R_VisualPtrClass(palette),
        prefix,
        spec,
        R2R_VisualPtrClass(spec),
        prefix,
        static_cast<unsigned int>(width),
        static_cast<unsigned int>(height),
        static_cast<unsigned int>(realWidth),
        static_cast<unsigned int>(realHeight),
        prefix,
        static_cast<unsigned int>(caps),
        prefix,
        substitution,
        R2R_VisualPtrClass(substitution)
    );

    if (readableSize >= sizeof(raw))
    {
        char filename[129] = {};
        std::memcpy(
            filename,
            raw + 0x46,
            128
        );
        filename[128] = '\0';

        // Keep the report readable even if this was not a valid filename.
        for (int i = 0; i < 128; i++)
        {
            const unsigned char c =
                static_cast<unsigned char>(filename[i]);

            if (c == 0)
            {
                break;
            }

            if (c < 32 || c > 126)
            {
                filename[i] = '?';
            }
        }

        fprintf(
            report,
            "%s filename      : %s\n",
            prefix,
            filename[0] != '\0'
            ? filename
            : "(empty)"
        );
    }
}

static void R2R_ReportGeometryMaterials(
    FILE* report,
    const char* label,
    void* geometricObject
)
{
    if (
        report == nullptr ||
        geometricObject == nullptr
        )
    {
        return;
    }

    fprintf(
        report,
        "\nMATERIAL / TEXTURE CHECK FOR %s\n"
        "------------------------------------------------------------\n",
        label
    );

    // GEO_tdstGeometricObject:
    // +0x10 element-type array
    // +0x14 element-pointer array
    // +0x2C number of points (s16)
    // +0x2E number of elements (s16)
    uint8_t geo[0x44] = {};

    if (
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(geometricObject),
            sizeof(geo)
        ) ||
        !SafeReadMemory(
            geometricObject,
            geo,
            sizeof(geo)
        )
        )
    {
        fprintf(
            report,
            "geometry header : NOT READABLE\n"
        );
        return;
    }

    uint32_t elementTypesRaw = 0;
    uint32_t elementsRaw = 0;
    int16_t pointCount = 0;
    int16_t elementCount = 0;

    std::memcpy(
        &elementTypesRaw,
        geo + 0x10,
        4
    );

    std::memcpy(
        &elementsRaw,
        geo + 0x14,
        4
    );

    std::memcpy(
        &pointCount,
        geo + 0x2C,
        2
    );

    std::memcpy(
        &elementCount,
        geo + 0x2E,
        2
    );

    void* elementTypes =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(elementTypesRaw)
            );

    void* elements =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(elementsRaw)
            );

    fprintf(
        report,
        "points          : %d\n"
        "drawing parts   : %d\n"
        "part types      : %p [%s]\n"
        "part pointers   : %p [%s]\n",
        static_cast<int>(pointCount),
        static_cast<int>(elementCount),
        elementTypes,
        R2R_VisualPtrClass(elementTypes),
        elements,
        R2R_VisualPtrClass(elements)
    );

    if (
        elementCount <= 0 ||
        elementCount > 64 ||
        elementTypes == nullptr ||
        elements == nullptr
        )
    {
        fprintf(
            report,
            "drawing parts  : INVALID/EMPTY\n"
        );
        return;
    }

    for (int i = 0; i < elementCount; i++)
    {
        int16_t type = -1;
        uint32_t elementRaw = 0;

        const uintptr_t typeAddress =
            reinterpret_cast<uintptr_t>(elementTypes) +
            static_cast<uintptr_t>(i * 2);

        const uintptr_t elementAddress =
            reinterpret_cast<uintptr_t>(elements) +
            static_cast<uintptr_t>(i * 4);

        if (
            !R2R_AddressReadable(typeAddress, 2) ||
            !R2R_AddressReadable(elementAddress, 4) ||
            !SafeReadMemory(
                reinterpret_cast<void*>(typeAddress),
                &type,
                2
            ) ||
            !SafeReadMemory(
                reinterpret_cast<void*>(elementAddress),
                &elementRaw,
                4
            )
            )
        {
            fprintf(
                report,
                "part[%d]       : READ FAILED\n",
                i
            );
            continue;
        }

        void* element =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(elementRaw)
                );

        fprintf(
            report,
            "\npart[%d] type=%d pointer=%p [%s]\n",
            i,
            static_cast<int>(type),
            element,
            R2R_VisualPtrClass(element)
        );

        // Type 1 = indexed triangles: the normal solid mesh type.
        if (
            type != 1 ||
            element == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(element),
                32
            )
            )
        {
            fprintf(
                report,
                "  material check skipped for this part type.\n"
            );
            continue;
        }

        uint8_t triangleElement[32] = {};

        if (!SafeReadMemory(
            element,
            triangleElement,
            sizeof(triangleElement)
        ))
        {
            fprintf(
                report,
                "  triangle data : READ FAILED\n"
            );
            continue;
        }

        uint32_t gameMaterialRaw = 0;
        int16_t faceCount = 0;
        int16_t uvCount = 0;
        uint32_t facesRaw = 0;
        uint32_t faceUvRaw = 0;
        uint32_t normalsRaw = 0;
        uint32_t uvRaw = 0;

        std::memcpy(
            &gameMaterialRaw,
            triangleElement + 0x00,
            4
        );

        std::memcpy(
            &faceCount,
            triangleElement + 0x04,
            2
        );

        std::memcpy(
            &uvCount,
            triangleElement + 0x06,
            2
        );

        std::memcpy(
            &facesRaw,
            triangleElement + 0x08,
            4
        );

        std::memcpy(
            &faceUvRaw,
            triangleElement + 0x0C,
            4
        );

        std::memcpy(
            &normalsRaw,
            triangleElement + 0x10,
            4
        );

        std::memcpy(
            &uvRaw,
            triangleElement + 0x14,
            4
        );

        void* gameMaterial =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(gameMaterialRaw)
                );

        fprintf(
            report,
            "  faces         : %d\n"
            "  UV entries    : %d\n"
            "  faces ptr     : %p [%s]\n"
            "  face-UV ptr   : %p [%s]\n"
            "  normals ptr   : %p [%s]\n"
            "  UV ptr        : %p [%s]\n"
            "  game material : %p [%s]\n",
            static_cast<int>(faceCount),
            static_cast<int>(uvCount),
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(facesRaw)
                ),
            R2R_VisualPtrClass(
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(facesRaw)
                    )
            ),
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(faceUvRaw)
                ),
            R2R_VisualPtrClass(
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(faceUvRaw)
                    )
            ),
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(normalsRaw)
                ),
            R2R_VisualPtrClass(
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(normalsRaw)
                    )
            ),
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(uvRaw)
                ),
            R2R_VisualPtrClass(
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(uvRaw)
                    )
            ),
            gameMaterial,
            R2R_VisualPtrClass(gameMaterial)
        );

        if (
            gameMaterial == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(gameMaterial),
                16
            )
            )
        {
            fprintf(
                report,
                "  game material : NOT READABLE\n"
            );
            continue;
        }

        uint32_t gameMat[4] = {};

        if (!SafeReadMemory(
            gameMaterial,
            gameMat,
            sizeof(gameMat)
        ))
        {
            fprintf(
                report,
                "  game material : READ FAILED\n"
            );
            continue;
        }

        void* visualMaterial =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(gameMat[0])
                );

        void* mechanicsMaterial =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(gameMat[1])
                );

        void* collideMaterial =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(gameMat[3])
                );

        fprintf(
            report,
            "  visual mat    : %p [%s]\n"
            "  physics mat   : %p [%s]\n"
            "  sound handle  : 0x%08X\n"
            "  collide mat   : %p [%s]\n",
            visualMaterial,
            R2R_VisualPtrClass(visualMaterial),
            mechanicsMaterial,
            R2R_VisualPtrClass(mechanicsMaterial),
            static_cast<unsigned int>(gameMat[2]),
            collideMaterial,
            R2R_VisualPtrClass(collideMaterial)
        );

        if (
            visualMaterial == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(visualMaterial),
                0x4C
            )
            )
        {
            fprintf(
                report,
                "  visual mat    : NOT READABLE\n"
            );
            continue;
        }

        uint8_t visualMat[0x4C] = {};

        if (!SafeReadMemory(
            visualMaterial,
            visualMat,
            sizeof(visualMat)
        ))
        {
            fprintf(
                report,
                "  visual mat    : READ FAILED\n"
            );
            continue;
        }

        uint32_t materialType = 0;
        uint32_t textureRaw = 0;

        std::memcpy(
            &materialType,
            visualMat + 0x00,
            4
        );

        // In GLI_tdstMaterial, p_stTexture is at +0x48.
        std::memcpy(
            &textureRaw,
            visualMat + 0x48,
            4
        );

        void* texture =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(textureRaw)
                );

        fprintf(
            report,
            "  material type : 0x%08X\n",
            static_cast<unsigned int>(materialType)
        );

        R2R_ReportTextureSummary(
            report,
            "  ",
            texture
        );
    }
}

static void R2R_ReportPossiblePhysicalObject(
    FILE* report,
    const char* label,
    void* target
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n%s\n"
        "------------------------------------------------------------\n"
        "target          : %p [%s]\n",
        label,
        target,
        R2R_VisualPtrClass(target)
    );

    if (
        target == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(target),
            16
        )
        )
    {
        fprintf(report, "target header    : NOT READABLE\n");
        return;
    }

    uint32_t header[4] = {};
    if (!SafeReadMemory(target, header, sizeof(header)))
    {
        fprintf(report, "target header    : READ FAILED\n");
        return;
    }

    void* visualSet =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(header[0])
            );

    void* collideSet =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(header[1])
            );

    void* visualBounds =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(header[2])
            );

    void* fourth =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(header[3])
            );

    fprintf(
        report,
        "header +00 visual     : %p [%s]\n"
        "header +04 collision  : %p [%s]\n"
        "header +08 bounds     : %p [%s]\n"
        "header +0C other      : %p [%s]\n",
        visualSet,
        R2R_VisualPtrClass(visualSet),
        collideSet,
        R2R_VisualPtrClass(collideSet),
        visualBounds,
        R2R_VisualPtrClass(visualBounds),
        fourth,
        R2R_VisualPtrClass(fourth)
    );

    // Rayman 2 PC visual-set header:
    // +00 usually 0, +04 LOD count (u16), +06 visual type (u16),
    // +08 LOD-distance array, +0C array of LOD object pointers.
    if (
        visualSet == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(visualSet),
            24
        )
        )
    {
        fprintf(report, "visual header    : NOT READABLE\n");
        return;
    }

    uint8_t visualHeader[24] = {};
    if (!SafeReadMemory(
        visualSet,
        visualHeader,
        sizeof(visualHeader)
    ))
    {
        fprintf(report, "visual header    : READ FAILED\n");
        return;
    }

    uint32_t zeroOrFlags = 0;
    uint16_t lodCount = 0;
    uint16_t visualType = 0;
    uint32_t lodDistancesRaw = 0;
    uint32_t lodObjectArrayRaw = 0;
    uint32_t rliRaw = 0;
    uint32_t rliCountRaw = 0;

    std::memcpy(&zeroOrFlags, visualHeader + 0x00, 4);
    std::memcpy(&lodCount, visualHeader + 0x04, 2);
    std::memcpy(&visualType, visualHeader + 0x06, 2);
    std::memcpy(&lodDistancesRaw, visualHeader + 0x08, 4);
    std::memcpy(&lodObjectArrayRaw, visualHeader + 0x0C, 4);
    std::memcpy(&rliRaw, visualHeader + 0x10, 4);
    std::memcpy(&rliCountRaw, visualHeader + 0x14, 4);

    void* lodDistances =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(lodDistancesRaw)
            );

    void* lodObjectArray =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(lodObjectArrayRaw)
            );

    void* rli =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(rliRaw)
            );

    fprintf(
        report,
        "visual +00 value      : %u (0x%08X)\n"
        "visual +04 LOD count  : %u\n"
        "visual +06 type       : %u\n"
        "visual +08 distances  : %p [%s]\n"
        "visual +0C objects[]  : %p [%s]\n"
        "visual +10 RLI        : %p [%s]\n"
        "visual +14 RLI count? : %u\n",
        static_cast<unsigned int>(zeroOrFlags),
        static_cast<unsigned int>(zeroOrFlags),
        static_cast<unsigned int>(lodCount),
        static_cast<unsigned int>(visualType),
        lodDistances,
        R2R_VisualPtrClass(lodDistances),
        lodObjectArray,
        R2R_VisualPtrClass(lodObjectArray),
        rli,
        R2R_VisualPtrClass(rli),
        static_cast<unsigned int>(rliCountRaw)
    );

    if (
        lodCount == 0 ||
        lodCount > 32 ||
        lodObjectArray == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(lodObjectArray),
            4
        )
        )
    {
        fprintf(report, "first LOD object : unavailable\n");
        return;
    }

    uint32_t firstLodRaw = 0;
    if (!SafeReadMemory(
        lodObjectArray,
        &firstLodRaw,
        sizeof(firstLodRaw)
    ))
    {
        fprintf(report, "first LOD object : READ FAILED\n");
        return;
    }

    void* firstLod =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(firstLodRaw)
            );

    fprintf(
        report,
        "first LOD object : %p [%s]\n",
        firstLod,
        R2R_VisualPtrClass(firstLod)
    );

    // A geometric object begins with several pointer fields. We only
    // inspect them as raw values here; no game memory is changed.
    if (
        firstLod != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(firstLod),
            48
        )
        )
    {
        uint32_t geo[12] = {};

        if (SafeReadMemory(
            firstLod,
            geo,
            sizeof(geo)
        ))
        {
            fprintf(
                report,
                "first LOD raw pointer fields:\n"
            );

            for (int i = 0; i < 12; i++)
            {
                void* candidate =
                    reinterpret_cast<void*>(
                        static_cast<uintptr_t>(geo[i])
                        );

                fprintf(
                    report,
                    "  +0x%02X = %p [%s]\n",
                    i * 4,
                    candidate,
                    R2R_VisualPtrClass(candidate)
                );
            }
        }
    }

    R2R_ReportGeometryMaterials(
        report,
        label,
        firstLod
    );
}

void RunAglaglVisualReadOnlyAudit()
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(
            GAM_g_stEngineStructure->szLevelName,
            "Bast_20"
        ) != 0
        )
    {
        return;
    }

    if (
        !g_AglaglPrepared ||
        !g_RuntimeAglaglFamilyRegistered ||
        g_RuntimeAglaglFamily == nullptr ||
        !g_A3dDonor301Captured
        )
    {
        MessageBoxA(
            nullptr,
            "The Aglagl preparation is not finished yet.\n\n"
            "Restart Rayman 2 and repeat the normal Water_20 -> Bast_20 steps.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    HIE_tdstObjectsTablesList* table =
        g_RuntimeAglaglFamily->hDefaultObjectsTable;

    if (
        table == nullptr ||
        table->d_stObjectsTable == nullptr
        )
    {
        MessageBoxA(
            nullptr,
            "I could not read Aglagl's 3D-object list.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONERROR
        );
        return;
    }

    HIE_tdstSuperObject* nativeSuper = nullptr;
    HIE_tdstEngineObject* nativeActor = nullptr;
    const char* nativeModel = nullptr;

    FindBast20ControlSource(
        nativeSuper,
        nativeActor,
        nativeModel
    );

    FILE* report = nullptr;
    fopen_s(
        &report,
        AGLAGL_VISUAL_AUDIT_REPORT_FILE,
        "w"
    );

    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - AGLAGL MATERIAL / TEXTURE READ-ONLY AUDIT\n"
        "============================================================\n\n"
        "RESULT ALREADY PROVEN\n"
        "------------------------------------------------------------\n"
        "Bast_20 native control object: VISIBLE (user saw a Piranha)\n"
        "Aglagl matched animation test: PASS but visually invisible\n\n"
        "WHAT THIS TEST DOES\n"
        "------------------------------------------------------------\n"
        "It checks the 3D pieces already found in h.7.18, then follows\n"
        "their drawing materials and textures.\n"
        "No object is spawned and no game memory is changed.\n\n"
        "Aglagl object-table entries : %u\n"
        "Aglagl family channels      : %lu\n"
        "Object table                : %p [%s]\n"
        "Object entries              : %p [%s]\n\n",
        static_cast<unsigned int>(table->uwNumberOfElement),
        g_RuntimeAglaglFamily->ulNumberOfChannels,
        table,
        R2R_VisualPtrClass(table),
        table->d_stObjectsTable,
        R2R_VisualPtrClass(table->d_stObjectsTable)
    );

    // IMPORTANT h.7.18 correction:
    // On Rayman 2 PC, a 6-byte NTTO record stores:
    //   +0x00 flags
    //   +0x02 object-table index
    //   +0x04/+0x05 two extra bytes
    //
    // h.7.17 accidentally read the first two WORDs in the opposite order.
    // That is why it printed impossible object index 2048. The real Aglagl
    // object indexes are small values inside its 28-entry table.
    std::vector<uint16_t> usedObjectIndices;

    fprintf(
        report,
        "OBJECTS ACTUALLY REQUESTED BY AGLAGL ANIMATION\n"
        "------------------------------------------------------------\n"
        "h.7.18 FIX: NTTO flags/index order corrected for Rayman 2 PC.\n\n"
    );

    const size_t nttoCount =
        g_A3dDonorNTTO.size() / 6;

    for (size_t i = 0; i < nttoCount; i++)
    {
        const uint8_t* raw =
            g_A3dDonorNTTO.data() + i * 6;

        uint16_t flags = 0;
        uint16_t objectIndex = 0;

        std::memcpy(
            &flags,
            raw + 0,
            2
        );

        std::memcpy(
            &objectIndex,
            raw + 2,
            2
        );

        const uint8_t extra0 = raw[4];
        const uint8_t extra1 = raw[5];

        bool alreadySeen = false;

        for (size_t j = 0; j < usedObjectIndices.size(); j++)
        {
            if (usedObjectIndices[j] == objectIndex)
            {
                alreadySeen = true;
                break;
            }
        }

        if (!alreadySeen)
        {
            usedObjectIndices.push_back(objectIndex);
        }

        fprintf(
            report,
            "NTTO[%zu] raw=%02X %02X %02X %02X %02X %02X"
            " -> flags=0x%04X, object-table index=%u, extra=%u/%u\n",
            i,
            static_cast<unsigned int>(raw[0]),
            static_cast<unsigned int>(raw[1]),
            static_cast<unsigned int>(raw[2]),
            static_cast<unsigned int>(raw[3]),
            static_cast<unsigned int>(raw[4]),
            static_cast<unsigned int>(raw[5]),
            static_cast<unsigned int>(flags),
            static_cast<unsigned int>(objectIndex),
            static_cast<unsigned int>(extra0),
            static_cast<unsigned int>(extra1)
        );
    }

    fprintf(
        report,
        "\nUnique object indexes used by this animation: "
    );

    for (size_t i = 0; i < usedObjectIndices.size(); i++)
    {
        fprintf(
            report,
            "%s%u",
            i == 0 ? "" : ", ",
            static_cast<unsigned int>(usedObjectIndices[i])
        );
    }

    fprintf(report, "\n");

    fprintf(
        report,
        "\nDEEP CHECK OF THE USED AGLAGL 3D OBJECTS\n"
        "============================================================\n"
    );

    for (size_t i = 0; i < usedObjectIndices.size(); i++)
    {
        const uint16_t index =
            usedObjectIndices[i];

        if (index >= table->uwNumberOfElement)
        {
            fprintf(
                report,
                "\nObject index %u is OUTSIDE the table (count=%u).\n",
                static_cast<unsigned int>(index),
                static_cast<unsigned int>(table->uwNumberOfElement)
            );

            continue;
        }

        HIE_tdstObjectsTableElement element = {};

        if (!SafeReadMemory(
            table->d_stObjectsTable + index,
            &element,
            sizeof(element)
        ))
        {
            fprintf(
                report,
                "\nObject index %u could not be read.\n",
                static_cast<unsigned int>(index)
            );

            continue;
        }

        char label[128] = {};

        sprintf_s(
            label,
            "Aglagl object-table[%u] channel=%lu type=%u",
            static_cast<unsigned int>(index),
            element.ulChannelNumber,
            static_cast<unsigned int>(element.uwTypeOfTarget)
        );

        fprintf(
            report,
            "\nentry metadata:\n"
            "  custom zoom : %p [%s]\n"
            "  target      : %p [%s]\n"
            "  channel     : %lu\n"
            "  target type : %u\n"
            "  phoneme     : %u\n"
            "  intensity   : %u\n"
            "  expression  : %u\n",
            element.p_stCustomZoom,
            R2R_VisualPtrClass(element.p_stCustomZoom),
            element.hTarget,
            R2R_VisualPtrClass(element.hTarget),
            element.ulChannelNumber,
            static_cast<unsigned int>(element.uwTypeOfTarget),
            static_cast<unsigned int>(element.ucPhoneme),
            static_cast<unsigned int>(element.ucIntensity),
            static_cast<unsigned int>(element.ucExpression)
        );

        R2R_ReportPossiblePhysicalObject(
            report,
            label,
            element.hTarget
        );
    }

    // Also log one known-visible Bast object for comparison.
    if (
        nativeActor != nullptr &&
        nativeActor->h3dData != nullptr
        )
    {
        HIE_tdstObjectsTablesList* nativeTable =
            nativeActor->h3dData->h_CurrentObjectsTable != nullptr
            ? nativeActor->h3dData->h_CurrentObjectsTable
            : nativeActor->h3dData->h_InitialObjectsTable;

        if (
            nativeTable != nullptr &&
            nativeTable->d_stObjectsTable != nullptr &&
            nativeTable->uwNumberOfElement > 0
            )
        {
            HIE_tdstObjectsTableElement nativeElement = {};

            if (SafeReadMemory(
                nativeTable->d_stObjectsTable,
                &nativeElement,
                sizeof(nativeElement)
            ))
            {
                fprintf(
                    report,
                    "\nKNOWN-VISIBLE BAST_20 CONTROL FOR COMPARISON\n"
                    "============================================================\n"
                    "Model name  : %s\n"
                    "Table count : %u\n"
                    "Entry[0] channel=%lu type=%u target=%p [%s]\n",
                    nativeModel != nullptr ? nativeModel : "(unknown)",
                    static_cast<unsigned int>(nativeTable->uwNumberOfElement),
                    nativeElement.ulChannelNumber,
                    static_cast<unsigned int>(nativeElement.uwTypeOfTarget),
                    nativeElement.hTarget,
                    R2R_VisualPtrClass(nativeElement.hTarget)
                );

                R2R_ReportPossiblePhysicalObject(
                    report,
                    "Known-visible Bast_20 control object-table[0]",
                    nativeElement.hTarget
                );
            }
        }
    }

    fprintf(
        report,
        "\n============================================================\n"
        "AUDIT COMPLETE\n"
        "============================================================\n"
        "No enemy was spawned.\n"
        "No pointer was redirected.\n"
        "No game memory was modified.\n"
    );

    fflush(report);
    fclose(report);

    MessageBoxA(
        nullptr,
        "3D APPEARANCE CHECK COMPLETE!\n\n"
        "Nothing was spawned this time.\n\n"
        "Send me:\nRayman2Randomizer_AglaglMaterialAudit.txt",
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | MB_ICONINFORMATION
    );
}


// ============================================================
// h.7.20 - TEMPORARY KNOWN-GOOD TEXTURE TEST
//
// Simple idea:
// Aglagl's geometry/materials are present, but his copied texture objects
// may still contain Water_20-only graphics-card data. For this test only,
// every Aglagl visual material is pointed at ONE known-visible Bast_20
// Piranha texture. If Aglagl becomes visible, the missing piece is the
// runtime texture/GPU resource. If he stays invisible, the problem is
// elsewhere.
//
// Only the private copied Water_20 data is patched. Native Bast data is not.
// ============================================================

static void* R2R_FindFirstTextureFromTarget(void* target)
{
    if (
        target == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(target),
            16
        )
        )
    {
        return nullptr;
    }

    uint32_t targetHeader[4] = {};
    if (!SafeReadMemory(target, targetHeader, sizeof(targetHeader)))
    {
        return nullptr;
    }

    void* visualSet =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(targetHeader[0])
            );

    if (
        visualSet == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(visualSet),
            16
        )
        )
    {
        return nullptr;
    }

    uint8_t visualHeader[16] = {};
    if (!SafeReadMemory(
        visualSet,
        visualHeader,
        sizeof(visualHeader)
    ))
    {
        return nullptr;
    }

    uint16_t lodCount = 0;
    uint32_t lodArrayRaw = 0;

    std::memcpy(&lodCount, visualHeader + 0x04, 2);
    std::memcpy(&lodArrayRaw, visualHeader + 0x0C, 4);

    if (lodCount == 0 || lodCount > 32 || lodArrayRaw == 0)
    {
        return nullptr;
    }

    void* lodArray =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(lodArrayRaw)
            );

    if (
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(lodArray),
            4
        )
        )
    {
        return nullptr;
    }

    uint32_t geoRaw = 0;
    if (!SafeReadMemory(lodArray, &geoRaw, 4) || geoRaw == 0)
    {
        return nullptr;
    }

    void* geo =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(geoRaw)
            );

    if (
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(geo),
            0x30
        )
        )
    {
        return nullptr;
    }

    uint8_t geoHeader[0x30] = {};
    if (!SafeReadMemory(geo, geoHeader, sizeof(geoHeader)))
    {
        return nullptr;
    }

    uint32_t typesRaw = 0;
    uint32_t elementsRaw = 0;
    int16_t elementCount = 0;

    std::memcpy(&typesRaw, geoHeader + 0x10, 4);
    std::memcpy(&elementsRaw, geoHeader + 0x14, 4);
    std::memcpy(&elementCount, geoHeader + 0x2E, 2);

    if (
        typesRaw == 0 ||
        elementsRaw == 0 ||
        elementCount <= 0 ||
        elementCount > 64
        )
    {
        return nullptr;
    }

    for (int i = 0; i < elementCount; i++)
    {
        int16_t type = -1;
        uint32_t elementRaw = 0;

        const uintptr_t typeAddress =
            static_cast<uintptr_t>(typesRaw) +
            static_cast<uintptr_t>(i * 2);

        const uintptr_t elementAddress =
            static_cast<uintptr_t>(elementsRaw) +
            static_cast<uintptr_t>(i * 4);

        if (
            !R2R_AddressReadable(typeAddress, 2) ||
            !R2R_AddressReadable(elementAddress, 4) ||
            !SafeReadMemory(
                reinterpret_cast<void*>(typeAddress),
                &type,
                2
            ) ||
            !SafeReadMemory(
                reinterpret_cast<void*>(elementAddress),
                &elementRaw,
                4
            )
            )
        {
            continue;
        }

        if (type != 1 || elementRaw == 0)
        {
            continue;
        }

        void* element =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(elementRaw)
                );

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(element),
                4
            )
            )
        {
            continue;
        }

        uint32_t gameMaterialRaw = 0;
        if (!SafeReadMemory(element, &gameMaterialRaw, 4) || gameMaterialRaw == 0)
        {
            continue;
        }

        void* gameMaterial =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(gameMaterialRaw)
                );

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(gameMaterial),
                4
            )
            )
        {
            continue;
        }

        uint32_t visualMaterialRaw = 0;
        if (!SafeReadMemory(
            gameMaterial,
            &visualMaterialRaw,
            4
        ) || visualMaterialRaw == 0)
        {
            continue;
        }

        void* visualMaterial =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(visualMaterialRaw)
                );

        const uintptr_t textureField =
            reinterpret_cast<uintptr_t>(visualMaterial) +
            0x48;

        if (!R2R_AddressReadable(textureField, 4))
        {
            continue;
        }

        uint32_t textureRaw = 0;
        if (!SafeReadMemory(
            reinterpret_cast<void*>(textureField),
            &textureRaw,
            4
        ))
        {
            continue;
        }

        if (textureRaw != 0)
        {
            return reinterpret_cast<void*>(
                static_cast<uintptr_t>(textureRaw)
                );
        }
    }

    return nullptr;
}



// ============================================================
// h.7.34 - CAPTURE THE REAL BLUE AGLAGL VARIANT IN WATER_20
//
// The cross-level import is now visually working, but it uses the orange
// default appearance. This read-only capture asks the REAL live Water_20
// boss which ObjectsTable he is using while he is blue.
//
// We store only the TABLE INDEX, not the Water_20 pointer itself. Later,
// after Bast_20 rebuilds the donor Family in our persistent arena, we select
// the table at that same index. This keeps the cross-level pointer-safe.
// ============================================================


static int R2R_GetSafeFamilyTableCount(
    HIE_tdstFamilyList* family
)
{
    if (
        family == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(family),
            sizeof(HIE_tdstFamilyList)
        )
        )
    {
        return 0;
    }

    const long rawCount =
        family->stForObjectsTablesList.lNbOfElementsSta;

    if (rawCount <= 0 || rawCount > 64)
    {
        return 0;
    }

    return static_cast<int>(rawCount);
}

static int R2R_GetObjectTableIndexInFamily(
    HIE_tdstFamilyList* family,
    HIE_tdstObjectsTablesList* wanted
)
{
    if (family == nullptr || wanted == nullptr)
    {
        return -1;
    }

    const int safeCount =
        R2R_GetSafeFamilyTableCount(family);

    if (safeCount <= 0)
    {
        return -1;
    }

    HIE_tdstObjectsTablesList* table =
        family->stForObjectsTablesList.hFirstElementSta;

    for (int index = 0; index < safeCount; index++)
    {
        if (
            table == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(table),
                sizeof(HIE_tdstObjectsTablesList)
            )
            )
        {
            return -1;
        }

        if (table == wanted)
        {
            return index;
        }

        HIE_tdstObjectsTablesList* next =
            table->hNextBrotherSta;

        if (next == table)
        {
            return -1;
        }

        table = next;
    }

    return -1;
}

static HIE_tdstObjectsTablesList* R2R_GetObjectTableByIndex(
    HIE_tdstFamilyList* family,
    int wantedIndex
)
{
    if (
        family == nullptr ||
        wantedIndex < 0
        )
    {
        return nullptr;
    }

    const int safeCount =
        R2R_GetSafeFamilyTableCount(family);

    if (
        safeCount <= 0 ||
        wantedIndex >= safeCount
        )
    {
        return nullptr;
    }

    HIE_tdstObjectsTablesList* table =
        family->stForObjectsTablesList.hFirstElementSta;

    for (int index = 0; index < safeCount; index++)
    {
        if (
            table == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(table),
                sizeof(HIE_tdstObjectsTablesList)
            )
            )
        {
            return nullptr;
        }

        if (index == wantedIndex)
        {
            return table;
        }

        HIE_tdstObjectsTablesList* next =
            table->hNextBrotherSta;

        if (next == table)
        {
            return nullptr;
        }

        table = next;
    }

    return nullptr;
}

// Bounded actor search used ONLY by the h.7.34b F3 capture.
// The old generic recursive search is left untouched because other tests
// already rely on it, but F3 must never be allowed to walk forever.
static bool R2R_FindActorByModelBounded(
    HIE_tdstSuperObject* root,
    const char* wantedModel,
    HIE_tdstSuperObject*& outSuperObject,
    HIE_tdstEngineObject*& outActor,
    int depth,
    unsigned int& remainingNodes
)
{
    if (
        root == nullptr ||
        wantedModel == nullptr ||
        depth > 64 ||
        remainingNodes == 0 ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(root),
            sizeof(HIE_tdstSuperObject)
        )
        )
    {
        return false;
    }

    remainingNodes--;

    if (root->ulType == HIE_C_Type_Actor)
    {
        HIE_tdstEngineObject* actor =
            HIE_M_hSuperObjectGetActor(root);

        if (
            actor != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(actor),
                sizeof(HIE_tdstEngineObject)
            ) &&
            actor->hStandardGame != nullptr
            )
        {
            const char* model =
                HIE_fn_szGetObjectModelName(root);

            if (
                model != nullptr &&
                _stricmp(model, wantedModel) == 0
                )
            {
                outSuperObject = root;
                outActor = actor;
                return true;
            }
        }
    }

    HIE_tdstSuperObject* child =
        root->hFirstElementDyn;

    unsigned int siblingGuard = 0;

    while (
        child != nullptr &&
        siblingGuard < 512 &&
        remainingNodes > 0
        )
    {
        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(child),
                sizeof(HIE_tdstSuperObject)
            )
            )
        {
            break;
        }

        HIE_tdstSuperObject* next =
            child->hNextBrotherDyn;

        if (
            R2R_FindActorByModelBounded(
                child,
                wantedModel,
                outSuperObject,
                outActor,
                depth + 1,
                remainingNodes
            )
            )
        {
            return true;
        }

        if (next == child)
        {
            break;
        }

        child = next;
        siblingGuard++;
    }

    return false;
}

static void R2R_ReportTableTextureSummary(
    FILE* report,
    const char* label,
    HIE_tdstObjectsTablesList* table
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n%s\n"
        "------------------------------------------------------------\n"
        "Table pointer : %p\n",
        label != nullptr ? label : "(table)",
        table
    );

    if (
        table == nullptr ||
        table->d_stObjectsTable == nullptr
        )
    {
        fprintf(report, "Table is NULL / unreadable.\n");
        return;
    }

    fprintf(
        report,
        "Entry count   : %u\n",
        static_cast<unsigned int>(
            table->uwNumberOfElement
            )
    );

    const unsigned int maxEntries =
        table->uwNumberOfElement < 64
        ? table->uwNumberOfElement
        : 64;

    for (unsigned int i = 0; i < maxEntries; i++)
    {
        HIE_tdstObjectsTableElement entry = {};

        if (
            !SafeReadMemory(
                table->d_stObjectsTable + i,
                &entry,
                sizeof(entry)
            )
            )
        {
            fprintf(
                report,
                "[%u] entry read failed\n",
                i
            );
            continue;
        }

        GLI_tdstTexture* texture =
            reinterpret_cast<GLI_tdstTexture*>(
                R2R_FindFirstTextureFromTarget(
                    entry.hTarget
                )
                );

        if (
            texture == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(texture),
                sizeof(GLI_tdstTexture)
            )
            )
        {
            fprintf(
                report,
                "[%u] ch=%lu type=%u target=%p texture=(none)\n",
                i,
                entry.ulChannelNumber,
                static_cast<unsigned int>(
                    entry.uwTypeOfTarget
                    ),
                entry.hTarget
            );
            continue;
        }

        GLI_tdstTexture copy = {};

        if (
            !SafeReadMemory(
                texture,
                &copy,
                sizeof(copy)
            )
            )
        {
            fprintf(
                report,
                "[%u] texture read failed @ %p\n",
                i,
                texture
            );
            continue;
        }

        const char* substitutionName = "(none)";

        GLI_tdstTexture substitution = {};

        if (
            copy.p_TextureOfSubstitution != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    copy.p_TextureOfSubstitution
                    ),
                sizeof(GLI_tdstTexture)
            ) &&
            SafeReadMemory(
                copy.p_TextureOfSubstitution,
                &substitution,
                sizeof(substitution)
            )
            )
        {
            substitutionName =
                substitution.szFileName;
        }

        fprintf(
            report,
            "[%u] ch=%lu type=%u target=%p\n"
            "     texture=%p name=%s\n"
            "     available=%d GPU=%p substitution=%p (%s)\n",
            i,
            entry.ulChannelNumber,
            static_cast<unsigned int>(
                entry.uwTypeOfTarget
                ),
            entry.hTarget,
            texture,
            copy.szFileName,
            static_cast<int>(
                copy.bIsAvailable
                ),
            copy.p_stSpecParam,
            copy.p_TextureOfSubstitution,
            substitutionName
        );
    }
}



static void R2R_ReportRawObjectTable(
    FILE* report,
    const char* label,
    HIE_tdstObjectsTablesList* table
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n%s\n"
        "============================================================\n"
        "table               : %p\n",
        label != nullptr ? label : "(table)",
        table
    );

    if (
        table == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(table),
            sizeof(HIE_tdstObjectsTablesList)
        )
        )
    {
        fprintf(report, "TABLE NOT READABLE\n");
        return;
    }

    HIE_tdstObjectsTablesList copy = {};

    if (!SafeReadMemory(table, &copy, sizeof(copy)))
    {
        fprintf(report, "TABLE READ FAILED\n");
        return;
    }

    fprintf(
        report,
        "next                 : %p\n"
        "d_stObjectsTable     : %p\n"
        "d_stInitObjectsTable : %p\n"
        "entry count          : %u\n"
        "wZDxUsed             : %u\n",
        copy.hNextBrotherSta,
        copy.d_stObjectsTable,
        copy.d_stInitObjectsTable,
        static_cast<unsigned int>(copy.uwNumberOfElement),
        static_cast<unsigned int>(copy.wZDxUsed)
    );

    if (
        copy.d_stObjectsTable == nullptr ||
        copy.uwNumberOfElement == 0 ||
        copy.uwNumberOfElement > 64
        )
    {
        fprintf(report, "NO SAFE CURRENT ENTRY ARRAY\n");
        return;
    }

    fprintf(
        report,
        "\nCURRENT ENTRY ARRAY\n"
        "idx  customZoom  target      channel type phon intens expr\n"
        "------------------------------------------------------------\n"
    );

    for (
        unsigned int i = 0;
        i < static_cast<unsigned int>(copy.uwNumberOfElement);
        i++
        )
    {
        HIE_tdstObjectsTableElement entry = {};

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    copy.d_stObjectsTable + i
                    ),
                sizeof(entry)
            ) ||
            !SafeReadMemory(
                copy.d_stObjectsTable + i,
                &entry,
                sizeof(entry)
            )
            )
        {
            fprintf(report, "%02u   ENTRY READ FAILED\n", i);
            continue;
        }

        fprintf(
            report,
            "%02u   %p  %p  %7lu %4u %4u %5u %4u\n",
            i,
            entry.p_stCustomZoom,
            entry.hTarget,
            entry.ulChannelNumber,
            static_cast<unsigned int>(entry.uwTypeOfTarget),
            static_cast<unsigned int>(entry.ucPhoneme),
            static_cast<unsigned int>(entry.ucIntensity),
            static_cast<unsigned int>(entry.ucExpression)
        );
    }

    if (
        copy.d_stInitObjectsTable != nullptr &&
        copy.d_stInitObjectsTable != copy.d_stObjectsTable
        )
    {
        fprintf(
            report,
            "\nINIT ENTRY ARRAY\n"
            "idx  customZoom  target      channel type phon intens expr\n"
            "------------------------------------------------------------\n"
        );

        for (
            unsigned int i = 0;
            i < static_cast<unsigned int>(copy.uwNumberOfElement);
            i++
            )
        {
            HIE_tdstObjectsTableElement entry = {};

            if (
                !R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(
                        copy.d_stInitObjectsTable + i
                        ),
                    sizeof(entry)
                ) ||
                !SafeReadMemory(
                    copy.d_stInitObjectsTable + i,
                    &entry,
                    sizeof(entry)
                )
                )
            {
                fprintf(report, "%02u   ENTRY READ FAILED\n", i);
                continue;
            }

            fprintf(
                report,
                "%02u   %p  %p  %7lu %4u %4u %5u %4u\n",
                i,
                entry.p_stCustomZoom,
                entry.hTarget,
                entry.ulChannelNumber,
                static_cast<unsigned int>(entry.uwTypeOfTarget),
                static_cast<unsigned int>(entry.ucPhoneme),
                static_cast<unsigned int>(entry.ucIntensity),
                static_cast<unsigned int>(entry.ucExpression)
            );
        }
    }
}

static void R2R_CompareCurrentAndDefaultTables(
    FILE* report,
    HIE_tdstObjectsTablesList* currentTable,
    HIE_tdstObjectsTablesList* defaultTable
)
{
    if (
        report == nullptr ||
        currentTable == nullptr ||
        defaultTable == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(currentTable),
            sizeof(HIE_tdstObjectsTablesList)
        ) ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(defaultTable),
            sizeof(HIE_tdstObjectsTablesList)
        )
        )
    {
        return;
    }

    HIE_tdstObjectsTablesList current = {};
    HIE_tdstObjectsTablesList def = {};

    if (
        !SafeReadMemory(currentTable, &current, sizeof(current)) ||
        !SafeReadMemory(defaultTable, &def, sizeof(def))
        )
    {
        return;
    }

    const unsigned int count =
        current.uwNumberOfElement < def.uwNumberOfElement
        ? current.uwNumberOfElement
        : def.uwNumberOfElement;

    if (
        count == 0 ||
        count > 64 ||
        current.d_stObjectsTable == nullptr ||
        def.d_stObjectsTable == nullptr
        )
    {
        return;
    }

    unsigned int sameTargets = 0;
    unsigned int differentTargets = 0;
    unsigned int otherDifferences = 0;

    fprintf(
        report,
        "\nCURRENT BLUE vs FAMILY DEFAULT\n"
        "============================================================\n"
        "Comparing %u entries only. No geometry/material traversal.\n\n",
        count
    );

    for (unsigned int i = 0; i < count; i++)
    {
        HIE_tdstObjectsTableElement a = {};
        HIE_tdstObjectsTableElement b = {};

        if (
            !SafeReadMemory(
                current.d_stObjectsTable + i,
                &a,
                sizeof(a)
            ) ||
            !SafeReadMemory(
                def.d_stObjectsTable + i,
                &b,
                sizeof(b)
            )
            )
        {
            fprintf(report, "[%02u] READ FAILED\n", i);
            continue;
        }

        const bool sameTarget =
            a.hTarget == b.hTarget;

        if (sameTarget)
        {
            sameTargets++;
        }
        else
        {
            differentTargets++;
        }

        const bool otherSame =
            a.p_stCustomZoom == b.p_stCustomZoom &&
            a.ulChannelNumber == b.ulChannelNumber &&
            a.uwTypeOfTarget == b.uwTypeOfTarget &&
            a.ucPhoneme == b.ucPhoneme &&
            a.ucIntensity == b.ucIntensity &&
            a.ucExpression == b.ucExpression;

        if (!otherSame)
        {
            otherDifferences++;
        }

        fprintf(
            report,
            "[%02u] target BLUE=%p DEFAULT=%p  %s\n",
            i,
            a.hTarget,
            b.hTarget,
            sameTarget ? "SAME" : "DIFFERENT"
        );
    }

    fprintf(
        report,
        "\nSUMMARY\n"
        "------------------------------------------------------------\n"
        "Same hTarget pointers       : %u\n"
        "Different hTarget pointers  : %u\n"
        "Other entry differences     : %u\n"
        "Current d_stObjectsTable    : %p\n"
        "Default d_stObjectsTable    : %p\n"
        "Current d_stInitObjectsTable: %p\n"
        "Default d_stInitObjectsTable: %p\n",
        sameTargets,
        differentTargets,
        otherDifferences,
        current.d_stObjectsTable,
        def.d_stObjectsTable,
        current.d_stInitObjectsTable,
        def.d_stInitObjectsTable
    );
}



static void R2R_ReportBlueDefaultVisualTextureDiff(
    FILE* report,
    HIE_tdstObjectsTablesList* blueTable,
    HIE_tdstObjectsTablesList* defaultTable
)
{
    if (
        report == nullptr ||
        blueTable == nullptr ||
        defaultTable == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(blueTable),
            sizeof(HIE_tdstObjectsTablesList)
        ) ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(defaultTable),
            sizeof(HIE_tdstObjectsTablesList)
        )
        )
    {
        return;
    }

    HIE_tdstObjectsTablesList blue = {};
    HIE_tdstObjectsTablesList def = {};

    if (
        !SafeReadMemory(blueTable, &blue, sizeof(blue)) ||
        !SafeReadMemory(defaultTable, &def, sizeof(def))
        )
    {
        return;
    }

    const unsigned int count =
        blue.uwNumberOfElement < def.uwNumberOfElement
        ? blue.uwNumberOfElement
        : def.uwNumberOfElement;

    if (
        count == 0 ||
        count > 64 ||
        blue.d_stObjectsTable == nullptr ||
        def.d_stObjectsTable == nullptr
        )
    {
        return;
    }

    unsigned int sameFirstTextureName = 0;
    unsigned int differentFirstTextureName = 0;
    unsigned int unreadableTexture = 0;
    unsigned int sameFirstGeo = 0;
    unsigned int differentFirstGeo = 0;

    fprintf(
        report,
        "\nBLUE vs DEFAULT - SAFE VISUAL/TEXTURE SNAPSHOT\n"
        "============================================================\n"
        "Only bounded, direct pointers are read here. No linked-list traversal.\n"
        "For each of the 28 entries we inspect:\n"
        "  PhysicalObject -> VisualSet -> first LOD geometric object\n"
        "  and the first texture found by the already-proven visual audit.\n\n"
    );

    for (unsigned int i = 0; i < count; i++)
    {
        HIE_tdstObjectsTableElement blueEntry = {};
        HIE_tdstObjectsTableElement defEntry = {};

        if (
            !SafeReadMemory(
                blue.d_stObjectsTable + i,
                &blueEntry,
                sizeof(blueEntry)
            ) ||
            !SafeReadMemory(
                def.d_stObjectsTable + i,
                &defEntry,
                sizeof(defEntry)
            )
            )
        {
            fprintf(
                report,
                "[%02u] ENTRY READ FAILED\n\n",
                i
            );
            continue;
        }

        PO_tdstPhysicalObject bluePO = {};
        PO_tdstPhysicalObject defPO = {};

        bool bluePOOK =
            blueEntry.hTarget != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(blueEntry.hTarget),
                sizeof(PO_tdstPhysicalObject)
            ) &&
            SafeReadMemory(
                blueEntry.hTarget,
                &bluePO,
                sizeof(bluePO)
            );

        bool defPOOK =
            defEntry.hTarget != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(defEntry.hTarget),
                sizeof(PO_tdstPhysicalObject)
            ) &&
            SafeReadMemory(
                defEntry.hTarget,
                &defPO,
                sizeof(defPO)
            );

        GEO_tdstGeometricObject* blueFirstGeo = nullptr;
        GEO_tdstGeometricObject* defFirstGeo = nullptr;

        if (
            bluePOOK &&
            bluePO.hVisualSet != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(bluePO.hVisualSet),
                sizeof(GEO_tdstVisualSet)
            )
            )
        {
            GEO_tdstVisualSet visual = {};

            if (
                SafeReadMemory(
                    bluePO.hVisualSet,
                    &visual,
                    sizeof(visual)
                ) &&
                visual.xNbLodDefinitions > 0 &&
                visual.xNbLodDefinitions <= 32 &&
                visual.d_p_stLodDefinitions != nullptr &&
                R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(
                        visual.d_p_stLodDefinitions
                        ),
                    sizeof(GEO_tdstGeometricObject*)
                )
                )
            {
                SafeReadMemory(
                    visual.d_p_stLodDefinitions,
                    &blueFirstGeo,
                    sizeof(blueFirstGeo)
                );
            }
        }

        if (
            defPOOK &&
            defPO.hVisualSet != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(defPO.hVisualSet),
                sizeof(GEO_tdstVisualSet)
            )
            )
        {
            GEO_tdstVisualSet visual = {};

            if (
                SafeReadMemory(
                    defPO.hVisualSet,
                    &visual,
                    sizeof(visual)
                ) &&
                visual.xNbLodDefinitions > 0 &&
                visual.xNbLodDefinitions <= 32 &&
                visual.d_p_stLodDefinitions != nullptr &&
                R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(
                        visual.d_p_stLodDefinitions
                        ),
                    sizeof(GEO_tdstGeometricObject*)
                )
                )
            {
                SafeReadMemory(
                    visual.d_p_stLodDefinitions,
                    &defFirstGeo,
                    sizeof(defFirstGeo)
                );
            }
        }

        if (
            blueFirstGeo != nullptr &&
            defFirstGeo != nullptr
            )
        {
            if (blueFirstGeo == defFirstGeo)
            {
                sameFirstGeo++;
            }
            else
            {
                differentFirstGeo++;
            }
        }

        GLI_tdstTexture* blueTexture =
            reinterpret_cast<GLI_tdstTexture*>(
                R2R_FindFirstTextureFromTarget(
                    blueEntry.hTarget
                )
                );

        GLI_tdstTexture* defTexture =
            reinterpret_cast<GLI_tdstTexture*>(
                R2R_FindFirstTextureFromTarget(
                    defEntry.hTarget
                )
                );

        GLI_tdstTexture blueTexCopy = {};
        GLI_tdstTexture defTexCopy = {};

        const bool blueTexOK =
            blueTexture != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(blueTexture),
                sizeof(GLI_tdstTexture)
            ) &&
            SafeReadMemory(
                blueTexture,
                &blueTexCopy,
                sizeof(blueTexCopy)
            );

        const bool defTexOK =
            defTexture != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(defTexture),
                sizeof(GLI_tdstTexture)
            ) &&
            SafeReadMemory(
                defTexture,
                &defTexCopy,
                sizeof(defTexCopy)
            );

        if (blueTexOK && defTexOK)
        {
            if (
                _stricmp(
                    blueTexCopy.szFileName,
                    defTexCopy.szFileName
                ) == 0
                )
            {
                sameFirstTextureName++;
            }
            else
            {
                differentFirstTextureName++;
            }
        }
        else
        {
            unreadableTexture++;
        }

        char blueSubName[128] = "(none)";
        char defSubName[128] = "(none)";

        if (
            blueTexOK &&
            blueTexCopy.p_TextureOfSubstitution != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    blueTexCopy.p_TextureOfSubstitution
                    ),
                sizeof(GLI_tdstTexture)
            )
            )
        {
            GLI_tdstTexture sub = {};

            if (
                SafeReadMemory(
                    blueTexCopy.p_TextureOfSubstitution,
                    &sub,
                    sizeof(sub)
                )
                )
            {
                strncpy_s(
                    blueSubName,
                    sub.szFileName,
                    _TRUNCATE
                );
            }
        }

        if (
            defTexOK &&
            defTexCopy.p_TextureOfSubstitution != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    defTexCopy.p_TextureOfSubstitution
                    ),
                sizeof(GLI_tdstTexture)
            )
            )
        {
            GLI_tdstTexture sub = {};

            if (
                SafeReadMemory(
                    defTexCopy.p_TextureOfSubstitution,
                    &sub,
                    sizeof(sub)
                )
                )
            {
                strncpy_s(
                    defSubName,
                    sub.szFileName,
                    _TRUNCATE
                );
            }
        }

        fprintf(
            report,
            "[%02u]\n"
            "  BLUE    target=%p visual=%p firstGeo=%p collide=%p bbox=%p\n"
            "          texture=%p name=%s\n"
            "          GPU=%p available=%d substitution=%p (%s)\n"
            "  DEFAULT target=%p visual=%p firstGeo=%p collide=%p bbox=%p\n"
            "          texture=%p name=%s\n"
            "          GPU=%p available=%d substitution=%p (%s)\n"
            "  firstGeo: %s    textureName: %s\n\n",
            i,
            blueEntry.hTarget,
            bluePOOK ? bluePO.hVisualSet : nullptr,
            blueFirstGeo,
            bluePOOK ? bluePO.hCollideSet : nullptr,
            bluePOOK ? bluePO.hBoundingVolume : nullptr,
            blueTexture,
            blueTexOK ? blueTexCopy.szFileName : "(unreadable)",
            blueTexOK ? blueTexCopy.p_stSpecParam : nullptr,
            blueTexOK ? static_cast<int>(blueTexCopy.bIsAvailable) : 0,
            blueTexOK ? blueTexCopy.p_TextureOfSubstitution : nullptr,
            blueSubName,
            defEntry.hTarget,
            defPOOK ? defPO.hVisualSet : nullptr,
            defFirstGeo,
            defPOOK ? defPO.hCollideSet : nullptr,
            defPOOK ? defPO.hBoundingVolume : nullptr,
            defTexture,
            defTexOK ? defTexCopy.szFileName : "(unreadable)",
            defTexOK ? defTexCopy.p_stSpecParam : nullptr,
            defTexOK ? static_cast<int>(defTexCopy.bIsAvailable) : 0,
            defTexOK ? defTexCopy.p_TextureOfSubstitution : nullptr,
            defSubName,
            (
                blueFirstGeo != nullptr &&
                defFirstGeo != nullptr &&
                blueFirstGeo == defFirstGeo
                )
            ? "SAME"
            : "DIFFERENT",
            (
                blueTexOK &&
                defTexOK &&
                _stricmp(
                    blueTexCopy.szFileName,
                    defTexCopy.szFileName
                ) == 0
                )
            ? "SAME"
            : "DIFFERENT"
        );
    }

    fprintf(
        report,
        "SUMMARY\n"
        "============================================================\n"
        "Same first geometric-object pointer      : %u\n"
        "Different first geometric-object pointer : %u\n"
        "Same first texture filename              : %u\n"
        "Different first texture filename         : %u\n"
        "Unreadable/missing texture comparison    : %u\n",
        sameFirstGeo,
        differentFirstGeo,
        sameFirstTextureName,
        differentFirstTextureName,
        unreadableTexture
    );
}


static AI_tdstIntelligence* R2R_GetActiveIntelligence(
    AI_tdstMind* mind
)
{
    if (mind == nullptr)
    {
        return nullptr;
    }

    if (
        mind->bDoingIntel != 0 &&
        mind->p_stIntelligence != nullptr
        )
    {
        return mind->p_stIntelligence;
    }

    if (
        mind->bDoingIntel == 0 &&
        mind->p_stReflex != nullptr
        )
    {
        return mind->p_stReflex;
    }

    // Some Rayman 2 actors/templates expose no Reflex block even when the
    // mode byte is zero. Fall back to Intelligence instead of failing.
    if (mind->p_stIntelligence != nullptr)
    {
        return mind->p_stIntelligence;
    }

    return mind->p_stReflex;
}

static AI_tdstScriptAI* R2R_GetScriptAIFromIntelligence(
    AI_tdstIntelligence* intelligence
)
{
    if (
        intelligence == nullptr ||
        intelligence->pp_stScriptAI == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                intelligence->pp_stScriptAI
                ),
            sizeof(AI_tdstScriptAI*)
        )
        )
    {
        return nullptr;
    }

    AI_tdstScriptAI* script = nullptr;

    if (
        !SafeReadMemory(
            intelligence->pp_stScriptAI,
            &script,
            sizeof(script)
        ) ||
        script == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(script),
            sizeof(AI_tdstScriptAI)
        )
        )
    {
        return nullptr;
    }

    return script;
}

static int R2R_GetComportIndex(
    AI_tdstScriptAI* script,
    AI_tdstComport* comport
)
{
    if (
        script == nullptr ||
        comport == nullptr ||
        script->a_stComport == nullptr ||
        script->ulNbComport == 0 ||
        script->ulNbComport > 1024
        )
    {
        return -1;
    }

    AI_tdstComport* begin =
        script->a_stComport;

    AI_tdstComport* end =
        begin + script->ulNbComport;

    if (
        comport < begin ||
        comport >= end
        )
    {
        return -1;
    }

    return static_cast<int>(
        comport - begin
        );
}


static void R2R_CopyCapturedName(
    char* destination,
    size_t destinationSize,
    const char* source
)
{
    if (
        destination == nullptr ||
        destinationSize == 0
        )
    {
        return;
    }

    destination[0] = '\0';

    if (source != nullptr)
    {
        sprintf_s(
            destination,
            destinationSize,
            "%s",
            source
        );
    }
}

static HIE_tdstSuperObject* R2R_GetActorSuperObjectSafe(
    HIE_tdstEngineObject* actor
)
{
    if (
        actor == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(actor),
            sizeof(HIE_tdstEngineObject)
        ) ||
        actor->hStandardGame == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                actor->hStandardGame
                ),
            sizeof(GAM_tdstStandardGame)
        )
        )
    {
        return nullptr;
    }

    HIE_tdstSuperObject* superObject =
        actor->hStandardGame->p_stSuperObject;

    if (
        superObject == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                superObject
                ),
            sizeof(HIE_tdstSuperObject)
        ) ||
        superObject->ulType != HIE_C_Type_Actor ||
        HIE_M_hSuperObjectGetActor(
            superObject
        ) != actor
        )
    {
        return nullptr;
    }

    return superObject;
}


static void R2R_CaptureLiveDsgPersoIdentities(
    HIE_tdstEngineObject* boss,
    AI_tdstMind* mind
)
{
    std::memset(
        g_R2RLiveDsgPersoIdentity,
        0,
        sizeof(g_R2RLiveDsgPersoIdentity)
    );

    g_R2RLiveDsgPersoIdentityCount = 0;

    if (
        mind == nullptr ||
        mind->p_stAIModel == nullptr ||
        mind->p_stAIModel->p_stDsgVar == nullptr ||
        g_R2RLiveAIDsgCurrent.empty()
        )
    {
        return;
    }

    AI_tdstDsgVar dsgVar = {};

    if (
        !SafeReadMemory(
            mind->p_stAIModel->p_stDsgVar,
            &dsgVar,
            sizeof(dsgVar)
        ) ||
        dsgVar.a_stDsgVarInfo == nullptr ||
        dsgVar.ucNbDsgVar == 0 ||
        dsgVar.ucNbDsgVar > 128 ||
        dsgVar.ulBufferSize !=
        g_R2RLiveAIDsgCurrent.size()
        )
    {
        return;
    }

    std::vector<AI_tdstDsgVarInfo> infos(
        dsgVar.ucNbDsgVar
    );

    if (
        !SafeReadMemory(
            dsgVar.a_stDsgVarInfo,
            infos.data(),
            infos.size() *
            sizeof(AI_tdstDsgVarInfo)
        )
        )
    {
        return;
    }

    g_R2RLiveDsgPersoIdentityCount =
        static_cast<unsigned int>(
            infos.size()
            );

    HIE_tdstSuperObject* mainSuper =
        (
            GAM_g_stEngineStructure != nullptr
            )
        ? GAM_g_stEngineStructure->g_hMainActor
        : nullptr;

    HIE_tdstSuperObject* bossSuper =
        R2R_GetActorSuperObjectSafe(
            boss
        );

    for (
        unsigned int i = 0;
        i < static_cast<unsigned int>(
            infos.size()
            );
        i++
        )
    {
        if (
            static_cast<unsigned int>(
                infos[i].eTypeId
                ) != 9 // AI_E_dvt_Perso
            )
        {
            continue;
        }

        const unsigned long offset =
            infos[i].ulOffsetInDsgMem;

        if (
            offset + sizeof(uint32_t) >
            g_R2RLiveAIDsgCurrent.size()
            )
        {
            continue;
        }

        uint32_t rawPointer = 0;

        std::memcpy(
            &rawPointer,
            g_R2RLiveAIDsgCurrent.data() +
            offset,
            sizeof(rawPointer)
        );

        R2R_DsgPersoIdentity& identity =
            g_R2RLiveDsgPersoIdentity[i];

        identity.rawPointer =
            rawPointer;

        // IMPORTANT h.7.50 FIX:
        // A DSG variable of type Perso stores the actor's SuperObject handle,
        // not the HIE_tdstEngineObject pointer itself.
        HIE_tdstSuperObject* superObject =
            reinterpret_cast<HIE_tdstSuperObject*>(
                static_cast<uintptr_t>(
                    rawPointer
                    )
                );

        if (
            superObject == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    superObject
                    ),
                sizeof(HIE_tdstSuperObject)
            )
            )
        {
            continue;
        }

        identity.superObjectType =
            static_cast<unsigned long>(
                superObject->ulType
                );

        if (
            superObject->ulType !=
            HIE_C_Type_Actor
            )
        {
            continue;
        }

        HIE_tdstEngineObject* actor =
            HIE_M_hSuperObjectGetActor(
                superObject
            );

        identity.linkedActorPointer =
            static_cast<uint32_t>(
                reinterpret_cast<uintptr_t>(
                    actor
                    )
                );

        if (
            actor == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    actor
                    ),
                sizeof(HIE_tdstEngineObject)
            ) ||
            actor->hStandardGame == nullptr ||
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    actor->hStandardGame
                    ),
                sizeof(GAM_tdstStandardGame)
            )
            )
        {
            continue;
        }

        identity.valid = true;

        identity.familyType =
            actor->hStandardGame->lObjectFamilyType;

        identity.modelType =
            actor->hStandardGame->lObjectModelType;

        identity.personalType =
            actor->hStandardGame->lObjectPersonalType;

        identity.isMainActor =
            superObject == mainSuper;

        identity.isBoss =
            superObject == bossSuper;

        R2R_CopyCapturedName(
            identity.familyName,
            sizeof(identity.familyName),
            HIE_fn_szGetObjectFamilyName(
                superObject
            )
        );

        R2R_CopyCapturedName(
            identity.modelName,
            sizeof(identity.modelName),
            HIE_fn_szGetObjectModelName(
                superObject
            )
        );

        R2R_CopyCapturedName(
            identity.personalName,
            sizeof(identity.personalName),
            HIE_fn_szGetObjectPersonalName(
                superObject
            )
        );
    }
}


static void R2R_ReportLiveDsgPersoIdentities(
    FILE* report
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\nLIVE WATER_20 PERSO DSG IDENTITIES - CORRECT SUPEROBJECT PARSE\n"
        "============================================================\n"
        "IMPORTANT: h.7.49b interpreted Perso raw values as EngineObject pointers.\n"
        "That was wrong. Perso values are SuperObject handles whose linked object\n"
        "is the real HIE_tdstEngineObject. h.7.50 parses that correctly.\n\n"
        "idx superObj  linkedActor soType valid main boss  family / model / personal\n"
        "--- --------- ----------- ------ ----- ---- ----  ---------------------------\n"
    );

    const unsigned int count =
        g_R2RLiveDsgPersoIdentityCount < 128
        ? g_R2RLiveDsgPersoIdentityCount
        : 128;

    for (
        unsigned int i = 0;
        i < count;
        i++
        )
    {
        const R2R_DsgPersoIdentity& identity =
            g_R2RLiveDsgPersoIdentity[i];

        if (
            identity.rawPointer == 0 &&
            !identity.valid
            )
        {
            continue;
        }

        fprintf(
            report,
            "%3u %08X  %08X   %04lX   %-5s %-4s %-4s  %s / %s / %s\n"
            "      types: family=%ld model=%ld personal=%ld\n",
            i,
            static_cast<unsigned int>(
                identity.rawPointer
                ),
            static_cast<unsigned int>(
                identity.linkedActorPointer
                ),
            identity.superObjectType,
            identity.valid ? "YES" : "NO",
            identity.isMainActor ? "YES" : "NO",
            identity.isBoss ? "YES" : "NO",
            identity.familyName[0] != '\0'
            ? identity.familyName
            : "(unknown family)",
            identity.modelName[0] != '\0'
            ? identity.modelName
            : "(unknown model)",
            identity.personalName[0] != '\0'
            ? identity.personalName
            : "(unknown personal)",
            identity.familyType,
            identity.modelType,
            identity.personalType
        );
    }
}


static bool R2R_CaptureLiveAglaglAIState(
    HIE_tdstEngineObject* boss,
    FILE* report
)
{
    g_R2RLiveAIStateCaptured = false;
    g_R2RLiveAIDoingIntel = -1;
    g_R2RLiveAICurrentComportIndex = -1;
    g_R2RLiveAIPrevComportIndex = -1;
    g_R2RLiveAINoComportInit = 0;
    g_R2RLiveAIScheduleNodeOffset = -1;
    g_R2RLiveAIDsgSize = 0;
    g_R2RLiveAIDsgVarCount = 0;
    g_R2RLiveAIDsgCurrent.clear();

    if (
        boss == nullptr ||
        boss->hBrain == nullptr ||
        boss->hBrain->p_stMind == nullptr
        )
    {
        return false;
    }

    AI_tdstMind* mind =
        boss->hBrain->p_stMind;

    AI_tdstIntelligence* active =
        R2R_GetActiveIntelligence(
            mind
        );

    AI_tdstScriptAI* script =
        R2R_GetScriptAIFromIntelligence(
            active
        );

    if (
        active == nullptr ||
        script == nullptr
        )
    {
        return false;
    }

    g_R2RLiveAIDoingIntel =
        static_cast<int>(
            mind->bDoingIntel
            );

    g_R2RLiveAICurrentComportIndex =
        R2R_GetComportIndex(
            script,
            active->p_stCurrentComport
        );

    g_R2RLiveAIPrevComportIndex =
        R2R_GetComportIndex(
            script,
            active->p_stPrevComport
        );

    g_R2RLiveAINoComportInit =
        active->ulNoComportInit;

    // If the live interpreter is in the middle of a schedule, store its
    // node offset relative to the current comport's schedule root. This can
    // later be mapped onto the persistent copy without preserving Water_20
    // pointers.
    if (
        active->p_stCurrentSchedule != nullptr &&
        active->p_stCurrentComport != nullptr &&
        R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(
                active->p_stCurrentComport
                ),
            sizeof(AI_tdstComport)
        )
        )
    {
        AI_tdstComport comport = {};

        if (
            SafeReadMemory(
                active->p_stCurrentComport,
                &comport,
                sizeof(comport)
            ) &&
            comport.p_stSchedule != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    comport.p_stSchedule
                    ),
                sizeof(AI_tdstTreeInterpret)
            )
            )
        {
            AI_tdstTreeInterpret tree = {};

            if (
                SafeReadMemory(
                    comport.p_stSchedule,
                    &tree,
                    sizeof(tree)
                ) &&
                tree.p_stNodeInterpret != nullptr
                )
            {
                ptrdiff_t nodeOffset =
                    active->p_stCurrentSchedule -
                    tree.p_stNodeInterpret;

                if (
                    nodeOffset >= 0 &&
                    nodeOffset < 4096
                    )
                {
                    g_R2RLiveAIScheduleNodeOffset =
                        static_cast<int>(
                            nodeOffset
                            );
                }
            }
        }
    }

    // Capture the LIVE current DSG buffer, not the template's DSG.
    if (
        mind->p_stAIModel != nullptr &&
        mind->p_stAIModel->p_stDsgVar != nullptr &&
        mind->p_stDsgMem != nullptr
        )
    {
        AI_tdstDsgVar dsgVar = {};
        AI_tdstDsgMem dsgMem = {};

        if (
            SafeReadMemory(
                mind->p_stAIModel->p_stDsgVar,
                &dsgVar,
                sizeof(dsgVar)
            ) &&
            SafeReadMemory(
                mind->p_stDsgMem,
                &dsgMem,
                sizeof(dsgMem)
            ) &&
            dsgVar.ulBufferSize > 0 &&
            dsgVar.ulBufferSize <= 4096 &&
            dsgMem.p_cDsgMemBuffer != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(
                    dsgMem.p_cDsgMemBuffer
                    ),
                dsgVar.ulBufferSize
            )
            )
        {
            g_R2RLiveAIDsgCurrent.resize(
                dsgVar.ulBufferSize
            );

            if (
                SafeReadMemory(
                    dsgMem.p_cDsgMemBuffer,
                    g_R2RLiveAIDsgCurrent.data(),
                    dsgVar.ulBufferSize
                )
                )
            {
                g_R2RLiveAIDsgSize =
                    dsgVar.ulBufferSize;

                g_R2RLiveAIDsgVarCount =
                    static_cast<unsigned int>(
                        dsgVar.ucNbDsgVar
                        );
            }
            else
            {
                g_R2RLiveAIDsgCurrent.clear();
            }
        }
    }

    g_R2RLiveAIStateCaptured =
        g_R2RLiveAICurrentComportIndex >= 0 &&
        g_R2RLiveAIDsgSize > 0 &&
        !g_R2RLiveAIDsgCurrent.empty();

    if (g_R2RLiveAIStateCaptured)
    {
        R2R_CaptureLiveDsgPersoIdentities(
            boss,
            mind
        );
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nLIVE BLUE AI RUNTIME SNAPSHOT\n"
            "============================================================\n"
            "Mind                  : %p\n"
            "Active intelligence   : %p\n"
            "ScriptAI              : %p\n"
            "bDoingIntel           : %d\n"
            "Current comport       : %p [index %d / %lu]\n"
            "Previous comport      : %p [index %d]\n"
            "Current schedule      : %p\n"
            "Schedule node offset  : %d\n"
            "NoComportInit         : %lu\n"
            "DsgMem                : %p\n"
            "DSG current size      : %lu\n"
            "DSG variable count    : %u\n"
            "Capture complete      : %s\n",
            mind,
            active,
            script,
            g_R2RLiveAIDoingIntel,
            active->p_stCurrentComport,
            g_R2RLiveAICurrentComportIndex,
            script->ulNbComport,
            active->p_stPrevComport,
            g_R2RLiveAIPrevComportIndex,
            active->p_stCurrentSchedule,
            g_R2RLiveAIScheduleNodeOffset,
            g_R2RLiveAINoComportInit,
            mind->p_stDsgMem,
            g_R2RLiveAIDsgSize,
            g_R2RLiveAIDsgVarCount,
            g_R2RLiveAIStateCaptured
            ? "YES"
            : "NO"
        );

        R2R_ReportLiveDsgPersoIdentities(
            report
        );
    }

    return g_R2RLiveAIStateCaptured;
}



static bool R2R_ApplyCapturedLiveAIStateToClone(
    AI_tdstMind* cloneMind,
    FILE* report
)
{
    if (
        !g_R2RLiveAIStateCaptured ||
        cloneMind == nullptr
        )
    {
        return false;
    }

    // h.7.45 - CURRENT COMPORT ONLY
    //
    // Known results:
    // - h.7.40: default BrainCopyClone state + one AI frame = NO crash,
    //           but sanctuary intro + Rayman death/respawn.
    // - h.7.44: current=7 + previous=6 + live bDoingIntel = CRASH.
    //
    // This isolates the CURRENT behavior pointer alone.
    //
    // We leave completely untouched:
    // - clone bDoingIntel
    // - clone previous Comport
    // - clone DSG memory
    // - clone NoComportInit
    // - clone CurrentSchedule

    AI_tdstIntelligence* active =
        R2R_GetActiveIntelligence(
            cloneMind
        );

    AI_tdstScriptAI* script =
        R2R_GetScriptAIFromIntelligence(
            active
        );

    if (
        active == nullptr ||
        script == nullptr ||
        script->a_stComport == nullptr ||
        g_R2RLiveAICurrentComportIndex < 0 ||
        static_cast<unsigned long>(
            g_R2RLiveAICurrentComportIndex
            ) >= script->ulNbComport
        )
    {
        return false;
    }

    AI_tdstComport* currentBefore =
        active->p_stCurrentComport;

    AI_tdstComport* previousBefore =
        active->p_stPrevComport;

    AI_tdstNodeInterpret* scheduleBefore =
        active->p_stCurrentSchedule;

    const unsigned long noComportInitBefore =
        active->ulNoComportInit;

    const int doingIntelBefore =
        static_cast<int>(
            cloneMind->bDoingIntel
            );

    active->p_stCurrentComport =
        script->a_stComport +
        g_R2RLiveAICurrentComportIndex;

    if (report != nullptr)
    {
        fprintf(
            report,
            "RAYMAN 2 RANDOMIZER\n"
            "v0.0.14b.0 - AGLAGL CURRENT-COMPORT-ONLY AI TEST\n"
            "============================================================\n\n"
            "h.7.44 crashed with current=7 + previous=6 + live bDoingIntel.\n\n"
            "h.7.45 changes ONLY p_stCurrentComport.\n"
            "Everything else stays exactly as BrainCopyClone created it.\n\n"
            "Captured live current idx : %d\n"
            "Captured live previous idx: %d (NOT APPLIED)\n"
            "Captured live bDoingIntel : %d (NOT APPLIED)\n"
            "Captured live DSG size    : %lu (NOT APPLIED)\n\n"
            "Clone current BEFORE      : %p\n"
            "Clone current AFTER       : %p [index %d]\n"
            "Clone previous            : %p (UNCHANGED)\n"
            "Clone schedule            : %p (UNCHANGED)\n"
            "Clone NoComportInit       : %lu (UNCHANGED)\n"
            "Clone bDoingIntel         : %d (UNCHANGED)\n\n"
            "READY FOR ONE AI FRAME: YES\n",
            g_R2RLiveAICurrentComportIndex,
            g_R2RLiveAIPrevComportIndex,
            g_R2RLiveAIDoingIntel,
            g_R2RLiveAIDsgSize,
            currentBefore,
            active->p_stCurrentComport,
            g_R2RLiveAICurrentComportIndex,
            previousBefore,
            scheduleBefore,
            noComportInitBefore,
            doingIntelBefore
        );

        fflush(report);
    }

    return true;
}



static const char* R2R_AITypeName(
    unsigned int type
)
{
    switch (type)
    {
    case 0: return "KeyWord";
    case 1: return "Condition";
    case 2: return "Operator";
    case 3: return "Function";
    case 4: return "Procedure";
    case 5: return "MetaAction";
    case 6: return "BeginMacro";
    case 7: return "EndMacro";
    case 8: return "EndTree";
    case 9: return "Field";
    case 10: return "DsgVar";
    case 11: return "DsgVarRef";
    case 12: return "Constant";
    case 13: return "Real";
    case 14: return "Button";
    case 15: return "ConstantVector";
    case 16: return "Vector";
    case 17: return "Mask";
    case 18: return "Module";
    case 19: return "DsgVarId";
    case 20: return "String";
    case 21: return "LipsSynchroRef";
    case 22: return "FamilyRef";
    case 23: return "PersoRef";
    case 24: return "ActionRef";
    case 25: return "SuperObjectRef";
    case 26: return "WayPointRef";
    case 27: return "TextRef";
    case 28: return "ComportRef";
    case 29: return "ModuleRef";
    case 30: return "SoundEventRef";
    case 31: return "ObjectTableRef";
    case 32: return "GameMaterialRef";
    case 33: return "ParticleGenerator";
    case 34: return "Color";
    case 35: return "ModelRef";
    case 36: return "Light";
    case 37: return "Caps";
    case 38: return "Graph";
    case 39: return "MacroRef";
    case 40: return "Unknown";
    default: return "OUT_OF_RANGE";
    }
}

static bool R2R_AITypeLooksLikeReference(
    unsigned int type
)
{
    return
        type == 21 ||
        (type >= 22 && type <= 33) ||
        (type >= 35 && type <= 39);
}

static void R2R_AuditOneAITree(
    FILE* report,
    const char* label,
    AI_tdstTreeInterpret* tree
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\nTREE: %s\n"
        "------------------------------------------------------------\n"
        "Tree object           : %p\n",
        label != nullptr ? label : "(unnamed)",
        tree
    );

    if (
        tree == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(tree),
            sizeof(AI_tdstTreeInterpret)
        )
        )
    {
        fprintf(report, "Tree readable         : NO\n");
        return;
    }

    AI_tdstTreeInterpret treeCopy = {};

    if (
        !SafeReadMemory(
            tree,
            &treeCopy,
            sizeof(treeCopy)
        )
        )
    {
        fprintf(report, "Tree read             : FAILED\n");
        return;
    }

    fprintf(
        report,
        "Node array            : %p\n"
        "Node array domain     : %s\n"
        "\n"
        "idx  node       type depth skip rawParam   ref-domain\n"
        "---- ---------- ---- ----- ---- ---------- ----------------\n",
        treeCopy.p_stNodeInterpret,
        PointerDomainFor3dAudit(
            treeCopy.p_stNodeInterpret
        )
    );

    if (treeCopy.p_stNodeInterpret == nullptr)
    {
        return;
    }

    const unsigned int MAX_NODES = 256;
    bool foundEnd = false;

    for (
        unsigned int i = 0;
        i < MAX_NODES;
        i++
        )
    {
        AI_tdstNodeInterpret* nodePtr =
            treeCopy.p_stNodeInterpret + i;

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(nodePtr),
                sizeof(AI_tdstNodeInterpret)
            )
            )
        {
            fprintf(
                report,
                "%4u %p  UNREADABLE\n",
                i,
                nodePtr
            );
            break;
        }

        AI_tdstNodeInterpret node = {};

        if (
            !SafeReadMemory(
                nodePtr,
                &node,
                sizeof(node)
            )
            )
        {
            fprintf(
                report,
                "%4u %p  READ_FAILED\n",
                i,
                nodePtr
            );
            break;
        }

        const unsigned int type =
            static_cast<unsigned int>(
                node.eType
                );

        void* rawParam =
            node.uParam.pvValue;

        const bool refLike =
            R2R_AITypeLooksLikeReference(
                type
            );

        fprintf(
            report,
            "%4u %p  %2u %-5u %-4u %p %-16s  %s%s\n",
            i,
            nodePtr,
            type,
            static_cast<unsigned int>(node.ucDepth),
            static_cast<unsigned int>(node.uwNodeToSkip),
            rawParam,
            R2R_AITypeName(type),
            refLike
            ? PointerDomainFor3dAudit(rawParam)
            : "(value/id)",
            (
                refLike &&
                rawParam != nullptr &&
                !PointerInsideCrossLevelArena(rawParam)
                )
            ? "  <== EXTERNAL REF"
            : ""
        );

        if (
            type == 24 &&
            rawParam != nullptr
            )
        {
            char actionLabel[96] = {};

            sprintf_s(
                actionLabel,
                "%s ACTIONREF node %u",
                label != nullptr ? label : "TREE",
                i
            );

            fprintf(
                report,
                "      >>> DEEP ACTIONREF AUDIT BEGIN >>>\n"
            );

            HIE_tdstState* actionState =
                reinterpret_cast<HIE_tdstState*>(
                    rawParam
                    );

            ReportStateDetails(
                report,
                actionLabel,
                actionState
            );

            // h.7.65:
            // The dangerous ChangeAction target in Comport 2 is General 302,
            // but its hNextState still points into the donor arena. Follow the
            // State chain READ-ONLY so we know every animation General that
            // this action may transition through before we import anything.
            if (
                actionState != nullptr &&
                PointerInsideCrossLevelArena(
                    actionState
                )
                )
            {
                fprintf(
                    report,
                    "      --- NEXTSTATE CHAIN (READ-ONLY) ---\n"
                );

                HIE_tdstState* visited[16] = {};
                unsigned int visitedCount = 0;

                HIE_tdstState* cursor =
                    actionState;

                for (
                    unsigned int chainIndex = 0;
                    chainIndex < 12;
                    chainIndex++
                    )
                {
                    if (
                        cursor == nullptr ||
                        !R2R_AddressReadable(
                            reinterpret_cast<uintptr_t>(
                                cursor
                                ),
                            sizeof(HIE_tdstState)
                        )
                        )
                    {
                        fprintf(
                            report,
                            "      chain[%u]: STOP (%s)\n",
                            chainIndex,
                            cursor == nullptr
                            ? "NULL"
                            : "UNREADABLE"
                        );
                        break;
                    }

                    bool alreadyVisited = false;

                    for (
                        unsigned int v = 0;
                        v < visitedCount;
                        v++
                        )
                    {
                        if (visited[v] == cursor)
                        {
                            alreadyVisited = true;
                            break;
                        }
                    }

                    if (alreadyVisited)
                    {
                        fprintf(
                            report,
                            "      chain[%u]: LOOP -> %p\n",
                            chainIndex,
                            cursor
                        );
                        break;
                    }

                    if (visitedCount < 16)
                    {
                        visited[visitedCount++] =
                            cursor;
                    }

                    HIE_tdstState stateCopy = {};

                    if (
                        !SafeReadMemory(
                            cursor,
                            &stateCopy,
                            sizeof(stateCopy)
                        )
                        )
                    {
                        fprintf(
                            report,
                            "      chain[%u]: READ_FAILED @ %p\n",
                            chainIndex,
                            cursor
                        );
                        break;
                    }

                    char chainLabel[128] = {};

                    sprintf_s(
                        chainLabel,
                        "%s NEXT[%u]",
                        actionLabel,
                        chainIndex
                    );

                    ReportStateDetails(
                        report,
                        chainLabel,
                        cursor
                    );

                    if (
                        stateCopy.hNextState == nullptr
                        )
                    {
                        fprintf(
                            report,
                            "      chain[%u]: END (NextState NULL)\n",
                            chainIndex
                        );
                        break;
                    }

                    cursor =
                        stateCopy.hNextState;
                }

                fprintf(
                    report,
                    "      --- END NEXTSTATE CHAIN ---\n"
                );
            }

            fprintf(
                report,
                "      <<< DEEP ACTIONREF AUDIT END <<<\n"
            );
        }

        if (type == 8)
        {
            foundEnd = true;
            break;
        }
    }

    fprintf(
        report,
        "EndTree found         : %s\n",
        foundEnd ? "YES" : "NO"
    );
}

static void R2R_AuditOneComport(
    FILE* report,
    const char* label,
    AI_tdstComport* comport
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n============================================================\n"
        "COMPORT: %s\n"
        "============================================================\n"
        "Comport pointer       : %p\n"
        "Comport domain        : %s\n",
        label != nullptr ? label : "(unnamed)",
        comport,
        PointerDomainFor3dAudit(comport)
    );

    if (
        comport == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(comport),
            sizeof(AI_tdstComport)
        )
        )
    {
        fprintf(report, "Comport readable      : NO\n");
        return;
    }

    AI_tdstComport copy = {};

    if (
        !SafeReadMemory(
            comport,
            &copy,
            sizeof(copy)
        )
        )
    {
        fprintf(report, "Comport read          : FAILED\n");
        return;
    }

    fprintf(
        report,
        "Rules array           : %p\n"
        "Rule count            : %u\n"
        "Schedule tree         : %p\n",
        copy.a_stRules,
        static_cast<unsigned int>(
            copy.ucNbRules
            ),
        copy.p_stSchedule
    );

    const unsigned int safeRules =
        copy.ucNbRules <= 64
        ? static_cast<unsigned int>(
            copy.ucNbRules
            )
        : 64;

    for (
        unsigned int i = 0;
        i < safeRules;
        i++
        )
    {
        char ruleName[64] = {};

        sprintf_s(
            ruleName,
            "%s RULE %u",
            label != nullptr ? label : "COMPORT",
            i
        );

        R2R_AuditOneAITree(
            report,
            ruleName,
            copy.a_stRules != nullptr
            ? copy.a_stRules + i
            : nullptr
        );
    }

    R2R_AuditOneAITree(
        report,
        "COMPORT SCHEDULE",
        copy.p_stSchedule
    );
}

static bool R2R_RunAglaglComportReadOnlyAudit(
    AI_tdstMind* cloneMind,
    FILE* report
)
{
    if (
        cloneMind == nullptr ||
        report == nullptr ||
        !g_R2RLiveAIStateCaptured
        )
    {
        return false;
    }

    AI_tdstIntelligence* active =
        R2R_GetActiveIntelligence(
            cloneMind
        );

    AI_tdstScriptAI* script =
        R2R_GetScriptAIFromIntelligence(
            active
        );

    if (
        active == nullptr ||
        script == nullptr ||
        script->a_stComport == nullptr ||
        script->ulNbComport == 0 ||
        script->ulNbComport > 1024 ||
        g_R2RLiveAICurrentComportIndex < 0 ||
        static_cast<unsigned long>(
            g_R2RLiveAICurrentComportIndex
            ) >= script->ulNbComport
        )
    {
        return false;
    }

    const int defaultCurrentIndex =
        R2R_GetComportIndex(
            script,
            active->p_stCurrentComport
        );

    AI_tdstComport* target =
        script->a_stComport +
        g_R2RLiveAICurrentComportIndex;

    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - AGLAGL COMPORT 7 READ-ONLY AUDIT\n"
        "============================================================\n\n"
        "Known result:\n"
        "- default BrainCopyClone AI frame does NOT crash, but replays intro\n"
        "- changing ONLY Current Comport to the live boss behavior crashes\n\n"
        "This build DOES NOT RUN AI and DOES NOT MODIFY the clone's Comport.\n"
        "It only inspects the default behavior and captured live behavior.\n\n"
        "ScriptAI              : %p\n"
        "Comport array         : %p\n"
        "Comport count         : %lu\n"
        "Clone current         : %p [index %d]\n"
        "Clone previous        : %p\n"
        "Captured live current : index %d\n"
        "Captured live previous: index %d\n"
        "Audit target          : %p\n"
        "NoAI                  : YES\n"
        "NoMechanic            : YES\n",
        script,
        script->a_stComport,
        script->ulNbComport,
        active->p_stCurrentComport,
        defaultCurrentIndex,
        active->p_stPrevComport,
        g_R2RLiveAICurrentComportIndex,
        g_R2RLiveAIPrevComportIndex,
        target
    );

    R2R_AuditOneComport(
        report,
        "DEFAULT CLONE CURRENT",
        active->p_stCurrentComport
    );

    R2R_AuditOneComport(
        report,
        "LIVE CAPTURED CURRENT",
        target
    );

    fflush(report);
    return true;
}


static const char* R2R_ACTION_ANIM_DEPENDENCY_REPORT_FILE =
"Rayman2Randomizer_AglaglActionAnimationDependencies.txt";

static void R2R_ReportOneActionA3dGeneralDependencyMap(
    FILE* report,
    uint16_t generalId
)
{
    if (report == nullptr)
    {
        return;
    }

    uint16_t words[28] = {};
    uintptr_t entryAddress = 0;
    uintptr_t generalBase = 0;

    if (
        !R2R_ReadA3dGeneralExact(
            generalId,
            words,
            entryAddress,
            generalBase
        )
        )
    {
        fprintf(
            report,
            "\nGENERAL %u: READ FAILED\n",
            static_cast<unsigned int>(generalId)
        );
        return;
    }

    uint32_t globals[12] = {};

    for (size_t i = 0; i < 12; i++)
    {
        R2R_ReadGlobal32(
            R2R_A3D_GLOBAL_SLOTS[i],
            globals[i]
        );
    }

    fprintf(
        report,
        "\n============================================================\n"
        "A3dGENERAL %u\n"
        "============================================================\n"
        "Entry address : %p\n"
        "General base  : %p\n\n",
        static_cast<unsigned int>(generalId),
        reinterpret_cast<void*>(entryAddress),
        reinterpret_cast<void*>(generalBase)
    );

    fprintf(report, "RAW 28 WORDS (0x38 bytes)\n");
    for (unsigned int i = 0; i < 28; i++)
    {
        fprintf(
            report,
            "  word[%02u] = %5u (0x%04X)%s",
            i,
            static_cast<unsigned int>(words[i]),
            static_cast<unsigned int>(words[i]),
            ((i + 1u) % 4u) == 0u ? "\n" : ""
        );
    }
    if ((28u % 4u) != 0u)
    {
        fprintf(report, "\n");
    }

    const uint32_t numVectors = words[1];
    const uint32_t numQuaternions = words[2];
    const uint32_t numHierarchies = words[3];
    const uint32_t numNTTO = words[4];
    const uint32_t numNumNTTO = words[5];
    const uint32_t numChannels = words[6];
    const uint32_t numOnlyFrames = words[7];
    const uint32_t numKeyFrames = words[8];
    const uint32_t numEvents = words[10];
    const uint32_t numMorphData = words[18];

    const uint32_t startVectors = words[19];
    const uint32_t startQuaternions = words[20];
    const uint32_t startHierarchies = words[21];
    const uint32_t startNTTO = words[22];
    const uint32_t startOnlyFrames = words[23];
    const uint32_t startChannels = words[24];
    const uint32_t startEvents = words[25];
    const uint32_t startMorphData = words[26];

    fprintf(
        report,
        "\nDIRECT DEPENDENCIES\n"
        "  speed                    : %u\n"
        "  vectors                  : start=%u count=%u\n"
        "  quaternions              : start=%u count=%u\n"
        "  hierarchies              : start=%u count=%u\n"
        "  NTTO                     : start=%u count=%u\n"
        "  numNumNTTO               : %u\n"
        "  channels                 : start=%u count=%u\n"
        "  onlyFrames               : start=%u count=%u\n"
        "  keyFrames total          : %u\n"
        "  events                   : start=%u count=%u\n"
        "  morphData                : start=%u count=%u\n"
        "  start_vectors2 (word16)  : %u\n"
        "  start_quat2    (word17)  : %u\n",
        static_cast<unsigned int>(words[0]),
        startVectors, numVectors,
        startQuaternions, numQuaternions,
        startHierarchies, numHierarchies,
        startNTTO, numNTTO,
        numNumNTTO,
        startChannels, numChannels,
        startOnlyFrames, numOnlyFrames,
        numKeyFrames,
        startEvents, numEvents,
        startMorphData, numMorphData,
        static_cast<unsigned int>(words[16]),
        static_cast<unsigned int>(words[17])
    );

    uint32_t minFrames = 0xFFFFFFFFu;
    uint32_t maxFrames = 0u;
    uint32_t minFramesKF = 0xFFFFFFFFu;
    uint32_t maxFramesKF = 0u;
    uint32_t minKeyFrames = 0xFFFFFFFFu;
    uint32_t maxKeyFramesConservative = 0u;
    unsigned int readableChannels = 0;

    fprintf(
        report,
        "\nCHANNEL REFERENCES (16 bytes each)\n"
        "  idx  unk0 id vector numNTTOStart framesKFStart keyFrameStart\n"
    );

    const uintptr_t channelBase =
        static_cast<uintptr_t>(globals[2]);

    for (uint32_t c = 0; c < numChannels && c < 128u; c++)
    {
        uint8_t raw[16] = {};

        const uintptr_t address =
            channelBase +
            static_cast<uintptr_t>(
                startChannels + c
                ) * 16u;

        if (
            channelBase == 0 ||
            !R2R_AddressReadable(
                address,
                sizeof(raw)
            ) ||
            !SafeReadMemory(
                reinterpret_cast<const void*>(address),
                raw,
                sizeof(raw)
            )
            )
        {
            fprintf(
                report,
                "  ch[%u] READ FAILED @ %p\n",
                static_cast<unsigned int>(c),
                reinterpret_cast<void*>(address)
            );
            continue;
        }

        uint16_t unk0 = 0;
        uint16_t id = 0;
        uint16_t vectorIndex = 0;
        uint16_t numStart = 0;
        uint32_t framesKFStart = 0;
        uint32_t keyFrameStart = 0;

        std::memcpy(&unk0, raw + 0, 2);
        std::memcpy(&id, raw + 2, 2);
        std::memcpy(&vectorIndex, raw + 4, 2);
        std::memcpy(&numStart, raw + 6, 2);
        std::memcpy(&framesKFStart, raw + 8, 4);
        std::memcpy(&keyFrameStart, raw + 12, 4);

        readableChannels++;

        if (numStart < minFrames)
        {
            minFrames = numStart;
        }

        const uint32_t framesEnd =
            static_cast<uint32_t>(numStart) +
            numNumNTTO;

        if (framesEnd > maxFrames)
        {
            maxFrames = framesEnd;
        }

        if (framesKFStart < minFramesKF)
        {
            minFramesKF = framesKFStart;
        }

        const uint32_t framesKFEnd =
            framesKFStart +
            numOnlyFrames;

        if (framesKFEnd > maxFramesKF)
        {
            maxFramesKF = framesKFEnd;
        }

        if (keyFrameStart < minKeyFrames)
        {
            minKeyFrames = keyFrameStart;
        }

        const uint32_t keyFrameEnd =
            keyFrameStart +
            numKeyFrames;

        if (keyFrameEnd > maxKeyFramesConservative)
        {
            maxKeyFramesConservative =
                keyFrameEnd;
        }

        fprintf(
            report,
            "  ch[%u] %u %u %u %u %u %u\n",
            static_cast<unsigned int>(c),
            static_cast<unsigned int>(unk0),
            static_cast<unsigned int>(id),
            static_cast<unsigned int>(vectorIndex),
            static_cast<unsigned int>(numStart),
            static_cast<unsigned int>(framesKFStart),
            static_cast<unsigned int>(keyFrameStart)
        );
    }

    if (minFrames == 0xFFFFFFFFu)
    {
        minFrames = 0;
    }

    if (minFramesKF == 0xFFFFFFFFu)
    {
        minFramesKF = 0;
    }

    if (minKeyFrames == 0xFFFFFFFFu)
    {
        minKeyFrames = 0;
    }

    fprintf(
        report,
        "\nSECONDARY CHANNEL-REFERENCED RANGES\n"
        "  readable channels        : %u / %u\n"
        "  frames/numNTTO           : start=%u count=%u end=%u\n"
        "  framesKF                 : start=%u count=%u end=%u\n"
        "  keyFrames conservative   : start=%u count=%u end=%u\n",
        readableChannels,
        static_cast<unsigned int>(numChannels),
        minFrames,
        maxFrames >= minFrames
        ? maxFrames - minFrames
        : 0u,
        maxFrames,
        minFramesKF,
        maxFramesKF >= minFramesKF
        ? maxFramesKF - minFramesKF
        : 0u,
        maxFramesKF,
        minKeyFrames,
        maxKeyFramesConservative >= minKeyFrames
        ? maxKeyFramesConservative - minKeyFrames
        : 0u,
        maxKeyFramesConservative
    );

    fprintf(
        report,
        "\nGLOBAL TABLE BASES AT CAPTURE TIME\n"
    );

    for (size_t i = 0; i < 12; i++)
    {
        fprintf(
            report,
            "  slot[%02zu] %-18s = %p\n",
            i,
            R2R_A3D_GLOBAL_NAMES[i],
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(
                    globals[i]
                    )
                )
        );
    }
}

static bool R2R_WriteAglaglActionAnimationDependencyAudit()
{
    FILE* report = nullptr;

    fopen_s(
        &report,
        R2R_ACTION_ANIM_DEPENDENCY_REPORT_FILE,
        "w"
    );

    if (report == nullptr)
    {
        return false;
    }

    setvbuf(
        report,
        nullptr,
        _IONBF,
        0
    );

    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - AGLAGL ACTION ANIMATION DEPENDENCY AUDIT\n"
        "============================================================\n\n"
        "READ-ONLY WATER_20 CAPTURE.\n\n"
        "h.7.66 proved that ChangeAction itself is safe when the donor\n"
        "State graph uses a known-valid animation descriptor. The exact\n"
        "donor action chains discovered by h.7.65 are:\n"
        "  General 302 -> General 303 -> END\n"
        "  General 305 -> General 301 -> General 301 loop\n\n"
        "This report captures the exact A3dGENERAL dependency ranges for\n"
        "301, 302, 303 and 305 while Water_20 still owns the live animation\n"
        "tables. No AI frame is executed and no animation table is modified.\n"
    );

    const uint16_t ids[] =
    {
        301,
        302,
        303,
        305
    };

    for (size_t i = 0; i < sizeof(ids) / sizeof(ids[0]); i++)
    {
        R2R_ReportOneActionA3dGeneralDependencyMap(
            report,
            ids[i]
        );
    }

    fprintf(
        report,
        "\n============================================================\n"
        "RESULT: ACTION ANIMATION DEPENDENCY AUDIT COMPLETE\n"
        "============================================================\n"
    );

    fclose(report);
    return true;
}


static void R2R_CaptureLiveBlueAglaglVariant()
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(
            GAM_g_stEngineStructure->szLevelName,
            "Water_20"
        ) != 0
        )
    {
        MessageBoxA(
            nullptr,
            "This safe comparison must be done in Water_20 while the REAL BLUE Aglagl is loaded.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONINFORMATION
        );
        return;
    }

    HIE_tdstSuperObject* bossSO = nullptr;
    HIE_tdstEngineObject* boss = nullptr;
    bool found = false;
    unsigned int remainingNodes = 5000;

    if (
        GAM_g_p_stDynamicWorld != nullptr &&
        *GAM_g_p_stDynamicWorld != nullptr
        )
    {
        found =
            R2R_FindActorByModelBounded(
                *GAM_g_p_stDynamicWorld,
                "STN_ouodeugwod",
                bossSO,
                boss,
                0,
                remainingNodes
            );
    }

    if (
        !found &&
        remainingNodes > 0 &&
        GAM_g_p_stInactiveDynamicWorld != nullptr &&
        *GAM_g_p_stInactiveDynamicWorld != nullptr
        )
    {
        found =
            R2R_FindActorByModelBounded(
                *GAM_g_p_stInactiveDynamicWorld,
                "STN_ouodeugwod",
                bossSO,
                boss,
                0,
                remainingNodes
            );
    }

    if (
        !found ||
        boss == nullptr ||
        boss->h3dData == nullptr ||
        boss->h3dData->h_Family == nullptr
        )
    {
        MessageBoxA(
            nullptr,
            "F3 finished safely, but the live boss was not found.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    GAM_tdst3dData* data = boss->h3dData;
    HIE_tdstFamilyList* family = data->h_Family;

    HIE_tdstObjectsTablesList* currentTable =
        data->h_CurrentObjectsTable;

    HIE_tdstObjectsTablesList* initialTable =
        data->h_InitialObjectsTable;

    HIE_tdstObjectsTablesList* defaultTable =
        family->hDefaultObjectsTable;

    // h.7.37: do NOT try to find the blue table in the Family linked list.
    // h.7.35/7.36 proved it is a standalone table stored near the Family.
    // Capture only its RELATIVE OFFSET from the live Family. The serialized
    // Water_20 donor arena uses the same layout, so we can recover the blue
    // table safely after the level change without keeping any live pointer.
    const intptr_t blueDelta =
        reinterpret_cast<uint8_t*>(currentTable) -
        reinterpret_cast<uint8_t*>(family);

    const intptr_t defaultDelta =
        reinterpret_cast<uint8_t*>(defaultTable) -
        reinterpret_cast<uint8_t*>(family);

    const bool blueDeltaPlausible =
        currentTable != nullptr &&
        blueDelta > 0 &&
        blueDelta < 0x10000;

    const bool defaultDeltaPlausible =
        defaultTable != nullptr &&
        defaultDelta > 0 &&
        defaultDelta < 0x10000;

    if (blueDeltaPlausible && defaultDeltaPlausible)
    {
        HIE_tdstObjectsTablesList blueCopy = {};

        if (
            SafeReadMemory(
                currentTable,
                &blueCopy,
                sizeof(blueCopy)
            ) &&
            blueCopy.uwNumberOfElement > 0 &&
            blueCopy.uwNumberOfElement <= 64
            )
        {
            g_R2RBlueVariantCaptured = true;
            g_R2RBlueTableFamilyDelta = blueDelta;
            g_R2RDefaultTableFamilyDelta = defaultDelta;
            g_R2RBlueTableEntryCount = blueCopy.uwNumberOfElement;
        }
    }

    FILE* report = nullptr;

    fopen_s(
        &report,
        R2R_BLUE_VARIANT_REPORT_FILE,
        "w"
    );

    if (report == nullptr)
    {
        return;
    }

    // h.7.82: while Water_20 still owns its ObjectType registries and Always
    // list, resolve the GenerateObject target IDs 10/11/11 to real names and
    // capture any exact Always template. Nothing is allocated or modified.
    R2R_CaptureGenerateObjectTemplateIdentity(report);

    // h.7.87: instantiate the native Water_20 Always template once, snapshot
    // the allocator result, then kill it before the level advances a frame.
    R2R_CaptureNativeWaterStalacShootAllocation(
        bossSO,
        report
    );

    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - LIVE BLUE AGLAGL TABLE OFFSET + VISUAL DIFF\n"
        "============================================================\n\n"
        "h.7.34b proved something important:\n"
        "- live BLUE current table != family default table\n"
        "- live BLUE current table is NOT linked normally in the Family list\n\n"
        "So h.7.35 does NOT try to assign it a Family-list index.\n"
        "It compares the live current table against the default table\n"
        "entry-by-entry, without following geometry/material/texture pointers.\n\n"
        "SuperObject       : %p\n"
        "EngineObject     : %p\n"
        "Family           : %p\n"
        "Current state    : %p\n"
        "Current anim     : %p\n"
        "Current table    : %p\n"
        "Initial table    : %p\n"
        "Default table    : %p\n"
        "Current==Default : %s\n"
        "Family->BLUE delta: 0x%IX\n"
        "Family->DEFAULT delta: 0x%IX\n"
        "Offset capture OK : %s\n"
        "Captured entries  : %u\n"
        "Nodes left guard : %u\n",
        bossSO,
        boss,
        family,
        data->h_CurrentState,
        data->h_CurrentState != nullptr
        ? data->h_CurrentState->p_stAnim
        : nullptr,
        currentTable,
        initialTable,
        defaultTable,
        currentTable == defaultTable ? "YES" : "NO",
        static_cast<size_t>(blueDelta),
        static_cast<size_t>(defaultDelta),
        g_R2RBlueVariantCaptured ? "YES" : "NO",
        static_cast<unsigned int>(g_R2RBlueTableEntryCount),
        remainingNodes
    );

    R2R_ReportRawObjectTable(
        report,
        "LIVE BLUE CURRENT TABLE",
        currentTable
    );

    R2R_ReportRawObjectTable(
        report,
        "FAMILY DEFAULT TABLE",
        defaultTable
    );

    if (
        initialTable != nullptr &&
        initialTable != defaultTable
        )
    {
        R2R_ReportRawObjectTable(
            report,
            "INITIAL TABLE",
            initialTable
        );
    }

    R2R_CompareCurrentAndDefaultTables(
        report,
        currentTable,
        defaultTable
    );

    R2R_ReportBlueDefaultVisualTextureDiff(
        report,
        currentTable,
        defaultTable
    );

    const bool liveAICaptured =
        R2R_CaptureLiveAglaglAIState(
            boss,
            report
        );

    const bool actionAnimationDependenciesCaptured =
        R2R_WriteAglaglActionAnimationDependencyAudit();

    fprintf(
        report,
        "\nF3 COMBINED CAPTURE RESULT\n"
        "============================================================\n"
        "Blue visual-table capture       : %s\n"
        "Live AI runtime capture         : %s\n"
        "Action animation dependency map : %s\n",
        g_R2RBlueVariantCaptured ? "YES" : "NO",
        liveAICaptured ? "YES" : "NO",
        actionAnimationDependenciesCaptured ? "YES" : "NO"
    );

    fclose(report);

    if (g_R2RBlueVariantCaptured)
    {
        char message[1100] = {};

        sprintf_s(
            message,
            "BLUE AGLAGL VISUAL + LIVE AI STATE CAPTURED!\n\n"
            "Family -> BLUE table delta: 0x%IX\n"
            "Family -> default table delta: 0x%IX\n"
            "Entries: %u\n"
            "Live AI snapshot: %s\n\n"
            "h.7.68 REAL ACTION IMPORT TEST:\n"
            "The blue visual + live AI capture is ready.\n\n"
            "Continue in this exact order:\n"
            "1. Press F7 HERE in Water_20 to preserve the real 301/302/303/305 animation data.\n"
            "2. Switch to Bast_20 and wait until playable.\n"
            "3. Press F7 in Bast_20 to install the expanded merged bank.\n"
            "4. Press F6 three times.\n\n"
            "General 302's single animation event is intentionally disabled for this first real-motion test.",
            static_cast<size_t>(g_R2RBlueTableFamilyDelta),
            static_cast<size_t>(g_R2RDefaultTableFamilyDelta),
            static_cast<unsigned int>(g_R2RBlueTableEntryCount),
            g_R2RLiveAIStateCaptured ? "YES" : "NO"
        );

        MessageBoxA(
            nullptr,
            message,
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONINFORMATION
        );
    }
    else
    {
        MessageBoxA(
            nullptr,
            "F3 finished safely, but the BLUE table offset was not plausible.\n\nSend me Rayman2Randomizer_AglaglBlueTableOffsetCapture.txt.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
    }
}

static bool R2R_ApplyCapturedBlueVariantToRuntimeFamily(FILE* report)
{
    if (
        !g_R2RBlueVariantCaptured ||
        g_R2RBlueTableFamilyDelta <= 0 ||
        g_AglaglFamily == nullptr ||
        g_RuntimeAglaglFamily == nullptr ||
        g_CrossLevelArena == nullptr
        )
    {
        return false;
    }

    HIE_tdstObjectsTablesList* blueTable =
        reinterpret_cast<HIE_tdstObjectsTablesList*>(
            reinterpret_cast<uint8_t*>(g_AglaglFamily) +
            g_R2RBlueTableFamilyDelta
            );

    HIE_tdstObjectsTablesList blueCopy = {};

    if (
        !PointerInsideCrossLevelArena(blueTable) ||
        !SafeReadMemory(
            blueTable,
            &blueCopy,
            sizeof(blueCopy)
        ) ||
        blueCopy.uwNumberOfElement != g_R2RBlueTableEntryCount ||
        blueCopy.uwNumberOfElement == 0 ||
        blueCopy.uwNumberOfElement > 64 ||
        blueCopy.d_stObjectsTable == nullptr ||
        !PointerInsideCrossLevelArena(blueCopy.d_stObjectsTable)
        )
    {
        if (report != nullptr)
        {
            fprintf(
                report,
                "BLUE TABLE RECOVERY FAILED\n"
                "  arena Family       : %p\n"
                "  captured delta     : 0x%IX\n"
                "  candidate table    : %p\n"
                "  expected entries   : %u\n"
                "  candidate entries  : %u\n"
                "  candidate array    : %p\n\n",
                g_AglaglFamily,
                static_cast<size_t>(g_R2RBlueTableFamilyDelta),
                blueTable,
                static_cast<unsigned int>(g_R2RBlueTableEntryCount),
                static_cast<unsigned int>(blueCopy.uwNumberOfElement),
                blueCopy.d_stObjectsTable
            );
        }

        return false;
    }

    // Strong identity check: h.7.36 showed the live BLUE body uses gardeo_
    // textures while the orange/default body uses gardef_. Confirm the donor
    // arena candidate is really the BLUE serialized table before applying it.
    GLI_tdstTexture* firstTexture = nullptr;

    if (blueCopy.d_stObjectsTable != nullptr)
    {
        HIE_tdstObjectsTableElement firstEntry = {};

        if (
            SafeReadMemory(
                blueCopy.d_stObjectsTable,
                &firstEntry,
                sizeof(firstEntry)
            )
            )
        {
            firstTexture =
                reinterpret_cast<GLI_tdstTexture*>(
                    R2R_FindFirstTextureFromTarget(
                        firstEntry.hTarget
                    )
                    );
        }
    }

    GLI_tdstTexture textureCopy = {};
    bool gardeoConfirmed = false;

    if (
        firstTexture != nullptr &&
        SafeReadMemory(
            firstTexture,
            &textureCopy,
            sizeof(textureCopy)
        )
        )
    {
        gardeoConfirmed =
            strstr(
                textureCopy.szFileName,
                "gardeo_"
            ) != nullptr;
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "BLUE TABLE RECOVERY\n"
            "  arena Family       : %p\n"
            "  captured delta     : 0x%IX\n"
            "  recovered table    : %p\n"
            "  entry array        : %p\n"
            "  entries            : %u\n"
            "  first texture      : %p\n"
            "  first texture name : %s\n"
            "  gardeo_ confirmed  : %s\n\n",
            g_AglaglFamily,
            static_cast<size_t>(g_R2RBlueTableFamilyDelta),
            blueTable,
            blueCopy.d_stObjectsTable,
            static_cast<unsigned int>(blueCopy.uwNumberOfElement),
            firstTexture,
            firstTexture != nullptr
            ? textureCopy.szFileName
            : "(none)",
            gardeoConfirmed ? "YES" : "NO"
        );

        fflush(report);
    }

    if (!gardeoConfirmed)
    {
        return false;
    }

    g_RuntimeAglaglFamily->hDefaultObjectsTable =
        blueTable;

    if (
        g_RuntimeAglaglTemplate != nullptr &&
        g_RuntimeAglaglTemplate->h3dData != nullptr
        )
    {
        g_RuntimeAglaglTemplate->h3dData->h_InitialObjectsTable =
            blueTable;

        g_RuntimeAglaglTemplate->h3dData->h_CurrentObjectsTable =
            blueTable;
    }

    return true;
}

// ============================================================
// h.7.30 - DONOR TEXTURE GPU-HANDLE ISOLATION
//
// h.7.28 proved:
//   real Aglagl geometry + real materials + native Piranha texture = VISIBLE
//
// h.7.29 proved:
//   real Aglagl texture object = immediate crash
//
// GLI_tdstTexture contains p_stSpecParam, explicitly described by ACP_Ray2
// as the "Parameter specific for graphics card".
//
// This test keeps every Aglagl texture structure/filename/bitmap/palette,
// but replaces ONLY p_stSpecParam with the known-good Piranha GPU handle.
// If this is stable, we have isolated the exact missing cross-level resource.
// ============================================================



static GLI_tdstTexture* R2R_GetOrCreateDonorTextureFromCapturedData(
    GLI_tdstTexture* originalTexture,
    FILE* report
)
{
    if (originalTexture == nullptr)
    {
        return nullptr;
    }

    for (size_t i = 0; i < g_R2RDonorTextureCloneOriginals.size(); i++)
    {
        if (g_R2RDonorTextureCloneOriginals[i] == originalTexture)
        {
            return g_R2RDonorTextureClones[i];
        }
    }

    if (
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(originalTexture),
            sizeof(GLI_tdstTexture)
        )
        )
    {
        return nullptr;
    }

    GLI_tdstTexture original = {};

    if (
        !SafeReadMemory(
            originalTexture,
            &original,
            sizeof(original)
        )
        )
    {
        return nullptr;
    }

    // We must have some captured CPU-side texture data to give back to Rayman 2.
    if (
        original.p_vBitMap == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(original.p_vBitMap),
            4
        )
        )
    {
        if (report != nullptr)
        {
            fprintf(
                report,
                "CAPTURED TEXTURE DATA NOT READABLE\n"
                "  original texture : %p\n"
                "  filename         : %s\n"
                "  bitmap           : %p\n\n",
                originalTexture,
                original.szFileName,
                original.p_vBitMap
            );

            fflush(report);
        }

        return nullptr;
    }

    GLI_tdstTexture* fresh =
        new (std::nothrow) GLI_tdstTexture;

    if (fresh == nullptr)
    {
        return nullptr;
    }

    // Keep the full captured Water_20 texture description and CPU-side data.
    *fresh = original;

    // Throw away ONLY the stale device-specific resource.
    fresh->p_stSpecParam = nullptr;
    fresh->p_TextureOfSubstitution = nullptr;
    fresh->bIsAvailable = FALSE;

    // Insert this private texture into Rayman 2's normal texture table.
    GLI_fn_vLoadTextureInTable(
        fresh
    );

    // Verify the insertion actually happened.
    int insertedSlot = -1;

    for (int i = 0; i < GLI_C_lNBMaxOfTextures; i++)
    {
        if (
            GLI_gs_aDEFTableOfTextureAlreadyRead[i] == fresh &&
            GLI_gs_aDEFTableOfTextureMemoryChannels[i] != GLI_C_TEXIsUnallocated
            )
        {
            insertedSlot = i;
            break;
        }
    }

    if (insertedSlot < 0)
    {
        if (report != nullptr)
        {
            fprintf(
                report,
                "TEXTURE TABLE INSERT FAILED\n"
                "  original texture : %p\n"
                "  filename         : %s\n\n",
                originalTexture,
                original.szFileName
            );

            fflush(report);
        }

        delete fresh;
        return nullptr;
    }

    g_R2RDonorTextureCloneOriginals.push_back(
        originalTexture
    );

    g_R2RDonorTextureClones.push_back(
        fresh
    );

    if (report != nullptr)
    {
        fprintf(
            report,
            "CAPTURED TEXTURE QUEUED\n"
            "  original texture : %p\n"
            "  fresh texture    : %p\n"
            "  table slot       : %d\n"
            "  filename         : %s\n"
            "  bitmap           : %p\n"
            "  palette          : %p\n"
            "  stale GPU param  : %p\n"
            "  fresh GPU param  : %p\n"
            "  size             : %hu x %hu\n"
            "  real size        : %hu x %hu\n\n",
            originalTexture,
            fresh,
            insertedSlot,
            fresh->szFileName,
            fresh->p_vBitMap,
            fresh->p_vColorTable,
            original.p_stSpecParam,
            fresh->p_stSpecParam,
            fresh->uwWidth,
            fresh->uwHeight,
            fresh->uwRealWidth,
            fresh->uwRealHeight
        );

        fflush(report);
    }

    return fresh;
}

static bool R2R_CollectTargetTextureReplacement(
    void* target,
    std::vector<void*>& visualMaterials,
    std::vector<uintptr_t>& textureFields,
    std::vector<GLI_tdstTexture*>& freshTextures,
    FILE* report
)
{
    if (
        target == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(target),
            16
        )
        )
    {
        return false;
    }

    uint32_t targetHeader[4] = {};

    if (!SafeReadMemory(
        target,
        targetHeader,
        sizeof(targetHeader)
    ))
    {
        return false;
    }

    void* visualSet =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(targetHeader[0])
            );

    if (
        visualSet == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(visualSet),
            16
        )
        )
    {
        return false;
    }

    uint8_t visualHeader[16] = {};

    if (!SafeReadMemory(
        visualSet,
        visualHeader,
        sizeof(visualHeader)
    ))
    {
        return false;
    }

    uint16_t lodCount = 0;
    uint32_t lodArrayRaw = 0;

    std::memcpy(
        &lodCount,
        visualHeader + 0x04,
        2
    );

    std::memcpy(
        &lodArrayRaw,
        visualHeader + 0x0C,
        4
    );

    if (
        lodCount == 0 ||
        lodCount > 32 ||
        lodArrayRaw == 0
        )
    {
        return false;
    }

    bool foundAnything = false;

    for (uint16_t lod = 0; lod < lodCount; lod++)
    {
        const uintptr_t lodPtrAddress =
            static_cast<uintptr_t>(lodArrayRaw) +
            static_cast<uintptr_t>(lod * 4);

        if (!R2R_AddressReadable(lodPtrAddress, 4))
        {
            continue;
        }

        uint32_t geoRaw = 0;

        if (
            !SafeReadMemory(
                reinterpret_cast<void*>(lodPtrAddress),
                &geoRaw,
                4
            ) ||
            geoRaw == 0
            )
        {
            continue;
        }

        void* geo =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(geoRaw)
                );

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(geo),
                0x30
            )
            )
        {
            continue;
        }

        uint8_t geoHeader[0x30] = {};

        if (!SafeReadMemory(
            geo,
            geoHeader,
            sizeof(geoHeader)
        ))
        {
            continue;
        }

        uint32_t typesRaw = 0;
        uint32_t elementsRaw = 0;
        int16_t elementCount = 0;

        std::memcpy(
            &typesRaw,
            geoHeader + 0x10,
            4
        );

        std::memcpy(
            &elementsRaw,
            geoHeader + 0x14,
            4
        );

        std::memcpy(
            &elementCount,
            geoHeader + 0x2E,
            2
        );

        if (
            typesRaw == 0 ||
            elementsRaw == 0 ||
            elementCount <= 0 ||
            elementCount > 64
            )
        {
            continue;
        }

        for (int i = 0; i < elementCount; i++)
        {
            int16_t type = -1;
            uint32_t elementRaw = 0;

            const uintptr_t typeAddress =
                static_cast<uintptr_t>(typesRaw) +
                static_cast<uintptr_t>(i * 2);

            const uintptr_t elementAddress =
                static_cast<uintptr_t>(elementsRaw) +
                static_cast<uintptr_t>(i * 4);

            if (
                !R2R_AddressReadable(typeAddress, 2) ||
                !R2R_AddressReadable(elementAddress, 4) ||
                !SafeReadMemory(
                    reinterpret_cast<void*>(typeAddress),
                    &type,
                    2
                ) ||
                !SafeReadMemory(
                    reinterpret_cast<void*>(elementAddress),
                    &elementRaw,
                    4
                )
                )
            {
                continue;
            }

            if (type != 1 || elementRaw == 0)
            {
                continue;
            }

            void* element =
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(elementRaw)
                    );

            uint32_t gameMaterialRaw = 0;

            if (
                !R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(element),
                    4
                ) ||
                !SafeReadMemory(
                    element,
                    &gameMaterialRaw,
                    4
                ) ||
                gameMaterialRaw == 0
                )
            {
                continue;
            }

            void* gameMaterial =
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(gameMaterialRaw)
                    );

            uint32_t visualMaterialRaw = 0;

            if (
                !R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(gameMaterial),
                    4
                ) ||
                !SafeReadMemory(
                    gameMaterial,
                    &visualMaterialRaw,
                    4
                ) ||
                visualMaterialRaw == 0
                )
            {
                continue;
            }

            void* visualMaterial =
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(visualMaterialRaw)
                    );

            bool alreadyQueued = false;

            for (size_t p = 0; p < visualMaterials.size(); p++)
            {
                if (visualMaterials[p] == visualMaterial)
                {
                    alreadyQueued = true;
                    break;
                }
            }

            if (alreadyQueued)
            {
                continue;
            }

            const uintptr_t textureField =
                reinterpret_cast<uintptr_t>(visualMaterial) +
                0x48;

            if (!R2R_AddressReadable(textureField, 4))
            {
                continue;
            }

            uint32_t originalTextureRaw = 0;

            if (
                !SafeReadMemory(
                    reinterpret_cast<void*>(textureField),
                    &originalTextureRaw,
                    4
                ) ||
                originalTextureRaw == 0
                )
            {
                continue;
            }

            GLI_tdstTexture* originalTexture =
                reinterpret_cast<GLI_tdstTexture*>(
                    static_cast<uintptr_t>(originalTextureRaw)
                    );

            GLI_tdstTexture* fresh =
                R2R_GetOrCreateDonorTextureFromCapturedData(
                    originalTexture,
                    report
                );

            if (fresh == nullptr)
            {
                continue;
            }

            visualMaterials.push_back(
                visualMaterial
            );

            textureFields.push_back(
                textureField
            );

            freshTextures.push_back(
                fresh
            );

            foundAnything = true;
        }
    }

    return foundAnything;
}

static bool R2R_UseAglaglCapturedTexturesThroughCompute()
{
    if (
        g_RuntimeAglaglFamily == nullptr ||
        g_RuntimeAglaglFamily->hDefaultObjectsTable == nullptr
        )
    {
        return false;
    }

    FILE* report = nullptr;

    fopen_s(
        &report,
        R2R_GPU_HANDLE_REPORT_FILE,
        "w"
    );

    // h.7.37: recover the serialized BLUE table by its captured offset from
    // the donor Family BEFORE collecting/rebuilding textures.
    if (!R2R_ApplyCapturedBlueVariantToRuntimeFamily(report))
    {
        if (report != nullptr)
        {
            fprintf(
                report,
                "FATAL: the serialized BLUE gardeo_ table could not be recovered.\n"
            );
            fclose(report);
        }

        return false;
    }

    HIE_tdstObjectsTablesList* aglaglTable =
        g_RuntimeAglaglFamily->hDefaultObjectsTable;

    if (
        aglaglTable == nullptr ||
        aglaglTable->d_stObjectsTable == nullptr ||
        aglaglTable->uwNumberOfElement == 0
        )
    {
        if (report != nullptr)
        {
            fclose(report);
        }
        return false;
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "RAYMAN 2 RANDOMIZER\n"
            "v0.0.14b.0 - CAPTURED TEXTURE + COMPUTETEXTURES TEST\n"
            "============================================================\n\n"
            "h.7.32 proved the loose .GF files are not present at the paths\n"
            "stored in Aglagl's texture names, so every GF read failed.\n\n"
            "This test does NOT read files from disk. It reuses the CPU-side\n"
            "texture data already captured from Water_20, clears only the stale\n"
            "GPU-specific pointer, registers each private clone in Rayman 2's\n"
            "texture table, then calls GLI_vComputeTextures() once.\n\n"
            "h.7.37 BLUE offset captured  : %s\n"
            "h.7.37 BLUE family delta      : 0x%IX\n"
            "h.7.37 default family delta   : 0x%IX\n\n",
            g_R2RBlueVariantCaptured ? "YES" : "NO",
            static_cast<size_t>(g_R2RBlueTableFamilyDelta),
            static_cast<size_t>(g_R2RDefaultTableFamilyDelta)
        );

        fflush(report);
    }

    std::vector<uint16_t> usedIndexes;

    const size_t nttoCount =
        g_A3dDonorNTTO.size() / 6;

    for (size_t i = 0; i < nttoCount; i++)
    {
        const uint8_t* raw =
            g_A3dDonorNTTO.data() + i * 6;

        uint16_t objectIndex = 0;

        std::memcpy(
            &objectIndex,
            raw + 2,
            2
        );

        if (objectIndex >= aglaglTable->uwNumberOfElement)
        {
            continue;
        }

        bool seen = false;

        for (size_t j = 0; j < usedIndexes.size(); j++)
        {
            if (usedIndexes[j] == objectIndex)
            {
                seen = true;
                break;
            }
        }

        if (!seen)
        {
            usedIndexes.push_back(
                objectIndex
            );
        }
    }

    std::vector<void*> visualMaterials;
    std::vector<uintptr_t> textureFields;
    std::vector<GLI_tdstTexture*> freshTextures;

    for (size_t i = 0; i < usedIndexes.size(); i++)
    {
        const uint16_t index =
            usedIndexes[i];

        R2R_CollectTargetTextureReplacement(
            aglaglTable->d_stObjectsTable[index].hTarget,
            visualMaterials,
            textureFields,
            freshTextures,
            report
        );
    }

    if (
        visualMaterials.empty() ||
        g_R2RDonorTextureClones.empty()
        )
    {
        if (report != nullptr)
        {
            fprintf(
                report,
                "RESULT: no donor GF textures could be queued.\n"
            );

            fclose(report);
        }

        return false;
    }

    const long oldNumberToCreate =
        GLI_gs_lNumberOfTextureToCreate != nullptr
        ? *GLI_gs_lNumberOfTextureToCreate
        : 0;

    if (GLI_gs_lNumberOfTextureToCreate != nullptr)
    {
        *GLI_gs_lNumberOfTextureToCreate =
            oldNumberToCreate +
            static_cast<long>(g_R2RDonorTextureClones.size());
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "Queued unique captured textures: %zu\n"
            "Pending material patches       : %zu\n"
            "NumberOfTextureToCreate before : %ld\n"
            "NumberOfTextureToCreate now    : %ld\n\n"
            "Calling GLI_vComputeTextures() now...\n\n",
            g_R2RDonorTextureClones.size(),
            visualMaterials.size(),
            oldNumberToCreate,
            GLI_gs_lNumberOfTextureToCreate != nullptr
            ? *GLI_gs_lNumberOfTextureToCreate
            : 0
        );

        fflush(report);
    }

    // Unlike h.7.31, these textures are now registered in the global texture
    // table before ComputeTextures runs.
    GLI_vComputeTextures();

    bool allGpuHandlesReady = true;

    if (report != nullptr)
    {
        fprintf(
            report,
            "AFTER GLI_vComputeTextures\n"
            "------------------------------------------------------------\n"
        );
    }

    for (size_t i = 0; i < g_R2RDonorTextureClones.size(); i++)
    {
        GLI_tdstTexture* fresh =
            g_R2RDonorTextureClones[i];

        const bool ready =
            fresh != nullptr &&
            fresh->p_stSpecParam != nullptr;

        if (!ready)
        {
            allGpuHandlesReady = false;
        }

        if (report != nullptr)
        {
            fprintf(
                report,
                "[%zu] %s\n"
                "  texture    : %p\n"
                "  GPU param  : %p\n"
                "  available  : %d\n"
                "  status     : %s\n",
                i,
                fresh != nullptr
                ? fresh->szFileName
                : "(null)",
                fresh,
                fresh != nullptr
                ? fresh->p_stSpecParam
                : nullptr,
                fresh != nullptr
                ? static_cast<int>(fresh->bIsAvailable)
                : 0,
                ready
                ? "READY"
                : "NOT READY"
            );
        }
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nAll GPU handles ready: %s\n",
            allGpuHandlesReady
            ? "YES"
            : "NO"
        );

        fflush(report);
    }

    // CRITICAL SAFETY RULE:
    // do not let the renderer see even one NULL fresh texture handle.
    if (!allGpuHandlesReady)
    {
        if (report != nullptr)
        {
            fprintf(
                report,
                "No materials were patched because at least one fresh texture\n"
                "did not receive a GPU handle.\n"
            );

            fclose(report);
        }

        return false;
    }

    unsigned int patchedCount = 0;

    for (size_t i = 0; i < textureFields.size(); i++)
    {
        GLI_tdstTexture* fresh =
            freshTextures[i];

        if (
            fresh == nullptr ||
            fresh->p_stSpecParam == nullptr
            )
        {
            continue;
        }

        const uint32_t freshRaw =
            static_cast<uint32_t>(
                reinterpret_cast<uintptr_t>(fresh)
                );

        std::memcpy(
            reinterpret_cast<void*>(textureFields[i]),
            &freshRaw,
            4
        );

        patchedCount++;
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "Material texture pointers patched: %u\n",
            patchedCount
        );

        fclose(report);
    }

    return patchedCount > 0;
}

static void RunAglaglCapturedTextureComputeTest()
{
    R2R_F6CrashPoint("ENTER RunAglaglCapturedTextureComputeTest");
    R2R_F6CrashPoint("BEFORE R2R_UseAglaglCapturedTexturesThroughCompute");
    const bool textureComputeOK = R2R_UseAglaglCapturedTexturesThroughCompute();
    R2R_F6CrashPoint(textureComputeOK ? "AFTER texture compute = OK" : "AFTER texture compute = FAILED");

    if (!textureComputeOK)
    {
        MessageBoxA(
            nullptr,
            "Aglagl's captured texture data did not produce fresh GPU handles.\n\n"
            "The report was still written. Send me:\n"
            "Rayman2Randomizer_AglaglBlueImportTest.txt",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );

        return;
    }

    R2R_F6CrashPoint("BEFORE Run3DIsolationVariant G1");
    Run3DIsolationVariant(
        R2R_ISO_G1_MERGED_ANIMATION_FOREIGN_TABLE,
        false
    );
    R2R_F6CrashPoint("AFTER Run3DIsolationVariant G1");
}

static bool R2R_PatchTargetTexturesToKnownGood(
    void* target,
    void* knownGoodTexture,
    std::vector<void*>& patchedVisualMaterials,
    unsigned int& patchedCount
)
{
    if (
        target == nullptr ||
        knownGoodTexture == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(target),
            16
        )
        )
    {
        return false;
    }

    uint32_t targetHeader[4] = {};
    if (!SafeReadMemory(target, targetHeader, sizeof(targetHeader)))
    {
        return false;
    }

    void* visualSet =
        reinterpret_cast<void*>(
            static_cast<uintptr_t>(targetHeader[0])
            );

    if (
        visualSet == nullptr ||
        !R2R_AddressReadable(
            reinterpret_cast<uintptr_t>(visualSet),
            16
        )
        )
    {
        return false;
    }

    uint8_t visualHeader[16] = {};
    if (!SafeReadMemory(
        visualSet,
        visualHeader,
        sizeof(visualHeader)
    ))
    {
        return false;
    }

    uint16_t lodCount = 0;
    uint32_t lodArrayRaw = 0;

    std::memcpy(&lodCount, visualHeader + 0x04, 2);
    std::memcpy(&lodArrayRaw, visualHeader + 0x0C, 4);

    if (
        lodCount == 0 ||
        lodCount > 32 ||
        lodArrayRaw == 0
        )
    {
        return false;
    }

    bool changedAnything = false;

    for (uint16_t lod = 0; lod < lodCount; lod++)
    {
        const uintptr_t lodPtrAddress =
            static_cast<uintptr_t>(lodArrayRaw) +
            static_cast<uintptr_t>(lod * 4);

        if (!R2R_AddressReadable(lodPtrAddress, 4))
        {
            continue;
        }

        uint32_t geoRaw = 0;
        if (!SafeReadMemory(
            reinterpret_cast<void*>(lodPtrAddress),
            &geoRaw,
            4
        ) || geoRaw == 0)
        {
            continue;
        }

        void* geo =
            reinterpret_cast<void*>(
                static_cast<uintptr_t>(geoRaw)
                );

        if (
            !R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(geo),
                0x30
            )
            )
        {
            continue;
        }

        uint8_t geoHeader[0x30] = {};
        if (!SafeReadMemory(
            geo,
            geoHeader,
            sizeof(geoHeader)
        ))
        {
            continue;
        }

        uint32_t typesRaw = 0;
        uint32_t elementsRaw = 0;
        int16_t elementCount = 0;

        std::memcpy(&typesRaw, geoHeader + 0x10, 4);
        std::memcpy(&elementsRaw, geoHeader + 0x14, 4);
        std::memcpy(&elementCount, geoHeader + 0x2E, 2);

        if (
            typesRaw == 0 ||
            elementsRaw == 0 ||
            elementCount <= 0 ||
            elementCount > 64
            )
        {
            continue;
        }

        for (int i = 0; i < elementCount; i++)
        {
            int16_t type = -1;
            uint32_t elementRaw = 0;

            const uintptr_t typeAddress =
                static_cast<uintptr_t>(typesRaw) +
                static_cast<uintptr_t>(i * 2);

            const uintptr_t elementAddress =
                static_cast<uintptr_t>(elementsRaw) +
                static_cast<uintptr_t>(i * 4);

            if (
                !R2R_AddressReadable(typeAddress, 2) ||
                !R2R_AddressReadable(elementAddress, 4) ||
                !SafeReadMemory(
                    reinterpret_cast<void*>(typeAddress),
                    &type,
                    2
                ) ||
                !SafeReadMemory(
                    reinterpret_cast<void*>(elementAddress),
                    &elementRaw,
                    4
                )
                )
            {
                continue;
            }

            if (type != 1 || elementRaw == 0)
            {
                continue;
            }

            void* element =
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(elementRaw)
                    );

            if (
                !R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(element),
                    4
                )
                )
            {
                continue;
            }

            uint32_t gameMaterialRaw = 0;
            if (!SafeReadMemory(element, &gameMaterialRaw, 4) || gameMaterialRaw == 0)
            {
                continue;
            }

            void* gameMaterial =
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(gameMaterialRaw)
                    );

            if (
                !R2R_AddressReadable(
                    reinterpret_cast<uintptr_t>(gameMaterial),
                    4
                )
                )
            {
                continue;
            }

            uint32_t visualMaterialRaw = 0;
            if (!SafeReadMemory(
                gameMaterial,
                &visualMaterialRaw,
                4
            ) || visualMaterialRaw == 0)
            {
                continue;
            }

            void* visualMaterial =
                reinterpret_cast<void*>(
                    static_cast<uintptr_t>(visualMaterialRaw)
                    );

            bool alreadyPatched = false;

            for (size_t p = 0; p < patchedVisualMaterials.size(); p++)
            {
                if (patchedVisualMaterials[p] == visualMaterial)
                {
                    alreadyPatched = true;
                    break;
                }
            }

            if (alreadyPatched)
            {
                continue;
            }

            const uintptr_t textureField =
                reinterpret_cast<uintptr_t>(visualMaterial) +
                0x48;

            if (!R2R_AddressReadable(textureField, 4))
            {
                continue;
            }

            const uint32_t textureRaw =
                static_cast<uint32_t>(
                    reinterpret_cast<uintptr_t>(
                        knownGoodTexture
                        )
                    );

            std::memcpy(
                reinterpret_cast<void*>(textureField),
                &textureRaw,
                4
            );

            patchedVisualMaterials.push_back(
                visualMaterial
            );

            patchedCount++;
            changedAnything = true;
        }
    }

    return changedAnything;
}

static bool R2R_UsePiranhaTextureOnAglagl()
{
    HIE_tdstSuperObject* nativeSuper = nullptr;
    HIE_tdstEngineObject* nativeActor = nullptr;
    const char* nativeModel = nullptr;

    if (
        !FindBast20ControlSource(
            nativeSuper,
            nativeActor,
            nativeModel
        ) ||
        nativeActor == nullptr ||
        nativeActor->h3dData == nullptr ||
        g_RuntimeAglaglFamily == nullptr ||
        g_RuntimeAglaglFamily->hDefaultObjectsTable == nullptr
        )
    {
        return false;
    }

    HIE_tdstObjectsTablesList* nativeTable =
        nativeActor->h3dData->h_CurrentObjectsTable != nullptr
        ? nativeActor->h3dData->h_CurrentObjectsTable
        : nativeActor->h3dData->h_InitialObjectsTable;

    if (
        nativeTable == nullptr ||
        nativeTable->d_stObjectsTable == nullptr ||
        nativeTable->uwNumberOfElement == 0
        )
    {
        return false;
    }

    void* knownGoodTexture =
        R2R_FindFirstTextureFromTarget(
            nativeTable->d_stObjectsTable[0].hTarget
        );

    if (knownGoodTexture == nullptr)
    {
        return false;
    }

    HIE_tdstObjectsTablesList* aglaglTable =
        g_RuntimeAglaglFamily->hDefaultObjectsTable;

    if (
        aglaglTable->d_stObjectsTable == nullptr ||
        aglaglTable->uwNumberOfElement == 0
        )
    {
        return false;
    }

    std::vector<uint16_t> usedIndexes;

    const size_t nttoCount =
        g_A3dDonorNTTO.size() / 6;

    for (size_t i = 0; i < nttoCount; i++)
    {
        const uint8_t* raw =
            g_A3dDonorNTTO.data() + i * 6;

        uint16_t objectIndex = 0;
        std::memcpy(
            &objectIndex,
            raw + 2,
            2
        );

        if (objectIndex >= aglaglTable->uwNumberOfElement)
        {
            continue;
        }

        bool seen = false;

        for (size_t j = 0; j < usedIndexes.size(); j++)
        {
            if (usedIndexes[j] == objectIndex)
            {
                seen = true;
                break;
            }
        }

        if (!seen)
        {
            usedIndexes.push_back(objectIndex);
        }
    }

    std::vector<void*> patchedVisualMaterials;
    unsigned int patchedCount = 0;

    for (size_t i = 0; i < usedIndexes.size(); i++)
    {
        const uint16_t index =
            usedIndexes[i];

        R2R_PatchTargetTexturesToKnownGood(
            aglaglTable->d_stObjectsTable[index].hTarget,
            knownGoodTexture,
            patchedVisualMaterials,
            patchedCount
        );
    }

    FILE* report = nullptr;
    fopen_s(
        &report,
        "Rayman2Randomizer_AglaglTextureSwap.txt",
        "w"
    );

    if (report != nullptr)
    {
        fprintf(
            report,
            "RAYMAN 2 RANDOMIZER\n"
            "v0.0.14b.0 - BLUE AGLAGL AI EXECUTION-MODE SYNC\n"
            "============================================================\n\n"
            "Known visible Bast object : %s\n"
            "Known good texture        : %p\n"
            "Aglagl visual materials patched : %u\n\n"
            "Only Aglagl's PRIVATE copied material data was changed.\n"
            "Native Bast_20 data was not modified.\n",
            nativeModel != nullptr
            ? nativeModel
            : "(unknown)",
            knownGoodTexture,
            patchedCount
        );

        fclose(report);
    }

    return patchedCount > 0;
}

static void RunAglaglKnownGoodTextureVisibilityTest()
{
    if (!R2R_UsePiranhaTextureOnAglagl())
    {
        MessageBoxA(
            nullptr,
            "I could not prepare the temporary Piranha texture test.\n\n"
            "Restart Rayman 2 and repeat the normal steps.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    Run3DIsolationVariant(
        R2R_ISO_G1_MERGED_ANIMATION_FOREIGN_TABLE,
        false
    );
}

// F6 owns preparation and then runs the active Aglagl visual test.
void RunHybridForeign3DNativeRuntime()
{
    R2R_F6CrashPoint("ENTER RunHybridForeign3DNativeRuntime");

    if (!g_A3dMergedBankInstalled)
    {
        MessageBoxA(
            nullptr,
            "The copied Aglagl animation is not installed yet.\n\n"
            "Easy order:\n"
            "1. F1 -> Water_20, then F7\n"
            "2. F2 -> Bast_20, then F7\n"
            "3. THEN use F6 three times.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONINFORMATION
        );
        return;
    }

    bool preparationStageCompleted = false;

    R2R_F6CrashPoint("BEFORE EnsureForeign3DHybridPrepared");
    const bool prepReady = EnsureForeign3DHybridPrepared(preparationStageCompleted);
    R2R_F6CrashPoint(prepReady ? "AFTER EnsureForeign3DHybridPrepared = READY" : "AFTER EnsureForeign3DHybridPrepared = NOT READY");

    if (!prepReady)
    {
        if (preparationStageCompleted)
        {
            const char* stageMessage =
                g_F6PreparationStage == 1
                ? "STEP 1/2 DONE.\n\nAglagl's basic game data is ready.\n\nWait until Rayman moves normally again, then press F6 one more time."
                : "STEP 2/2 DONE.\n\nAglagl is ready.\n\nWait until Rayman moves normally again, then press F6 a THIRD time.\n\nThe third F6 will spawn BLUE Aglagl, clone his Brain, find Bast_20's two native CHG_TexteMenu actors, bind DSG Perso #14/#15 to those native SuperObjects, then run the guarded full AI + mechanics + animation test with donor ActionRef animations temporarily substituted by the known-safe imported idle animation.";

            MessageBoxA(
                nullptr,
                stageMessage,
                "Rayman 2 Randomizer v0.0.14b.0",
                MB_OK | MB_ICONINFORMATION
            );
        }
        else
        {
            MessageBoxA(
                nullptr,
                "Preparation failed.\n\nRestart Rayman 2 and repeat the test from Water_20.",
                "Rayman 2 Randomizer v0.0.14b.0",
                MB_OK | MB_ICONWARNING
            );
        }

        return;
    }

    // h.7.34:
    // F3 in Water_20 can now capture the REAL blue boss's ObjectsTable
    // index. The texture-compute path will apply that variant before spawn.
    R2R_F6CrashPoint("BEFORE RunAglaglCapturedTextureComputeTest");
    RunAglaglCapturedTextureComputeTest();
    R2R_F6CrashPoint("AFTER RunAglaglCapturedTextureComputeTest");
}

void RunHybridNative3DForeignRuntime()
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(
            GAM_g_stEngineStructure->szLevelName,
            "Bast_20"
        ) != 0
        )
    {
        return;
    }

    if (g_HybridProbeDone)
    {
        MessageBoxA(
            nullptr,
            "A hybrid test has already run in this process.\n\nRestart Rayman 2 before another hybrid test.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    if (
        !g_AglaglPrepared ||
        g_AglaglTemplate == nullptr ||
        g_AglaglModelType == GAM_C_InvalidObjectType
        )
    {
        MessageBoxA(
            nullptr,
            "TEST B requires F9 first.\n\nF12 is NOT required for Test B.\nDo not use F5.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    HIE_tdstSuperObject* nativeSuper = nullptr;
    HIE_tdstEngineObject* nativeActor = nullptr;
    const char* nativeModel = nullptr;

    if (
        !FindBast20ControlSource(
            nativeSuper,
            nativeActor,
            nativeModel
        ) ||
        nativeActor == nullptr ||
        nativeActor->h3dData == nullptr ||
        nativeActor->h3dData->h_Family == nullptr
        )
    {
        MessageBoxA(
            nullptr,
            "Could not find a valid native Bast_20 control actor.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONERROR
        );
        return;
    }

    g_HybridProbeDone = true;

    FILE* report = nullptr;
    fopen_s(&report, HYBRID_FOREIGN_RUNTIME_REPORT, "w");

    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - HYBRID TEST B: NATIVE 3D / FOREIGN RUNTIME\n"
        "============================================================\n\n"
        "Current Level       : Bast_20\n"
        "Native 3D source    : %s\n"
        "Foreign Brain/Dynam : Water_20 STN_ouodeugwod\n"
        "Alias ModelType     : %ld\n\n",
        nativeModel != nullptr ? nativeModel : "(unknown)",
        g_AglaglModelType
    );
    fflush(report);

    g_HybridTemplate =
        BuildRuntimeTemplateFromNativeSource(
            nativeActor,
            g_AglaglModelType
        );

    if (
        g_HybridTemplate == nullptr ||
        g_HybridTemplate->hStandardGame == nullptr ||
        g_HybridTemplate->h3dData == nullptr
        )
    {
        fprintf(report, "TEMPLATE BUILD FAILED.\n");
        fclose(report);
        return;
    }

    fprintf(report, "STEP 1: COPYING FOREIGN BRAIN...\n");
    fflush(report);
    AI_fn_vBrainCopyClone(
        g_HybridTemplate,
        g_AglaglTemplate
    );
    fprintf(report, "STEP 1 RETURNED.\n");
    fflush(report);

    fprintf(report, "STEP 2: COPYING FOREIGN DYNAMICS...\n");
    fflush(report);
    DNM_fn_vDynamCopyClone(
        g_HybridTemplate,
        g_AglaglTemplate
    );
    fprintf(report, "STEP 2 RETURNED.\n");
    fflush(report);

    // Re-apply ONLY the native Bast_20 3D side.
    HIE_tdstFamilyList* family =
        nativeActor->h3dData->h_Family;

    g_HybridTemplate->h3dData->h_Family =
        family;
    g_HybridTemplate->h3dData->h_InitialObjectsTable =
        family->hDefaultObjectsTable;
    g_HybridTemplate->h3dData->h_CurrentObjectsTable =
        family->hDefaultObjectsTable;
    g_HybridTemplate->h3dData->h_InitialState =
        family->stForStateArray.hFirstElementSta;
    g_HybridTemplate->h3dData->h_CurrentState =
        family->stForStateArray.hFirstElementSta;
    g_HybridTemplate->h3dData->h_FirstStateOfAction =
        family->stForStateArray.hFirstElementSta;
    g_HybridTemplate->h3dData->ulNumberOfChannels =
        family->ulNumberOfChannels;

    // Keep the native 3D Family type for this isolation test.
    g_HybridTemplate->hStandardGame->lObjectFamilyType =
        nativeActor->hStandardGame->lObjectFamilyType;
    g_HybridTemplate->hStandardGame->lObjectModelType =
        g_AglaglModelType;
    g_HybridTemplate->hStandardGame->lObjectPersonalType =
        nativeActor->hStandardGame->lObjectPersonalType;

    fprintf(
        report,
        "HYBRID TEMPLATE READY\n"
        "  Template   : %p\n"
        "  3D Family  : %p [NATIVE]\n"
        "  3D State   : %p [NATIVE]\n"
        "  3D Table   : %p [NATIVE]\n"
        "  Brain      : %p [FOREIGN]\n"
        "  AIModel    : %p [FOREIGN]\n"
        "  Dynam      : %p [FOREIGN]\n\n",
        g_HybridTemplate,
        g_HybridTemplate->h3dData->h_Family,
        g_HybridTemplate->h3dData->h_InitialState,
        g_HybridTemplate->h3dData->h_InitialObjectsTable,
        g_HybridTemplate->hBrain,
        (
            g_HybridTemplate->hBrain != nullptr &&
            g_HybridTemplate->hBrain->p_stMind != nullptr
            )
        ? g_HybridTemplate->hBrain->p_stMind->p_stAIModel
        : nullptr,
        g_HybridTemplate->hDynam
    );
    fflush(report);
    fclose(report);

    const bool spawned =
        SpawnHybridShell(
            g_HybridTemplate,
            HYBRID_FOREIGN_RUNTIME_REPORT,
            "TEST B - NATIVE 3D / FOREIGN BRAIN+DYNAM"
        );

    MessageBoxA(
        nullptr,
        spawned
        ? "HYBRID TEST B SPAWNED.\n\nNATIVE Bast_20 3D\n+ FOREIGN Water_20 Brain/Dynamics\n\nClose this box and try moving Rayman.\nIf responsive, press F11."
        : "HYBRID TEST B DID NOT COMPLETE.\n\nSend me the report.",
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | (spawned ? MB_ICONINFORMATION : MB_ICONWARNING)
    );
}

void DestroyHybridSafely()
{
    // h.7.26: restore the runtime Family before any kill/unregister path.
    R2R_RestoreRuntimeFamilyDefaultTable();

    if (
        g_SpawnedHybrid == nullptr ||
        g_SpawnedHybridActor == nullptr
        )
    {
        MessageBoxA(
            nullptr,
            "There is no live hybrid object to destroy.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONINFORMATION
        );
        return;
    }

    // Critical h.6 safety fix:
    // if the spawned object died by normal gameplay, its saved pointer
    // must NOT be passed to the kill function a second time.
    if (
        !IsAlwaysObjectStillLive(
            g_SpawnedHybrid,
            g_SpawnedHybridActor
        )
        )
    {
        g_SpawnedHybrid = nullptr;
        g_SpawnedHybridActor = nullptr;
        UnregisterRuntimeAglaglFamilySilently();

        MessageBoxA(
            nullptr,
            "The hybrid object is already gone.\n\nF11 did NOT call the kill function, so no double-kill was attempted.\n\nThe temporary garde_tfeu Family was also unregistered.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONINFORMATION
        );
        return;
    }

    if (R2_KillEngineObjectOrAlwaysByPointer == nullptr)
    {
        MessageBoxA(
            nullptr,
            "The kill function is unavailable.\n\nRestart the game instead.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    R2_KillEngineObjectOrAlwaysByPointer(
        g_SpawnedHybridActor
    );

    g_SpawnedHybrid = nullptr;
    g_SpawnedHybridActor = nullptr;
    UnregisterRuntimeAglaglFamilySilently();

    MessageBoxA(
        nullptr,
        "HYBRID OBJECT DESTROYED SAFELY!\n\nThe temporary garde_tfeu Family was also unregistered.\nYou can now change level or use Abandon safely for this probe.",
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | MB_ICONINFORMATION
    );
}

void RunSameMapNormalizedControl()
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying
        )
    {
        return;
    }

    if (
        _stricmp(
            GAM_g_stEngineStructure->szLevelName,
            "Bast_20"
        ) != 0
        )
    {
        MessageBoxA(
            nullptr,
            "This control test must run in Bast_20.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );

        return;
    }

    if (g_ControlProbeDone)
    {
        MessageBoxA(
            nullptr,
            "F10 has already been used in this process.\n\nRestart Rayman 2 before repeating it.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONWARNING
        );

        return;
    }

    if (g_SpawnedControl != nullptr)
    {
        return;
    }

    HIE_tdstSuperObject* sourceSO = nullptr;
    HIE_tdstEngineObject* source = nullptr;
    const char* sourceModelName = nullptr;

    if (
        !FindBast20ControlSource(
            sourceSO,
            source,
            sourceModelName
        )
        )
    {
        MessageBoxA(
            nullptr,
            "Could not find the Bast_20 Piranha or pirate control source.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONERROR
        );

        return;
    }

    if (
        source == nullptr ||
        source->hStandardGame == nullptr ||
        source->h3dData == nullptr ||
        source->h3dData->h_Family == nullptr
        )
    {
        MessageBoxA(
            nullptr,
            "The native control source is incomplete.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONERROR
        );

        return;
    }

    const long aliasModelType =
        EnsureModelType(
            "R2R_NATIVE_CONTROL_MODEL"
        );

    if (aliasModelType == GAM_C_InvalidObjectType)
    {
        MessageBoxA(
            nullptr,
            "Could not create the temporary control ModelType.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONERROR
        );

        return;
    }

    g_ControlProbeDone = true;

    FILE* report = nullptr;
    fopen_s(&report, CONTROL_REPORT_FILE, "w");

    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - SAME-MAP NORMALIZED CONTROL\n"
        "============================================================\n\n"
        "Current Level     : %s\n"
        "Source Model      : %s\n"
        "Source SuperObj   : %p\n"
        "Source EngineObj  : %p\n"
        "Source FamilyType : %ld\n"
        "Source ModelType  : %ld\n"
        "Control ModelType : %ld\n\n",
        GAM_g_stEngineStructure->szLevelName,
        sourceModelName != nullptr ? sourceModelName : "(null)",
        sourceSO,
        source,
        source->hStandardGame->lObjectFamilyType,
        source->hStandardGame->lObjectModelType,
        aliasModelType
    );

    fflush(report);

    g_ControlTemplate =
        BuildRuntimeTemplateFromNativeSource(
            source,
            aliasModelType
        );

    fprintf(
        report,
        "STEP 1: RUNTIME TEMPLATE BUILD\n"
        "  Template : %p\n"
        "  StdGame  : %p\n"
        "  3dData   : %p\n"
        "  Brain    : %p\n"
        "  Dynam    : %p\n"
        "  CollSet  : %p\n"
        "  SectInfo : %p\n\n",
        g_ControlTemplate,
        g_ControlTemplate != nullptr ? g_ControlTemplate->hStandardGame : nullptr,
        g_ControlTemplate != nullptr ? g_ControlTemplate->h3dData : nullptr,
        g_ControlTemplate != nullptr ? g_ControlTemplate->hBrain : nullptr,
        g_ControlTemplate != nullptr ? g_ControlTemplate->hDynam : nullptr,
        g_ControlTemplate != nullptr ? g_ControlTemplate->hCollSet : nullptr,
        g_ControlTemplate != nullptr ? g_ControlTemplate->hSectInfo : nullptr
    );

    fflush(report);

    if (
        g_ControlTemplate == nullptr ||
        g_ControlTemplate->hStandardGame == nullptr ||
        g_ControlTemplate->h3dData == nullptr ||
        g_ControlTemplate->hBrain == nullptr ||
        g_ControlTemplate->hDynam == nullptr
        )
    {
        fprintf(report, "RESULT: RUNTIME TEMPLATE BUILD FAILED\n");
        fclose(report);
        return;
    }

    fprintf(report, "STEP 2: CALLING AI_fn_vBrainCopyClone NOW...\n");
    fflush(report);

    AI_fn_vBrainCopyClone(
        g_ControlTemplate,
        source
    );

    fprintf(
        report,
        "STEP 2 RETURNED\n"
        "  AIModel : %p\n"
        "  DsgMem  : %p\n\n",
        (
            g_ControlTemplate->hBrain != nullptr &&
            g_ControlTemplate->hBrain->p_stMind != nullptr
            )
        ? g_ControlTemplate->hBrain->p_stMind->p_stAIModel
        : nullptr,
        (
            g_ControlTemplate->hBrain != nullptr &&
            g_ControlTemplate->hBrain->p_stMind != nullptr
            )
        ? g_ControlTemplate->hBrain->p_stMind->p_stDsgMem
        : nullptr
    );

    fflush(report);

    fprintf(report, "STEP 3: CALLING DNM_fn_vDynamCopyClone NOW...\n");
    fflush(report);

    DNM_fn_vDynamCopyClone(
        g_ControlTemplate,
        source
    );

    fprintf(
        report,
        "STEP 3 RETURNED\n"
        "  Dynamics     : %p\n"
        "  ParsingDatas : %p\n\n",
        g_ControlTemplate->hDynam != nullptr
        ? g_ControlTemplate->hDynam->p_stDynamics
        : nullptr,
        g_ControlTemplate->hDynam != nullptr
        ? g_ControlTemplate->hDynam->p_stParsingDatas
        : nullptr
    );

    fflush(report);

    // Re-apply native static roots after the copy helpers.
    HIE_tdstFamilyList* family = source->h3dData->h_Family;

    g_ControlTemplate->h3dData->h_Family = family;
    g_ControlTemplate->h3dData->h_InitialObjectsTable = family->hDefaultObjectsTable;
    g_ControlTemplate->h3dData->h_CurrentObjectsTable = family->hDefaultObjectsTable;
    g_ControlTemplate->h3dData->h_InitialState = family->stForStateArray.hFirstElementSta;
    g_ControlTemplate->h3dData->h_CurrentState = family->stForStateArray.hFirstElementSta;
    g_ControlTemplate->h3dData->h_FirstStateOfAction = family->stForStateArray.hFirstElementSta;
    g_ControlTemplate->h3dData->ulNumberOfChannels = family->ulNumberOfChannels;

    g_ControlTemplate->hStandardGame->lObjectFamilyType =
        source->hStandardGame->lObjectFamilyType;

    g_ControlTemplate->hStandardGame->lObjectModelType =
        aliasModelType;

    g_ControlTemplate->hStandardGame->lObjectPersonalType =
        source->hStandardGame->lObjectPersonalType;

    g_ControlTemplate->hStandardGame->ulCustomBits |=
        (
            Std_C_CustBit_NoAI |
            Std_C_CustBit_NoMechanic |
            Std_C_CustBit_NoAnimPlayer |
            Std_C_CustBit_OutOfVisibility
            );

    const unsigned char sourceFlags =
        source->hStandardGame->ucMiscFlags;

    g_ControlTemplate->hStandardGame->ucMiscFlags =
        sourceFlags;

    ALW_tdstAlwaysModelList* node =
        AddTemporaryAlwaysTemplateGeneric(
            aliasModelType,
            g_ControlTemplate
        );

    if (node == nullptr)
    {
        fprintf(report, "STEP 4 FAILED: temporary Always node\n");
        fclose(report);
        return;
    }

    fprintf(
        report,
        "STEP 4: TEMPORARY ALWAYS ENTRY CREATED\n"
        "  Node     : %p\n"
        "  Template : %p\n\n",
        node,
        g_ControlTemplate
    );

    fflush(report);

    const unsigned char originalFlags =
        g_ControlTemplate->hStandardGame->ucMiscFlags;

    g_ControlTemplate->hStandardGame->ucMiscFlags |=
        Std_C_MiscFlag_Always;

    HIE_tdstSuperObject* mainActor = HIE_M_hGetMainActor();

    if (
        mainActor == nullptr ||
        mainActor->p_stGlobalMatrix == nullptr ||
        GAM_g_p_stDynamicWorld == nullptr ||
        *GAM_g_p_stDynamicWorld == nullptr
        )
    {
        g_ControlTemplate->hStandardGame->ucMiscFlags = originalFlags;
        RemoveTemporaryAlwaysTemplate(node);
        fprintf(report, "STEP 5 FAILED: live world pointers\n");
        fclose(report);
        return;
    }

    POS_tdstCompletePosition position =
        *mainActor->p_stGlobalMatrix;

    // h.7.23: put the known-visible Piranha on the OPPOSITE side of Rayman.
    // Aglagl remains at +4.0 X; the Piranha goes to -4.0 X.
    position.stPos.x -= 4.0f;

    fprintf(
        report,
        "STEP 5: CALLING ALW_fn_p_stAllocateAlways NOW...\n"
        "  Spawn XYZ : %.3f %.3f %.3f\n",
        position.stPos.x,
        position.stPos.y,
        position.stPos.z
    );

    fflush(report);

    HIE_tdstSuperObject* spawned =
        ALW_fn_p_stAllocateAlways(
            aliasModelType,
            *GAM_g_p_stDynamicWorld,
            mainActor,
            0,
            &position
        );

    g_ControlTemplate->hStandardGame->ucMiscFlags =
        originalFlags;

    RemoveTemporaryAlwaysTemplate(node);

    fprintf(
        report,
        "STEP 5 RETURNED\n"
        "  SuperObject : %p\n\n",
        spawned
    );

    fflush(report);

    if (spawned == nullptr)
    {
        fprintf(report, "RESULT: ALW RETURNED NULL - GAME SURVIVED\n");
        fclose(report);
        return;
    }

    HIE_tdstEngineObject* spawnedActor =
        HIE_M_hSuperObjectGetActor(spawned);

    if (
        spawnedActor == nullptr ||
        spawnedActor->hStandardGame == nullptr
        )
    {
        fprintf(report, "RESULT: SPAWNED SHELL INCOMPLETE\n");
        fclose(report);
        return;
    }

    GAM_tdstStandardGame* spawnedStd =
        spawnedActor->hStandardGame;

    const unsigned long beforeBits = spawnedStd->ulCustomBits;
    const unsigned char beforeFlags = spawnedStd->ucMiscFlags;

    // h.7.16 visibility control:
    // Keep AI and movement disabled, but turn the normal animation/display
    // back on. This uses ONLY a native Bast_20 object, so if this is visible
    // then our generic spawn/display path is good and the remaining problem
    // is specifically Aglagl's imported visual data.
    spawnedStd->ulCustomBits &=
        ~(
            Std_C_CustBit_NoAnimPlayer |
            Std_C_CustBit_UnseenFrozenAnimPlayer |
            Std_C_CustBit_UnseenFrozen |
            Std_C_CustBit_OutOfVisibility
            );

    spawnedStd->ulCustomBits |=
        (
            Std_C_CustBit_NoAI |
            Std_C_CustBit_NoMechanic
            );

    spawnedStd->ucMiscFlags &=
        ~(
            Std_C_MiscFlag_DesactivateAtAll |
            Std_C_MiscFlag_TooFar
            );

    spawnedStd->ucMiscFlags |=
        (
            Std_C_MiscFlag_Activable |
            Std_C_MiscFlag_Active |
            Std_C_MiscFlag_Always |
            Std_C_MiscFlag_AlwaysActive |
            Std_C_MiscFlag_UselessCulling
            );

    g_SpawnedControl = spawned;

    fprintf(
        report,
        "STEP 6: SAME-MAP VISIBLE CONTROL ENABLED\n"
        "  Spawned Engine : %p\n"
        "  Family         : %ld\n"
        "  Model          : %ld\n"
        "  Personal       : %ld\n"
        "  Custom before  : 0x%08X\n"
        "  Custom after   : 0x%08X\n"
        "  Misc before    : 0x%02X\n"
        "  Misc after     : 0x%02X\n\n"
        "RESULT\n"
        "------------------------------------------------------------\n"
        "SAME-MAP NORMALIZED ALWAYS SHELL LEFT ALIVE\n\n"
        "If the game remains responsive after closing the dialog,\n"
        "the normalized runtime/Always path itself is stable.\n"
        "Press F11 to destroy the control shell after a few seconds.\n",
        spawnedActor,
        spawnedStd->lObjectFamilyType,
        spawnedStd->lObjectModelType,
        spawnedStd->lObjectPersonalType,
        static_cast<unsigned int>(beforeBits),
        static_cast<unsigned int>(spawnedStd->ulCustomBits),
        static_cast<unsigned int>(beforeFlags),
        static_cast<unsigned int>(spawnedStd->ucMiscFlags)
    );

    fflush(report);
    fclose(report);

    MessageBoxA(
        nullptr,
        "VISIBLE CONTROL CREATED!\n\n"
        "Close this box and look around Rayman.\n\n"
        "A normal Bast_20 enemy/object should now be visible a few steps beside Rayman.\n"
        "It will NOT move or attack because its AI is disabled.\n\n"
        "When you are done looking, press F11 to remove it.\n\n"
        "Tell me only: VISIBLE or INVISIBLE.",
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | MB_ICONINFORMATION
    );
}

void DestroySameMapControl()
{
    if (g_SpawnedControl == nullptr)
    {
        return;
    }

    if (R2_KillEngineObjectOrAlwaysByPointer == nullptr)
    {
        return;
    }

    HIE_tdstEngineObject* actor =
        HIE_M_hSuperObjectGetActor(g_SpawnedControl);

    if (actor != nullptr)
    {
        R2_KillEngineObjectOrAlwaysByPointer(actor);
    }

    g_SpawnedControl = nullptr;

    MessageBoxA(
        nullptr,
        "SAME-MAP CONTROL OBJECT DESTROYED.\n\n"
        "If Rayman is still playable, the control test fully passed.",
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | MB_ICONINFORMATION
    );
}


// ============================================================
// h.7.12 - COPIED AGLAGL ANIMATION BANK + ONE-FRAME TEST
// ============================================================

static const char* A3D_MERGED_BANK_REPORT_FILE =
"Rayman2Randomizer_A3dMergedBank.txt";


bool R2R_WriteGlobal32(uintptr_t slot, uint32_t value)
{
    DWORD oldProtect = 0;
    if (!VirtualProtect(
        reinterpret_cast<void*>(slot),
        sizeof(value),
        PAGE_READWRITE,
        &oldProtect
    ))
    {
        return false;
    }

    *reinterpret_cast<volatile uint32_t*>(slot) = value;

    DWORD ignored = 0;
    VirtualProtect(
        reinterpret_cast<void*>(slot),
        sizeof(value),
        oldProtect,
        &ignored
    );

    return true;
}


// ============================================================
// y.20: ACTOR + STATIC LEVEL SECTOR TEXTURE RANDOMIZER (Textures=1)
// Reuse the proven y19 material/GPU compatibility validator and pointer
// restoration. New: scan render materials of static PO / IPO objects under
// GAM_g_p_stFatherSector (the actual map sectors), never collisions/UVs.
// No import/file writes, no UI/menu changes, no pointers to unloaded GPU
// resources. Restore on world/sector reload or when config is disabled.
// ============================================================
struct R2R_Tex18Entry
{
    uintptr_t field;
    uint32_t nativeTexture;
    uint32_t currentTexture;
    uint16_t width, height, realWidth, realHeight;
    uint32_t caps;
    bool palette;
    bool terrain; // y20: originated from static sector geometry (may also appear on actors)
    char filename[128];
    R2R_Tex18Entry() : field(0), nativeTexture(0), currentTexture(0),
        width(0), height(0), realWidth(0), realHeight(0), caps(0), palette(false), terrain(false)
    { filename[0]=0; }
};
static std::vector<R2R_Tex18Entry> g_R2RTex18;
static char g_R2RTex18Level[64] = {};
static HIE_tdstSuperObject* g_R2RTex18World = nullptr;
static HIE_tdstSuperObject* g_R2RTex18Inactive = nullptr;
static HIE_tdstSuperObject* g_R2RTex20SectorRoot = nullptr;
static unsigned int g_R2RTex20Nodes=0, g_R2RTex20Sectors=0;
static unsigned int g_R2RTex20POs=0, g_R2RTex20IPOs=0;
static unsigned int g_R2RTex20BadPointers=0;
static unsigned int g_R2RTex20TerrainFields=0, g_R2RTex20ActorFields=0;
static unsigned int g_R2RTex20Budget=0;
static bool g_R2RTex20ScanningTerrain=false;
static const unsigned int R2R_TEX20_MAX_MATERIALS=3600u;

static uint32_t g_R2RTex18Seed = 0;
static unsigned int g_R2RTex18Frame = 0;
static bool g_R2RTex18Scanned = false;
static unsigned int g_R2RTex18Budget = 0;
static const char* R2R_TEX18_REPORT = "Rayman2Randomizer_Textures.txt";
static unsigned int g_R2RTex19Nodes=0, g_R2RTex19Actors=0;
static unsigned int g_R2RTex19Tables=0, g_R2RTex19Targets=0;
static unsigned int g_R2RTex19Visuals=0, g_R2RTex19Geometries=0;
static unsigned int g_R2RTex19Triangles=0, g_R2RTex19Fields=0;
static unsigned int g_R2RTex19InvalidTexture=0;
static unsigned int g_R2RTex19FormatRejected=0, g_R2RTex19MissingGPU=0;
static unsigned int g_R2RTex19DimensionRejected=0;
static unsigned int g_R2RTex19Duplicate=0;
static unsigned int g_R2RTex19LastConfig=0xFFFFFFFFu;
static bool g_R2RTex19Opened=false;
static void R2R_Tex19ReportConfig()
{
    const unsigned int mask = (g_R2RConfig.enabled?1u:0u) |
                              (g_R2RConfig.textures?2u:0u);
    if(g_R2RTex19LastConfig==mask)return;
    g_R2RTex19LastConfig=mask;
    FILE* f=nullptr;
    fopen_s(&f,R2R_TEX18_REPORT,g_R2RTex19Opened?"a":"w");
    if(!f)return;
    g_R2RTex19Opened=true;
    fprintf(f,"RAYMAN 2 RANDOMIZER - %s\n",VERSION);
    fprintf(f,"[TEXTURE-CONFIG] Enabled=%u Textures=%u seed=%u\n",
        g_R2RConfig.enabled?1u:0u,g_R2RConfig.textures?1u:0u,g_R2RConfig.seed);
    if(!g_R2RConfig.enabled || !g_R2RConfig.textures)
        fprintf(f,"[TEXTURE-OFF] Set [Randomizer] Enabled=1 and Textures=1 in Rayman2Randomizer.ini, then press F5.\n");
    fclose(f);
}
static void R2R_Tex19ResetCounters()
{
    g_R2RTex19Nodes=0;g_R2RTex19Actors=0;g_R2RTex19Tables=0;
    g_R2RTex19Targets=0;g_R2RTex19Visuals=0;g_R2RTex19Geometries=0;
    g_R2RTex19Triangles=0;g_R2RTex19Fields=0;g_R2RTex19InvalidTexture=0;
    g_R2RTex19FormatRejected=0;g_R2RTex19MissingGPU=0;
    g_R2RTex19DimensionRejected=0;g_R2RTex19Duplicate=0;
}


static bool R2R_Tex18Read32(uintptr_t address, uint32_t& out)
{
    return address >= 0x10000u && R2R_AddressReadable(address, 4u) &&
        SafeReadMemory(reinterpret_cast<const void*>(address), &out, 4u);
}
static bool R2R_Tex18Decode(uint32_t raw, R2R_Tex18Entry& item)
{
    if(raw < 0x10000u || !R2R_AddressReadable(static_cast<uintptr_t>(raw), sizeof(GLI_tdstTexture)))
    { ++g_R2RTex19InvalidTexture; return false; }
    GLI_tdstTexture tex = {};
    if(!SafeReadMemory(reinterpret_cast<void*>(static_cast<uintptr_t>(raw)), &tex, sizeof(tex)))
    { ++g_R2RTex19InvalidTexture; return false; }
    if(!tex.bIsAvailable || tex.p_stSpecParam == nullptr)
    { ++g_R2RTex19MissingGPU; return false; }
    // Don't override textures which the engine already substitutes (sprites, etc.).
    if(tex.p_TextureOfSubstitution != nullptr)
    { ++g_R2RTex19FormatRejected; return false; }
    const uint8_t* bytes = reinterpret_cast<const uint8_t*>(&tex);
    uint16_t h=0,w=0,rh=0,rw=0;
    uint32_t caps=0, palette=0;
    std::memcpy(&h,bytes+0x18,2);std::memcpy(&w,bytes+0x1A,2);
    std::memcpy(&rh,bytes+0x1C,2);std::memcpy(&rw,bytes+0x1E,2);
    std::memcpy(&caps,bytes+0x14,4);
    std::memcpy(&palette,bytes+0x0C,4);
    if(w<8 || h<8 || w>2048 || h>2048 || !rw || !rh || rw>2048 || rh>2048 ||
       (w&(w-1)) || (h&(h-1)))
    { ++g_R2RTex19DimensionRejected; return false; }
    if(std::memchr(tex.szFileName, 0, sizeof(tex.szFileName)) == nullptr || tex.szFileName[0] == 0)
    { ++g_R2RTex19FormatRejected; return false; }
    item.nativeTexture=raw;item.currentTexture=raw;
    item.width=w;item.height=h;item.realWidth=rw;item.realHeight=rh;
    item.caps=caps;item.palette=palette!=0;
    strncpy_s(item.filename,sizeof(item.filename),tex.szFileName,_TRUNCATE);
    return true;
}
static void R2R_Tex18CollectMaterial(uintptr_t field)
{
    if(!field || g_R2RTex18.size()>=R2R_TEX20_MAX_MATERIALS) return;
    ++g_R2RTex19Fields;
    for(size_t i=0;i<g_R2RTex18.size();++i)
        if(g_R2RTex18[i].field==field)
        {
            ++g_R2RTex19Duplicate;
            if(g_R2RTex20ScanningTerrain && !g_R2RTex18[i].terrain)
            {
                g_R2RTex18[i].terrain=true;
                ++g_R2RTex20TerrainFields;
            }
            return;
        }
    uint32_t tex=0;
    if(!R2R_Tex18Read32(field,tex))return;
    R2R_Tex18Entry e;
    if(!R2R_Tex18Decode(tex,e))return;
    e.field=field;
    e.terrain=g_R2RTex20ScanningTerrain;
    if(e.terrain)++g_R2RTex20TerrainFields;
    else ++g_R2RTex20ActorFields;
    g_R2RTex18.push_back(e);
}
static void R2R_Tex18CollectTarget(void* target)
{
    if(!target)return;
    ++g_R2RTex19Targets;
    const uintptr_t p=reinterpret_cast<uintptr_t>(target);
    uint32_t visual=0,lodArray=0;
    if(!R2R_Tex18Read32(p,visual) || !visual ||
       !R2R_AddressReadable(static_cast<uintptr_t>(visual),16u))return;
    uint16_t count=0;
    if(!SafeReadMemory(reinterpret_cast<void*>(static_cast<uintptr_t>(visual)+4u),&count,2u) ||
       count<1 || count>32 ||
       !R2R_Tex18Read32(static_cast<uintptr_t>(visual)+12u,lodArray) || !lodArray)return;
    ++g_R2RTex19Visuals;
    // The visual set stores an array of pointers to GEO objects, not a GEO itself.
    // Visit available LODs (up to 12) to cover close-up/alternate render geometry.
    for(unsigned int li=0;li<count && li<12u && g_R2RTex18.size()<R2R_TEX20_MAX_MATERIALS;++li)
    {
        uint32_t geo=0,types=0,elements=0;
        if(!R2R_Tex18Read32(static_cast<uintptr_t>(lodArray)+4u*li,geo) || !geo ||
           !R2R_Tex18Read32(static_cast<uintptr_t>(geo)+0x10u,types) || !types ||
           !R2R_Tex18Read32(static_cast<uintptr_t>(geo)+0x14u,elements) || !elements)continue;
        int16_t parts=0;
        if(!R2R_AddressReadable(static_cast<uintptr_t>(geo)+0x2Eu,2u) ||
           !SafeReadMemory(reinterpret_cast<void*>(static_cast<uintptr_t>(geo)+0x2Eu),&parts,2u) ||
           parts<=0 || parts>128)continue;
        ++g_R2RTex19Geometries;
        for(int i=0;i<parts && g_R2RTex18.size()<R2R_TEX20_MAX_MATERIALS;++i)
        {
            const uintptr_t typeAddr=static_cast<uintptr_t>(types)+2u*static_cast<uintptr_t>(i);
            int16_t type=0;
            if(!R2R_AddressReadable(typeAddr,2u) ||
               !SafeReadMemory(reinterpret_cast<void*>(typeAddr),&type,2u) || type!=1)continue;
            uint32_t triangles=0,gameMat=0,visualMat=0;
            if(!R2R_Tex18Read32(static_cast<uintptr_t>(elements)+4u*static_cast<uintptr_t>(i),triangles) || !triangles ||
               !R2R_Tex18Read32(static_cast<uintptr_t>(triangles),gameMat) || !gameMat ||
               !R2R_Tex18Read32(static_cast<uintptr_t>(gameMat),visualMat) || !visualMat)continue;
            ++g_R2RTex19Triangles;
            R2R_Tex18CollectMaterial(static_cast<uintptr_t>(visualMat)+0x48u);
        }
    }
}
static void R2R_Tex18CollectActor(HIE_tdstSuperObject* object)
{
    if(object==nullptr || object->ulType!=HIE_C_Type_Actor)return;
    ++g_R2RTex19Actors;
    HIE_tdstEngineObject* actor=HIE_M_hSuperObjectGetActor(object);
    if(!actor || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor),sizeof(*actor)) ||
        !actor->h3dData ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor->h3dData),sizeof(*actor->h3dData)))return;
    HIE_tdstObjectsTablesList* table=actor->h3dData->h_CurrentObjectsTable;
    if(!table)return;
    HIE_tdstObjectsTablesList t={};
    if(!R2R_AddressReadable(reinterpret_cast<uintptr_t>(table),sizeof(t)) ||
        !SafeReadMemory(table,&t,sizeof(t)) || !t.d_stObjectsTable ||
        t.uwNumberOfElement==0 || t.uwNumberOfElement>128)return;
    ++g_R2RTex19Tables;
    for(unsigned int i=0;i<t.uwNumberOfElement && g_R2RTex18.size()<R2R_TEX20_MAX_MATERIALS;++i)
    {
        HIE_tdstObjectsTableElement entry={};
        if(!R2R_AddressReadable(reinterpret_cast<uintptr_t>(t.d_stObjectsTable+i),sizeof(entry)) ||
            !SafeReadMemory(t.d_stObjectsTable+i,&entry,sizeof(entry)))break;
        if(entry.hTarget)R2R_Tex18CollectTarget(entry.hTarget);
    }
}
static void R2R_Tex18Scan(HIE_tdstSuperObject* object,int depth)
{
    if(!object || depth>64 || !g_R2RTex18Budget ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(object),sizeof(*object)))return;
    --g_R2RTex18Budget;
    ++g_R2RTex19Nodes;
    R2R_Tex18CollectActor(object);
    HIE_tdstSuperObject* child=nullptr;
    LST_M_DynamicForEach(object,child)
    {
        if(!g_R2RTex18Budget || g_R2RTex18.size()>=R2R_TEX20_MAX_MATERIALS)break;
        if(child)R2R_Tex18Scan(child,depth+1);
    }
}

// A level's fixed geometry lives in the father-sector hierarchy, not in the
// active/inactive character lists. The public ACP_Ray2 SDK defines:
// HIE_C_Type_Sector=0x4, PO=0x8, IPO=0x20, PO_Mirror=0x10, IPO_Mirror=0x40.
// A PO begins with GEO_tdstVisualSet *hVisualSet, and an IPO begins with
// PO_tdstPhysicalObject *hPhysicalObject. The y19 collector already knows
// how to traverse the visual-set LODs from a pointer-to-visual-set field.
static void R2R_Tex20CollectStaticObject(const HIE_tdstSuperObject& so)
{
    const unsigned int type=static_cast<unsigned int>(so.ulType);
    uintptr_t physical=0;
    if(type==0x8u || type==0x10u) // PO / mirrored PO
    {
        ++g_R2RTex20POs;
        physical=reinterpret_cast<uintptr_t>(so.hLinkedObject.p_Void);
    }
    else if(type==0x20u || type==0x40u) // instantiated PO / mirrored IPO
    {
        ++g_R2RTex20IPOs;
        const uintptr_t ipo=reinterpret_cast<uintptr_t>(so.hLinkedObject.p_Void);
        uint32_t po=0;
        if(!R2R_Tex18Read32(ipo,po) || !po)
        { ++g_R2RTex20BadPointers; return; }
        physical=static_cast<uintptr_t>(po);
    }
    else if(type==0x4u) // sector container
    {
        ++g_R2RTex20Sectors;
        return;
    }
    else return; // actors, lights, collision helpers, etc.

    // An invalid PO address must never be interpreted as material data.
    // Only read the visual-set pointer. Never modify collision structures.
    uint32_t visual=0;
    if(!R2R_Tex18Read32(physical,visual) || !visual)
    { ++g_R2RTex20BadPointers; return; }
    R2R_Tex18CollectTarget(reinterpret_cast<void*>(physical));
}
static void R2R_Tex20ScanSectorTree(HIE_tdstSuperObject* object,int depth)
{
    if(!object || depth>64 || !g_R2RTex20Budget ||
       g_R2RTex18.size()>=R2R_TEX20_MAX_MATERIALS)return;
    HIE_tdstSuperObject so={};
    if(!R2R_AddressReadable(reinterpret_cast<uintptr_t>(object),sizeof(so)) ||
       !SafeReadMemory(object,&so,sizeof(so)))
    { ++g_R2RTex20BadPointers; return; }
    --g_R2RTex20Budget;
    ++g_R2RTex20Nodes;
    R2R_Tex20CollectStaticObject(so);
    // Use the same engine-linked child iteration as the y19 actor scanner.
    // Only HIE nodes are followed; sector metadata itself is never edited.
    HIE_tdstSuperObject* child=nullptr;
    LST_M_DynamicForEach(object,child)
    {
        if(!g_R2RTex20Budget ||
           g_R2RTex18.size()>=R2R_TEX20_MAX_MATERIALS)break;
        if(child)R2R_Tex20ScanSectorTree(child,depth+1);
    }
}
static void R2R_Tex20ScanTerrain(HIE_tdstSuperObject* sectorRoot)
{
    g_R2RTex20Nodes=0;g_R2RTex20Sectors=0;g_R2RTex20POs=0;
    g_R2RTex20IPOs=0;g_R2RTex20BadPointers=0;
    g_R2RTex20TerrainFields=0;
    g_R2RTex20ActorFields=static_cast<unsigned int>(g_R2RTex18.size());
    if(!sectorRoot)return;
    g_R2RTex20Budget=12000u;
    g_R2RTex20ScanningTerrain=true;
    R2R_Tex20ScanSectorTree(sectorRoot,0);
    g_R2RTex20ScanningTerrain=false;
}

static bool R2R_Tex18Compatible(const R2R_Tex18Entry& a,const R2R_Tex18Entry& b)
{
    return a.nativeTexture!=b.nativeTexture &&
        _stricmp(a.filename,b.filename)!=0 &&
        a.caps==b.caps && a.palette==b.palette;
}
static bool R2R_Tex19SameDimensions(const R2R_Tex18Entry& a,const R2R_Tex18Entry& b)
{
    return a.width==b.width && a.height==b.height &&
           a.realWidth==b.realWidth && a.realHeight==b.realHeight;
}
static void R2R_Tex18Restore()
{
    for(size_t i=0;i<g_R2RTex18.size();++i)
    {
        R2R_Tex18Entry& e=g_R2RTex18[i];
        if(e.currentTexture==e.nativeTexture)continue;
        uint32_t seen=0;
        if(R2R_Tex18Read32(e.field,seen) && seen==e.currentTexture)
            R2R_WriteGlobal32(e.field,e.nativeTexture);
        e.currentTexture=e.nativeTexture;
    }
    g_R2RTex18.clear();
    g_R2RTex18World=nullptr;g_R2RTex18Inactive=nullptr;
    g_R2RTex20SectorRoot=nullptr;
    g_R2RTex18Level[0]=0;g_R2RTex18Frame=0;g_R2RTex18Scanned=false;
}
static bool R2R_Tex18Active()
{
    return g_R2RConfig.enabled && g_R2RConfig.textures &&
        GAM_g_stEngineStructure && GAM_g_stEngineStructure->eEngineMode==E_EM_ModePlaying &&
        GAM_g_stEngineStructure->szLevelName[0] &&
        _stricmp(GAM_g_stEngineStructure->szLevelName,"Menu")!=0 &&
        GAM_g_p_stDynamicWorld && *GAM_g_p_stDynamicWorld;
}
static void R2R_Tex18BeforeEngine()
{
    // Restore before engine deinitializes/changes worlds, or after F5 disables it.
    if(!R2R_Tex18Active() ||
        _stricmp(g_R2RTex18Level,GAM_g_stEngineStructure->szLevelName)!=0 ||
        g_R2RTex18World!=*GAM_g_p_stDynamicWorld ||
        g_R2RTex20SectorRoot!=(GAM_g_p_stFatherSector?*GAM_g_p_stFatherSector:nullptr) ||
        g_R2RTex18Seed!=g_R2RConfig.seed)
        if(!g_R2RTex18.empty())R2R_Tex18Restore();
}
static void R2R_Tex18AfterEngine()
{
    R2R_Tex19ReportConfig();
    if(!R2R_Tex18Active())return;
    HIE_tdstSuperObject* active=*GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive=GAM_g_p_stInactiveDynamicWorld?*GAM_g_p_stInactiveDynamicWorld:nullptr;
    HIE_tdstSuperObject* sectors=GAM_g_p_stFatherSector?*GAM_g_p_stFatherSector:nullptr;
    const char* level=GAM_g_stEngineStructure->szLevelName;
    if(g_R2RTex18World==active && g_R2RTex18Inactive==inactive &&
       g_R2RTex20SectorRoot==sectors &&
       _stricmp(g_R2RTex18Level,level)==0 && g_R2RTex18Seed==g_R2RConfig.seed &&
       g_R2RTex18Scanned)
    {
        // If level assets are still initializing, retry only once per 120 frames.
        if(!g_R2RTex18.empty() || (++g_R2RTex18Frame%120u)!=0u)return;
    }
    R2R_Tex18Restore();
    g_R2RTex18World=active;g_R2RTex18Inactive=inactive;
    g_R2RTex20SectorRoot=sectors;g_R2RTex18Seed=g_R2RConfig.seed;
    strncpy_s(g_R2RTex18Level,sizeof(g_R2RTex18Level),level,_TRUNCATE);
    g_R2RTex18Budget=4096u;
    R2R_Tex19ResetCounters();
    R2R_Tex18Scan(active,0);
    if(inactive && inactive!=active && g_R2RTex18Budget)R2R_Tex18Scan(inactive,0);
    // y20: true static sector meshes (PO/IPO), using the same validated
    // texture material fields as before. No second independent patch pass.
    R2R_Tex20ScanTerrain(sectors);
    g_R2RTex18Scanned=true;
    FILE* report=nullptr;
    fopen_s(&report,R2R_TEX18_REPORT,"a");
    if(report)
    {
        fprintf(report,"\n[TEXTURE-LEVEL] version=%s level=%s seed=%u materials=%u scope=actor-3D+static-sector-PO\n",
            VERSION,level,g_R2RConfig.seed,static_cast<unsigned int>(g_R2RTex18.size()));
        fprintf(report,"[TERRAIN-SCAN] root=%p nodes=%u sectors=%u PO=%u IPO=%u badPointers=%u actorMaterials=%u terrainMaterials=%u cap=%u\n",
            static_cast<void*>(sectors),g_R2RTex20Nodes,g_R2RTex20Sectors,
            g_R2RTex20POs,g_R2RTex20IPOs,g_R2RTex20BadPointers,
            g_R2RTex20ActorFields,g_R2RTex20TerrainFields,R2R_TEX20_MAX_MATERIALS);
        if(!sectors)fprintf(report,"[TERRAIN-SKIP] Father-sector root not available; actor textures continue normally.\n");
        else if(!g_R2RTex20TerrainFields)
            fprintf(report,"[TERRAIN-SKIP] No texture materials found under the sector root; geometry not modified.\n");
        fprintf(report,"[TEXTURE-SCAN] nodes=%u actors=%u tables=%u targets=%u visuals=%u geometries=%u triangles=%u materialFields=%u duplicate=%u\n",
            g_R2RTex19Nodes,g_R2RTex19Actors,g_R2RTex19Tables,g_R2RTex19Targets,
            g_R2RTex19Visuals,g_R2RTex19Geometries,g_R2RTex19Triangles,g_R2RTex19Fields,g_R2RTex19Duplicate);
        fprintf(report,"[TEXTURE-FILTER] invalid=%u gpuMissing=%u substitutedOrUnnamed=%u badDimensions=%u\n",
            g_R2RTex19InvalidTexture,g_R2RTex19MissingGPU,g_R2RTex19FormatRejected,
            g_R2RTex19DimensionRejected);
        if(g_R2RTex18.empty())fprintf(report,"[TEXTURE-NONE] No valid GPU-ready 3D material texture found.\n");
    }
    unsigned int changed=0,skipped=0;
    unsigned int terrainChanged=0,terrainSkipped=0;
    for(size_t i=0;i<g_R2RTex18.size();++i)
    {
        R2R_Tex18Entry& a=g_R2RTex18[i];
        unsigned int compatible=0;
        bool exactSize=false;
        // Prefer exact dimensions for maximum compatibility. If a model has
        // no alternate same-size image, accept another initialized texture
        // with the SAME GPU caps/palette; the normalized UVs remain valid.
        for(size_t j=0;j<g_R2RTex18.size();++j)
            if(R2R_Tex18Compatible(a,g_R2RTex18[j]) &&
                R2R_Tex19SameDimensions(a,g_R2RTex18[j]))
            {exactSize=true;break;}
        uint32_t hash=R2R_RollU32("Textures.3D",level,
            static_cast<uint32_t>(R2R_HashText64(a.filename)) ^ (a.width<<16u) ^ a.height);
        size_t pick=g_R2RTex18.size();
        for(size_t j=0;j<g_R2RTex18.size();++j)
        {
            if(!R2R_Tex18Compatible(a,g_R2RTex18[j]))continue;
            if(exactSize && !R2R_Tex19SameDimensions(a,g_R2RTex18[j]))continue;
            ++compatible;
            hash=static_cast<uint32_t>(R2R_SplitMix64(static_cast<uint64_t>(hash)+0x9E3779B97F4A7C15ULL));
            if(hash%compatible==0u)pick=j;
        }
        if(pick==g_R2RTex18.size()){++skipped;if(a.terrain)++terrainSkipped;continue;}
        // Another owner may have changed a material while we were scanning.
        uint32_t observed=0;
        if(!R2R_Tex18Read32(a.field,observed) || observed!=a.nativeTexture)
        {++skipped;if(a.terrain)++terrainSkipped;continue;}
        R2R_Tex18Entry& donor=g_R2RTex18[pick];
        if(R2R_WriteGlobal32(a.field,donor.nativeTexture))
        {
            a.currentTexture=donor.nativeTexture;
            ++changed;
            if(a.terrain)++terrainChanged;
            if(report && a.terrain && terrainChanged<=70u)
                fprintf(report,"[TERRAIN-RANDO] src=%s -> donor=%s %ux%u caps=0x%08X choices=%u sizeMatch=%u\n",
                    a.filename,donor.filename,static_cast<unsigned>(a.width),
                    static_cast<unsigned>(a.height),static_cast<unsigned>(a.caps),compatible,exactSize?1u:0u);
            if(report && changed<=100u)
                fprintf(report,"[TEXTURE-RANDO] src=%s -> donor=%s %ux%u caps=0x%08X choices=%u sizeMatch=%u\n",
                    a.filename,donor.filename,static_cast<unsigned>(a.width),
                    static_cast<unsigned>(a.height),static_cast<unsigned>(a.caps),compatible,exactSize?1u:0u);
        }
        else { ++skipped;if(a.terrain)++terrainSkipped; }
    }
    if(report){
        fprintf(report,"[TERRAIN-SUMMARY] level=%s found=%u changed=%u skipped=%u\n",
            level,g_R2RTex20TerrainFields,terrainChanged,terrainSkipped);
        fprintf(report,"[TEXTURE-SUMMARY] level=%s found=%u changed=%u skipped=%u\n",level,
        static_cast<unsigned>(g_R2RTex18.size()),changed,skipped);
        if(!changed && !g_R2RTex18.empty())
            fprintf(report,"[TEXTURE-NONE] Valid textures found, but no compatible GPU-format donor or writable field.\n");
        fclose(report);
    }
}

void R2R_FreeMergedAllocations()
{
    for (size_t i = 0; i < 12; i++)
    {
        if (g_A3dMergedAllocations[i] != nullptr)
        {
            VirtualFree(g_A3dMergedAllocations[i], 0, MEM_RELEASE);
            g_A3dMergedAllocations[i] = nullptr;
        }
    }
}

void RestoreMergedAnimationBank(bool showMessage)
{
    if (!g_A3dMergedBankInstalled)
    {
        if (showMessage)
        {
            MessageBoxA(
                nullptr,
                "No merged animation bank is currently installed.",
                "Rayman 2 Randomizer v0.0.14b.0",
                MB_OK | MB_ICONINFORMATION
            );
        }
        return;
    }

    for (size_t i = 0; i < 12; i++)
    {
        if (g_A3dMergedAllocations[i] != nullptr)
        {
            R2R_WriteGlobal32(
                R2R_A3D_GLOBAL_SLOTS[i],
                g_A3dMergedOriginalGlobals[i]
            );
        }
    }

    g_A3dMergedBankInstalled = false;
    g_A3dMergedSyntheticId = 0xFFFF;

    for (int i = 0; i < 4; i++)
    {
        g_R2RActionSyntheticGeneralIds[i] = 0xFFFF;
    }

    // h.7.97: DO NOT free the merged allocations here.  Earlier tests showed
    // that Rayman 2 can keep transient references to animation-bank memory
    // even after the global pointers are restored.  Freeing it immediately
    // caused the F6 regression in h.7.96.  The process will reclaim it later.

    FILE* report = nullptr;
    fopen_s(&report, A3D_MERGED_BANK_REPORT_FILE, "a");
    if (report != nullptr)
    {
        fprintf(
            report,
            "\n============================================================\n"
            "MERGED BANK RESTORED\n"
            "============================================================\n"
            "All redirected animation globals were restored to Bast_20.\n"
            "Merged allocation memory intentionally retained until process exit.\n"
        );
        fclose(report);
    }

    if (showMessage)
    {
        MessageBoxA(
            nullptr,
            "MERGED A3D BANK RESTORED!\n\nRayman 2 is back on the original Bast_20 animation tables.\n\nSend me:\nRayman2Randomizer_A3dMergedBank.txt",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONINFORMATION
        );
    }
}

bool R2R_MapU16Index(
    uint16_t oldValue,
    uint32_t oldStart,
    uint32_t oldCount,
    uint32_t newStart,
    uint16_t& outValue
)
{
    outValue = oldValue;

    if (
        oldCount == 0 ||
        oldValue < oldStart ||
        static_cast<uint32_t>(oldValue) >= oldStart + oldCount
        )
    {
        return false;
    }

    const uint32_t mapped =
        newStart + (static_cast<uint32_t>(oldValue) - oldStart);

    if (mapped > 0xFFFFu)
    {
        return false;
    }

    outValue = static_cast<uint16_t>(mapped);
    return true;
}

bool R2R_MapU32Index(
    uint32_t oldValue,
    uint32_t oldStart,
    uint32_t oldCount,
    uint32_t newStart,
    uint32_t& outValue
)
{
    outValue = oldValue;

    if (
        oldCount == 0 ||
        oldValue < oldStart ||
        oldValue >= oldStart + oldCount
        )
    {
        return false;
    }

    outValue = newStart + (oldValue - oldStart);
    return true;
}

void R2R_PatchU16FieldIfMapped(
    std::vector<uint8_t>& bytes,
    size_t offset,
    uint32_t oldStart,
    uint32_t oldCount,
    uint32_t newStart,
    unsigned int& patchedCount
)
{
    if (offset + 2 > bytes.size()) return;

    uint16_t oldValue = 0;
    std::memcpy(&oldValue, bytes.data() + offset, 2);

    uint16_t mapped = oldValue;
    if (R2R_MapU16Index(oldValue, oldStart, oldCount, newStart, mapped))
    {
        std::memcpy(bytes.data() + offset, &mapped, 2);
        patchedCount++;
    }
}

void R2R_PatchU32FieldIfMapped(
    std::vector<uint8_t>& bytes,
    size_t offset,
    uint32_t oldStart,
    uint32_t oldCount,
    uint32_t newStart,
    unsigned int& patchedCount
)
{
    if (offset + 4 > bytes.size()) return;

    uint32_t oldValue = 0;
    std::memcpy(&oldValue, bytes.data() + offset, 4);

    uint32_t mapped = oldValue;
    if (R2R_MapU32Index(oldValue, oldStart, oldCount, newStart, mapped))
    {
        std::memcpy(bytes.data() + offset, &mapped, 4);
        patchedCount++;
    }
}

void* R2R_AllocateMergedTable(
    uintptr_t sourceBase,
    uint32_t activeCount,
    size_t elementSize,
    const std::vector<uint8_t>& appendBytes,
    uint32_t& outAppendStart
)
{
    outAppendStart = activeCount;

    if (sourceBase == 0 || elementSize == 0)
    {
        return nullptr;
    }

    const size_t prefixBytes =
        static_cast<size_t>(activeCount) * elementSize;
    const size_t totalBytes = prefixBytes + appendBytes.size();

    if (totalBytes == 0)
    {
        return nullptr;
    }

    void* memory = VirtualAlloc(
        nullptr,
        totalBytes,
        MEM_COMMIT | MEM_RESERVE,
        PAGE_READWRITE
    );

    if (memory == nullptr)
    {
        return nullptr;
    }

    std::memset(memory, 0, totalBytes);

    if (
        prefixBytes != 0 &&
        !SafeReadMemory(
            reinterpret_cast<const void*>(sourceBase),
            memory,
            prefixBytes
        )
        )
    {
        VirtualFree(memory, 0, MEM_RELEASE);
        return nullptr;
    }

    if (!appendBytes.empty())
    {
        std::memcpy(
            reinterpret_cast<uint8_t*>(memory) + prefixBytes,
            appendBytes.data(),
            appendBytes.size()
        );
    }

    return memory;
}

bool R2R_PrepareRemappedDonorSlices(
    const R2R_A3dUsageSummary& usage,
    uint16_t outGeneralWords[28],
    std::vector<uint8_t>& outOnlyFrames,
    std::vector<uint8_t>& outChannels,
    std::vector<uint8_t>& outFrames,
    std::vector<uint8_t>& outFramesKF,
    std::vector<uint8_t>& outKeyFrames,
    FILE* report
)
{
    if (!g_A3dDonor301Captured)
    {
        return false;
    }

    std::memcpy(outGeneralWords, g_A3dDonor301Words, 0x38);
    outOnlyFrames = g_A3dDonorOnlyFrames;
    outChannels = g_A3dDonorChannels;
    outFrames = g_A3dDonorFrames;
    outFramesKF = g_A3dDonorFramesKF;
    outKeyFrames = g_A3dDonorKeyFrames;

    const uint32_t oldVec = g_A3dDonor301Words[19];
    const uint32_t oldQuat = g_A3dDonor301Words[20];
    const uint32_t oldHier = g_A3dDonor301Words[21];
    const uint32_t oldNtto = g_A3dDonor301Words[22];
    const uint32_t oldOnly = g_A3dDonor301Words[23];
    const uint32_t oldChan = g_A3dDonor301Words[24];

    const uint32_t newVec = usage.vectors;
    const uint32_t newQuat = usage.quaternions;
    const uint32_t newHier = usage.hierarchies;
    const uint32_t newNtto = usage.ntto;
    const uint32_t newOnly = usage.onlyFrames;
    const uint32_t newChan = usage.channels;
    const uint32_t newFrames = usage.frames;
    const uint32_t newFramesKF = usage.framesKF;
    const uint32_t newKeyFrames = usage.keyFrames;

    // A3dGENERAL index fields.
    auto patchGeneralU16 = [&](size_t wordIndex, uint32_t oldStart, uint32_t oldCount, uint32_t newStart) -> bool
        {
            uint16_t mapped = outGeneralWords[wordIndex];
            if (!R2R_MapU16Index(
                outGeneralWords[wordIndex],
                oldStart,
                oldCount,
                newStart,
                mapped
            ))
            {
                return false;
            }
            outGeneralWords[wordIndex] = mapped;
            return true;
        };

    bool generalOK = true;
    generalOK &= patchGeneralU16(16, oldVec, g_A3dDonor301Words[1], newVec);  // start_vectors2
    generalOK &= patchGeneralU16(19, oldVec, g_A3dDonor301Words[1], newVec);  // start_vectors
    generalOK &= patchGeneralU16(17, oldQuat, g_A3dDonor301Words[2], newQuat); // start_quaternions2
    generalOK &= patchGeneralU16(20, oldQuat, g_A3dDonor301Words[2], newQuat); // start_quaternions
    generalOK &= patchGeneralU16(21, oldHier, g_A3dDonor301Words[3], newHier);
    generalOK &= patchGeneralU16(22, oldNtto, g_A3dDonor301Words[4], newNtto);
    generalOK &= patchGeneralU16(23, oldOnly, g_A3dDonor301Words[7], newOnly);
    generalOK &= patchGeneralU16(24, oldChan, g_A3dDonor301Words[6], newChan);

    // unk_1A behaves as a vector-table index in this donor (oldVec + 2).
    // Remap it only when it actually falls inside the captured donor vector slice.
    uint16_t mappedUnknown = outGeneralWords[11];
    if (R2R_MapU16Index(
        outGeneralWords[11],
        oldVec,
        g_A3dDonor301Words[1],
        newVec,
        mappedUnknown
    ))
    {
        outGeneralWords[11] = mappedUnknown;
    }

    unsigned int onlyFramePatches = 0;
    for (size_t off = 0; off + 10 <= outOnlyFrames.size(); off += 10)
    {
        R2R_PatchU16FieldIfMapped(outOnlyFrames, off + 0, oldQuat, g_A3dDonor301Words[2], newQuat, onlyFramePatches);
        R2R_PatchU16FieldIfMapped(outOnlyFrames, off + 2, oldVec, g_A3dDonor301Words[1], newVec, onlyFramePatches);
        R2R_PatchU16FieldIfMapped(outOnlyFrames, off + 6, oldHier, g_A3dDonor301Words[3], newHier, onlyFramePatches);
    }

    unsigned int channelPatches = 0;
    for (size_t off = 0; off + 16 <= outChannels.size(); off += 16)
    {
        R2R_PatchU16FieldIfMapped(outChannels, off + 4, oldVec, g_A3dDonor301Words[1], newVec, channelPatches);
        R2R_PatchU16FieldIfMapped(outChannels, off + 6, g_A3dDonorFramesStart, g_A3dDonorFramesCount, newFrames, channelPatches);
        R2R_PatchU32FieldIfMapped(outChannels, off + 8, g_A3dDonorFramesKFStart, g_A3dDonorFramesKFCount, newFramesKF, channelPatches);
        R2R_PatchU32FieldIfMapped(outChannels, off + 12, g_A3dDonorKeyFramesStart, g_A3dDonorKeyFramesCount, newKeyFrames, channelPatches);
    }

    // h.7.27 IMPORTANT FIX:
    // The 2-byte "frames/numOfNTTO" table does NOT contain harmless frame
    // numbers. Each value is an ABSOLUTE index into the global NTTO table.
    //
    // We already moved the donor NTTO slice from Water_20 to the appended
    // Bast_20 location, but until now these six values still pointed back to
    // the old Water_20 NTTO indices. That makes the animation player select
    // unrelated Bast_20 NTTO entries and explains why it created empty
    // channel containers instead of drawable Physical Objects.
    unsigned int numOfNTTOPatches = 0;
    for (size_t off = 0; off + 2 <= outFrames.size(); off += 2)
    {
        R2R_PatchU16FieldIfMapped(
            outFrames,
            off,
            oldNtto,
            g_A3dDonor301Words[4],
            newNtto,
            numOfNTTOPatches
        );
    }

    unsigned int framesKFPatches = 0;
    for (size_t off = 0; off + 4 <= outFramesKF.size(); off += 4)
    {
        R2R_PatchU32FieldIfMapped(
            outFramesKF,
            off,
            g_A3dDonorKeyFramesStart,
            g_A3dDonorKeyFramesCount,
            newKeyFrames,
            framesKFPatches
        );
    }

    unsigned int keyFramePatches = 0;
    for (size_t off = 0; off + 36 <= outKeyFrames.size(); off += 36)
    {
        // R2 PC AnimKeyframe: quaternion, quaternion2, scaleVector,
        // positionVector live at +0x14,+0x16,+0x18,+0x1A.
        R2R_PatchU16FieldIfMapped(outKeyFrames, off + 20, oldQuat, g_A3dDonor301Words[2], newQuat, keyFramePatches);
        R2R_PatchU16FieldIfMapped(outKeyFrames, off + 22, oldQuat, g_A3dDonor301Words[2], newQuat, keyFramePatches);
        R2R_PatchU16FieldIfMapped(outKeyFrames, off + 24, oldVec, g_A3dDonor301Words[1], newVec, keyFramePatches);
        R2R_PatchU16FieldIfMapped(outKeyFrames, off + 26, oldVec, g_A3dDonor301Words[1], newVec, keyFramePatches);
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nDONOR REMAP SUMMARY\n"
            "------------------------------------------------------------\n"
            "  new vectors start      : %u\n"
            "  new quaternions start  : %u\n"
            "  new hierarchies start  : %u\n"
            "  new NTTO start         : %u\n"
            "  new onlyFrames start   : %u\n"
            "  new channels start     : %u\n"
            "  new frames start       : %u\n"
            "  new framesKF start     : %u\n"
            "  new keyFrames start    : %u\n"
            "  onlyFrame index patches: %u\n"
            "  channel index patches  : %u\n"
            "  numOfNTTO value patches: %u\n"
            "  framesKF index patches : %u\n"
            "  keyFrame index patches : %u\n"
            "  general remap          : %s\n",
            newVec,
            newQuat,
            newHier,
            newNtto,
            newOnly,
            newChan,
            newFrames,
            newFramesKF,
            newKeyFrames,
            onlyFramePatches,
            channelPatches,
            numOfNTTOPatches,
            framesKFPatches,
            keyFramePatches,
            generalOK ? "OK" : "FAILED"
        );
    }

    return generalOK;
}


static bool R2R_PrepareRemappedAglaglActionBank(
    const R2R_A3dUsageSummary& usage,
    std::vector<uint8_t>& outGenerals,
    std::vector<uint8_t>& outOnlyFrames,
    std::vector<uint8_t>& outChannels,
    std::vector<uint8_t>& outFrames,
    std::vector<uint8_t>& outFramesKF,
    std::vector<uint8_t>& outKeyFrames,
    FILE* report
)
{
    if (!g_R2RActionBankCaptured)
    {
        return false;
    }

    outGenerals.clear();
    outGenerals.resize(4u * 0x38u);

    outOnlyFrames =
        g_R2RActionOnlyFrames;

    outChannels =
        g_R2RActionChannels;

    outFrames =
        g_R2RActionFrames;

    outFramesKF =
        g_R2RActionFramesKF;

    outKeyFrames =
        g_R2RActionKeyFrames;

    const uint32_t newVector =
        usage.vectors;

    const uint32_t newQuat =
        usage.quaternions;

    const uint32_t newHier =
        usage.hierarchies;

    const uint32_t newNTTO =
        usage.ntto;

    const uint32_t newOnly =
        usage.onlyFrames;

    const uint32_t newChannel =
        usage.channels;

    const uint32_t newFrames =
        usage.frames;

    const uint32_t newFramesKF =
        usage.framesKF;

    const uint32_t newKeyFrame =
        usage.keyFrames;

    bool generalOK = true;

    for (int g = 0; g < 4; g++)
    {
        uint16_t words[28] = {};

        std::memcpy(
            words,
            g_R2RActionGeneralWords[g],
            sizeof(words)
        );

        auto patchGeneralU16 =
            [&](
                size_t wordIndex,
                uint32_t oldStart,
                uint32_t oldCount,
                uint32_t newStart
                ) -> bool
            {
                uint16_t mapped =
                    words[wordIndex];

                if (
                    !R2R_MapU16Index(
                        words[wordIndex],
                        oldStart,
                        oldCount,
                        newStart,
                        mapped
                    )
                    )
                {
                    return false;
                }

                words[wordIndex] =
                    mapped;

                return true;
            };

        generalOK &=
            patchGeneralU16(
                16,
                g_R2RActionVectorStart,
                g_R2RActionVectorCount,
                newVector
            );

        generalOK &=
            patchGeneralU16(
                19,
                g_R2RActionVectorStart,
                g_R2RActionVectorCount,
                newVector
            );

        generalOK &=
            patchGeneralU16(
                17,
                g_R2RActionQuaternionStart,
                g_R2RActionQuaternionCount,
                newQuat
            );

        generalOK &=
            patchGeneralU16(
                20,
                g_R2RActionQuaternionStart,
                g_R2RActionQuaternionCount,
                newQuat
            );

        generalOK &=
            patchGeneralU16(
                21,
                g_R2RActionHierarchyStart,
                g_R2RActionHierarchyCount,
                newHier
            );

        generalOK &=
            patchGeneralU16(
                22,
                g_R2RActionNTTOStart,
                g_R2RActionNTTOCount,
                newNTTO
            );

        generalOK &=
            patchGeneralU16(
                23,
                g_R2RActionOnlyFrameStart,
                g_R2RActionOnlyFrameCount,
                newOnly
            );

        generalOK &=
            patchGeneralU16(
                24,
                g_R2RActionChannelStart,
                g_R2RActionChannelCount,
                newChannel
            );

        // The R2 donor's word[11] behaves as a vector-table index.
        uint16_t mappedUnknown =
            words[11];

        if (
            R2R_MapU16Index(
                words[11],
                g_R2RActionVectorStart,
                g_R2RActionVectorCount,
                newVector,
                mappedUnknown
            )
            )
        {
            words[11] =
                mappedUnknown;
        }

        // h.7.68 first REAL action-motion test:
        // General 302 owns one Water_20 animation event. Its event object
        // points at Water runtime data and has not been reconstructed yet.
        // Suppress events for ALL four imported descriptors so no stale
        // Water event pointer/index can be consumed.
        words[10] = 0;
        words[25] = 0;

        // These four animations have no morph payload. Clear the unused
        // start as well so the merged descriptor has no stale Water index.
        words[18] = 0;
        words[26] = 0;

        std::memcpy(
            outGenerals.data() +
            static_cast<size_t>(g) * 0x38u,
            words,
            0x38u
        );
    }

    unsigned int onlyFramePatches = 0;

    for (
        size_t off = 0;
        off + 10 <= outOnlyFrames.size();
        off += 10
        )
    {
        R2R_PatchU16FieldIfMapped(
            outOnlyFrames,
            off + 0,
            g_R2RActionQuaternionStart,
            g_R2RActionQuaternionCount,
            newQuat,
            onlyFramePatches
        );

        R2R_PatchU16FieldIfMapped(
            outOnlyFrames,
            off + 2,
            g_R2RActionVectorStart,
            g_R2RActionVectorCount,
            newVector,
            onlyFramePatches
        );

        R2R_PatchU16FieldIfMapped(
            outOnlyFrames,
            off + 6,
            g_R2RActionHierarchyStart,
            g_R2RActionHierarchyCount,
            newHier,
            onlyFramePatches
        );
    }

    unsigned int channelPatches = 0;

    for (
        size_t off = 0;
        off + 16 <= outChannels.size();
        off += 16
        )
    {
        R2R_PatchU16FieldIfMapped(
            outChannels,
            off + 4,
            g_R2RActionVectorStart,
            g_R2RActionVectorCount,
            newVector,
            channelPatches
        );

        R2R_PatchU16FieldIfMapped(
            outChannels,
            off + 6,
            g_R2RActionFramesStart,
            g_R2RActionFramesCount,
            newFrames,
            channelPatches
        );

        R2R_PatchU32FieldIfMapped(
            outChannels,
            off + 8,
            g_R2RActionFramesKFStart,
            g_R2RActionFramesKFCount,
            newFramesKF,
            channelPatches
        );

        R2R_PatchU32FieldIfMapped(
            outChannels,
            off + 12,
            g_R2RActionKeyFrameStart,
            g_R2RActionKeyFrameCount,
            newKeyFrame,
            channelPatches
        );
    }

    // Same h.7.27 fix, now applied to the broad 301..305 union:
    // each 16-bit value is an ABSOLUTE NTTO index.
    unsigned int numOfNTTOPatches = 0;

    for (
        size_t off = 0;
        off + 2 <= outFrames.size();
        off += 2
        )
    {
        R2R_PatchU16FieldIfMapped(
            outFrames,
            off,
            g_R2RActionNTTOStart,
            g_R2RActionNTTOCount,
            newNTTO,
            numOfNTTOPatches
        );
    }

    unsigned int framesKFPatches = 0;

    for (
        size_t off = 0;
        off + 4 <= outFramesKF.size();
        off += 4
        )
    {
        R2R_PatchU32FieldIfMapped(
            outFramesKF,
            off,
            g_R2RActionKeyFrameStart,
            g_R2RActionKeyFrameCount,
            newKeyFrame,
            framesKFPatches
        );
    }

    unsigned int keyFramePatches = 0;

    for (
        size_t off = 0;
        off + 36 <= outKeyFrames.size();
        off += 36
        )
    {
        R2R_PatchU16FieldIfMapped(
            outKeyFrames,
            off + 20,
            g_R2RActionQuaternionStart,
            g_R2RActionQuaternionCount,
            newQuat,
            keyFramePatches
        );

        R2R_PatchU16FieldIfMapped(
            outKeyFrames,
            off + 22,
            g_R2RActionQuaternionStart,
            g_R2RActionQuaternionCount,
            newQuat,
            keyFramePatches
        );

        R2R_PatchU16FieldIfMapped(
            outKeyFrames,
            off + 24,
            g_R2RActionVectorStart,
            g_R2RActionVectorCount,
            newVector,
            keyFramePatches
        );

        R2R_PatchU16FieldIfMapped(
            outKeyFrames,
            off + 26,
            g_R2RActionVectorStart,
            g_R2RActionVectorCount,
            newVector,
            keyFramePatches
        );
    }

    if (report != nullptr)
    {
        fprintf(
            report,
            "\nACTION BANK REMAP SUMMARY\n"
            "------------------------------------------------------------\n"
            "  Generals appended        : 301, 302, 303, 305\n"
            "  new vector start         : %u\n"
            "  new quaternion start     : %u\n"
            "  new hierarchy start      : %u\n"
            "  new NTTO start           : %u\n"
            "  new onlyFrame start      : %u\n"
            "  new channel start        : %u\n"
            "  new frames start         : %u\n"
            "  new framesKF start       : %u\n"
            "  new keyFrame start       : %u\n"
            "  onlyFrame patches        : %u\n"
            "  channel patches          : %u\n"
            "  NTTO-index patches       : %u\n"
            "  framesKF patches         : %u\n"
            "  keyFrame patches         : %u\n"
            "  animation events         : DISABLED FOR h.7.68\n"
            "  general remap            : %s\n",
            newVector,
            newQuat,
            newHier,
            newNTTO,
            newOnly,
            newChannel,
            newFrames,
            newFramesKF,
            newKeyFrame,
            onlyFramePatches,
            channelPatches,
            numOfNTTOPatches,
            framesKFPatches,
            keyFramePatches,
            generalOK ? "OK" : "FAILED"
        );
    }

    return generalOK;
}


bool InstallMergedAnimationBank(FILE* report)
{
    if (
        report == nullptr ||
        !g_A3dDonor301Captured ||
        !g_R2RActionBankCaptured ||
        g_A3dMergedBankInstalled
        )
    {
        return false;
    }

    uint32_t globals[12] = {};

    for (size_t i = 0; i < 12; i++)
    {
        if (
            !R2R_ReadGlobal32(
                R2R_A3D_GLOBAL_SLOTS[i],
                globals[i]
            )
            )
        {
            fprintf(
                report,
                "FAILED reading global slot %zu.\n",
                i
            );
            return false;
        }
    }

    const R2R_A3dUsageSummary usage =
        R2R_ScanCurrentA3dUsage(
            report
        );

    if (
        usage.highestAnimationPlusOne == 0 ||
        usage.highestAnimationPlusOne + 4u >= 0xFFFFu ||
        usage.vectors +
        g_R2RActionVectorCount > 0xFFFFu ||
        usage.quaternions +
        g_R2RActionQuaternionCount > 0xFFFFu ||
        usage.hierarchies +
        g_R2RActionHierarchyCount > 0xFFFFu ||
        usage.ntto +
        g_R2RActionNTTOCount > 0xFFFFu ||
        usage.onlyFrames +
        g_R2RActionOnlyFrameCount > 0xFFFFu ||
        usage.channels +
        g_R2RActionChannelCount > 0xFFFFu ||
        usage.frames +
        g_R2RActionFramesCount > 0xFFFFu
        )
    {
        fprintf(
            report,
            "FAILED: one or more 16-bit merged action-bank indices would overflow.\n"
        );
        return false;
    }

    std::vector<uint8_t> remappedGenerals;
    std::vector<uint8_t> remappedOnlyFrames;
    std::vector<uint8_t> remappedChannels;
    std::vector<uint8_t> remappedFrames;
    std::vector<uint8_t> remappedFramesKF;
    std::vector<uint8_t> remappedKeyFrames;

    if (
        !R2R_PrepareRemappedAglaglActionBank(
            usage,
            remappedGenerals,
            remappedOnlyFrames,
            remappedChannels,
            remappedFrames,
            remappedFramesKF,
            remappedKeyFrames,
            report
        )
        )
    {
        fprintf(
            report,
            "FAILED preparing remapped Aglagl action bank.\n"
        );
        return false;
    }

    uint32_t starts[12] = {};

    // Events (slot 9) and morph data (slot 5) are deliberately NOT
    // redirected in h.7.68.  Every imported descriptor has those counts
    // forced to zero.  This isolates the real skeleton/action motion first.
    g_A3dMergedAllocations[0] =
        R2R_AllocateMergedTable(
            globals[0],
            usage.framesKF,
            4,
            remappedFramesKF,
            starts[0]
        );

    g_A3dMergedAllocations[1] =
        R2R_AllocateMergedTable(
            globals[1],
            usage.highestAnimationPlusOne,
            0x38,
            remappedGenerals,
            starts[1]
        );

    g_A3dMergedAllocations[2] =
        R2R_AllocateMergedTable(
            globals[2],
            usage.channels,
            16,
            remappedChannels,
            starts[2]
        );

    g_A3dMergedAllocations[3] =
        R2R_AllocateMergedTable(
            globals[3],
            usage.frames,
            2,
            remappedFrames,
            starts[3]
        );

    g_A3dMergedAllocations[4] =
        R2R_AllocateMergedTable(
            globals[4],
            usage.hierarchies,
            4,
            g_R2RActionHierarchies,
            starts[4]
        );

    g_A3dMergedAllocations[6] =
        R2R_AllocateMergedTable(
            globals[6],
            usage.keyFrames,
            36,
            remappedKeyFrames,
            starts[6]
        );

    g_A3dMergedAllocations[7] =
        R2R_AllocateMergedTable(
            globals[7],
            usage.onlyFrames,
            10,
            remappedOnlyFrames,
            starts[7]
        );

    g_A3dMergedAllocations[8] =
        R2R_AllocateMergedTable(
            globals[8],
            usage.vectors,
            12,
            g_R2RActionVectors,
            starts[8]
        );

    g_A3dMergedAllocations[10] =
        R2R_AllocateMergedTable(
            globals[10],
            usage.ntto,
            6,
            g_R2RActionNTTO,
            starts[10]
        );

    g_A3dMergedAllocations[11] =
        R2R_AllocateMergedTable(
            globals[11],
            usage.quaternions,
            8,
            g_R2RActionQuaternions,
            starts[11]
        );

    const size_t requiredSlots[] =
    {
        0, 1, 2, 3, 4, 6, 7, 8, 10, 11
    };

    for (
        size_t i = 0;
        i < sizeof(requiredSlots) /
        sizeof(requiredSlots[0]);
        i++
        )
    {
        if (
            g_A3dMergedAllocations[
                requiredSlots[i]
            ] == nullptr
            )
        {
            fprintf(
                report,
                "FAILED allocating merged table slot %zu.\n",
                requiredSlots[i]
            );

            R2R_FreeMergedAllocations();
            return false;
        }
    }

    const bool startsMatch =
        starts[0] ==
        usage.framesKF &&
        starts[1] ==
        usage.highestAnimationPlusOne &&
        starts[2] ==
        usage.channels &&
        starts[3] ==
        usage.frames &&
        starts[4] ==
        usage.hierarchies &&
        starts[6] ==
        usage.keyFrames &&
        starts[7] ==
        usage.onlyFrames &&
        starts[8] ==
        usage.vectors &&
        starts[10] ==
        usage.ntto &&
        starts[11] ==
        usage.quaternions;

    if (!startsMatch)
    {
        fprintf(
            report,
            "FAILED: allocator append starts do not match action-bank remap plan.\n"
        );

        R2R_FreeMergedAllocations();
        return false;
    }

    std::memcpy(
        g_A3dMergedOriginalGlobals,
        globals,
        sizeof(globals)
    );

    uint8_t native397Before[0x38] = {};

    const bool native397BeforeOK =
        SafeReadMemory(
            reinterpret_cast<const void*>(
                static_cast<uintptr_t>(
                    globals[1]
                    ) +
                397u * 0x38u
                ),
            native397Before,
            sizeof(native397Before)
        );

    bool writeOK = true;

    for (
        size_t i = 0;
        i < sizeof(requiredSlots) /
        sizeof(requiredSlots[0]);
        i++
        )
    {
        const size_t slotIndex =
            requiredSlots[i];

        writeOK &=
            R2R_WriteGlobal32(
                R2R_A3D_GLOBAL_SLOTS[
                    slotIndex
                ],
                static_cast<uint32_t>(
                    reinterpret_cast<uintptr_t>(
                        g_A3dMergedAllocations[
                            slotIndex
                        ]
                        )
                    )
            );
    }

    if (!writeOK)
    {
        fprintf(
            report,
            "FAILED while redirecting one or more action-bank globals.\n"
        );

        for (
            size_t i = 0;
            i < sizeof(requiredSlots) /
            sizeof(requiredSlots[0]);
            i++
            )
        {
            const size_t slotIndex =
                requiredSlots[i];

            R2R_WriteGlobal32(
                R2R_A3D_GLOBAL_SLOTS[
                    slotIndex
                ],
                globals[slotIndex]
            );
        }

        R2R_FreeMergedAllocations();
        return false;
    }

    const uint16_t syntheticBase =
        static_cast<uint16_t>(
            usage.highestAnimationPlusOne
            );

    g_A3dMergedSyntheticId =
        syntheticBase;

    for (int i = 0; i < 4; i++)
    {
        g_R2RActionSyntheticGeneralIds[i] =
            static_cast<uint16_t>(
                syntheticBase + i
                );
    }

    g_A3dMergedBankInstalled = true;

    typedef void* (__cdecl* R2R_GetA3dGeneralFn)(
        unsigned short
        );

    R2R_GetA3dGeneralFn getGeneral =
        reinterpret_cast<R2R_GetA3dGeneralFn>(
            0x004192E0
            );

    bool allSyntheticValid = true;

    fprintf(
        report,
        "\nMERGED REAL ACTION BANK VALIDATION\n"
        "------------------------------------------------------------\n"
    );

    for (int i = 0; i < 4; i++)
    {
        const uint16_t syntheticId =
            g_R2RActionSyntheticGeneralIds[i];

        void* resolved =
            getGeneral(
                syntheticId
            );

        void* expected =
            reinterpret_cast<uint8_t*>(
                g_A3dMergedAllocations[1]
                ) +
            static_cast<size_t>(
                syntheticId
                ) * 0x38u;

        const uint8_t* expectedBytes =
            remappedGenerals.data() +
            static_cast<size_t>(i) *
            0x38u;

        uint8_t actual[0x38] = {};

        const bool readable =
            SafeReadMemory(
                expected,
                actual,
                sizeof(actual)
            );

        const bool exact =
            readable &&
            std::memcmp(
                actual,
                expectedBytes,
                0x38u
            ) == 0;

        const bool resolverMatch =
            resolved == expected;

        allSyntheticValid &=
            exact &&
            resolverMatch;

        fprintf(
            report,
            "  Water General %u -> synthetic %u  resolver=%s bytes=%s\n",
            static_cast<unsigned int>(
                R2R_ACTION_SOURCE_GENERAL_IDS[i]
                ),
            static_cast<unsigned int>(
                syntheticId
                ),
            resolverMatch ? "OK" : "BAD",
            exact ? "OK" : "BAD"
        );
    }

    uint8_t native397After[0x38] = {};

    const bool native397AfterOK =
        SafeReadMemory(
            reinterpret_cast<const void*>(
                reinterpret_cast<uintptr_t>(
                    g_A3dMergedAllocations[1]
                    ) +
                397u * 0x38u
                ),
            native397After,
            sizeof(native397After)
        );

    const bool native397Same =
        native397BeforeOK &&
        native397AfterOK &&
        std::memcmp(
            native397Before,
            native397After,
            0x38u
        ) == 0;

    fprintf(
        report,
        "  native Bast #397 intact : %s\n"
        "  events imported         : NO (302 event suppressed)\n"
        "  globals redirected      : YES\n",
        native397Same ? "YES" : "NO"
    );

    fflush(report);

    return
        allSyntheticValid &&
        native397Same;
}

void RunMergedA3dBankProbe()
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying
        )
    {
        return;
    }

    const char* levelName = GAM_g_stEngineStructure->szLevelName;
    if (levelName == nullptr) levelName = "(unknown)";

    const bool isWater = _stricmp(levelName, "Water_20") == 0;
    const bool isBast = _stricmp(levelName, "Bast_20") == 0;

    if (isWater)
    {
        FILE* report = nullptr;
        fopen_s(&report, A3D_MERGED_BANK_REPORT_FILE, "w");
        if (report == nullptr) return;

        fprintf(
            report,
            "RAYMAN 2 RANDOMIZER\n"
            "v0.0.14b.0 - PRIVATE MERGED A3D BANK\n"
            "============================================================\n\n"
            "STAGE 1 captures Water_20 Aglagl animation dependencies.\n"
            "STAGE 2 allocates private Bast_20 table copies, appends the\n"
            "donor slices, remaps internal indices, then redirects globals.\n"
            "No enemy is spawned in h.7.12.\n\n"
            "############################################################\n"
            "STAGE 1: WATER_20 DONOR CAPTURE\n"
            "############################################################\n"
        );

        const bool idleOk =
            R2R_CaptureWaterAglagl301(
                report
            );

        const bool actionOk =
            R2R_CaptureWaterAglaglActionBank(
                report
            );

        const bool ok =
            idleOk &&
            actionOk;

        fprintf(
            report,
            "\nSTAGE 1 RESULT: %s\n"
            "  idle General 301 capture : %s\n"
            "  action bank capture      : %s\n",
            ok ? "SUCCESS" : "FAILED",
            idleOk ? "SUCCESS" : "FAILED",
            actionOk ? "SUCCESS" : "FAILED"
        );

        fclose(report);

        MessageBoxA(
            nullptr,
            ok
            ? "WATER_20 ACTION ANIMATIONS CAPTURED!\n\n301, 302, 303 and 305 are preserved in memory.\n\nNow switch to Bast_20, wait until it is fully playable, then press F7 again.\n\nThe second F7 will install the expanded PRIVATE animation bank."
            : "Water_20 action-animation capture failed. Send Rayman2Randomizer_A3dMergedBank.txt.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | (ok ? MB_ICONINFORMATION : MB_ICONWARNING)
        );
        return;
    }

    if (isBast)
    {
        if (
            !g_A3dDonor301Captured ||
            !g_R2RActionBankCaptured
            )
        {
            MessageBoxA(
                nullptr,
                "Water_20 action-animation data is not captured in this process.\n\nStart fresh: Water_20 -> F3 -> F7, then Bast_20 -> F7.",
                "Rayman 2 Randomizer v0.0.14b.0",
                MB_OK | MB_ICONWARNING
            );
            return;
        }

        if (g_A3dMergedBankInstalled)
        {
            MessageBoxA(
                nullptr,
                "Aglagl's expanded action-animation bank is already installed.\n\nUse F6 three times for the guarded real-action test.\n\nF8 stays disabled for safety.",
                "Rayman 2 Randomizer v0.0.14b.0",
                MB_OK | MB_ICONINFORMATION
            );
            return;
        }

        FILE* report = nullptr;
        fopen_s(&report, A3D_MERGED_BANK_REPORT_FILE, "a");
        if (report == nullptr) return;

        fprintf(
            report,
            "\n\n############################################################\n"
            "STAGE 2: BAST_20 PRIVATE MERGED BANK INSTALL\n"
            "############################################################\n"
        );

        const bool ok = InstallMergedAnimationBank(report);
        fprintf(report, "\nSTAGE 2 VALIDATION: %s\n", ok ? "PASS" : "FAILED");
        fclose(report);

        if (!ok)
        {
            if (g_A3dMergedBankInstalled)
            {
                RestoreMergedAnimationBank(false);
            }

            MessageBoxA(
                nullptr,
                "MERGED BANK VALIDATION FAILED.\n\nThe original Bast_20 globals were restored.\n\nSend me:\nRayman2Randomizer_A3dMergedBank.txt",
                "Rayman 2 Randomizer v0.0.14b.0",
                MB_OK | MB_ICONWARNING
            );
            return;
        }

        char message[1024] = {};
        sprintf_s(
            message,
            "AGLAGL REAL ACTION ANIMATION BANK INSTALLED!\n\nSynthetic General mapping:\n301 -> %u\n302 -> %u\n303 -> %u\n305 -> %u\n\nGeneral 302's single animation event is DISABLED only for this first motion test.\n\nNow press F6 three times. The third F6 runs the PROJECTILE SUPEROBJECT AUDIT for up to 180 guarded frames.\n\nDo NOT change level after the merged bank is installed.",
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[0]
                ),
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[1]
                ),
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[2]
                ),
            static_cast<unsigned int>(
                g_R2RActionSyntheticGeneralIds[3]
                )
        );

        MessageBoxA(
            nullptr,
            message,
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONINFORMATION
        );
        return;
    }

    MessageBoxA(
        nullptr,
        "h.7.12 expects Water_20 first, then Bast_20.\n\nUse F1/F2 and F7.",
        "Rayman 2 Randomizer v0.0.14b.0",
        MB_OK | MB_ICONINFORMATION
    );
}



// ============================================================
// h.7.26 - KEEP THE WHOLE FAMILY ON THE SAME VISUAL TABLE
//
// h.7.25 proved that changing only the spawned object's CurrentObjectsTable
// is NOT enough. The object used the Bast_20 Piranha table, but the runtime
// Aglagl Family still had its Water_20 table as hDefaultObjectsTable.
//
// This test temporarily makes BOTH references use the same native Bast table.
// Rayman 2 still creates all visual channel objects itself.
// ============================================================

static bool R2R_SwapRuntimeFamilyDefaultToNativeTable()
{
    if (
        g_RuntimeAglaglFamily == nullptr ||
        g_SpawnedHybridActor == nullptr ||
        g_SpawnedHybridActor->h3dData == nullptr
        )
    {
        return false;
    }

    HIE_tdstObjectsTablesList* nativeTable =
        g_SpawnedHybridActor->h3dData->h_CurrentObjectsTable != nullptr
        ? g_SpawnedHybridActor->h3dData->h_CurrentObjectsTable
        : g_SpawnedHybridActor->h3dData->h_InitialObjectsTable;

    if (nativeTable == nullptr)
    {
        return false;
    }

    if (!g_R2RFamilyDefaultTableWasSwapped)
    {
        g_R2RFamilyDefaultTableBeforeTest =
            g_RuntimeAglaglFamily->hDefaultObjectsTable;

        g_R2RFamilyDefaultTableWasSwapped = true;
    }

    g_RuntimeAglaglFamily->hDefaultObjectsTable =
        nativeTable;

    return true;
}

static void R2R_RestoreRuntimeFamilyDefaultTable()
{
    if (
        g_R2RFamilyDefaultTableWasSwapped &&
        g_RuntimeAglaglFamily != nullptr
        )
    {
        g_RuntimeAglaglFamily->hDefaultObjectsTable =
            g_R2RFamilyDefaultTableBeforeTest;
    }

    g_R2RFamilyDefaultTableBeforeTest = nullptr;
    g_R2RFamilyDefaultTableWasSwapped = false;
}

// ============================================================
// h.7.22 DEBUG ORBIT CAMERA
//
// This uses Rayman 2's own "forced camera position / target" fields.
// The same method is used by existing Rayman 2 debug tooling.
// ============================================================

static CAM_tdstCineinfo* R2R_GetStandardCameraCineInfo()
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->g_hStdCamCharacter == nullptr
        )
    {
        return nullptr;
    }

    HIE_tdstEngineObject* cameraActor =
        HIE_M_hSuperObjectGetActor(
            GAM_g_stEngineStructure->g_hStdCamCharacter
        );

    if (cameraActor == nullptr)
    {
        return nullptr;
    }

    return cameraActor->hCineInfo;
}

static void R2R_ApplyDebugOrbitCamera()
{
    if (
        !g_R2RDebugCameraEnabled ||
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying
        )
    {
        return;
    }

    HIE_tdstSuperObject* rayman =
        HIE_M_hGetMainActor();

    CAM_tdstCineinfo* cine =
        R2R_GetStandardCameraCineInfo();

    if (
        rayman == nullptr ||
        rayman->p_stGlobalMatrix == nullptr ||
        cine == nullptr ||
        cine->hWork == nullptr
        )
    {
        return;
    }

    MTH3D_tdstVector target =
        rayman->p_stGlobalMatrix->stPos;

    // Aim a little above Rayman's feet.
    target.z += 1.5f;

    MTH3D_tdstVector cameraPos =
        target;

    switch (
        (g_R2RDebugCameraQuarter % 4 + 4) % 4
        )
    {
    default:
    case 0:
        cameraPos.x += R2R_DEBUG_CAMERA_DISTANCE;
        break;

    case 1:
        cameraPos.y += R2R_DEBUG_CAMERA_DISTANCE;
        break;

    case 2:
        cameraPos.x -= R2R_DEBUG_CAMERA_DISTANCE;
        break;

    case 3:
        cameraPos.y -= R2R_DEBUG_CAMERA_DISTANCE;
        break;
    }

    cameraPos.z +=
        R2R_DEBUG_CAMERA_HEIGHT;

    // Rebuild Work from the normal camera settings, then override only
    // the position/target for this frame.
    CAM_fn_vSetCineinfoWorkFromCurrent(
        cine
    );

    cine->stForcePosition =
        cameraPos;

    cine->stForceTarget =
        target;

    cine->hWork->uwIAFlags |=
        (
            CAM_C_IAFlags_PositionIsAlreadyComputed |
            CAM_C_IAFlags_TargetIsAlreadyComputed |
            CAM_C_IAFlags_NoDynamicTarget |
            CAM_C_IAFlags_NoDynSpeed |
            CAM_C_IAFlags_NoVisibility |
            CAM_C_IAFlags_NoVisibilityWithDynHie
            );

    cine->hWork->xLinearSpeed =
        1000.0f;

    cine->hWork->xAngularSpeed =
        1000.0f;

    cine->hWork->xTargetSpeed =
        1000.0f;

    cine->eState =
        CAM_e_State_GoToOptimal;

    // Apply the forced camera immediately after the normal engine update.
    CAM_fn_vUpdateTargetPosition(
        cine
    );

    CAM_fn_vCameraManagement();
}

static void R2R_WriteOne3dChannelSnapshot(
    FILE* report,
    const char* title,
    HIE_tdstSuperObject* superObject,
    HIE_tdstEngineObject* actor
)
{
    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "\n============================================================\n"
        "%s\n"
        "============================================================\n",
        title != nullptr ? title : "(object)"
    );

    if (
        actor == nullptr ||
        actor->h3dData == nullptr
        )
    {
        fprintf(
            report,
            "No readable 3D data.\n"
        );
        return;
    }

    GAM_tdst3dData* data =
        actor->h3dData;

    fprintf(
        report,
        "SuperObject              : %p\n"
        "Actor                    : %p\n"
        "World position           : %.3f %.3f %.3f\n"
        "SO draw mode mask        : 0x%08X\n"
        "SO flags                 : 0x%08X\n"
        "SO bounding volume       : %p\n"
        "Current frame            : %u\n"
        "Current state            : %p\n"
        "Current object table     : %p\n"
        "Family                   : %p\n"
        "Family default table     : %p\n"
        "3D channel count         : %lu\n"
        "Channel array            : %p\n"
        "First active channel     : %p\n"
        "Frame element array      : %p\n"
        "Frame number             : %u\n"
        "Current hierarchy        : %p\n"
        "Hierarchy couple count   : %u\n"
        "3D draw mask init        : 0x%08X\n"
        "3D draw mask             : 0x%08X\n"
        "Transparency             : %u\n",
        superObject,
        actor,
        (
            superObject != nullptr &&
            superObject->p_stGlobalMatrix != nullptr
            )
        ? superObject->p_stGlobalMatrix->stPos.x
        : 0.0f,
        (
            superObject != nullptr &&
            superObject->p_stGlobalMatrix != nullptr
            )
        ? superObject->p_stGlobalMatrix->stPos.y
        : 0.0f,
        (
            superObject != nullptr &&
            superObject->p_stGlobalMatrix != nullptr
            )
        ? superObject->p_stGlobalMatrix->stPos.z
        : 0.0f,
        superObject != nullptr
        ? static_cast<unsigned int>(
            superObject->lDrawModeMask
            )
        : 0,
        superObject != nullptr
        ? static_cast<unsigned int>(
            superObject->ulFlags
            )
        : 0,
        superObject != nullptr
        ? superObject->pBoundingVolume
        : nullptr,
        static_cast<unsigned int>(
            data->uwCurrentFrame
            ),
        data->h_CurrentState,
        data->h_CurrentObjectsTable,
        data->h_Family,
        data->h_Family != nullptr
        ? data->h_Family->hDefaultObjectsTable
        : nullptr,
        data->ulNumberOfChannels,
        data->hArrayOfChannels,
        data->hFirstActiveChannel,
        data->stFrame3d.p_stArrayOfElts3d,
        static_cast<unsigned int>(
            data->stFrame3d.uwFrameNumber
            ),
        data->p_stCurrentHieCouples,
        static_cast<unsigned int>(
            data->wCurrentHieNbCouples
            ),
        static_cast<unsigned int>(
            data->lDrawMaskInit
            ),
        static_cast<unsigned int>(
            data->lDrawMask
            ),
        static_cast<unsigned int>(
            data->ucTransparency
            )
    );

    if (
        data->hArrayOfChannels == nullptr ||
        data->ulNumberOfChannels == 0 ||
        data->ulNumberOfChannels > 64
        )
    {
        fprintf(
            report,
            "Channel list is empty or suspicious.\n"
        );
        return;
    }

    fprintf(
        report,
        "\nCHANNELS\n"
        "------------------------------------------------------------\n"
    );

    for (
        unsigned long i = 0;
        i < data->ulNumberOfChannels;
        i++
        )
    {
        GAM_tdstAChannel channel = {};

        if (!SafeReadMemory(
            data->hArrayOfChannels + i,
            &channel,
            sizeof(channel)
        ))
        {
            fprintf(
                report,
                "[%02lu] READ FAILED\n",
                i
            );
            continue;
        }

        MTH3D_tdstVector channelPos = {};

        const bool hasPosition =
            channel.hSupObject != nullptr &&
            channel.hSupObject->p_stGlobalMatrix != nullptr &&
            SafeReadMemory(
                &channel.hSupObject->p_stGlobalMatrix->stPos,
                &channelPos,
                sizeof(channelPos)
            );

        HIE_tdstSuperObject channelSO = {};
        bool channelSOReadable = false;

        if (
            channel.hSupObject != nullptr &&
            R2R_AddressReadable(
                reinterpret_cast<uintptr_t>(channel.hSupObject),
                sizeof(HIE_tdstSuperObject)
            ) &&
            SafeReadMemory(
                channel.hSupObject,
                &channelSO,
                sizeof(channelSO)
            )
            )
        {
            channelSOReadable = true;
        }

        fprintf(
            report,
            "[%02lu] SO=%p  ZoomSO=%p  next=%p  father=%p  controlled=%u  active=%u",
            i,
            channel.hSupObject,
            channel.hZoomSupObject,
            channel.p_stNextActiveChannel,
            channel.p_stFatherChannel,
            static_cast<unsigned int>(
                channel.bControlledChannel
                ),
            static_cast<unsigned int>(
                channel.bActiveChannel
                )
        );

        if (hasPosition)
        {
            fprintf(
                report,
                "  XYZ=%.3f %.3f %.3f",
                channelPos.x,
                channelPos.y,
                channelPos.z
            );
        }

        if (channelSOReadable)
        {
            fprintf(
                report,
                "  SOtype=0x%08X linked=%p draw=0x%08X flags=0x%08X bbox=%p",
                static_cast<unsigned int>(channelSO.ulType),
                channelSO.hLinkedObject.p_Void,
                static_cast<unsigned int>(channelSO.lDrawModeMask),
                static_cast<unsigned int>(channelSO.ulFlags),
                channelSO.pBoundingVolume
            );
        }
        else if (channel.hSupObject != nullptr)
        {
            fprintf(
                report,
                "  SO_DETAILS_UNREADABLE"
            );
        }

        fprintf(
            report,
            "\n"
        );
    }
}

static void R2R_WriteAglaglChannelAudit()
{
    if (
        g_R2RChannelAuditWritten ||
        g_SpawnedHybrid == nullptr ||
        g_SpawnedHybridActor == nullptr
        )
    {
        return;
    }

    HIE_tdstSuperObject* nativeSuper = nullptr;
    HIE_tdstEngineObject* nativeActor = nullptr;
    const char* nativeModel = nullptr;

    FindBast20ControlSource(
        nativeSuper,
        nativeActor,
        nativeModel
    );

    // h.7.23: the old report compared Aglagl with the dormant source Piranha,
    // whose live animation channels were not initialized. Prefer the Piranha
    // that we actually spawned beside Rayman in this same test.
    if (g_SpawnedControl != nullptr)
    {
        HIE_tdstEngineObject* liveControlActor =
            HIE_M_hSuperObjectGetActor(
                g_SpawnedControl
            );

        if (liveControlActor != nullptr)
        {
            nativeSuper = g_SpawnedControl;
            nativeActor = liveControlActor;
            nativeModel = "LIVE_SPAWNED_VISIBLE_PIRANHA";
        }
    }

    FILE* report = nullptr;

    fopen_s(
        &report,
        R2R_CHANNEL_AUDIT_FILE,
        "w"
    );

    if (report == nullptr)
    {
        return;
    }

    fprintf(
        report,
        "RAYMAN 2 RANDOMIZER\n"
        "v0.0.14b.0 - FULL REAL AGLAGL VISUAL AUDIT\n"
        "============================================================\n\n"
        "WHY THIS TEST EXISTS\n"
        "------------------------------------------------------------\n"
        "h.7.27 proved the NTTO index remap fix, and h.7.28 proved Aglagl's\n"
        "real Water_20 geometry is drawable in Bast_20 when using a safe native\n"
        "texture. This test removes that final substitution and uses Aglagl's\n"
        "real Water_20 materials and textures too.\n\n"
        "Native comparison model: %s\n",
        nativeModel != nullptr
        ? nativeModel
        : "(unknown)"
    );

    R2R_WriteOne3dChannelSnapshot(
        report,
        "LIVE AGLAGL TEST OBJECT",
        g_SpawnedHybrid,
        g_SpawnedHybridActor
    );

    R2R_WriteOne3dChannelSnapshot(
        report,
        "KNOWN-VISIBLE BAST_20 PIRANHA SOURCE",
        nativeSuper,
        nativeActor
    );

    fclose(report);

    g_R2RChannelAuditWritten = true;
}

// TEST 26: restored the previously working F1/F2 native level switch.
void JumpToLevel(const char* level)
{
    if (level == nullptr)
    {
        return;
    }

    if (g_A3dMergedBankInstalled)
    {
        MessageBoxA(
            nullptr,
            "The copied Aglagl animation is currently active.\n\n"
            "For safety, level changes are blocked now.\n"
            "Restart Rayman 2 when you want to start over.",
            "Rayman 2 Randomizer v0.0.14b.0",
            MB_OK | MB_ICONINFORMATION
        );
        return;
    }

    CleanupCrossLevelRuntimeSilently();

    GAM_fn_vAskToChangeLevel(
        level,
        FALSE
    );
}


