static const unsigned int R2R_RAYMAP_GAME_ORDER_COUNT =
static_cast<unsigned int>(sizeof(g_R2RRaymapGameOrder) / sizeof(g_R2RRaymapGameOrder[0]));

static bool R2R_LevelFolderInstalled(const char* name)
{
    if (name == nullptr || name[0] == '\0')
        return false;

    char snaPath[MAX_PATH] = {};
    char exePath[MAX_PATH]={};
    GetModuleFileNameA(nullptr,exePath,MAX_PATH);
    char* lastSlash=std::strrchr(exePath,'\\');
    if(lastSlash)lastSlash[1]='\0';else exePath[0]='\0';
    sprintf_s(snaPath,"%sData\\World\\Levels\\%s\\%s.sna",exePath,name,name);

    const DWORD attrs = GetFileAttributesA(snaPath);
    return
        attrs != INVALID_FILE_ATTRIBUTES &&
        !(attrs & FILE_ATTRIBUTE_DIRECTORY);
}

static unsigned int R2R_CollectInstalledLevels(
    char outLevels[R2R_LEVEL_SWITCH_MAX][R2R_LEVEL_NAME_MAX]
)
{
    unsigned int count = 0;

    // Exact order supplied in Raym.app.txt.  Do NOT alphabetically sort:
    // F1/F2 are intended to follow the actual game progression/test order.
    for (unsigned int i = 0;
        i < R2R_RAYMAP_GAME_ORDER_COUNT && count < R2R_LEVEL_SWITCH_MAX;
        ++i)
    {
        const char* name = g_R2RRaymapGameOrder[i];
        if (!R2R_LevelFolderInstalled(name))
            continue;

        strncpy_s(
            outLevels[count],
            R2R_LEVEL_NAME_MAX,
            name,
            _TRUNCATE
        );
        ++count;
    }

    return count;
}

static void R2R_LogQuickLevelSwitch(
    const char* direction,
    const char* fromLevel,
    const char* toLevel,
    unsigned int count
)
{
    FILE* f = nullptr;
    fopen_s(&f, R2R_LEVEL_SWITCH_REPORT, "a");
    if (f == nullptr)
        return;

    fprintf(
        f,
        "%s | %s | %s -> %s | detected=%u\n",
        VERSION,
        direction != nullptr ? direction : "?",
        fromLevel != nullptr ? fromLevel : "(unknown)",
        toLevel != nullptr ? toLevel : "(none)",
        count
    );
    fclose(f);
}

static void R2R_SwitchRelativeLevel(int delta)
{
    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying
        )
    {
        return;
    }

    char levels[R2R_LEVEL_SWITCH_MAX][R2R_LEVEL_NAME_MAX] = {};
    const unsigned int count = R2R_CollectInstalledLevels(levels);

    if (count == 0)
    {
        R2R_LogQuickLevelSwitch(
            delta >= 0 ? "F1 NEXT" : "F2 PREVIOUS",
            GAM_g_stEngineStructure->szLevelName,
            nullptr,
            0
        );
        MessageBoxA(
            nullptr,
            "No playable level folders were detected in Data\\World\\Levels.",
            "Rayman 2 Randomizer - Quick Level Switch",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    const char* current = GAM_g_stEngineStructure->szLevelName;
    int currentIndex = -1;

    if (current != nullptr)
    {
        for (unsigned int i = 0; i < count; ++i)
        {
            if (_stricmp(levels[i], current) == 0)
            {
                currentIndex = static_cast<int>(i);
                break;
            }
        }
    }

    int targetIndex = 0;
    if (currentIndex < 0)
    {
        targetIndex = delta >= 0
            ? 0
            : static_cast<int>(count) - 1;
    }
    else
    {
        targetIndex = currentIndex + (delta >= 0 ? 1 : -1);
        if (targetIndex >= static_cast<int>(count))
            targetIndex = 0;
        if (targetIndex < 0)
            targetIndex = static_cast<int>(count) - 1;
    }

    R2R_LogQuickLevelSwitch(
        delta >= 0 ? "F1 NEXT" : "F2 PREVIOUS",
        current,
        levels[targetIndex],
        count
    );

    JumpToLevel(levels[targetIndex]);
}

static void R2R_SwitchDirectLevel(const char* targetLevel, const char* label)
{
    if (
        targetLevel == nullptr ||
        targetLevel[0] == '\0' ||
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying
        )
    {
        return;
    }

    char snaPath[MAX_PATH] = {};
    sprintf_s(
        snaPath,
        ".\\Data\\World\\Levels\\%s\\%s.sna",
        targetLevel,
        targetLevel
    );

    const DWORD attrs = GetFileAttributesA(snaPath);
    if (
        attrs == INVALID_FILE_ATTRIBUTES ||
        (attrs & FILE_ATTRIBUTE_DIRECTORY)
        )
    {
        char msg[512] = {};
        _snprintf_s(
            msg,
            sizeof(msg),
            _TRUNCATE,
            "Level %s was not found at:\n%s",
            targetLevel,
            snaPath
        );
        MessageBoxA(
            nullptr,
            msg,
            "Rayman 2 Randomizer - Direct Level Teleport",
            MB_OK | MB_ICONWARNING
        );
        return;
    }

    R2R_LogQuickLevelSwitch(
        label != nullptr ? label : "DIRECT",
        GAM_g_stEngineStructure->szLevelName,
        targetLevel,
        1
    );

    JumpToLevel(targetLevel);
}




AI_tdstNodeInterpret* HookedAIEvalTree(
    HIE_tdstSuperObject* p_stSpo,
    AI_tdstNodeInterpret* p_stNode,
    AI_tdstGetSetParam* p_stParam
)
{
    const bool traceThisCall =
        g_R2RAITraceActive &&
        g_R2RAITraceFile != nullptr &&
        p_stSpo != nullptr &&
        p_stSpo == g_SpawnedHybrid;

    unsigned long sequence = 0;
    int depth = 0;
    bool r2rGenerateObjectThisCall = false;

    if (traceThisCall)
    {
        sequence =
            ++g_R2RAITraceSequence;

        depth =
            g_R2RAITraceDepth++;

        AI_tdstNodeInterpret node = {};
        const bool readable =
            p_stNode != nullptr &&
            SafeReadMemory(
                p_stNode,
                &node,
                sizeof(node)
            );

        if (readable)
        {
            fprintf(
                g_R2RAITraceFile,
                "ENTER  #%06lu depth=%d node=%p type=%u %-16s "
                "nodeDepth=%u skip=%u raw=%p rawDomain=%s\n",
                sequence,
                depth,
                p_stNode,
                static_cast<unsigned int>(node.eType),
                R2R_AITypeName(
                    static_cast<unsigned int>(node.eType)
                ),
                static_cast<unsigned int>(node.ucDepth),
                static_cast<unsigned int>(node.uwNodeToSkip),
                node.uParam.pvValue,
                PointerDomainFor3dAudit(
                    node.uParam.pvValue
                )
            );

            if (
                static_cast<unsigned int>(node.eType) == 3u &&
                static_cast<unsigned int>(
                    reinterpret_cast<uintptr_t>(node.uParam.pvValue)
                    ) == 0x42u
                )
            {
                r2rGenerateObjectThisCall = true;
            }

            // h.7.79: DsgVarRef raw is a BYTE OFFSET into the 80-byte DSG
            // buffer, not a pointer.  Annotate its owning variable so the
            // attack trace directly tells us which imported helper is used.
            if (static_cast<unsigned int>(node.eType) == 11u)
            {
                const unsigned int dsgOffset =
                    static_cast<unsigned int>(
                        reinterpret_cast<uintptr_t>(node.uParam.pvValue)
                        );

                const int ownerVar =
                    R2R_DsgVarOwnerForOffset(dsgOffset);

                fprintf(
                    g_R2RAITraceFile,
                    "       DSGREF offset=0x%02X ownerVar=%d role=%s\n",
                    dsgOffset,
                    ownerVar,
                    R2R_DsgCapturedRoleForVar(ownerVar)
                );
            }

            // h.7.81: resolve each UNIQUE constant PersoRef as an EngineObject/Actor once.
            // This is read-only and does not alter the interpreted node.
            if (static_cast<unsigned int>(node.eType) == 23u)
            {
                R2R_PersoRefAuditReportFirstSeen(
                    g_R2RAITraceFile,
                    node.uParam.pvValue
                );
            }
        }
        else
        {
            fprintf(
                g_R2RAITraceFile,
                "ENTER  #%06lu depth=%d node=%p UNREADABLE\n",
                sequence,
                depth,
                p_stNode
            );
        }

        fflush(g_R2RAITraceFile);
    }

    AI_tdstNodeInterpret* result =
        AI_fn_p_stEvalTree(
            p_stSpo,
            p_stNode,
            p_stParam
        );

    if (
        traceThisCall &&
        r2rGenerateObjectThisCall &&
        g_R2RStalacShootImportPrepared
        )
    {
        g_R2RStalacShootGenerateReturnedThisFrame = true;

        fprintf(
            g_R2RAITraceFile,
            "\nFUNCTION 0x42 RETURNED SAFELY\n"
            "The real STN_Stalac_shoot birth will be captured and quarantined at the end of this engine frame.\n"
        );
        fflush(g_R2RAITraceFile);
    }

    if (traceThisCall)
    {
        if (g_R2RAITraceDepth > 0)
        {
            g_R2RAITraceDepth--;
        }

        fprintf(
            g_R2RAITraceFile,
            "RETURN #%06lu depth=%d result=%p\n",
            sequence,
            depth,
            result
        );

        fflush(g_R2RAITraceFile);
    }

    return result;
}

static void R2R_RunDeferredPostProbeCleanupIfReady()
{
    if (!g_R2RPostProbeCleanupPending)
    {
        return;
    }

    if (
        GAM_g_stEngineStructure == nullptr ||
        GAM_g_stEngineStructure->eEngineMode != E_EM_ModePlaying ||
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Bast_20") != 0
        )
    {
        return;
    }

    g_R2RPostProbeCleanupFrames++;

    if (
        g_R2RPostProbeCleanupFrames <
        R2R_POST_PROBE_CLEANUP_DELAY_FRAMES
        )
    {
        return;
    }

    FILE* report = nullptr;
    fopen_s(&report, TRANSITION_CLEANUP_REPORT, "a");
    if (report != nullptr)
    {
        fprintf(
            report,
            "\nDeferred cleanup grace period completed: %u frames.\n"
            "Cleaning Aglagl shell/helpers/runtime families now.\n",
            g_R2RPostProbeCleanupFrames
        );
        fclose(report);
    }

    CleanupCrossLevelRuntimeSilently();

    // Restore only the engine's global animation pointers.  The copied bank
    // allocation itself stays alive so stale internal references remain valid.
    if (g_A3dMergedBankInstalled)
    {
        RestoreMergedAnimationBank(false);
    }

    // h.7.99: once all runtime actors/families are gone, remove the ObjectType
    // names that our DLL appended to the process-global lists.  Keeping them
    // linked into the menu transition can remap later serialized type indices
    // (the 7.98 symptom was the Bast_20 Piranha appearing as the menu cursor).
    FILE* typeReport = nullptr;
    fopen_s(&typeReport, R2R_OBJECTTYPE_CLEANUP_REPORT, "w");
    if (typeReport != nullptr)
    {
        fprintf(
            typeReport,
            "RAYMAN 2 RANDOMIZER\n"
            "v0.0.14b.0 - OBJECTTYPE TRANSITION CLEANUP\n"
            "============================================================\n"
            "Path: deferred post-probe cleanup while Bast_20 is still playing.\n"
        );
    }
    R2R_DetachInsertedObjectTypes(typeReport);
    if (typeReport != nullptr)
    {
        fclose(typeReport);
    }

    g_R2RPostProbeCleanupPending = false;
    g_R2RPostProbeCleanupFrames = 0;

    fopen_s(&report, TRANSITION_CLEANUP_REPORT, "a");
    if (report != nullptr)
    {
        fprintf(
            report,
            "Deferred cleanup COMPLETE.\n"
            "Merged globals restored : %s\n"
            "Merged memory retained   : YES\n",
            g_A3dMergedBankInstalled ? "NO" : "YES"
        );
        fclose(report);
    }
}

