static int R2R_Batam10PathTargetIndex(int rateTarget)
{
    for (unsigned int i = 0; i < R2R_BATAM10_PATH_TARGET_COUNT; ++i)
        if (rateTarget >= 0 && static_cast<unsigned int>(rateTarget) == g_R2RBatam10PathTargets[i].rateTarget)
            return static_cast<int>(i);
    return -1;
}
struct R2R_Batam10PathEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    DNM_tdstDynamics* dynamics;
    AI_tdstMind* mind;
    AI_tdstAIModel* model;
    AI_tdstDsgMem* memory;
    AI_tdstDsgVar* definition;
    AI_tdstScriptAI* script;
    char* buffer;
    unsigned long bytes;
    unsigned int target;
    int phase;
    uint32_t waypoints[3];
    unsigned int visit;
    int loggedMode;
    int loggedPhase;
    int loggedMoving;
    unsigned int hookLogs;
    unsigned int hookHits;
    unsigned int scaledHits;
    char personal[96];
};
static R2R_Batam10PathEntry g_R2RBatam10PathEntries[R2R_BATAM10_PATH_MAX_ACTORS] = {};
static unsigned int g_R2RBatam10PathVisit = 0;
static unsigned int g_R2RBatam10PathFrame = 0;
static bool g_R2RBatam10PathSkipLogged[R2R_BATAM10_PATH_TARGET_COUNT] = {};
static unsigned int g_R2RBatam10PathCaptureCursor = 0;
static unsigned int R2R_Batam10PathWidth(unsigned int type)
{
    return type == 0 || type == 1 || type == 2 ? 1 : type == 11 ? 12 : 4;
}
static void R2R_Batam10PathSkip(unsigned int target, const char* reason)
{
    if (target >= R2R_BATAM10_PATH_TARGET_COUNT || g_R2RBatam10PathSkipLogged[target] || !R2R_Batam10MoveStartReport()) return;
    const auto& t = g_R2RBatam10PathTargets[target];
    FILE* f = nullptr; fopen_s(&f, R2R_BATAM10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[BATAM10-PATH-SKIP] family=%s model=%s personal=%s path=%s reason=%s\n",
        t.family, t.model, t.personal, t.path, reason);
    fclose(f); g_R2RBatam10PathSkipLogged[target] = true;
}
static bool R2R_Batam10PathLayout(unsigned int target, const AI_tdstMind& mind, AI_tdstDsgMem& memory,
    AI_tdstDsgVar*& definition, AI_tdstDsgVar& vars)
{
    if (target >= R2R_BATAM10_PATH_TARGET_COUNT) return false;
    const auto& t = g_R2RBatam10PathTargets[target];
    AI_tdstAIModel model = {};
    if (!R2R_Batam10MovementRead(mind.p_stAIModel, model) ||
        !R2R_Batam10MovementRead(mind.p_stDsgMem, memory) ||
        !R2R_Batam10MovementRead(memory.pp_stDsgVar, definition) ||
        definition == nullptr || definition != model.p_stDsgVar ||
        !R2R_Batam10MovementRead(definition, vars) || vars.ucNbDsgVar != t.variables ||
        vars.a_stDsgVarInfo == nullptr || vars.ulBufferSize < t.minimumBytes || vars.ulBufferSize > 256 ||
        memory.p_cDsgMemBuffer == nullptr) return false;
    // The screenshot supplies the types, not the offsets. Read native offsets
    // and verify their complete spans and non-overlap instead of inventing them.
    // DSG is only read: a current buffer aliasing init/default is acceptable.
    bool occupied[256] = {};
    for (unsigned int i = 0; i < t.variables; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Batam10MovementRead(vars.a_stDsgVarInfo + i, info)) return false;
        const unsigned int type = static_cast<unsigned int>(info.eTypeId);
        // Accept either native signed/unsigned four-byte integer for an Int field.
        if (type != t.types[i] && !(t.types[i] == 5 && type == 6)) return false;
        const unsigned int width = R2R_Batam10PathWidth(type);
        if (info.ulOffsetInDsgMem >= vars.ulBufferSize ||
            width > vars.ulBufferSize - info.ulOffsetInDsgMem) return false;
        for (unsigned long j = info.ulOffsetInDsgMem; j < info.ulOffsetInDsgMem + width; ++j)
        {
            if (occupied[j]) return false; occupied[j] = true;
        }
    }
    return R2R_AddressReadable(reinterpret_cast<uintptr_t>(memory.p_cDsgMemBuffer), vars.ulBufferSize);
}
static bool R2R_Batam10PathSnapshot(HIE_tdstSuperObject* object,
    const R2R_Batam10Identity& identity, R2R_Batam10PathEntry& result)
{
    const int target = R2R_Batam10PathTargetIndex(identity.target);
    if (target < 0) return false;
    const auto& t = g_R2RBatam10PathTargets[target];
    HIE_tdstEngineObject actor = {}; AI_tdstBrain brain = {}; AI_tdstMind mind = {};
    AI_tdstDsgMem memory = {}; AI_tdstDsgVar* definition = nullptr;
    AI_tdstDsgVar vars = {}; AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr;
    AI_tdstScriptAI scripts = {};
    if (!R2R_Batam10MovementRead(identity.actor, actor) ||
        !R2R_Batam10MovementRead(actor.hBrain, brain) || !R2R_Batam10MovementRead(brain.p_stMind, mind) ||
        !R2R_Batam10PathLayout(static_cast<unsigned int>(target), mind, memory, definition, vars) ||
        !R2R_Batam10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Batam10MovementRead(intel.pp_stScriptAI, script) || !R2R_Batam10MovementRead(script, scripts)) return false;
    const int phase = R2R_Batam10MovementPhase(mind, 0);
    if (phase < 0) return false;
    result = R2R_Batam10PathEntry(); result.owner = object; result.actor = identity.actor;
    // Script-driven cinematics can lack a dynamics block. Keep their exact
    // brain/DSG snapshot for diagnosis; only live mechanics can be modified.
    DNM_tdstDynam dynam = {};
    if (R2R_Batam10MovementRead(actor.hDynam, dynam) && dynam.p_stDynamics != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stDynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        result.dynamics = dynam.p_stDynamics;
    result.mind = brain.p_stMind; result.model = mind.p_stAIModel;
    result.memory = mind.p_stDsgMem; result.definition = definition; result.script = script;
    result.buffer = memory.p_cDsgMemBuffer; result.bytes = vars.ulBufferSize; result.phase = phase; result.target = static_cast<unsigned int>(target);
    if (t.waypointCount == 0 || t.waypointCount > 3 || t.firstWaypoint >= t.variables ||
        t.waypointCount > t.variables - t.firstWaypoint) return false;
    for (unsigned int i = 0; i < t.waypointCount; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Batam10MovementRead(vars.a_stDsgVarInfo + t.firstWaypoint + i, info) ||
            static_cast<unsigned int>(info.eTypeId) != 8 ||
            !SafeReadMemory(result.buffer + info.ulOffsetInDsgMem, &result.waypoints[i], 4)) return false;
    }
    std::memcpy(result.personal, identity.personal, sizeof(result.personal));
    return true;
}
static bool R2R_Batam10PathSame(const R2R_Batam10PathEntry& a, const R2R_Batam10PathEntry& b)
{
    return a.owner == b.owner && a.actor == b.actor && a.dynamics == b.dynamics && a.mind == b.mind &&
        a.model == b.model && a.memory == b.memory && a.definition == b.definition &&
        a.script == b.script && a.buffer == b.buffer && a.bytes == b.bytes && a.target == b.target;
}
static void R2R_Batam10PathProcess(HIE_tdstSuperObject* object)
{
    R2R_Batam10Identity identity = {}; R2R_Batam10PathEntry current = {};
    if (!R2R_Batam10ReadIdentity(object, identity)) return;
    const int target = R2R_Batam10PathTargetIndex(identity.target);
    if (target < 0) return;
    if (!R2R_Batam10PathSnapshot(object, identity, current))
    {
        R2R_Batam10PathSkip(static_cast<unsigned int>(target), "typed buffer or script unavailable"); return;
    }
    R2R_NoMomentumObserveMotionTarget(object, R2R_NO_MOMENTUM_NAMED);
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_BATAM10_PATH_MAX_ACTORS; ++i)
    {
        if (R2R_Batam10PathSame(g_R2RBatam10PathEntries[i], current)) { slot = static_cast<int>(i); break; }
        if (g_R2RBatam10PathEntries[i].owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0) { R2R_Batam10PathSkip(static_cast<unsigned int>(target), "tracking table full"); return; }
    R2R_Batam10PathEntry& e = g_R2RBatam10PathEntries[slot];
    if (!fresh && e.visit == g_R2RBatam10PathVisit) return;
    if (fresh)
    {
        e = current; e.loggedMode = -1; e.loggedPhase = -1; e.loggedMoving = -1;
        FILE* f = nullptr; fopen_s(&f, R2R_BATAM10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RBatam10PathTargets[e.target];
            fprintf(f, "[BATAM10-PATH-TRACK] family=%s model=%s personal=%s path=%s "
                "phase=%d bytes=%lu owner=%p dynamics=%p buffer=%p\n",
                t.family, t.model, t.personal, t.path, e.phase, e.bytes,
                static_cast<void*>(object), static_cast<void*>(e.dynamics), static_cast<void*>(e.buffer)); fclose(f);
        }
    }
    e.phase = current.phase; std::memcpy(e.waypoints, current.waypoints, sizeof(e.waypoints)); e.visit = g_R2RBatam10PathVisit;
}
static void R2R_Batam10PathScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_Batam10PathProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr) R2R_Batam10PathScan(object, depth + 1);
    }
}
// These scripts are not in the supplied reports. Capture only eight exact targets
// in small, delayed batches so a non-mechanical trajectory can be diagnosed
// without large startup captures. Raw references stay opaque.
struct R2R_Batam10PathCapture
{
    AI_tdstAIModel* model;
    AI_tdstScriptAI* script;
    unsigned int comport;
    unsigned int rule;
    unsigned int node;
    unsigned int total;
    bool started;
    bool complete;
};
static R2R_Batam10PathCapture g_R2RBatam10PathCaptures[R2R_BATAM10_PATH_TARGET_COUNT] = {};
static void R2R_Batam10PathCaptureStep(const R2R_Batam10PathEntry& e)
{
    if (e.target >= R2R_BATAM10_PATH_TARGET_COUNT || g_R2RBatam10PathFrame < 120 || g_R2RBatam10PathCaptures[e.target].complete) return;
    const auto& t = g_R2RBatam10PathTargets[e.target];
    R2R_Batam10Identity identity = {}; R2R_Batam10PathEntry current = {};
    AI_tdstScriptAI script = {}; AI_tdstDsgVar vars = {};
    if (!R2R_Batam10ReadIdentity(e.owner, identity) || !R2R_Batam10PathSnapshot(e.owner, identity, current) ||
        !R2R_Batam10PathSame(e, current) || !R2R_Batam10MovementRead(e.script, script) ||
        !R2R_Batam10MovementRead(e.definition, vars)) return;
    if (script.ulNbComport == 0 || script.ulNbComport > 64 || script.a_stComport == nullptr) return;
    auto& capture = g_R2RBatam10PathCaptures[e.target];
    if (capture.started && (capture.model != e.model || capture.script != e.script)) return;
    FILE* f = nullptr; fopen_s(&f, R2R_BATAM10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    if (!capture.started)
    {
        capture.model = e.model; capture.script = e.script; capture.started = true;
        fprintf(f, "[BATAM10-PATH-AI-CAPTURE] target=%u family=%s model=%s personal=%s path=%s comports=%lu "
            "variables=%u bytes=%lu budgetPerFrame=64 totalBudget=8192 modelPtr=%p script=%p\n",
            e.target, t.family, t.model, t.personal, t.path, script.ulNbComport, static_cast<unsigned int>(vars.ucNbDsgVar), vars.ulBufferSize,
            static_cast<void*>(e.model), static_cast<void*>(e.script));
        for (unsigned int i = 0; i < t.variables; ++i)
        {
            AI_tdstDsgVarInfo info = {}; uint32_t raw = 0;
            if (!R2R_Batam10MovementRead(vars.a_stDsgVarInfo + i, info)) break;
            const unsigned int type = static_cast<unsigned int>(info.eTypeId);
            const unsigned int width = R2R_Batam10PathWidth(type);
            if (!SafeReadMemory(e.buffer + info.ulOffsetInDsgMem, &raw, width == 1 ? 1 : 4)) break;
            fprintf(f, "[BATAM10-PATH-DSG] target=%u var=%u type=%u offset=%lu raw=0x%08X", e.target, i, type, info.ulOffsetInDsgMem, raw);
            if (type == 7) { float value = 0; std::memcpy(&value, &raw, 4); fprintf(f, " float=%.9g", value); }
            fprintf(f, "\n");
        }
    }
    unsigned int budget = 64;
    while (budget && capture.comport < script.ulNbComport && capture.total < 8192)
    {
        AI_tdstComport comport = {};
        if (!R2R_Batam10MovementRead(script.a_stComport + capture.comport, comport) || comport.ucNbRules > 64)
        {
            fprintf(f, "[BATAM10-PATH-AI-UNAVAILABLE] target=%u comport=%u\n", e.target, capture.comport); ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        const bool schedule = capture.rule == comport.ucNbRules;
        if (capture.rule > comport.ucNbRules || (schedule && comport.p_stSchedule == nullptr))
        {
            ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        AI_tdstTreeInterpret* tree = schedule ? comport.p_stSchedule : comport.a_stRules == nullptr ?
            nullptr : comport.a_stRules + capture.rule;
        AI_tdstTreeInterpret rule = {}; AI_tdstNodeInterpret node = {};
        if (capture.node >= 512 || !R2R_Batam10MovementRead(tree, rule) || rule.p_stNodeInterpret == nullptr ||
            !R2R_Batam10MovementRead(rule.p_stNodeInterpret + capture.node, node))
        {
            fprintf(f, "[BATAM10-PATH-AI-UNAVAILABLE] target=%u comport=%u rule=%u schedule=%u node=%u\n",
                e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node); ++capture.rule; capture.node = 0; --budget; continue;
        }
        fprintf(f, "[BATAM10-PATH-AI-NODE] target=%u comport=%u rule=%u schedule=%u node=%u type=%u depth=%u "
            "skip=%u raw=0x%08X\n", e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node,
            static_cast<unsigned int>(node.eType), static_cast<unsigned int>(node.ucDepth),
            static_cast<unsigned int>(node.uwNodeToSkip), static_cast<unsigned int>(reinterpret_cast<uintptr_t>(node.uParam.pvValue)));
        ++capture.node; ++capture.total; --budget;
        if (static_cast<unsigned int>(node.eType) == 8) { ++capture.rule; capture.node = 0; }
    }
    if (capture.comport >= script.ulNbComport || capture.total >= 8192)
    {
        fprintf(f, "[BATAM10-PATH-AI-CAPTURE-END] target=%u nodes=%u complete=%s\n", e.target, capture.total,
            capture.comport >= script.ulNbComport ? "YES" : "BUDGET_LIMIT"); capture.complete = true;
    }
    fclose(f);
}
static void R2R_Batam10PathForgetWorld()
{
    std::memset(g_R2RBatam10PathEntries, 0, sizeof(g_R2RBatam10PathEntries));
    std::memset(g_R2RBatam10PathCaptures, 0, sizeof(g_R2RBatam10PathCaptures));
    std::memset(g_R2RBatam10PathSkipLogged, 0, sizeof(g_R2RBatam10PathSkipLogged));
    g_R2RBatam10PathFrame = 0;g_R2RBatam10PathCaptureCursor = 0;
}
static void R2R_Batam10PathControlTick()
{
    if (!R2R_Batam10MovePlaying()) { R2R_Batam10PathForgetWorld(); return; }
    R2R_Batam10MoveStartReport(); ++g_R2RBatam10PathVisit; ++g_R2RBatam10PathFrame;
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    R2R_Batam10PathScan(active, 0); if (inactive != active)R2R_Batam10PathScan(inactive, 0);
    for (auto& e : g_R2RBatam10PathEntries)
        if (e.visit != g_R2RBatam10PathVisit)e = R2R_Batam10PathEntry();
    // Only one capture step in the entire tick: eight targets share 64 nodes/frame.
    for (unsigned int attempt = 0;attempt < R2R_BATAM10_PATH_TARGET_COUNT;++attempt)
    {
        const unsigned int target = (g_R2RBatam10PathCaptureCursor + attempt) % R2R_BATAM10_PATH_TARGET_COUNT;
        const auto& capture = g_R2RBatam10PathCaptures[target];
        if (capture.complete)continue;
        for (const auto& e : g_R2RBatam10PathEntries)
        {
            if (e.owner == nullptr || e.target != target || (capture.started &&
                (e.model != capture.model || e.script != capture.script)))continue;
            R2R_Batam10PathCaptureStep(e);g_R2RBatam10PathCaptureCursor = (target + 1) % R2R_BATAM10_PATH_TARGET_COUNT;return;
        }
    }
}

static bool R2R_Batam10PathWritable(const void* address, size_t length)
{
    if (address == nullptr || length == 0) return false;
    MEMORY_BASIC_INFORMATION info = {};
    if (VirtualQuery(address, &info, sizeof(info)) == 0 || info.State != MEM_COMMIT ||
        (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const DWORD p = info.Protect & 0xff;
    if (p != PAGE_READWRITE && p != PAGE_WRITECOPY &&
        p != PAGE_EXECUTE_READWRITE && p != PAGE_EXECUTE_WRITECOPY) return false;
    const uintptr_t start = reinterpret_cast<uintptr_t>(address);
    const uintptr_t base = reinterpret_cast<uintptr_t>(info.BaseAddress);
    return start >= base && start - base < info.RegionSize &&
        length <= info.RegionSize - (start - base) && R2R_AddressReadable(start, length);
}
static R2R_Batam10PathEntry* R2R_Batam10PathLiveMechanics(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, R2R_Batam10PathEntry& current)
{
    if (!R2R_Batam10MovePlaying() || object == nullptr || object == HIE_M_hGetMainActor() ||
        dynamics == nullptr) return nullptr;
    for (auto& e : g_R2RBatam10PathEntries)
    {
        if (e.owner != object || e.dynamics != dynamics || e.visit != g_R2RBatam10PathVisit) continue;
        R2R_Batam10Identity identity = {};
        if (!R2R_Batam10ReadIdentity(object, identity) ||
            !R2R_Batam10PathSnapshot(object, identity, current) || !R2R_Batam10PathSame(e, current)) return nullptr;
        return &e;
    }
    return nullptr;
}
static bool R2R_Batam10PathBeginMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    MTH_tdxReal dt, MTH3D_tdstVector& original, MTH3D_tdstVector& applied)
{
    R2R_Batam10PathEntry current = {}; MTH3D_tdstVector before = {};
    R2R_Batam10PathEntry* e = R2R_Batam10PathLiveMechanics(object, dynamics, current);
    if (e == nullptr || !R2R_Batam10MovementRead(&dynamics->stDynamicsBase.stImposeSpeed, before)) return false;
    const bool validVector = std::isfinite(before.x) && std::isfinite(before.y) && std::isfinite(before.z) &&
        std::fabs(before.x) <= 1000 && std::fabs(before.y) <= 1000 && std::fabs(before.z) <= 1000;
    const bool moving = validVector && std::fabs(before.x) + std::fabs(before.y) + std::fabs(before.z) > .00001f;
    const bool pathReady = current.waypoints[0] != 0 || current.waypoints[1] != 0 || current.waypoints[2] != 0;
    const bool validDT = std::isfinite(dt) && dt > 0 && dt <= .25f;
    const float factor = R2R_Batam10MoveFactor();
    bool modified = false;
    original = before; applied = before;
    if (pathReady && moving && validDT && factor != 1 &&
        R2R_Batam10PathWritable(&dynamics->stDynamicsBase.stImposeSpeed, sizeof(applied)))
    {
        applied = { before.x * factor, before.y * factor, before.z * factor };
        std::memcpy(&dynamics->stDynamicsBase.stImposeSpeed, &applied, sizeof(applied));
        modified = true; ++e->scaledHits;
    }
    ++e->hookHits;
    if (e->loggedMode != g_R2RBatam10RateMode) e->hookLogs = 0;
    // Short samples show native stops and missing path references as well as writes.
    const int status = !validVector || !validDT ? -2 : !pathReady ? 0 : !moving ? 1 : modified ? 3 : 2;
    if (e->hookLogs < 24 && (e->hookLogs == 0 || e->loggedMode != g_R2RBatam10RateMode ||
        e->loggedPhase != current.phase || e->loggedMoving != status || (modified && e->hookLogs < 8)))
    {
        FILE* f = nullptr; fopen_s(&f, R2R_BATAM10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RBatam10PathTargets[current.target];
            fprintf(f, "[BATAM10-PATH-SPEED] family=%s model=%s personal=%s path=%s "
                "mode=%d phase=%d pathReady=%s moving=%s validVector=%s validDT=%s modified=%s "
                "requestedFactor=%.3f appliedFactor=%.3f inputDT=%.9g appliedDT=%.9g "
                "before=(%.6f %.6f %.6f) applied=(%.6f %.6f %.6f) "
                "waypoints=(0x%08X 0x%08X 0x%08X) owner=%p hookHits=%u scaledHits=%u\n",
                t.family, t.model, t.personal, t.path, g_R2RBatam10RateMode, current.phase, pathReady ? "YES" : "NO", moving ? "YES" : "NO",
                validVector ? "YES" : "NO", validDT ? "YES" : "NO", modified ? "YES" : "NO",
                factor, modified ? factor : 1.0f, static_cast<double>(dt), static_cast<double>(dt),
                before.x, before.y, before.z, applied.x, applied.y, applied.z,
                current.waypoints[0], current.waypoints[1], current.waypoints[2], static_cast<void*>(object), e->hookHits, e->scaledHits);
            fclose(f); ++e->hookLogs;
        }
    }
    e->loggedMode = g_R2RBatam10RateMode; e->loggedPhase = current.phase; e->loggedMoving = status;
    return modified;
}
static void R2R_Batam10PathEndMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    const MTH3D_tdstVector& original, const MTH3D_tdstVector& applied)
{
    R2R_Batam10PathEntry current = {}; MTH3D_tdstVector after = {};
    if (R2R_Batam10PathLiveMechanics(object, dynamics, current) == nullptr ||
        !R2R_Batam10MovementRead(&dynamics->stDynamicsBase.stImposeSpeed, after) ||
        after.x != applied.x || after.y != applied.y || after.z != applied.z ||
        !R2R_Batam10PathWritable(&dynamics->stDynamicsBase.stImposeSpeed, sizeof(original))) return;
    // Restore only our own temporary command, preserving native stops/new commands.
    std::memcpy(&dynamics->stDynamicsBase.stImposeSpeed, &original, sizeof(original));
}

