{
    return R2R_StatsLegacyFactorForLevel(g_R2RChase10RateMode, "Chase_10", 0x10Cu);
}
static bool R2R_Chase10MoveStartReport()
{
    if (g_R2RChase10MovementReportStarted) return true;
    FILE* f = nullptr; fopen_s(&f, R2R_CHASE10_MOVEMENT_REPORT, "w");
    if (f == nullptr) return false;
    fprintf(f, "%s CHASE_10 FOUR BARRELS, BOAT AND RAYMAN FRG_FIN PATH TEST\n"
        "Barrels: FRG_Way_2/3/4/5; OLD_tonneau_reseau Float_3 x4 / x0.25 / native.\n"
        "All four Chase_10 barrels keep native inertia; speed variation remains. Learn_30 retains its separately requested travel-only fix.\n"
        "Boat: FRG_Bato_Way_1 Graph_4/WayPoint_15, finite native command x4 / x0.25 / native.\n"
        "Boat DSG/DT/flags remain native; its screenshot supplies only a 24-variable prefix.\n"
        "Rayman end: ARG_Rayseau, exact Graph_0 name FRG_Fin, WayPoint_3 and full 17-field/14-comport layout.\n"
        "Only this network permits an unnamed helper; main actor is excluded before every metadata getter.\n"
        "End mechanics DT x4 / x0.25 / native, capped by the live waypoint radius; no persistent writes.\n"
        "No implicit projectile-physics changes. Other Rayman networks stay native.\n"
        "Six path identities share delayed capture after 120 ticks, <=64 nodes/frame total.\n"
        "Global Stats controls drive MIN/MAX/RANDOM/NATIVE for this validated route. Hook=%s.\n", VERSION,
        g_R2RMovementHookInstalled ? "YES" : "NO");
    fclose(f); g_R2RChase10MovementReportStarted = true; return true;
}
static int R2R_Chase10MovementPhase(const AI_tdstMind& mind, unsigned long expectedCount)
{
    AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr; AI_tdstScriptAI s = {};
    if (!R2R_Chase10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Chase10MovementRead(intel.pp_stScriptAI, script) ||
        !R2R_Chase10MovementRead(script, s) || s.a_stComport == nullptr ||
        s.ulNbComport == 0 || s.ulNbComport > 64 ||
        (expectedCount != 0 && s.ulNbComport != expectedCount)) return -1;
    const uintptr_t first = reinterpret_cast<uintptr_t>(s.a_stComport);
    const uintptr_t current = reinterpret_cast<uintptr_t>(intel.p_stCurrentComport);
    const size_t span = sizeof(AI_tdstComport) * s.ulNbComport;
    if (current < first || current - first >= span || (current - first) % sizeof(AI_tdstComport) != 0 ||
        !R2R_AddressReadable(current, sizeof(AI_tdstComport))) return -1;
    return static_cast<int>((current - first) / sizeof(AI_tdstComport));
}

