static R2R_Chase10PathEntry g_R2RChase10PathEntries[R2R_CHASE10_PATH_MAX_ACTORS] = {};
static unsigned int g_R2RChase10PathVisit = 0;
static unsigned int g_R2RChase10PathFrame = 0;
static bool g_R2RChase10PathSkipLogged[R2R_CHASE10_PATH_TARGET_COUNT] = {};
static unsigned int g_R2RChase10PathCaptureCursor = 0;
static unsigned int R2R_Chase10PathWidth(unsigned int type)
{
    return type == 0 || type == 1 || type == 2 ? 1 : type == 11 ? 12 : type == 10 ? 16 : 4;
}
static void R2R_Chase10PathSkip(unsigned int target, const char* reason)
{
    if (target >= R2R_CHASE10_PATH_TARGET_COUNT || g_R2RChase10PathSkipLogged[target] || !R2R_Chase10MoveStartReport()) return;
    const auto& t = g_R2RChase10PathTargets[target];
    FILE* f = nullptr; fopen_s(&f, R2R_CHASE10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[CHASE10-PATH-SKIP] family=%s model=%s personal=%s path=%s reason=%s\n",
        t.family, t.model, t.personal, t.path, reason);
    fclose(f); g_R2RChase10PathSkipLogged[target] = true;
}
static bool R2R_Chase10PathLayout(unsigned int target, const AI_tdstMind& mind, AI_tdstDsgMem& memory,
    AI_tdstDsgVar*& definition, AI_tdstDsgVar& vars)
{
    if (target >= R2R_CHASE10_PATH_TARGET_COUNT) return false;
    const auto& t = g_R2RChase10PathTargets[target];
    AI_tdstAIModel model = {};
    if (!R2R_Chase10MovementRead(mind.p_stAIModel, model) ||
        !R2R_Chase10MovementRead(mind.p_stDsgMem, memory) ||
        !R2R_Chase10MovementRead(memory.pp_stDsgVar, definition) ||
        definition == nullptr || definition != model.p_stDsgVar ||
        !R2R_Chase10MovementRead(definition, vars) || (t.exactLayout ? vars.ucNbDsgVar != t.variables : vars.ucNbDsgVar < t.variables || vars.ucNbDsgVar > 64) ||
        vars.a_stDsgVarInfo == nullptr || vars.ulBufferSize < t.minimumBytes || vars.ulBufferSize > 256 ||
        memory.p_cDsgMemBuffer == nullptr) return false;
    // The screenshot supplies the types, not the offsets. Read native offsets
    // and verify their complete spans and non-overlap instead of inventing them.
    // Boat DSG is only read. Barrel scalar writes separately reject init/default aliases.
    bool occupied[256] = {};
    for (unsigned int i = 0; i < vars.ucNbDsgVar; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Chase10MovementRead(vars.a_stDsgVarInfo + i, info)) return false;
        const unsigned int type = static_cast<unsigned int>(info.eTypeId);
        // Accept either native signed/unsigned four-byte integer for an Int field.
        if (type > 17 || (i < t.variables && type != t.types[i] && !(t.types[i] == 5 && type == 6))) return false;
        const unsigned int width = R2R_Chase10PathWidth(type);
        if (info.ulOffsetInDsgMem >= vars.ulBufferSize ||
            width > vars.ulBufferSize - info.ulOffsetInDsgMem) return false;
        for (unsigned long j = info.ulOffsetInDsgMem; j < info.ulOffsetInDsgMem + width; ++j)
        {
            if (occupied[j]) return false; occupied[j] = true;
        }
    }
    return R2R_AddressReadable(reinterpret_cast<uintptr_t>(memory.p_cDsgMemBuffer), vars.ulBufferSize);
}
// Use the real SDK graph field, never a guessed graph-name offset.
// Primary declaration: raytools/ACP_Ray2, src/AI/AI_Way.h.
static bool R2R_Chase10RayEndGraph(uint32_t reference)
{
    WP_tdstGraph graph = {}; char name[96] = {};
    return reference != 0 && R2R_Chase10MovementRead(
        reinterpret_cast<const WP_tdstGraph*>(static_cast<uintptr_t>(reference)), graph) &&
        R2R_Chase10CopyName(graph.m_szNameOfGraph, name, sizeof(name)) &&
        _stricmp(name, "FRG_Fin") == 0;
}
static bool R2R_Chase10PathSnapshot(HIE_tdstSuperObject* object,
    const R2R_Chase10Identity& identity, R2R_Chase10PathEntry& result)
{
    const int target = R2R_Chase10PathTargetIndex(identity.target);
    if (target < 0) return false;
    const auto& t = g_R2RChase10PathTargets[target];
    HIE_tdstEngineObject actor = {}; AI_tdstBrain brain = {}; AI_tdstMind mind = {};
    AI_tdstDsgMem memory = {}; AI_tdstDsgVar* definition = nullptr;
    AI_tdstDsgVar vars = {}; AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr;
    AI_tdstScriptAI scripts = {};
    if (!R2R_Chase10MovementRead(identity.actor, actor) ||
        !R2R_Chase10MovementRead(actor.hBrain, brain) || !R2R_Chase10MovementRead(brain.p_stMind, mind) ||
        !R2R_Chase10PathLayout(static_cast<unsigned int>(target), mind, memory, definition, vars) ||
        !R2R_Chase10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Chase10MovementRead(intel.pp_stScriptAI, script) || !R2R_Chase10MovementRead(script, scripts)) return false;
    const int phase = R2R_Chase10MovementPhase(mind, 0);
    if (phase < 0 || (target < 4 && scripts.ulNbComport != 6) ||
        (static_cast<unsigned int>(target) == R2R_CHASE10_RAY_END_TARGET && scripts.ulNbComport != 14)) return false;
    result = R2R_Chase10PathEntry(); result.owner = object; result.actor = identity.actor;
    // Script-driven cinematics can lack a dynamics block. Keep their exact
    // brain/DSG snapshot for diagnosis; boat writes require live mechanics.
    // Barrel scalar writes separately require an isolated writable current buffer.
    DNM_tdstDynam dynam = {};
    if (R2R_Chase10MovementRead(actor.hDynam, dynam) && dynam.p_stDynamics != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stDynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        result.dynamics = dynam.p_stDynamics;
    result.mind = brain.p_stMind; result.model = mind.p_stAIModel;
    result.memory = mind.p_stDsgMem; result.definition = definition; result.script = script;
    result.buffer = memory.p_cDsgMemBuffer; result.bytes = vars.ulBufferSize; result.phase = phase; result.target = static_cast<unsigned int>(target);
    if (t.waypointCount == 0 || t.waypointCount > 3 || t.firstWaypoint >= t.variables ||
        t.waypointCount > t.variables - t.firstWaypoint) return false;
    for (unsigned int i = 0; i < t.waypointCount; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Chase10MovementRead(vars.a_stDsgVarInfo + t.firstWaypoint + i, info) ||
            static_cast<unsigned int>(info.eTypeId) != 8 ||
            !SafeReadMemory(result.buffer + info.ulOffsetInDsgMem, &result.waypoints[i], 4)) return false;
    }
    AI_tdstDsgVarInfo graphInfo = {};
    if (t.graphIndex >= vars.ucNbDsgVar || !R2R_Chase10MovementRead(vars.a_stDsgVarInfo + t.graphIndex, graphInfo) ||
        static_cast<unsigned int>(graphInfo.eTypeId) != 17 ||
        !SafeReadMemory(result.buffer + graphInfo.ulOffsetInDsgMem, &result.graph, 4)) return false;
    if (result.target == R2R_CHASE10_RAY_END_TARGET)
    {
        char nativeModel[96] = {};
        // Reject normal/other networks before querying a helper's model name.
        // The main actor never reaches this exception.
        if (object == HIE_M_hGetMainActor() || !R2R_Chase10RayEndGraph(result.graph) ||
            !R2R_Chase10CopyName(R2R_Chase10NativeName(object, 1), nativeModel, sizeof(nativeModel)) ||
            _stricmp(nativeModel, "ARG_Rayseau") != 0) return false;
    }
    std::memcpy(result.personal, identity.personal, sizeof(result.personal));
    return true;
}
// Animation identity and its main/unnamed guards remain unchanged. Only path
// identity has this extra, fully typed FRG_Fin exception for generated helpers.
static bool R2R_Chase10ReadPathIdentity(HIE_tdstSuperObject* object, R2R_Chase10Identity& identity)
{
    if (R2R_Chase10ReadIdentity(object, identity))
    {
        if (identity.target != 4) return true;
    }
    else
    {
        identity = R2R_Chase10Identity(); identity.target = -1;
        if (!R2R_Chase10IdentityActor(object, identity.actor) ||
            !R2R_Chase10CopyName(R2R_Chase10NativeName(object, 0), identity.family, sizeof(identity.family)) ||
            _stricmp(identity.family, "rayman") != 0) return false;
        identity.target = 4;
        std::memcpy(identity.model, "ARG_Rayseau", sizeof("ARG_Rayseau"));
        if (!R2R_Chase10CopyName(R2R_Chase10NativeName(object, 2), identity.personal, sizeof(identity.personal)))
            std::memcpy(identity.personal, "(unnamed)", sizeof("(unnamed)"));
    }
    R2R_Chase10PathEntry verified = {};
    return R2R_Chase10PathSnapshot(object, identity, verified);
}
static bool R2R_Chase10PathSame(const R2R_Chase10PathEntry& a, const R2R_Chase10PathEntry& b)
{
    return a.owner == b.owner && a.actor == b.actor && a.dynamics == b.dynamics && a.mind == b.mind &&
        a.model == b.model && a.memory == b.memory && a.definition == b.definition &&
        a.script == b.script && a.buffer == b.buffer && a.bytes == b.bytes && a.target == b.target;
}
static bool R2R_Chase10PathWritable(const void* address, size_t length);
static bool R2R_Chase10PathSameInstance(const R2R_Chase10PathEntry& a, const R2R_Chase10PathEntry& b)
{
    return a.owner == b.owner && a.actor == b.actor && a.mind == b.mind && a.model == b.model &&
        a.definition == b.definition && a.bytes == b.bytes && a.target == b.target;
}
static bool R2R_Chase10BarrelScalar(const R2R_Chase10PathEntry& e, float*& address, float& value)
{
    if (e.target >= 4) return false;
    AI_tdstDsgMem mem = {}; AI_tdstDsgVar vars = {}; AI_tdstDsgVarInfo scalar = {};
    if (!R2R_Chase10MovementRead(e.memory, mem) || !R2R_Chase10MovementRead(e.definition, vars) ||
        mem.p_cDsgMemBuffer != e.buffer || mem.p_cDsgMemBuffer == mem.p_cDsgMemBufferInit ||
        mem.p_cDsgMemBuffer == vars.p_cDsgMemDefaultInit ||
        !R2R_Chase10MovementRead(vars.a_stDsgVarInfo + 3, scalar) || static_cast<unsigned int>(scalar.eTypeId) != 7 ||
        scalar.ulOffsetInDsgMem >= e.bytes || sizeof(float) > e.bytes - scalar.ulOffsetInDsgMem) return false;
    address = reinterpret_cast<float*>(e.buffer + scalar.ulOffsetInDsgMem);
    return SafeReadMemory(address, &value, sizeof(value)) && std::isfinite(value) && value >= 0 && value <= 1000;
}
static void R2R_Chase10BarrelSpeed(R2R_Chase10PathEntry& e)
{
    float* address = nullptr; float before = 0;
    if (!R2R_Chase10BarrelScalar(e, address, before) || !R2R_Chase10PathWritable(address, sizeof(float))) return;
    const bool modeChanged = e.speedMode != g_R2RChase10RateMode;
    if (!e.speedForced || before != e.lastSpeed) e.originalSpeed = before;
    float applied = before; const char* action = "NATIVE";
    if (g_R2RChase10RateMode == 0)
    {
        if (e.speedForced && before == e.lastSpeed) { applied = e.originalSpeed; action = "RESTORE"; }
        e.speedForced = false;
    }
    else if (e.graph != 0 && (e.waypoints[0] != 0 || e.waypoints[1] != 0) && before > 0 && e.originalSpeed <= 250)
    {
        applied = e.originalSpeed * R2R_Chase10MoveFactor();
        if (!std::isfinite(applied) || applied <= 0 || applied > 1000) return;
        e.speedForced = true; action = "APPLY";
    }
    else if (e.speedForced && before == e.lastSpeed)
    {
        applied = e.originalSpeed; e.speedForced = false; action = "RESTORE_INACTIVE";
    }
    // A native zero/new value becomes the next baseline; never reapply stale motion.
    if (applied != before) std::memcpy(address, &applied, sizeof(applied));
    if (modeChanged || applied != before)
    {
        FILE* f = nullptr; fopen_s(&f, R2R_CHASE10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RChase10PathTargets[e.target];
            fprintf(f, "[CHASE10-BARREL-SPEED] personal=%s path=%s mode=%d phase=%d action=%s original=%.9g before=%.9g applied=%.9g factor=%.3f variableIndex=3 owner=%p buffer=%p\n",
                t.personal, t.path, g_R2RChase10RateMode, e.phase, action, e.originalSpeed, before, applied,
                R2R_Chase10MoveFactor(), static_cast<void*>(e.owner), static_cast<void*>(e.buffer)); fclose(f);
        }
    }
    e.lastSpeed = applied; e.speedMode = g_R2RChase10RateMode;
}

static void R2R_Chase10PathProcess(HIE_tdstSuperObject* object)
{
    R2R_Chase10Identity identity = {}; R2R_Chase10PathEntry current = {};
    if (!R2R_Chase10ReadPathIdentity(object, identity)) return;
    const int target = R2R_Chase10PathTargetIndex(identity.target);
    if (target < 0) return;
    if (!R2R_Chase10PathSnapshot(object, identity, current))
    {
        // Keep an existing scalar baseline through a transient metadata failure;
        // hooks still revalidate and never dereference the cached layout here.
        for (auto& e : g_R2RChase10PathEntries)
            if (e.owner == object && e.actor == identity.actor && e.target == static_cast<unsigned int>(target)) e.visit = g_R2RChase10PathVisit;
        R2R_Chase10PathSkip(static_cast<unsigned int>(target), "typed buffer or script unavailable"); return;
    }
    R2R_NoMomentumObserveMotionTarget(object, R2R_Chase10RateFindTarget(identity.family, identity.model, identity.personal) < 0 ? R2R_NO_MOMENTUM_CHASE10_NETWORK : R2R_NO_MOMENTUM_NAMED);
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_CHASE10_PATH_MAX_ACTORS; ++i)
    {
        if (R2R_Chase10PathSameInstance(g_R2RChase10PathEntries[i], current)) { slot = static_cast<int>(i); break; }
        if (g_R2RChase10PathEntries[i].owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0) { R2R_Chase10PathSkip(static_cast<unsigned int>(target), "tracking table full"); return; }
    R2R_Chase10PathEntry& e = g_R2RChase10PathEntries[slot];
    if (!fresh && e.visit == g_R2RChase10PathVisit) return;
    if (fresh)
    {
        e = current; e.loggedMode = -1; e.loggedPhase = -1; e.loggedMoving = -1; e.speedMode = -1;
        FILE* f = nullptr; fopen_s(&f, R2R_CHASE10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RChase10PathTargets[e.target];
            fprintf(f, "[CHASE10-PATH-TRACK] family=%s model=%s personal=%s path=%s "
                "phase=%d bytes=%lu owner=%p dynamics=%p buffer=%p\n",
                t.family, t.model, e.personal, t.path, e.phase, e.bytes,
                static_cast<void*>(object), static_cast<void*>(e.dynamics), static_cast<void*>(e.buffer)); fclose(f);
        }
    }
    e.phase = current.phase; e.dynamics = current.dynamics; e.script = current.script; e.graph = current.graph;
    e.memory = current.memory; e.buffer = current.buffer;
    std::memcpy(e.waypoints, current.waypoints, sizeof(e.waypoints)); e.visit = g_R2RChase10PathVisit;
    if (e.target < 4) R2R_Chase10BarrelSpeed(e);
}
static void R2R_Chase10PathScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_Chase10PathProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (object != nullptr) R2R_Chase10PathScan(object, depth + 1);
    }
}
// The end script has a native reference capture; Chase_10 runtime paths are
// captured only for five exact objects and the fully validated FRG_Fin helper
// in small, delayed batches so a non-mechanical trajectory can be diagnosed
// without large startup captures. Raw references stay opaque.
struct R2R_Chase10PathCapture
{
    AI_tdstAIModel* model;
    AI_tdstScriptAI* script;
    unsigned int comport;
    unsigned int rule;
    unsigned int node;
    unsigned int total;
    bool started;
    bool complete;
};
static R2R_Chase10PathCapture g_R2RChase10PathCaptures[R2R_CHASE10_PATH_TARGET_COUNT] = {};
static void R2R_Chase10PathCaptureStep(const R2R_Chase10PathEntry& e)
{
    if (e.target >= R2R_CHASE10_PATH_TARGET_COUNT || g_R2RChase10PathFrame < 120 || g_R2RChase10PathCaptures[e.target].complete) return;
    const auto& t = g_R2RChase10PathTargets[e.target];
    R2R_Chase10Identity identity = {}; R2R_Chase10PathEntry current = {};
    AI_tdstScriptAI script = {}; AI_tdstDsgVar vars = {};
    if (!R2R_Chase10ReadPathIdentity(e.owner, identity) || !R2R_Chase10PathSnapshot(e.owner, identity, current) ||
        !R2R_Chase10PathSame(e, current) || !R2R_Chase10MovementRead(e.script, script) ||
        !R2R_Chase10MovementRead(e.definition, vars)) return;
    if (script.ulNbComport == 0 || script.ulNbComport > 64 || script.a_stComport == nullptr) return;
    auto& capture = g_R2RChase10PathCaptures[e.target];
    if (capture.started && (capture.model != e.model || capture.script != e.script)) return;
    FILE* f = nullptr; fopen_s(&f, R2R_CHASE10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    if (!capture.started)
    {
        capture.model = e.model; capture.script = e.script; capture.started = true;
        fprintf(f, "[CHASE10-PATH-AI-CAPTURE] target=%u family=%s model=%s personal=%s path=%s comports=%lu "
            "variables=%u bytes=%lu budgetPerFrame=64 totalBudget=8192 modelPtr=%p script=%p\n",
            e.target, t.family, t.model, e.personal, t.path, script.ulNbComport, static_cast<unsigned int>(vars.ucNbDsgVar), vars.ulBufferSize,
            static_cast<void*>(e.model), static_cast<void*>(e.script));
        for (unsigned int i = 0; i < vars.ucNbDsgVar; ++i)
        {
            AI_tdstDsgVarInfo info = {}; uint32_t raw = 0;
            if (!R2R_Chase10MovementRead(vars.a_stDsgVarInfo + i, info)) break;
            const unsigned int type = static_cast<unsigned int>(info.eTypeId);
            const unsigned int width = R2R_Chase10PathWidth(type);
            if (!SafeReadMemory(e.buffer + info.ulOffsetInDsgMem, &raw, width == 1 ? 1 : 4)) break;
            fprintf(f, "[CHASE10-PATH-DSG] target=%u var=%u type=%u offset=%lu raw=0x%08X", e.target, i, type, info.ulOffsetInDsgMem, raw);
            if (type == 7) { float value = 0; std::memcpy(&value, &raw, 4); fprintf(f, " float=%.9g", value); }
            fprintf(f, "\n");
        }
    }
    unsigned int budget = 64;
    while (budget && capture.comport < script.ulNbComport && capture.total < 8192)
    {
        AI_tdstComport comport = {};
        if (!R2R_Chase10MovementRead(script.a_stComport + capture.comport, comport) || comport.ucNbRules > 64)
        {
            fprintf(f, "[CHASE10-PATH-AI-UNAVAILABLE] target=%u comport=%u\n", e.target, capture.comport); ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        const bool schedule = capture.rule == comport.ucNbRules;
        if (capture.rule > comport.ucNbRules || (schedule && comport.p_stSchedule == nullptr))
        {
            ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        AI_tdstTreeInterpret* tree = schedule ? comport.p_stSchedule : comport.a_stRules == nullptr ?
            nullptr : comport.a_stRules + capture.rule;
        AI_tdstTreeInterpret rule = {}; AI_tdstNodeInterpret node = {};
        if (capture.node >= 512 || !R2R_Chase10MovementRead(tree, rule) || rule.p_stNodeInterpret == nullptr ||
            !R2R_Chase10MovementRead(rule.p_stNodeInterpret + capture.node, node))
        {
            fprintf(f, "[CHASE10-PATH-AI-UNAVAILABLE] target=%u comport=%u rule=%u schedule=%u node=%u\n",
                e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node); ++capture.rule; capture.node = 0; --budget; continue;
        }
        fprintf(f, "[CHASE10-PATH-AI-NODE] target=%u comport=%u rule=%u schedule=%u node=%u type=%u depth=%u "
            "skip=%u raw=0x%08X\n", e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node,
            static_cast<unsigned int>(node.eType), static_cast<unsigned int>(node.ucDepth),
            static_cast<unsigned int>(node.uwNodeToSkip), static_cast<unsigned int>(reinterpret_cast<uintptr_t>(node.uParam.pvValue)));
        ++capture.node; ++capture.total; --budget;
        if (static_cast<unsigned int>(node.eType) == 8) { ++capture.rule; capture.node = 0; }
    }
    if (capture.comport >= script.ulNbComport || capture.total >= 8192)
    {
        fprintf(f, "[CHASE10-PATH-AI-CAPTURE-END] target=%u nodes=%u complete=%s\n", e.target, capture.total,
            capture.comport >= script.ulNbComport ? "YES" : "BUDGET_LIMIT"); capture.complete = true;
    }
    fclose(f);
}
static void R2R_Chase10PathForgetWorld()
{
    std::memset(g_R2RChase10PathEntries, 0, sizeof(g_R2RChase10PathEntries));
    std::memset(g_R2RChase10PathCaptures, 0, sizeof(g_R2RChase10PathCaptures));
    std::memset(g_R2RChase10PathSkipLogged, 0, sizeof(g_R2RChase10PathSkipLogged));
    g_R2RChase10PathFrame = 0;g_R2RChase10PathCaptureCursor = 0;
}
static void R2R_Chase10PathControlTick()
{
    if (!R2R_Chase10MovePlaying()) { R2R_Chase10PathForgetWorld(); return; }
    R2R_Chase10MoveStartReport(); ++g_R2RChase10PathVisit; ++g_R2RChase10PathFrame;
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    R2R_Chase10PathScan(active, 0); if (inactive != active)R2R_Chase10PathScan(inactive, 0);
    for (auto& e : g_R2RChase10PathEntries)
        if (e.visit != g_R2RChase10PathVisit)e = R2R_Chase10PathEntry();
    // Only one capture step in the entire tick: six targets share 64 nodes/frame.
    for (unsigned int attempt = 0;attempt < R2R_CHASE10_PATH_TARGET_COUNT;++attempt)
    {
        const unsigned int target = (g_R2RChase10PathCaptureCursor + attempt) % R2R_CHASE10_PATH_TARGET_COUNT;
        const auto& capture = g_R2RChase10PathCaptures[target];
        if (capture.complete)continue;
        for (const auto& e : g_R2RChase10PathEntries)
        {
            if (e.owner == nullptr || e.target != target || (capture.started &&
                (e.model != capture.model || e.script != capture.script)))continue;
            R2R_Chase10PathCaptureStep(e);g_R2RChase10PathCaptureCursor = (target + 1) % R2R_CHASE10_PATH_TARGET_COUNT;return;
        }
    }
}

static bool R2R_Chase10PathWritable(const void* address, size_t length)
{
    if (address == nullptr || length == 0) return false;
    MEMORY_BASIC_INFORMATION info = {};
    if (VirtualQuery(address, &info, sizeof(info)) == 0 || info.State != MEM_COMMIT ||
        (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const DWORD p = info.Protect & 0xff;
    if (p != PAGE_READWRITE && p != PAGE_WRITECOPY &&
        p != PAGE_EXECUTE_READWRITE && p != PAGE_EXECUTE_WRITECOPY) return false;
    const uintptr_t start = reinterpret_cast<uintptr_t>(address);
    const uintptr_t base = reinterpret_cast<uintptr_t>(info.BaseAddress);
    return start >= base && start - base < info.RegionSize &&
        length <= info.RegionSize - (start - base) && R2R_AddressReadable(start, length);
}
static R2R_Chase10PathEntry* R2R_Chase10PathLiveMechanics(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, R2R_Chase10PathEntry& current)
{
    if (!R2R_Chase10MovePlaying() || object == nullptr || object == HIE_M_hGetMainActor() ||
        dynamics == nullptr) return nullptr;
    for (auto& e : g_R2RChase10PathEntries)
    {
        if (e.owner != object || e.dynamics != dynamics || e.visit != g_R2RChase10PathVisit) continue;
        R2R_Chase10Identity identity = {};
        if (!R2R_Chase10ReadPathIdentity(object, identity) ||
            !R2R_Chase10PathSnapshot(object, identity, current) || !R2R_Chase10PathSame(e, current)) return nullptr;
        return &e;
    }
    return nullptr;
}
static bool R2R_Chase10PathBeginMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    MTH_tdxReal dt, MTH3D_tdstVector& original, MTH3D_tdstVector& applied)
{
    R2R_Chase10PathEntry current = {}; MTH3D_tdstVector before = {};
    R2R_Chase10PathEntry* e = R2R_Chase10PathLiveMechanics(object, dynamics, current);
    if (e == nullptr || current.target != 4 || !R2R_Chase10MovementRead(&dynamics->stDynamicsBase.stImposeSpeed, before)) return false;
    const bool validVector = std::isfinite(before.x) && std::isfinite(before.y) && std::isfinite(before.z) &&
        std::fabs(before.x) <= 1000 && std::fabs(before.y) <= 1000 && std::fabs(before.z) <= 1000;
    const bool moving = validVector && std::fabs(before.x) + std::fabs(before.y) + std::fabs(before.z) > .00001f;
    const bool pathReady = current.graph != 0 && current.waypoints[0] != 0;
    const bool validDT = std::isfinite(dt) && dt > 0 && dt <= .25f;
    const float factor = R2R_Chase10MoveFactor();
    bool modified = false;
    original = before; applied = before;
    if (pathReady && moving && validDT && factor != 1 &&
        R2R_Chase10PathWritable(&dynamics->stDynamicsBase.stImposeSpeed, sizeof(applied)))
    {
        applied = { before.x * factor, before.y * factor, before.z * factor };
        std::memcpy(&dynamics->stDynamicsBase.stImposeSpeed, &applied, sizeof(applied));
        modified = true; ++e->scaledHits;
    }
    ++e->hookHits;
    if (e->loggedMode != g_R2RChase10RateMode) e->hookLogs = 0;
    // Short samples show native stops and missing path references as well as writes.
    const int status = !validVector || !validDT ? -2 : !pathReady ? 0 : !moving ? 1 : modified ? 3 : 2;
    if (e->hookLogs < 24 && (e->hookLogs == 0 || e->loggedMode != g_R2RChase10RateMode ||
        e->loggedPhase != current.phase || e->loggedMoving != status || (modified && e->hookLogs < 8)))
    {
        FILE* f = nullptr; fopen_s(&f, R2R_CHASE10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RChase10PathTargets[current.target];
            fprintf(f, "[CHASE10-PATH-SPEED] family=%s model=%s personal=%s path=%s "
                "mode=%d phase=%d pathReady=%s moving=%s validVector=%s validDT=%s modified=%s "
                "requestedFactor=%.3f appliedFactor=%.3f inputDT=%.9g appliedDT=%.9g "
                "before=(%.6f %.6f %.6f) applied=(%.6f %.6f %.6f) "
                "waypoints=(0x%08X 0x%08X 0x%08X) owner=%p hookHits=%u scaledHits=%u\n",
                t.family, t.model, t.personal, t.path, g_R2RChase10RateMode, current.phase, pathReady ? "YES" : "NO", moving ? "YES" : "NO",
                validVector ? "YES" : "NO", validDT ? "YES" : "NO", modified ? "YES" : "NO",
                factor, modified ? factor : 1.0f, static_cast<double>(dt), static_cast<double>(dt),
                before.x, before.y, before.z, applied.x, applied.y, applied.z,
                current.waypoints[0], current.waypoints[1], current.waypoints[2], static_cast<void*>(object), e->hookHits, e->scaledHits);
            fclose(f); ++e->hookLogs;
        }
    }
    e->loggedMode = g_R2RChase10RateMode; e->loggedPhase = current.phase; e->loggedMoving = status;
    return modified;
}
static void R2R_Chase10PathEndMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    const MTH3D_tdstVector& original, const MTH3D_tdstVector& applied)
{
    R2R_Chase10PathEntry current = {}; MTH3D_tdstVector after = {};
    if (R2R_Chase10PathLiveMechanics(object, dynamics, current) == nullptr ||
        !R2R_Chase10MovementRead(&dynamics->stDynamicsBase.stImposeSpeed, after) ||
        after.x != applied.x || after.y != applied.y || after.z != applied.z ||
        !R2R_Chase10PathWritable(&dynamics->stDynamicsBase.stImposeSpeed, sizeof(original))) return;
    // Restore only our own temporary command, preserving native stops/new commands.
    std::memcpy(&dynamics->stDynamicsBase.stImposeSpeed, &original, sizeof(original));
}

// The prior Chase_10 barrel inertia override was added automatically.
// Native momentum is now the default; speed controls and captures stay active.
static bool R2R_Chase10BarrelBeginMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    unsigned long& originalInertiaBit)
{
    (void)object; (void)dynamics; originalInertiaBit = 0;
    return false;
}
static void R2R_Chase10BarrelEndMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    unsigned long originalInertiaBit)
{
    (void)object; (void)dynamics; (void)originalInertiaBit;
}

// ARG_Rayseau uses animation-driven travel, SetMechanicSpeedVector for jumps
// and swimming, and ProposeSpeedXYZ for another network mode. Scale only this
// call's mechanics time so all native motion routes keep their own vectors.
// Procedure meanings: byvar/raymap, AITypes_R2.cs; native script has 14 comports.
static MTH_tdxReal R2R_Chase10RayEndMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    R2R_Chase10PathEntry current = {};
    auto* e = R2R_Chase10PathLiveMechanics(object, dynamics, current);
    if (e == nullptr || current.target != R2R_CHASE10_RAY_END_TARGET) return dt;
    const bool travel = current.phase == 3 || current.phase == 4 || current.phase == 5 ||
        current.phase == 6 || current.phase == 9 || current.phase == 10 ||
        current.phase == 11 || current.phase == 12;
    const bool validDT = std::isfinite(dt) && dt > 0 && dt <= .25f;
    DNM_tdstDynamicsBaseBlock base = {};
    if (!R2R_Chase10MovementRead(&dynamics->stDynamicsBase, base)) return dt;
    float speed = 0; bool finiteMotion = true;
    const MTH3D_tdstVector commands[3] = { base.stImposeSpeed,base.stProposeSpeed,base.stPreviousSpeed };
    for (const auto& command : commands)
    {
        if (!std::isfinite(command.x) || !std::isfinite(command.y) || !std::isfinite(command.z) ||
            std::fabs(command.x) > 1000 || std::fabs(command.y) > 1000 || std::fabs(command.z) > 1000)
        {
            finiteMotion = false; break;
        }
        const float length = std::sqrt(command.x * command.x + command.y * command.y + command.z * command.z);
        if (!std::isfinite(length)) { finiteMotion = false; break; }
        if (length > speed) speed = length;
    }
    const bool moving = finiteMotion && speed > .00001f;
    WP_tdstWayPoint waypoint = {};
    // WayPoint_3 is the current destination in the captured native script.
    const bool waypointReady = current.waypoints[1] != 0 && R2R_Chase10MovementRead(
        reinterpret_cast<const WP_tdstWayPoint*>(static_cast<uintptr_t>(current.waypoints[1])), waypoint) &&
        std::isfinite(waypoint.m_xRadius) && waypoint.m_xRadius > 0 && waypoint.m_xRadius <= 1000;
    const float factor = R2R_Chase10MoveFactor();
    MTH_tdxReal applied = dt; bool capped = false;
    if (travel && validDT && moving && waypointReady && factor != 1)
    {
        applied = dt * factor;
        // Keep consecutive steps below the diameter of the native waypoint
        // collision sphere with 10% margin. Never shrink an already-native
        // fast-mode step; if that native step is too large, leave it native.
        if (factor > 1)
        {
            const float limit = 1.8f * waypoint.m_xRadius / speed;
            if (applied > limit) { applied = limit > dt ? limit : dt; capped = true; }
        }
        if (!std::isfinite(applied) || applied <= 0 || applied > 1) applied = dt;
    }
    ++e->hookHits; if (applied != dt) ++e->scaledHits;
    if (e->loggedMode != g_R2RChase10RateMode) e->hookLogs = 0;
    const int status = !validDT || !finiteMotion ? -2 : !travel || !waypointReady ? 0 :
        !moving ? 1 : applied != dt ? (capped ? 4 : 3) : 2;
    if (e->hookLogs < 24 && (e->hookLogs == 0 || e->loggedMode != g_R2RChase10RateMode ||
        e->loggedPhase != current.phase || e->loggedMoving != status || (applied != dt && e->hookLogs < 8)))
    {
        FILE* f = nullptr; fopen_s(&f, R2R_CHASE10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            fprintf(f, "[CHASE10-RAYMAN-FIN-SPEED] personal=%s path=FRG_Fin mode=%d phase=%d "
                "travel=%s pathReady=%s moving=%s finiteMotion=%s validDT=%s modified=%s "
                "requestedFactor=%.3f appliedFactor=%.6f inputDT=%.9g appliedDT=%.9g "
                "speedBound=%.6f waypointRadius=%.6f stepCapped=%s graph=0x%08X "
                "destination=0x%08X owner=%p hookHits=%u scaledHits=%u\n",
                e->personal, g_R2RChase10RateMode, current.phase, travel ? "YES" : "NO", waypointReady ? "YES" : "NO",
                moving ? "YES" : "NO", finiteMotion ? "YES" : "NO", validDT ? "YES" : "NO", applied != dt ? "YES" : "NO",
                factor, validDT ? static_cast<double>(applied / dt) : 1.0,
                static_cast<double>(dt), static_cast<double>(applied), speed, waypointReady ? waypoint.m_xRadius : 0.0f,
                capped ? "YES" : "NO", current.graph, current.waypoints[1], static_cast<void*>(object), e->hookHits, e->scaledHits);
            fclose(f); ++e->hookLogs;
        }
    }
    e->loggedMode = g_R2RChase10RateMode; e->loggedPhase = current.phase; e->loggedMoving = status;
    return applied;
}

// v0.0.19n.3: Chase_22 exact networks; intro Rayseau + exit Ptizetre progression-locked native.
static const char* R2R_CHASE22_MOVEMENT_REPORT = "Rayman2Randomizer_Chase22Movement.txt";
static bool g_R2RChase22MovementReportStarted = false;
template<class T> static bool R2R_Chase22MovementRead(const T* source, T& destination)
{
    return source != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(source), sizeof(T)) &&
        SafeReadMemory(source, &destination, sizeof(T));
}
static bool R2R_Chase22MovePlaying()
{
    return GAM_g_stEngineStructure != nullptr &&
        GAM_g_stEngineStructure->eEngineMode == E_EM_ModePlaying &&
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Chase_22") == 0 &&
        GAM_g_p_stDynamicWorld != nullptr && *GAM_g_p_stDynamicWorld != nullptr;
}
static float R2R_Chase22MoveFactor()
{
    return R2R_StatsLegacyFactorForLevel(g_R2RChase22RateMode, "Chase_22", 0x10Du);
}
static bool R2R_Chase22MoveStartReport()
{
    if (g_R2RChase22MovementReportStarted) return true;
    FILE* f = nullptr; fopen_s(&f, R2R_CHASE22_MOVEMENT_REPORT, "w");
    if (f == nullptr) return false;
    fprintf(f, "%s CHASE_22 RAYMAN, PIRANHA AND DONKEY NETWORKS TEST\n"
        "Opening ALW_Rayseau1: fully native and not enrolled in Chase22Path.\n"
        "Main actor excluded before all metadata getters; unrelated Rayman networks remain native.\n"
        "Piranha: exact FRG_PiranhaSauteurVisible_1, WayPoints_7/8, 14 fields/12 comports, flight 3/4/5.\n"
        "Eight ARG_Gen_Tono_Roule generators are captured, not treated as moving barrels.\n"
        "Generated tonneau_boum / ARG_Tonneau_DonkeyKong must match a supplied FRG_Donkey graph.\n"
        "Barrel schema: 13 typed fields; only live mechanics time varies, no guessed Float speed role.\n"
        "ALW_Rayseau1 and FRG_Ptizetre_Fin: fully native; not enrolled in path/no-momentum control.\n"
        "Fast steps capped by live waypoint radius; DSG, commands, jump vectors and flags remain native.\n"
        "Five model captures share <=64 nodes/frame after 120 ticks, <=8192 nodes/model.\n"
        "F6 MIN, F7 MAX, F8 full-range RANDOM, F12 native. Movement hook=%s.\n", VERSION,
        g_R2RMovementHookInstalled ? "YES" : "NO");
    fclose(f); g_R2RChase22MovementReportStarted = true; return true;
}
static int R2R_Chase22MovementPhase(const AI_tdstMind& mind, unsigned long expectedCount)
{
    AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr; AI_tdstScriptAI s = {};
    if (!R2R_Chase22MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Chase22MovementRead(intel.pp_stScriptAI, script) ||
        !R2R_Chase22MovementRead(script, s) || s.a_stComport == nullptr ||
        s.ulNbComport == 0 || s.ulNbComport > 64 ||
        (expectedCount != 0 && s.ulNbComport != expectedCount)) return -1;
    const uintptr_t first = reinterpret_cast<uintptr_t>(s.a_stComport);
    const uintptr_t current = reinterpret_cast<uintptr_t>(intel.p_stCurrentComport);
    const size_t span = sizeof(AI_tdstComport) * s.ulNbComport;
    if (current < first || current - first >= span || (current - first) % sizeof(AI_tdstComport) != 0 ||
        !R2R_AddressReadable(current, sizeof(AI_tdstComport))) return -1;
    return static_cast<int>((current - first) / sizeof(AI_tdstComport));
}

