static int R2R_Chase22PathTargetIndex(int rateTarget)
{
    for (unsigned int i = 0; i < R2R_CHASE22_PATH_TARGET_COUNT; ++i)
        if (rateTarget >= 0 && static_cast<unsigned int>(rateTarget) == g_R2RChase22PathTargets[i].rateTarget)
            return static_cast<int>(i);
    return -1;
}
struct R2R_Chase22PathEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    DNM_tdstDynamics* dynamics;
    AI_tdstMind* mind;
    AI_tdstAIModel* model;
    AI_tdstDsgMem* memory;
    AI_tdstDsgVar* definition;
    AI_tdstScriptAI* script;
    char* buffer;
    unsigned long bytes;
    unsigned int target;
    int phase;
    uint32_t waypoints[3], graph;
    unsigned int visit;
    int loggedMode, loggedPhase, loggedMoving;
    unsigned int hookLogs, hookHits, scaledHits;
    char personal[96];
};
static R2R_Chase22PathEntry g_R2RChase22PathEntries[R2R_CHASE22_PATH_MAX_ACTORS] = {};
static unsigned int g_R2RChase22PathVisit = 0, g_R2RChase22PathFrame = 0;
static bool g_R2RChase22PathSkipLogged[R2R_CHASE22_PATH_TARGET_COUNT] = {};
static unsigned int g_R2RChase22PathCaptureCursor = 0;
static unsigned int R2R_Chase22PathWidth(unsigned int type)
{
    return type == 0 || type == 1 || type == 2 ? 1 : type == 11 ? 12 : type == 10 ? 16 : 4;
}
static void R2R_Chase22PathSkip(unsigned int target, const char* reason)
{
    if (target >= R2R_CHASE22_PATH_TARGET_COUNT || g_R2RChase22PathSkipLogged[target] || !R2R_Chase22MoveStartReport()) return;
    const auto& t = g_R2RChase22PathTargets[target];
    FILE* f = nullptr; fopen_s(&f, R2R_CHASE22_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[CHASE22-PATH-SKIP] family=%s model=%s personal=%s path=%s reason=%s\n",
        t.family, t.model, t.personal, t.path, reason);
    fclose(f); g_R2RChase22PathSkipLogged[target] = true;
}
static bool R2R_Chase22PathLayout(unsigned int target, const AI_tdstMind& mind, AI_tdstDsgMem& memory,
    AI_tdstDsgVar*& definition, AI_tdstDsgVar& vars)
{
    if (target >= R2R_CHASE22_PATH_TARGET_COUNT) return false;
    const auto& t = g_R2RChase22PathTargets[target];
    AI_tdstAIModel model = {};
    if (!R2R_Chase22MovementRead(mind.p_stAIModel, model) ||
        !R2R_Chase22MovementRead(mind.p_stDsgMem, memory) ||
        !R2R_Chase22MovementRead(memory.pp_stDsgVar, definition) ||
        definition == nullptr || definition != model.p_stDsgVar ||
        !R2R_Chase22MovementRead(definition, vars) || vars.ucNbDsgVar != t.variables ||
        vars.a_stDsgVarInfo == nullptr || vars.ulBufferSize < t.minimumBytes || vars.ulBufferSize > 256 ||
        memory.p_cDsgMemBuffer == nullptr) return false;
    // Native offsets are validated, never inferred from screenshot row order.
    // Read-only DSG permits init/default aliases; this module never writes DSG.
    bool occupied[256] = {};
    for (unsigned int i = 0; i < t.variables; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Chase22MovementRead(vars.a_stDsgVarInfo + i, info)) return false;
        const unsigned int type = static_cast<unsigned int>(info.eTypeId);
        if (type != t.types[i] && !(t.types[i] == 5 && type == 6)) return false;
        const unsigned int width = R2R_Chase22PathWidth(type);
        if (info.ulOffsetInDsgMem >= vars.ulBufferSize || width > vars.ulBufferSize - info.ulOffsetInDsgMem) return false;
        for (unsigned long j = info.ulOffsetInDsgMem; j < info.ulOffsetInDsgMem + width; ++j)
        {
            if (occupied[j]) return false; occupied[j] = true;
        }
    }
    return R2R_AddressReadable(reinterpret_cast<uintptr_t>(memory.p_cDsgMemBuffer), vars.ulBufferSize);
}
static bool R2R_Chase22GraphName(uint32_t reference, char* name, size_t capacity)
{
    WP_tdstGraph graph = {};
    return reference != 0 && R2R_Chase22MovementRead(
        reinterpret_cast<const WP_tdstGraph*>(static_cast<uintptr_t>(reference)), graph) &&
        R2R_Chase22CopyName(graph.m_szNameOfGraph, name, capacity);
}
static bool R2R_Chase22PathSnapshot(HIE_tdstSuperObject* object,
    const R2R_Chase22Identity& identity, R2R_Chase22PathEntry& result)
{
    int target = R2R_Chase22PathTargetIndex(identity.target);
    if (target < 0 || object == HIE_M_hGetMainActor()) return false;
    const auto& t = g_R2RChase22PathTargets[target];
    HIE_tdstEngineObject actor = {}; AI_tdstBrain brain = {}; AI_tdstMind mind = {};
    AI_tdstDsgMem memory = {}; AI_tdstDsgVar* definition = nullptr;
    AI_tdstDsgVar vars = {}; AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr;
    AI_tdstScriptAI scripts = {};
    if (!R2R_Chase22MovementRead(identity.actor, actor) ||
        !R2R_Chase22MovementRead(actor.hBrain, brain) || !R2R_Chase22MovementRead(brain.p_stMind, mind) ||
        !R2R_Chase22PathLayout(static_cast<unsigned int>(target), mind, memory, definition, vars) ||
        !R2R_Chase22MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Chase22MovementRead(intel.pp_stScriptAI, script) || !R2R_Chase22MovementRead(script, scripts)) return false;
    const int phase = R2R_Chase22MovementPhase(mind, t.comports);
    if (phase < 0) return false;
    result = R2R_Chase22PathEntry(); result.owner = object; result.actor = identity.actor;
    DNM_tdstDynam dynam = {};
    if (R2R_Chase22MovementRead(actor.hDynam, dynam) && dynam.p_stDynamics != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stDynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        result.dynamics = dynam.p_stDynamics;
    result.mind = brain.p_stMind; result.model = mind.p_stAIModel;
    result.memory = mind.p_stDsgMem; result.definition = definition; result.script = script;
    result.buffer = memory.p_cDsgMemBuffer; result.bytes = vars.ulBufferSize; result.phase = phase;
    if (t.waypointCount > 3 || (t.waypointCount &&
        (t.firstWaypoint >= t.variables || t.waypointCount > t.variables - t.firstWaypoint))) return false;
    for (unsigned int i = 0; i < t.waypointCount; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Chase22MovementRead(vars.a_stDsgVarInfo + t.firstWaypoint + i, info) ||
            static_cast<unsigned int>(info.eTypeId) != 8 ||
            !SafeReadMemory(result.buffer + info.ulOffsetInDsgMem, &result.waypoints[i], 4)) return false;
    }
    if (t.graphIndex != R2R_CHASE22_NO_GRAPH)
    {
        AI_tdstDsgVarInfo info = {}; char graphName[96] = {};
        if (t.graphIndex >= t.variables || !R2R_Chase22MovementRead(vars.a_stDsgVarInfo + t.graphIndex, info) ||
            static_cast<unsigned int>(info.eTypeId) != 17 ||
            !SafeReadMemory(result.buffer + info.ulOffsetInDsgMem, &result.graph, 4) ||
            !R2R_Chase22GraphName(result.graph, graphName, sizeof(graphName))) return false;
        if (t.kind == R2R_CHASE22_ROLLING)
        {
            target = -1;
            for (unsigned int i = 0; i < R2R_CHASE22_PATH_TARGET_COUNT; ++i)
                if (g_R2RChase22PathTargets[i].kind == R2R_CHASE22_ROLLING &&
                    _stricmp(graphName, g_R2RChase22PathTargets[i].path) == 0) {
                    target = static_cast<int>(i); break;
                }
            if (target < 0) return false;
        }
        else if (_stricmp(graphName, t.path) != 0) return false;
    }
    if (t.kind == R2R_CHASE22_RAY || t.kind == R2R_CHASE22_ROLLING)
    {
        char nativeModel[96] = {};
        // The full layout and exact graph guard precede the model getter for
        // unnamed generated helpers. Main actor never reaches this exception.
        if (!R2R_Chase22CopyName(R2R_Chase22NativeName(object, 1), nativeModel, sizeof(nativeModel)) ||
            _stricmp(nativeModel, t.model) != 0) return false;
    }
    result.target = static_cast<unsigned int>(target);
    std::memcpy(result.personal, identity.personal, sizeof(result.personal)); return true;
}
// Allow generated path owners only after full typed layout and exact graph validation.
static bool R2R_Chase22ReadPathIdentity(HIE_tdstSuperObject* object, R2R_Chase22Identity& identity)
{
    if (R2R_Chase22ReadIdentity(object, identity))
        return R2R_Chase22PathTargetIndex(identity.target) >= 0;
    identity = R2R_Chase22Identity(); identity.target = -1;
    if (!R2R_Chase22IdentityActor(object, identity.actor) ||
        !R2R_Chase22CopyName(R2R_Chase22NativeName(object, 0), identity.family, sizeof(identity.family))) return false;
    if (_stricmp(identity.family, "rayman") == 0)
    {
        identity.target = 0; std::memcpy(identity.model, "ARG_Rayseau", sizeof("ARG_Rayseau"));
    }
    else if (_stricmp(identity.family, "tonneau_boum") == 0)
    {
        identity.target = 1; std::memcpy(identity.model, "ARG_Tonneau_DonkeyKong", sizeof("ARG_Tonneau_DonkeyKong"));
    }
    else return false;
    if (!R2R_Chase22CopyName(R2R_Chase22NativeName(object, 2), identity.personal, sizeof(identity.personal)))
        std::memcpy(identity.personal, "(unnamed)", sizeof("(unnamed)"));
    R2R_Chase22PathEntry verified = {};
    return R2R_Chase22PathSnapshot(object, identity, verified);
}
static bool R2R_Chase22RollingAnimationIdentity(HIE_tdstSuperObject* object, R2R_Chase22Identity& identity)
{
    R2R_Chase22PathEntry verified = {};
    if (_stricmp(identity.family, "tonneau_boum") != 0 ||
        _stricmp(identity.model, "ARG_Tonneau_DonkeyKong") != 0) return false;
    identity.target = 1;
    return R2R_Chase22PathSnapshot(object, identity, verified) &&
        verified.waypoints[0] != 0 && verified.waypoints[1] != 0;
}
static bool R2R_Chase22PathSame(const R2R_Chase22PathEntry& a, const R2R_Chase22PathEntry& b)
{
    return a.owner == b.owner && a.actor == b.actor && a.dynamics == b.dynamics && a.mind == b.mind &&
        a.model == b.model && a.memory == b.memory && a.definition == b.definition &&
        a.script == b.script && a.buffer == b.buffer && a.bytes == b.bytes && a.target == b.target;
}
static void R2R_Chase22PathProcess(HIE_tdstSuperObject* object)
{
    R2R_Chase22Identity identity = {}; R2R_Chase22PathEntry current = {};
    if (!R2R_Chase22ReadPathIdentity(object, identity)) return;
    if (!R2R_Chase22PathSnapshot(object, identity, current))
    {
        const int target = R2R_Chase22PathTargetIndex(identity.target);
        if (target >= 0) R2R_Chase22PathSkip(static_cast<unsigned int>(target), "exact graph, typed buffer or script unavailable");
        return;
    }
    R2R_NoMomentumObserveMotionTarget(object, R2R_Chase22RateFindTarget(identity.family, identity.model, identity.personal) < 0 ? R2R_NO_MOMENTUM_CHASE22_NETWORK : R2R_NO_MOMENTUM_NAMED);
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_CHASE22_PATH_MAX_ACTORS; ++i)
    {
        if (R2R_Chase22PathSame(g_R2RChase22PathEntries[i], current)) { slot = static_cast<int>(i); break; }
        if (g_R2RChase22PathEntries[i].owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0) { R2R_Chase22PathSkip(current.target, "tracking table full"); return; }
    auto& e = g_R2RChase22PathEntries[slot];
    if (!fresh && e.visit == g_R2RChase22PathVisit) return;
    if (fresh)
    {
        e = current; e.loggedMode = -1; e.loggedPhase = -1; e.loggedMoving = -1;
        FILE* f = nullptr; fopen_s(&f, R2R_CHASE22_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RChase22PathTargets[e.target];
            fprintf(f, "[CHASE22-PATH-TRACK] target=%u kind=%u family=%s model=%s personal=%s path=%s "
                "phase=%d bytes=%lu owner=%p dynamics=%p buffer=%p\n", e.target, static_cast<unsigned int>(t.kind),
                t.family, t.model, e.personal, t.path, e.phase, e.bytes, static_cast<void*>(object),
                static_cast<void*>(e.dynamics), static_cast<void*>(e.buffer)); fclose(f);
        }
    }
    e.phase = current.phase; e.graph = current.graph;
    std::memcpy(e.waypoints, current.waypoints, sizeof(e.waypoints)); e.visit = g_R2RChase22PathVisit;
}
static void R2R_Chase22PathScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    R2R_Chase22PathProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object) { if (object != nullptr) R2R_Chase22PathScan(object, depth + 1); }
}

struct R2R_Chase22PathCapture
{
    AI_tdstAIModel* model;
    AI_tdstScriptAI* script;
    unsigned int comport;
    unsigned int rule;
    unsigned int node;
    unsigned int total;
    bool started;
    bool complete;
};
static R2R_Chase22PathCapture g_R2RChase22PathCaptures[R2R_CHASE22_CAPTURE_COUNT] = {};
static void R2R_Chase22PathCaptureStep(const R2R_Chase22PathEntry& e)
{
    if (e.target >= R2R_CHASE22_PATH_TARGET_COUNT || g_R2RChase22PathFrame < 120) return;
    const auto& t = g_R2RChase22PathTargets[e.target];
    const unsigned int group = static_cast<unsigned int>(t.kind);
    if (group >= R2R_CHASE22_CAPTURE_COUNT || g_R2RChase22PathCaptures[group].complete) return;
    R2R_Chase22Identity identity = {}; R2R_Chase22PathEntry current = {};
    AI_tdstScriptAI script = {}; AI_tdstDsgVar vars = {};
    if (!R2R_Chase22ReadPathIdentity(e.owner, identity) || !R2R_Chase22PathSnapshot(e.owner, identity, current) ||
        !R2R_Chase22PathSame(e, current) || !R2R_Chase22MovementRead(e.script, script) ||
        !R2R_Chase22MovementRead(e.definition, vars)) return;
    if (script.ulNbComport == 0 || script.ulNbComport > 64 || script.a_stComport == nullptr) return;
    auto& capture = g_R2RChase22PathCaptures[group];
    if (capture.started && (capture.model != e.model || capture.script != e.script)) return;
    FILE* f = nullptr; fopen_s(&f, R2R_CHASE22_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    if (!capture.started)
    {
        capture.model = e.model; capture.script = e.script; capture.started = true;
        fprintf(f, "[CHASE22-PATH-AI-CAPTURE] target=%u family=%s model=%s personal=%s path=%s comports=%lu "
            "variables=%u bytes=%lu budgetPerFrame=64 totalBudget=8192 modelPtr=%p script=%p\n",
            e.target, t.family, t.model, e.personal, t.path, script.ulNbComport, static_cast<unsigned int>(vars.ucNbDsgVar), vars.ulBufferSize,
            static_cast<void*>(e.model), static_cast<void*>(e.script));
        for (unsigned int i = 0; i < vars.ucNbDsgVar; ++i)
        {
            AI_tdstDsgVarInfo info = {}; uint32_t raw = 0;
            if (!R2R_Chase22MovementRead(vars.a_stDsgVarInfo + i, info)) break;
            const unsigned int type = static_cast<unsigned int>(info.eTypeId);
            const unsigned int width = R2R_Chase22PathWidth(type);
            if (!SafeReadMemory(e.buffer + info.ulOffsetInDsgMem, &raw, width == 1 ? 1 : 4)) break;
            fprintf(f, "[CHASE22-PATH-DSG] target=%u var=%u type=%u offset=%lu raw=0x%08X", e.target, i, type, info.ulOffsetInDsgMem, raw);
            if (type == 7) { float value = 0; std::memcpy(&value, &raw, 4); fprintf(f, " float=%.9g", value); }
            fprintf(f, "\n");
        }
    }
    unsigned int budget = 64;
    while (budget && capture.comport < script.ulNbComport && capture.total < 8192)
    {
        AI_tdstComport comport = {};
        if (!R2R_Chase22MovementRead(script.a_stComport + capture.comport, comport) || comport.ucNbRules > 64)
        {
            fprintf(f, "[CHASE22-PATH-AI-UNAVAILABLE] target=%u comport=%u\n", e.target, capture.comport); ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        const bool schedule = capture.rule == comport.ucNbRules;
        if (capture.rule > comport.ucNbRules || (schedule && comport.p_stSchedule == nullptr))
        {
            ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        AI_tdstTreeInterpret* tree = schedule ? comport.p_stSchedule : comport.a_stRules == nullptr ?
            nullptr : comport.a_stRules + capture.rule;
        AI_tdstTreeInterpret rule = {}; AI_tdstNodeInterpret node = {};
        if (capture.node >= 512 || !R2R_Chase22MovementRead(tree, rule) || rule.p_stNodeInterpret == nullptr ||
            !R2R_Chase22MovementRead(rule.p_stNodeInterpret + capture.node, node))
        {
            fprintf(f, "[CHASE22-PATH-AI-UNAVAILABLE] target=%u comport=%u rule=%u schedule=%u node=%u\n",
                e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node); ++capture.rule; capture.node = 0; --budget; continue;
        }
        fprintf(f, "[CHASE22-PATH-AI-NODE] target=%u comport=%u rule=%u schedule=%u node=%u type=%u depth=%u "
            "skip=%u raw=0x%08X\n", e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node,
            static_cast<unsigned int>(node.eType), static_cast<unsigned int>(node.ucDepth),
            static_cast<unsigned int>(node.uwNodeToSkip), static_cast<unsigned int>(reinterpret_cast<uintptr_t>(node.uParam.pvValue)));
        ++capture.node; ++capture.total; --budget;
        if (static_cast<unsigned int>(node.eType) == 8) { ++capture.rule; capture.node = 0; }
    }
    if (capture.comport >= script.ulNbComport || capture.total >= 8192)
    {
        fprintf(f, "[CHASE22-PATH-AI-CAPTURE-END] target=%u nodes=%u complete=%s\n", e.target, capture.total,
            capture.comport >= script.ulNbComport ? "YES" : "BUDGET_LIMIT"); capture.complete = true;
    }
    fclose(f);
}
static void R2R_Chase22PathForgetWorld()
{
    std::memset(g_R2RChase22PathEntries, 0, sizeof(g_R2RChase22PathEntries));
    std::memset(g_R2RChase22PathCaptures, 0, sizeof(g_R2RChase22PathCaptures));
    std::memset(g_R2RChase22PathSkipLogged, 0, sizeof(g_R2RChase22PathSkipLogged));
    g_R2RChase22PathFrame = 0;g_R2RChase22PathCaptureCursor = 0;
}
static void R2R_Chase22PathControlTick()
{
    if (!R2R_Chase22MovePlaying()) { R2R_Chase22PathForgetWorld(); return; }
    R2R_Chase22MoveStartReport(); ++g_R2RChase22PathVisit; ++g_R2RChase22PathFrame;
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    R2R_Chase22PathScan(active, 0); if (inactive != active)R2R_Chase22PathScan(inactive, 0);
    for (auto& e : g_R2RChase22PathEntries)
        if (e.visit != g_R2RChase22PathVisit)e = R2R_Chase22PathEntry();
    // One capture step for the entire tick; four distinct controller models share 64 nodes/frame.
    for (unsigned int attempt = 0;attempt < R2R_CHASE22_CAPTURE_COUNT;++attempt)
    {
        const unsigned int target = (g_R2RChase22PathCaptureCursor + attempt) % R2R_CHASE22_CAPTURE_COUNT;
        const auto& capture = g_R2RChase22PathCaptures[target];
        if (capture.complete)continue;
        for (const auto& e : g_R2RChase22PathEntries)
        {
            if (e.owner == nullptr || static_cast<unsigned int>(g_R2RChase22PathTargets[e.target].kind) != target || (capture.started &&
                (e.model != capture.model || e.script != capture.script)))continue;
            R2R_Chase22PathCaptureStep(e);g_R2RChase22PathCaptureCursor = (target + 1) % R2R_CHASE22_CAPTURE_COUNT;return;
        }
    }
}

static R2R_Chase22PathEntry* R2R_Chase22PathLiveMechanics(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, R2R_Chase22PathEntry& current)
{
    if (!R2R_Chase22MovePlaying() || object == nullptr || object == HIE_M_hGetMainActor() ||
        dynamics == nullptr) return nullptr;
    for (auto& e : g_R2RChase22PathEntries)
    {
        if (e.owner != object || e.dynamics != dynamics || e.visit != g_R2RChase22PathVisit) continue;
        R2R_Chase22Identity identity = {};
        if (!R2R_Chase22ReadPathIdentity(object, identity) ||
            !R2R_Chase22PathSnapshot(object, identity, current) || !R2R_Chase22PathSame(e, current)) return nullptr;
        return &e;
    }
    return nullptr;
}

static bool R2R_Chase22PathWaypoint(const R2R_Chase22PathEntry& current, WP_tdstWayPoint& waypoint)
{
    const auto& t = g_R2RChase22PathTargets[current.target];
    if (t.kind == R2R_CHASE22_GENERATOR) return false;
    // Rayseau WayPoint_3 and piranha WayPoint_8 are native destinations.
    // Rolling-barrel endpoint roles await capture: require both references and
    // use the smaller valid radius so neither endpoint can loosen the cap.
    const unsigned int count = t.kind == R2R_CHASE22_ROLLING ? 2 : 1;
    if (count == 2 && (current.waypoints[0] == 0 || current.waypoints[1] == 0)) return false;
    for (unsigned int i = 0; i < count; ++i)
    {
        const unsigned int index = t.kind == R2R_CHASE22_PTIZETRE ? 0 : (count == 2 ? i : 1);
        WP_tdstWayPoint native = {};
        if (current.waypoints[index] == 0 || !R2R_Chase22MovementRead(
            reinterpret_cast<const WP_tdstWayPoint*>(static_cast<uintptr_t>(current.waypoints[index])), native) ||
            !std::isfinite(native.m_xRadius) || native.m_xRadius <= 0 || native.m_xRadius > 1000) return false;
        if (i == 0 || native.m_xRadius < waypoint.m_xRadius) waypoint = native;
    }
    return true;
}
static bool R2R_Chase22PathMotion(const DNM_tdstDynamicsBaseBlock& base, float& speed)
{
    speed = 0;
    const MTH3D_tdstVector commands[3] = { base.stImposeSpeed,base.stProposeSpeed,base.stPreviousSpeed };
    for (const auto& command : commands)
    {
        if (!std::isfinite(command.x) || !std::isfinite(command.y) || !std::isfinite(command.z) ||
            std::fabs(command.x) > 1000 || std::fabs(command.y) > 1000 || std::fabs(command.z) > 1000) return false;
        const float length = std::sqrt(command.x * command.x + command.y * command.y + command.z * command.z);
        if (!std::isfinite(length)) return false;
        if (length > speed) speed = length;
    }
    return true;
}
static MTH_tdxReal R2R_Chase22PathMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    R2R_Chase22PathEntry current = {};
    auto* e = R2R_Chase22PathLiveMechanics(object, dynamics, current);
    if (e == nullptr) return dt;
    const auto& t = g_R2RChase22PathTargets[current.target];
    // n.2 progression safety: ALW_Rayseau1 controls the intro handoff and the
    // exit Ptizetre can tunnel through geometry when its waypoint travel is scaled.
    // Keep both completely native regardless of F6/F7/F8.
    if (t.kind == R2R_CHASE22_GENERATOR || t.kind == R2R_CHASE22_RAY ||
        t.kind == R2R_CHASE22_PTIZETRE) return dt;
    bool travel = false;
    if (t.kind == R2R_CHASE22_RAY)
        travel = current.phase == 3 || current.phase == 4 || current.phase == 5 || current.phase == 6 ||
        current.phase == 9 || current.phase == 10 || current.phase == 11 || current.phase == 12;
    else if (t.kind == R2R_CHASE22_FISH) travel = current.phase >= 3 && current.phase <= 5;
    else if (t.kind == R2R_CHASE22_ROLLING) travel = true;
    else if (t.kind == R2R_CHASE22_PTIZETRE) travel = current.phase == 3;
    DNM_tdstDynamicsBaseBlock base = {}; float speed = 0;
    if (!R2R_Chase22MovementRead(&dynamics->stDynamicsBase, base)) return dt;
    const bool finiteMotion = R2R_Chase22PathMotion(base, speed);
    const bool moving = finiteMotion && speed > .00001f;
    const bool validDT = std::isfinite(dt) && dt > 0 && dt <= .25f;
    WP_tdstWayPoint waypoint = {};
    const bool waypointReady = R2R_Chase22PathWaypoint(current, waypoint);
    const float factor = R2R_Chase22MoveFactor(); MTH_tdxReal applied = dt; bool capped = false;
    if (travel && moving && validDT && waypointReady && factor != 1)
    {
        applied = dt * factor;
        if (factor > 1)
        {
            const float limit = 1.8f * waypoint.m_xRadius / speed;
            if (applied > limit)
            {
                // Preserve the native DT as the lower bound of a fast step.
                applied = limit > dt ? limit : dt;
                capped = true;
            }
        }
        if (!std::isfinite(applied) || applied <= 0 || applied > 1) applied = dt;
    }
    ++e->hookHits; if (applied != dt) ++e->scaledHits;
    if (e->loggedMode != g_R2RChase22RateMode) { e->hookLogs = 0; }
    const int status = !finiteMotion || !validDT ? -2 : !travel || !waypointReady ? 0 :
        !moving ? 1 : applied != dt ? (capped ? 4 : 3) : 2;
    if (e->hookLogs < 24 && (e->hookLogs == 0 || e->loggedMode != g_R2RChase22RateMode ||
        e->loggedPhase != current.phase || e->loggedMoving != status || (applied != dt && e->hookLogs < 8)))
    {
        FILE* f = nullptr; fopen_s(&f, R2R_CHASE22_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            fprintf(f, "[CHASE22-PATH-SPEED] target=%u kind=%u family=%s model=%s personal=%s path=%s "
                "mode=%d phase=%d travel=%s pathReady=%s moving=%s finiteMotion=%s validDT=%s modified=%s "
                "requestedFactor=%.3f appliedFactor=%.6f inputDT=%.9g appliedDT=%.9g speedBound=%.6f "
                "waypointRadius=%.6f stepCapped=%s graph=0x%08X waypoints=(0x%08X 0x%08X) "
                "owner=%p hookHits=%u scaledHits=%u\n", current.target, static_cast<unsigned int>(t.kind),
                t.family, t.model, e->personal, t.path, g_R2RChase22RateMode, current.phase, travel ? "YES" : "NO",
                waypointReady ? "YES" : "NO", moving ? "YES" : "NO", finiteMotion ? "YES" : "NO", validDT ? "YES" : "NO",
                applied != dt ? "YES" : "NO", factor, validDT ? static_cast<double>(applied / dt) : 1.0,
                static_cast<double>(dt), static_cast<double>(applied), speed, waypointReady ? waypoint.m_xRadius : 0.0f,
                capped ? "YES" : "NO", current.graph, current.waypoints[0], current.waypoints[1], static_cast<void*>(object),
                e->hookHits, e->scaledHits); fclose(f); ++e->hookLogs;
        }
    }
    e->loggedMode = g_R2RChase22RateMode; e->loggedPhase = current.phase; e->loggedMoving = status; return applied;
}

// v0.0.18x.0: three named Ly_10 graph/waypoint commands; read-only DSG, bounded delayed capture.
static const char* R2R_LY10_MOVEMENT_REPORT = "Rayman2Randomizer_Ly10Movement.txt";
static bool g_R2RLy10MovementReportStarted = false;
template<class T> static bool R2R_Ly10MovementRead(const T* source, T& destination)
{
    return source != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(source), sizeof(T)) &&
        SafeReadMemory(source, &destination, sizeof(T));
}
static bool R2R_Ly10MovePlaying()
{
    return GAM_g_stEngineStructure != nullptr &&
        GAM_g_stEngineStructure->eEngineMode == E_EM_ModePlaying &&
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Ly_10") == 0 &&
        GAM_g_p_stDynamicWorld != nullptr && *GAM_g_p_stDynamicWorld != nullptr;
}
static float R2R_Ly10MoveFactor()
{
    return R2R_StatsLegacyFactorForLevel(g_R2RLy10RateMode, "Ly_10", 0x10Eu);
}
static bool R2R_Ly10MoveStartReport()
{
    if (g_R2RLy10MovementReportStarted) return true;
    FILE* f = nullptr; fopen_s(&f, R2R_LY10_MOVEMENT_REPORT, "w");
    if (f == nullptr) return false;
    fprintf(f, "%s LY_10 SAFE LY ROUTE TEST\n"
        "Exact movement target: GRP_OLD_fee_Ly / GRP_Parcours_Course only.\n"
        "ALW_Rayseau1 and GRP_ARG_Ptizetre_I1 are exact-protected but fully native in all Stats modes.\n"
        "Ly speed scaling is allowed only in Intelligence 4 (Ballade) and 10 (Nage); jump/water-exit phases stay native.\n"
        "WayPoint_10 must be readable and its native acceptance radius caps fast steps to avoid overshoot/tunneling.\n"
        "Command x4 / x0.25 / native, restored if still ours; DSG and shared states stay native.\n"
        "Only the Ly identity is captured after 120 ticks, <=64 nodes/frame total, even without dynamics.\n"
        "Global Stats controls drive MIN/MAX/RANDOM/NATIVE for this validated route. Hook=%s.\n", VERSION,
        g_R2RMovementHookInstalled ? "YES" : "NO");
    fclose(f); g_R2RLy10MovementReportStarted = true; return true;
}
static int R2R_Ly10MovementPhase(const AI_tdstMind& mind, unsigned long expectedCount)
{
    AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr; AI_tdstScriptAI s = {};
    if (!R2R_Ly10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Ly10MovementRead(intel.pp_stScriptAI, script) ||
        !R2R_Ly10MovementRead(script, s) || s.a_stComport == nullptr ||
        s.ulNbComport == 0 || s.ulNbComport > 64 ||
        (expectedCount != 0 && s.ulNbComport != expectedCount)) return -1;
    const uintptr_t first = reinterpret_cast<uintptr_t>(s.a_stComport);
    const uintptr_t current = reinterpret_cast<uintptr_t>(intel.p_stCurrentComport);
    const size_t span = sizeof(AI_tdstComport) * s.ulNbComport;
    if (current < first || current - first >= span || (current - first) % sizeof(AI_tdstComport) != 0 ||
        !R2R_AddressReadable(current, sizeof(AI_tdstComport))) return -1;
    return static_cast<int>((current - first) / sizeof(AI_tdstComport));
}

// o.0: only Ly's route is speed-scaled. ALW_Rayseau1 and Ptizetre remain
// exact-protected native because they gate control/progression and use jump-heavy paths.
// Multiply only Ly's validated live command; DSG values and jump mechanics stay native.
static const unsigned int R2R_LY10_PATH_MAX_ACTORS = 64;
static const unsigned int R2R_LY10_PATH_TARGET_COUNT = 1;
// Transcribed Ly variable types only. Offsets/script counts are read at runtime.
static const unsigned int g_R2RLy10LyTypes[27] = { 11,7,7,9,17,8,0,16,5,5,8,8,7,9,0,0,0,5,7,0,11,11,7,7,7,11,11 };
struct R2R_Ly10PathTarget
{
    unsigned int rateTarget;
    const char* family;
    const char* model;
    const char* personal;
    const char* path; // Supplied native Graph name, compared as a bounded string.
    unsigned int variables;
    unsigned long minimumBytes;
    unsigned int graphIndex;
    unsigned int waypointCount;
    unsigned int waypointIndices[3];
    const unsigned int* types;
};
static const R2R_Ly10PathTarget g_R2RLy10PathTargets[R2R_LY10_PATH_TARGET_COUNT] =
{
    // WayPoint_10 (second displayed waypoint slot) is Ly's current destination.
    {2, "ly", "OLD_fee_ly", "GRP_OLD_fee_Ly", "GRP_Parcours_Course", 27,133,4,3,{5,10,11},g_R2RLy10LyTypes},
};
static int R2R_Ly10PathTargetIndex(int rateTarget)
{
    for (unsigned int i = 0; i < R2R_LY10_PATH_TARGET_COUNT; ++i)
        if (rateTarget >= 0 && static_cast<unsigned int>(rateTarget) == g_R2RLy10PathTargets[i].rateTarget)
            return static_cast<int>(i);
    return -1;
}
struct R2R_Ly10PathEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    DNM_tdstDynamics* dynamics;
    AI_tdstMind* mind;
    AI_tdstAIModel* model;
    AI_tdstDsgMem* memory;
    AI_tdstDsgVar* definition;
    AI_tdstScriptAI* script;
    char* buffer;
    unsigned long bytes;
    unsigned int target;
    int phase;
    uint32_t graph;
    uint32_t waypoints[3];
    unsigned int visit;
    int loggedMode;
    int loggedPhase;
    int loggedMoving;
    unsigned int hookLogs;
    unsigned int hookHits;
    unsigned int scaledHits;
    char personal[96];
};
static R2R_Ly10PathEntry g_R2RLy10PathEntries[R2R_LY10_PATH_MAX_ACTORS] = {};
static unsigned int g_R2RLy10PathVisit = 0;
static unsigned int g_R2RLy10PathFrame = 0;
static bool g_R2RLy10PathSkipLogged[R2R_LY10_PATH_TARGET_COUNT] = {};
static unsigned int g_R2RLy10PathCaptureCursor = 0;
static unsigned int R2R_Ly10PathWidth(unsigned int type)
{
    return type == 0 || type == 1 || type == 2 ? 1 : type == 11 ? 12 : 4;
}
static void R2R_Ly10PathSkip(unsigned int target, const char* reason)
{
    if (target >= R2R_LY10_PATH_TARGET_COUNT || g_R2RLy10PathSkipLogged[target] || !R2R_Ly10MoveStartReport()) return;
    const auto& t = g_R2RLy10PathTargets[target];
    FILE* f = nullptr; fopen_s(&f, R2R_LY10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[LY10-PATH-SKIP] family=%s model=%s personal=%s path=%s reason=%s\n",
        t.family, t.model, t.personal, t.path, reason);
    fclose(f); g_R2RLy10PathSkipLogged[target] = true;
}
static bool R2R_Ly10PathLayout(unsigned int target, const AI_tdstMind& mind, AI_tdstDsgMem& memory,
    AI_tdstDsgVar*& definition, AI_tdstDsgVar& vars)
{
    if (target >= R2R_LY10_PATH_TARGET_COUNT) return false;
    const auto& t = g_R2RLy10PathTargets[target];
    AI_tdstAIModel model = {};
    if (!R2R_Ly10MovementRead(mind.p_stAIModel, model) ||
        !R2R_Ly10MovementRead(mind.p_stDsgMem, memory) ||
        !R2R_Ly10MovementRead(memory.pp_stDsgVar, definition) ||
        definition == nullptr || definition != model.p_stDsgVar ||
        !R2R_Ly10MovementRead(definition, vars) || vars.ucNbDsgVar != t.variables ||
        vars.a_stDsgVarInfo == nullptr || vars.ulBufferSize < t.minimumBytes || vars.ulBufferSize > 256 ||
        memory.p_cDsgMemBuffer == nullptr) return false;
    // The screenshot supplies the types, not the offsets. Read native offsets
    // and verify their complete spans and non-overlap instead of inventing them.
    // DSG is only read: a current buffer aliasing init/default is acceptable.
    bool occupied[256] = {};
    for (unsigned int i = 0; i < t.variables; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Ly10MovementRead(vars.a_stDsgVarInfo + i, info)) return false;
        const unsigned int type = static_cast<unsigned int>(info.eTypeId);
        // Accept either native signed/unsigned four-byte integer for an Int field.
        if (type != t.types[i] && !(t.types[i] == 5 && type == 6)) return false;
        const unsigned int width = R2R_Ly10PathWidth(type);
        if (info.ulOffsetInDsgMem >= vars.ulBufferSize ||
            width > vars.ulBufferSize - info.ulOffsetInDsgMem) return false;
        for (unsigned long j = info.ulOffsetInDsgMem; j < info.ulOffsetInDsgMem + width; ++j)
        {
            if (occupied[j]) return false; occupied[j] = true;
        }
    }
    return R2R_AddressReadable(reinterpret_cast<uintptr_t>(memory.p_cDsgMemBuffer), vars.ulBufferSize);
}
static bool R2R_Ly10PathSnapshot(HIE_tdstSuperObject* object,
    const R2R_Ly10Identity& identity, R2R_Ly10PathEntry& result)
{
    const int target = R2R_Ly10PathTargetIndex(identity.target);
    if (target < 0) return false;
    const auto& t = g_R2RLy10PathTargets[target];
    HIE_tdstEngineObject actor = {}; AI_tdstBrain brain = {}; AI_tdstMind mind = {};
    AI_tdstDsgMem memory = {}; AI_tdstDsgVar* definition = nullptr;
    AI_tdstDsgVar vars = {}; AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr;
    AI_tdstScriptAI scripts = {};
    if (!R2R_Ly10MovementRead(identity.actor, actor) ||
        !R2R_Ly10MovementRead(actor.hBrain, brain) || !R2R_Ly10MovementRead(brain.p_stMind, mind) ||
        !R2R_Ly10PathLayout(static_cast<unsigned int>(target), mind, memory, definition, vars) ||
        !R2R_Ly10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Ly10MovementRead(intel.pp_stScriptAI, script) || !R2R_Ly10MovementRead(script, scripts)) return false;
    const int phase = R2R_Ly10MovementPhase(mind, 0);
    if (phase < 0) return false;
    result = R2R_Ly10PathEntry(); result.owner = object; result.actor = identity.actor;
    // Script-driven cinematics can lack a dynamics block. Keep their exact
    // brain/DSG snapshot for diagnosis; only live mechanics can be modified.
    DNM_tdstDynam dynam = {};
    if (R2R_Ly10MovementRead(actor.hDynam, dynam) && dynam.p_stDynamics != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stDynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        result.dynamics = dynam.p_stDynamics;
    result.mind = brain.p_stMind; result.model = mind.p_stAIModel;
    result.memory = mind.p_stDsgMem; result.definition = definition; result.script = script;
    result.buffer = memory.p_cDsgMemBuffer; result.bytes = vars.ulBufferSize; result.phase = phase; result.target = static_cast<unsigned int>(target);
    AI_tdstDsgVarInfo graphInfo = {};
    if (t.graphIndex >= t.variables || !R2R_Ly10MovementRead(vars.a_stDsgVarInfo + t.graphIndex, graphInfo) ||
        static_cast<unsigned int>(graphInfo.eTypeId) != 17 ||
        !SafeReadMemory(result.buffer + graphInfo.ulOffsetInDsgMem, &result.graph, 4) ||
        t.waypointCount == 0 || t.waypointCount > 3) return false;
    for (unsigned int i = 0; i < t.waypointCount; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (t.waypointIndices[i] >= t.variables ||
            !R2R_Ly10MovementRead(vars.a_stDsgVarInfo + t.waypointIndices[i], info) ||
            static_cast<unsigned int>(info.eTypeId) != 8 ||
            !SafeReadMemory(result.buffer + info.ulOffsetInDsgMem, &result.waypoints[i], 4)) return false;
    }
    std::memcpy(result.personal, identity.personal, sizeof(result.personal));
    return true;
}
static bool R2R_Ly10PathSame(const R2R_Ly10PathEntry& a, const R2R_Ly10PathEntry& b)
{
    return a.owner == b.owner && a.actor == b.actor && a.dynamics == b.dynamics && a.mind == b.mind &&
        a.model == b.model && a.memory == b.memory && a.definition == b.definition &&
        a.script == b.script && a.buffer == b.buffer && a.bytes == b.bytes && a.target == b.target && a.graph == b.graph;
}
static void R2R_Ly10PathProcess(HIE_tdstSuperObject* object)
{
    R2R_Ly10Identity identity = {}; R2R_Ly10PathEntry current = {};
    if (!R2R_Ly10ReadIdentity(object, identity)) return;
    const int target = R2R_Ly10PathTargetIndex(identity.target);
    if (target < 0) return;
    if (!R2R_Ly10PathSnapshot(object, identity, current))
    {
        R2R_Ly10PathSkip(static_cast<unsigned int>(target), "typed buffer or script unavailable"); return;
    }
    R2R_NoMomentumObserveMotionTarget(object, R2R_NO_MOMENTUM_NAMED);
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_LY10_PATH_MAX_ACTORS; ++i)
    {
        if (R2R_Ly10PathSame(g_R2RLy10PathEntries[i], current)) { slot = static_cast<int>(i); break; }
        if (g_R2RLy10PathEntries[i].owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0) { R2R_Ly10PathSkip(static_cast<unsigned int>(target), "tracking table full"); return; }
    R2R_Ly10PathEntry& e = g_R2RLy10PathEntries[slot];
    if (!fresh && e.visit == g_R2RLy10PathVisit) return;
    if (fresh)
    {
        e = current; e.loggedMode = -1; e.loggedPhase = -1; e.loggedMoving = -1;
        FILE* f = nullptr; fopen_s(&f, R2R_LY10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RLy10PathTargets[e.target];
            fprintf(f, "[LY10-PATH-TRACK] family=%s model=%s personal=%s path=%s "
                "phase=%d bytes=%lu owner=%p dynamics=%p buffer=%p\n",
                t.family, t.model, t.personal, t.path, e.phase, e.bytes,
                static_cast<void*>(object), static_cast<void*>(e.dynamics), static_cast<void*>(e.buffer)); fclose(f);
        }
    }
    e.phase = current.phase; std::memcpy(e.waypoints, current.waypoints, sizeof(e.waypoints)); e.visit = g_R2RLy10PathVisit;
}
static unsigned int g_R2RLy10PathScanBudget = 0;
static void R2R_Ly10PathScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || g_R2RLy10PathScanBudget == 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    --g_R2RLy10PathScanBudget;
    R2R_Ly10PathProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (g_R2RLy10PathScanBudget == 0) break; if (object != nullptr) R2R_Ly10PathScan(object, depth + 1);
    }
}
// These scripts are not in the supplied reports. Capture only three exact targets
// in small, delayed batches so a non-mechanical trajectory can be diagnosed
// without large startup captures. Raw references stay opaque.
struct R2R_Ly10PathCapture
{
    AI_tdstAIModel* model;
    AI_tdstScriptAI* script;
    unsigned int comport;
    unsigned int rule;
    unsigned int node;
    unsigned int total;
    bool started;
    bool complete;
};
static R2R_Ly10PathCapture g_R2RLy10PathCaptures[R2R_LY10_PATH_TARGET_COUNT] = {};
static void R2R_Ly10PathCaptureStep(const R2R_Ly10PathEntry& e)
{
    if (e.target >= R2R_LY10_PATH_TARGET_COUNT || g_R2RLy10PathFrame < 120 || g_R2RLy10PathCaptures[e.target].complete) return;
    const auto& t = g_R2RLy10PathTargets[e.target];
    R2R_Ly10Identity identity = {}; R2R_Ly10PathEntry current = {};
    AI_tdstScriptAI script = {}; AI_tdstDsgVar vars = {};
    if (!R2R_Ly10ReadIdentity(e.owner, identity) || !R2R_Ly10PathSnapshot(e.owner, identity, current) ||
        !R2R_Ly10PathSame(e, current) || !R2R_Ly10MovementRead(e.script, script) ||
        !R2R_Ly10MovementRead(e.definition, vars)) return;
    if (script.ulNbComport == 0 || script.ulNbComport > 64 || script.a_stComport == nullptr) return;
    auto& capture = g_R2RLy10PathCaptures[e.target];
    if (capture.started && (capture.model != e.model || capture.script != e.script)) return;
    FILE* f = nullptr; fopen_s(&f, R2R_LY10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    if (!capture.started)
    {
        capture.model = e.model; capture.script = e.script; capture.started = true;
        fprintf(f, "[LY10-PATH-AI-CAPTURE] target=%u family=%s model=%s personal=%s path=%s comports=%lu "
            "variables=%u bytes=%lu budgetPerFrame=64 totalBudget=8192 modelPtr=%p script=%p\n",
            e.target, t.family, t.model, t.personal, t.path, script.ulNbComport, static_cast<unsigned int>(vars.ucNbDsgVar), vars.ulBufferSize,
            static_cast<void*>(e.model), static_cast<void*>(e.script));
        for (unsigned int i = 0; i < t.variables; ++i)
        {
            AI_tdstDsgVarInfo info = {}; uint32_t raw = 0;
            if (!R2R_Ly10MovementRead(vars.a_stDsgVarInfo + i, info)) break;
            const unsigned int type = static_cast<unsigned int>(info.eTypeId);
            const unsigned int width = R2R_Ly10PathWidth(type);
            if (!SafeReadMemory(e.buffer + info.ulOffsetInDsgMem, &raw, width == 1 ? 1 : 4)) break;
            fprintf(f, "[LY10-PATH-DSG] target=%u var=%u type=%u offset=%lu raw=0x%08X", e.target, i, type, info.ulOffsetInDsgMem, raw);
            if (type == 7) { float value = 0; std::memcpy(&value, &raw, 4); fprintf(f, " float=%.9g", value); }
            fprintf(f, "\n");
        }
    }
    unsigned int budget = 64;
    while (budget && capture.comport < script.ulNbComport && capture.total < 8192)
    {
        AI_tdstComport comport = {};
        if (!R2R_Ly10MovementRead(script.a_stComport + capture.comport, comport) || comport.ucNbRules > 64)
        {
            fprintf(f, "[LY10-PATH-AI-UNAVAILABLE] target=%u comport=%u\n", e.target, capture.comport); ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        const bool schedule = capture.rule == comport.ucNbRules;
        if (capture.rule > comport.ucNbRules || (schedule && comport.p_stSchedule == nullptr))
        {
            ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        AI_tdstTreeInterpret* tree = schedule ? comport.p_stSchedule : comport.a_stRules == nullptr ?
            nullptr : comport.a_stRules + capture.rule;
        AI_tdstTreeInterpret rule = {}; AI_tdstNodeInterpret node = {};
        if (capture.node >= 512 || !R2R_Ly10MovementRead(tree, rule) || rule.p_stNodeInterpret == nullptr ||
            !R2R_Ly10MovementRead(rule.p_stNodeInterpret + capture.node, node))
        {
            fprintf(f, "[LY10-PATH-AI-UNAVAILABLE] target=%u comport=%u rule=%u schedule=%u node=%u\n",
                e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node); ++capture.rule; capture.node = 0; --budget; continue;
        }
        fprintf(f, "[LY10-PATH-AI-NODE] target=%u comport=%u rule=%u schedule=%u node=%u type=%u depth=%u "
            "skip=%u raw=0x%08X\n", e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node,
            static_cast<unsigned int>(node.eType), static_cast<unsigned int>(node.ucDepth),
            static_cast<unsigned int>(node.uwNodeToSkip), static_cast<unsigned int>(reinterpret_cast<uintptr_t>(node.uParam.pvValue)));
        ++capture.node; ++capture.total; --budget;
        if (static_cast<unsigned int>(node.eType) == 8) { ++capture.rule; capture.node = 0; }
    }
    if (capture.comport >= script.ulNbComport || capture.total >= 8192)
    {
        fprintf(f, "[LY10-PATH-AI-CAPTURE-END] target=%u nodes=%u complete=%s\n", e.target, capture.total,
            capture.comport >= script.ulNbComport ? "YES" : "BUDGET_LIMIT"); capture.complete = true;
    }
    fclose(f);
}
static void R2R_Ly10PathForgetWorld()
{
    std::memset(g_R2RLy10PathEntries, 0, sizeof(g_R2RLy10PathEntries));
    std::memset(g_R2RLy10PathCaptures, 0, sizeof(g_R2RLy10PathCaptures));
    std::memset(g_R2RLy10PathSkipLogged, 0, sizeof(g_R2RLy10PathSkipLogged));
    g_R2RLy10PathFrame = 0;g_R2RLy10PathCaptureCursor = 0;
}
static void R2R_Ly10PathControlTick()
{
    if (!R2R_Ly10MovePlaying()) { R2R_Ly10PathForgetWorld(); return; }
    R2R_Ly10MoveStartReport(); ++g_R2RLy10PathVisit; ++g_R2RLy10PathFrame;
    g_R2RLy10PathScanBudget = 4096;
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    R2R_Ly10PathScan(active, 0); if (inactive != active)R2R_Ly10PathScan(inactive, 0);
    for (auto& e : g_R2RLy10PathEntries)
        if (e.visit != g_R2RLy10PathVisit)e = R2R_Ly10PathEntry();
    // Only one capture step in the entire tick: three targets share 64 nodes/frame.
    for (unsigned int attempt = 0;attempt < R2R_LY10_PATH_TARGET_COUNT;++attempt)
    {
        const unsigned int target = (g_R2RLy10PathCaptureCursor + attempt) % R2R_LY10_PATH_TARGET_COUNT;
        const auto& capture = g_R2RLy10PathCaptures[target];
        if (capture.complete)continue;
        for (const auto& e : g_R2RLy10PathEntries)
        {
            if (e.owner == nullptr || e.target != target || (capture.started &&
                (e.model != capture.model || e.script != capture.script)))continue;
            R2R_Ly10PathCaptureStep(e);g_R2RLy10PathCaptureCursor = (target + 1) % R2R_LY10_PATH_TARGET_COUNT;return;
        }
    }
}

static bool R2R_Ly10PathWritable(const void* address, size_t length)
{
    if (address == nullptr || length == 0) return false;
    MEMORY_BASIC_INFORMATION info = {};
    if (VirtualQuery(address, &info, sizeof(info)) == 0 || info.State != MEM_COMMIT ||
        (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const DWORD p = info.Protect & 0xff;
    if (p != PAGE_READWRITE && p != PAGE_WRITECOPY &&
        p != PAGE_EXECUTE_READWRITE && p != PAGE_EXECUTE_WRITECOPY) return false;
    const uintptr_t start = reinterpret_cast<uintptr_t>(address);
    const uintptr_t base = reinterpret_cast<uintptr_t>(info.BaseAddress);
    return start >= base && start - base < info.RegionSize &&
        length <= info.RegionSize - (start - base) && R2R_AddressReadable(start, length);
}
static R2R_Ly10PathEntry* R2R_Ly10PathLiveMechanics(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, R2R_Ly10PathEntry& current)
{
    if (!R2R_Ly10MovePlaying() || object == nullptr || object == HIE_M_hGetMainActor() ||
        dynamics == nullptr) return nullptr;
    for (auto& e : g_R2RLy10PathEntries)
    {
        if (e.owner != object || e.dynamics != dynamics || e.visit != g_R2RLy10PathVisit) continue;
        R2R_Ly10Identity identity = {};
        if (!R2R_Ly10ReadIdentity(object, identity) ||
            !R2R_Ly10PathSnapshot(object, identity, current) || !R2R_Ly10PathSame(e, current)) return nullptr;
        return &e;
    }
    return nullptr;
}
static bool R2R_Ly10PathWaypoint(const R2R_Ly10PathEntry& current, WP_tdstWayPoint& waypoint)
{
    if (current.target >= R2R_LY10_PATH_TARGET_COUNT) return false;
    // Ly's displayed waypoint slots are WayPoint_5, WayPoint_10, WayPoint_11.
    // WayPoint_10 is assigned on every route transition and is the live destination.
    const uint32_t raw = current.waypoints[1];
    if (raw == 0 || !R2R_Ly10MovementRead(
        reinterpret_cast<WP_tdstWayPoint*>(static_cast<uintptr_t>(raw)), waypoint)) return false;
    return std::isfinite(waypoint.m_stVertex.x) && std::isfinite(waypoint.m_stVertex.y) &&
        std::isfinite(waypoint.m_stVertex.z) && std::isfinite(waypoint.m_xRadius) &&
        waypoint.m_xRadius > 0.0f && waypoint.m_xRadius <= 1000.0f;
}
static bool R2R_Ly10PathReady(const R2R_Ly10PathEntry& current, WP_tdstWayPoint& waypoint)
{
    if (current.target >= R2R_LY10_PATH_TARGET_COUNT || current.graph == 0) return false;
    const auto& t = g_R2RLy10PathTargets[current.target];
    WP_tdstGraph graph = {}; char name[96] = {};
    if (!R2R_Ly10MovementRead(reinterpret_cast<WP_tdstGraph*>(static_cast<uintptr_t>(current.graph)), graph) ||
        !R2R_Ly10CopyName(graph.m_szNameOfGraph, name, sizeof(name)) || _stricmp(name, t.path) != 0) return false;
    return R2R_Ly10PathWaypoint(current, waypoint);
}
static bool R2R_Ly10PathBeginMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    MTH_tdxReal dt, MTH3D_tdstVector& original, MTH3D_tdstVector& applied)
{
    R2R_Ly10PathEntry current = {}; MTH3D_tdstVector before = {};
    R2R_Ly10PathEntry* e = R2R_Ly10PathLiveMechanics(object, dynamics, current);
    if (e == nullptr || !R2R_Ly10MovementRead(&dynamics->stDynamicsBase.stImposeSpeed, before)) return false;

    const bool validVector = std::isfinite(before.x) && std::isfinite(before.y) && std::isfinite(before.z) &&
        std::fabs(before.x) <= 1000 && std::fabs(before.y) <= 1000 && std::fabs(before.z) <= 1000;
    const float speed = validVector ? std::sqrt(before.x * before.x + before.y * before.y + before.z * before.z) : 0.0f;
    const bool moving = validVector && std::isfinite(speed) && speed > .00001f;
    const bool validDT = std::isfinite(dt) && dt > 0 && dt <= .25f;

    // OLD_fee_ly Intelligence[4] = MTR_ly_Ballade and Intelligence[10] = MTR_ly_Nage.
    // Jump phases 5 and 11 use Proc_JumpImpulsion and are deliberately untouched.
    const bool travel = current.phase == 4 || current.phase == 10;
    WP_tdstWayPoint waypoint = {};
    const bool pathReady = travel && R2R_Ly10PathReady(current, waypoint);

    const float requestedFactor = R2R_Ly10MoveFactor();
    float factor = requestedFactor;
    bool capped = false;
    if (pathReady && moving && validDT && factor > 1.0f)
    {
        const float maxFactor = (1.8f * waypoint.m_xRadius) / (speed * dt);
        if (std::isfinite(maxFactor) && factor > maxFactor)
        {
            factor = maxFactor > 1.0f ? maxFactor : 1.0f;
            capped = true;
        }
    }

    bool modified = false;
    original = before; applied = before;
    if (pathReady && moving && validDT && factor != 1 &&
        R2R_Ly10PathWritable(&dynamics->stDynamicsBase.stImposeSpeed, sizeof(applied)))
    {
        applied = { before.x * factor, before.y * factor, before.z * factor };
        std::memcpy(&dynamics->stDynamicsBase.stImposeSpeed, &applied, sizeof(applied));
        modified = true; ++e->scaledHits;
    }

    ++e->hookHits;
    if (e->loggedMode != g_R2RLy10RateMode) e->hookLogs = 0;
    const int status = !validVector || !validDT ? -2 : !travel || !pathReady ? 0 :
        !moving ? 1 : modified ? (capped ? 4 : 3) : 2;
    if (e->hookLogs < 24 && (e->hookLogs == 0 || e->loggedMode != g_R2RLy10RateMode ||
        e->loggedPhase != current.phase || e->loggedMoving != status || (modified && e->hookLogs < 8)))
    {
        FILE* f = nullptr; fopen_s(&f, R2R_LY10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RLy10PathTargets[current.target];
            fprintf(f, "[LY10-PATH-SPEED] family=%s model=%s personal=%s path=%s "
                "mode=%d phase=%d travel=%s pathReady=%s moving=%s validVector=%s validDT=%s modified=%s "
                "requestedFactor=%.3f appliedFactor=%.6f inputDT=%.9g speed=%.6f waypointRadius=%.6f capped=%s "
                "before=(%.6f %.6f %.6f) applied=(%.6f %.6f %.6f) "
                "graph=0x%08X waypoints=(0x%08X 0x%08X 0x%08X) owner=%p hookHits=%u scaledHits=%u\n",
                t.family, t.model, t.personal, t.path, g_R2RLy10RateMode, current.phase,
                travel ? "YES" : "NO", pathReady ? "YES" : "NO", moving ? "YES" : "NO",
                validVector ? "YES" : "NO", validDT ? "YES" : "NO", modified ? "YES" : "NO",
                requestedFactor, modified ? factor : 1.0f, static_cast<double>(dt), speed,
                pathReady ? waypoint.m_xRadius : 0.0f, capped ? "YES" : "NO",
                before.x, before.y, before.z, applied.x, applied.y, applied.z,
                current.graph, current.waypoints[0], current.waypoints[1], current.waypoints[2],
                static_cast<void*>(object), e->hookHits, e->scaledHits);
            fclose(f); ++e->hookLogs;
        }
    }
    e->loggedMode = g_R2RLy10RateMode;
    e->loggedPhase = current.phase;
    e->loggedMoving = status;
    return modified;
}
static void R2R_Ly10PathEndMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    const MTH3D_tdstVector& original, const MTH3D_tdstVector& applied)
{
    R2R_Ly10PathEntry current = {}; MTH3D_tdstVector after = {};
    if (R2R_Ly10PathLiveMechanics(object, dynamics, current) == nullptr ||
        !R2R_Ly10MovementRead(&dynamics->stDynamicsBase.stImposeSpeed, after) ||
        after.x != applied.x || after.y != applied.y || after.z != applied.z ||
        !R2R_Ly10PathWritable(&dynamics->stDynamicsBase.stImposeSpeed, sizeof(original))) return;
    // Restore only our own temporary command, preserving native stops/new commands.
    std::memcpy(&dynamics->stDynamicsBase.stImposeSpeed, &original, sizeof(original));
}

// v0.0.18x.0: two exact nego_10 cinematic waypoint commands; no invented graph/timer roles.
static const char* R2R_NEGO10_MOVEMENT_REPORT = "Rayman2Randomizer_Nego10Movement.txt";
static bool g_R2RNego10MovementReportStarted = false;
template<class T> static bool R2R_Nego10MovementRead(const T* source, T& destination)
{
    return source != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(source), sizeof(T)) &&
        SafeReadMemory(source, &destination, sizeof(T));
}
static bool R2R_Nego10MovePlaying()
{
    return GAM_g_stEngineStructure != nullptr &&
        GAM_g_stEngineStructure->eEngineMode == E_EM_ModePlaying &&
        _stricmp(GAM_g_stEngineStructure->szLevelName, "nego_10") == 0 &&
        GAM_g_p_stDynamicWorld != nullptr && *GAM_g_p_stDynamicWorld != nullptr;
}
static float R2R_Nego10MoveFactor()
{
    // p.0: the complete selective export shows only command-driven positioning/actions
    // for the two waypoint-bearing cinematic actors.  Their WayPoint_1/2 values are
    // staging/teleport references, not a validated movement-speed control.  Keep every
    // live mechanics command native so F6/F7/F8 cannot desynchronise the negotiation
    // cinematic or its map transition.  Animation-rate randomization remains separate.
    return 1.0f;
}
static bool R2R_Nego10MoveStartReport()
{
    if (g_R2RNego10MovementReportStarted) return true;
    FILE* f = nullptr; fopen_s(&f, R2R_NEGO10_MOVEMENT_REPORT, "w");
    if (f == nullptr) return false;
    fprintf(f, "%s NEGO_10 TWO ISOLATED WAYPOINT COMMAND TESTS\n"
        "Exact Ray_Nego / NIK_Ray_Nego / NIK_Ray_Nego_2 and ptizetre_nego_cine / NIK_Ptizetre_nego_cine / NIK_Ptizetre_nego_cine.\n"
        "Both supplied layouts use isolated WayPoint_1/2; there is no displayed Graph or speed Float.\n"
        "At least one supplied nonnull WayPoint and finite nonzero native imposed command required.\n"
        "Command x4 / x0.25 / native, restored if still ours; native DT/DSG/shared states preserved.\n"
        "Native momentum in F6/F7/F8. Main player and unrelated rayman helpers excluded.\n"
        "No point pairing, travel phase, interpolation timer or arrival threshold is invented.\n"
        "Only two exact scripts captured after 120 ticks, <=64 nodes/frame total, even without dynamics.\n"
        "A direct script trajectory without a mechanics command needs its native capture for diagnosis.\n"
        "Global Stats controls drive MIN/MAX/RANDOM/NATIVE for this validated route. Hook=%s.\n", VERSION,
        g_R2RMovementHookInstalled ? "YES" : "NO");
    fclose(f); g_R2RNego10MovementReportStarted = true; return true;
}
static int R2R_Nego10MovementPhase(const AI_tdstMind& mind, unsigned long expectedCount)
{
    AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr; AI_tdstScriptAI s = {};
    if (!R2R_Nego10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Nego10MovementRead(intel.pp_stScriptAI, script) ||
        !R2R_Nego10MovementRead(script, s) || s.a_stComport == nullptr ||
        s.ulNbComport == 0 || s.ulNbComport > 64 ||
        (expectedCount != 0 && s.ulNbComport != expectedCount)) return -1;
    const uintptr_t first = reinterpret_cast<uintptr_t>(s.a_stComport);
    const uintptr_t current = reinterpret_cast<uintptr_t>(intel.p_stCurrentComport);
    const size_t span = sizeof(AI_tdstComport) * s.ulNbComport;
    if (current < first || current - first >= span || (current - first) % sizeof(AI_tdstComport) != 0 ||
        !R2R_AddressReadable(current, sizeof(AI_tdstComport))) return -1;
    return static_cast<int>((current - first) / sizeof(AI_tdstComport));
}

// The supplied images establish types and isolated points; no Graph or speed Float is displayed.
// Multiply only the validated live imposed command, leaving DSG and DT native.
static const unsigned int R2R_NEGO10_PATH_MAX_ACTORS = 64;
static const unsigned int R2R_NEGO10_PATH_TARGET_COUNT = 2;
static const unsigned int g_R2RNego10RayTypes[7] = { 2,8,8,9,5,5,5 };
static const unsigned int g_R2RNego10PtizTypes[5] = { 2,8,8,9,0 };
struct R2R_Nego10PathTarget
{
    unsigned int rateTarget;
    const char* family;
    const char* model;
    const char* personal;
    const char* path; // Displayed slots only: no native Graph name was supplied.
    unsigned int variables;
    unsigned long minimumBytes;
    unsigned int firstWaypoint;
    unsigned int waypointCount;
    const unsigned int* types;
};
static const R2R_Nego10PathTarget g_R2RNego10PathTargets[R2R_NEGO10_PATH_TARGET_COUNT] =
{
    {0,"Ray_Nego","NIK_Ray_Nego","NIK_Ray_Nego_2","WayPoint_1/2 (isolated)",7,25,1,2,g_R2RNego10RayTypes},
    {2,"ptizetre_nego_cine","NIK_Ptizetre_nego_cine","NIK_Ptizetre_nego_cine","WayPoint_1/2 (isolated)",5,14,1,2,g_R2RNego10PtizTypes},
};
static int R2R_Nego10PathTargetIndex(int rateTarget)
{
    for (unsigned int i = 0; i < R2R_NEGO10_PATH_TARGET_COUNT; ++i)
        if (rateTarget >= 0 && static_cast<unsigned int>(rateTarget) == g_R2RNego10PathTargets[i].rateTarget)
            return static_cast<int>(i);
    return -1;
}
struct R2R_Nego10PathEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    DNM_tdstDynamics* dynamics;
    AI_tdstMind* mind;
    AI_tdstAIModel* model;
    AI_tdstDsgMem* memory;
    AI_tdstDsgVar* definition;
    AI_tdstScriptAI* script;
    char* buffer;
    unsigned long bytes;
    unsigned int target;
    int phase;
    uint32_t waypoints[3];
    unsigned int visit;
    int loggedMode;
    int loggedPhase;
    int loggedMoving;
    unsigned int hookLogs;
    unsigned int hookHits;
    unsigned int scaledHits;
    char personal[96];
};
static R2R_Nego10PathEntry g_R2RNego10PathEntries[R2R_NEGO10_PATH_MAX_ACTORS] = {};
static unsigned int g_R2RNego10PathVisit = 0;
static unsigned int g_R2RNego10PathFrame = 0;
static bool g_R2RNego10PathSkipLogged[R2R_NEGO10_PATH_TARGET_COUNT] = {};
static unsigned int g_R2RNego10PathCaptureCursor = 0;
static unsigned int R2R_Nego10PathWidth(unsigned int type)
{
    return type == 0 || type == 1 || type == 2 ? 1 : type == 11 ? 12 : 4;
}
static void R2R_Nego10PathSkip(unsigned int target, const char* reason)
{
    if (target >= R2R_NEGO10_PATH_TARGET_COUNT || g_R2RNego10PathSkipLogged[target] || !R2R_Nego10MoveStartReport()) return;
    const auto& t = g_R2RNego10PathTargets[target];
    FILE* f = nullptr; fopen_s(&f, R2R_NEGO10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[NEGO10-PATH-SKIP] family=%s model=%s personal=%s path=%s reason=%s\n",
        t.family, t.model, t.personal, t.path, reason);
    fclose(f); g_R2RNego10PathSkipLogged[target] = true;
}
static bool R2R_Nego10PathLayout(unsigned int target, const AI_tdstMind& mind, AI_tdstDsgMem& memory,
    AI_tdstDsgVar*& definition, AI_tdstDsgVar& vars)
{
    if (target >= R2R_NEGO10_PATH_TARGET_COUNT) return false;
    const auto& t = g_R2RNego10PathTargets[target];
    AI_tdstAIModel model = {};
    if (!R2R_Nego10MovementRead(mind.p_stAIModel, model) ||
        !R2R_Nego10MovementRead(mind.p_stDsgMem, memory) ||
        !R2R_Nego10MovementRead(memory.pp_stDsgVar, definition) ||
        definition == nullptr || definition != model.p_stDsgVar ||
        !R2R_Nego10MovementRead(definition, vars) || vars.ucNbDsgVar != t.variables ||
        vars.a_stDsgVarInfo == nullptr || vars.ulBufferSize < t.minimumBytes || vars.ulBufferSize > 256 ||
        memory.p_cDsgMemBuffer == nullptr) return false;
    // The screenshot supplies the types, not the offsets. Read native offsets
    // and verify their complete spans and non-overlap instead of inventing them.
    // DSG is only read: a current buffer aliasing init/default is acceptable.
    bool occupied[256] = {};
    for (unsigned int i = 0; i < t.variables; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Nego10MovementRead(vars.a_stDsgVarInfo + i, info)) return false;
        const unsigned int type = static_cast<unsigned int>(info.eTypeId);
        // Accept either native signed/unsigned four-byte integer for an Int field.
        if (type != t.types[i] && !(t.types[i] == 5 && type == 6)) return false;
        const unsigned int width = R2R_Nego10PathWidth(type);
        if (info.ulOffsetInDsgMem >= vars.ulBufferSize ||
            width > vars.ulBufferSize - info.ulOffsetInDsgMem) return false;
        for (unsigned long j = info.ulOffsetInDsgMem; j < info.ulOffsetInDsgMem + width; ++j)
        {
            if (occupied[j]) return false; occupied[j] = true;
        }
    }
    return R2R_AddressReadable(reinterpret_cast<uintptr_t>(memory.p_cDsgMemBuffer), vars.ulBufferSize);
}
static bool R2R_Nego10PathSnapshot(HIE_tdstSuperObject* object,
    const R2R_Nego10Identity& identity, R2R_Nego10PathEntry& result)
{
    const int target = R2R_Nego10PathTargetIndex(identity.target);
    if (target < 0) return false;
    const auto& t = g_R2RNego10PathTargets[target];
    HIE_tdstEngineObject actor = {}; AI_tdstBrain brain = {}; AI_tdstMind mind = {};
    AI_tdstDsgMem memory = {}; AI_tdstDsgVar* definition = nullptr;
    AI_tdstDsgVar vars = {}; AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr;
    AI_tdstScriptAI scripts = {};
    if (!R2R_Nego10MovementRead(identity.actor, actor) ||
        !R2R_Nego10MovementRead(actor.hBrain, brain) || !R2R_Nego10MovementRead(brain.p_stMind, mind) ||
        !R2R_Nego10PathLayout(static_cast<unsigned int>(target), mind, memory, definition, vars) ||
        !R2R_Nego10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Nego10MovementRead(intel.pp_stScriptAI, script) || !R2R_Nego10MovementRead(script, scripts)) return false;
    const int phase = R2R_Nego10MovementPhase(mind, 0);
    if (phase < 0) return false;
    result = R2R_Nego10PathEntry(); result.owner = object; result.actor = identity.actor;
    // Script-driven cinematics can lack a dynamics block. Keep their exact
    // brain/DSG snapshot for diagnosis; only live mechanics can be modified.
    DNM_tdstDynam dynam = {};
    if (R2R_Nego10MovementRead(actor.hDynam, dynam) && dynam.p_stDynamics != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stDynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        result.dynamics = dynam.p_stDynamics;
    result.mind = brain.p_stMind; result.model = mind.p_stAIModel;
    result.memory = mind.p_stDsgMem; result.definition = definition; result.script = script;
    result.buffer = memory.p_cDsgMemBuffer; result.bytes = vars.ulBufferSize; result.phase = phase; result.target = static_cast<unsigned int>(target);
    if (t.waypointCount == 0 || t.waypointCount > 3 || t.firstWaypoint >= t.variables ||
        t.waypointCount > t.variables - t.firstWaypoint) return false;
    for (unsigned int i = 0; i < t.waypointCount; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Nego10MovementRead(vars.a_stDsgVarInfo + t.firstWaypoint + i, info) ||
            static_cast<unsigned int>(info.eTypeId) != 8 ||
            !SafeReadMemory(result.buffer + info.ulOffsetInDsgMem, &result.waypoints[i], 4)) return false;
    }
    std::memcpy(result.personal, identity.personal, sizeof(result.personal));
    return true;
}
static bool R2R_Nego10PathSame(const R2R_Nego10PathEntry& a, const R2R_Nego10PathEntry& b)
{
    return a.owner == b.owner && a.actor == b.actor && a.dynamics == b.dynamics && a.mind == b.mind &&
        a.model == b.model && a.memory == b.memory && a.definition == b.definition &&
        a.script == b.script && a.buffer == b.buffer && a.bytes == b.bytes && a.target == b.target;
}
static void R2R_Nego10PathProcess(HIE_tdstSuperObject* object)
{
    R2R_Nego10Identity identity = {}; R2R_Nego10PathEntry current = {};
    if (!R2R_Nego10ReadIdentity(object, identity)) return;
    const int target = R2R_Nego10PathTargetIndex(identity.target);
    if (target < 0) return;
    if (!R2R_Nego10PathSnapshot(object, identity, current))
    {
        R2R_Nego10PathSkip(static_cast<unsigned int>(target), "typed buffer or script unavailable"); return;
    }
    R2R_NoMomentumObserveMotionTarget(object, R2R_NO_MOMENTUM_NAMED);
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_NEGO10_PATH_MAX_ACTORS; ++i)
    {
        if (R2R_Nego10PathSame(g_R2RNego10PathEntries[i], current)) { slot = static_cast<int>(i); break; }
        if (g_R2RNego10PathEntries[i].owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0) { R2R_Nego10PathSkip(static_cast<unsigned int>(target), "tracking table full"); return; }
    R2R_Nego10PathEntry& e = g_R2RNego10PathEntries[slot];
    if (!fresh && e.visit == g_R2RNego10PathVisit) return;
    if (fresh)
    {
        e = current; e.loggedMode = -1; e.loggedPhase = -1; e.loggedMoving = -1;
        FILE* f = nullptr; fopen_s(&f, R2R_NEGO10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RNego10PathTargets[e.target];
            fprintf(f, "[NEGO10-PATH-TRACK] family=%s model=%s personal=%s path=%s "
                "phase=%d bytes=%lu owner=%p dynamics=%p buffer=%p\n",
                t.family, t.model, t.personal, t.path, e.phase, e.bytes,
                static_cast<void*>(object), static_cast<void*>(e.dynamics), static_cast<void*>(e.buffer)); fclose(f);
        }
    }
    e.phase = current.phase; std::memcpy(e.waypoints, current.waypoints, sizeof(e.waypoints)); e.visit = g_R2RNego10PathVisit;
}
static unsigned int g_R2RNego10PathScanBudget = 0;
static void R2R_Nego10PathScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || g_R2RNego10PathScanBudget == 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    --g_R2RNego10PathScanBudget;
    R2R_Nego10PathProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (g_R2RNego10PathScanBudget == 0) break; if (object != nullptr) R2R_Nego10PathScan(object, depth + 1);
    }
}
// These scripts are not in the supplied reports. Capture only two exact targets
// in small, delayed batches so a non-mechanical trajectory can be diagnosed
// without large startup captures. Raw references stay opaque.
struct R2R_Nego10PathCapture
{
    AI_tdstAIModel* model;
    AI_tdstScriptAI* script;
    unsigned int comport;
    unsigned int rule;
    unsigned int node;
    unsigned int total;
    bool started;
    bool complete;
};
static R2R_Nego10PathCapture g_R2RNego10PathCaptures[R2R_NEGO10_PATH_TARGET_COUNT] = {};
static void R2R_Nego10PathCaptureStep(const R2R_Nego10PathEntry& e)
{
    if (e.target >= R2R_NEGO10_PATH_TARGET_COUNT || g_R2RNego10PathFrame < 120 || g_R2RNego10PathCaptures[e.target].complete) return;
    const auto& t = g_R2RNego10PathTargets[e.target];
    R2R_Nego10Identity identity = {}; R2R_Nego10PathEntry current = {};
    AI_tdstScriptAI script = {}; AI_tdstDsgVar vars = {};
    if (!R2R_Nego10ReadIdentity(e.owner, identity) || !R2R_Nego10PathSnapshot(e.owner, identity, current) ||
        !R2R_Nego10PathSame(e, current) || !R2R_Nego10MovementRead(e.script, script) ||
        !R2R_Nego10MovementRead(e.definition, vars)) return;
    if (script.ulNbComport == 0 || script.ulNbComport > 64 || script.a_stComport == nullptr) return;
    auto& capture = g_R2RNego10PathCaptures[e.target];
    if (capture.started && (capture.model != e.model || capture.script != e.script)) return;
    FILE* f = nullptr; fopen_s(&f, R2R_NEGO10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    if (!capture.started)
    {
        capture.model = e.model; capture.script = e.script; capture.started = true;
        fprintf(f, "[NEGO10-PATH-AI-CAPTURE] target=%u family=%s model=%s personal=%s path=%s comports=%lu "
            "variables=%u bytes=%lu budgetPerFrame=64 totalBudget=8192 modelPtr=%p script=%p\n",
            e.target, t.family, t.model, t.personal, t.path, script.ulNbComport, static_cast<unsigned int>(vars.ucNbDsgVar), vars.ulBufferSize,
            static_cast<void*>(e.model), static_cast<void*>(e.script));
        for (unsigned int i = 0; i < t.variables; ++i)
        {
            AI_tdstDsgVarInfo info = {}; uint32_t raw = 0;
            if (!R2R_Nego10MovementRead(vars.a_stDsgVarInfo + i, info)) break;
            const unsigned int type = static_cast<unsigned int>(info.eTypeId);
            const unsigned int width = R2R_Nego10PathWidth(type);
            if (!SafeReadMemory(e.buffer + info.ulOffsetInDsgMem, &raw, width == 1 ? 1 : 4)) break;
            fprintf(f, "[NEGO10-PATH-DSG] target=%u var=%u type=%u offset=%lu raw=0x%08X", e.target, i, type, info.ulOffsetInDsgMem, raw);
            if (type == 7) { float value = 0; std::memcpy(&value, &raw, 4); fprintf(f, " float=%.9g", value); }
            fprintf(f, "\n");
        }
    }
    unsigned int budget = 64;
    while (budget && capture.comport < script.ulNbComport && capture.total < 8192)
    {
        AI_tdstComport comport = {};
        if (!R2R_Nego10MovementRead(script.a_stComport + capture.comport, comport) || comport.ucNbRules > 64)
        {
            fprintf(f, "[NEGO10-PATH-AI-UNAVAILABLE] target=%u comport=%u\n", e.target, capture.comport); ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        const bool schedule = capture.rule == comport.ucNbRules;
        if (capture.rule > comport.ucNbRules || (schedule && comport.p_stSchedule == nullptr))
        {
            ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        AI_tdstTreeInterpret* tree = schedule ? comport.p_stSchedule : comport.a_stRules == nullptr ?
            nullptr : comport.a_stRules + capture.rule;
        AI_tdstTreeInterpret rule = {}; AI_tdstNodeInterpret node = {};
        if (capture.node >= 512 || !R2R_Nego10MovementRead(tree, rule) || rule.p_stNodeInterpret == nullptr ||
            !R2R_Nego10MovementRead(rule.p_stNodeInterpret + capture.node, node))
        {
            fprintf(f, "[NEGO10-PATH-AI-UNAVAILABLE] target=%u comport=%u rule=%u schedule=%u node=%u\n",
                e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node); ++capture.rule; capture.node = 0; --budget; continue;
        }
        fprintf(f, "[NEGO10-PATH-AI-NODE] target=%u comport=%u rule=%u schedule=%u node=%u type=%u depth=%u "
            "skip=%u raw=0x%08X\n", e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node,
            static_cast<unsigned int>(node.eType), static_cast<unsigned int>(node.ucDepth),
            static_cast<unsigned int>(node.uwNodeToSkip), static_cast<unsigned int>(reinterpret_cast<uintptr_t>(node.uParam.pvValue)));
        ++capture.node; ++capture.total; --budget;
        if (static_cast<unsigned int>(node.eType) == 8) { ++capture.rule; capture.node = 0; }
    }
    if (capture.comport >= script.ulNbComport || capture.total >= 8192)
    {
        fprintf(f, "[NEGO10-PATH-AI-CAPTURE-END] target=%u nodes=%u complete=%s\n", e.target, capture.total,
            capture.comport >= script.ulNbComport ? "YES" : "BUDGET_LIMIT"); capture.complete = true;
    }
    fclose(f);
}
static void R2R_Nego10PathForgetWorld()
{
    std::memset(g_R2RNego10PathEntries, 0, sizeof(g_R2RNego10PathEntries));
    std::memset(g_R2RNego10PathCaptures, 0, sizeof(g_R2RNego10PathCaptures));
    std::memset(g_R2RNego10PathSkipLogged, 0, sizeof(g_R2RNego10PathSkipLogged));
    g_R2RNego10PathFrame = 0;g_R2RNego10PathCaptureCursor = 0;
}
static void R2R_Nego10PathControlTick()
{
    if (!R2R_Nego10MovePlaying()) { R2R_Nego10PathForgetWorld(); return; }
    R2R_Nego10MoveStartReport(); ++g_R2RNego10PathVisit; ++g_R2RNego10PathFrame;
    g_R2RNego10PathScanBudget = 4096;
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    R2R_Nego10PathScan(active, 0); if (inactive != active)R2R_Nego10PathScan(inactive, 0);
    for (auto& e : g_R2RNego10PathEntries)
        if (e.visit != g_R2RNego10PathVisit)e = R2R_Nego10PathEntry();
    // Only one capture step in the entire tick: two targets share 64 nodes/frame.
    for (unsigned int attempt = 0;attempt < R2R_NEGO10_PATH_TARGET_COUNT;++attempt)
    {
        const unsigned int target = (g_R2RNego10PathCaptureCursor + attempt) % R2R_NEGO10_PATH_TARGET_COUNT;
        const auto& capture = g_R2RNego10PathCaptures[target];
        if (capture.complete)continue;
        for (const auto& e : g_R2RNego10PathEntries)
        {
            if (e.owner == nullptr || e.target != target || (capture.started &&
                (e.model != capture.model || e.script != capture.script)))continue;
            R2R_Nego10PathCaptureStep(e);g_R2RNego10PathCaptureCursor = (target + 1) % R2R_NEGO10_PATH_TARGET_COUNT;return;
        }
    }
}

static bool R2R_Nego10PathWritable(const void* address, size_t length)
{
    if (address == nullptr || length == 0) return false;
    MEMORY_BASIC_INFORMATION info = {};
    if (VirtualQuery(address, &info, sizeof(info)) == 0 || info.State != MEM_COMMIT ||
        (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const DWORD p = info.Protect & 0xff;
    if (p != PAGE_READWRITE && p != PAGE_WRITECOPY &&
        p != PAGE_EXECUTE_READWRITE && p != PAGE_EXECUTE_WRITECOPY) return false;
    const uintptr_t start = reinterpret_cast<uintptr_t>(address);
    const uintptr_t base = reinterpret_cast<uintptr_t>(info.BaseAddress);
    return start >= base && start - base < info.RegionSize &&
        length <= info.RegionSize - (start - base) && R2R_AddressReadable(start, length);
}
static R2R_Nego10PathEntry* R2R_Nego10PathLiveMechanics(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, R2R_Nego10PathEntry& current)
{
    if (!R2R_Nego10MovePlaying() || object == nullptr || object == HIE_M_hGetMainActor() ||
        dynamics == nullptr) return nullptr;
    for (auto& e : g_R2RNego10PathEntries)
    {
        if (e.owner != object || e.dynamics != dynamics || e.visit != g_R2RNego10PathVisit) continue;
        R2R_Nego10Identity identity = {};
        if (!R2R_Nego10ReadIdentity(object, identity) ||
            !R2R_Nego10PathSnapshot(object, identity, current) || !R2R_Nego10PathSame(e, current)) return nullptr;
        return &e;
    }
    return nullptr;
}
static bool R2R_Nego10PathBeginMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    MTH_tdxReal dt, MTH3D_tdstVector& original, MTH3D_tdstVector& applied)
{
    R2R_Nego10PathEntry current = {}; MTH3D_tdstVector before = {};
    R2R_Nego10PathEntry* e = R2R_Nego10PathLiveMechanics(object, dynamics, current);
    if (e == nullptr || !R2R_Nego10MovementRead(&dynamics->stDynamicsBase.stImposeSpeed, before)) return false;
    const bool validVector = std::isfinite(before.x) && std::isfinite(before.y) && std::isfinite(before.z) &&
        std::fabs(before.x) <= 1000 && std::fabs(before.y) <= 1000 && std::fabs(before.z) <= 1000;
    const bool moving = validVector && std::fabs(before.x) + std::fabs(before.y) + std::fabs(before.z) > .00001f;
    const bool pathReady = current.waypoints[0] != 0 || current.waypoints[1] != 0 || current.waypoints[2] != 0;
    const bool validDT = std::isfinite(dt) && dt > 0 && dt <= .25f;
    const float factor = R2R_Nego10MoveFactor();
    bool modified = false;
    original = before; applied = before;
    if (pathReady && moving && validDT && factor != 1 &&
        R2R_Nego10PathWritable(&dynamics->stDynamicsBase.stImposeSpeed, sizeof(applied)))
    {
        applied = { before.x * factor, before.y * factor, before.z * factor };
        std::memcpy(&dynamics->stDynamicsBase.stImposeSpeed, &applied, sizeof(applied));
        modified = true; ++e->scaledHits;
    }
    ++e->hookHits;
    if (e->loggedMode != g_R2RNego10RateMode) e->hookLogs = 0;
    // Short samples show native stops and missing path references as well as writes.
    const int status = !validVector || !validDT ? -2 : !pathReady ? 0 : !moving ? 1 : modified ? 3 : 2;
    if (e->hookLogs < 24 && (e->hookLogs == 0 || e->loggedMode != g_R2RNego10RateMode ||
        e->loggedPhase != current.phase || e->loggedMoving != status || (modified && e->hookLogs < 8)))
    {
        FILE* f = nullptr; fopen_s(&f, R2R_NEGO10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RNego10PathTargets[current.target];
            fprintf(f, "[NEGO10-PATH-SPEED] family=%s model=%s personal=%s path=%s "
                "mode=%d phase=%d pathReady=%s moving=%s validVector=%s validDT=%s modified=%s "
                "requestedFactor=%.3f appliedFactor=%.3f inputDT=%.9g appliedDT=%.9g "
                "before=(%.6f %.6f %.6f) applied=(%.6f %.6f %.6f) "
                "waypoints=(0x%08X 0x%08X 0x%08X) owner=%p hookHits=%u scaledHits=%u\n",
                t.family, t.model, t.personal, t.path, g_R2RNego10RateMode, current.phase, pathReady ? "YES" : "NO", moving ? "YES" : "NO",
                validVector ? "YES" : "NO", validDT ? "YES" : "NO", modified ? "YES" : "NO",
                factor, modified ? factor : 1.0f, static_cast<double>(dt), static_cast<double>(dt),
                before.x, before.y, before.z, applied.x, applied.y, applied.z,
                current.waypoints[0], current.waypoints[1], current.waypoints[2], static_cast<void*>(object), e->hookHits, e->scaledHits);
            fclose(f); ++e->hookLogs;
        }
    }
    e->loggedMode = g_R2RNego10RateMode; e->loggedPhase = current.phase; e->loggedMoving = status;
    return modified;
}
static void R2R_Nego10PathEndMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    const MTH3D_tdstVector& original, const MTH3D_tdstVector& applied)
{
    R2R_Nego10PathEntry current = {}; MTH3D_tdstVector after = {};
    if (R2R_Nego10PathLiveMechanics(object, dynamics, current) == nullptr ||
        !R2R_Nego10MovementRead(&dynamics->stDynamicsBase.stImposeSpeed, after) ||
        after.x != applied.x || after.y != applied.y || after.z != applied.z ||
        !R2R_Nego10PathWritable(&dynamics->stDynamicsBase.stImposeSpeed, sizeof(original))) return;
    // Restore only our own temporary command, preserving native stops/new commands.
    std::memcpy(&dynamics->stDynamicsBase.stImposeSpeed, &original, sizeof(original));
}

// v0.0.18x.0: two supplied Water_10 graph commands and three exact crab waypoint commands; read-only DSG, bounded delayed capture.
static const char* R2R_WATER10_MOVEMENT_REPORT = "Rayman2Randomizer_Water10Movement.txt";
static bool g_R2RWater10MovementReportStarted = false;
template<class T> static bool R2R_Water10MovementRead(const T* source, T& destination)
{
    return source != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(source), sizeof(T)) &&
        SafeReadMemory(source, &destination, sizeof(T));
}
static bool R2R_Water10MovePlaying()
{
    return GAM_g_stEngineStructure != nullptr &&
        GAM_g_stEngineStructure->eEngineMode == E_EM_ModePlaying &&
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Water_10") == 0 &&
        GAM_g_p_stDynamicWorld != nullptr && *GAM_g_p_stDynamicWorld != nullptr;
}
static float R2R_Water10MoveFactor()
{
    return R2R_StatsLegacyFactorForLevel(g_R2RWater10RateMode, "Water_10", 0x110u);
}
static bool R2R_Water10MoveStartReport()
{
    if (g_R2RWater10MovementReportStarted) return true;
    FILE* f = nullptr; fopen_s(&f, R2R_WATER10_MOVEMENT_REPORT, "w");
    if (f == nullptr) return false;
    fprintf(f, "%s WATER_10 TWO NAMED PATHS AND THREE CRAB COMMAND TESTS\n"
        "Exact ALW_Rayseau1 / DS1_chasse_d_eau and DOT_NiaGnak / DOT_Niak.\n"
        "Three exact DS1_MIC_Krab_I1/I2/I3 use displayed isolated WayPoint_0/1/3; no Graph is invented.\n"
        "Full supplied DSG types and native offsets verified; no Float/Int/Boolean speed or timer role presumed.\n"
        "Named paths require the exact readable Graph name; all five targets require one readable finite displayed WayPoint.\n"
        "Full selective export validation: movement is fully native; isolated waypoints are command staging, not speed stats.\n"
        "List_46 is opaque: only its bounded four-byte header is read; no pointer/list contents are traversed.\n"
        "No comport number or arrival radius is invented. Test native arrivals in game.\n"
        "Native momentum in F6/F7/F8 for every Water_10 target; main player excluded.\n"
        "Only five identities captured after 120 ticks, <=64 nodes/frame total, even without dynamics.\n"
        "A direct script trajectory without a mechanics command needs its native capture for diagnosis.\n"
        "Global Stats controls drive MIN/MAX/RANDOM/NATIVE for this validated route. Hook=%s.\n", VERSION,
        g_R2RMovementHookInstalled ? "YES" : "NO");
    fclose(f); g_R2RWater10MovementReportStarted = true; return true;
}
static int R2R_Water10MovementPhase(const AI_tdstMind& mind, unsigned long expectedCount)
{
    AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr; AI_tdstScriptAI s = {};
    if (!R2R_Water10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Water10MovementRead(intel.pp_stScriptAI, script) ||
        !R2R_Water10MovementRead(script, s) || s.a_stComport == nullptr ||
        s.ulNbComport == 0 || s.ulNbComport > 64 ||
        (expectedCount != 0 && s.ulNbComport != expectedCount)) return -1;
    const uintptr_t first = reinterpret_cast<uintptr_t>(s.a_stComport);
    const uintptr_t current = reinterpret_cast<uintptr_t>(intel.p_stCurrentComport);
    const size_t span = sizeof(AI_tdstComport) * s.ulNbComport;
    if (current < first || current - first >= span || (current - first) % sizeof(AI_tdstComport) != 0 ||
        !R2R_AddressReadable(current, sizeof(AI_tdstComport))) return -1;
    return static_cast<int>((current - first) / sizeof(AI_tdstComport));
}

