static int R2R_Rodeo10MovementPhase(const AI_tdstMind& mind, unsigned long expectedCount)
{
    AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr; AI_tdstScriptAI s = {};
    if (!R2R_Rodeo10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Rodeo10MovementRead(intel.pp_stScriptAI, script) ||
        !R2R_Rodeo10MovementRead(script, s) || s.a_stComport == nullptr ||
        s.ulNbComport == 0 || s.ulNbComport > 64 ||
        (expectedCount != 0 && s.ulNbComport != expectedCount)) return -1;
    const uintptr_t first = reinterpret_cast<uintptr_t>(s.a_stComport);
    const uintptr_t current = reinterpret_cast<uintptr_t>(intel.p_stCurrentComport);
    const size_t span = sizeof(AI_tdstComport) * s.ulNbComport;
    if (current < first || current - first >= span || (current - first) % sizeof(AI_tdstComport) != 0 ||
        !R2R_AddressReadable(current, sizeof(AI_tdstComport))) return -1;
    return static_cast<int>((current - first) / sizeof(AI_tdstComport));
}

