static int R2R_Rodeo40PathTargetIndex(int rateTarget)
{
    for (unsigned int i = 0; i < R2R_RODEO40_PATH_TARGET_COUNT; ++i)
        if (rateTarget >= 0 && static_cast<unsigned int>(rateTarget) == g_R2RRodeo40PathTargets[i].rateTarget)
            return static_cast<int>(i);
    return -1;
}
