template<class T> static bool R2R_Rodeo60MovementRead(const T* source, T& destination)
{
    return source != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(source), sizeof(T)) &&
        SafeReadMemory(source, &destination, sizeof(T));
}
