static int R2R_Rodeo60PathTargetIndex(int rateTarget)
{
    for (unsigned int i = 0; i < R2R_RODEO60_PATH_TARGET_COUNT; ++i)
        if (rateTarget >= 0 && static_cast<unsigned int>(rateTarget) == g_R2RRodeo60PathTargets[i].rateTarget)
            return static_cast<int>(i);
    return -1;
}
struct R2R_Rodeo60PathEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    DNM_tdstDynamics* dynamics;
    AI_tdstMind* mind;
    AI_tdstAIModel* model;
    AI_tdstDsgMem* memory;
    AI_tdstDsgVar* definition;
    AI_tdstScriptAI* script;
    char* buffer;
    unsigned long bytes;
    unsigned int target;
    int phase;
    uint32_t graph;
    uint32_t waypoints[10];
    unsigned int visit;
    int loggedMode;
    int loggedPhase;
    int loggedMoving;
    unsigned int hookLogs;
    unsigned int hookHits;
    unsigned int scaledHits;
    char personal[96];
};
static R2R_Rodeo60PathEntry g_R2RRodeo60PathEntries[R2R_RODEO60_PATH_MAX_ACTORS] = {};
static unsigned int g_R2RRodeo60PathVisit = 0;
static unsigned int g_R2RRodeo60PathFrame = 0;
static bool g_R2RRodeo60PathSkipLogged[R2R_RODEO60_PATH_TARGET_COUNT] = {};
static unsigned int g_R2RRodeo60PathCaptureCursor = 0;
static unsigned int R2R_Rodeo60PathWidth(unsigned int type)
{
    return type == 0 || type == 1 || type == 2 ? 1 : type == 11 ? 12 : 4;
}
static void R2R_Rodeo60PathSkip(unsigned int target, const char* reason)
{
    if (target >= R2R_RODEO60_PATH_TARGET_COUNT || g_R2RRodeo60PathSkipLogged[target] || !R2R_Rodeo60MoveStartReport()) return;
    const auto& t = g_R2RRodeo60PathTargets[target];
    FILE* f = nullptr; fopen_s(&f, R2R_RODEO60_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[RODEO60-PATH-SKIP] family=%s model=%s personal=%s path=%s reason=%s\n",
        t.family, t.model, t.personal, t.path, reason);
    fclose(f); g_R2RRodeo60PathSkipLogged[target] = true;
}
static bool R2R_Rodeo60PathLayout(unsigned int target, const AI_tdstMind& mind, AI_tdstDsgMem& memory,
    AI_tdstDsgVar*& definition, AI_tdstDsgVar& vars)
{
    if (target >= R2R_RODEO60_PATH_TARGET_COUNT) return false;
    const auto& t = g_R2RRodeo60PathTargets[target];
    AI_tdstAIModel model = {};
    if (!R2R_Rodeo60MovementRead(mind.p_stAIModel, model) ||
        !R2R_Rodeo60MovementRead(mind.p_stDsgMem, memory) ||
        !R2R_Rodeo60MovementRead(memory.pp_stDsgVar, definition) ||
        definition == nullptr || definition != model.p_stDsgVar ||
        !R2R_Rodeo60MovementRead(definition, vars) || vars.ucNbDsgVar != t.variables ||
        vars.a_stDsgVarInfo == nullptr || vars.ulBufferSize < t.minimumBytes || vars.ulBufferSize > 512 ||
        memory.p_cDsgMemBuffer == nullptr) return false;
    // The screenshot supplies the types, not the offsets. Read native offsets
    // and verify their complete spans and non-overlap instead of inventing them.
    // DSG is only read: a current buffer aliasing init/default is acceptable.
    bool occupied[512] = {};
    for (unsigned int i = 0; i < t.variables; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Rodeo60MovementRead(vars.a_stDsgVarInfo + i, info)) return false;
        const unsigned int type = static_cast<unsigned int>(info.eTypeId);
        // Accept either native signed/unsigned four-byte integer for an Int field.
        if (type != t.types[i] && !(t.types[i] == 5 && type == 6)) return false;
        const unsigned int width = R2R_Rodeo60PathWidth(type);
        if (info.ulOffsetInDsgMem >= vars.ulBufferSize ||
            width > vars.ulBufferSize - info.ulOffsetInDsgMem) return false;
        for (unsigned long j = info.ulOffsetInDsgMem; j < info.ulOffsetInDsgMem + width; ++j)
        {
            if (occupied[j]) return false; occupied[j] = true;
        }
    }
    return R2R_AddressReadable(reinterpret_cast<uintptr_t>(memory.p_cDsgMemBuffer), vars.ulBufferSize);
}
static bool R2R_Rodeo60GraphName(uint32_t reference, char* name, size_t capacity)
{
    WP_tdstGraph graph = {};
    return reference != 0 && R2R_Rodeo60MovementRead(
        reinterpret_cast<const WP_tdstGraph*>(static_cast<uintptr_t>(reference)), graph) &&
        R2R_Rodeo60CopyName(graph.m_szNameOfGraph, name, capacity);
}
static bool R2R_Rodeo60EndGraph(uint32_t reference)
{
    char name[96] = {};
    return R2R_Rodeo60GraphName(reference, name, sizeof(name)) &&
        _stricmp(name, "OLP_Chemin_Intro_Ray") == 0;
}
static bool R2R_Rodeo60PathSnapshot(HIE_tdstSuperObject* object,
    const R2R_Rodeo60Identity& identity, R2R_Rodeo60PathEntry& result)
{
    const int target = R2R_Rodeo60PathTargetIndex(identity.target);
    if (target < 0) return false;
    const auto& t = g_R2RRodeo60PathTargets[target];
    HIE_tdstEngineObject actor = {}; AI_tdstBrain brain = {}; AI_tdstMind mind = {};
    AI_tdstDsgMem memory = {}; AI_tdstDsgVar* definition = nullptr;
    AI_tdstDsgVar vars = {}; AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr;
    AI_tdstScriptAI scripts = {};
    if (!R2R_Rodeo60MovementRead(identity.actor, actor) ||
        !R2R_Rodeo60MovementRead(actor.hBrain, brain) || !R2R_Rodeo60MovementRead(brain.p_stMind, mind) ||
        !R2R_Rodeo60PathLayout(static_cast<unsigned int>(target), mind, memory, definition, vars) ||
        !R2R_Rodeo60MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Rodeo60MovementRead(intel.pp_stScriptAI, script) || !R2R_Rodeo60MovementRead(script, scripts)) return false;
    const int phase = R2R_Rodeo60MovementPhase(mind, 0);
    if (phase < 0 || (static_cast<unsigned int>(target) == R2R_RODEO60_RAY_END_TARGET && scripts.ulNbComport != 14)) return false;
    result = R2R_Rodeo60PathEntry(); result.owner = object; result.actor = identity.actor;
    // Script-driven cinematics can lack a dynamics block. Keep their exact
    // brain/DSG snapshot for diagnosis; only live mechanics can be modified.
    DNM_tdstDynam dynam = {};
    if (R2R_Rodeo60MovementRead(actor.hDynam, dynam) && dynam.p_stDynamics != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stDynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        result.dynamics = dynam.p_stDynamics;
    result.mind = brain.p_stMind; result.model = mind.p_stAIModel;
    result.memory = mind.p_stDsgMem; result.definition = definition; result.script = script;
    result.buffer = memory.p_cDsgMemBuffer; result.bytes = vars.ulBufferSize; result.phase = phase; result.target = static_cast<unsigned int>(target);
    if (t.waypointCount > 10 || (t.waypointCount == 0 && t.graphIndex == R2R_RODEO60_NO_GRAPH && !R2R_Rodeo60IsMenhir(result.target))) return false;
    if (t.graphIndex != R2R_RODEO60_NO_GRAPH)
    {
        AI_tdstDsgVarInfo graphInfo = {};
        if (t.graphIndex >= t.variables || !R2R_Rodeo60MovementRead(vars.a_stDsgVarInfo + t.graphIndex, graphInfo) ||
            static_cast<unsigned int>(graphInfo.eTypeId) != 17 ||
            !SafeReadMemory(result.buffer + graphInfo.ulOffsetInDsgMem, &result.graph, 4)) return false;
    }
    for (unsigned int i = 0; i < t.waypointCount; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (t.waypointIndices[i] >= t.variables ||
            !R2R_Rodeo60MovementRead(vars.a_stDsgVarInfo + t.waypointIndices[i], info) ||
            static_cast<unsigned int>(info.eTypeId) != 8 ||
            !SafeReadMemory(result.buffer + info.ulOffsetInDsgMem, &result.waypoints[i], 4)) return false;
    }
    if (result.target == R2R_RODEO60_RAY_END_TARGET)
    {
        char nativeModel[96] = {};
        // Full layout, script and named network are verified before any model getter.
        if (object == HIE_M_hGetMainActor() || !R2R_Rodeo60EndGraph(result.graph) ||
            !R2R_Rodeo60CopyName(R2R_Rodeo60NativeName(object, 1), nativeModel, sizeof(nativeModel)) ||
            _stricmp(nativeModel, "ARG_Rayseau") != 0) return false;
    }
    std::memcpy(result.personal, identity.personal, sizeof(result.personal));
    return true;
}
static bool R2R_Rodeo60ReadPathIdentity(HIE_tdstSuperObject* object, R2R_Rodeo60Identity& identity)
{
    if (R2R_Rodeo60ReadIdentity(object, identity))
    {
        if (identity.target != 0) return true;
    }
    else
    {
        identity = R2R_Rodeo60Identity();identity.target = -1;
        if (!R2R_Rodeo60IdentityActor(object, identity.actor) ||
            !R2R_Rodeo60CopyName(R2R_Rodeo60NativeName(object, 0), identity.family, sizeof(identity.family)) ||
            _stricmp(identity.family, "rayman") != 0) return false;
        identity.target = 0;
        std::memcpy(identity.model, "ARG_Rayseau", sizeof("ARG_Rayseau"));
        if (!R2R_Rodeo60CopyName(R2R_Rodeo60NativeName(object, 2), identity.personal, sizeof(identity.personal)))
            std::memcpy(identity.personal, "(unnamed)", sizeof("(unnamed)"));
    }
    R2R_Rodeo60PathEntry verified = {};
    return R2R_Rodeo60PathSnapshot(object, identity, verified);
}
static bool R2R_Rodeo60PathSame(const R2R_Rodeo60PathEntry& a, const R2R_Rodeo60PathEntry& b)
{
    return a.owner == b.owner && a.actor == b.actor && a.dynamics == b.dynamics && a.mind == b.mind &&
        a.model == b.model && a.memory == b.memory && a.definition == b.definition &&
        a.script == b.script && a.buffer == b.buffer && a.bytes == b.bytes && a.target == b.target && a.graph == b.graph;
}
static void R2R_Rodeo60PathProcess(HIE_tdstSuperObject* object)
{
    R2R_Rodeo60Identity identity = {}; R2R_Rodeo60PathEntry current = {};
    if (!R2R_Rodeo60ReadPathIdentity(object, identity)) return;
    const int target = R2R_Rodeo60PathTargetIndex(identity.target);
    if (target < 0) return;
    if (!R2R_Rodeo60PathSnapshot(object, identity, current))
    {
        R2R_Rodeo60PathSkip(static_cast<unsigned int>(target), "typed buffer or script unavailable"); return;
    }
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_RODEO60_PATH_MAX_ACTORS; ++i)
    {
        if (R2R_Rodeo60PathSame(g_R2RRodeo60PathEntries[i], current)) { slot = static_cast<int>(i); break; }
        if (g_R2RRodeo60PathEntries[i].owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0) { R2R_Rodeo60PathSkip(static_cast<unsigned int>(target), "tracking table full"); return; }
    R2R_Rodeo60PathEntry& e = g_R2RRodeo60PathEntries[slot];
    if (!fresh && e.visit == g_R2RRodeo60PathVisit) return;
    if (fresh)
    {
        e = current; e.loggedMode = -1; e.loggedPhase = -1; e.loggedMoving = -1;
        FILE* f = nullptr; fopen_s(&f, R2R_RODEO60_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RRodeo60PathTargets[e.target];
            fprintf(f, "[RODEO60-PATH-TRACK] family=%s model=%s personal=%s path=%s "
                "phase=%d bytes=%lu owner=%p dynamics=%p buffer=%p\n",
                t.family, t.model, t.personal, t.path, e.phase, e.bytes,
                static_cast<void*>(object), static_cast<void*>(e.dynamics), static_cast<void*>(e.buffer)); fclose(f);
        }
    }
    e.phase = current.phase; std::memcpy(e.waypoints, current.waypoints, sizeof(e.waypoints)); e.visit = g_R2RRodeo60PathVisit;
}
static unsigned int g_R2RRodeo60PathScanBudget = 0;
static void R2R_Rodeo60PathScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || g_R2RRodeo60PathScanBudget == 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    --g_R2RRodeo60PathScanBudget;
    R2R_Rodeo60PathProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (g_R2RRodeo60PathScanBudget == 0) break; if (object != nullptr) R2R_Rodeo60PathScan(object, depth + 1);
    }
}
// These scripts are not in the supplied reports. Capture six validated model groups
// in small, delayed batches so a non-mechanical trajectory can be diagnosed
// without large startup captures. Raw references stay opaque.
struct R2R_Rodeo60PathCapture
{
    AI_tdstAIModel* model;
    AI_tdstScriptAI* script;
    unsigned int comport;
    unsigned int rule;
    unsigned int node;
    unsigned int total;
    bool started;
    bool complete;
};
static R2R_Rodeo60PathCapture g_R2RRodeo60PathCaptures[R2R_RODEO60_PATH_CAPTURE_COUNT] = {};
static void R2R_Rodeo60PathCaptureStep(const R2R_Rodeo60PathEntry& e)
{
    if (e.target >= R2R_RODEO60_PATH_TARGET_COUNT) return;
    const unsigned int captureIndex = R2R_Rodeo60PathCaptureIndex(e.target);
    if (g_R2RRodeo60PathFrame < 120 || g_R2RRodeo60PathCaptures[captureIndex].complete) return;
    const auto& t = g_R2RRodeo60PathTargets[e.target];
    R2R_Rodeo60Identity identity = {}; R2R_Rodeo60PathEntry current = {};
    AI_tdstScriptAI script = {}; AI_tdstDsgVar vars = {};
    if (!R2R_Rodeo60ReadPathIdentity(e.owner, identity) || !R2R_Rodeo60PathSnapshot(e.owner, identity, current) ||
        !R2R_Rodeo60PathSame(e, current) || !R2R_Rodeo60MovementRead(e.script, script) ||
        !R2R_Rodeo60MovementRead(e.definition, vars)) return;
    if (script.ulNbComport == 0 || script.ulNbComport > 64 || script.a_stComport == nullptr) return;
    auto& capture = g_R2RRodeo60PathCaptures[captureIndex];
    if (capture.started && (capture.model != e.model || capture.script != e.script)) return;
    FILE* f = nullptr; fopen_s(&f, R2R_RODEO60_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    if (!capture.started)
    {
        capture.model = e.model; capture.script = e.script; capture.started = true;
        fprintf(f, "[RODEO60-PATH-AI-CAPTURE] target=%u family=%s model=%s personal=%s path=%s comports=%lu "
            "variables=%u bytes=%lu budgetPerFrame=64 totalBudget=8192 modelPtr=%p script=%p\n",
            e.target, t.family, t.model, t.personal, t.path, script.ulNbComport, static_cast<unsigned int>(vars.ucNbDsgVar), vars.ulBufferSize,
            static_cast<void*>(e.model), static_cast<void*>(e.script));
        for (unsigned int i = 0; i < t.variables; ++i)
        {
            AI_tdstDsgVarInfo info = {}; uint32_t raw = 0;
            if (!R2R_Rodeo60MovementRead(vars.a_stDsgVarInfo + i, info)) break;
            const unsigned int type = static_cast<unsigned int>(info.eTypeId);
            const unsigned int width = R2R_Rodeo60PathWidth(type);
            if (!SafeReadMemory(e.buffer + info.ulOffsetInDsgMem, &raw, width == 1 ? 1 : 4)) break;
            fprintf(f, "[RODEO60-PATH-DSG] target=%u var=%u type=%u offset=%lu raw=0x%08X", e.target, i, type, info.ulOffsetInDsgMem, raw);
            if (type == 7) { float value = 0; std::memcpy(&value, &raw, 4); fprintf(f, " float=%.9g", value); }
            fprintf(f, "\n");
        }
    }
    unsigned int budget = 64;
    while (budget && capture.comport < script.ulNbComport && capture.total < 8192)
    {
        AI_tdstComport comport = {};
        if (!R2R_Rodeo60MovementRead(script.a_stComport + capture.comport, comport) || comport.ucNbRules > 64)
        {
            fprintf(f, "[RODEO60-PATH-AI-UNAVAILABLE] target=%u comport=%u\n", e.target, capture.comport); ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        const bool schedule = capture.rule == comport.ucNbRules;
        if (capture.rule > comport.ucNbRules || (schedule && comport.p_stSchedule == nullptr))
        {
            ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        AI_tdstTreeInterpret* tree = schedule ? comport.p_stSchedule : comport.a_stRules == nullptr ?
            nullptr : comport.a_stRules + capture.rule;
        AI_tdstTreeInterpret rule = {}; AI_tdstNodeInterpret node = {};
        if (capture.node >= 512 || !R2R_Rodeo60MovementRead(tree, rule) || rule.p_stNodeInterpret == nullptr ||
            !R2R_Rodeo60MovementRead(rule.p_stNodeInterpret + capture.node, node))
        {
            fprintf(f, "[RODEO60-PATH-AI-UNAVAILABLE] target=%u comport=%u rule=%u schedule=%u node=%u\n",
                e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node); ++capture.rule; capture.node = 0; --budget; continue;
        }
        fprintf(f, "[RODEO60-PATH-AI-NODE] target=%u comport=%u rule=%u schedule=%u node=%u type=%u depth=%u "
            "skip=%u raw=0x%08X\n", e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node,
            static_cast<unsigned int>(node.eType), static_cast<unsigned int>(node.ucDepth),
            static_cast<unsigned int>(node.uwNodeToSkip), static_cast<unsigned int>(reinterpret_cast<uintptr_t>(node.uParam.pvValue)));
        ++capture.node; ++capture.total; --budget;
        if (static_cast<unsigned int>(node.eType) == 8) { ++capture.rule; capture.node = 0; }
    }
    if (capture.comport >= script.ulNbComport || capture.total >= 8192)
    {
        fprintf(f, "[RODEO60-PATH-AI-CAPTURE-END] target=%u nodes=%u complete=%s\n", e.target, capture.total,
            capture.comport >= script.ulNbComport ? "YES" : "BUDGET_LIMIT"); capture.complete = true;
    }
    fclose(f);
}
static void R2R_Rodeo60PathForgetWorld()
{
    std::memset(g_R2RRodeo60PathEntries, 0, sizeof(g_R2RRodeo60PathEntries));
    std::memset(g_R2RRodeo60PathCaptures, 0, sizeof(g_R2RRodeo60PathCaptures));
    std::memset(g_R2RRodeo60PathSkipLogged, 0, sizeof(g_R2RRodeo60PathSkipLogged));
    g_R2RRodeo60PathFrame = 0;g_R2RRodeo60PathCaptureCursor = 0;
}
static void R2R_Rodeo60PathControlTick()
{
    if (!R2R_Rodeo60MovePlaying())
    {
        R2R_Rodeo60PathForgetWorld();
        return;
    }

    // v.0: direct DSG fields own validated gameplay stats.
    // No delayed path capture or broad live-command scaling remains.
    R2R_Rodeo60PathForgetWorld();
    R2R_Rodeo60MoveStartReport();
}

static bool R2R_Rodeo60PathWritable(const void* address, size_t length)
{
    if (address == nullptr || length == 0) return false;
    MEMORY_BASIC_INFORMATION info = {};
    if (VirtualQuery(address, &info, sizeof(info)) == 0 || info.State != MEM_COMMIT ||
        (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const DWORD p = info.Protect & 0xff;
    if (p != PAGE_READWRITE && p != PAGE_WRITECOPY &&
        p != PAGE_EXECUTE_READWRITE && p != PAGE_EXECUTE_WRITECOPY) return false;
    const uintptr_t start = reinterpret_cast<uintptr_t>(address);
    const uintptr_t base = reinterpret_cast<uintptr_t>(info.BaseAddress);
    return start >= base && start - base < info.RegionSize &&
        length <= info.RegionSize - (start - base) && R2R_AddressReadable(start, length);
}
static R2R_Rodeo60PathEntry* R2R_Rodeo60PathLiveMechanics(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, R2R_Rodeo60PathEntry& current)
{
    if (!R2R_Rodeo60MovePlaying() || object == nullptr || object == HIE_M_hGetMainActor() ||
        dynamics == nullptr) return nullptr;
    for (auto& e : g_R2RRodeo60PathEntries)
    {
        if (e.owner != object || e.dynamics != dynamics || e.visit != g_R2RRodeo60PathVisit) continue;
        R2R_Rodeo60Identity identity = {};
        if (!R2R_Rodeo60ReadPathIdentity(object, identity) ||
            !R2R_Rodeo60PathSnapshot(object, identity, current) || !R2R_Rodeo60PathSame(e, current)) return nullptr;
        return &e;
    }
    return nullptr;
}
static bool R2R_Rodeo60PathReady(const R2R_Rodeo60PathEntry& current)
{
    if (current.target >= R2R_RODEO60_PATH_TARGET_COUNT) return false;
    const auto& t = g_R2RRodeo60PathTargets[current.target];
    // These exact eight-field menhir schemas have no graph or waypoint.
    // Modify only their finite live imposed command, never invent a DSG speed role.
    if (R2R_Rodeo60IsMenhir(current.target)) return true;
    if (current.target == R2R_RODEO60_RAY_END_TARGET)
    {
        if (!R2R_Rodeo60EndGraph(current.graph)) return false;
    }
    else if (t.graphIndex != R2R_RODEO60_NO_GRAPH)
    {
        char name[96] = {};
        if (!R2R_Rodeo60GraphName(current.graph, name, sizeof(name)) || _stricmp(name, t.path) != 0) return false;
        // The controlled obus can issue a command without a WP reference.
        if (current.target == 0) return true;
    }
    for (unsigned int i = 0;i < t.waypointCount;++i)
    {
        WP_tdstWayPoint point = {};
        if (current.waypoints[i] != 0 && R2R_Rodeo60MovementRead(
            reinterpret_cast<const WP_tdstWayPoint*>(static_cast<uintptr_t>(current.waypoints[i])), point) &&
            std::isfinite(point.m_stVertex.x) && std::isfinite(point.m_stVertex.y) && std::isfinite(point.m_stVertex.z)) return true;
    }
    return false;
}
