// and swimming, and ProposeSpeedXYZ for another network mode. Scale only this
// call's mechanics time so all native motion routes keep their own vectors.
// Procedure meanings: byvar/raymap, AITypes_R2.cs; native script has 14 comports.
static MTH_tdxReal R2R_Rodeo60RayEndMechanicsDT(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, MTH_tdxReal dt)
{
    (void)object; (void)dynamics;
    // v.0 progression lock: keep the entire ARG_Rayseau intro network native.
    return dt;
}

// v0.0.18x.0: 18 live commands and four Uhnam controls; nine speed exclusions, native momentum.
static const char* R2R_VULCA10_MOVEMENT_REPORT = "Rayman2Randomizer_Vulca10Movement.txt";
static bool g_R2RVulca10MovementReportStarted = false;
template<class T> static bool R2R_Vulca10MovementRead(const T* source, T& destination)
{
    return source != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(source), sizeof(T)) &&
        SafeReadMemory(source, &destination, sizeof(T));
}
static bool R2R_Vulca10MovePlaying()
{
    return GAM_g_stEngineStructure != nullptr &&
        GAM_g_stEngineStructure->eEngineMode == E_EM_ModePlaying &&
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Vulca_10") == 0 &&
        GAM_g_p_stDynamicWorld != nullptr && *GAM_g_p_stDynamicWorld != nullptr;
}
static float R2R_Vulca10MoveFactor()
{
    return R2R_StatsLegacyFactorForLevel(g_R2RVulca10RateMode, "Vulca_10", 0x116u);
}
static bool R2R_Vulca10MoveStartReport()
{
    if (g_R2RVulca10MovementReportStarted) return true;
    FILE* f = nullptr; fopen_s(&f, R2R_VULCA10_MOVEMENT_REPORT, "w");
    if (f == nullptr) return false;
    fprintf(f, "%s VULCA_10 FULL-EXPORT SAFE MOVEMENT OWNERSHIP\n"
        "w.0 disables the old broad live-imposed-command scaler for Jano hands, platforms, cranes, walls and Main_PF helpers.\n"
        "Only the four exact ARG_Chenille_Reseau actors retain their previously validated phase-4 Float_2 speed controller (x0.25..x4).\n"
        "Their DS1_unham / DS1_unham02 graph, waypoint, caps, arrays and phase selectors remain native.\n"
        "All platform vectors, Rayseau travel, magic-key movement and cinematic positioning stay fully native.\n"
        "Direct audited DSG values are owned separately by Vulca10Extra. Hook=%s.\n",
        VERSION, g_R2RMovementHookInstalled ? "YES" : "NO");
    fclose(f);
    g_R2RVulca10MovementReportStarted = true;
    return true;
}

static int R2R_Vulca10MovementPhase(const AI_tdstMind& mind, unsigned long expectedCount)
{
    AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr; AI_tdstScriptAI s = {};
    if (!R2R_Vulca10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Vulca10MovementRead(intel.pp_stScriptAI, script) ||
        !R2R_Vulca10MovementRead(script, s) || s.a_stComport == nullptr ||
        s.ulNbComport == 0 || s.ulNbComport > 64 ||
        (expectedCount != 0 && s.ulNbComport != expectedCount)) return -1;
    const uintptr_t first = reinterpret_cast<uintptr_t>(s.a_stComport);
    const uintptr_t current = reinterpret_cast<uintptr_t>(intel.p_stCurrentComport);
    const size_t span = sizeof(AI_tdstComport) * s.ulNbComport;
    if (current < first || current - first >= span || (current - first) % sizeof(AI_tdstComport) != 0 ||
        !R2R_AddressReadable(current, sizeof(AI_tdstComport))) return -1;
    return static_cast<int>((current - first) / sizeof(AI_tdstComport));
}

