static int R2R_Vulca10PathTargetIndex(int rateTarget)
{
    for (unsigned int i = 0; i < R2R_VULCA10_PATH_TARGET_COUNT; ++i)
        if (rateTarget >= 0 && static_cast<unsigned int>(rateTarget) == g_R2RVulca10PathTargets[i].rateTarget)
            return static_cast<int>(i);
    return -1;
}
struct R2R_Vulca10PathEntry
{
    HIE_tdstSuperObject* owner;
    HIE_tdstEngineObject* actor;
    DNM_tdstDynamics* dynamics;
    AI_tdstMind* mind;
    AI_tdstAIModel* model;
    AI_tdstDsgMem* memory;
    AI_tdstDsgVar* definition;
    AI_tdstScriptAI* script;
    char* buffer;
    unsigned long bytes;
    unsigned int target;
    int phase;
    uint32_t graph;
    uint32_t waypoints[10];
    unsigned int visit;
    int loggedMode;
    int loggedPhase;
    int loggedMoving;
    unsigned int hookLogs;
    unsigned int hookHits;
    unsigned int scaledHits;
    char personal[96];
    unsigned long speedOffset;
    float speedOriginal, speedApplied;
    bool speedForced;
};
static R2R_Vulca10PathEntry g_R2RVulca10PathEntries[R2R_VULCA10_PATH_MAX_ACTORS] = {};
static unsigned int g_R2RVulca10PathVisit = 0;
static unsigned int g_R2RVulca10PathFrame = 0;
static bool g_R2RVulca10PathSkipLogged[R2R_VULCA10_PATH_TARGET_COUNT] = {};
static unsigned int g_R2RVulca10PathCaptureCursor = 0;
static unsigned int R2R_Vulca10PathWidth(unsigned int type)
{
    return type <= 2 ? 1 : type == 3 || type == 4 ? 2 :
        type == 11 ? 12 : type == 19 ? 368 : 4;
}
static void R2R_Vulca10PathSkip(unsigned int target, const char* reason)
{
    if (target >= R2R_VULCA10_PATH_TARGET_COUNT || g_R2RVulca10PathSkipLogged[target] || !R2R_Vulca10MoveStartReport()) return;
    const auto& t = g_R2RVulca10PathTargets[target];
    FILE* f = nullptr; fopen_s(&f, R2R_VULCA10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[VULCA10-PATH-SKIP] family=%s model=%s personal=%s path=%s reason=%s\n",
        t.family, t.model, t.personal, t.path, reason);
    fclose(f); g_R2RVulca10PathSkipLogged[target] = true;
}
static bool R2R_Vulca10PathLayout(unsigned int target, const AI_tdstMind& mind, AI_tdstDsgMem& memory,
    AI_tdstDsgVar*& definition, AI_tdstDsgVar& vars)
{
    if (target >= R2R_VULCA10_PATH_TARGET_COUNT) return false;
    const auto& t = g_R2RVulca10PathTargets[target];
    AI_tdstAIModel model = {};
    if (!R2R_Vulca10MovementRead(mind.p_stAIModel, model) ||
        !R2R_Vulca10MovementRead(mind.p_stDsgMem, memory) ||
        !R2R_Vulca10MovementRead(memory.pp_stDsgVar, definition) ||
        definition == nullptr || definition != model.p_stDsgVar ||
        !R2R_Vulca10MovementRead(definition, vars) || vars.ucNbDsgVar != t.variables ||
        vars.a_stDsgVarInfo == nullptr || vars.ulBufferSize < t.minimumBytes || vars.ulBufferSize > 512 ||
        memory.p_cDsgMemBuffer == nullptr) return false;
    // The screenshot supplies the types, not the offsets. Read native offsets
    // and verify their complete spans and non-overlap instead of inventing them.
    // DSG is only read: a current buffer aliasing init/default is acceptable.
    bool occupied[512] = {};
    for (unsigned int i = 0; i < t.variables; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Vulca10MovementRead(vars.a_stDsgVarInfo + i, info)) return false;
        const unsigned int type = static_cast<unsigned int>(info.eTypeId);
        // Accept either native signed/unsigned four-byte integer for an Int field.
        if (type != t.types[i] && !(t.types[i] == 5 && type == 6)) return false;
        const unsigned int width = R2R_Vulca10PathWidth(type);
        if (info.ulOffsetInDsgMem >= vars.ulBufferSize ||
            width > vars.ulBufferSize - info.ulOffsetInDsgMem) return false;
        for (unsigned long j = info.ulOffsetInDsgMem; j < info.ulOffsetInDsgMem + width; ++j)
        {
            if (occupied[j]) return false; occupied[j] = true;
        }
    }
    return R2R_AddressReadable(reinterpret_cast<uintptr_t>(memory.p_cDsgMemBuffer), vars.ulBufferSize);
}
static bool R2R_Vulca10GraphName(uint32_t reference, char* name, size_t capacity)
{
    WP_tdstGraph graph = {};
    return reference != 0 && R2R_Vulca10MovementRead(
        reinterpret_cast<const WP_tdstGraph*>(static_cast<uintptr_t>(reference)), graph) &&
        R2R_Vulca10CopyName(graph.m_szNameOfGraph, name, capacity);
}
static bool R2R_Vulca10PathSnapshot(HIE_tdstSuperObject* object,
    const R2R_Vulca10Identity& identity, R2R_Vulca10PathEntry& result)
{
    const int target = R2R_Vulca10PathTargetIndex(identity.target);
    if (target < 0) return false;
    const auto& t = g_R2RVulca10PathTargets[target];
    HIE_tdstEngineObject actor = {}; AI_tdstBrain brain = {}; AI_tdstMind mind = {};
    AI_tdstDsgMem memory = {}; AI_tdstDsgVar* definition = nullptr;
    AI_tdstDsgVar vars = {}; AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr;
    AI_tdstScriptAI scripts = {};
    if (!R2R_Vulca10MovementRead(identity.actor, actor) ||
        !R2R_Vulca10MovementRead(actor.hBrain, brain) || !R2R_Vulca10MovementRead(brain.p_stMind, mind) ||
        !R2R_Vulca10PathLayout(static_cast<unsigned int>(target), mind, memory, definition, vars) ||
        !R2R_Vulca10MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Vulca10MovementRead(intel.pp_stScriptAI, script) || !R2R_Vulca10MovementRead(script, scripts)) return false;
    const int phase = R2R_Vulca10MovementPhase(mind, 0);
    if (phase < 0 || (R2R_Vulca10IsUhnam(static_cast<unsigned int>(target)) && scripts.ulNbComport != 7)) return false;
    result = R2R_Vulca10PathEntry(); result.owner = object; result.actor = identity.actor;
    // Script-driven cinematics can lack a dynamics block. Keep their exact
    // brain/DSG snapshot for diagnosis; only live mechanics can be modified.
    DNM_tdstDynam dynam = {};
    if (R2R_Vulca10MovementRead(actor.hDynam, dynam) && dynam.p_stDynamics != nullptr &&
        R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stDynamics), sizeof(DNM_tdstDynamicsBaseBlock)))
        result.dynamics = dynam.p_stDynamics;
    result.mind = brain.p_stMind; result.model = mind.p_stAIModel;
    result.memory = mind.p_stDsgMem; result.definition = definition; result.script = script;
    result.buffer = memory.p_cDsgMemBuffer; result.bytes = vars.ulBufferSize; result.phase = phase; result.target = static_cast<unsigned int>(target);
    if (t.waypointCount > 10) return false;
    if (t.graphIndex != R2R_VULCA10_NO_GRAPH)
    {
        AI_tdstDsgVarInfo graphInfo = {};
        if (t.graphIndex >= t.variables || !R2R_Vulca10MovementRead(vars.a_stDsgVarInfo + t.graphIndex, graphInfo) ||
            static_cast<unsigned int>(graphInfo.eTypeId) != 17 ||
            !SafeReadMemory(result.buffer + graphInfo.ulOffsetInDsgMem, &result.graph, 4)) return false;
    }
    for (unsigned int i = 0; i < t.waypointCount; ++i)
    {
        AI_tdstDsgVarInfo info = {};
        if (t.waypointIndices[i] >= t.variables ||
            !R2R_Vulca10MovementRead(vars.a_stDsgVarInfo + t.waypointIndices[i], info) ||
            static_cast<unsigned int>(info.eTypeId) != 8 ||
            !SafeReadMemory(result.buffer + info.ulOffsetInDsgMem, &result.waypoints[i], 4)) return false;
    }
    if (R2R_Vulca10IsUhnam(result.target))
    {
        AI_tdstDsgVarInfo info = {};
        if (!R2R_Vulca10MovementRead(vars.a_stDsgVarInfo + 2, info)) return false;
        result.speedOffset = info.ulOffsetInDsgMem;
    }
    std::memcpy(result.personal, identity.personal, sizeof(result.personal));
    return true;
}
static bool R2R_Vulca10ReadPathIdentity(HIE_tdstSuperObject* object, R2R_Vulca10Identity& identity)
{
    return R2R_Vulca10ReadIdentity(object, identity) && R2R_Vulca10PathTargetIndex(identity.target) >= 0;
}
static bool R2R_Vulca10PathSame(const R2R_Vulca10PathEntry& a, const R2R_Vulca10PathEntry& b)
{
    return a.owner == b.owner && a.actor == b.actor &&
        (a.dynamics == b.dynamics || R2R_Vulca10IsUhnam(a.target)) && a.mind == b.mind &&
        a.model == b.model && a.memory == b.memory && a.definition == b.definition &&
        a.script == b.script && a.buffer == b.buffer && a.bytes == b.bytes && a.target == b.target &&
        (a.graph == b.graph || (R2R_Vulca10IsUhnam(a.target) && a.speedOffset == b.speedOffset));
}
static bool R2R_Vulca10PathWritable(const void*, size_t);
static bool R2R_Vulca10PathReady(const R2R_Vulca10PathEntry&);
static bool R2R_Vulca10UhnamPrivate(const R2R_Vulca10PathEntry& e)
{
    AI_tdstDsgMem memory = {};AI_tdstDsgVar vars = {};
    return R2R_Vulca10MovementRead(e.memory, memory) && R2R_Vulca10MovementRead(e.definition, vars) &&
        e.buffer != memory.p_cDsgMemBufferInit && e.buffer != vars.p_cDsgMemDefaultInit;
}
static void R2R_Vulca10UhnamRestore(R2R_Vulca10PathEntry& e)
{
    if (!e.owner || !e.speedForced || !R2R_Vulca10IsUhnam(e.target)) return;
    R2R_Vulca10Identity identity = {};R2R_Vulca10PathEntry current = {};float before = 0;
    if (!R2R_Vulca10ReadPathIdentity(e.owner, identity) || !R2R_Vulca10PathSnapshot(e.owner, identity, current) ||
        !R2R_Vulca10PathSame(e, current) || !R2R_Vulca10UhnamPrivate(current) ||
        !SafeReadMemory(current.buffer + current.speedOffset, &before, sizeof(before)) || before != e.speedApplied ||
        !R2R_Vulca10PathWritable(current.buffer + current.speedOffset, sizeof(float))) return;
    std::memcpy(current.buffer + current.speedOffset, &e.speedOriginal, sizeof(float));e.speedForced = false;
}
static void R2R_Vulca10UhnamControl(R2R_Vulca10PathEntry& e, const R2R_Vulca10PathEntry& current)
{
    if (!R2R_Vulca10IsUhnam(e.target) || !R2R_Vulca10UhnamPrivate(current)) return;
    float before = 0;
    if (!SafeReadMemory(current.buffer + current.speedOffset, &before, sizeof(before)) ||
        !std::isfinite(before) || before < 0 || before>1000 ||
        !R2R_Vulca10PathWritable(current.buffer + current.speedOffset, sizeof(float))) return;
    // Preserve a new engine command, including zero, rather than restoring over it.
    if (e.speedForced && before != e.speedApplied) e.speedForced = false;
    if (!e.speedForced) e.speedOriginal = before;
    const bool travel = current.phase == 4 && R2R_Vulca10PathReady(current);
    const float factor = R2R_Vulca10MoveFactor();float applied = before;
    if (!travel || factor == 1)
    {
        if (e.speedForced && before == e.speedApplied) applied = e.speedOriginal;
        e.speedForced = false;
    }
    else if (e.speedOriginal > 0 && e.speedOriginal <= 250)
    {
        applied = e.speedOriginal * factor;
        if (!std::isfinite(applied) || applied <= 0 || applied > 1000) return;
        e.speedForced = true;
    }
    if (applied != before) std::memcpy(current.buffer + current.speedOffset, &applied, sizeof(applied));
    if (e.loggedMode != g_R2RVulca10RateMode || e.loggedPhase != current.phase || applied != before)
    {
        FILE* f = nullptr;fopen_s(&f, R2R_VULCA10_MOVEMENT_REPORT, "a");
        if (f)
        {
            fprintf(f, "[VULCA10-UHNAM-SPEED] personal=%s path=%s mode=%d phase=%d travel=%s "
                "original=%.9g before=%.9g applied=%.9g factor=%.3f variableIndex=2 byteOffset=%lu owner=%p\n",
                e.personal, g_R2RVulca10PathTargets[e.target].path, g_R2RVulca10RateMode, current.phase, travel ? "YES" : "NO",
                e.speedOriginal, before, applied, factor, current.speedOffset, static_cast<void*>(e.owner));fclose(f);
        }
    }
    e.speedApplied = applied;e.loggedMode = g_R2RVulca10RateMode;e.loggedPhase = current.phase;
}

static void R2R_Vulca10PathProcess(HIE_tdstSuperObject* object)
{
    R2R_Vulca10Identity identity = {}; R2R_Vulca10PathEntry current = {};
    if (!R2R_Vulca10ReadPathIdentity(object, identity)) return;
    const int target = R2R_Vulca10PathTargetIndex(identity.target);
    if (target < 0) return;
    // w.0: all non-Uhnam movement is owned by native scripts or Vulca10Extra.
    if (!R2R_Vulca10IsUhnam(static_cast<unsigned int>(target))) return;
    if (!R2R_Vulca10PathSnapshot(object, identity, current))
    {
        // Preserve the scalar baseline through a transient unreadable layout.
        for (auto& e : g_R2RVulca10PathEntries)
            if (e.owner == object && e.actor == identity.actor && e.target == static_cast<unsigned int>(target))
                e.visit = g_R2RVulca10PathVisit;
        R2R_Vulca10PathSkip(static_cast<unsigned int>(target), "typed buffer or script unavailable");return;
    }
    int slot = -1, freeSlot = -1;
    for (unsigned int i = 0; i < R2R_VULCA10_PATH_MAX_ACTORS; ++i)
    {
        if (R2R_Vulca10PathSame(g_R2RVulca10PathEntries[i], current)) { slot = static_cast<int>(i); break; }
        if (g_R2RVulca10PathEntries[i].owner == nullptr && freeSlot < 0) freeSlot = static_cast<int>(i);
    }
    const bool fresh = slot < 0;
    if (fresh) slot = freeSlot;
    if (slot < 0) { R2R_Vulca10PathSkip(static_cast<unsigned int>(target), "tracking table full"); return; }
    R2R_Vulca10PathEntry& e = g_R2RVulca10PathEntries[slot];
    if (!fresh && e.visit == g_R2RVulca10PathVisit) return;
    if (fresh)
    {
        e = current; e.loggedMode = -1; e.loggedPhase = -1; e.loggedMoving = -1;
        FILE* f = nullptr; fopen_s(&f, R2R_VULCA10_MOVEMENT_REPORT, "a");
        if (f != nullptr)
        {
            const auto& t = g_R2RVulca10PathTargets[e.target];
            fprintf(f, "[VULCA10-PATH-TRACK] family=%s model=%s personal=%s path=%s "
                "phase=%d bytes=%lu owner=%p dynamics=%p buffer=%p\n",
                t.family, t.model, t.personal, t.path, e.phase, e.bytes,
                static_cast<void*>(object), static_cast<void*>(e.dynamics), static_cast<void*>(e.buffer)); fclose(f);
        }
    }
    e.phase = current.phase;e.graph = current.graph;e.dynamics = current.dynamics;
    std::memcpy(e.waypoints, current.waypoints, sizeof(e.waypoints)); e.visit = g_R2RVulca10PathVisit;
    R2R_Vulca10UhnamControl(e, current);
}
static unsigned int g_R2RVulca10PathScanBudget = 0;
static void R2R_Vulca10PathScan(HIE_tdstSuperObject* root, int depth)
{
    if (root == nullptr || depth > 64 || g_R2RVulca10PathScanBudget == 0 ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(HIE_tdstSuperObject))) return;
    --g_R2RVulca10PathScanBudget;
    R2R_Vulca10PathProcess(root);
    HIE_tdstSuperObject* object = nullptr;
    LST_M_DynamicForEach(root, object)
    {
        if (g_R2RVulca10PathScanBudget == 0) break; if (object != nullptr) R2R_Vulca10PathScan(object, depth + 1);
    }
}
// These scripts are not in the supplied reports. Capture eight validated model groups
// in small, delayed batches so a non-mechanical trajectory can be diagnosed
// without large startup captures. Raw references stay opaque.
struct R2R_Vulca10PathCapture
{
    AI_tdstAIModel* model;
    AI_tdstScriptAI* script;
    unsigned int comport;
    unsigned int rule;
    unsigned int node;
    unsigned int total;
    bool started;
    bool complete;
};
static R2R_Vulca10PathCapture g_R2RVulca10PathCaptures[R2R_VULCA10_PATH_CAPTURE_COUNT] = {};
static void R2R_Vulca10PathCaptureStep(const R2R_Vulca10PathEntry& e)
{
    if (e.target >= R2R_VULCA10_PATH_TARGET_COUNT) return;
    const unsigned int captureIndex = R2R_Vulca10PathCaptureIndex(e.target);
    if (g_R2RVulca10PathFrame < 120 || g_R2RVulca10PathCaptures[captureIndex].complete) return;
    const auto& t = g_R2RVulca10PathTargets[e.target];
    R2R_Vulca10Identity identity = {}; R2R_Vulca10PathEntry current = {};
    AI_tdstScriptAI script = {}; AI_tdstDsgVar vars = {};
    if (!R2R_Vulca10ReadPathIdentity(e.owner, identity) || !R2R_Vulca10PathSnapshot(e.owner, identity, current) ||
        !R2R_Vulca10PathSame(e, current) || !R2R_Vulca10MovementRead(e.script, script) ||
        !R2R_Vulca10MovementRead(e.definition, vars)) return;
    if (script.ulNbComport == 0 || script.ulNbComport > 64 || script.a_stComport == nullptr) return;
    auto& capture = g_R2RVulca10PathCaptures[captureIndex];
    if (capture.started && (capture.model != e.model || capture.script != e.script)) return;
    FILE* f = nullptr; fopen_s(&f, R2R_VULCA10_MOVEMENT_REPORT, "a");
    if (f == nullptr) return;
    if (!capture.started)
    {
        capture.model = e.model; capture.script = e.script; capture.started = true;
        fprintf(f, "[VULCA10-PATH-AI-CAPTURE] target=%u family=%s model=%s personal=%s path=%s comports=%lu "
            "variables=%u bytes=%lu budgetPerFrame=64 totalBudget=8192 modelPtr=%p script=%p\n",
            e.target, t.family, t.model, t.personal, t.path, script.ulNbComport, static_cast<unsigned int>(vars.ucNbDsgVar), vars.ulBufferSize,
            static_cast<void*>(e.model), static_cast<void*>(e.script));
        for (unsigned int i = 0; i < t.variables; ++i)
        {
            AI_tdstDsgVarInfo info = {}; uint32_t raw = 0;
            if (!R2R_Vulca10MovementRead(vars.a_stDsgVarInfo + i, info)) break;
            const unsigned int type = static_cast<unsigned int>(info.eTypeId);
            const unsigned int width = R2R_Vulca10PathWidth(type);
            if (!SafeReadMemory(e.buffer + info.ulOffsetInDsgMem, &raw, width < 4 ? width : 4)) break;
            fprintf(f, "[VULCA10-PATH-DSG] target=%u var=%u type=%u offset=%lu raw=0x%08X", e.target, i, type, info.ulOffsetInDsgMem, raw);
            if (type == 7) { float value = 0; std::memcpy(&value, &raw, 4); fprintf(f, " float=%.9g", value); }
            fprintf(f, "\n");
        }
    }
    unsigned int budget = 64;
    while (budget && capture.comport < script.ulNbComport && capture.total < 8192)
    {
        AI_tdstComport comport = {};
        if (!R2R_Vulca10MovementRead(script.a_stComport + capture.comport, comport) || comport.ucNbRules > 64)
        {
            fprintf(f, "[VULCA10-PATH-AI-UNAVAILABLE] target=%u comport=%u\n", e.target, capture.comport); ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        const bool schedule = capture.rule == comport.ucNbRules;
        if (capture.rule > comport.ucNbRules || (schedule && comport.p_stSchedule == nullptr))
        {
            ++capture.comport; capture.rule = 0; capture.node = 0; --budget; continue;
        }
        AI_tdstTreeInterpret* tree = schedule ? comport.p_stSchedule : comport.a_stRules == nullptr ?
            nullptr : comport.a_stRules + capture.rule;
        AI_tdstTreeInterpret rule = {}; AI_tdstNodeInterpret node = {};
        if (capture.node >= 512 || !R2R_Vulca10MovementRead(tree, rule) || rule.p_stNodeInterpret == nullptr ||
            !R2R_Vulca10MovementRead(rule.p_stNodeInterpret + capture.node, node))
        {
            fprintf(f, "[VULCA10-PATH-AI-UNAVAILABLE] target=%u comport=%u rule=%u schedule=%u node=%u\n",
                e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node); ++capture.rule; capture.node = 0; --budget; continue;
        }
        fprintf(f, "[VULCA10-PATH-AI-NODE] target=%u comport=%u rule=%u schedule=%u node=%u type=%u depth=%u "
            "skip=%u raw=0x%08X\n", e.target, capture.comport, capture.rule, schedule ? 1 : 0, capture.node,
            static_cast<unsigned int>(node.eType), static_cast<unsigned int>(node.ucDepth),
            static_cast<unsigned int>(node.uwNodeToSkip), static_cast<unsigned int>(reinterpret_cast<uintptr_t>(node.uParam.pvValue)));
        ++capture.node; ++capture.total; --budget;
        if (static_cast<unsigned int>(node.eType) == 8) { ++capture.rule; capture.node = 0; }
    }
    if (capture.comport >= script.ulNbComport || capture.total >= 8192)
    {
        fprintf(f, "[VULCA10-PATH-AI-CAPTURE-END] target=%u nodes=%u complete=%s\n", e.target, capture.total,
            capture.comport >= script.ulNbComport ? "YES" : "BUDGET_LIMIT"); capture.complete = true;
    }
    fclose(f);
}
static void R2R_Vulca10PathForgetWorld()
{
    for (auto& e : g_R2RVulca10PathEntries)R2R_Vulca10UhnamRestore(e);
    std::memset(g_R2RVulca10PathEntries, 0, sizeof(g_R2RVulca10PathEntries));
    std::memset(g_R2RVulca10PathCaptures, 0, sizeof(g_R2RVulca10PathCaptures));
    std::memset(g_R2RVulca10PathSkipLogged, 0, sizeof(g_R2RVulca10PathSkipLogged));
    g_R2RVulca10PathFrame = 0;g_R2RVulca10PathCaptureCursor = 0;
}
static void R2R_Vulca10PathControlTick()
{
    if (!R2R_Vulca10MovePlaying()) { R2R_Vulca10PathForgetWorld(); return; }
    R2R_Vulca10MoveStartReport(); ++g_R2RVulca10PathVisit; ++g_R2RVulca10PathFrame;
    g_R2RVulca10PathScanBudget = 4096;
    HIE_tdstSuperObject* active = *GAM_g_p_stDynamicWorld;
    HIE_tdstSuperObject* inactive = GAM_g_p_stInactiveDynamicWorld != nullptr ? *GAM_g_p_stInactiveDynamicWorld : nullptr;
    R2R_Vulca10PathScan(active, 0); if (inactive != active)R2R_Vulca10PathScan(inactive, 0);
    for (auto& e : g_R2RVulca10PathEntries)
        if (e.visit != g_R2RVulca10PathVisit)
        {
            R2R_Vulca10UhnamRestore(e);e = R2R_Vulca10PathEntry();
        }
    // Only one capture step in the entire tick: 22 identities / eight model captures share <=64 nodes/frame.
    for (unsigned int attempt = 0;attempt < R2R_VULCA10_PATH_TARGET_COUNT;++attempt)
    {
        const unsigned int target = (g_R2RVulca10PathCaptureCursor + attempt) % R2R_VULCA10_PATH_TARGET_COUNT;
        const auto& capture = g_R2RVulca10PathCaptures[R2R_Vulca10PathCaptureIndex(target)];
        if (capture.complete)continue;
        for (const auto& e : g_R2RVulca10PathEntries)
        {
            if (e.owner == nullptr || e.target != target || (capture.started &&
                (e.model != capture.model || e.script != capture.script)))continue;
            R2R_Vulca10PathCaptureStep(e);g_R2RVulca10PathCaptureCursor = (target + 1) % R2R_VULCA10_PATH_TARGET_COUNT;return;
        }
    }
}

static bool R2R_Vulca10PathWritable(const void* address, size_t length)
{
    if (address == nullptr || length == 0) return false;
    MEMORY_BASIC_INFORMATION info = {};
    if (VirtualQuery(address, &info, sizeof(info)) == 0 || info.State != MEM_COMMIT ||
        (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const DWORD p = info.Protect & 0xff;
    if (p != PAGE_READWRITE && p != PAGE_WRITECOPY &&
        p != PAGE_EXECUTE_READWRITE && p != PAGE_EXECUTE_WRITECOPY) return false;
    const uintptr_t start = reinterpret_cast<uintptr_t>(address);
    const uintptr_t base = reinterpret_cast<uintptr_t>(info.BaseAddress);
    return start >= base && start - base < info.RegionSize &&
        length <= info.RegionSize - (start - base) && R2R_AddressReadable(start, length);
}
static R2R_Vulca10PathEntry* R2R_Vulca10PathLiveMechanics(HIE_tdstSuperObject* object,
    DNM_tdstDynamics* dynamics, R2R_Vulca10PathEntry& current)
{
    if (!R2R_Vulca10MovePlaying() || object == nullptr || object == HIE_M_hGetMainActor() ||
        dynamics == nullptr) return nullptr;
    for (auto& e : g_R2RVulca10PathEntries)
    {
        if (e.owner != object || e.dynamics != dynamics || e.visit != g_R2RVulca10PathVisit) continue;
        R2R_Vulca10Identity identity = {};
        if (!R2R_Vulca10ReadPathIdentity(object, identity) ||
            !R2R_Vulca10PathSnapshot(object, identity, current) || !R2R_Vulca10PathSame(e, current)) return nullptr;
        return &e;
    }
    return nullptr;
}
static bool R2R_Vulca10PathReady(const R2R_Vulca10PathEntry& current)
{
    if (current.target >= R2R_VULCA10_PATH_TARGET_COUNT) return false;
    const auto& t = g_R2RVulca10PathTargets[current.target];
    if (t.graphIndex != R2R_VULCA10_NO_GRAPH)
    {
        char name[96] = {};
        if (!R2R_Vulca10GraphName(current.graph, name, sizeof(name)) || _stricmp(name, t.path) != 0) return false;
        // Float_2 is the proven forward command for the seven-comport Uhnam.
        // It does not need a nonempty point slot before the native AI updates it.
        if (R2R_Vulca10IsUhnam(current.target))return true;
    }
    else if (t.waypointCount == 0)return true;
    for (unsigned int i = 0;i < t.waypointCount;++i)
    {
        WP_tdstWayPoint point = {};
        if (current.waypoints[i] != 0 && R2R_Vulca10MovementRead(
            reinterpret_cast<const WP_tdstWayPoint*>(static_cast<uintptr_t>(current.waypoints[i])), point) &&
            std::isfinite(point.m_stVertex.x) && std::isfinite(point.m_stVertex.y) && std::isfinite(point.m_stVertex.z)) return true;
    }
    return false;
}
static bool R2R_Vulca10PathBeginMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    MTH_tdxReal dt, MTH3D_tdstVector& original, MTH3D_tdstVector& applied)
{
    (void)object; (void)dynamics; (void)dt; (void)original; (void)applied;
    // w.0: broad live mechanics scaling disabled; Uhnam speed is handled
    // by its validated private Float_2 controller in R2R_Vulca10UhnamControl.
    return false;
}

static void R2R_Vulca10PathEndMechanics(HIE_tdstSuperObject* object, DNM_tdstDynamics* dynamics,
    const MTH3D_tdstVector& original, const MTH3D_tdstVector& applied)
{
    (void)object; (void)dynamics; (void)original; (void)applied;
}

// v0.0.18x.0: seven exact Vulca_20 live-command controllers; native momentum and read-only DSG.
static const char* R2R_VULCA20_MOVEMENT_REPORT = "Rayman2Randomizer_Vulca20Movement.txt";
static bool g_R2RVulca20MovementReportStarted = false;
template<class T> static bool R2R_Vulca20MovementRead(const T* source, T& destination)
{
    return source != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(source), sizeof(T)) &&
        SafeReadMemory(source, &destination, sizeof(T));
}
static bool R2R_Vulca20MovePlaying()
{
    return GAM_g_stEngineStructure != nullptr &&
        GAM_g_stEngineStructure->eEngineMode == E_EM_ModePlaying &&
        _stricmp(GAM_g_stEngineStructure->szLevelName, "Vulca_20") == 0 &&
        GAM_g_p_stDynamicWorld != nullptr && *GAM_g_p_stDynamicWorld != nullptr;
}
static float R2R_Vulca20MoveFactor()
{
    return R2R_StatsLegacyFactorForLevel(g_R2RVulca20RateMode, "Vulca_20", 0x117u);
}
static bool R2R_Vulca20MoveStartReport()
{
    if (g_R2RVulca20MovementReportStarted) return true;
    FILE* f = nullptr; fopen_s(&f, R2R_VULCA20_MOVEMENT_REPORT, "w");
    if (f == nullptr) return false;
    fprintf(f, "%s VULCA_20 SAFE BOSS MOVEMENT\n"
        "x.0 disables broad live-command scaling and delayed path capture on all seven selected actors.\n"
        "Jano's hard-coded jump, sighting, 12-unit chase and exact waypoint arrivals stay native.\n"
        "Crane flight uses UByte_2: MIN=x0.50; MAX=x2; RANDOM=x0.50..x2.\n"
        "MIN/MAX/RANDOM delay the flight AND fixed-phase timers by up to 120000ms each.\n"
        "MAX/fast RANDOM: Jano animation rate capped to 35 to space skull emissions; other animations untouched.\n"
        "Cinematic MaxHP command mailboxes, camera control and map transition stay native.\n",
        VERSION);
    fclose(f);
    g_R2RVulca20MovementReportStarted = true;
    return true;
}
static int R2R_Vulca20MovementPhase(const AI_tdstMind& mind, unsigned long expectedCount)
{
    AI_tdstIntelligence intel = {}; AI_tdstScriptAI* script = nullptr; AI_tdstScriptAI s = {};
    if (!R2R_Vulca20MovementRead(mind.p_stIntelligence, intel) ||
        !R2R_Vulca20MovementRead(intel.pp_stScriptAI, script) ||
        !R2R_Vulca20MovementRead(script, s) || s.a_stComport == nullptr ||
        s.ulNbComport == 0 || s.ulNbComport > 64 ||
        (expectedCount != 0 && s.ulNbComport != expectedCount)) return -1;
    const uintptr_t first = reinterpret_cast<uintptr_t>(s.a_stComport);
    const uintptr_t current = reinterpret_cast<uintptr_t>(intel.p_stCurrentComport);
    const size_t span = sizeof(AI_tdstComport) * s.ulNbComport;
    if (current < first || current - first >= span || (current - first) % sizeof(AI_tdstComport) != 0 ||
        !R2R_AddressReadable(current, sizeof(AI_tdstComport))) return -1;
    return static_cast<int>((current - first) / sizeof(AI_tdstComport));
}

