static unsigned int g_R2RMenuTextLanguage = 0, g_R2RMenuTextFrames = 0;
// TEXT_DisplayText can retain its current character pointer while a timed line
// is running. Keep each published backing allocation alive for process life,
// including across F9/F10, world changes and DLL detachment. No native string
// allocation is freed or overwritten; unchanged frames allocate nothing.
static std::vector<std::vector<std::string> >* g_R2RMenuTextStorage =
new (std::nothrow) std::vector<std::vector<std::string> >();

template<class T> static bool R2R_MenuTextRead(const T* address, T& value)
{
    return address != nullptr && R2R_AddressReadable(reinterpret_cast<uintptr_t>(address), sizeof(T)) &&
        SafeReadMemory(address, &value, sizeof(T));
}
static bool R2R_MenuTextWritable(const void* address, size_t bytes)
{
    if (address == nullptr || bytes == 0) return false;
    const uintptr_t p = reinterpret_cast<uintptr_t>(address);
    if (p > UINTPTR_MAX - bytes) return false;
    MEMORY_BASIC_INFORMATION info = {};
    if (VirtualQuery(address, &info, sizeof(info)) == 0 || info.State != MEM_COMMIT ||
        (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
    const DWORD protection = info.Protect & 0xff;
    if (protection != PAGE_READWRITE && protection != PAGE_WRITECOPY &&
        protection != PAGE_EXECUTE_READWRITE && protection != PAGE_EXECUTE_WRITECOPY) return false;
    const uintptr_t base = reinterpret_cast<uintptr_t>(info.BaseAddress);
    return p >= base && p - base <= info.RegionSize && bytes <= info.RegionSize - (p - base);
}
static int R2R_MenuTextPoolIndex(uint32_t handle)
{
    for (unsigned int i = 0; i < R2R_MENU_TEXT_COUNT; ++i)
        if (g_R2RMenuTextPool[i] == handle) return static_cast<int>(i);
    return -1;
}
static void R2R_MenuTextDraw(uint32_t seed, uint32_t generation, uint32_t(&mapping)[R2R_MENU_TEXT_COUNT])
{
    std::memcpy(mapping, g_R2RMenuTextPool, sizeof(mapping));
    uint64_t rng = R2R_SplitMix64((static_cast<uint64_t>(seed) << 32) | generation);
    rng ^= R2R_HashText64("Rayman2/all-levels/visible-text-pool");
    for (unsigned int i = R2R_MENU_TEXT_COUNT - 1; i > 0; --i)
    {
        rng = R2R_SplitMix64(rng);
        const unsigned int j = static_cast<unsigned int>(rng % (i + 1));
        const uint32_t temp = mapping[i]; mapping[i] = mapping[j]; mapping[j] = temp;
    }
}
static void R2R_MenuTextLog(const char* action, const char* detail, unsigned int count = 0)
{
    FILE* f = nullptr; fopen_s(&f, R2R_MENU_TEXT_REPORT, "a");
    if (f == nullptr) return;
    fprintf(f, "[GAME-TEXT] %s seed=%u roll=%u enabled=%u slots=%u %s\n", action,
        g_R2RConfig.seed, g_R2RMenuTextGeneration, g_R2RConfig.texts ? 1u : 0u, count, detail);
    fclose(f);
}
static bool R2R_MenuTextString(const char* p, std::string& result)
{
    result.clear();
    if (p == nullptr) return false;
    const uintptr_t start = reinterpret_cast<uintptr_t>(p);
    for (size_t offset = 0; offset < 8192;)
    {
        if (start > UINTPTR_MAX - offset) return false;
        const uintptr_t address = start + offset;
        MEMORY_BASIC_INFORMATION info = {};
        if (VirtualQuery(reinterpret_cast<const void*>(address), &info, sizeof(info)) == 0 ||
            info.State != MEM_COMMIT || (info.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
        const uintptr_t base = reinterpret_cast<uintptr_t>(info.BaseAddress);
        if (address < base || address - base >= info.RegionSize) return false;
        size_t bytes = info.RegionSize - (address - base);
        if (bytes > 128) bytes = 128;
        if (bytes > 8192 - offset) bytes = 8192 - offset;
        char block[128] = {};
        if (!SafeReadMemory(reinterpret_cast<const void*>(address), block, bytes)) return false;
        for (size_t i = 0; i < bytes; ++i)
        {
            if (block[i] == '\0') { result.append(block, i); return true; }
        }
        result.append(block, bytes); offset += bytes;
    }
    return false;
}
static size_t R2R_MenuTextToken(const std::string& s, size_t at)
{
    if (at + 2 >= s.size() || s[at] != '/') return at;
    const unsigned char first = static_cast<unsigned char>(s[at + 1]);
    if (!((first >= 'A' && first <= 'Z') || (first >= 'a' && first <= 'z'))) return at;
    for (size_t i = at + 2; i < s.size() && i - at <= 32; ++i)
    {
        const unsigned char c = static_cast<unsigned char>(s[i]);
        if (c == ':') return i + 1;
        if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
            (c >= '0' && c <= '9') || c == '-' || c == '+' || c == '.')) break;
    }
    return at;
}
static bool R2R_MenuTextBlank(unsigned char c) { return c == ' ' || c == '\r' || c == '\n' || c == '\t'; }
static void R2R_MenuTextGlyphMode(const std::string& s, size_t at, size_t end, bool& glyph)
{
    if (end <= at + 3 || (s[at + 1] != 'o' && s[at + 1] != 'O')) return;
    unsigned int font = 0;
    for (size_t i = at + 2; i + 1 < end; ++i)
    {
        if (s[i] < '0' || s[i] > '9' || font > 100000u) return;
        font = font * 10u + static_cast<unsigned int>(s[i] - '0');
    }
    glyph = font == 800u;
}
static std::string R2R_MenuTextVisible(const std::string& s)
{
    std::string body; bool glyph = false;
    for (size_t i = 0; i < s.size();)
    {
        const size_t end = R2R_MenuTextToken(s, i);
        if (end != i)
        {
            R2R_MenuTextGlyphMode(s, i, end, glyph);
            // Donors contain words and line breaks, without script events or
            // characters drawn as button/cursor sprites by the icon font.
            if (!glyph && (s[i + 1] == 'L' || s[i + 1] == 'l') && end == i + 3) body += "/L:";
            i = end;
        }
        else { if (!glyph) body.push_back(s[i]); ++i; }
    }
    for (;;)
    {
        if (!body.empty() && R2R_MenuTextBlank(static_cast<unsigned char>(body.front()))) body.erase(0, 1);
        else if (body.compare(0, 3, "/L:") == 0) body.erase(0, 3);
        else break;
    }
    for (;;)
    {
        if (!body.empty() && R2R_MenuTextBlank(static_cast<unsigned char>(body.back()))) body.pop_back();
        else if (body.size() >= 3 && body.compare(body.size() - 3, 3, "/L:") == 0) body.resize(body.size() - 3);
        else break;
    }
    return body;
}
