    text.hex("RIP=", c.Rip, 16);text.hex("RSP=", c.Rsp, 16);text.hex("RBP=", c.Rbp, 16);text.add("\r\n");
#else
    const uintptr_t ip = static_cast<uintptr_t>(c.Eip), sp = static_cast<uintptr_t>(c.Esp);
    text.hex("EIP=", c.Eip);text.hex("ESP=", c.Esp);text.hex("EBP=", c.Ebp);text.add("\r\n");
    text.hex("EAX=", c.Eax);text.hex("EBX=", c.Ebx);text.hex("ECX=", c.Ecx);text.hex("EDX=", c.Edx);text.hex("ESI=", c.Esi);text.hex("EDI=", c.Edi);text.add("\r\n");
#endif
    text.hex("exe_base=", f.imageBase);text.hex("exe_bytes=", f.imageBytes);
    if (f.imageBase && ip >= f.imageBase && r2bank::range(ip - f.imageBase, 1, f.imageBytes))text.hex("exe_RVA=", ip - f.imageBase);
    else text.add("exe_RVA=OUTSIDE_KNOWN_IMAGE ");text.add("\r\n");
    if (er.NumberParameters >= 2 && (er.ExceptionCode == EXCEPTION_ACCESS_VIOLATION || er.ExceptionCode == EXCEPTION_IN_PAGE_ERROR)) {
        text.hex("access_kind=", er.ExceptionInformation[0]);text.hex("fault_memory=", er.ExceptionInformation[1]);text.add("(0=read 1=write 8=execute)\r\n");
    }
