// ===========================================================================
// EXPERIMENTAL MENU ACTOR SHUFFLE -- separate from public Enemy Randomizer.
// INI: EnemiesMenuTest=1. Requires Enabled=1. ONLY the eight Raymap actors
// listed below, ONLY when level == "Menu". Enemies=0 remains forced in beta.
//
// Crucial design: MOVE INTACT ACTORS between scene slots. Never transplant
// Family/Model, State, Anim3d, 3D tables, Brain, mechanics or collision pointers.
// Model-as-skin swapping across families previously froze this game's renderer.
// This experiment changes LOCATION, not the enemy/actor's underlying type.
//
// 5 ambient (no waypoint) actors: deterministic deranged slot permutation.
// Francesco + Baleine: graph pair only if BOTH have initialized graph,
// waypoint and navigation caches. Exchange graph + active waypoint + route
// progress, then RECOMPUTE recipient Vector_3 + Vector_4 from the new target
// and recipient Float_1 speed. Old engine velocity is replaced next AI tick.
// If either cache/layout is invalid: leave these two completely untouched.
// Test 09 uses per-instance reset-source seeding plus deferred route rebinding. Each AI advances to the
// NEXT waypoint on its assigned network. If the game resets or despawns one,
// DO NOT rewrite a dying actor immediately; wait for a stable reconstructed
// instance, then restore its slot and route. No global AI scripts change.
// Test 21: Krabos joins the six-actor location remix. Its two isolated waypoints stay original.
// ===========================================================================
static const char* R2R_MENU_ENEMY_REPORT = "Rayman2Randomizer_MenuEnemyTest.txt";
// Report next to Rayman2Randomizer.ini / Rayman2.exe, never in an unknown working directory.
static void R2R_MenuReportPath(char out[MAX_PATH]) {
    out[0] = '\0';
    const char* path = g_R2RConfigPath;
    if (path && *path) {
        const char* slash = strrchr(path, '\\');
        const char* alt = strrchr(path, '/');
        if (alt && (!slash || alt > slash)) slash = alt;
        if (slash) {
            const size_t prefix = static_cast<size_t>(slash - path + 1);
            const size_t leaf = strlen(R2R_MENU_ENEMY_REPORT);
            if (prefix + leaf < MAX_PATH) {
                memcpy(out, path, prefix);
                memcpy(out + prefix, R2R_MENU_ENEMY_REPORT, leaf + 1);
                return;
            }
        }
    }
    snprintf(out, MAX_PATH, "%s", R2R_MENU_ENEMY_REPORT);
}
static FILE* R2R_MenuOpenReport(const char* mode) {
    char path[MAX_PATH] = {};
    R2R_MenuReportPath(path);
    FILE* f = nullptr;
    fopen_s(&f, path, mode);
    return f;
}
static void R2R_MenuEnemyStartupDiagnostic(const char* reason) {
    const char* mode = g_R2RConfigReloadCount <= 1 ? "w" : "a";
    FILE* f = R2R_MenuOpenReport(mode);
    if (!f) return;
    char reportPath[MAX_PATH] = {};
    R2R_MenuReportPath(reportPath);
    fprintf(f, "RAYMAN 2 RANDOMIZER %s - ENEMY MENU TEST 21\n", VERSION);
    fprintf(f, "[LOAD] reason=%s seed=%u enabled=%d enemiesMenuTest=%d reload=%u\n",
        reason ? reason : "?", g_R2RConfig.seed, g_R2RConfig.enabled ? 1 : 0,
        g_R2RConfig.enemiesMenuTest ? 1 : 0, g_R2RConfigReloadCount);
    fprintf(f, "[PATH] config=%s\n[PATH] report=%s\n", g_R2RConfigPath, reportPath);
    if (!g_R2RConfig.enemiesMenuTest || !g_R2RConfig.enabled)
        fprintf(f, "[DISABLED] Set Enabled=1 and EnemiesMenuTest=1 in the INI above, then restart Ray2x.exe.\n");
    else
        fprintf(f, "[READY] Waiting for the Menu level and 8 exact Raymap actors.\n");
    fclose(f);
}

