// TEST 15: PRIVATE GRAPH SHADOW (Menu only, Francesco / Baleine).
// Test14 proved the original baleine graph's 8-node linked list is cleared
// at frame ~2776 exactly when Francesco restarts. Changing Graph_0 alone
// cannot fix a graph with zero nodes. Snapshot the WHOLE graph while intact;
// at a deferred respawn, use independent graph/node/arc/waypoint storage.
// Do not restore the engine-owned linked anchor or traverse freed engine nodes.
static const int R2R_MENU_SHADOW_NODES=32;
static const int R2R_MENU_SHADOW_ARCS=16;
struct R2R_MenuShadowSnapshot {
    bool valid;
    uint32_t originalGraph;
    WP_tdstGraph base;
    int count;
    WP_tdstGraphNode* originalNode[R2R_MENU_SHADOW_NODES];
    WP_tdstGraphNode nodes[R2R_MENU_SHADOW_NODES];
    WP_tdstWayPoint points[R2R_MENU_SHADOW_NODES];
    int arcCount[R2R_MENU_SHADOW_NODES];
    WP_tdstArc arcs[R2R_MENU_SHADOW_NODES][R2R_MENU_SHADOW_ARCS];
};
// Test 19: NO nodes, waypoints or arcs embedded inside a larger allocation.
// Game code may unlink and free individual nodes when a route is finished.
// Every pointer reachable through the list has its OWN game allocator block.
// Local bookkeeping is only used before ownership is handed to the engine.
static R2R_MenuShadowSnapshot g_R2RMenuShadowBackup[2] = {};
static unsigned int g_R2RMenuShadowCreated[2] = {};
static bool R2R_MenuCaptureShadow(unsigned int idx,uint32_t raw) {
    if(idx>1 || !raw) return false;
    auto& dst=g_R2RMenuShadowBackup[idx];
    std::memset(&dst,0,sizeof(dst));
    WP_tdstGraph src={};
    if(!SafeReadMemory(reinterpret_cast<const WP_tdstGraph*>(uintptr_t(raw)),&src,sizeof(src))) return false;
    const long num=src.m_hListOfNode.lNbOfElementsDyn;
    if(num<2 || num>R2R_MENU_SHADOW_NODES || !src.m_hListOfNode.hFirstElementDyn ||
       !src.m_hListOfNode.hLastElementDyn) return false;
    dst.originalGraph=raw;
    dst.count=static_cast<int>(num);
    dst.base=src;
    WP_tdstGraphNode* sourceNode=src.m_hListOfNode.hFirstElementDyn;
    for(int i=0;i<dst.count;++i) {
        if(!sourceNode || !SafeReadMemory(sourceNode,&dst.nodes[i],sizeof(dst.nodes[i]))) return false;
        dst.originalNode[i]=sourceNode;
        if(!dst.nodes[i].m_hWayPoint ||
           !SafeReadMemory(dst.nodes[i].m_hWayPoint,&dst.points[i],sizeof(dst.points[i])) ||
           !R2R_MenuVecValid(dst.points[i].m_stVertex)) return false;
        const WP_tdstListOfArc* arcList=dst.nodes[i].m_hListOfArc;
        if(arcList) {
            WP_tdstListOfArc copy={};
            if(!SafeReadMemory(arcList,&copy,sizeof(copy))) return false;
            const auto& anchor=copy.m_hArc;
            if(anchor.lNbOfElementsDyn<0 || anchor.lNbOfElementsDyn>R2R_MENU_SHADOW_ARCS) return false;
            dst.arcCount[i]=static_cast<int>(anchor.lNbOfElementsDyn);
            WP_tdstArc* arc=anchor.hFirstElementDyn;
            for(int j=0;j<dst.arcCount[i];++j) {
                if(!arc || !SafeReadMemory(arc,&dst.arcs[i][j],sizeof(WP_tdstArc))) return false;
                arc=dst.arcs[i][j].hNextBrotherDyn;
            }
            if(arc) return false; // no unexpected extra/cyclic arc chain
        }
        sourceNode=dst.nodes[i].hNextBrotherDyn;
    }
    if(sourceNode || dst.originalNode[dst.count-1]!=src.m_hListOfNode.hLastElementDyn) return false;
    // Every arc target must point inside this same graph: external links
    // require a different, explicitly validated cloning strategy.
    for(int i=0;i<dst.count;++i)for(int j=0;j<dst.arcCount[i];++j) {
        bool found=false;
        for(int k=0;k<dst.count;++k) if(dst.arcs[i][j].m_hNode==dst.originalNode[k]) {found=true;break;}
        if(!found) return false;
    }
    dst.valid=true;
    char line[220]={};
    snprintf(line,sizeof(line),"[SHADOW-CAPTURE] actor=%s originalGraph=0x%08X nodes=%d verified=1",
       g_R2RMenuSpecs[idx].personal,raw,dst.count);
    R2R_MenuLog(line);
    return true;
}
static WP_tdstGraph* R2R_MenuBuildShadow(unsigned int idx) {
    if (idx > 1 || !g_R2RMenuShadowBackup[idx].valid || !AI_fn_p_vTrueAlloc || !AI_fn_vTrueFree)
        return nullptr;
    const auto& src = g_R2RMenuShadowBackup[idx];
    if (src.count < 2 || src.count > R2R_MENU_SHADOW_NODES) return nullptr;

    // Not attached to the world yet: any failure can be rolled back safely.
    // Allocations are independent because Rayman 2 can release list entries
    // separately after a path completes. Never free after attaching to the AI.
    std::vector<void*> allocations;
    auto makeBlock = [&allocations](size_t bytes) -> void* {
        void* p = AI_fn_p_vTrueAlloc(bytes);
        if (p) { std::memset(p, 0, bytes); allocations.push_back(p); }
        return p;
    };
    auto rollback = [&allocations]() -> WP_tdstGraph* {
        for (auto it = allocations.rbegin(); it != allocations.rend(); ++it)
            AI_fn_vTrueFree(*it);
        return nullptr;
    };
    WP_tdstGraph* graph = static_cast<WP_tdstGraph*>(makeBlock(sizeof(WP_tdstGraph)));
    if (!graph) return rollback();
    *graph = src.base;
    const char* name = idx == 0 ? "YAM_Reso_Baleine" : "YAM_Reso_Francesco";
    char* nameCopy = static_cast<char*>(makeBlock(std::strlen(name) + 1));
    if (!nameCopy) return rollback();
    std::memcpy(nameCopy, name, std::strlen(name) + 1);
    graph->m_szNameOfGraph = nameCopy;

    WP_tdstGraphNode* nodes[R2R_MENU_SHADOW_NODES] = {};
    WP_tdstWayPoint* points[R2R_MENU_SHADOW_NODES] = {};
    WP_tdstListOfArc* arcLists[R2R_MENU_SHADOW_NODES] = {};
    WP_tdstArc* arcs[R2R_MENU_SHADOW_NODES][R2R_MENU_SHADOW_ARCS] = {};
    for (int i = 0; i < src.count; ++i) {
        nodes[i] = static_cast<WP_tdstGraphNode*>(makeBlock(sizeof(WP_tdstGraphNode)));
        points[i] = static_cast<WP_tdstWayPoint*>(makeBlock(sizeof(WP_tdstWayPoint)));
        if (!nodes[i] || !points[i]) return rollback();
        *nodes[i] = src.nodes[i];
        *points[i] = src.points[i];
        if (src.arcCount[i]) {
            arcLists[i] = static_cast<WP_tdstListOfArc*>(makeBlock(sizeof(WP_tdstListOfArc)));
            if (!arcLists[i]) return rollback();
            for (int j = 0; j < src.arcCount[i]; ++j) {
                arcs[i][j] = static_cast<WP_tdstArc*>(makeBlock(sizeof(WP_tdstArc)));
                if (!arcs[i][j]) return rollback();
                *arcs[i][j] = src.arcs[i][j];
            }
        }
    }
    auto& anchor = graph->m_hListOfNode;
    anchor.hFirstElementDyn = nodes[0];
    anchor.hLastElementDyn = nodes[src.count - 1];
    anchor.lNbOfElementsDyn = src.count;
    for (int i = 0; i < src.count; ++i) {
        auto* node = nodes[i];
        node->m_hWayPoint = points[i];
        node->hPrevBrotherDyn = i ? nodes[i-1] : nullptr;
        node->hNextBrotherDyn = i + 1 < src.count ? nodes[i+1] : nullptr;
        node->hFatherDyn = &anchor;
        if (src.arcCount[i]) {
            auto& aa = arcLists[i]->m_hArc;
            aa.hFirstElementDyn = arcs[i][0];
            aa.hLastElementDyn = arcs[i][src.arcCount[i]-1];
            aa.lNbOfElementsDyn = src.arcCount[i];
            node->m_hListOfArc = arcLists[i];
            for (int j = 0; j < src.arcCount[i]; ++j) {
                auto* arc = arcs[i][j];
                arc->hPrevBrotherDyn = j ? arcs[i][j-1] : nullptr;
                arc->hNextBrotherDyn = j+1 < src.arcCount[i] ? arcs[i][j+1] : nullptr;
                arc->hFatherDyn = &aa;
                bool found = false;
                for (int k = 0; k < src.count; ++k) {
                    if (arc->m_hNode == src.originalNode[k]) {
                        arc->m_hNode = nodes[k];
                        found = true;
                        break;
                    }
                }
                if (!found) return rollback();
            }
        } else node->m_hListOfArc = nullptr;
    }
    // Full ownership is now handed to the engine. No mod-side frees of live data.
    return graph;
}
static bool R2R_MenuEnsureDurableGraph(unsigned int idx) {
    if(idx>1) return false;
    auto& b=g_R2RMenuBindings[idx];
    WP_tdstGraph current={};
    const bool read=b.desiredGraph && SafeReadMemory(
        reinterpret_cast<const WP_tdstGraph*>(uintptr_t(b.desiredGraph)),&current,sizeof(current));
    const bool healthy=read && current.m_hListOfNode.lNbOfElementsDyn>=2 &&
        current.m_hListOfNode.lNbOfElementsDyn<=R2R_MENU_SHADOW_NODES &&
        current.m_hListOfNode.hFirstElementDyn && current.m_hListOfNode.hLastElementDyn;
    if(healthy)return true;
    if(!g_R2RMenuShadowBackup[idx].valid) {
        char line[175]={};snprintf(line,sizeof(line),"[SHADOW-SKIP] actor=%s backup-not-verified",
            g_R2RMenuSpecs[idx].personal);R2R_MenuLog(line);
        return false;
    }
    // Never repair the original graph's linked list: use our own copy.
    // Bound the test's live rebuilds, to avoid accumulating memory indefinitely.
    // Six cycles cover repeated respawns while keeping this diagnosis controlled.
    if (g_R2RMenuShadowCreated[idx] >= 6u) {
        R2R_MenuLog("[SHADOW-LIMIT] six independent rebuilds reached; further reattachment disabled");
        return false;
    }
    WP_tdstGraph* fresh=R2R_MenuBuildShadow(idx);
    if(!fresh)return false;
    const uint32_t old=b.desiredGraph;
    b.desiredGraph=static_cast<uint32_t>(reinterpret_cast<uintptr_t>(fresh));
    ++g_R2RMenuShadowCreated[idx];
    char line[270]={};
    snprintf(line,sizeof(line),
       "[SHADOW-ATTACH] actor=%s oldGraph=0x%08X privateGraph=0x%08X nodes=%d copies=%u alloc=separate",
       g_R2RMenuSpecs[idx].personal,old,b.desiredGraph,
       g_R2RMenuShadowBackup[idx].count,g_R2RMenuShadowCreated[idx]);
    R2R_MenuLog(line);
    return true;
}

static void R2R_MenuReset(HIE_tdstSuperObject* world) {
    if (g_R2RMenuWorld && g_R2RMenuApplied) {
        for (unsigned int idx=0; idx<2; ++idx) {
            const R2R_MenuRouteBinding& b=g_R2RMenuBindings[idx];
            if (!b.postReattachActive) continue;
            char line[190]={};
            snprintf(line,sizeof(line),"[POST-REATTACH-LEVEL-EXIT] actor=%s observedFrames=%u",
                     g_R2RMenuSpecs[idx].personal,b.postReattachFrames);
            R2R_MenuLog(line);
        }
    }
    std::memset(g_R2RMenuActors, 0, sizeof(g_R2RMenuActors));
    g_R2RMenuWorld = world;
    g_R2RMenuApplied = false;
    g_R2RMenuFrames = 0;
    g_R2RMenuReported = false;
    g_R2RMenuVerifyFrames = 0;
    g_R2RMenuCrabRelocated = false;
    g_R2RMenuCrabDestination = {};
    g_R2RMenuGraphMoved = false;
    std::memset(g_R2RMenuBindings, 0, sizeof(g_R2RMenuBindings));
    std::memset(g_R2RMenuShadowBackup,0,sizeof(g_R2RMenuShadowBackup));
    g_R2RMenuShadowCreated[0]=g_R2RMenuShadowCreated[1]=0;
    g_R2RMenuGraphAuditFrames=0;
    g_R2RMenuLastGraphNodeCount[0]=-10000L;
    g_R2RMenuLastGraphNodeCount[1]=-10000L;
    g_R2RMenuLastGraphHead[0]=g_R2RMenuLastGraphHead[1]=0u;
    g_R2RMenuLastGraphTail[0]=g_R2RMenuLastGraphTail[1]=0u;
}
static void R2R_MenuConsider(HIE_tdstSuperObject* o) {
    if (!o || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(o), sizeof(HIE_tdstSuperObject)) ||
        o->ulType != HIE_C_Type_Actor || o == HIE_M_hGetMainActor()) return;
    const char* p = HIE_fn_szGetObjectPersonalName(o);
    if (!p) return;
    int slot = -1;
    for (int i=0; i<8; ++i)
        if (_stricmp(p, g_R2RMenuSpecs[i].personal) == 0) { slot=i; break; }
    if (slot < 0 || g_R2RMenuActors[slot].object) return;
    const char* family = HIE_fn_szGetObjectFamilyName(o);
    const char* model = HIE_fn_szGetObjectModelName(o);
    if (!family || !model || _stricmp(family, g_R2RMenuSpecs[slot].family) ||
        _stricmp(model, g_R2RMenuSpecs[slot].model)) return;
    HIE_tdstEngineObject* a = HIE_M_hSuperObjectGetActor(o);
    if (!a || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(a), sizeof(HIE_tdstEngineObject)) ||
        !a->h3dData || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(a->h3dData), sizeof(GAM_tdst3dData)) ||
        !a->hBrain || !o->hFatherDyn ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(o->hFatherDyn), sizeof(HIE_tdstSuperObject))) return;
    POS_tdstCompletePosition* g=o->p_stGlobalMatrix, *l=o->p_stLocalMatrix;
    if (!g || !l || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(g), sizeof(*g)) ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(l), sizeof(*l)) ||
        !R2R_MenuVecValid(g->stPos) || !R2R_MenuVecValid(l->stPos)) return;
    R2R_MenuEnemyActor& dest = g_R2RMenuActors[slot];
    dest.object=o; dest.actor=a; dest.parent=o->hFatherDyn;
    dest.global=g; dest.local=l; dest.native=g->stPos;
}
static void R2R_MenuWalk(HIE_tdstSuperObject* root, unsigned depth) {
    if (!root || depth>64 || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(root), sizeof(*root))) return;
    R2R_MenuConsider(root);
    HIE_tdstSuperObject* child=nullptr;
    LST_M_DynamicForEach(root, child) {
        if (child) R2R_MenuWalk(child, depth+1);
    }
}
// Compute target local matrix before ANY mutation. A translated local matrix
// is not equivalent to world space if a parent sector is rotated/scaled.
static bool R2R_MenuLocalTarget(const R2R_MenuEnemyActor& e, const MTH3D_tdstVector& target,
    MTH3D_tdstVector& out) {
    if (!e.global || !e.local || !R2R_MenuVecValid(target) ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(e.global), sizeof(*e.global)) ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(e.local), sizeof(*e.local)) ||
        !R2R_MenuVecValid(e.global->stPos) || !R2R_MenuVecValid(e.local->stPos)) return false;
    if (e.global == e.local) out=target;
    else {
        if (!e.parent || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(e.parent), sizeof(*e.parent))) return false;
        POS_tdstCompletePosition* parent=e.parent->p_stGlobalMatrix;
        if (!parent || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(parent), sizeof(*parent)) ||
            parent->eType==MTH_C_Type_IdentityMatrix || parent->eType==MTH_C_Type_TranslationMatrix) {
            out=e.local->stPos;
            out.x += target.x-e.global->stPos.x;
            out.y += target.y-e.global->stPos.y;
            out.z += target.z-e.global->stPos.z;
        } else {
            if (!POS_fn_vInvertMatrix || !POS_fn_vMulMatrixVertex) return false;
            POS_tdstCompletePosition inv={};
            POS_fn_vInvertMatrix(&inv, parent);
            MTH3D_tdstVector world=target;
            POS_fn_vMulMatrixVertex(&out, &inv, &world);
        }
    }
    return R2R_MenuVecValid(out) &&
        R2R_Learn30MoveWritable(e.global, sizeof(*e.global)) &&
        R2R_Learn30MoveWritable(e.local, sizeof(*e.local));
}
static void R2R_MenuCommit(const R2R_MenuEnemyActor& e, const MTH3D_tdstVector& to,
    const MTH3D_tdstVector& localTarget) {
    e.local->stPos = localTarget;
    if(e.global != e.local) e.global->stPos=to;
}
// Full-object movement needs physics' previous/current matrices synchronized too.
// Otherwise engine mechanics can overwrite our visual matrix on the next tick.
static bool R2R_MenuPreparePhysics(const R2R_MenuEnemyActor& a,
                                  R2R_MenuPhysics& out, const char* label) {
    std::memset(&out,0,sizeof(out));
    if(!a.actor || !a.actor->hDynam) {
        char line[160]={};
        snprintf(line,sizeof(line),"[PHYSICS] actor=%s mode=no-dynamics",label);
        R2R_MenuLog(line);
        return true;
    }
    DNM_tdstDynam dynam={};
    if(!SafeReadMemory(a.actor->hDynam,&dynam,sizeof(dynam)) || !dynam.p_stDynamics ||
       !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stDynamics),sizeof(DNM_tdstDynamicsBaseBlock)) ||
       !R2R_Learn30MoveWritable(dynam.p_stDynamics,sizeof(DNM_tdstDynamicsBaseBlock))) {
        char line[170]={};snprintf(line,sizeof(line),"[PHYSICS-REJECT] actor=%s reason=dynamics-unreadable",label);
        R2R_MenuLog(line);return false;
    }
    DNM_tdstDynamicsBaseBlock base={};
    if(!SafeReadMemory(&dynam.p_stDynamics->stDynamicsBase,&base,sizeof(base)) ||
       !R2R_MenuVecValid(base.stPreviousMatrix.stPos) ||
       !R2R_MenuVecValid(base.stCurrentMatrix.stPos)) {
        char line[170]={};snprintf(line,sizeof(line),"[PHYSICS-REJECT] actor=%s reason=matrix-invalid",label);
        R2R_MenuLog(line);return false;
    }
    out.physics=dynam.p_stDynamics;
    out.hasDynamics=true;
    if(dynam.p_stParsingDatas &&
       R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stParsingDatas),sizeof(DNM_tdstParsingDatas)) &&
       R2R_Learn30MoveWritable(dynam.p_stParsingDatas,sizeof(DNM_tdstParsingDatas))) {
        DNM_tdstParsingDatas pd={};
        if(SafeReadMemory(dynam.p_stParsingDatas,&pd,sizeof(pd)) && R2R_MenuVecValid(pd.stPosition))
            out.parsing=dynam.p_stParsingDatas;
    }
    char line[260]={};
    snprintf(line,sizeof(line),"[PHYSICS] actor=%s previous=%.2f,%.2f,%.2f current=%.2f,%.2f,%.2f",label,
        base.stPreviousMatrix.stPos.x,base.stPreviousMatrix.stPos.y,base.stPreviousMatrix.stPos.z,
        base.stCurrentMatrix.stPos.x,base.stCurrentMatrix.stPos.y,base.stCurrentMatrix.stPos.z);
    R2R_MenuLog(line);
    return true;
}
static void R2R_MenuPhysicsCommit(const R2R_MenuPhysics& p,
                                  const MTH3D_tdstVector& delta) {
    if(!p.hasDynamics) return;
    DNM_tdstDynamicsBaseBlock& base=p.physics->stDynamicsBase;
    base.stPreviousMatrix.stPos.x+=delta.x;
    base.stPreviousMatrix.stPos.y+=delta.y;
    base.stPreviousMatrix.stPos.z+=delta.z;
    base.stCurrentMatrix.stPos.x+=delta.x;
    base.stCurrentMatrix.stPos.y+=delta.y;
    base.stCurrentMatrix.stPos.z+=delta.z;
    if(p.parsing) {
        p.parsing->stPosition.x+=delta.x;
        p.parsing->stPosition.y+=delta.y;
        p.parsing->stPosition.z+=delta.z;
    }
}
static bool R2R_MenuNamedGraph(const R2R_MenuEnemyNav& n, const char* expected,
                               const char* actorName) {
    uint32_t graphRaw=0;memcpy(&graphRaw,n.data[0],4);
    WP_tdstGraph g={};
    if(!graphRaw || !SafeReadMemory(reinterpret_cast<const WP_tdstGraph*>(uintptr_t(graphRaw)),&g,sizeof(g)) ||
       !g.m_szNameOfGraph || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(g.m_szNameOfGraph),1)) {
        char line[170]={};snprintf(line,sizeof(line),"[GRAPH-NAME-REJECT] actor=%s reason=unreadable",actorName);
        R2R_MenuLog(line);return false;
    }
    char name[65]={};
    bool terminated=false;
    for(unsigned int i=0;i<64;++i){
        const char* p=g.m_szNameOfGraph+i;
        if(!R2R_AddressReadable(reinterpret_cast<uintptr_t>(p),1) ||
           !SafeReadMemory(p,&name[i],1)) return false;
        if(name[i]=='\0'){terminated=true;break;}
    }
    if(!terminated)return false;
    char line[220]={};
    snprintf(line,sizeof(line),"[GRAPH-IDENTITY] actor=%s graph=%s expected=%s",actorName,name,expected);
    R2R_MenuLog(line);
    // Guard against swapping an unrelated menu route or a stale graph.
    return _stricmp(name,expected)==0;
}
// Some network procedures cache route progress in actor->hMSWay.
// The route cursor must agree with the newly installed DSG Graph_0.
static bool R2R_MenuReadCursor(const R2R_MenuEnemyActor& a,R2R_MenuCursor& out,
                               const char* actorName){
    std::memset(&out,0,sizeof(out));
    if(!a.actor || !a.actor->hMSWay) return true;
    if(!R2R_AddressReadable(reinterpret_cast<uintptr_t>(a.actor->hMSWay),sizeof(WP_tdstMSWay)) ||
       !R2R_Learn30MoveWritable(a.actor->hMSWay,sizeof(WP_tdstMSWay)) ||
       !SafeReadMemory(a.actor->hMSWay,&out.original,sizeof(out.original))) {
        char line[190]={};snprintf(line,sizeof(line),"[CURSOR-REJECT] actor=%s",actorName);
        R2R_MenuLog(line);return false;
    }
    out.ptr=a.actor->hMSWay;
    return true;
}
static void R2R_MenuCommitCursor(const R2R_MenuCursor& receiver,
                                 const R2R_MenuCursor& donor, uint32_t newGraph) {
    if(!receiver.ptr)return;
    WP_tdstMSWay w=receiver.original;
    w.m_hPath=reinterpret_cast<WP_tdstGraph*>(uintptr_t(newGraph));
    if(donor.ptr) {w.m_lIndex=donor.original.m_lIndex;w.m_bIsCircular=donor.original.m_bIsCircular;}
    else w.m_lIndex=0; // no donor progress available; start the new graph
    *receiver.ptr=w;
}
static float R2R_MenuDistance(const MTH3D_tdstVector& a, const MTH3D_tdstVector& b); // Test 21: declaration before CRAB-VERIFY
static void R2R_MenuVerifyPositions() {
    if(!g_R2RMenuGraphMoved && !g_R2RMenuCrabRelocated) return;
    ++g_R2RMenuVerifyFrames;
    const unsigned int at=g_R2RMenuVerifyFrames;
    if(at!=1 && at!=5 && at!=30 && at!=90)return;
    if (g_R2RMenuGraphMoved) {
        const MTH3D_tdstVector targets[2]={g_R2RMenuWhaleSlot,g_R2RMenuFrancescoSlot};
        for(int i=0;i<2;++i){
            const R2R_MenuEnemyActor& a=g_R2RMenuActors[i];
            if(!a.global || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(a.global),sizeof(*a.global)))continue;
            const MTH3D_tdstVector v=a.global->stPos;
            const float dx=v.x-targets[i].x,dy=v.y-targets[i].y,dz=v.z-targets[i].z;
            const float dist=std::sqrt(dx*dx+dy*dy+dz*dz);
            char line[230]={};
            snprintf(line,sizeof(line),"[POSITION-VERIFY] frames=%u actor=%s pos=%.2f,%.2f,%.2f distanceFromSwapSlot=%.2f",
                at,g_R2RMenuSpecs[i].personal,v.x,v.y,v.z,dist);
            R2R_MenuLog(line);
        }
    }
    // Crab has two isolated WayPoint DSG fields rather than the other two actors' Graph_0.
    // Observe motion, do NOT repoint them to arbitrary graph points.
    if (g_R2RMenuCrabRelocated) {
        const R2R_MenuEnemyActor& crab=g_R2RMenuActors[7];
        if(crab.global && R2R_AddressReadable(reinterpret_cast<uintptr_t>(crab.global),sizeof(*crab.global))) {
            MTH3D_tdstVector pos={};
            if(SafeReadMemory(&crab.global->stPos,&pos,sizeof(pos)) && R2R_MenuVecValid(pos)) {
                char line[285]={};
                snprintf(line,sizeof(line),
                    "[CRAB-VERIFY] frames=%u actor=YAM_Krabos pos=%.2f,%.2f,%.2f distanceFromNewSlot=%.2f distanceFromNative=%.2f",
                    at,pos.x,pos.y,pos.z,R2R_MenuDistance(pos,g_R2RMenuCrabDestination),
                    R2R_MenuDistance(pos,crab.native));
                R2R_MenuLog(line);
            }
        }
    }
}
// Strictly typed DSG. If either actor has a different script memory layout,
// nothing will be written. Graph and cached navigation must be transferred
// together; a Graph-only change can strand a moving character.
static bool R2R_MenuNavReject(const char* actorName, const char* why) {
    char diagnostic[240] = {};
    snprintf(diagnostic, sizeof(diagnostic), "[NAV-REJECT] actor=%s reason=%s",
        actorName ? actorName : "?", why ? why : "?");
    R2R_MenuLog(diagnostic);
    return false;
}
static bool R2R_MenuReadGraphNav(const R2R_MenuEnemyActor& a, R2R_MenuEnemyNav& nav, const char* actorName, bool allowEmptyWaypoint=false) {
    if (!a.actor || !a.actor->hBrain ||
        !R2R_AddressReadable(reinterpret_cast<uintptr_t>(a.actor->hBrain), sizeof(AI_tdstBrain)))
        return R2R_MenuNavReject(actorName,"brain-pointer");
    AI_tdstBrain brain={};
    if(!SafeReadMemory(a.actor->hBrain, &brain, sizeof(brain)) || !brain.p_stMind)
        return R2R_MenuNavReject(actorName,"brain-mind");
    AI_tdstMind mind={};
    if(!SafeReadMemory(brain.p_stMind, &mind, sizeof(mind)) || !mind.p_stDsgMem || !mind.p_stAIModel)
        return R2R_MenuNavReject(actorName,"mind-layout");
    AI_tdstAIModel model={}; AI_tdstDsgMem mem={};
    if(!SafeReadMemory(mind.p_stAIModel, &model, sizeof(model)) ||
       !SafeReadMemory(mind.p_stDsgMem, &mem, sizeof(mem)) ||
       !mem.pp_stDsgVar || !mem.p_cDsgMemBuffer || !model.p_stDsgVar)
        return R2R_MenuNavReject(actorName,"dsg-memory");
    AI_tdstDsgVar* def=nullptr;
    if(!SafeReadMemory(mem.pp_stDsgVar, &def, sizeof(def)) || def != model.p_stDsgVar)
        return R2R_MenuNavReject(actorName,"dsg-definition");
    AI_tdstDsgVar vars={};
    if(!SafeReadMemory(def, &vars, sizeof(vars)) || vars.ucNbDsgVar!=8 ||
       vars.ulBufferSize<56 || vars.ulBufferSize>256 || !vars.a_stDsgVarInfo ||
       mem.p_cDsgMemBuffer == mem.p_cDsgMemBufferInit ||
       mem.p_cDsgMemBuffer == vars.p_cDsgMemDefaultInit ||
       !R2R_Learn30MoveWritable(mem.p_cDsgMemBuffer, vars.ulBufferSize))
        return R2R_MenuNavReject(actorName,"dsg-buffer-shape");
    static const unsigned int indices[4]={0,5,6,7};
    static const unsigned int types[4]={17,11,5,8};
    static const unsigned int widths[4]={4,12,4,4};
    std::memset(&nav,0,sizeof(nav)); nav.buffer=mem.p_cDsgMemBuffer; nav.bytes=vars.ulBufferSize;
    for(unsigned int i=0;i<4;++i) {
        AI_tdstDsgVarInfo info={};
        if(!SafeReadMemory(vars.a_stDsgVarInfo+indices[i], &info, sizeof(info)))
            return R2R_MenuNavReject(actorName,"navigation-info-read");
        const unsigned int type=static_cast<unsigned int>(info.eTypeId);
        if(type != types[i] && !(i==2 && type==6))
            return R2R_MenuNavReject(actorName,"navigation-info-type");
        if(info.ulOffsetInDsgMem >= nav.bytes || widths[i] > nav.bytes-info.ulOffsetInDsgMem)
            return R2R_MenuNavReject(actorName,"navigation-info-offset");
        nav.offsets[i]=info.ulOffsetInDsgMem; nav.sizes[i]=widths[i];
        if(!SafeReadMemory(nav.buffer+nav.offsets[i],nav.data[i],nav.sizes[i]))
            return R2R_MenuNavReject(actorName,"navigation-value-read");
        for(unsigned int j=0;j<i;++j)
            if(nav.offsets[i]<nav.offsets[j]+nav.sizes[j] && nav.offsets[j]<nav.offsets[i]+nav.sizes[i])
                return R2R_MenuNavReject(actorName,"navigation-overlap");
    }
    uint32_t graph=0, wp=0;
    std::memcpy(&graph, nav.data[0], 4); std::memcpy(&wp, nav.data[3], 4);
    if(!graph || !R2R_AddressReadable(graph, sizeof(WP_tdstGraph)) ||
       (!wp && !allowEmptyWaypoint) ||
       (wp && !R2R_AddressReadable(wp, sizeof(WP_tdstWayPoint))))
        return R2R_MenuNavReject(actorName,"uninitialized-graph-or-waypoint");
    // During a deferred respawn ONLY, Rayman may temporarily clear WayPoint_7.
    // Validate the whole DSG layout but permit wp=0 so we can restore the
    // donor's known-good waypoint as ONE route unit after the safety delay.
    if(!wp && allowEmptyWaypoint) {
        char line[180]={};
        snprintf(line,sizeof(line),"[NAV-EMPTY-WP] actor=%s grace-passed; route rebind allowed",actorName);
        R2R_MenuLog(line);
    }
    MTH3D_tdstVector v={}; std::memcpy(&v, nav.data[1], 12);
    if (!R2R_MenuVecValid(v))
        return R2R_MenuNavReject(actorName,"invalid-cached-waypoint-target");
    // Vector_5 is the game's validated cached absolute waypoint position.
    // The pointer is checked above; do not incorrectly reject a waypoint
    // because of its radius or internal layout (which steering never reads).
    // Verify these three extra DSG fields in both actor models rather than
    // assuming their offsets from the Raymap export (may vary by game build).
    static const unsigned int extraIndex[3]={1,3,4};
    static const unsigned int extraType[3]={7,11,11}; // AI_E_dvt_Float=7, AI_E_dvt_Vector=11, AI_E_dvt_Perso=9
    static const unsigned int extraWidth[3]={4,12,12};
    unsigned long extraOffset[3]={};
    for(unsigned int i=0;i<3;++i){
        AI_tdstDsgVarInfo info={};
        if(!SafeReadMemory(vars.a_stDsgVarInfo+extraIndex[i], &info, sizeof(info)))
            return R2R_MenuNavReject(actorName,"steering-info-read");
        if(static_cast<unsigned int>(info.eTypeId)!=extraType[i]) {
            char reason[128] = {};
            snprintf(reason,sizeof(reason),"steering-type-index-%u-actual-%u-expected-%u",
                extraIndex[i],static_cast<unsigned int>(info.eTypeId),extraType[i]);
            return R2R_MenuNavReject(actorName,reason);
        }
        if(info.ulOffsetInDsgMem>=nav.bytes ||
           extraWidth[i]>nav.bytes-info.ulOffsetInDsgMem)
            return R2R_MenuNavReject(actorName,"steering-info-offset");
        extraOffset[i]=info.ulOffsetInDsgMem;
        for(unsigned int j=0;j<4;++j)
            if(extraOffset[i]<nav.offsets[j]+nav.sizes[j] &&
               nav.offsets[j]<extraOffset[i]+extraWidth[i])
                return R2R_MenuNavReject(actorName,"steering-overlaps-navigation");
        for(unsigned int j=0;j<i;++j)
            if(extraOffset[i]<extraOffset[j]+extraWidth[j] &&
               extraOffset[j]<extraOffset[i]+extraWidth[i])
                return R2R_MenuNavReject(actorName,"steering-overlap");
    }
    if(!SafeReadMemory(nav.buffer+extraOffset[0], &nav.speed, sizeof(nav.speed)) ||
       !std::isfinite(nav.speed) || nav.speed<0.1f || nav.speed>50.0f)
        return R2R_MenuNavReject(actorName,"steering-speed");
    for(unsigned int i=0;i<2;++i){
        nav.steeringOffsets[i]=extraOffset[i+1];
        if(!SafeReadMemory(nav.buffer+nav.steeringOffsets[i],
                           &nav.originalSteering[i], sizeof(MTH3D_tdstVector)) ||
           !R2R_MenuVecValid(nav.originalSteering[i]))
            return R2R_MenuNavReject(actorName,"steering-vector-read");
    }
    {
        char line[256] = {};
        snprintf(line, sizeof(line),
            "[NAV-CHECK] actor=%s graph=0x%08X wp=0x%08X speed=%.2f target=%.2f,%.2f,%.2f",
            actorName ? actorName : "?", graph, wp, nav.speed, v.x, v.y, v.z);
        R2R_MenuLog(line);
    }
    return true;
}
// Steering toward the new graph's CURRENT game-computed waypoint target.
// In this scenario the new position is exactly the donor's native slot,
// so its initialized WayPoint_7 + Vector_5 is a suitable next destination.
// Keep each actor's OWN speed Float_1 (Franc 5 vs Whale 6 in Raymap).
static bool R2R_MenuPlanSteering(const R2R_MenuEnemyNav& destination,
    const R2R_MenuEnemyNav& donor, const MTH3D_tdstVector& newPosition,
    MTH3D_tdstVector& result){
    MTH3D_tdstVector target={};
    std::memcpy(&target,donor.data[1],sizeof(target)); // donor Vector_5
    if(!R2R_MenuVecValid(target) || !R2R_MenuVecValid(newPosition)) return false;
    const float dx=target.x-newPosition.x, dy=target.y-newPosition.y, dz=target.z-newPosition.z;
    const float len=std::sqrt(dx*dx+dy*dy+dz*dz);
    if(!std::isfinite(len)) return false;
    if(len > 0.001f){
        const float factor=destination.speed/len;
        result={dx*factor,dy*factor,dz*factor};
    } else {
        // The actor is already at the current waypoint. Let the original
        // behavior advance the graph on its next tick. Avoid a stale speed.
        result={0.0f,0.0f,0.0f};
    }
    return R2R_MenuVecValid(result);
}
// Bounded read-only membership test. A character can legitimately change its
// WayPoint_7 as it travels, so NEVER overwrite a valid waypoint on the assigned
// graph. Only reject a waypoint proven to be from another graph. -1=unknown.
static int R2R_MenuWaypointOnGraph(uint32_t graphRaw, uint32_t wpRaw) {
    if (!graphRaw || !wpRaw) return 0;
    WP_tdstGraph graph={};
    if (!SafeReadMemory(reinterpret_cast<const WP_tdstGraph*>(uintptr_t(graphRaw)),
                        &graph,sizeof(graph))) return -1;
    const auto& anchor=graph.m_hListOfNode;
    if (anchor.lNbOfElementsDyn < 0 || anchor.lNbOfElementsDyn > 1024)
        return -1;
    if (!anchor.hFirstElementDyn || anchor.lNbOfElementsDyn == 0) return -1;
    WP_tdstGraphNode* node=anchor.hFirstElementDyn;
    for (unsigned int n=0; node && n<1024; ++n) {
        WP_tdstGraphNode snapshot={};
        if (!SafeReadMemory(node,&snapshot,sizeof(snapshot))) return -1;
        if (reinterpret_cast<uintptr_t>(snapshot.m_hWayPoint) == uintptr_t(wpRaw)) return 1;
        node=snapshot.hNextBrotherDyn;
    }
    return node ? -1 : 0;
}
static float R2R_MenuDistance(const MTH3D_tdstVector& a,const MTH3D_tdstVector& b){
    const float x=a.x-b.x,y=a.y-b.y,z=a.z-b.z;
    return std::sqrt(x*x+y*y+z*z);
}
static void R2R_MenuBindRoute(unsigned int idx,const R2R_MenuEnemyNav& original,
                               const R2R_MenuEnemyNav& donor,
                               const R2R_MenuCursor& donorCursor){
    R2R_MenuRouteBinding& b=g_R2RMenuBindings[idx];
    std::memset(&b,0,sizeof(b));
    std::memcpy(&b.desiredGraph,donor.data[0],4);
    std::memcpy(&b.oldGraph,original.data[0],4);
    b.originalAssignedGraph=b.desiredGraph;
    std::memcpy(&b.firstWaypoint,donor.data[3],4);
    std::memcpy(&b.initialTarget,donor.data[1],sizeof(b.initialTarget));
    std::memcpy(&b.initialRemaining,donor.data[2],4);
    b.initialCursorIndex=donorCursor.ptr?donorCursor.original.m_lIndex:0;
    for(unsigned int i=0;i<4;++i)b.offsets[i]=original.offsets[i];
    for(unsigned int i=0;i<2;++i)b.steeringOffsets[i]=original.steeringOffsets[i];
    b.ownSpeed=original.speed;
    b.dsgBuffer=original.buffer;
    b.lastObject=g_R2RMenuActors[idx].object;
    b.lastPosition=idx==0?g_R2RMenuWhaleSlot:g_R2RMenuFrancescoSlot;
    b.positionKnown=true;
    b.enabled=b.desiredGraph && b.firstWaypoint;
    char line[280]={};
    snprintf(line,sizeof(line),
        "[PATH-BIND] actor=%s assigned=%s graph=0x%08X firstWP=0x%08X fromSlot=%s",
        g_R2RMenuSpecs[idx].personal,
        idx==0?"YAM_Reso_Baleine":"YAM_Reso_Francesco",
        b.desiredGraph,b.firstWaypoint,
        idx==0?"YAM_Baleine_I1":"YAM_francesco");
    R2R_MenuLog(line);
}
// The engine can restore Graph_0 from an actor's INITIAL DSG data when its
// itinerary ends. A live Graph_0 swap alone cannot survive that reset.
// Change only Graph_0 in the actor INSTANCE init buffer, never the common
// model template or the live buffer. Do not patch if we cannot prove that
// Francesco and Baleine own distinct initialized blocks.
struct R2R_MenuInitBlock {
    char* base;
    unsigned long size;
    unsigned long offset;
    uint32_t currentGraph;
};
static bool R2R_MenuGetInitBlock(unsigned int idx,R2R_MenuInitBlock& out) {
    std::memset(&out,0,sizeof(out));
    if(idx>1)return false;
    const R2R_MenuEnemyActor& a=g_R2RMenuActors[idx];
    const R2R_MenuRouteBinding& b=g_R2RMenuBindings[idx];
    if(!b.enabled || !a.actor || !a.actor->hBrain ||
       !R2R_AddressReadable(reinterpret_cast<uintptr_t>(a.actor->hBrain),sizeof(AI_tdstBrain)))return false;
    AI_tdstBrain brain={};AI_tdstMind mind={};AI_tdstDsgMem mem={};
    AI_tdstAIModel model={}; AI_tdstDsgVar* def=nullptr; AI_tdstDsgVar vars={};
    if(!SafeReadMemory(a.actor->hBrain,&brain,sizeof(brain)) || !brain.p_stMind ||
       !SafeReadMemory(brain.p_stMind,&mind,sizeof(mind)) ||
       !mind.p_stDsgMem || !mind.p_stAIModel ||
       !SafeReadMemory(mind.p_stDsgMem,&mem,sizeof(mem)) ||
       !SafeReadMemory(mind.p_stAIModel,&model,sizeof(model)) ||
       !mem.pp_stDsgVar || !SafeReadMemory(mem.pp_stDsgVar,&def,sizeof(def)) ||
       !def || def!=model.p_stDsgVar ||
       !SafeReadMemory(def,&vars,sizeof(vars)))return false;
    if(!mem.p_cDsgMemBufferInit || !mem.p_cDsgMemBuffer ||
       mem.p_cDsgMemBufferInit==mem.p_cDsgMemBuffer ||
       mem.p_cDsgMemBufferInit==vars.p_cDsgMemDefaultInit ||
       vars.ulBufferSize<56 || vars.ulBufferSize>256 ||
       b.offsets[0]>vars.ulBufferSize-4 ||
       !R2R_AddressReadable(reinterpret_cast<uintptr_t>(mem.p_cDsgMemBufferInit),vars.ulBufferSize))return false;
    uint32_t graph=0;
    if(!SafeReadMemory(mem.p_cDsgMemBufferInit+b.offsets[0],&graph,4) ||
       (graph!=b.oldGraph && graph!=b.desiredGraph && graph!=b.originalAssignedGraph))return false;
    out.base=mem.p_cDsgMemBufferInit;
    out.size=vars.ulBufferSize;
    out.offset=b.offsets[0];
    out.currentGraph=graph;
    return true;
}
// Persist the WHOLE owner's route, not only Graph_0. Test09 observed that
// seeding only Graph_0 made a reset load Graph_0=donor with WayPoint_7=NULL.
// Write only per-INSTANCE initialization buffers, never a model template.
static void R2R_MenuSeedBothInitGraphs() {
    R2R_MenuInitBlock blocks[2]={};
    const bool valid0=R2R_MenuGetInitBlock(0,blocks[0]);
    const bool valid1=R2R_MenuGetInitBlock(1,blocks[1]);
    bool distinct=valid0 && valid1 && blocks[0].base!=blocks[1].base;
    if(distinct) {
        // Different base addresses are not enough: the memory ranges must
        // not alias. In particular, do not write into a shared DSG template.
        const uintptr_t a=reinterpret_cast<uintptr_t>(blocks[0].base);
        const uintptr_t b=reinterpret_cast<uintptr_t>(blocks[1].base);
        distinct=(a+blocks[0].size<=b || b+blocks[1].size<=a);
    }
    if(!distinct) {
        char line[230]={};
        snprintf(line,sizeof(line),
            "[INIT-ROUTE-SKIP] Francesco=%d Baleine=%d distinct=%d (no shared/default write)",
            valid0?1:0,valid1?1:0,distinct?1:0);
        R2R_MenuLog(line);
        return;
    }
    for(unsigned int i=0;i<2;++i) {
        R2R_MenuRouteBinding& route=g_R2RMenuBindings[i];
        const R2R_MenuInitBlock& block=blocks[i];
        const unsigned long widths[4]={4,12,4,4};
        const void* values[4]={&route.desiredGraph,&route.initialTarget,
                               &route.initialRemaining,&route.firstWaypoint};
        const char* names[4]={"Graph_0","Vector_5","Int_6","WayPoint_7"};
        bool safe=route.enabled && route.firstWaypoint &&
                  R2R_MenuVecValid(route.initialTarget) &&
                  R2R_AddressReadable(static_cast<uintptr_t>(route.firstWaypoint),sizeof(WP_tdstWayPoint)) &&
                  R2R_AddressReadable(static_cast<uintptr_t>(route.desiredGraph),sizeof(WP_tdstGraph));
        for(unsigned int k=0;k<4 && safe;++k) {
            if(route.offsets[k]>=block.size || widths[k]>block.size-route.offsets[k] ||
               !R2R_Learn30MoveWritable(block.base+route.offsets[k],widths[k]))
                safe=false;
        }
        if(!safe) {
            route.resetSeeded=false;
            char line[190]={};
            snprintf(line,sizeof(line),"[INIT-ROUTE-SKIP] actor=%s reason=unsafe-field-layout",
                g_R2RMenuSpecs[i].personal);
            R2R_MenuLog(line);
            continue;
        }
        // All four fields were validated before any writes.
        for(unsigned int k=0;k<4;++k)
            std::memcpy(block.base+route.offsets[k],values[k],widths[k]);
        bool verified=true;
        for(unsigned int k=0;k<4;++k) {
            unsigned char result[12]={};
            if(!SafeReadMemory(block.base+route.offsets[k],result,widths[k]) ||
               std::memcmp(result,values[k],widths[k])!=0) {
                verified=false;
                char line[190]={};
                snprintf(line,sizeof(line),"[INIT-ROUTE-VERIFY-FAIL] actor=%s field=%s",
                    g_R2RMenuSpecs[i].personal,names[k]);
                R2R_MenuLog(line);
            }
        }
        route.resetSeeded=verified;
        char line[320]={};
        snprintf(line,sizeof(line),
            "[INIT-ROUTE] actor=%s graph=0x%08X firstWP=0x%08X remaining=%d seeded=%d fields=Graph_0,Vector_5,Int_6,WayPoint_7",
            g_R2RMenuSpecs[i].personal,route.desiredGraph,route.firstWaypoint,
            route.initialRemaining,route.resetSeeded?1:0);
        R2R_MenuLog(line);
    }
}
// Walk the REAL linked actor lists periodically. Actors can disappear and be
// reconstructed (sometimes at their old original spawn coordinates), which
// invalidates a one-shot actor pointer and its DSG buffer.
static bool R2R_MenuRefreshGraphActors(bool& changed0,bool& changed1){
    changed0=changed1=false;
    HIE_tdstSuperObject* before0=g_R2RMenuActors[0].object;
    HIE_tdstSuperObject* before1=g_R2RMenuActors[1].object;
    R2R_MenuEnemyActor cache[8]={};
    std::memcpy(cache,g_R2RMenuActors,sizeof(cache));
    std::memset(g_R2RMenuActors,0,sizeof(g_R2RMenuActors));
    if (g_R2RMenuWorld) R2R_MenuWalk(g_R2RMenuWorld,0);
    if (GAM_g_p_stInactiveDynamicWorld && *GAM_g_p_stInactiveDynamicWorld)
        R2R_MenuWalk(*GAM_g_p_stInactiveDynamicWorld,0);
    changed0=(before0!=g_R2RMenuActors[0].object && g_R2RMenuActors[0].object);
    changed1=(before1!=g_R2RMenuActors[1].object && g_R2RMenuActors[1].object);
    // The six non-graph actors are not re-randomized by this guard.
    for(int i=2;i<8;++i)if(!g_R2RMenuActors[i].object)g_R2RMenuActors[i]=cache[i];
    return g_R2RMenuActors[0].object && g_R2RMenuActors[1].object;
}
// Must NEVER be invoked on the first frame of the actor returning to its
// native spawn: Rayman's AI calls fn_p_stKillPersoAndClearVariableProcedure1
// at the end of both route scripts. That instance may still be in teardown.
// Wait for at least 30 complete engine ticks before any attempt to reattach.
static bool R2R_MenuDeferredRespawn(unsigned int idx, R2R_MenuEnemyActor& a,
                                   const MTH3D_tdstVector& current,
                                   const MTH3D_tdstVector& desired,
                                   const MTH3D_tdstVector& old) {
    R2R_MenuRouteBinding& b=g_R2RMenuBindings[idx];
    const char* label=g_R2RMenuSpecs[idx].personal;
    ++b.respawnWait;
    if (b.respawnSeenObject != a.object) {
        b.respawnSeenObject=a.object;
        b.respawnWait=0; // newly allocated actor also needs a grace period
        R2R_MenuLog(idx==0 ?
            "[RESPAWN-OBJECT] actor=YAM_francesco instance-changed; waiting for stable AI" :
            "[RESPAWN-OBJECT] actor=YAM_Baleine_I1 instance-changed; waiting for stable AI");
    }
    if (b.respawnWait == 1 || b.respawnWait == 15 || b.respawnWait == 30) {
        char line[220]={};
        snprintf(line,sizeof(line),"[RESPAWN-WAIT] actor=%s frames=%u pos=%.2f,%.2f,%.2f",
            label,b.respawnWait,current.x,current.y,current.z);
        R2R_MenuLog(line);
    }
    b.lastPosition=current;
    b.positionKnown=true;
    if (b.respawnWait < 30 || (b.respawnWait%10)!=0) return false;

    // If the object has already moved away or its layout is still changing,
    // do NOT change old pointers/physics. Let the engine own the lifecycle.
    if (R2R_MenuDistance(current,old)>12.0f) {
        R2R_MenuLog(idx==0 ?
            "[RESPAWN-SKIP] actor=YAM_francesco no longer near native slot" :
            "[RESPAWN-SKIP] actor=YAM_Baleine_I1 no longer near native slot");
        b.respawnPending=false;
        b.positionKnown=false;
        // The player may be watching the native actor continue its own
        // route: stop retrying in this run, and report the conflict safely.
        b.waypointConflictSuspended=true;
        R2R_MenuLog(idx==0 ?
            "[RESPAWN-UNRESOLVED] actor=YAM_francesco retaining native travel until next lifecycle" :
            "[RESPAWN-UNRESOLVED] actor=YAM_Baleine_I1 retaining native travel until next lifecycle");
        return false;
    }
    R2R_MenuEnemyNav nav={};
    // Test09 confirmed: Graph_0 stays assigned, but WayPoint_7 is zero after
    // a native reset. This controlled, delayed call may recover that case.
    if (!R2R_MenuReadGraphNav(a,nav,label,true)) {
        ++b.respawnProbeFailures;
        return false;
    }
    uint32_t seenGraph=0, seenWaypoint=0;
    std::memcpy(&seenGraph,nav.data[0],4);
    std::memcpy(&seenWaypoint,nav.data[3],4);
    if(!seenWaypoint) {
        char line[220]={};
        snprintf(line,sizeof(line),
            "[RESPAWN-EMPTY-WP] actor=%s graph=0x%08X donorWP=0x%08X safeWait=%u",
            label,seenGraph,b.firstWaypoint,b.respawnWait);
        R2R_MenuLog(line);
    }
    if (seenGraph!=b.oldGraph && seenGraph!=b.desiredGraph && seenGraph!=b.originalAssignedGraph) {
        char line[185]={};
        snprintf(line,sizeof(line),"[RESPAWN-WAIT] actor=%s unknown-graph=0x%08X",label,seenGraph);
        R2R_MenuLog(line);
        return false;
    }
    // A valid donor waypoint may not appear in m_hListOfNode in this build.
    // Test 08 proved the old 'membership == 1' gate is false for the first
    // donor waypoint, even though this exact pointer drove the first path.
    // Preserve it if it is still readable in this loaded world.
    const int firstWpBelongs=R2R_MenuWaypointOnGraph(b.desiredGraph,b.firstWaypoint);
    const bool donorWpReadable=b.firstWaypoint &&
        R2R_AddressReadable(static_cast<uintptr_t>(b.firstWaypoint),sizeof(WP_tdstWayPoint));
    if (!donorWpReadable || !R2R_MenuVecValid(b.initialTarget) ||
        !R2R_AddressReadable(static_cast<uintptr_t>(b.desiredGraph),sizeof(WP_tdstGraph))) {
        if (b.respawnWait==30 || b.respawnWait%120==0) {
            char line[260]={};
            snprintf(line,sizeof(line),"[RESPAWN-GATE] actor=%s stage=unreadable-donor waypoint=0x%08X membership=%d",
                label,b.firstWaypoint,firstWpBelongs);
            R2R_MenuLog(line);
        }
        return false;
    }
    // The original graph can be emptied at route end. Never reattach to
    // it: build a private full graph from pre-reset captured nodes instead.
    if(!R2R_MenuEnsureDurableGraph(idx)) {
        ++b.respawnProbeFailures;
        if(b.respawnWait==30 || b.respawnWait%120==0)
            R2R_MenuLog("[RESPAWN-GATE] private-route-unavailable; no unsafe reattachment");
        return false;
    }
    if(b.respawnWait==30){
        char line[240]={};
        snprintf(line,sizeof(line),"[RESPAWN-DONOR] actor=%s firstWP=0x%08X membership=%d readable=1 (initial donor successfully used)",
            label,b.firstWaypoint,firstWpBelongs);
        R2R_MenuLog(line);
        // Re-seed the individual reset source if actor was reconstructed.
        R2R_MenuSeedBothInitGraphs();
    }
    MTH3D_tdstVector local={};
    R2R_MenuPhysics physics={};
    R2R_MenuCursor cursor={};
    const char* blockedStage=nullptr;
    if (!R2R_MenuLocalTarget(a,desired,local)) blockedStage="local-position";
    else if (!R2R_MenuPreparePhysics(a,physics,label)) blockedStage="physics";
    else if (!R2R_MenuReadCursor(a,cursor,label)) blockedStage="cursor";
    if (blockedStage) {
        if (b.respawnWait==30 || b.respawnWait%120==0) {
            char line[200]={};
            snprintf(line,sizeof(line),"[RESPAWN-GATE] actor=%s stage=%s wait=%u",
                label,blockedStage,b.respawnWait);
            R2R_MenuLog(line);
        }
        return false;
    }
    MTH3D_tdstVector direction={};
    const float dx=b.initialTarget.x-desired.x;
    const float dy=b.initialTarget.y-desired.y;
    const float dz=b.initialTarget.z-desired.z;
    const float len=std::sqrt(dx*dx+dy*dy+dz*dz);
    if(!std::isfinite(len))return false;
    if(len>.001f){const float v=nav.speed/len; direction={dx*v,dy*v,dz*v};}
    if(!R2R_MenuVecValid(direction))return false;
    // The entire actor was rediscovered, so these offsets belong to the new
    // DSG buffer, not the possibly destroyed previous instance's DSG buffer.
    std::memcpy(nav.buffer+nav.offsets[0],&b.desiredGraph,4);
    std::memcpy(nav.buffer+nav.offsets[3],&b.firstWaypoint,4);
    std::memcpy(nav.buffer+nav.offsets[1],&b.initialTarget,12);
    std::memcpy(nav.buffer+nav.offsets[2],&b.initialRemaining,4);
    for(unsigned int i=0;i<2;++i)
        std::memcpy(nav.buffer+nav.steeringOffsets[i],&direction,12);
    if(cursor.ptr){
        cursor.original.m_hPath=reinterpret_cast<WP_tdstGraph*>(uintptr_t(b.desiredGraph));
        cursor.original.m_lIndex=b.initialCursorIndex;
        *cursor.ptr=cursor.original;
    }
    const MTH3D_tdstVector delta={desired.x-current.x,desired.y-current.y,desired.z-current.z};
    R2R_MenuPhysicsCommit(physics,delta);
    R2R_MenuCommit(a,desired,local);
    b.dsgBuffer=nav.buffer;
    for(unsigned int k=0;k<4;++k)b.offsets[k]=nav.offsets[k];
    for(unsigned int k=0;k<2;++k)b.steeringOffsets[k]=nav.steeringOffsets[k];
    b.ownSpeed=nav.speed;
    b.lastObject=a.object;
    b.lastPosition=desired;
    b.positionKnown=true;
    b.respawnPending=false;
    b.consecutiveForeignWaypointFrames=0;
    b.waypointConflictSuspended=false;
    b.postReattachActive=true;
    b.postReattachFrames=0;
    b.postWpObserved=false;
    b.postWpHadValue=false;
    b.postWpLossLogged=false;
    ++b.relocatedRespawns;
    ++b.repairs;
    char line[250]={};
    snprintf(line,sizeof(line),"[RESPAWN-REATTACH] actor=%s waited=%u oldGraph=0x%08X newGraph=0x%08X repairs=%u",
        label,b.respawnWait,seenGraph,b.desiredGraph,b.repairs);
    R2R_MenuLog(line);
    return true;
}
// Test 13 is OBSERVATION ONLY. The Test 10 reattachment and its crash
// protections are unchanged. Diagnose whether waypoint loss is path progress,
// a script behavior change, or an inactive actor after a route-end kill.
static const char* R2R_MenuWorldStatus(const HIE_tdstSuperObject* ptr) {
    if (!ptr) return "null";
    HIE_tdstSuperObject* active=(GAM_g_p_stDynamicWorld ? *GAM_g_p_stDynamicWorld : nullptr);
    HIE_tdstSuperObject* inactive=(GAM_g_p_stInactiveDynamicWorld ? *GAM_g_p_stInactiveDynamicWorld : nullptr);
    const HIE_tdstSuperObject* node=ptr;
    for(unsigned int depth=0;node && depth<64;++depth) {
        if(node==active) return "active";
        if(node==inactive) return "inactive";
        HIE_tdstSuperObject snapshot={};
        if(!SafeReadMemory(node,&snapshot,sizeof(snapshot))) return "unreadable";
        if(snapshot.hFatherDyn==node) return "cycle";
        node=snapshot.hFatherDyn;
    }
    return "unknown";
}
static void R2R_MenuPostRouteDetail(unsigned int idx,
    const R2R_MenuEnemyActor& a,unsigned int n,bool waypointLost) {
    const R2R_MenuRouteBinding& b=g_R2RMenuBindings[idx];
    const char* label=g_R2RMenuSpecs[idx].personal;
    uint32_t graph=0,wp=0; int remaining=-9999;
    MTH3D_tdstVector target={};
    const bool graphOK=b.dsgBuffer && SafeReadMemory(b.dsgBuffer+b.offsets[0],&graph,4);
    const bool wpOK=b.dsgBuffer && SafeReadMemory(b.dsgBuffer+b.offsets[3],&wp,4);
    const bool countOK=b.dsgBuffer && SafeReadMemory(b.dsgBuffer+b.offsets[2],&remaining,4);
    const bool targetOK=b.dsgBuffer && SafeReadMemory(b.dsgBuffer+b.offsets[1],&target,12);
    WP_tdstMSWay cursor={};
    const bool cursorOK=a.actor && a.actor->hMSWay && SafeReadMemory(a.actor->hMSWay,&cursor,sizeof(cursor));
    AI_tdstBrain brain={}; AI_tdstMind mind={}; AI_tdstIntelligence intel={};
    bool mindOK=a.actor && a.actor->hBrain && SafeReadMemory(a.actor->hBrain,&brain,sizeof(brain)) &&
        brain.p_stMind && SafeReadMemory(brain.p_stMind,&mind,sizeof(mind));
    const bool intelOK=mindOK && mind.p_stIntelligence &&
        SafeReadMemory(mind.p_stIntelligence,&intel,sizeof(intel));
    HIE_tdstSuperObject obj={};
    const bool objectOK=a.object && SafeReadMemory(a.object,&obj,sizeof(obj));
    // Two entries keep each log line comfortably below the 600-char buffer.
    char s[460]={};
    snprintf(s,sizeof(s),
       "[ROUTE-CYCLE] actor=%s frames=%u event=%s world=%s graph=0x%08X graphOK=%d "
       "wp=0x%08X wpOK=%d remaining=%d countOK=%d cursorPath=0x%08X cursorIndex=%ld "
       "cursorOK=%d activeIntel=0x%08X intelOK=%d flags=0x%08X objectOK=%d",
       label,n,waypointLost?"WP-LOST":"SAMPLE",R2R_MenuWorldStatus(a.object),
       graph,graphOK?1:0,wp,wpOK?1:0,remaining,countOK?1:0,
       cursorOK?static_cast<unsigned int>(reinterpret_cast<uintptr_t>(cursor.m_hPath)):0u,
       cursorOK?cursor.m_lIndex:-9999L,cursorOK?1:0,
       intelOK?static_cast<unsigned int>(reinterpret_cast<uintptr_t>(intel.p_stCurrentComport)):0u,
       intelOK?1:0,objectOK?static_cast<unsigned int>(obj.ulFlags):0u,objectOK?1:0);
    R2R_MenuLog(s);
    char s2[285]={};
    snprintf(s2,sizeof(s2),
       "[ROUTE-TARGET] actor=%s frames=%u desiredGraph=0x%08X target=%.2f,%.2f,%.2f "
       "targetOK=%d currentComport=0x%08X",
       label,n,b.desiredGraph,target.x,target.y,target.z,targetOK?1:0,
       intelOK?static_cast<unsigned int>(reinterpret_cast<uintptr_t>(intel.p_stCurrentComport)):0u);
    R2R_MenuLog(s2);
}
// -------------------------------------------------------------------------
// MENU TEST 13: READ-ONLY WAYPOINT TRANSITION INSPECTOR.
// Test 12 showed the counter decreases from 7 to 6 at first node, while
// NETWORK_GetWPAIndex(NETWORK_IncrementIndex(1)) leaves WayPoint_7=null.
// Inspect path anchors and MSWay without assuming that raw graph nodes are
// safe to use for navigation. DO NOT WRITE to an actor or graph here.
// -------------------------------------------------------------------------
static void R2R_MenuInspectPathGraph(const char* actorName,
    const char* which, uint32_t graphRaw, uint32_t firstWP, unsigned int frame) {
    char line[400]={};
    WP_tdstGraph graph={};
    if(!graphRaw || !SafeReadMemory(reinterpret_cast<const WP_tdstGraph*>(uintptr_t(graphRaw)),
                                    &graph,sizeof(graph))) {
        snprintf(line,sizeof(line),
            "[PATH-GRAPH] actor=%s frame=%u role=%s graph=0x%08X status=unreadable",
            actorName,frame,which,graphRaw);
        R2R_MenuLog(line);
        return;
    }
    const auto& anchor=graph.m_hListOfNode;
    const uintptr_t head=reinterpret_cast<uintptr_t>(anchor.hFirstElementDyn);
    const uintptr_t tail=reinterpret_cast<uintptr_t>(anchor.hLastElementDyn);
    const int member=R2R_MenuWaypointOnGraph(graphRaw,firstWP);
    snprintf(line,sizeof(line),
        "[PATH-GRAPH] actor=%s frame=%u role=%s graph=0x%08X nodes=%ld head=0x%08X tail=0x%08X firstWP=0x%08X member=%d",
        actorName,frame,which,graphRaw,static_cast<long>(anchor.lNbOfElementsDyn),
        static_cast<unsigned int>(head),static_cast<unsigned int>(tail),firstWP,member);
    R2R_MenuLog(line);
    if(anchor.lNbOfElementsDyn<=0 || anchor.lNbOfElementsDyn>256 || !head) {
        R2R_MenuLog("[PATH-NODE-SKIP] Graph has empty/untrusted linked-node anchor; no waypoint inference.");
        return;
    }
    WP_tdstGraphNode* node=anchor.hFirstElementDyn;
    const long wanted=(std::min)(anchor.lNbOfElementsDyn,12L);
    for(long i=0;i<wanted && node;++i) {
        WP_tdstGraphNode n={};
        if(!SafeReadMemory(node,&n,sizeof(n))) {
            snprintf(line,sizeof(line),
                "[PATH-NODE-STOP] actor=%s frame=%u role=%s index=%ld reason=unreadable-node",
                actorName,frame,which,i);
            R2R_MenuLog(line);
            return;
        }
        const uint32_t ptr=static_cast<uint32_t>(reinterpret_cast<uintptr_t>(n.m_hWayPoint));
        WP_tdstWayPoint w={};
        const bool readable=n.m_hWayPoint && SafeReadMemory(n.m_hWayPoint,&w,sizeof(w));
        snprintf(line,sizeof(line),
            "[PATH-NODE] actor=%s frame=%u role=%s index=%ld node=0x%08X wp=0x%08X wpOK=%d coords=%.2f,%.2f,%.2f isInitial=%d",
            actorName,frame,which,i,static_cast<unsigned int>(reinterpret_cast<uintptr_t>(node)),
            ptr,readable?1:0,readable?w.m_stVertex.x:0.0f,
            readable?w.m_stVertex.y:0.0f,readable?w.m_stVertex.z:0.0f,
            ptr==firstWP?1:0);
        R2R_MenuLog(line);
        if(!n.hNextBrotherDyn || n.hNextBrotherDyn==node) break;
        node=n.hNextBrotherDyn;
    }
}
static void R2R_MenuInspectWaypointTransition(unsigned int idx,
    const R2R_MenuEnemyActor& actor, unsigned int frame) {
    if(idx>1) return;
    const R2R_MenuRouteBinding& b=g_R2RMenuBindings[idx];
    const char* name=g_R2RMenuSpecs[idx].personal;
    WP_tdstMSWay cursor={};
    const bool valid=actor.actor && actor.actor->hMSWay &&
        SafeReadMemory(actor.actor->hMSWay,&cursor,sizeof(cursor));
    char line[330]={};
    snprintf(line,sizeof(line),
       "[PATH-CURSOR-INSPECT] actor=%s frame=%u cursorOK=%d cursorPath=0x%08X index=%ld circular=%d desired=0x%08X native=0x%08X",
       name,frame,valid?1:0,
       valid?static_cast<uint32_t>(reinterpret_cast<uintptr_t>(cursor.m_hPath)):0u,
       valid?cursor.m_lIndex:-9999L,valid?static_cast<int>(cursor.m_bIsCircular):-1,
       b.desiredGraph,b.oldGraph);
    R2R_MenuLog(line);
    R2R_MenuInspectPathGraph(name,"assigned",b.desiredGraph,b.firstWaypoint,frame);
    R2R_MenuInspectPathGraph(name,"native",b.oldGraph,b.firstWaypoint,frame);
}

// TEST 14: A valid network must have a traversable node list when its AI
// advances from one waypoint to another. The assigned whale graph had
// nodes=0/head!=null/tail=null after reset in Test 13. This observer
// determines whether it is born empty or emptied later. NEVER MODIFY GRAPH.
static void R2R_MenuGraphLifecycleProbe(const char* phase, unsigned int frame) {
    if (!g_R2RMenuGraphMoved) return;
    const bool sample = frame==1u || frame==5u || frame==25u || frame==90u ||
        frame==600u || frame==1200u || frame==1800u || frame==2400u ||
        frame==3600u || (frame>3600u && frame%1800u==0u);
    for(unsigned int idx=0;idx<2;++idx) {
        const R2R_MenuRouteBinding& b=g_R2RMenuBindings[idx];
        if(!b.enabled || !b.desiredGraph) continue;
        WP_tdstGraph g={};
        const bool read=SafeReadMemory(
            reinterpret_cast<const WP_tdstGraph*>(uintptr_t(b.desiredGraph)),
            &g,sizeof(g));
        const long count=read?static_cast<long>(g.m_hListOfNode.lNbOfElementsDyn):-10001L;
        const uint32_t head=read?static_cast<uint32_t>(reinterpret_cast<uintptr_t>(g.m_hListOfNode.hFirstElementDyn)):0u;
        const uint32_t tail=read?static_cast<uint32_t>(reinterpret_cast<uintptr_t>(g.m_hListOfNode.hLastElementDyn)):0u;
        const bool changed = count!=g_R2RMenuLastGraphNodeCount[idx] ||
            head!=g_R2RMenuLastGraphHead[idx] || tail!=g_R2RMenuLastGraphTail[idx];
        if(sample || changed) {
            char s[350]={};
            snprintf(s,sizeof(s),
                "[GRAPH-LIFECYCLE] phase=%s frame=%u actor=%s assigned=0x%08X read=%d nodes=%ld head=0x%08X tail=0x%08X firstWP=0x%08X consistent=%d changed=%d",
                phase?phase:"?",frame,g_R2RMenuSpecs[idx].personal,
                b.desiredGraph,read?1:0,count,head,tail,b.firstWaypoint,
                read && count>0 && count<=256 && head && tail ? 1 : 0,
                changed?1:0);
            R2R_MenuLog(s);
        }
        g_R2RMenuLastGraphNodeCount[idx]=count;
        g_R2RMenuLastGraphHead[idx]=head;
        g_R2RMenuLastGraphTail[idx]=tail;
    }
}
static void R2R_MenuObservePostReattach(unsigned int idx,
    const R2R_MenuEnemyActor& a,const MTH3D_tdstVector& current,
    const MTH3D_tdstVector& desired,const MTH3D_tdstVector& old) {
    R2R_MenuRouteBinding& b=g_R2RMenuBindings[idx];
    if (!b.postReattachActive) return;
    if (b.lastObject!=a.object) {
        char line[190]={};
        snprintf(line,sizeof(line),"[POST-REATTACH-NEW-INSTANCE] actor=%s observedFrames=%u",
                 g_R2RMenuSpecs[idx].personal,b.postReattachFrames);
        R2R_MenuLog(line);
        b.postReattachActive=false;
        return;
    }
    ++b.postReattachFrames;
    const unsigned int n=b.postReattachFrames;
    uint32_t wp=0;
    const bool wpOK=b.dsgBuffer && SafeReadMemory(b.dsgBuffer+b.offsets[3],&wp,sizeof(wp));
    const bool present=wpOK && wp!=0;
    const bool transition=b.postWpObserved && b.postWpHadValue && wpOK && !present;
    if(transition && !b.postWpLossLogged) {
        R2R_MenuGraphLifecycleProbe("waypoint-lost",g_R2RMenuGraphAuditFrames);
        b.postWpLossLogged=true;
        char s[210]={};
        snprintf(s,sizeof(s),"[POST-WP-LOST] actor=%s frames=%u after reattach (no writes)",
                 g_R2RMenuSpecs[idx].personal,n);
        R2R_MenuLog(s);
    }
    if(wpOK) {b.postWpObserved=true;b.postWpHadValue=present;}
    const bool sampled = n==1 || n==5 || n==30 || n==90 || n==105 || n==120 ||
        n==135 || n==150 || n==165 || n==180 || n==210 || n==240 ||
        n==300 || n==450 || n==600 || n==900;
    if(!sampled && !transition)return;
    uint32_t graph=0;
    const bool graphOK=b.dsgBuffer &&
        SafeReadMemory(b.dsgBuffer+b.offsets[0],&graph,sizeof(graph));
    char line[450]={};
    snprintf(line,sizeof(line),
        "[POST-REATTACH] actor=%s frames=%u pos=%.2f,%.2f,%.2f "
        "distanceToNewSlot=%.2f distanceToOldSlot=%.2f "
        "graph=0x%08X desiredGraph=0x%08X graphOK=%d graphMatch=%d "
        "wp=0x%08X wpOK=%d wpPresent=%d",
        g_R2RMenuSpecs[idx].personal,n,current.x,current.y,current.z,
        R2R_MenuDistance(current,desired),R2R_MenuDistance(current,old),
        graph,b.desiredGraph,graphOK?1:0,(graphOK && graph==b.desiredGraph)?1:0,
        wp,wpOK?1:0,present?1:0);
    R2R_MenuLog(line);
    R2R_MenuPostRouteDetail(idx,a,n,transition);
    // Compare the graph layout before reaching the first node and at loss.
    if(n==1 || n==150 || transition)
        R2R_MenuInspectWaypointTransition(idx,a,n);
    if (n==900) {
        b.postReattachActive=false;
        R2R_MenuLog("[POST-REATTACH-COMPLETE] completed 900-frame read-only observation");
    }
}
// A persistent, actor-specific assignment: Francesco *always* owns the
// baleine graph while displaced and vice versa. Does not freeze legitimate
// progress within the correct graph; only repairs mismatch/reinitialization.
static void R2R_MenuMaintainRoute(unsigned int idx,bool newActor){
    if(idx>1)return;
    R2R_MenuRouteBinding& b=g_R2RMenuBindings[idx];
    if(!b.enabled)return;
    R2R_MenuEnemyActor& a=g_R2RMenuActors[idx];
    if(!a.object||!a.actor||!a.global||
       !R2R_AddressReadable(reinterpret_cast<uintptr_t>(a.global),sizeof(*a.global)))return;
    const char* label=g_R2RMenuSpecs[idx].personal;
    const MTH3D_tdstVector desired=idx==0?g_R2RMenuWhaleSlot:g_R2RMenuFrancescoSlot;
    const MTH3D_tdstVector old=idx==0?g_R2RMenuFrancescoSlot:g_R2RMenuWhaleSlot;
    MTH3D_tdstVector current={};
    if(!SafeReadMemory(&a.global->stPos,&current,sizeof(current))||!R2R_MenuVecValid(current))return;
    // Diagnostic only: this has no influence on route maintenance.
    R2R_MenuObservePostReattach(idx,a,current,desired,old);
    if(b.respawnPending) {
        R2R_MenuDeferredRespawn(idx,a,current,desired,old);
        return; // Even after a successful rebind, don't touch the same frame again.
    }
    // Re-read the validated DSG layout when the actor is newly instantiated,
    // so a fresh AI buffer cannot leave us writing to freed memory.
    if(newActor || b.lastObject!=a.object){
        R2R_MenuEnemyNav now={};
        if(!R2R_MenuReadGraphNav(a,now,label))return;
        b.dsgBuffer=now.buffer;
        for(unsigned int k=0;k<4;++k)b.offsets[k]=now.offsets[k];
        for(unsigned int k=0;k<2;++k)b.steeringOffsets[k]=now.steeringOffsets[k];
        b.ownSpeed=now.speed;
        b.lastObject=a.object;
        b.positionKnown=false;
        b.consecutiveForeignWaypointFrames=0;
        b.waypointConflictSuspended=false;
        char line[160]={};snprintf(line,sizeof(line),"[PATH-REATTACH] actor=%s newActor=%d",label,1);
        R2R_MenuLog(line);
    }
    if(!b.dsgBuffer||!R2R_Learn30MoveWritable(b.dsgBuffer,56))return;
    uint32_t currentGraph=0,currentWp=0;
    if(!SafeReadMemory(b.dsgBuffer+b.offsets[0],&currentGraph,4) ||
       !SafeReadMemory(b.dsgBuffer+b.offsets[3],&currentWp,4))return;
    int belongs=R2R_MenuWaypointOnGraph(b.desiredGraph,currentWp);
    const bool graphWrong=currentGraph!=b.desiredGraph;
    const int nativeBelongs=R2R_MenuWaypointOnGraph(b.oldGraph,currentWp);
    // False-negative donor membership (Test 08) is not proof of a bad path.
    // Only replace a WP confidently present on the old graph but absent on
    // the assigned graph. A graph reset is fixed as a whole route unit.
    const bool wpWrong=belongs==0 && nativeBelongs==1;
    bool cursorWrong=false;
    WP_tdstMSWay cursor={};
    WP_tdstMSWay* cursorPtr=(a.actor&&a.actor->hMSWay)?a.actor->hMSWay:nullptr;
    if(cursorPtr && SafeReadMemory(cursorPtr,&cursor,sizeof(cursor)))
        cursorWrong=cursor.m_hPath!=reinterpret_cast<WP_tdstGraph*>(uintptr_t(b.desiredGraph));
    else cursorPtr=nullptr;
    // Detect an ENGINE respawn/teleport, not ordinary travel along a route.
    // A distance jump towards the character's OWN native spawn indicates the
    // engine has restored the old slot after route completion.
    const float homeDistance=R2R_MenuDistance(current,old);
    const float distanceToNewSlot=R2R_MenuDistance(current,desired);
    const float jump=b.positionKnown?R2R_MenuDistance(current,b.lastPosition):0.f;
    const bool returnedToOldSlot=homeDistance<5.f && distanceToNewSlot>12.f &&
        (newActor || graphWrong || (b.positionKnown && jump>9.f));
    if(returnedToOldSlot){
        if(b.postReattachActive) {
            char line[180]={};
            snprintf(line,sizeof(line),"[POST-REATTACH-NEXT-RESET] actor=%s observedFrames=%u",
                     label,b.postReattachFrames);
            R2R_MenuLog(line);
            b.postReattachActive=false;
        }
        // Do not write to the object here. AI route-end scripts kill/despawn
        // the actor, which may be freed immediately after this callback.
        b.respawnPending=true;
        b.respawnWait=0;
        b.respawnSeenObject=a.object;
        b.respawnProbeFailures=0;
        b.lastPosition=current;
        b.positionKnown=true;
        char line[230]={};
        snprintf(line,sizeof(line),"[RESPAWN-DEFER] actor=%s graphReset=%d waypointReset=%d jumped=%.2f safeWait=30",
            label,graphWrong?1:0,wpWrong?1:0,jump);
        R2R_MenuLog(line);
        return;
    }
    // Detect repeat contention: if the game's script rewrites a foreign WP
    // immediately after our last correction, three consecutive frames are
    // enough to prove one-time DSG edits cannot permanently replace its path.
    if (wpWrong && !graphWrong && !cursorWrong && !newActor) {
        if (b.consecutiveForeignWaypointFrames < 1000000u)
            ++b.consecutiveForeignWaypointFrames;
        if (b.consecutiveForeignWaypointFrames >= 3 && !b.waypointConflictSuspended) {
            b.waypointConflictSuspended=true;
            char line[310]={};
            snprintf(line,sizeof(line),
                "[WAYPOINT-CONFLICT] actor=%s foreignWP=0x%08X desiredGraph=0x%08X nativeGraph=0x%08X nativeMember=%d cursorIndex=%ld; stop continuous writes",
                label,currentWp,b.desiredGraph,b.oldGraph,
                R2R_MenuWaypointOnGraph(b.oldGraph,currentWp),cursor.m_lIndex);
            R2R_MenuLog(line);
        }
    } else if (!wpWrong) {
        b.consecutiveForeignWaypointFrames=0;
    }
    if (b.waypointConflictSuspended && !newActor) {
        // A graph pointer can remain correct while the native AI pushes its
        // own waypoint every frame. The only safe default is read-only
        // observation until respawn or a new actor instance.
        if (b.observedFrames > 0 && b.observedFrames % 600 == 0 &&
            b.lastWaypointConflictNotice != b.observedFrames) {
            b.lastWaypointConflictNotice=b.observedFrames;
            char line[265]={};
            snprintf(line,sizeof(line),
                "[WAYPOINT-OBSERVE] actor=%s graph=0x%08X wp=0x%08X desiredMembership=%d nativeMembership=%d repairs=%u",
                label,currentGraph,currentWp,belongs,
                R2R_MenuWaypointOnGraph(b.oldGraph,currentWp),b.repairs);
            R2R_MenuLog(line);
        }
    } else if(graphWrong || wpWrong || cursorWrong || newActor){
        // The single graph pointer plus WayPoint, cached target, remaining
        // steps, MSWay and steering are reinstated as a coherent route unit.
        // We do NOT reset legitimate progress on a correct graph.
        const unsigned long minSize=(std::max)(b.offsets[3]+4,b.steeringOffsets[1]+12);
        if(!R2R_Learn30MoveWritable(b.dsgBuffer,minSize))return;
        std::memcpy(b.dsgBuffer+b.offsets[0],&b.desiredGraph,4);
        std::memcpy(b.dsgBuffer+b.offsets[3],&b.firstWaypoint,4);
        std::memcpy(b.dsgBuffer+b.offsets[1],&b.initialTarget,12);
        std::memcpy(b.dsgBuffer+b.offsets[2],&b.initialRemaining,4);
        MTH3D_tdstVector direction={};
        const float dx=b.initialTarget.x-current.x,dy=b.initialTarget.y-current.y,dz=b.initialTarget.z-current.z;
        const float len=std::sqrt(dx*dx+dy*dy+dz*dz);
        if(std::isfinite(len)&&len>.001f){const float v=b.ownSpeed/len; direction={dx*v,dy*v,dz*v};}
        std::memcpy(b.dsgBuffer+b.steeringOffsets[0],&direction,12);
        std::memcpy(b.dsgBuffer+b.steeringOffsets[1],&direction,12);
        if(cursorPtr){
            cursor.m_hPath=reinterpret_cast<WP_tdstGraph*>(uintptr_t(b.desiredGraph));
            cursor.m_lIndex=b.initialCursorIndex;
            *cursorPtr=cursor;
        }
        ++b.repairs;
        // Log each of first 12 repairs then periodically, not every frame.
        if(b.repairs<=12 || b.repairs%50==0){
            char line[280]={};
            snprintf(line,sizeof(line),"[PATH-REPAIR] actor=%s desired=%s graphReset=%d waypointReset=%d cursorReset=%d respawn=%d repairs=%u",
                label,idx==0?"YAM_Reso_Baleine":"YAM_Reso_Francesco",
                graphWrong?1:0,wpWrong?1:0,cursorWrong?1:0,0,b.repairs);
            R2R_MenuLog(line);
        }
    }
    b.lastPosition=current;
    b.positionKnown=true;
    ++b.observedFrames;
    if(b.observedFrames==90 || b.observedFrames==600 ||
       (b.observedFrames>600 && b.observedFrames%1800==0)){
        char line[270]={};
        snprintf(line,sizeof(line),"[PATH-STATUS] actor=%s frames=%u graph=0x%08X desired=0x%08X repairs=%u respawnRelocations=%u waypointGuard=%d initSeeded=%d",
            label,b.observedFrames,currentGraph,b.desiredGraph,b.repairs,b.relocatedRespawns,
            b.waypointConflictSuspended?1:0,b.resetSeeded?1:0);
        R2R_MenuLog(line);
    }
}
static void R2R_MenuMaintainAllRoutes(){
    if(!g_R2RMenuGraphMoved)return;
    ++g_R2RMenuGraphAuditFrames;
    R2R_MenuGraphLifecycleProbe("running",g_R2RMenuGraphAuditFrames);
    bool changed0=false,changed1=false;
    // The two scripts can kill their actors around 30 seconds. Rescan on
    // EVERY frame once nearing the end of their first path, not every 20.
    // Never trust a cached SuperObject/DSG pointer across a despawn.
    const bool lifecycleSensitive=
        g_R2RMenuBindings[0].respawnPending || g_R2RMenuBindings[1].respawnPending ||
        g_R2RMenuVerifyFrames >= 900;
    if(lifecycleSensitive || (g_R2RMenuVerifyFrames && g_R2RMenuVerifyFrames%20==0)){
        R2R_MenuRefreshGraphActors(changed0,changed1);
    }
    for(unsigned int i=0;i<2;++i){
        if(!g_R2RMenuActors[i].object){
            R2R_MenuRouteBinding& b=g_R2RMenuBindings[i];
            if(b.lastObject){
                if(b.postReattachActive) {
                    char trace[180]={};
                    snprintf(trace,sizeof(trace),"[POST-REATTACH-DESPAWN] actor=%s observedFrames=%u",
                             g_R2RMenuSpecs[i].personal,b.postReattachFrames);
                    R2R_MenuLog(trace);
                    b.postReattachActive=false;
                }
                char line[165]={};
                snprintf(line,sizeof(line),"[RESPAWN-DESPAWN] actor=%s pointer-gone; skip memory access",
                    g_R2RMenuSpecs[i].personal);
                R2R_MenuLog(line);
                b.lastObject=nullptr;
                b.dsgBuffer=nullptr;
                b.positionKnown=false;
                b.respawnPending=true;
                b.respawnWait=0;
                b.respawnSeenObject=nullptr;
            }
        }
    }
    R2R_MenuMaintainRoute(0,changed0);
    R2R_MenuMaintainRoute(1,changed1);
}
static void R2R_MenuApply() {
    int present=0;
    for(int i=0;i<8;++i) if(g_R2RMenuActors[i].object) ++present;
    FILE* f=R2R_MenuOpenReport("a");
    if(f) fprintf(f,"%s - EXPERIMENTAL MENU ACTOR SLOT RANDOMIZER\n"
        "Level=Menu Seed=%u Selected=%d/8\n"
        "Intact actors move; no model/Brain/anim/DSG schema replacement.\n"
        "Graph pair: four-field per-instance navigation reset seed + deferred reattachment.\n"
        "TEST 21: Test 19 private route fix + six-actor location cycle including Krabos.\n"
        "Repeated incompatible native-waypoint rewrites still trigger a circuit breaker.\n"
        "Krabos retains its TWO native isolated waypoints; only its physical location moves.\n\n",
        VERSION,g_R2RConfig.seed,present);
    if(present!=8) {
        if(f) {
            for(int i=0;i<8;++i) {
                if(!g_R2RMenuActors[i].object)
                    fprintf(f,"[MISSING] %s\n",g_R2RMenuSpecs[i].personal);
            }
            fclose(f);
        }
        g_R2RMenuApplied=true; return;
    }
    // Pair: Francesco <-> Whale. Both retain own AI, models and mechanics.
    bool graphMoved=false;
    R2R_MenuPhysics phys0={},phys1={};
    R2R_MenuCursor cursor0={},cursor1={};
    R2R_MenuEnemyNav nav0={},nav1={};
    MTH3D_tdstVector p0={},p1={};
    MTH3D_tdstVector steering0={},steering1={};
    if(R2R_MenuReadGraphNav(g_R2RMenuActors[0],nav0,g_R2RMenuSpecs[0].personal) &&
       R2R_MenuReadGraphNav(g_R2RMenuActors[1],nav1,g_R2RMenuSpecs[1].personal) &&
       R2R_MenuNamedGraph(nav0,"YAM_Reso_Francesco",g_R2RMenuSpecs[0].personal) &&
       R2R_MenuNamedGraph(nav1,"YAM_Reso_Baleine",g_R2RMenuSpecs[1].personal) &&
       R2R_MenuReadCursor(g_R2RMenuActors[0],cursor0,g_R2RMenuSpecs[0].personal) &&
       R2R_MenuReadCursor(g_R2RMenuActors[1],cursor1,g_R2RMenuSpecs[1].personal) &&
       R2R_MenuPreparePhysics(g_R2RMenuActors[0],phys0,g_R2RMenuSpecs[0].personal) &&
       R2R_MenuPreparePhysics(g_R2RMenuActors[1],phys1,g_R2RMenuSpecs[1].personal) &&
       R2R_MenuLocalTarget(g_R2RMenuActors[0], g_R2RMenuWhaleSlot, p0) &&
       R2R_MenuLocalTarget(g_R2RMenuActors[1], g_R2RMenuFrancescoSlot, p1) &&
       R2R_MenuPlanSteering(nav0,nav1,g_R2RMenuWhaleSlot,steering0) &&
       R2R_MenuPlanSteering(nav1,nav0,g_R2RMenuFrancescoSlot,steering1)) {
        // Read-only inspection BEFORE either actor's graph or cursor changes.
        // This is vital to distinguish a naturally empty whale network from
        // one cleared later by the game's end-of-path routine.
        if(f) fflush(f);
        uint32_t originalGraphFranc=0,originalGraphWhale=0;
        uint32_t originalWPFranc=0,originalWPWhale=0;
        std::memcpy(&originalGraphFranc,nav0.data[0],4);
        std::memcpy(&originalGraphWhale,nav1.data[0],4);
        std::memcpy(&originalWPFranc,nav0.data[3],4);
        std::memcpy(&originalWPWhale,nav1.data[3],4);
        R2R_MenuInspectPathGraph("YAM_francesco","native-pre-swap",
            originalGraphFranc,originalWPFranc,0);
        R2R_MenuInspectPathGraph("YAM_Baleine_I1","native-pre-swap",
            originalGraphWhale,originalWPWhale,0);
        // Cache both ORIGINAL slot-owner graph lists before route-end cleanup.
        // If copying fails, old Test14 behavior remains intact but the log
        // explains that no private network can be attached later.
        if(!R2R_MenuCaptureShadow(0,originalGraphWhale))
            R2R_MenuLog("[SHADOW-SKIP] actor=YAM_francesco source-network-capture-failed");
        if(!R2R_MenuCaptureShadow(1,originalGraphFranc))
            R2R_MenuLog("[SHADOW-SKIP] actor=YAM_Baleine_I1 source-network-capture-failed");
        // All graph, waypoint, target, speed and BOTH steering-vector offsets
        // are checked BEFORE writing. Original actors and behaviors remain intact.
        for(unsigned int i=0;i<4;++i){
            std::memcpy(nav0.buffer+nav0.offsets[i],nav1.data[i],nav0.sizes[i]);
            std::memcpy(nav1.buffer+nav1.offsets[i],nav0.data[i],nav1.sizes[i]);
        }
        for(unsigned int i=0;i<2;++i){
            std::memcpy(nav0.buffer+nav0.steeringOffsets[i],&steering0,sizeof(steering0));
            std::memcpy(nav1.buffer+nav1.steeringOffsets[i],&steering1,sizeof(steering1));
        }
        const MTH3D_tdstVector before0=g_R2RMenuActors[0].global->stPos;
        const MTH3D_tdstVector before1=g_R2RMenuActors[1].global->stPos;
        const MTH3D_tdstVector delta0={g_R2RMenuWhaleSlot.x-before0.x,
            g_R2RMenuWhaleSlot.y-before0.y,g_R2RMenuWhaleSlot.z-before0.z};
        const MTH3D_tdstVector delta1={g_R2RMenuFrancescoSlot.x-before1.x,
            g_R2RMenuFrancescoSlot.y-before1.y,g_R2RMenuFrancescoSlot.z-before1.z};
        uint32_t graph0=0,graph1=0;
        memcpy(&graph0,nav1.data[0],4); memcpy(&graph1,nav0.data[0],4);
        R2R_MenuCommitCursor(cursor0,cursor1,graph0);
        R2R_MenuCommitCursor(cursor1,cursor0,graph1);
        R2R_MenuPhysicsCommit(phys0,delta0);
        R2R_MenuPhysicsCommit(phys1,delta1);
        R2R_MenuCommit(g_R2RMenuActors[0],g_R2RMenuWhaleSlot,p0);
        R2R_MenuCommit(g_R2RMenuActors[1],g_R2RMenuFrancescoSlot,p1);
        graphMoved=true;g_R2RMenuGraphMoved=true;g_R2RMenuVerifyFrames=0;
        R2R_MenuBindRoute(0,nav0,nav1,cursor1);
        R2R_MenuBindRoute(1,nav1,nav0,cursor0);
        // Graph assignment must survive a future native DSG reset.
        R2R_MenuSeedBothInitGraphs();
        if(f){
            fprintf(f,"[POSITION-SWAP] actor=%s original=%.2f,%.2f,%.2f target=%.2f,%.2f,%.2f actual=%.2f,%.2f,%.2f\n",
                g_R2RMenuSpecs[0].personal,before0.x,before0.y,before0.z,
                g_R2RMenuWhaleSlot.x,g_R2RMenuWhaleSlot.y,g_R2RMenuWhaleSlot.z,
                g_R2RMenuActors[0].global->stPos.x,g_R2RMenuActors[0].global->stPos.y,g_R2RMenuActors[0].global->stPos.z);
            fprintf(f,"[POSITION-SWAP] actor=%s original=%.2f,%.2f,%.2f target=%.2f,%.2f,%.2f actual=%.2f,%.2f,%.2f\n",
                g_R2RMenuSpecs[1].personal,before1.x,before1.y,before1.z,
                g_R2RMenuFrancescoSlot.x,g_R2RMenuFrancescoSlot.y,g_R2RMenuFrancescoSlot.z,
                g_R2RMenuActors[1].global->stPos.x,g_R2RMenuActors[1].global->stPos.y,g_R2RMenuActors[1].global->stPos.z);
            fprintf(f,"[GRAPH-ASSIGN] %s -> YAM_Reso_Baleine; %s -> YAM_Reso_Francesco\n",
                g_R2RMenuSpecs[0].personal,g_R2RMenuSpecs[1].personal);
            fprintf(f,"[CURSOR] Francesco=%s Baleine=%s\n",cursor0.ptr?"updated":"absent",cursor1.ptr?"updated":"absent");
        }
        if(f) {
            uint32_t graphs[2]={}, waypoints[2]={};
            std::memcpy(&graphs[0],nav1.data[0],4);
            std::memcpy(&graphs[1],nav0.data[0],4);
            std::memcpy(&waypoints[0],nav1.data[3],4);
            std::memcpy(&waypoints[1],nav0.data[3],4);
            fprintf(f,"[GRAPH-SWAP] %s <-> %s; Graph_0, Vector_5, Int_6, WayPoint_7 transferred\n",
                g_R2RMenuSpecs[0].personal,g_R2RMenuSpecs[1].personal);
            fprintf(f,"[NAV-RESET] actor=%s newGraph=0x%08X newWP=0x%08X ownSpeed=%.2f Vector_3=%.3f,%.3f,%.3f Vector_4=%.3f,%.3f,%.3f\n",
                g_R2RMenuSpecs[0].personal,graphs[0],waypoints[0],nav0.speed,
                steering0.x,steering0.y,steering0.z,steering0.x,steering0.y,steering0.z);
            fprintf(f,"[NAV-RESET] actor=%s newGraph=0x%08X newWP=0x%08X ownSpeed=%.2f Vector_3=%.3f,%.3f,%.3f Vector_4=%.3f,%.3f,%.3f\n",
                g_R2RMenuSpecs[1].personal,graphs[1],waypoints[1],nav1.speed,
                steering1.x,steering1.y,steering1.z,steering1.x,steering1.y,steering1.z);
            fprintf(f,"[NAV-NOTE] WayPoint_7 is the DONOR's already initialized graph waypoint, not a new nearest-point engine query. Next AI tick controls the engine mechanic velocity.\n");
        }
    } else if(f) fprintf(f,"[GRAPH-SKIP] Francesco/Whale: unable to validate navigation or target; see [NAV-REJECT] above. Both actors unchanged.\n");

    // TEST 21: six-actor cycle including Krabos. Together with the proven
    // Francesco/whale graph+slot swap above, all EIGHT Menu actors are involved.
    // This is a POSITION exchange, never a model/brain/DSG swap. Krabos's
    // WayPoint_0/1 cannot be transferred to the non-graph ambient characters.
    int ids[6]={2,3,4,5,6,7};
    for(int i=5;i>0;--i) {
        const uint32_t dice=R2R_RollU32("Enemies.Menu.All8Cycle.Test21","Menu",
            0xE2121u+static_cast<unsigned int>(i));
        const int j=static_cast<int>(dice%static_cast<unsigned int>(i+1));
        const int t=ids[i]; ids[i]=ids[j]; ids[j]=t;
    }
    MTH3D_tdstVector desiredLocal[6]={};
    MTH3D_tdstVector before[6]={};
    MTH3D_tdstVector destination[6]={};
    R2R_MenuPhysics physics[6]={};
    bool canMove=true;
    // Validate every recipient and its physics BEFORE mutating ANY one of them.
    for(int i=0;i<6;++i) {
        R2R_MenuEnemyActor& actor=g_R2RMenuActors[ids[i]];
        const R2R_MenuEnemyActor& donor=g_R2RMenuActors[ids[(i+1)%6]];
        destination[i]=donor.native;
        if(!R2R_MenuLocalTarget(actor,destination[i],desiredLocal[i]) ||
           !R2R_MenuPreparePhysics(actor,physics[i],g_R2RMenuSpecs[ids[i]].personal) ||
           !actor.global ||
           !SafeReadMemory(&actor.global->stPos,&before[i],sizeof(before[i])) ||
           !R2R_MenuVecValid(before[i])) {
            canMove=false;
            if(f) fprintf(f,"[MENU-REMIX-REJECT] actor=%s reason=unsafe-matrix-or-physics\n",
                g_R2RMenuSpecs[ids[i]].personal);
            break;
        }
    }
    if (f) {
        fprintf(f,"[MENU-REMIX-MODE] mode=8-actors menu-only seed=%u pair=Francesco+Baleine cycle=6-including-Krabos\n",
            g_R2RConfig.seed);
        for(int i=0;i<6;++i) fprintf(f,"[MENU-REMIX-PLAN] actor=%s destinationActor=%s pos=%.2f,%.2f,%.2f\n",
            g_R2RMenuSpecs[ids[i]].personal,g_R2RMenuSpecs[ids[(i+1)%6]].personal,
            g_R2RMenuActors[ids[(i+1)%6]].native.x,
            g_R2RMenuActors[ids[(i+1)%6]].native.y,
            g_R2RMenuActors[ids[(i+1)%6]].native.z);
    }
    if(canMove) {
        for(int i=0;i<6;++i) {
            R2R_MenuEnemyActor& actor=g_R2RMenuActors[ids[i]];
            const MTH3D_tdstVector delta={destination[i].x-before[i].x,
                destination[i].y-before[i].y,destination[i].z-before[i].z};
            R2R_MenuPhysicsCommit(physics[i],delta);
            R2R_MenuCommit(actor,destination[i],desiredLocal[i]);
            if(ids[i]==7) {
                g_R2RMenuCrabRelocated=true;
                g_R2RMenuCrabDestination=destination[i];
            }
            if(f) fprintf(f,"[MENU-REMIX-MOVE] actor=%s destinationActor=%s pos=%.2f,%.2f,%.2f physics=%d\n",
                g_R2RMenuSpecs[ids[i]].personal,g_R2RMenuSpecs[ids[(i+1)%6]].personal,
                destination[i].x,destination[i].y,destination[i].z,physics[i].hasDynamics?1:0);
        }
    } else if(f) fprintf(f,"[MENU-REMIX-SKIP] all six relocations cancelled: no partial ambient/crab remix.\n");
    if(f) {
        fprintf(f,"[CRAB-WAYPOINTS] native-isolated WayPoint_0+WayPoint_1 preserved; remote slot may send Krabos towards its original route.\n");
        fprintf(f,"[SUMMARY] graphActorsMoved=%d ambientActorsMoved=%d crabMoved=%d totalActorsMoved=%d\n",
            graphMoved?2:0,canMove?5:0,g_R2RMenuCrabRelocated?1:0,
            (graphMoved?2:0)+(canMove?6:0));
        fprintf(f,"Observe [POSITION-VERIFY] and [CRAB-VERIFY] after 1/5/30/90 frames.\n");
        fclose(f);
    }
    g_R2RMenuAppliedSeed=g_R2RConfig.seed;
    g_R2RMenuApplied=true;
}
static void R2R_MenuEnemyTestTick() {
    if(!GAM_g_stEngineStructure || GAM_g_stEngineStructure->eEngineMode!=E_EM_ModePlaying ||
       _stricmp(GAM_g_stEngineStructure->szLevelName,"Menu")!=0 ||
       !GAM_g_p_stDynamicWorld || !*GAM_g_p_stDynamicWorld) {
        if(g_R2RMenuWorld) R2R_MenuReset(nullptr);
        R2R_MenuOffLevelDiagnostics();
        return;
    }
    g_R2RMenuOffLevelFrames = 0;
    HIE_tdstSuperObject* world=*GAM_g_p_stDynamicWorld;
    if(world!=g_R2RMenuWorld) {
        R2R_MenuReset(world);
        if(g_R2RConfig.enabled && g_R2RConfig.enemiesMenuTest)
            R2R_MenuLog("[WORLD] Menu loaded; starting 8-actor discovery.");
    }
    if(!g_R2RConfig.enabled || !g_R2RConfig.enemiesMenuTest) return;
    // Do not shuffle a second time after F5 within the same loaded world.
    // For fresh results, return to Menu or restart the game.
    if(g_R2RMenuApplied) {
        R2R_MenuVerifyPositions();
        R2R_MenuMaintainAllRoutes();
        if(!g_R2RMenuReported && g_R2RMenuAppliedSeed != g_R2RConfig.seed) {
            R2R_MenuLog("[NOTE] Seed changed mid-menu; reload Menu to reshuffle.");
            g_R2RMenuReported=true;
        }
        return;
    }
    ++g_R2RMenuFrames;
    if(g_R2RMenuFrames<25u) return;
    std::memset(g_R2RMenuActors,0,sizeof(g_R2RMenuActors));
    R2R_MenuWalk(world,0);
    if(GAM_g_p_stInactiveDynamicWorld && *GAM_g_p_stInactiveDynamicWorld)
        R2R_MenuWalk(*GAM_g_p_stInactiveDynamicWorld,0);
    int found=0; for(int i=0;i<8;++i) found+=(g_R2RMenuActors[i].object!=nullptr);
    if (g_R2RMenuFrames==25u || g_R2RMenuFrames==90u || g_R2RMenuFrames==179u) {
        char line[120] = {};
        snprintf(line, sizeof(line), "[SCAN] frames=%u found=%d/8", g_R2RMenuFrames, found);
        R2R_MenuLog(line);
    }
    if(found==8 || g_R2RMenuFrames>=180u) R2R_MenuApply();
}
