static void R2R_WorldRemixLog(const char* message,bool overwrite=false){
    char path[MAX_PATH]={};
    snprintf(path,sizeof(path),"%s",g_R2RConfigPath);
    char* slash=std::strrchr(path,'\\');
    if(!slash)slash=std::strrchr(path,'/');
    if(slash)++slash;
    else slash=path;
    const char* filename="Rayman2Randomizer_Learn10PositionsTest.txt";
    if(size_t(slash-path)+std::strlen(filename)+1>=sizeof(path))return;
    strcpy_s(slash, sizeof(path) - static_cast<size_t>(slash - path), filename);
    FILE* f=nullptr;
    fopen_s(&f,path,overwrite?"w":"a");
    if(f){fprintf(f,"%s\n",message ? message : "");fclose(f);}
}
// TEST 26: create the report at DLL/config startup, even if Jail_20 never
// reaches Playing mode. This is intentionally independent of the world scanner.
static void R2R_WorldRemixStartupDiagnostic(const char* reason){
    char path[MAX_PATH]={};
    snprintf(path,sizeof(path),"%s",g_R2RConfigPath);
    char* slash=std::strrchr(path,'\\');
    if(!slash)slash=std::strrchr(path,'/');
    if(slash)++slash;else slash=path;
    const char* leaf="Rayman2Randomizer_Learn10PositionsTest.txt";
    if(size_t(slash-path)+std::strlen(leaf)+1>=sizeof(path))return;
    strcpy_s(slash, sizeof(path) - static_cast<size_t>(slash - path), leaf);
    FILE* f=nullptr;
    fopen_s(&f,path,g_R2RConfigReloadCount<=1?"w":"a");
    if(!f)return;
    fprintf(f,"RAYMAN 2 RANDOMIZER %s - LEARN_10 POSITION DIAGNOSTIC\n",VERSION);
    fprintf(f,"[STARTUP] reason=%s enabled=%d enemiesWorldRemixTest=%d enemiesMenuTest=%d seed=%u reload=%u\n",
      reason?reason:"?",g_R2RConfig.enabled?1:0,
      g_R2RConfig.enemiesWorldRemixTest?1:0,g_R2RConfig.enemiesMenuTest?1:0,
      g_R2RConfig.seed,g_R2RConfigReloadCount);
    fprintf(f,"[PATH] config=%s\n[PATH] report=%s\n",g_R2RConfigPath,path);
    if(!g_R2RConfig.enabled || !g_R2RConfig.enemiesWorldRemixTest)
        fprintf(f,"[DISABLED] In [Randomizer] set Enabled=1 and EnemiesWorldRemixTest=1, then press F5 or restart.\n");
    else
        fprintf(f,"[READY] Report started before any level loads; waiting for Learn_10.\n");
    fflush(f);fclose(f);
}
// TEST 43: read-only live-render compatibility probe.
// A family owns animation channels, states and object tables. Swapping just
// a pointer between unlike families can crash when the animation updates.
// Observe both live actors before considering a controlled model test.
struct R2R_World3DReadout {
    bool actorOk;
    bool dataOk;
    bool tableOk;
    unsigned channels;
    unsigned tableElements;
    const void* dataAddress;
    const void* family;
    const void* initialState;
    const void* currentState;
    const void* initialTable;
    const void* currentTable;
    const void* firstTarget;
};
static R2R_World3DReadout R2R_World3DRead(int index,const char* scene){
    R2R_World3DReadout out={};
    const R2R_MenuEnemyActor& a=g_R2RWorldRemixActors[index];
    out.actorOk=a.actor && R2R_AddressReadable(reinterpret_cast<uintptr_t>(a.actor),sizeof(HIE_tdstEngineObject));
    HIE_tdstEngineObject actor={};
    if(out.actorOk && SafeReadMemory(a.actor,&actor,sizeof(actor)) && actor.h3dData &&
       R2R_AddressReadable(reinterpret_cast<uintptr_t>(actor.h3dData),sizeof(GAM_tdst3dData))){
        GAM_tdst3dData d={};
        if(SafeReadMemory(actor.h3dData,&d,sizeof(d))){
            out.dataOk=true;
            out.dataAddress=actor.h3dData;
            out.family=d.h_Family;
            out.channels=static_cast<unsigned>(d.ulNumberOfChannels);
            out.initialState=d.h_InitialState;
            out.currentState=d.h_CurrentState;
            out.initialTable=d.h_InitialObjectsTable;
            out.currentTable=d.h_CurrentObjectsTable;
            HIE_tdstObjectsTablesList table={};
            if(d.h_CurrentObjectsTable &&
                R2R_AddressReadable(reinterpret_cast<uintptr_t>(d.h_CurrentObjectsTable),sizeof(table)) &&
                SafeReadMemory(d.h_CurrentObjectsTable,&table,sizeof(table)) &&
                table.uwNumberOfElement>0u && table.uwNumberOfElement<=128u &&
                table.d_stObjectsTable &&
                R2R_AddressReadable(reinterpret_cast<uintptr_t>(table.d_stObjectsTable),sizeof(HIE_tdstObjectsTableElement))){
                out.tableOk=true;
                out.tableElements=static_cast<unsigned>(table.uwNumberOfElement);
                HIE_tdstObjectsTableElement first={};
                if(SafeReadMemory(table.d_stObjectsTable,&first,sizeof(first)))
                    out.firstTarget=first.hTarget;
            }
        }
    }
    char line[650]={};
    snprintf(line,sizeof(line),
      "[WORLD-3D-ACTOR] frame=%u scene=%s name=%s active=%d actorOk=%d dataOk=%d data=%p family=%p channels=%u initialState=%p currentState=%p initialTable=%p currentTable=%p tableOk=%d tableElements=%u firstTarget=%p",
      g_R2RWorldRemixFrames,scene,g_R2RWorldRemixSpecs[index].name,
      g_R2RWorldRemixActorActive[index]?1:0,out.actorOk?1:0,out.dataOk?1:0,
      out.dataAddress,out.family,out.channels,out.initialState,out.currentState,
      out.initialTable,out.currentTable,out.tableOk?1:0,out.tableElements,out.firstTarget);
    R2R_WorldRemixLog(line);
    return out;
}
static void R2R_World3DCompare(const char* scene,int first,int second){
    R2R_WorldRemixLog("[WORLD-3D-AUDIT-START] readOnly=1 no-model-write=1");
    const R2R_World3DReadout a=R2R_World3DRead(first,scene);
    const R2R_World3DReadout b=R2R_World3DRead(second,scene);
    const bool readable=a.dataOk && b.dataOk;
    const bool sameFamily=readable && a.family==b.family;
    const bool equalChannels=readable && a.channels==b.channels;
    const bool equalTables=readable && a.tableOk && b.tableOk && a.tableElements==b.tableElements;
    char line[350]={};
    snprintf(line,sizeof(line),
       "[WORLD-3D-COMPARE] scene=%s readable=%d sameFamily=%d sameChannels=%d sameTableElements=%d channels=%u,%u tableElements=%u,%u modelSwapPerformed=0",
       scene,readable?1:0,sameFamily?1:0,equalChannels?1:0,equalTables?1:0,
       a.channels,b.channels,a.tableElements,b.tableElements);
    R2R_WorldRemixLog(line);
    R2R_WorldRemixLog("[WORLD-3D-AUDIT-END] modelSwapPerformed=0 reason=cross-family-runtime-safety");
}
static void R2R_WorldRemixClear(){
    std::memset(g_R2RWorldRemixActors,0,sizeof(g_R2RWorldRemixActors));
    g_R2RWorldRemixFrames=0;

    g_R2RWorldRemixApplied=false;
    std::memset(g_R2RWorldRemixGroupsDone,0,sizeof(g_R2RWorldRemixGroupsDone));
    std::memset(g_R2RWorldRemixObserved,0,sizeof(g_R2RWorldRemixObserved));
    std::memset(g_R2RWorldRemixActorActive,0,sizeof(g_R2RWorldRemixActorActive));
    std::memset(g_R2RWorldRemixObservedSince,0,sizeof(g_R2RWorldRemixObservedSince));
    std::memset(g_R2RWorldRemixHoldTarget,0,sizeof(g_R2RWorldRemixHoldTarget));
    std::memset(g_R2RWorldRemixHoldIdentity,0,sizeof(g_R2RWorldRemixHoldIdentity));
    std::memset(g_R2RWorldRemixHoldCorrections,0,sizeof(g_R2RWorldRemixHoldCorrections));
    std::memset(g_R2RWorldRemixHoldMember,0,sizeof(g_R2RWorldRemixHoldMember));
    std::memset(g_R2RWorldRemixGroupFrames,0,sizeof(g_R2RWorldRemixGroupFrames));
    g_R2RWorldRemixHoldActive=false;
}
static void R2R_WorldRemixVisit(HIE_tdstSuperObject* o,unsigned depth,bool fromActiveWorld){
    if(!o || depth>64 || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(o),sizeof(*o)))return;
    if(o->ulType==HIE_C_Type_Actor && o!=HIE_M_hGetMainActor()){
        const char* name=HIE_fn_szGetObjectPersonalName(o);
        if(name){
            for(int i=0;i<R2R_WORLD_COUNT;++i){
                const R2R_WorldRemixSpec& s=g_R2RWorldRemixSpecs[i];
                if(_stricmp(s.level,g_R2RWorldRemixLevel) || _stricmp(s.name,name) ||
                   g_R2RWorldRemixActors[i].object)continue;
                const char* fam=HIE_fn_szGetObjectFamilyName(o);
                const char* model=HIE_fn_szGetObjectModelName(o);
                if(!fam || !model || _stricmp(fam,s.family) || _stricmp(model,s.model)){
                    if(g_R2RWorldRemixFrames==10u || g_R2RWorldRemixFrames==90u ||
                       g_R2RWorldRemixFrames%300u==0u){
                        char line[400]={};
                        snprintf(line,sizeof(line),"[WORLD-REJECT] actor=%s reason=family/model expected=%s/%s found=%s/%s",
                          name,s.family,s.model,fam?fam:"(null)",model?model:"(null)");
                        R2R_WorldRemixLog(line);
                    }
                    break;
                }
                HIE_tdstEngineObject* a=HIE_M_hSuperObjectGetActor(o);
                const bool aReadable=a && R2R_AddressReadable(reinterpret_cast<uintptr_t>(a),sizeof(*a));
                if(!aReadable || !a->h3dData || !a->hBrain || !o->hFatherDyn ||
                   !R2R_AddressReadable(reinterpret_cast<uintptr_t>(o->hFatherDyn),sizeof(HIE_tdstSuperObject))){
                    if(g_R2RWorldRemixFrames==10u || g_R2RWorldRemixFrames==90u ||
                       g_R2RWorldRemixFrames%300u==0u){
                        char line[280]={};
                        snprintf(line,sizeof(line),"[WORLD-REJECT] actor=%s reason=actor/data/brain/parent actor=%p readable=%d",
                          name,static_cast<void*>(a),aReadable?1:0);
                        R2R_WorldRemixLog(line);
                    }
                    break;
                }
                auto* global=o->p_stGlobalMatrix;
                auto* local=o->p_stLocalMatrix;
                if(!global || !local || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(global),sizeof(*global)) ||
                   !R2R_AddressReadable(reinterpret_cast<uintptr_t>(local),sizeof(*local)) ||
                   !R2R_MenuVecValid(global->stPos) || !R2R_MenuVecValid(local->stPos)){
                    if(g_R2RWorldRemixFrames==10u || g_R2RWorldRemixFrames==90u ||
                       g_R2RWorldRemixFrames%300u==0u){
                        char line[280]={};
                        snprintf(line,sizeof(line),"[WORLD-REJECT] actor=%s reason=invalid-matrices global=%p local=%p",
                          name,static_cast<void*>(global),static_cast<void*>(local));
                        R2R_WorldRemixLog(line);
                    }
                    break;
                }
                R2R_MenuEnemyActor& dst=g_R2RWorldRemixActors[i];
                dst.object=o;dst.actor=a;dst.parent=o->hFatherDyn;
                dst.global=global;dst.local=local;dst.native=global->stPos;
                g_R2RWorldRemixActorActive[i]=fromActiveWorld;
                break;
            }
        }
    }
    HIE_tdstSuperObject* child=nullptr;
    LST_M_DynamicForEach(o,child){if(child)R2R_WorldRemixVisit(child,depth+1,fromActiveWorld);}
}
static int R2R_WorldRemixCountHeld(){
    int count=0;
    for(int i=0;i<R2R_WORLD_COUNT;++i)if(g_R2RWorldRemixHoldMember[i])++count;
    return count;
}
static void R2R_WorldRemixApply(){
    int found=0, moved=0, groups=0, skipped=0;
    for(int i=0;i<R2R_WORLD_COUNT;++i) if(g_R2RWorldRemixActors[i].object)++found;
    char line[460]={};
    const unsigned frame=g_R2RWorldRemixFrames;
    if(frame==10u || frame==30u || frame==90u || frame%300u==0u) {
        snprintf(line,sizeof(line),"[WORLD-SCAN] level=%s seed=%u candidatesFound=%d/%d mode=TEST43-INTRO-2 TUYO-120F-3D-READONLY-AUDIT",
            g_R2RWorldRemixLevel,g_R2RConfig.seed,found,R2R_WORLD_COUNT);
        R2R_WorldRemixLog(line);
        for(int i=0;i<R2R_WORLD_COUNT;++i) {
            const auto& a=g_R2RWorldRemixActors[i];
            if(a.object)
                snprintf(line,sizeof(line),"[JAIL-ACTOR] name=%s group=%s found=1 source=%s pos=%.2f,%.2f,%.2f",
                    g_R2RWorldRemixSpecs[i].name,g_R2RWorldRemixSpecs[i].group,
                    g_R2RWorldRemixActorActive[i]?"ACTIVE":"INACTIVE",a.native.x,a.native.y,a.native.z);
            else
                snprintf(line,sizeof(line),"[JAIL-ACTOR] name=%s group=%s found=0",
                    g_R2RWorldRemixSpecs[i].name,g_R2RWorldRemixSpecs[i].group);
            R2R_WorldRemixLog(line);
        }
    }
    for(int first=0;first<R2R_WORLD_COUNT;++first) {
        if(g_R2RWorldRemixGroupsDone[first])continue;
        const char* group=g_R2RWorldRemixSpecs[first].group;
        const int groupIndex=R2R_WorldRemixGroupIndex(group);
        if(groupIndex<0){g_R2RWorldRemixGroupsDone[first]=true;continue;}
        // Wait for the real game event, not for a hard-coded frame interval.
        // The camera/character cinematic can start hundreds or thousands of
        // frames later depending on how quickly the level is played.
        // Only the two ACTIVE actors near the final-scene anchor are eligible.
        // Never force-activate an inactive actor or write to a stale object.
        int ids[R2R_WORLD_COUNT]={};int count=0,needed=0,activeCount=0;
        for(int i=0;i<R2R_WORLD_COUNT;++i) {
            if(_stricmp(g_R2RWorldRemixSpecs[i].group,group))continue;
            ++needed;
            if(g_R2RWorldRemixActors[i].object){
                ids[count++]=i;
                if(g_R2RWorldRemixActorActive[i])++activeCount;
            }
        }
        // Both late-scene actors must be ACTIVE at the SAME time.
        if(count!=needed || activeCount!=needed){
            if(frame==10u || frame==30u || frame==90u || frame%300u==0u){
                snprintf(line,sizeof(line),"[WORLD-WAIT] group=%s found=%d active=%d needed=%d reason=%s",
                    group,count,activeCount,needed,
                    count!=needed?"member-not-found":"inactive-scene-actor");
                R2R_WorldRemixLog(line);
            }
            continue;
        }
        if(groupIndex==1){
            const MTH3D_tdstVector anchor={385.9771f,327.080383f,279.618073f};
            float radius[2]={},pairDistance=0.0f;
            bool stageValid=(count==2);
            for(int k=0;k<count && k<2;++k){
                const MTH3D_tdstVector& p=g_R2RWorldRemixActors[ids[k]].native;
                const float x=p.x-anchor.x,y=p.y-anchor.y,z=p.z-anchor.z;
                radius[k]=std::sqrt(x*x+y*y+z*z);
                if(!std::isfinite(radius[k]) || radius[k]>40.0f)stageValid=false;
            }
            if(count==2){
                const auto& p=g_R2RWorldRemixActors[ids[0]].native;
                const auto& q=g_R2RWorldRemixActors[ids[1]].native;
                const float x=p.x-q.x,y=p.y-q.y,z=p.z-q.z;
                pairDistance=std::sqrt(x*x+y*y+z*z);
                if(!std::isfinite(pairDistance) || pairDistance<3.0f || pairDistance>40.0f)stageValid=false;
            }
            if(!stageValid){
                if(frame==10u || frame%300u==0u){
                    snprintf(line,sizeof(line),"[WORLD-TUYO-WAIT] frame=%u active=%d stageValid=%d radii=%.2f,%.2f separation=%.2f writes=0",
                        frame,activeCount,stageValid?1:0,radius[0],radius[1],pairDistance);
                    R2R_WorldRemixLog(line);
                }
                continue;
            }
            snprintf(line,sizeof(line),"[WORLD-TUYO-READY] frame=%u active=%d radii=%.2f,%.2f separation=%.2f (event-triggered max 120-frame guarded hold)",
                frame,activeCount,radius[0],radius[1],pairDistance);
            R2R_WorldRemixLog(line);
        }
        // Capture each actual scene's 3D tables BEFORE any positional write.
        // This is read-only and intentionally does not reinterpret donor animations.
        if(groupIndex==0)R2R_World3DCompare("INTRO",0,1);
        else if(groupIndex==1)R2R_World3DCompare("TUYO",4,5);
        // Deterministic permutation of ACTORS, then a cyclic permutation of SLOTS.
        // This guarantees no actor keeps its own location within its group.
        for(int k=count-1;k>0;--k){
            const unsigned slot=0x29A000u + unsigned(groupIndex)*0x200u + unsigned(k);
            const int j=int(R2R_RollU32("Enemies.Jail20.AllVisualCycle.Test29",g_R2RWorldRemixLevel,slot)%unsigned(k+1));
            const int tmp=ids[k];ids[k]=ids[j];ids[j]=tmp;
        }
        R2R_MenuPhysics physics[R2R_WORLD_COUNT]={};
        MTH3D_tdstVector locals[R2R_WORLD_COUNT]={};
        MTH3D_tdstVector targets[R2R_WORLD_COUNT]={};
        bool valid=true;
        for(int k=0;k<count;++k){
            const int actorId=ids[k],donorId=ids[(k+1)%count];
            const auto& actor=g_R2RWorldRemixActors[actorId];
            const MTH3D_tdstVector& to=g_R2RWorldRemixActors[donorId].native;
            targets[k]=to;
            const MTH3D_tdstVector& expected=g_R2RWorldRemixNativeSlots[actorId];
            const float nx=actor.native.x-expected.x,ny=actor.native.y-expected.y,nz=actor.native.z-expected.z;
            const float originalError=std::sqrt(nx*nx+ny*ny+nz*nz);
            const float dx=to.x-actor.native.x,dy=to.y-actor.native.y,dz=to.z-actor.native.z;
            const float distance=std::sqrt(dx*dx+dy*dy+dz*dz);
            const float maxMove=(groupIndex==0?145.0f:260.0f);
            const char* reject=nullptr;
            if(!std::isfinite(distance) || distance<0.01f || distance>maxMove)reject="out-of-zone-distance";
            // Late TUYO actors have already moved into the ending stage.
            // Their old loading positions are intentionally NOT authoritative;
            // the stage-anchor + simultaneous-ACTIVE checks above replace it.
            else if(groupIndex==0 && (!std::isfinite(originalError) || originalError>5.0f))reject="not-at-original-slot";
            else if(!R2R_MenuLocalTarget(actor,to,locals[k]))reject="invalid-local-transform";
            else if(!R2R_MenuPreparePhysics(actor,physics[k],g_R2RWorldRemixSpecs[actorId].name))reject="invalid-physics";
            if(reject){
                snprintf(line,sizeof(line),"[WORLD-REJECT] group=%s actor=%s reason=%s nativeError=%.2f moveDistance=%.2f",
                    group,g_R2RWorldRemixSpecs[actorId].name,reject,originalError,distance);
                R2R_WorldRemixLog(line);valid=false;break;
            }
            snprintf(line,sizeof(line),"[WORLD-CHECK] group=%s actor=%s donor=%s distance=%.2f dynamics=%d",
                group,g_R2RWorldRemixSpecs[actorId].name,g_R2RWorldRemixSpecs[donorId].name,distance,
                physics[k].hasDynamics?1:0);
            R2R_WorldRemixLog(line);
        }
        // Mark an invalid group done: do not keep trying writes into a modified cutscene.
        if(!valid){
            ++skipped;
            for(int i=0;i<R2R_WORLD_COUNT;++i)
                if(!_stricmp(g_R2RWorldRemixSpecs[i].group,group))g_R2RWorldRemixGroupsDone[i]=true;
            snprintf(line,sizeof(line),"[WORLD-SKIP] group=%s reason=validation",group);
            R2R_WorldRemixLog(line);
            continue;
        }
        // Preflight ALL actors before ANY commit. Exact donor positions were
        // saved above, so writes cannot change a later donor's destination.
        for(int k=0;k<count;++k){
            const int actorId=ids[k],donorId=ids[(k+1)%count];
            const auto& actor=g_R2RWorldRemixActors[actorId];
            const MTH3D_tdstVector& to=targets[k];
            const MTH3D_tdstVector delta={to.x-actor.native.x,to.y-actor.native.y,to.z-actor.native.z};
            R2R_MenuPhysicsCommit(physics[k],delta);
            R2R_MenuCommit(actor,to,locals[k]);
            // Cache intro verification only; late TUYO is re-discovered safely.
            if(groupIndex==0){
                g_R2RWorldRemixObserved[actorId]=actor;
                g_R2RWorldRemixObservedSince[actorId]=frame;
            }
            // TUYO also gets a STRICTLY TIME-BOUNDED (120-frame) hold.
            // Both actors must remain active and keep their identities.
            if(groupIndex==0 || groupIndex==1){
                g_R2RWorldRemixHoldTarget[actorId]=to;
                g_R2RWorldRemixHoldIdentity[actorId]=actor.object;
                g_R2RWorldRemixHoldMember[actorId]=true;
            }
            snprintf(line,sizeof(line),"[WORLD-MIX] group=%s actor=%s donor=%s target=%.2f,%.2f,%.2f",
                group,g_R2RWorldRemixSpecs[actorId].name,g_R2RWorldRemixSpecs[donorId].name,to.x,to.y,to.z);
            R2R_WorldRemixLog(line);++moved;
        }
        ++groups;
        if(groupIndex==0 || groupIndex==1)g_R2RWorldRemixHoldActive=true;
        for(int i=0;i<R2R_WORLD_COUNT;++i)
            if(!_stricmp(g_R2RWorldRemixSpecs[i].group,group))g_R2RWorldRemixGroupsDone[i]=true;
        if(groupIndex==1){
            R2R_WorldRemixLog("[WORLD-TUYO-SWAP] group=TUYO count=2 active=2 trigger=scene-activation maxHoldFrames=120 active-world-guard=1 scripts-unchanged=1");
        } else {
            snprintf(line,sizeof(line),"[WORLD-HOLD-START] group=%s count=%d post-engine per-frame with group-atomic safety",group,count);
            R2R_WorldRemixLog(line);
        }
        if(groupIndex==0)R2R_WorldRemixLog("[WORLD-ISOLATION] Test43: intro Globox/pirate unchanged; TUYO event-driven swap pending; read-only 3D audit (no frame cutoff); Rayman-Jail and all Lums protected.");
        
    }
    if(moved)g_R2RWorldRemixApplied=true;
    if(moved || skipped || frame==90u || frame%300u==0u){
        snprintf(line,sizeof(line),"[WORLD-SUMMARY] level=Jail_20 movedThisScan=%d groupsThisScan=%d skippedGroups=%d totalHoldMembers=%d",
            moved,groups,skipped,R2R_WorldRemixCountHeld());
        R2R_WorldRemixLog(line);
    }
}
// TEST 35: a cutscene script may move actors on EVERY engine tick. Reading
// fresh actor identities from the active world avoids writing to stale actors
// after cutscene teardown. Physics/matrix writes use the validated Menu helpers.
static bool R2R_WorldRemixPhysicsQuiet(const R2R_MenuEnemyActor& a, R2R_MenuPhysics& out) {
    std::memset(&out,0,sizeof(out));
    if(!a.actor || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(a.actor),sizeof(*a.actor))) return false;
    if(!a.actor->hDynam) return true;
    DNM_tdstDynam dynam={};
    if(!SafeReadMemory(a.actor->hDynam,&dynam,sizeof(dynam)) || !dynam.p_stDynamics ||
       !R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stDynamics),sizeof(DNM_tdstDynamicsBaseBlock)) ||
       !R2R_Learn30MoveWritable(dynam.p_stDynamics,sizeof(DNM_tdstDynamicsBaseBlock))) return false;
    DNM_tdstDynamicsBaseBlock base={};
    if(!SafeReadMemory(&dynam.p_stDynamics->stDynamicsBase,&base,sizeof(base)) ||
       !R2R_MenuVecValid(base.stPreviousMatrix.stPos) ||
       !R2R_MenuVecValid(base.stCurrentMatrix.stPos)) return false;
    out.physics=dynam.p_stDynamics;
    out.hasDynamics=true;
    if(dynam.p_stParsingDatas &&
       R2R_AddressReadable(reinterpret_cast<uintptr_t>(dynam.p_stParsingDatas),sizeof(DNM_tdstParsingDatas)) &&
       R2R_Learn30MoveWritable(dynam.p_stParsingDatas,sizeof(DNM_tdstParsingDatas))) {
        DNM_tdstParsingDatas pd={};
        if(SafeReadMemory(dynam.p_stParsingDatas,&pd,sizeof(pd)) && R2R_MenuVecValid(pd.stPosition))
            out.parsing=dynam.p_stParsingDatas;
    }
    return true;
}
static void R2R_WorldRemixHoldStopGroup(int groupIndex,const char* reason){
    const char* group=groupIndex==0?"INTRO":"TUYO";
    unsigned fixes=0;int members=0;
    for(int i=0;i<R2R_WORLD_COUNT;++i){
        if(!g_R2RWorldRemixHoldMember[i] || R2R_WorldRemixGroupIndex(g_R2RWorldRemixSpecs[i].group)!=groupIndex)
            continue;
        ++members; fixes+=g_R2RWorldRemixHoldCorrections[i];
        g_R2RWorldRemixHoldMember[i]=false;
        g_R2RWorldRemixHoldIdentity[i]=nullptr;
    }
    if(members){
        char line[300]={};
        snprintf(line,sizeof(line),"[WORLD-HOLD-STOP] group=%s reason=%s heldFrames=%u members=%d corrections=%u",
            group,reason?reason:"?",g_R2RWorldRemixGroupFrames[groupIndex],members,fixes);
        R2R_WorldRemixLog(line);
    }
    g_R2RWorldRemixHoldActive=R2R_WorldRemixCountHeld()>0;
}
static void R2R_WorldRemixHoldStop(const char* reason){
    if(!g_R2RWorldRemixHoldActive)return;
    R2R_WorldRemixHoldStopGroup(0,reason);
    R2R_WorldRemixHoldStopGroup(1,reason);
}
static void R2R_WorldRemixHoldTick(HIE_tdstSuperObject* world){
    if(!g_R2RWorldRemixHoldActive || !world)return;
    // The active world is scanned anew each frame. Never rely on cached
    // actor object or matrix pointers after a cinematic scene transition.
    std::memset(g_R2RWorldRemixActors,0,sizeof(g_R2RWorldRemixActors));
    std::memset(g_R2RWorldRemixActorActive,0,sizeof(g_R2RWorldRemixActorActive));
    R2R_WorldRemixVisit(world,0,true);
    // TUYO may disappear in the very next frame. Watch read-only at 11, 30,
    // then every 300th frame; never dereference stale pointers.
    if(g_R2RWorldRemixFrames==11u || g_R2RWorldRemixFrames==30u || g_R2RWorldRemixFrames%300u==0u){
        const int watch[]={2,3,4,5,6};
        for(int wi=0;wi<5;++wi){
            const int i=watch[wi];
            const R2R_MenuEnemyActor& a=g_R2RWorldRemixActors[i];
            char line[360]={};
            if(a.object && a.global && R2R_MenuVecValid(a.global->stPos))
                snprintf(line,sizeof(line),"[WORLD-SCENE-PROBE] frame=%u name=%s group=%s present=1 pos=%.2f,%.2f,%.2f",
                    g_R2RWorldRemixFrames,g_R2RWorldRemixSpecs[i].name,g_R2RWorldRemixSpecs[i].group,
                    a.global->stPos.x,a.global->stPos.y,a.global->stPos.z);
            else
                snprintf(line,sizeof(line),"[WORLD-SCENE-PROBE] frame=%u name=%s group=%s present=0",
                    g_R2RWorldRemixFrames,g_R2RWorldRemixSpecs[i].name,g_R2RWorldRemixSpecs[i].group);
            R2R_WorldRemixLog(line);
        }
    }
    for(int groupIndex=0;groupIndex<2;++groupIndex){
        int ids[R2R_WORLD_COUNT]={};int count=0;
        for(int i=0;i<R2R_WORLD_COUNT;++i){
            if(g_R2RWorldRemixHoldMember[i] &&
                R2R_WorldRemixGroupIndex(g_R2RWorldRemixSpecs[i].group)==groupIndex)ids[count++]=i;
        }
        if(count==0)continue;
        if(groupIndex==1 && g_R2RWorldRemixGroupFrames[1]>=120u){
            // Always allow the native scene script to retake full control.
            R2R_WorldRemixHoldStopGroup(1,"120-frame-time-limit-return-to-engine");
            continue;
        }
        R2R_MenuPhysics physics[R2R_WORLD_COUNT]={};
        MTH3D_tdstVector locals[R2R_WORLD_COUNT]={};
        MTH3D_tdstVector deltas[R2R_WORLD_COUNT]={};
        float drifts[R2R_WORLD_COUNT]={};
        const char* problem=nullptr;
        // Prevalidate the complete group. Stale pointers or a major scene
        // jump invalidate the group without writing a partial correction.
        for(int k=0;k<count;++k){
            const int i=ids[k];
            const auto& a=g_R2RWorldRemixActors[i];
            const auto& target=g_R2RWorldRemixHoldTarget[i];
            if(!a.object || a.object!=g_R2RWorldRemixHoldIdentity[i] ||
               !a.global || !a.local || !R2R_MenuVecValid(target)){
                problem="actor-inactive-or-identity-changed";break;
            }
            // TEST 42: the game may park one cinematic actor into the inactive
            // world before its scene ends. Do not continue to pin the other one.
            // Both TUYO actors must still be in the live active-world traversal.
            if(groupIndex==1 && !g_R2RWorldRemixActorActive[i]){
                problem="tuyo-actor-left-active-world";break;
            }
            deltas[k]={target.x-a.global->stPos.x,target.y-a.global->stPos.y,target.z-a.global->stPos.z};
            const auto& d=deltas[k];
            drifts[k]=std::sqrt(d.x*d.x+d.y*d.y+d.z*d.z);
            // The stage controller may transition to a later scene; do NOT
            // drag its characters back into the old shot.
            if(!std::isfinite(drifts[k]) || drifts[k]>(groupIndex==0?110.0f:40.0f)){
                problem="cinematic-scene-transition-or-teleport";break;
            }
            if(!R2R_MenuLocalTarget(a,target,locals[k]) ||
               !R2R_WorldRemixPhysicsQuiet(a,physics[k])){
                problem="unsafe-matrix-or-physics";break;
            }
        }
        if(problem){R2R_WorldRemixHoldStopGroup(groupIndex,problem);continue;}
        const unsigned frame=++g_R2RWorldRemixGroupFrames[groupIndex];
        for(int k=0;k<count;++k){
            const int i=ids[k];
            const auto& a=g_R2RWorldRemixActors[i];
            if(drifts[k]>0.001f)++g_R2RWorldRemixHoldCorrections[i];
            R2R_MenuPhysicsCommit(physics[k],deltas[k]);
            R2R_MenuCommit(a,g_R2RWorldRemixHoldTarget[i],locals[k]);
            if(frame==1u || frame==30u || frame==90u || frame==300u || frame==600u || frame%600u==0u ||
               (groupIndex==1 && (frame==10u || frame==20u || frame==45u || frame==60u || frame==75u || frame==105u || frame==120u))){
                char line[330]={};
                snprintf(line,sizeof(line),"[WORLD-HOLD] group=%s frames=%u actor=%s drift=%.3f final=%.2f,%.2f,%.2f fixes=%u",
                    g_R2RWorldRemixSpecs[i].group,frame,g_R2RWorldRemixSpecs[i].name,drifts[k],
                    a.global->stPos.x,a.global->stPos.y,a.global->stPos.z,g_R2RWorldRemixHoldCorrections[i]);
                R2R_WorldRemixLog(line);
            }
        }
    }
}
// TEST 36: bounded, read-only active-actor audit. No engine write, no changes
// to donor selection, cutscene scripts, actor brains, or progression flags.
static HIE_tdstSuperObject* g_R2RWorldAuditRoot=nullptr;
static char g_R2RWorldAuditLevel[64]={};
static unsigned g_R2RWorldAuditFrames=0;
struct R2R_WorldAuditStats {
    unsigned objectsVisited;
    unsigned actorsSeen;
    unsigned actorsLogged;
    unsigned validPosition;
    unsigned truncated;
    unsigned cinematicHints;
};
static void R2R_WorldRemixAuditVisit(HIE_tdstSuperObject* o,unsigned depth,R2R_WorldAuditStats& stats,const char* side){
    if(!o || depth>64 || stats.objectsVisited>12000u ||
       !R2R_AddressReadable(reinterpret_cast<uintptr_t>(o),sizeof(*o)))return;
    ++stats.objectsVisited;
    if(o->ulType==HIE_C_Type_Actor && o!=HIE_M_hGetMainActor()){
        ++stats.actorsSeen;
        if(stats.actorsLogged<80u){
            const char* name=HIE_fn_szGetObjectPersonalName(o);
            const char* family=HIE_fn_szGetObjectFamilyName(o);
            const char* model=HIE_fn_szGetObjectModelName(o);
            const bool posReadable=o->p_stGlobalMatrix &&
                R2R_AddressReadable(reinterpret_cast<uintptr_t>(o->p_stGlobalMatrix),sizeof(*o->p_stGlobalMatrix)) &&
                R2R_MenuVecValid(o->p_stGlobalMatrix->stPos);
            const HIE_tdstEngineObject* engineActor=HIE_M_hSuperObjectGetActor(o);
            const bool brainReady=engineActor &&
                R2R_AddressReadable(reinterpret_cast<uintptr_t>(engineActor),sizeof(*engineActor)) &&
                engineActor->hBrain!=nullptr;
            // A naming hint is NOT a safety judgment. Future experiments
            // must individually validate these actors before moving them.
            const bool scriptedHint=(name && (strstr(name,"Cine") || strstr(name,"Intro") ||
                strstr(name,"Dummy") || strstr(name,"THX") || strstr(name,"CONTROL"))) ||
                (model && (strstr(model,"Cinema") || strstr(model,"Intro")));
            if(scriptedHint)++stats.cinematicHints;
            if(posReadable)++stats.validPosition;
            char line[420]={};
            if(posReadable){
                const MTH3D_tdstVector& p=o->p_stGlobalMatrix->stPos;
                snprintf(line,sizeof(line),"[WORLD-AUDIT-ACTOR] level=%s frame=%u source=%s name=%.60s family=%.55s model=%.55s pos=%.2f,%.2f,%.2f brain=%d scriptedHint=%d",
                    g_R2RWorldAuditLevel,g_R2RWorldAuditFrames,side,name?name:"?",family?family:"?",model?model:"?",
                    p.x,p.y,p.z,brainReady?1:0,scriptedHint?1:0);
            } else {
                snprintf(line,sizeof(line),"[WORLD-AUDIT-ACTOR] level=%s frame=%u source=%s name=%.60s family=%.55s model=%.55s position=UNAVAILABLE brain=%d scriptedHint=%d",
                    g_R2RWorldAuditLevel,g_R2RWorldAuditFrames,side,name?name:"?",family?family:"?",model?model:"?",
                    brainReady?1:0,scriptedHint?1:0);
            }
            R2R_WorldRemixLog(line);
            ++stats.actorsLogged;
        } else ++stats.truncated;
    }
    HIE_tdstSuperObject* child=nullptr;
    LST_M_DynamicForEach(o,child){if(child)R2R_WorldRemixAuditVisit(child,depth+1,stats,side);}
}
static void R2R_WorldRemixAuditTick(const char* level,HIE_tdstSuperObject* world){
    if(!level || !world)return;
    // Jail_10 precedes Jail_20 in the regular route; Learn_40 can be audited
    // if reached later. Jail_20 is our current stability baseline.
    const bool selected=!_stricmp(level,"Jail_10") || !_stricmp(level,"Jail_20") ||
                        !_stricmp(level,"Learn_40");
    if(!selected){g_R2RWorldAuditRoot=nullptr;g_R2RWorldAuditLevel[0]='\0';g_R2RWorldAuditFrames=0;return;}
    if(world!=g_R2RWorldAuditRoot || _stricmp(level,g_R2RWorldAuditLevel)){
        g_R2RWorldAuditRoot=world;
        snprintf(g_R2RWorldAuditLevel,sizeof(g_R2RWorldAuditLevel),"%s",level);
        g_R2RWorldAuditFrames=0;
    }
    ++g_R2RWorldAuditFrames;
    const unsigned f=g_R2RWorldAuditFrames;
    // Extend read-only audits beyond 7500. Test40 reached the final scene
    // later than its hard-coded deadline and showed only until frame 7500.
    const bool early=(f==10u || f==90u || f==300u);
    const bool late=(!_stricmp(level,"Jail_20") &&
        (f==4500u || f==5100u || f==5400u || f==5700u || f==5850u ||
         f==6000u || f==6150u || f==6300u || f==6450u ||
         f==6600u || f==6900u || f==7200u || f==7500u ||
         (f>=7800u && f<=12000u && f%300u==0u)));
    if(!early && !late)return;
    char line[260]={};
    snprintf(line,sizeof(line),"[WORLD-STAGE-AUDIT] level=%s frame=%u stage=%s writes=0",
        level,f,late?"ENDING_WINDOW":"INTRO_WINDOW");
    R2R_WorldRemixLog(line);
    HIE_tdstSuperObject* inactive=(GAM_g_p_stInactiveDynamicWorld &&
        *GAM_g_p_stInactiveDynamicWorld)?*GAM_g_p_stInactiveDynamicWorld:nullptr;
    for(int sideIndex=0;sideIndex<2;++sideIndex){
        if(sideIndex==1 && (!inactive || inactive==world))continue;
        HIE_tdstSuperObject* root=sideIndex==0?world:inactive;
        const char* side=sideIndex==0?"ACTIVE":"INACTIVE";
        snprintf(line,sizeof(line),"[WORLD-AUDIT-START] level=%s frame=%u source=%s writes=0 sampleLimit=80",
            level,f,side);
        R2R_WorldRemixLog(line);
        R2R_WorldAuditStats stats={};
        R2R_WorldRemixAuditVisit(root,0,stats,side);
        snprintf(line,sizeof(line),"[WORLD-AUDIT-END] level=%s frame=%u source=%s objects=%u actors=%u reported=%u extra=%u readablePositions=%u scriptedHintsInReported=%u writes=0",
            level,f,side,stats.objectsVisited,stats.actorsSeen,stats.actorsLogged,stats.truncated,
            stats.validPosition,stats.cinematicHints);
        R2R_WorldRemixLog(line);
    }
}

