// POS_tdstCompletePosition::stPos uses (x,z,y) for these actors.
// Verified from Test44: JCP_champ1 Raymap (56.39,-6.48,316.08) and live
// engine (56.39,316.08,-6.48). Convert BOTH home validation AND destinations.
// Keep the 20 Raymap constants unchanged so subsequent imports are auditable.
static MTH3D_tdstVector R2R_Learn10RaymapToEngine(const MTH3D_tdstVector& p){
    return {p.x,p.z,p.y};
}
// ===========================================================================
// TEST 58: Learn_10 is an actual TEN-ACTOR SLOT PERMUTATION (four cycles),
// NOT an offset/random-wander system. Translate only the selected ACTOR'S
// instance-owned Graph/WayPoint references together with its slot exchange.
// Graph and WP objects belonging to the world are NEVER changed in place.
// This is intentionally more generic than Learn_30's name-specific routes.
// Unknown/unsafe live DSG routes block a movement rather than guessing.
// ===========================================================================
struct R2R_Learn10RouteField {
    unsigned id;
    void* cell;
    uint32_t original;
    unsigned type;
};
struct R2R_Learn10RouteState {
    bool installed;
    bool hasPath;
    bool lastActive;
    bool failureLogged;
    unsigned recoveries;
    unsigned count;
    R2R_Learn10RouteField fields[16];
    uint32_t updated[16];
    unsigned dynamicRebinds;
    unsigned graphWaypointCount;
    uint32_t graphOriginalWaypoints[16];
    uint32_t graphPrivateWaypoints[16];
    MTH3D_tdstVector delta;
};
static R2R_Learn10RouteState g_R2RLearn10Routes[20]={};
static unsigned g_R2RLearn10RouteLifetimeAllocations=0;
static void R2R_Learn10RouteLog(const char* message,bool overwrite=false){
    char path[MAX_PATH]={};
    snprintf(path,sizeof(path),"%s",g_R2RConfigPath);
    char* p=std::strrchr(path,'\\');if(!p)p=std::strrchr(path,'/');p=p?p+1:path;
    const char* filename="Rayman2Randomizer_Learn10RoutesTest.txt";
    if(static_cast<size_t>(p-path)+std::strlen(filename)+1>=sizeof(path))return;
    strcpy_s(p,sizeof(path)-static_cast<size_t>(p-path),filename);
    FILE* f=nullptr;fopen_s(&f,path,overwrite?"w":"a");
    if(f){fprintf(f,"%s\n",message?message:"");fclose(f);}
}
static bool R2R_Learn10RouteFields(const R2R_MenuEnemyActor& a,
                                   R2R_Learn10RouteField (&fields)[16],
                                   unsigned& count,const char*& why){
    count=0;why="unknown";
    if(!a.object || !a.actor || !a.actor->hBrain || !AI_fn_bGetDsgVar){
        why="missing-active-brain";return false;
    }
    AI_tdstBrain brain={};AI_tdstMind mind={};AI_tdstDsgMem mem={};
    AI_tdstDsgVar* defPtr=nullptr;AI_tdstDsgVar def={};
    if(!SafeReadMemory(a.actor->hBrain,&brain,sizeof(brain)) || !brain.p_stMind ||
       !SafeReadMemory(brain.p_stMind,&mind,sizeof(mind)) || !mind.p_stDsgMem ||
       !SafeReadMemory(mind.p_stDsgMem,&mem,sizeof(mem)) ||
       !mem.pp_stDsgVar || !SafeReadMemory(mem.pp_stDsgVar,&defPtr,sizeof(defPtr)) ||
       !defPtr || !SafeReadMemory(defPtr,&def,sizeof(def)) ||
       !def.a_stDsgVarInfo || !def.ucNbDsgVar || def.ucNbDsgVar>96 ||
       def.ulBufferSize<4u || def.ulBufferSize>16384u){
        why="dsg-instance-metadata-invalid";return false;
    }
    const uintptr_t base=reinterpret_cast<uintptr_t>(mem.p_cDsgMemBuffer);
    if(!base || mem.p_cDsgMemBuffer==mem.p_cDsgMemBufferInit ||
       mem.p_cDsgMemBuffer==def.p_cDsgMemDefaultInit ||
       !R2R_AddressReadable(base,def.ulBufferSize)){
        why="dsg-not-an-active-private-buffer";return false;
    }
    unsigned graphCount=0;
    for(unsigned id=0;id<static_cast<unsigned>(def.ucNbDsgVar);++id){
        AI_tdstDsgVarInfo info={};
        if(!SafeReadMemory(def.a_stDsgVarInfo+id,&info,sizeof(info))){
            why="dsg-field-metadata-unreadable";return false;
        }
        const unsigned kind=static_cast<unsigned>(info.eTypeId);
        if(kind!=8u && kind!=17u)continue;
        if(count>=16u || (kind==17u && ++graphCount>1u) ||
           info.ulOffsetInDsgMem>def.ulBufferSize-sizeof(uint32_t)){
            why="too-many-or-overlapping-graph-fields";return false;
        }
        AI_tdeDsgVarType type=AI_E_Nb_dvt;void* raw=nullptr;
        uint32_t pointer=0;
        if(!AI_fn_bGetDsgVar(a.object,id,&type,&raw) || !raw ||
           static_cast<unsigned>(type)!=kind ||
           reinterpret_cast<uintptr_t>(raw)!=base+info.ulOffsetInDsgMem ||
           !R2R_Learn10ExtraWritable(raw,sizeof(pointer)) ||
           !SafeReadMemory(raw,&pointer,sizeof(pointer))){
            why="nonprivate-or-unwritable-route-cell";return false;
        }
        fields[count++]={id,raw,pointer,kind};
    }
    why=count?"instance-route-fields-validated":"no-graph-or-waypoint-fields";
    return true;
}
static float R2R_Learn10RouteDist(const MTH3D_tdstVector& a,const MTH3D_tdstVector& b){
    const float x=a.x-b.x,y=a.y-b.y,z=a.z-b.z;
    return std::sqrt(x*x+y*y+z*z);
}
static bool R2R_Learn10RouteInstall(const R2R_MenuEnemyActor& a,int index,
                                     const MTH3D_tdstVector& target,unsigned frame,
                                     const char*& why){
    why="unknown";
    auto& state=g_R2RLearn10Routes[index];
    if(state.installed){why="already-installed";return true;}
    R2R_Learn10RouteField cells[16]={};unsigned fieldCount=0;
    if(!R2R_Learn10RouteFields(a,cells,fieldCount,why))return false;
    const MTH3D_tdstVector shift={target.x-a.native.x,target.y-a.native.y,target.z-a.native.z};
    if(!R2R_MenuVecValid(shift) || R2R_Learn10RouteDist(shift,{0.f,0.f,0.f})>42.1f){
        why="slot-swap-route-distance-invalid";return false;
    }
    if(!fieldCount){
        state.installed=true;state.hasPath=false;state.lastActive=true;state.delta=shift;
        char line[230]={};snprintf(line,sizeof(line),
            "[LEARN10-ROUTE-NONE] frame=%u actor=%s no-typed-graph-or-waypoint; position-swap-only",
            frame,g_R2RLearn10PositionSpecs[index].name);
        R2R_Learn10RouteLog(line);
        why="no-route-needed";return true;
    }
    if(!AI_fn_p_vTrueAlloc || !AI_fn_vTrueFree ||
       g_R2RLearn10RouteLifetimeAllocations>=640u){
        why="native-allocator-or-lifetime-cap";return false;
    }
    int graphIndex=-1;
    for(unsigned j=0;j<fieldCount;++j){
        if(cells[j].type==17u)graphIndex=static_cast<int>(j);
    }
    // Plan the private topology before writing any actor DSG cell.
    WP_tdstGraph sourceGraph={};
    std::vector<WP_tdstGraphNode> oldNodes;
    std::vector<WP_tdstGraphNode*> oldNodePtrs;
    std::vector<WP_tdstWayPoint> oldGraphPoints;
    std::vector<WP_tdstListOfArc> oldArcLists;
    std::vector<std::vector<WP_tdstArc>> oldArcs;
    if(graphIndex>=0 && cells[graphIndex].original){
        if(!SafeReadMemory(reinterpret_cast<const void*>(uintptr_t(cells[graphIndex].original)),
                           &sourceGraph,sizeof(sourceGraph))){
            why="source-graph-unreadable";return false;
        }
        const long n=sourceGraph.m_hListOfNode.lNbOfElementsDyn;
        if(n<1 || n>8 || !sourceGraph.m_hListOfNode.hFirstElementDyn ||
           !sourceGraph.m_hListOfNode.hLastElementDyn){
            why="source-graph-node-count-outside-1-to-8";return false;
        }
        auto* cursor=sourceGraph.m_hListOfNode.hFirstElementDyn;
        for(long i=0;i<n;++i){
            WP_tdstGraphNode node={};WP_tdstWayPoint point={};
            if(!cursor || !SafeReadMemory(cursor,&node,sizeof(node)) ||
               !node.m_hWayPoint || !SafeReadMemory(node.m_hWayPoint,&point,sizeof(point)) ||
               !R2R_MenuVecValid(point.m_stVertex)){
                why="source-graph-node-invalid";return false;
            }
            for(auto* used:oldNodePtrs)if(used==cursor){why="cyclic-graph-node-list";return false;}
            oldNodePtrs.push_back(cursor);oldNodes.push_back(node);oldGraphPoints.push_back(point);
            WP_tdstListOfArc arcList={};std::vector<WP_tdstArc> arcs;
            if(node.m_hListOfArc){
                if(!SafeReadMemory(node.m_hListOfArc,&arcList,sizeof(arcList)) ||
                   arcList.m_hArc.lNbOfElementsDyn<0 || arcList.m_hArc.lNbOfElementsDyn>12){
                    why="source-arc-list-invalid";return false;
                }
                auto* arc=arcList.m_hArc.hFirstElementDyn;
                for(long k=0;k<arcList.m_hArc.lNbOfElementsDyn;++k){
                    WP_tdstArc item={};
                    if(!arc || !SafeReadMemory(arc,&item,sizeof(item))){
                        why="source-arc-unreadable";return false;
                    }
                    arcs.push_back(item);arc=item.hNextBrotherDyn;
                }
                if(arc){why="extra-arc-list-elements";return false;}
            }
            oldArcLists.push_back(arcList);oldArcs.push_back(arcs);
            cursor=node.hNextBrotherDyn;
        }
        if(cursor || oldNodePtrs.back()!=sourceGraph.m_hListOfNode.hLastElementDyn){
            why="graph-list-inconsistent";return false;
        }
        for(auto& list:oldArcs)for(auto& arc:list){
            bool found=false;
            for(auto* p:oldNodePtrs)if(arc.m_hNode==p)found=true;
            if(!found){why="graph-arc-points-outside-graph";return false;}
        }
    }
    std::vector<void*> blocks;
    auto allocate=[&blocks](size_t bytes)->void*{
        void* p=AI_fn_p_vTrueAlloc(bytes);
        if(p){std::memset(p,0,bytes);blocks.push_back(p);}return p;
    };
    auto rollback=[&blocks](){
        for(auto it=blocks.rbegin();it!=blocks.rend();++it)AI_fn_vTrueFree(*it);
    };
    // Map ORIGINAL world WP pointer -> PRIVATE translated WP pointer.
    std::vector<uint32_t> originalWp;
    std::vector<WP_tdstWayPoint*> privateWp;
    auto makePoint=[&](uint32_t original,const WP_tdstWayPoint* cached)->bool{
        if(!original)return true;
        for(uint32_t x:originalWp)if(x==original)return true;
        if(originalWp.size()>=16u)return false;
        WP_tdstWayPoint value={};
        if(cached)value=*cached;
        else if(!SafeReadMemory(reinterpret_cast<const void*>(uintptr_t(original)),
                                &value,sizeof(value)))return false;
        if(!R2R_MenuVecValid(value.m_stVertex))return false;
        auto* copy=static_cast<WP_tdstWayPoint*>(allocate(sizeof(value)));
        if(!copy || reinterpret_cast<uintptr_t>(copy)>0xffffffffu)return false;
        *copy=value;copy->m_stVertex.x+=shift.x;
        copy->m_stVertex.y+=shift.y;copy->m_stVertex.z+=shift.z;
        if(!R2R_MenuVecValid(copy->m_stVertex))return false;
        originalWp.push_back(original);privateWp.push_back(copy);
        return true;
    };
    bool valid=true;
    for(size_t i=0;i<oldNodes.size() && valid;++i){
        const auto ptr=reinterpret_cast<uintptr_t>(oldNodes[i].m_hWayPoint);
        if(ptr>0xffffffffu || !ptr)valid=false;
        else valid=makePoint(static_cast<uint32_t>(ptr),&oldGraphPoints[i]);
    }
    for(unsigned j=0;j<fieldCount && valid;++j){
        if(cells[j].type==8u)valid=makePoint(cells[j].original,nullptr);
    }
    if(!valid){rollback();why="private-waypoint-copy-failed";return false;}
    WP_tdstGraph* newGraph=nullptr;
    if(graphIndex>=0 && cells[graphIndex].original){
        newGraph=static_cast<WP_tdstGraph*>(allocate(sizeof(WP_tdstGraph)));
        if(!newGraph || reinterpret_cast<uintptr_t>(newGraph)>0xffffffffu){
            rollback();why="private-graph-alloc-failed";return false;
        }
        *newGraph=sourceGraph;
        const char* name=g_R2RLearn10PositionSpecs[index].name;
        char* nameCopy=static_cast<char*>(allocate(std::strlen(name)+1));
        if(!nameCopy){rollback();why="private-graph-name-alloc-failed";return false;}
        std::memcpy(nameCopy,name,std::strlen(name)+1);newGraph->m_szNameOfGraph=nameCopy;
        const unsigned n=static_cast<unsigned>(oldNodes.size());
        std::vector<WP_tdstGraphNode*> nodes(n,nullptr);
        std::vector<WP_tdstListOfArc*> lists(n,nullptr);
        std::vector<std::vector<WP_tdstArc*>> arcs(n);
        valid=true;
        for(unsigned i=0;i<n && valid;++i){
            nodes[i]=static_cast<WP_tdstGraphNode*>(allocate(sizeof(WP_tdstGraphNode)));
            if(!nodes[i]){valid=false;break;}
            *nodes[i]=oldNodes[i];
            if(oldArcs[i].empty())continue;
            lists[i]=static_cast<WP_tdstListOfArc*>(allocate(sizeof(WP_tdstListOfArc)));
            if(!lists[i]){valid=false;break;}
            *lists[i]=oldArcLists[i];
            for(const auto& oldArc:oldArcs[i]){
                auto* arc=static_cast<WP_tdstArc*>(allocate(sizeof(WP_tdstArc)));
                if(!arc){valid=false;break;}
                *arc=oldArc;arcs[i].push_back(arc);
            }
        }
        if(valid){
            auto& anchor=newGraph->m_hListOfNode;
            anchor.hFirstElementDyn=nodes.front();anchor.hLastElementDyn=nodes.back();
            anchor.lNbOfElementsDyn=static_cast<long>(n);
            for(unsigned i=0;i<n;++i){
                auto* node=nodes[i];
                node->hPrevBrotherDyn=i?nodes[i-1]:nullptr;
                node->hNextBrotherDyn=i+1<n?nodes[i+1]:nullptr;
                node->hFatherDyn=&anchor;
                const auto original=static_cast<uint32_t>(reinterpret_cast<uintptr_t>(oldNodes[i].m_hWayPoint));
                for(size_t k=0;k<originalWp.size();++k){
                    if(originalWp[k]==original){node->m_hWayPoint=privateWp[k];break;}
                }
                node->m_hListOfArc=lists[i];
                if(!lists[i])continue;
                auto& arcAnchor=lists[i]->m_hArc;
                arcAnchor.hFirstElementDyn=arcs[i].front();
                arcAnchor.hLastElementDyn=arcs[i].back();
                arcAnchor.lNbOfElementsDyn=static_cast<long>(arcs[i].size());
                for(size_t j=0;j<arcs[i].size();++j){
                    auto* arc=arcs[i][j];
                    arc->hPrevBrotherDyn=j?arcs[i][j-1]:nullptr;
                    arc->hNextBrotherDyn=j+1<arcs[i].size()?arcs[i][j+1]:nullptr;
                    arc->hFatherDyn=&arcAnchor;
                    for(unsigned k=0;k<n;++k){
                        if(arc->m_hNode==oldNodePtrs[k]){arc->m_hNode=nodes[k];break;}
                    }
                }
            }
        }
        if(!valid){rollback();why="private-graph-topology-allocation-failed";return false;}
    }
    if(g_R2RLearn10RouteLifetimeAllocations+blocks.size()>640u){
        rollback();why="route-allocation-lifetime-budget-exceeded";return false;
    }
    uint32_t updated[16]={};
    for(unsigned j=0;j<fieldCount;++j){
        updated[j]=cells[j].original;
        if(cells[j].type==17u){
            if(cells[j].original && newGraph)
                updated[j]=static_cast<uint32_t>(reinterpret_cast<uintptr_t>(newGraph));
        }else if(cells[j].type==8u){
            for(size_t k=0;k<originalWp.size();++k){
                if(cells[j].original==originalWp[k]){
                    updated[j]=static_cast<uint32_t>(reinterpret_cast<uintptr_t>(privateWp[k]));break;
                }
            }
        }
    }
    // Commit only private DSG POINTER CELLS; never write native world nodes.
    for(unsigned j=0;j<fieldCount;++j){
        std::memcpy(cells[j].cell,&updated[j],sizeof(uint32_t));
    }
    bool verified=true;
    for(unsigned j=0;j<fieldCount;++j){
        uint32_t read=0;
        if(!SafeReadMemory(cells[j].cell,&read,sizeof(read)) || read!=updated[j])verified=false;
    }
    if(!verified){
        for(unsigned j=0;j<fieldCount;++j)
            std::memcpy(cells[j].cell,&cells[j].original,sizeof(uint32_t));
        // A native tick could have seen our temporary pointer; retain blocks.
        g_R2RLearn10RouteLifetimeAllocations+=static_cast<unsigned>(blocks.size());
        why="private-dsg-bind-verify-failed";return false;
    }
    state.installed=true;state.hasPath=true;state.lastActive=true;
    state.count=fieldCount;state.delta=shift;
    state.graphWaypointCount=static_cast<unsigned>(originalWp.size());
    for(unsigned j=0;j<state.graphWaypointCount;++j){
        state.graphOriginalWaypoints[j]=originalWp[j];
        state.graphPrivateWaypoints[j]=static_cast<uint32_t>(reinterpret_cast<uintptr_t>(privateWp[j]));
    }
    for(unsigned j=0;j<fieldCount;++j){state.fields[j]=cells[j];state.updated[j]=updated[j];}
    g_R2RLearn10RouteLifetimeAllocations+=static_cast<unsigned>(blocks.size());
    char line[360]={};
    snprintf(line,sizeof(line),
        "[LEARN10-ROUTE-BIND] frame=%u actor=%s graph=%u graphNodes=%u waypointFields=%u privateWp=%u shift=%.2f,%.2f,%.2f allocations=%u worldUntouched=1",
        frame,g_R2RLearn10PositionSpecs[index].name,newGraph?1u:0u,
        static_cast<unsigned>(oldNodes.size()),fieldCount-(graphIndex>=0?1u:0u),
        static_cast<unsigned>(privateWp.size()),shift.x,shift.y,shift.z,
        static_cast<unsigned>(blocks.size()));
    R2R_Learn10RouteLog(line);
    why="private-route-bound";return true;
}
static void R2R_Learn10RouteRefresh(const R2R_MenuEnemyActor& actor,int index,
                                     unsigned frame,const MTH3D_tdstVector& target){
    auto& state=g_R2RLearn10Routes[index];
    if(!state.installed || !state.hasPath)return;
    const bool active=actor.object!=nullptr;
    const bool reactivated=active && !state.lastActive;
    state.lastActive=active;
    if(!active)return;
    R2R_Learn10RouteField observed[16]={};unsigned count=0;
    const char* why="";
    if(!R2R_Learn10RouteFields(actor,observed,count,why) || count!=state.count){
        if(!state.failureLogged){
            char line[260]={};snprintf(line,sizeof(line),
                "[LEARN10-ROUTE-SKIP] frame=%u actor=%s reason=%s",
                frame,g_R2RLearn10PositionSpecs[index].name,why);
            R2R_Learn10RouteLog(line);state.failureLogged=true;
        }
        return;
    }
    unsigned rewires=0,foreign=0,dynamicWaypoints=0;
    for(unsigned j=0;j<count;++j){
        if(observed[j].id!=state.fields[j].id ||
           observed[j].type!=state.fields[j].type){++foreign;continue;}
        const uint32_t current=observed[j].original;
        if(current==state.updated[j])continue;
        // The butterfly's SCRIPT can assign a NEW waypoint while moving.
        // Treat any already-private point as valid, and map only known
        // ORIGINAL graph points to the matching private copies.
        if(observed[j].type==8u){
            bool knownPrivate=false;
            for(unsigned k=0;k<state.graphWaypointCount;++k){
                if(current==state.graphPrivateWaypoints[k]){knownPrivate=true;break;}
            }
            if(knownPrivate)continue;
            bool mapped=false;
            for(unsigned k=0;k<state.graphWaypointCount;++k){
                if(current!=state.graphOriginalWaypoints[k])continue;
                if(state.dynamicRebinds>=128u){mapped=true;++foreign;break;}
                const uint32_t translated=state.graphPrivateWaypoints[k];
                if(!R2R_Learn10ExtraWritable(observed[j].cell,sizeof(translated))){
                    mapped=true;++foreign;break;
                }
                std::memcpy(observed[j].cell,&translated,sizeof(translated));
                ++rewires;++dynamicWaypoints;++state.dynamicRebinds;mapped=true;break;
            }
            if(mapped)continue;
        }
        if(current==state.fields[j].original && state.recoveries<16u &&
           R2R_Learn10ExtraWritable(observed[j].cell,sizeof(uint32_t))){
            std::memcpy(observed[j].cell,&state.updated[j],sizeof(uint32_t));
            ++rewires;
        }else ++foreign;
    }
    if(rewires){
        ++state.recoveries;
        char line[340]={};snprintf(line,sizeof(line),
            "[LEARN10-ROUTE-RECOVER] frame=%u actor=%s reactivated=%d rewired=%u dynamicWP=%u dynamicTotal=%u/128 foreign=%u attempts=%u/16",
            frame,g_R2RLearn10PositionSpecs[index].name,reactivated?1:0,
            rewires,dynamicWaypoints,state.dynamicRebinds,foreign,state.recoveries);
        R2R_Learn10RouteLog(line);
        // Streaming may reset BOTH the actor matrix and its DSG fields.
        // Only reposition if it is back at its native home on reactivation.
        if(reactivated){
            const auto home=R2R_Learn10RaymapToEngine(g_R2RLearn10PositionSpecs[index].home);
            if(R2R_Learn10RouteDist(actor.native,home)<3.f){
                MTH3D_tdstVector local={};R2R_MenuPhysics phy={};
                if(R2R_MenuLocalTarget(actor,target,local) &&
                   R2R_MenuPreparePhysics(actor,phy,g_R2RLearn10PositionSpecs[index].name)){
                    const MTH3D_tdstVector delta={target.x-actor.native.x,target.y-actor.native.y,target.z-actor.native.z};
                    R2R_MenuPhysicsCommit(phy,delta);R2R_MenuCommit(actor,target,local);
                    R2R_Learn10RouteLog("[LEARN10-ROUTE-REENTRY] sector-reset restored target slot once");
                }
            }
        }
    }
    if(foreign && !state.failureLogged){
        char line[240]={};snprintf(line,sizeof(line),
            "[LEARN10-ROUTE-FOREIGN] frame=%u actor=%s foreignFields=%u; no overwrite",
            frame,g_R2RLearn10PositionSpecs[index].name,foreign);
        R2R_Learn10RouteLog(line);state.failureLogged=true;
    }
    if(frame%600u==0u){
        char line[240]={};snprintf(line,sizeof(line),
            "[LEARN10-ROUTE-CHECK] frame=%u actor=%s pos=%.2f,%.2f,%.2f recovered=%u",
            frame,g_R2RLearn10PositionSpecs[index].name,
            actor.native.x,actor.native.y,actor.native.z,state.recoveries);
        R2R_Learn10RouteLog(line);
    }
}

// TEST59: Learn_10 Kipik script STN_kipik_init sets its own DSG Vector_2
// to Position(); the normal AI uses it as its home/orientation reference.
// It has NO Graph or WayPoint fields, so only modify the LIVE per-instance
// Vector_2 when we can prove it matches the original home (not a chase target).
struct R2R_Learn10KipikState {
    unsigned repairs;
    bool initiallyLogged;
    bool failureLogged;
};
static R2R_Learn10KipikState g_R2RLearn10KipikState[20]={};
static bool R2R_Learn10KipikCell(const R2R_MenuEnemyActor& a,
                                  MTH3D_tdstVector*& cell,const char*& reason){
    cell=nullptr;reason="unknown";
    if(!a.object || !a.actor || !a.actor->hBrain || !AI_fn_bGetDsgVar){
        reason="inactive-or-no-brain";return false;
    }
    AI_tdeDsgVarType type=AI_E_Nb_dvt;void* raw=nullptr;
    if(!AI_fn_bGetDsgVar(a.object,2u,&type,&raw) || type!=AI_E_dvt_Vector || !raw){
        reason="not-vector2";return false;
    }
    AI_tdstBrain brain={};AI_tdstMind mind={};AI_tdstDsgMem mem={};
    AI_tdstDsgVar* definitionPtr=nullptr;AI_tdstDsgVar definition={};
    AI_tdstDsgVarInfo info={};
    if(!SafeReadMemory(a.actor->hBrain,&brain,sizeof(brain)) || !brain.p_stMind ||
       !SafeReadMemory(brain.p_stMind,&mind,sizeof(mind)) || !mind.p_stDsgMem ||
       !SafeReadMemory(mind.p_stDsgMem,&mem,sizeof(mem)) || !mem.pp_stDsgVar ||
       !SafeReadMemory(mem.pp_stDsgVar,&definitionPtr,sizeof(definitionPtr)) ||
       !definitionPtr || !SafeReadMemory(definitionPtr,&definition,sizeof(definition)) ||
       definition.ucNbDsgVar!=3u || !definition.a_stDsgVarInfo ||
       definition.ulBufferSize<sizeof(MTH3D_tdstVector) || definition.ulBufferSize>512u ||
       !SafeReadMemory(definition.a_stDsgVarInfo+2,&info,sizeof(info))){
        reason="kipik-dsg-layout-invalid";return false;
    }
    const uintptr_t base=reinterpret_cast<uintptr_t>(mem.p_cDsgMemBuffer);
    if(!base || mem.p_cDsgMemBuffer==mem.p_cDsgMemBufferInit ||
       mem.p_cDsgMemBuffer==definition.p_cDsgMemDefaultInit ||
       static_cast<unsigned>(info.eTypeId)!=11u ||
       info.ulOffsetInDsgMem>definition.ulBufferSize-sizeof(MTH3D_tdstVector) ||
       reinterpret_cast<uintptr_t>(raw)!=base+info.ulOffsetInDsgMem ||
       !R2R_Learn10ExtraWritable(raw,sizeof(MTH3D_tdstVector))){
        reason="vector2-not-private-writable";return false;
    }
    cell=static_cast<MTH3D_tdstVector*>(raw);
    reason="private-vector2";return true;
}
static void R2R_Learn10KipikHomeRefresh(const R2R_MenuEnemyActor& actor,
                                         int index,const MTH3D_tdstVector& target,
                                         unsigned frame){
    if(index<16 || index>19 || !actor.object)return;
    auto& state=g_R2RLearn10KipikState[index];
    MTH3D_tdstVector* cell=nullptr;const char* why="unknown";
    if(!R2R_Learn10KipikCell(actor,cell,why)){
        if(!state.failureLogged){
            char line[250]={};snprintf(line,sizeof(line),
                "[LEARN10-KIPIK-HOME-SKIP] frame=%u actor=%s reason=%s",
                frame,g_R2RLearn10PositionSpecs[index].name,why);
            R2R_Learn10RouteLog(line);state.failureLogged=true;
        }
        return;
    }
    MTH3D_tdstVector stored={};
    if(!SafeReadMemory(cell,&stored,sizeof(stored)) || !R2R_MenuVecValid(stored))return;
    const auto nativeHome=R2R_Learn10RaymapToEngine(g_R2RLearn10PositionSpecs[index].home);
    const float nativeDistance=R2R_Learn10RouteDist(stored,nativeHome);
    const float targetDistance=R2R_Learn10RouteDist(stored,target);
    const float zeroDistance=R2R_Learn10RouteDist(stored,{0.f,0.f,0.f});
    if(!state.initiallyLogged){
        char line[330]={};snprintf(line,sizeof(line),
            "[LEARN10-KIPIK-HOME-AUDIT] frame=%u actor=%s stored=%.2f,%.2f,%.2f nativeError=%.2f targetError=%.2f zeroError=%.2f",
            frame,g_R2RLearn10PositionSpecs[index].name,stored.x,stored.y,stored.z,
            nativeDistance,targetDistance,zeroDistance);
        R2R_Learn10RouteLog(line);state.initiallyLogged=true;
    }
    // A zero vector is still UNINITIALIZED: let the game's init script set
    // the new home, instead of guessing its internal state.
    if(zeroDistance<0.5f || targetDistance<2.5f ||
       nativeDistance>=2.5f || targetDistance<=5.f || state.repairs>=16u)return;
    std::memcpy(cell,&target,sizeof(target));
    MTH3D_tdstVector verified={};
    if(SafeReadMemory(cell,&verified,sizeof(verified)) &&
       R2R_Learn10RouteDist(verified,target)<0.01f){
        ++state.repairs;
        char line[260]={};snprintf(line,sizeof(line),
            "[LEARN10-KIPIK-HOME-REPAIR] frame=%u actor=%s nativeHomeCorrected=1 repairs=%u/16",
            frame,g_R2RLearn10PositionSpecs[index].name,state.repairs);
        R2R_Learn10RouteLog(line);
    }
}
static HIE_tdstSuperObject* g_R2RLearn10PositionRoot=nullptr;
static unsigned g_R2RLearn10PositionFrames=0;
static bool g_R2RLearn10PositionDone[20]={};
static bool g_R2RLearn10PositionMoved[20]={};
static int g_R2RLearn10PositionDonor[20]={};
static unsigned g_R2RLearn10PositionMoveFrame[20]={};
static unsigned g_R2RLearn10PositionStatusMilestones[20]={};
static unsigned g_R2RLearn10PositionMoves=0;
static bool g_R2RLearn10PositionWasActive[20]={};
static unsigned g_R2RLearn10PositionReentries[20]={};
static void R2R_Learn10PositionReset(HIE_tdstSuperObject* next){
    g_R2RLearn10PositionRoot=next;
    g_R2RLearn10PositionFrames=0;
    g_R2RLearn10PositionMoves=0;
    std::memset(g_R2RLearn10Routes,0,sizeof(g_R2RLearn10Routes));
    std::memset(g_R2RLearn10KipikState,0,sizeof(g_R2RLearn10KipikState));
    std::memset(g_R2RLearn10PositionWasActive,0,sizeof(g_R2RLearn10PositionWasActive));
    std::memset(g_R2RLearn10PositionReentries,0,sizeof(g_R2RLearn10PositionReentries));
    std::memset(g_R2RLearn10PositionDone,0,sizeof(g_R2RLearn10PositionDone));
    std::memset(g_R2RLearn10PositionMoved,0,sizeof(g_R2RLearn10PositionMoved));
    std::memset(g_R2RLearn10PositionMoveFrame,0,sizeof(g_R2RLearn10PositionMoveFrame));
    std::memset(g_R2RLearn10PositionStatusMilestones,0,sizeof(g_R2RLearn10PositionStatusMilestones));
    for(int i=0;i<20;++i)g_R2RLearn10PositionDonor[i]=-1;
    // Local clusters are from the exact Raymap export, not cross-level
    // distances: A=(start champignons, butterfly), B=(mid mushroom,
    // first mosquito), C=(butterfly, mosquito), D=(late mushroom, mosquitos).
    // Only shuffle within each small physical neighborhood; this avoids
    // moving a currently active actor to an inactive streaming sector.
    static const int localGroups[4][3]={{1,2,5},{3,16,-1},{6,17,-1},{4,18,19}};
    static const int localSizes[4]={3,2,2,3};
    int count=0;
    for(int group=0;group<4;++group){
        const int length=localSizes[group];
        const unsigned roll=R2R_RollU32(
            "Enemies.Learn10.Positions.Local46","Learn_10",0x46000u+unsigned(group));
        const int shift=(length==3 && (roll&1u)) ? 2 : 1;
        for(int k=0;k<length;++k){
            const int actor=localGroups[group][k];
            const int donor=localGroups[group][(k+shift)%length];
            g_R2RLearn10PositionDonor[actor]=donor;
            ++count;
        }
    }
    // Never silently add an unpaired target.
    for(int i=0;i<20;++i){
        if(g_R2RLearn10PositionSpecs[i].movable &&
           g_R2RLearn10PositionDonor[i]<0)
            return;
    }
    if(!next)return;
    char routeHead[235]={};
    snprintf(routeHead,sizeof(routeHead),"RAYMAN 2 RANDOMIZER %s - LEARN_10 PRIVATE ROUTES",VERSION);
    R2R_Learn10RouteLog(routeHead,true);
    R2R_Learn10RouteLog("[ROUTE-POLICY] TRUE slot cycles; private graph / dynamically selected original WP mapping; Kipik own Vector_2 home; guarded re-entry; NO shared world edits.");
    char line[370]={};
    snprintf(line,sizeof(line),"[LEARN10-LOAD] seed=%u selected=20 movable=%d protected=%d mode=TEST59-PERSISTENT-SLOT-PERMUTATIONS-ANCHORS",
        g_R2RConfig.seed,count,20-count);
    R2R_WorldRemixLog(line);
    R2R_WorldRemixLog("[LEARN10-POLICY] true donor SLOT cycles; private instance DSG route-pointer reassignment after cloned graph/WP validation; NO shared world modifications, Jail_20 disabled");
    R2R_WorldRemixLog("[LEARN10-AXES] Raymap export XYZ -> engine stPos XZY; both home and target converted");
    R2R_WorldRemixLog("[LEARN10-LOCAL] four 3D SLOT cycles (3+2+2+3). Each actor takes exact DONOR original XYZ; private Graph/Waypoint paths translated with the actor, guarded reactivation recovery");
    for(int i=0;i<20;++i){
        const auto& s=g_R2RLearn10PositionSpecs[i];
        if(!s.movable){
            snprintf(line,sizeof(line),"[LEARN10-PROTECTED] name=%s reason=scripted-tutorial-or-cutscene",s.name);
        }else{
            const auto& donor=g_R2RLearn10PositionSpecs[g_R2RLearn10PositionDonor[i]];
            const MTH3D_tdstVector target=R2R_Learn10RaymapToEngine(donor.home);
            const MTH3D_tdstVector home=R2R_Learn10RaymapToEngine(s.home);
            const float dx=target.x-home.x,dy=target.y-home.y,dz=target.z-home.z;
            const float planned=std::sqrt(dx*dx+dy*dy+dz*dz);
            snprintf(line,sizeof(line),"[LEARN10-PLAN] actor=%s donor=%s targetEngine=%.2f,%.2f,%.2f distance=%.2f",
                s.name,donor.name,target.x,target.y,target.z,planned);
        }
        R2R_WorldRemixLog(line);
    }
}
struct R2R_Learn10PositionScan {
    R2R_MenuEnemyActor actors[20];
    bool inactive[20];
    bool mismatched[20];
};
static void R2R_Learn10PositionWalk(HIE_tdstSuperObject* o,unsigned depth,bool active,R2R_Learn10PositionScan& scan){
    if(!o || depth>64 || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(o),sizeof(*o)))return;
    if(o->ulType==HIE_C_Type_Actor && o!=HIE_M_hGetMainActor()){
        const char* name=HIE_fn_szGetObjectPersonalName(o);
        if(name){
            for(int i=0;i<20;++i){
                const auto& s=g_R2RLearn10PositionSpecs[i];
                if(_stricmp(s.name,name))continue;
                if(!active){scan.inactive[i]=true;break;}
                if(scan.actors[i].object)break;
                const char* family=HIE_fn_szGetObjectFamilyName(o);
                const char* model=HIE_fn_szGetObjectModelName(o);
                if(!family || !model || _stricmp(s.family,family) || _stricmp(s.model,model)){
                    scan.mismatched[i]=true;break;
                }
                HIE_tdstEngineObject* a=HIE_M_hSuperObjectGetActor(o);
                if(!a || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(a),sizeof(*a)) ||
                   !a->h3dData || !a->hBrain || !o->hFatherDyn ||
                   !R2R_AddressReadable(reinterpret_cast<uintptr_t>(o->hFatherDyn),sizeof(HIE_tdstSuperObject)))break;
                POS_tdstCompletePosition* g=o->p_stGlobalMatrix;
                POS_tdstCompletePosition* l=o->p_stLocalMatrix;
                if(!g || !l || !R2R_AddressReadable(reinterpret_cast<uintptr_t>(g),sizeof(*g)) ||
                   !R2R_AddressReadable(reinterpret_cast<uintptr_t>(l),sizeof(*l)) ||
                   !R2R_MenuVecValid(g->stPos) || !R2R_MenuVecValid(l->stPos))break;
                auto& out=scan.actors[i];
                out.object=o;out.actor=a;out.parent=o->hFatherDyn;
                out.global=g;out.local=l;out.native=g->stPos;
                break;
            }
        }
    }
    HIE_tdstSuperObject* child=nullptr;
    LST_M_DynamicForEach(o,child){if(child)R2R_Learn10PositionWalk(child,depth+1,active,scan);}
}
static void R2R_Learn10PositionTick(HIE_tdstSuperObject* world){
    if(!world)return;
    if(world!=g_R2RLearn10PositionRoot)R2R_Learn10PositionReset(world);
    const unsigned frame=++g_R2RLearn10PositionFrames;
    if(frame!=1u && frame%10u!=0u)return;
    R2R_Learn10PositionScan scan={};
    R2R_Learn10PositionWalk(world,0,true,scan);
    if(GAM_g_p_stInactiveDynamicWorld && *GAM_g_p_stInactiveDynamicWorld &&
       *GAM_g_p_stInactiveDynamicWorld!=world)
        R2R_Learn10PositionWalk(*GAM_g_p_stInactiveDynamicWorld,0,false,scan);
    int active=0,inactive=0,pending=0,protectedActive=0;
    char line[420]={};
    for(int i=0;i<20;++i){
        const auto& spec=g_R2RLearn10PositionSpecs[i];
        auto& actor=scan.actors[i];
        if(actor.object)++active;
        else if(scan.inactive[i])++inactive;
        if(!spec.movable){if(actor.object)++protectedActive;continue;}
        if(g_R2RLearn10PositionMoved[i]){
            const auto donorPos=R2R_Learn10RaymapToEngine(
                g_R2RLearn10PositionSpecs[g_R2RLearn10PositionDonor[i]].home);
            const bool nowActive=actor.object!=nullptr;
            const bool reactivated=nowActive && !g_R2RLearn10PositionWasActive[i];
            g_R2RLearn10PositionWasActive[i]=nowActive;
            // On sector reload the engine may recreate the actor at its
            // ORIGINAL slot, even if its route pointer is already private.
            // Re-swap only on actual inactive -> active transition, not while
            // the actor is walking or chasing Rayman.
            if(reactivated && g_R2RLearn10PositionReentries[i]<16u){
                const auto nativeHome=R2R_Learn10RaymapToEngine(spec.home);
                if(R2R_Learn10RouteDist(actor.native,nativeHome)<2.5f &&
                   R2R_Learn10RouteDist(actor.native,donorPos)>5.f){
                    MTH3D_tdstVector local={};R2R_MenuPhysics phy={};
                    if(R2R_MenuLocalTarget(actor,donorPos,local) &&
                       R2R_MenuPreparePhysics(actor,phy,spec.name)){
                        const MTH3D_tdstVector delta={donorPos.x-actor.native.x,
                            donorPos.y-actor.native.y,donorPos.z-actor.native.z};
                        R2R_MenuPhysicsCommit(phy,delta);
                        R2R_MenuCommit(actor,donorPos,local);
                        actor.native=donorPos; // update this scan's snapshot, avoid duplicate re-entry
                        ++g_R2RLearn10PositionReentries[i];
                        snprintf(line,sizeof(line),
                            "[LEARN10-SLOT-REENTRY] frame=%u actor=%s originalSlotReset=1 restoredDonor=%s attempts=%u/16",
                            frame,spec.name,g_R2RLearn10PositionSpecs[g_R2RLearn10PositionDonor[i]].name,
                            g_R2RLearn10PositionReentries[i]);
                        R2R_WorldRemixLog(line);R2R_Learn10RouteLog(line);
                    }
                }
            }
            R2R_Learn10RouteRefresh(actor,i,frame,donorPos);
            R2R_Learn10KipikHomeRefresh(actor,i,donorPos,frame);
        }
        if(g_R2RLearn10PositionDone[i])continue;
        if(!actor.object){++pending;continue;}
        const auto& donor=g_R2RLearn10PositionSpecs[g_R2RLearn10PositionDonor[i]];
        const MTH3D_tdstVector to=R2R_Learn10RaymapToEngine(donor.home);
        const MTH3D_tdstVector home=R2R_Learn10RaymapToEngine(spec.home);
        const float dx=actor.native.x-home.x,dy=actor.native.y-home.y,dz=actor.native.z-home.z;
        const float fromHome=std::sqrt(dx*dx+dy*dy+dz*dz);
        const float tx=to.x-actor.native.x,ty=to.y-actor.native.y,tz=to.z-actor.native.z;
        const float distance=std::sqrt(tx*tx+ty*ty+tz*tz);
        snprintf(line,sizeof(line),"[LEARN10-AXIS-CHECK] frame=%u actor=%s currentEngine=%.2f,%.2f,%.2f expectedEngine=%.2f,%.2f,%.2f originalError=%.3f",
            frame,spec.name,actor.native.x,actor.native.y,actor.native.z,home.x,home.y,home.z,fromHome);
        R2R_WorldRemixLog(line);
        MTH3D_tdstVector local={};R2R_MenuPhysics physics={};
        const char* reject=nullptr;
        // Skip actors the script already moved: never pull them away mid-event.
        if(!std::isfinite(fromHome) || fromHome>12.0f)reject="already-moved-by-native-ai";
        else if(!std::isfinite(distance) || distance<0.05f || distance>42.0f)reject="distance-over-local-42-limit";
        else if(!R2R_MenuLocalTarget(actor,to,local))reject="unsafe-parent-local-matrix";
        else if(!R2R_MenuPreparePhysics(actor,physics,spec.name))reject="unsafe-physics";
        if(reject){
            g_R2RLearn10PositionDone[i]=true;
            snprintf(line,sizeof(line),"[LEARN10-SKIP] actor=%s reason=%s current=%.2f,%.2f,%.2f originalError=%.2f",
                spec.name,reject,actor.native.x,actor.native.y,actor.native.z,fromHome);
            R2R_WorldRemixLog(line);continue;
        }
        // IMPORTANT: a successful route assignment must happen BEFORE the
        // position exchange. An unknown graph/WP layout is NOT guessed.
        const char* routeReason="unknown";
        if(!R2R_Learn10RouteInstall(actor,i,to,frame,routeReason)){
            g_R2RLearn10PositionDone[i]=true;
            snprintf(line,sizeof(line),
                "[LEARN10-ROUTE-BLOCK] frame=%u actor=%s donor=%s reason=%s; original-slot-retained",
                frame,spec.name,donor.name,routeReason);
            R2R_WorldRemixLog(line);R2R_Learn10RouteLog(line);
            continue;
        }
        const MTH3D_tdstVector delta={tx,ty,tz};
        R2R_MenuPhysicsCommit(physics,delta);
        R2R_MenuCommit(actor,to,local);
        g_R2RLearn10PositionWasActive[i]=true;
        R2R_Learn10KipikHomeRefresh(actor,i,to,frame);
        g_R2RLearn10PositionDone[i]=true;
        g_R2RLearn10PositionMoved[i]=true;
        g_R2RLearn10PositionMoveFrame[i]=frame;
        ++g_R2RLearn10PositionMoves;
        snprintf(line,sizeof(line),"[LEARN10-MIX] actor=%s donor=%s from=%.2f,%.2f,%.2f to=%.2f,%.2f,%.2f distance=%.2f dynamics=%d",
            spec.name,donor.name,actor.native.x,actor.native.y,actor.native.z,to.x,to.y,to.z,distance,physics.hasDynamics?1:0);
        R2R_WorldRemixLog(line);
    }
    // Test45 could not tell which actors were deactivated after a teleport:
    // it only logged verification for actors STILL in the active world, and
    // frame-1 changes missed the exact +10-frame sampling interval.
    static const unsigned checkpoints[5]={10u,30u,90u,300u,600u};
    for(int i=0;i<20;++i){
        if(!g_R2RLearn10PositionMoved[i])continue;
        const unsigned since=frame-g_R2RLearn10PositionMoveFrame[i];
        for(unsigned slot=0;slot<5u;++slot){
            if(since<checkpoints[slot] ||
               (g_R2RLearn10PositionStatusMilestones[i]&(1u<<slot)))continue;
            g_R2RLearn10PositionStatusMilestones[i]|=(1u<<slot);
            const bool isActive=scan.actors[i].object!=nullptr;
            const char* state=isActive ? "ACTIVE" :
                (scan.inactive[i] ? "INACTIVE" : "NOT-IN-SCANNED-WORLDS");
            if(isActive){
                const auto& p=scan.actors[i].native;
                snprintf(line,sizeof(line),
                    "[LEARN10-STATUS] actor=%s afterFrames=%u state=%s pos=%.2f,%.2f,%.2f",
                    g_R2RLearn10PositionSpecs[i].name,since,state,p.x,p.y,p.z);
            }else{
                snprintf(line,sizeof(line),
                    "[LEARN10-STATUS] actor=%s afterFrames=%u state=%s",
                    g_R2RLearn10PositionSpecs[i].name,since,state);
            }
            R2R_WorldRemixLog(line);
        }
    }
    if(frame==1u || frame==10u || frame==30u || frame==90u || frame%300u==0u){
        int movedActive=0,movedInactive=0;
        for(int i=0;i<20;++i){
            if(!g_R2RLearn10PositionMoved[i])continue;
            if(scan.actors[i].object)++movedActive;
            else if(scan.inactive[i])++movedInactive;
        }
        snprintf(line,sizeof(line),"[LEARN10-HEARTBEAT] frame=%u activeSelected=%d inactiveSelected=%d protectedActive=%d moved=%u/10 movedActive=%d movedInactive=%d pending=%d",
            frame,active,inactive,protectedActive,g_R2RLearn10PositionMoves,movedActive,movedInactive,pending);
        R2R_WorldRemixLog(line);
    }
}


// ===========================================================================
// TEST 57 — Learn_30 actors + translated PRIVATE navigation graphs.
// Based on Test54: actor mixing and fish anchor recovery unchanged.
// TEST 54 — Learn_30 seven actors + fish anchor recovery after sector reload.
// Six placements use short/local exchanges or partial cross-family movement.
// Baby Globoxes swap; butterfly/fish cross-place while retaining own altitude;
// mushroom/piranha approach each other's slots by ~one quarter of distance,
// avoiding the >42-unit full swap that instantly deactivated the mushroom.
// Francesco receives a small seeded translation instead of being sent to a
// different streaming sector (where baby #2 disappeared in Test51).
// Fish: keep its instance-local Vector_2 HOME aligned with its new position.
// Test53 proved the field can be updated but the game restores its native
// value after the fish becomes inactive then active again.  Test54 checks the
// field on activation and on subsequent scans; it refreshes ONLY when the
// actor's private current Vector_2 was reset to its original location.  The
// refreshed value is read back, no changes to engine/world/initial/model DSG,
// and there are no repeated position teleports.
// Jumping piranha route waypoints and butterfly graph remain untouched.
// Recovered fish HOME is scoped to the live instance and bounded to 16 writes.
// All seven have a nonzero intended displacement; pending inactive actors wait
// until safely activated, and native AI may subsequently restore routes.
// Max health and testing powers from Test50 are preserved unchanged.
// ===========================================================================
