static void R2R_Learn30PositionReset(HIE_tdstSuperObject* next){
    g_R2RLearn30PositionRoot=next;
    g_R2RLearn30PositionFrames=0;
    g_R2RLearn30PositionMoves=0;
    g_R2RLearn30PreplaceAttempted=false;
    g_R2RLearn30PreplaceSucceeded=false;
    g_R2RLearn30PreplaceFirstActivationLogged=false;
    std::memset(g_R2RLearn30PositionDone,0,sizeof(g_R2RLearn30PositionDone));
    std::memset(g_R2RLearn30PositionMoved,0,sizeof(g_R2RLearn30PositionMoved));
    std::memset(g_R2RLearn30PositionWasActive,0,sizeof(g_R2RLearn30PositionWasActive));
    std::memset(g_R2RLearn30PositionReentryAttempts,0,sizeof(g_R2RLearn30PositionReentryAttempts));
    std::memset(g_R2RLearn30PositionMoveFrame,0,sizeof(g_R2RLearn30PositionMoveFrame));
    std::memset(g_R2RLearn30PositionStatusBits,0,sizeof(g_R2RLearn30PositionStatusBits));
    std::memset(g_R2RLearn30PositionWatchLogged,0,sizeof(g_R2RLearn30PositionWatchLogged));
    std::memset(g_R2RLearn30PositionReturnReported,0,sizeof(g_R2RLearn30PositionReturnReported));
    g_R2RLearn30FishHomeCommitted=false;
    g_R2RLearn30FishHomeCheckLogged=false;
    g_R2RLearn30FishWasActive=false;
    g_R2RLearn30FishHomeRefreshes=0;
    g_R2RLearn30FishHomeRefreshCappedLogged=false;
    std::memset(g_R2RLearn30RouteWasActive,0,sizeof(g_R2RLearn30RouteWasActive));
    std::memset(g_R2RLearn30RouteActivations,0,sizeof(g_R2RLearn30RouteActivations));
    // Do NOT free old private native waypoint copies on level unload: the
    // engine may still hold them during late inactive-sector cleanup.
    g_R2RLearn30PiranhaRoute={};
    // Do not free engine-visible graph blocks on level unload: the engine may
    // still run inactive-sector teardown after this event.
    std::memset(g_R2RLearn30PrivateGraph,0,sizeof(g_R2RLearn30PrivateGraph));

    // TEST60: STRICT EXACT 3D DONOR SLOT PAIRS. Absolutely no fractional
    // movements, local offsets, or personal-altitude locking: all 3 axes
    // are copied from the other actor's ORIGINAL Raymap position.
    // We intentionally pilot only validated land/local and cross-sector
    // pairs. The butterfly, Francesco and aquatic fish are UNCHANGED until
    // compatible true swap partners are identified: they never receive
    // invented approximate positions.
    static const int donors[7]={1,0,2,3,6,5,4};
    for(int i=0;i<7;++i){
        g_R2RLearn30PositionDonor[i]=donors[i];
        g_R2RLearn30PositionDest[i]=R2R_Learn30PositionEngine(
            g_R2RLearn30PositionSpecs[donors[i]].home);
    }
    if(!next)return;
    char line[420]={};
    snprintf(line,sizeof(line),"RAYMAN 2 RANDOMIZER %s - LEARN_30 POSITION DIAGNOSTIC",VERSION);
    R2R_Learn30PositionLog(line,true);
    snprintf(line,sizeof(line),"[LEARN30-LOAD] seed=%u selected=7 movable=4 protected=3 enabled=%d remixFlag=%d mode=TEST66-PIRANHA-NATIVE-WAYPOINT-CONTROL",
        g_R2RConfig.seed,g_R2RConfig.enabled?1:0,g_R2RConfig.enemiesWorldRemixTest?1:0);
    R2R_Learn30PositionLog(line);
    R2R_Learn30PositionLog("[LEARN30-POLICY] TRUE exact XYZ donor slots: baby pair + mushroom/piranha pair. TEST66 CONTROL: piranha retains ORIGINAL waypoints; no cloned waypoint allocations/bindings/refreshes; 3 protected actors unchanged.");
    R2R_Learn30PositionLog("[LEARN30-AXES] TRUE complete XYZ donor coordinates for four swapped actors; three other actors unchanged.");
    for(int i=0;i<7;++i){
        const auto& spec=g_R2RLearn30PositionSpecs[i];
        const auto original=R2R_Learn30PositionEngine(spec.home);
        const auto dst=g_R2RLearn30PositionDest[i];
        const float dx=dst.x-original.x,dy=dst.y-original.y,dz=dst.z-original.z;
        const float distance=std::sqrt(dx*dx+dy*dy+dz*dz);
        const char* scheme=!spec.movable?"PROTECTED-NO-COMPATIBLE-PARTNER":
            (i==0||i==1)?"EXACT-BABY-2-CYCLE":"EXACT-MUSHROOM-PIRANHA-2-CYCLE";
        snprintf(line,sizeof(line),
            "[LEARN30-PLAN] actor=%s donor=%s from=%.2f,%.2f,%.2f to=%.2f,%.2f,%.2f distance=%.2f exact3D=%d scheme=%s",
            spec.name,g_R2RLearn30PositionSpecs[g_R2RLearn30PositionDonor[i]].name,
            original.x,original.y,original.z,dst.x,dst.y,dst.z,distance,spec.movable?1:0,scheme);
        R2R_Learn30PositionLog(line);
    }
}
